('artist_awards', 299, 'award_name_en', 'c91c892e917a7107f14786f2634558ed659bc16e1a2066f1eef62f5b29780aaf', 'Sydney International Piano Competition, 1st prize'),
('artist_awards', 300, 'award_name_en', '2d85a69635bf4e8b994431f5d23e55374b63b38eda0c9ebffadf26809fb79ca4', 'Hamamatsu International Piano Competition, 1st prize'),
