('artist_awards', 302, 'award_name_en', '46602a504c74f3f0824d5ed0445d704da0411366601d5f0c3d536c52eb56a36d', 'Andorra (Spain) International Piano Competition, 1st prize'),
('artist_awards', 303, 'award_name_en', 'e627cd2da6680b4ecd3583f397502627f32e31021a6211cab006dae76c6723a1', 'Warsaw International Composers'' Competition, 1st prize'),
('artist_awards', 304, 'award_name_en', '8feae38f41979fd1148288c4863196435dbdb0e23b2305636116ebf688fb4d4a', 'Ludwig van Beethoven International Piano Competition, winner'),
('artist_awards', 305, 'award_name_en', '9751ccd1cb7a2c0de33886355e73ffe17189c7c551c8b064d7f4067f6e8a0c47', '9th International Chopin Piano Competition, winner'),
('artist_awards', 306, 'award_name_en', '1dc83190ce3d7e536b1e8cbb33d04ff80caf079812911a0bc7bf865f3e22d898', 'Léonie Sonning Music Prize'),
('artist_awards', 307, 'award_name_en', 'd1abb9180da137536ba39e311153686c02c9e21c3902d73453a7dca3499f7566', 'French Legion of Honour'),
('artist_awards', 308, 'award_name_en', '2ace9e13319f313e8c64c6ad0186266ff02f8961d045c4c9c77b6e88d53ef303', 'Poland''s Gold Medal for Merit to Culture – Gloria Artis'),
('artist_awards', 309, 'award_name_en', '9c3489d0173a256859ee0404f514e1283860f3b51e6be2a4bb4893457142daf1', 'Order of Polonia Restituta'),
('artist_awards', 310, 'award_name_en', '56d41d7a93815324b02eb21d318594f0532c9c510191fb35a70eb65da3133660', 'Praemium Imperiale'),
('artist_awards', 311, 'award_name_en', '307f1d5672fc5934077223aa75b41ee7af1527a326df23a8fef58074d6e42ab7', 'Gramophone Award'),
('artist_awards', 312, 'award_name_en', 'e4f477e67d7862cf76297f54ad85b74d9af5e01694d7c36acc3581311d459338', 'Anton Rubinstein International Competition'),
('artist_awards', 313, 'award_name_en', 'a8fe6e5defa3f3e6b24110639dbd7d867b8934973f62150177e37086e4bd59a8', 'Presidential Medal of Freedom'),
('artist_awards', 314, 'award_name_en', '5315bf033b4481d35af1265eced5459e628c2b935da5b341536cd71cf0ca2a76', 'Order of the British Empire, Second Class (KBE, honorary knighthood)'),
('artist_awards', 315, 'award_name_en', 'd1abb9180da137536ba39e311153686c02c9e21c3902d73453a7dca3499f7566', 'French Legion of Honour'),
('artist_awards', 316, 'award_name_en', 'c2869ac871523365951448b9f6abd391d69608b3c0fbb803e0cd9d6e42dc7274', 'Kennedy Center Honors'),
('artist_awards', 317, 'award_name_en', 'aeeb0d396fe40c692357b30ae98db67bd990c68e395ed3fe0c2b68f92d112d9d', 'Six or more Grammy Awards in total (complete Beethoven piano concertos, Brahms concertos, etc.)'),
('artist_awards', 318, 'award_name_en', 'fd0f6cde3daf882f3db79113f93aac558f8a941f4e9bec1421ed6f8e4e5502c7', '25 Grammy Awards in total (Horowitz in Moscow, etc.)'),
('artist_awards', 319, 'award_name_en', '64fd1bab9355a4c48aad1f224ddafeb377ff68332f16dea1b18e08967b7f7ec6', 'Grammy Lifetime Achievement Award'),
('artist_awards', 320, 'award_name_en', 'a8fe6e5defa3f3e6b24110639dbd7d867b8934973f62150177e37086e4bd59a8', 'Presidential Medal of Freedom'),
('artist_awards', 321, 'award_name_en', 'b4fb27b3708e287e5978d538e2bec2db030c2b9d6cf7cc246a41c830c0dc4b3a', 'National Medal of Arts'),
('artist_awards', 322, 'award_name_en', 'd1abb9180da137536ba39e311153686c02c9e21c3902d73453a7dca3499f7566', 'French Legion of Honour'),
('artist_awards', 323, 'award_name_en', '386c0961473efb534809cda75cd09196138763ae002f020691ed0465e377f027', 'Royal Philharmonic Society Gold Medal'),
('screen_music_cues', 150, 'part_label_en', 'd79403123286333b2a7648f318ad4210e014d3c7ea62649cee7342b66f9f0d3d', '3rd movement, Finale. Allegro'),
('screen_music_cues', 150, 'scene_note_en', '6cd90647890793d9d8104ef088074b1e759b32fe985854af6d637da0ba63b149', 'Plays over the loudspeakers in the contestants'' dormitory as the wake-up call every morning. It is used from the first wake-up scene in the middle of episode 1.'),
('screen_music_cues', 151, 'scene_note_en', '6b81231198ead19e56ca1405d33d5b95a4bafcd3f0097952d5b0886a313a7473', 'Plays over the loudspeakers as the contestants walk through the stairwell to the game arena and after the games end. It is also used in the VIP lounge scenes.'),
('screen_music_cues', 152, 'part_label_en', '6e674911004470fb10e6cf25f6ce56aa065f2daaa349437c82c9ad70e6ff0ee2', 'Act 2, Rodelinda''s aria ''Spietati, io vi giurai'''),
('screen_music_cues', 152, 'scene_note_en', '675f722a81a6e79c4d07db047061ed3ac9607fc56583d4d5bbbce904200e6585', 'Underscores the montage in which Ki-taek gets taken on as Mr. Park''s family driver and the family prepares to push out the housekeeper.'),
('screen_music_cues', 153, 'part_label_en', '26f6fdd71409bfa67a6ebe2de3deed18788511d9066e6bdd8bbf209dfcabae7b', 'Act 3, Rodelinda''s aria ''Mio caro bene'''),
('screen_music_cues', 153, 'scene_note_en', '1d3980e33c50961c5e90792d673f2a0c478595f325aa2a82720e5907dfaf01e3', 'At Da-song''s birthday party in the garden of Mr. Park''s house, an invited singer performs this aria.'),
('screen_music_cues', 154, 'part_label_en', '4eded67e1c1074f54726f18f9651ee8422c77e8b76c29ce6873e683c69994397', '4th movement, Adagietto. Sehr langsam'),
('screen_music_cues', 154, 'scene_note_en', 'fa096a2cf3f009740f6025adeff63aae363ccb4326c84568099b7625eddcfb15', 'Plays as Hae-jun climbs, in person, the rocky mountain that Seo-rae''s husband climbed on the day he died, retracing the case.'),
('screen_music_cues', 155, 'part_label_en', 'b4b8e9e6843627aa34d2b4f74770a46e8c7d881c27e6610eaed1f4ff714dba2a', '1st movement, Allegro non molto'),
('screen_music_cues', 155, 'scene_note_en', '1b9ed5038480562b1227f18b2b25def80fdbb1a90b23befd82d29c858f2789f1', 'Underscores the scene in which Oh Dae-su, having found the private prison that held him, tortures Mr. Park and presses him for answers.'),
('screen_music_cues', 156, 'part_label_en', '465f81a87b114964b06503387cf411c180bb4b4e4abd652c2590a9f77766fc16', 'Act 3, duet ''Sull''aria... Che soave zeffiretto'''),
('screen_music_cues', 156, 'scene_note_en', '5147df6571fa4985adb85c19f3699af643c689c1132f8282b1a359c8ba7e8071', 'Andy locks the warden''s office door and plays a record of this duet over the prison loudspeakers. The prisoners stop in their tracks to listen, and Andy is put in solitary confinement.'),
('screen_music_cues', 157, 'part_label_en', '8b16d5a2e75090ec6460223a1d4d96067f46db1b64132f551ce51c61f66f784a', 'Overture'),
('screen_music_cues', 157, 'scene_note_en', '0bb79ecdab9966d2bacfc957ef19d677a95ebb95ff8c6346d789e857a24ac055', 'In the first treatment session, Bertie listens to this piece loudly on headphones while reading Hamlet''s soliloquy. Logue records his voice.'),
('screen_music_cues', 158, 'part_label_en', 'f60463a35b30cf14c5d51d3183a8b6c4aac29e9dac5e4f24556ebdcec59061ec', '2nd movement, Allegretto'),
('screen_music_cues', 158, 'scene_note_en', '1bd4052746f9f12270ef2e001cfb524a6c9cc5170bb8f90f3b7c52927eab7847', 'Heard as George VI gives his radio address on the declaration of war in 1939. Only Logue stays beside him in the broadcast room to help with the speech.'),
('screen_music_cues', 159, 'part_label_en', 'd5da52723557f0563c3d4fcef81bee0769955cc184181d98af14471fd917a2e7', '2nd movement, Adagio un poco mosso'),
('screen_music_cues', 159, 'scene_note_en', '614d7f595c55ecdb5d35605d805dc8d1b41f8cd7eff0899442ae29e07efeca0c', 'Heard after the speech, in the final scene where the royal family steps out onto the palace balcony, and in the epilogue captions.'),
('screen_music_cues', 160, 'part_label_en', '08b224a73a55318cb64457820425f0796f4dc993af7c268a49a8964c9afa59b7', 'Introduction (Einleitung, ''Sunrise'')'),
('screen_music_cues', 160, 'scene_note_en', '863e4ed60b6fca0e68b4776f2d4ea9d847e9956de91eb75386d48b1dea3ebb7d', 'Heard in the opening titles as the Earth and the sun rise behind the moon. It returns in the scene where an ape first uses a bone as a tool.'),
('screen_music_cues', 161, 'part_label_en', 'fea97feac74661ad8f433761ba89c1712030ccf1d4db8c409458aae487e4fcdd', '2nd movement, Kyrie'),
('screen_music_cues', 161, 'scene_note_en', '93f5a808fb1ca13db653965ea1fdb902d8ab9b720d272a46d376fa6dcefa4396', 'Heard when the black monolith first appears before the group of apes. It returns when the monolith is found on the moon and again near Jupiter.'),
('screen_music_cues', 162, 'scene_note_en', 'f8c21b789efde886a681b47e6a70b0f16d1bb02d68dd460dda62d7b9977b8f58', 'Heard as the Pan Am space shuttle docks with the rotating space station. It returns in the moon-landing scene and over the end credits.'),
('screen_music_cues', 163, 'scene_note_en', 'd8cf16b8407dbc6b86ed634697b1f76d5bdb659ed74ba2c1d81461c602ded77a', 'Heard as the lunar shuttle carrying Dr. Floyd''s party flies over the moon''s surface to the excavation site.'),
('screen_music_cues', 164, 'part_label_en', 'e90a853abf7207072af298fb68ebc96e9fbcb3be8b4707b544865737c1330159', 'Adagio (Gayane Adagio)'),
('screen_music_cues', 164, 'scene_note_en', '7099b424a13195075dbd7a79cfef6593ec63049f5774b4903ee80c3ef3d65859', 'Heard in the scene introducing Bowman and Poole aboard Discovery One on its way to Jupiter.'),
('screen_music_cues', 165, 'scene_note_en', '86c2d110aa906ff4164f4c507a5b5549fe79c616fb5824f591c56c918acb58f4', 'Heard as Bowman enters the Star Gate near Jupiter. Parts of it are also used in the overture before the film begins and in the intermission.'),
('screen_music_cues', 166, 'part_label_en', 'c50d4a3553d5726a022cc11635d34fab02beb564fbf7dbd08e2336d9645a0633', '1st movement, Adagio sostenuto – Presto'),
('screen_music_cues', 166, 'scene_note_en', '82eb641c20bb9eec6abe199b184a6933500e1bd39623eab7951b9e5a9023531d', 'Kaori plays this movement on stage in the violin competition preliminaries. She ignores the score''s markings and plays it her own way.'),
('screen_music_cues', 167, 'scene_note_en', '29ea2e222107a244f71edaee7af9603b24679f25c3d56529beb5212b3e687686', 'In the second round of the competition, Kaori plays violin with Kousei accompanying on piano. When Kousei stops partway through, Kaori stops too, and then they start again together.'),
('screen_music_cues', 168, 'scene_note_en', '0eff51c7d5e917c7c2fd0c664e566e9172069f9524a083879b8aa2a6ea981b1a', 'Kousei plays this étude on stage at the piano competition. His playing falters partway through, but he picks it back up and continues to the end.'),
('screen_music_cues', 169, 'scene_note_en', '34add06b3831d77d29c62c860c2cea52280bf01b044f0eb306a493af793737ae', 'Kaori does not show up for the gala concert, so Kousei goes on stage alone. He plays this piece, which his mother loved, in the solo piano version.'),
('screen_music_cues', 170, 'scene_note_en', 'c9845a30d3b8d228314658a819830ce51a4f1ae212d392aa8f93a5889f2d1acd', 'Kousei plays this ballade in the finals of the piano competition. During the performance, Kaori, violin in hand, appears on stage.'),
('screen_music_cues', 171, 'part_label_en', '3bc34b1ede8d18b57d86172086116aada8e8e0644ea60f0d15a7512814606c08', 'No. 7, ''Träumerei'''),
('screen_music_cues', 171, 'scene_note_en', '943d461c5c59ab4f33134d76068e68dc56b8921b4b55192c8bfa568404176e2b', 'In episode 3, Jun-young plays "Träumerei" when Jeong-gyeong asks him to play any piece at all. The piece is tied to their childhood and returns up to episode 14.'),
('screen_music_cues', 172, 'scene_note_en', 'd769a7fdf948e8666bbeb4aed23d226f7c66dae581491eefedc536c13ebdc769', 'In the graduation recital in episode 16, Jun-young plays Schumann''s "Widmung" in Liszt''s piano transcription.'),
('screen_music_cues', 173, 'scene_note_en', 'b7fd096d1ef9cea459d58a7b32514c76b8a55159de9d572853a01e6f2ad8b5ca', 'In episode 2, Seon-jae and Hye-won sit side by side at one piano and play together for the first time. It is then used as the drama''s main theme.'),
('screen_music_cues', 174, 'part_label_en', '1d82a78e5ace22172af8dde737b6b8eb46db658a4a1be6d8f65436d91b4f8ca5', '3rd movement, Allegro ma non troppo – Presto'),
('screen_music_cues', 174, 'scene_note_en', '01ac69cf821097aca219f8f3f695bfd3781cdb684b35b990501abccb37eae0c2', 'In episode 2, Seon-jae plays the finale of the "Appassionata" with great force. The official clip is titled "Seon-jae playing on the bridge."'),
('screen_music_cues', 175, 'part_label_en', 'de65c2b688ddb6b8c9aa97eb8a0d6c99c08a826d05bb1b299d50cbedf6882145', 'Prelude'),
('screen_music_cues', 175, 'scene_note_en', '538a4c38f6ed1ac91cf0a46310cc25f678ece415c5ff2861a25a304512ad4327', 'In episode 2, when Hye-won tests Seon-jae''s ability, this is the first of the pieces he plays in succession.'),
('screen_music_cues', 176, 'part_label_en', '293501a9a3462507ef8d5006b5a0678161abecde6d0f329258205555a94c16ba', 'April, ''Snowdrop'''),
('screen_music_cues', 176, 'scene_note_en', '1747377a135a7b504d46527a4af307f860e4ac33d387d52a6121c4943a3d2ce2', 'In episode 2, Hye-won listens to Seon-jae play "April." In episode 5, Seon-jae plays this piece again in Hye-won''s practice room.'),
('screen_music_cues', 177, 'part_label_en', '42cac066e1ebf4e8361d799a6801e74096ce271f841b561f231d0b43b536fe78', '1st movement, Allegro'),
('screen_music_cues', 177, 'scene_note_en', 'b9343c58109b96ac27a5e2eb58b11932cece4b43ea44c443de73625a9a3e9d5e', 'In episode 5, Hye-won and Seon-jae sit at one piano again and play four hands together.'),
('screen_music_cues', 178, 'scene_note_en', '88eaa63566ec3503dfb50ae6e035170e78b11cbc713f6b7908ae38933fb7d33d', 'In episode 8, Hye-won and Seon-jae work on it in a lesson as they prepare for a concerto performance. In episode 10, Seon-jae performs it on stage with an orchestra.'),
('screen_music_cues', 179, 'part_label_en', '450ca08dd19e727708fe1d7a8143bc7207ebe6831e8cf5e41b4a113d66443529', '4th movement, Finale (''Ode to Joy'')'),
('screen_music_cues', 179, 'scene_note_en', 'bc937cae0da0fbb3e509ff94a7aead9f07df6362de3a3ce5c01bc32755d4d7e3', 'On the day of the performance in episode 10, Kang Mae conducts the "Choral" Symphony with the orchestra and chorus in a hall filled with flood victims.'),
('screen_music_cues', 180, 'scene_note_en', 'c6f5f6b56425351c940b3eddd958713e21cad0ab5327059e746d1a46c7807306', 'In episode 5, the Seokran City Orchestra plays this as the final piece of its first performance, under Kang Mae''s baton.'),
('screen_music_cues', 181, 'scene_note_en', '63335d35aba8beae39e37af9e76fbe00ad18023242146f31646f811c7aabde0a', 'In 1939 Szpilman plays this piece live at the Warsaw radio station. German bombing hits the station during the performance.'),
('screen_music_cues', 182, 'part_label_en', '3b48bd7a49f6df3ec663355d7e00e8ebd1c21aef44a8b601552fe2c0f8d83c25', 'Second part, ''Grande Polonaise brillante'''),
('screen_music_cues', 182, 'scene_note_en', 'bf2b51bc1555f131d8dfd009d5cc9f5c610e7d3d66e6ab0ac8645df02ad038a3', 'In the hiding apartment, Szpilman, unable to make a sound, only moves his fingers over the keys while imagining this piece. At the end of the film, he plays it on stage with an orchestra.'),
('screen_music_cues', 183, 'part_label_en', '04f9af2f69bcfa2646e818642292b4ed568ad06ba62880ba2447ca87af1a3bde', '1st movement, Adagio sostenuto'),
('screen_music_cues', 183, 'scene_note_en', '8b6f8b68529a0f2f67becf4d54418729751bc8c40859c6bedbdeee6882b6206d', 'Szpilman, hiding in the attic of an empty house, hears this piece from the piano downstairs. The player is the German officer Hosenfeld.'),
('screen_music_cues', 184, 'scene_note_en', '1f3b264f4c0e5b8e90b5ac4898207ea35011a30f0165b2bc2d9d022a882ad5fd', 'In a ruined house, the German officer Hosenfeld has Szpilman play after he says he is a pianist. Szpilman plays this piece on an old grand piano.'),
('screen_music_cues', 185, 'scene_note_en', 'c2bc8eabbfc65508fe0fb4e085261907cd7ec70ed12da8d457d22523f1af1ea6', 'Lieutenant Colonel Kilgore''s helicopter unit attacks a coastal village while playing this piece through speakers mounted on the helicopters.'),
('screen_music_cues', 186, 'part_label_en', '760bc2e088ce0c406c150c35192258b3de00a4c67fe8aee233d686845d4f1490', '1st movement, Prélude'),
('screen_music_cues', 186, 'scene_note_en', '656def7d7c69bfdd75b4a349645579063422a1162343c695cdec6a675dd380ec', 'Shinji plays the prelude alone on his cello at home. Asuka, who has just come back, hears it and applauds.'),
('screen_music_cues', 187, 'part_label_en', '79adeb316e32c500f3ce5cebb76d38a8dac271943b9f602c6a509e12f8ada57f', 'Part 2, chorus ''Hallelujah'''),
('screen_music_cues', 187, 'scene_note_en', '3e56de92bbc654e7d7940533e8c3cca386e1b311434ee594526454a07bb9223b', 'The "Hallelujah" chorus plays in the background while Asuka, inside Eva Unit-02, is subjected to an Angel''s mental attack.'),
('screen_music_cues', 188, 'part_label_en', '5f2063ea9ee68422bf05f9a713fa6a252b4f26006f655ca2c4e7c2154e7710cb', '4th movement, Presto – Allegro assai (Ode to Joy)'),
('screen_music_cues', 188, 'scene_note_en', '019836a75fab34118eb4ed69d1eb22b5f4188941feb4d20819f6daad187b1c23', 'The fourth-movement chorus plays in the background as Kaworu descends to the lowest level of NERV headquarters. Earlier, by the lakeside, Kaworu hums this melody.'),
('screen_music_cues', 189, 'part_label_en', 'b4b8e9e6843627aa34d2b4f74770a46e8c7d881c27e6610eaed1f4ff714dba2a', '1st movement, Allegro non molto'),
('screen_music_cues', 189, 'scene_note_en', 'c6e8dbfb4b962b8b15c4daa3ff02056a5b5cb6db435c4fee39f0c092375e4bee', 'Wednesday plays an arrangement of the first movement of Vivaldi''s "Winter" on the cello.'),
('screen_music_cues', 190, 'part_label_en', 'e52dc1f3279cc6a6f72d71ab17dbb2fd62b469f5ecae7b7420ade28819c47621', '1st movement, Adagio – Moderato'),
('screen_music_cues', 190, 'scene_note_en', 'd74118d66d96a789c0cfc16f74fa05fba14ce3d0d183ec0f35afd844fcdc6752', 'Plays as a drawing of Wednesday playing the cello begins to move by magic.'),
('screen_music_cues', 191, 'part_label_en', '0eeca362da98577347b3f86364e22eed847cadebc21ad34b118dc067a948cad0', 'Act 1, ''Dance of the Knights'''),
('screen_music_cues', 191, 'scene_note_en', '969ac498dcd80fe18f6648566f036da57509f824989f73bf1c250500907bb909', 'Wednesday plays this piece alone on the cello in a dark room, with glimpses of other characters cutting in.'),
('screen_music_cues', 192, 'part_label_en', '3875ebac3b0704dcc26ecae86b4d5fd3ee3cf2b4f220782b25146183a85d2d81', 'No. 2, ''Day of Wrath'' (Dies irae)'),
('screen_music_cues', 192, 'scene_note_en', 'e93fe89df68d02c3d16cf4472c7a80e11453f8c960e719eaee767f9505f50f0a', 'Plays as Wednesday hijacks Enid''s driving lesson and drives recklessly with the instructor still in the car.'),
('screen_music_cues', 193, 'scene_note_en', 'bf7989a98b8e4de49f822de615256971fbc80677045356dc8573a75f62a97964', 'Plays at Camp Jericho when Wednesday summons Eugene''s swarm of bees during the Cadets versus Outcasts contest.'),
('screen_music_cues', 194, 'scene_note_en', 'f9c631fe7136787b0d0fee533c75d4e96a5736496e9f9c0932bd537e290d8b22', 'Serves as the theme of the admissions coordinator Kim Joo-young and plays in many episodes. In episode 13 there is also a scene of Kim Joo-young listening to it alone.'),
('screen_music_cues', 195, 'part_label_en', '01fa817bf1211c3abd932f862ad8ba6800f0f581bb61c1e98137d2f30094c7cd', 'No. 5, ''The Fairy Garden'''),
('screen_music_cues', 195, 'scene_note_en', 'f890a92e0ec2007dff1e3286df0add0a61b5a47c60cb3cfe525ab8e92e0a0302', 'Background music, in a piano arrangement, that plays under scenes where the characters'' emotions come to the surface.'),
('screen_music_cues', 196, 'part_label_en', '5d2eabf856ca26eceed8a589f7ec3d089828b4b9c4fcc196ce850fb14e293904', 'Act 2, aria ''Der Hölle Rache kocht in meinem Herzen'' (Queen of the Night''s aria)'),
('screen_music_cues', 196, 'scene_note_en', '0137669275d0bdaf59a5a273c3b5059c0cd901c26376bae137b2f0482874e368', 'Bae Ro-na sings this aria in front of her mother, Oh Yoon-hee, who told her not to sing and tore everything up.'),
('screen_music_cues', 197, 'part_label_en', '5514b7453e0bbc1ab0d2ea3712cb171bdd045e2d4504e3276a0f25521ce290f4', 'No. 4, ''Mazeppa'''),
('screen_music_cues', 197, 'scene_note_en', '2b235945207d82a16270f158ed8c2a3f8d03c3b8ddd2dbeab6fe1e70c213d2a6', 'Having left her father at the bottom of the stairs, Cheon Seo-jin plays the piano in her lesson room with bloodied hands.'),
('screen_music_cues', 198, 'part_label_en', '3772749955a4bc53b0d5a91c696b3fea36540635f83a568d60c6645783217651', 'Act 1, cavatina ''Una voce poco fa'''),
('screen_music_cues', 198, 'scene_note_en', 'e121d210bcc2afa99f8b153dd6ef173e447f84f0cb0a3ffcf457edac57198931', 'At Cheon Seo-jin''s recital, Oh Yoon-hee, hidden backstage, sings in her place while Cheon Seo-jin only mouths the words.'),
('screen_music_cues', 199, 'part_label_en', 'a5028a4e4ff5989500504d0f32098e49050862ac910114514ba9b65568f31121', 'No. 4, Pie Jesu (Merciful Jesus)'),
('screen_music_cues', 199, 'scene_note_en', 'ab5df3f26ce2308bcca9496e4610e93986eda3486bdf9e46cc4c5a4d88dd75d5', 'Used as background music: an arrangement of the Pie Jesu from Fauré''s Requiem with vocals added.'),
('screen_music_cues', 200, 'part_label_en', '5303dacf844bcdb341238dbec3751b40faf92d14eb3a9b3cf85bc8edac0fbbe5', '3rd movement, Presto agitato'),
('screen_music_cues', 200, 'scene_note_en', '8d0176e95adff9a696393ac3ffcb38e5f6917e370153c0cea17ea51f428ae55d', 'Jin-tae sits down at a piano in the middle of a busy street and plays properly in front of people for the first time.'),
('screen_music_cues', 201, 'part_label_en', 'cbae825488368cfe164705839379bd04768f7056289659125703d838f623f11d', '3rd movement, Rondo. Vivace'),
('screen_music_cues', 201, 'scene_note_en', '3e14f01a4d1a15599778df9af9649ed04adf2372d84afc6ff2a7194926a21276', 'Jin-tae plays the grand piano, its cloth cover removed, at Ga-yul''s house. Ga-yul, who gave up the piano after the accident, listens.'),
('screen_music_cues', 202, 'scene_note_en', '8f660298d778a91f130b9dd7d853cfd02f1005f85f66e9605aab975127ec4965', 'Ga-yul carefully presses a key, Jin-tae picks it up, and the two play a four-hand duet at one piano.'),
('screen_music_cues', 203, 'scene_note_en', '7ad9fb55fbcf2569f5a9b0695c1001055b2ac66d033ddafa5b48e8f201093b14', 'Jin-tae, on stage at the gala concert, plays this concerto with an orchestra. It is a performance scene in the latter part of the film.'),
('screen_music_cues', 204, 'part_label_en', '81505addde1f3331d9c896f994d3dd4cd1a1c84fafd9c517d246bd65b5cbeacb', 'No. 2, aria ''Ah, ch''infelice sempre'''),
('screen_music_cues', 204, 'scene_note_en', '41e941c1e2cd1ee607dc7b2650417c5fae278095e57810f38477bcf679355bec', 'Plays as Geum-ja, released after 13 years, tells the evangelist who has come to meet her, "Why don''t you live right yourself?"'),
('screen_music_cues', 205, 'scene_note_en', '1aae145d827b7eb1fc1d8dfc1b48f6087311154b503c6e931b3335459e2aa665', 'Underscores many scenes, including the one in which Oh Su-hui first enters the prison.'),
('screen_music_cues', 206, 'part_label_en', '7ec05dbcf2e37e92ef4c67e602abe8d24c51c8c3c66f12fbcf5ac47eb208a645', 'Allegro movement'),
('screen_music_cues', 206, 'scene_note_en', 'e349de40a71b4af893678ca7d402232ae05242d063ffc59824f2fc49359e35ef', 'Plays on a sunny afternoon during exercise time in the prison, as inmates talk about how Geum-ja came to be called "the Witch."'),
('screen_music_cues', 207, 'part_label_en', '85e2b4efaadf3f44f090a555d779b80802fd181f9f4e06f620098c6a93d0ee15', '2nd movement, Largo'),
('screen_music_cues', 207, 'scene_note_en', 'da6aca053d9aba1e968cd2900867fb34eba6923537d1066d1ff3d7d03fe2e70b', 'Plays as Geum-ja meets the released Oh Su-hui again and they talk about taking revenge on Mr. Baek.'),
('screen_music_cues', 208, 'part_label_en', '5f6fc27fd6d4267fb9b354b11489ca6ba68413e6742f3a1668a389d31934ceaf', '1st movement, Adagio e spiccato'),
('screen_music_cues', 208, 'scene_note_en', 'a677a368b83a8460f7bf21044aa4c1b4f4aeb5a87466b56bcc567f96573183ee', 'Underscores three scenes, including one explaining the crime committed by the inmate known as "the Witch" in the prison.'),
('screen_music_cues', 209, 'part_label_en', '71b99763f1aeb24b18e22e57b488ac48d888c46be94057f25e82dd3b6facf787', '3rd movement, Allegro'),
('screen_music_cues', 209, 'scene_note_en', 'e082de19720778896cabf0be80a7892cbd0e882490bd7019ca215f39bfb97af2', 'Underscores the scene in which Geum-ja, pursued by kidnappers together with her daughter Jenny, fires a gun.'),
('screen_music_cues', 210, 'scene_note_en', '1fe044109c1060d21c0b293f55d71950f6f9a0a6ecef43297febba9b9be57e08', 'Plays in a piano version as the Count first joins the gathering where Kouzuki has Hideko read erotic books aloud.'),
('screen_music_cues', 211, 'part_label_en', '26d259bbaaa2608e9e76b4bd345973c1303fa17d14ddeb75e94afcbde48e6fb9', 'No. 1, aria ''Ich habe genug'''),
('screen_music_cues', 211, 'scene_note_en', 'aadef8ba4f6ee1363049720c9300f6ebbeea9f76b9dcf45a514b79bc61826e04', 'Father Sang-hyun himself plays this aria''s melody on a recorder. An arrangement of the piece by Jo Yeong-wook also plays at the beginning and end of the film.'),
('screen_music_cues', 212, 'part_label_en', 'e7683ff707b0c2406d73b6732a68e0bbb6d53b4b933e1f5089a93bc8ab458dcc', '1st movement, Allegro con brio'),
('screen_music_cues', 212, 'scene_note_en', '175399cda84e54df1f7b6b7ecec88d9e40fbb7efe3dd306a7cbe65d5f0463cfb', 'Plays over the opening titles as the elderly Salieri, after a suicide attempt, is taken to hospital on a snowy night.'),
('screen_music_cues', 213, 'part_label_en', '810bd38caa18e40f7d672fc8ccf2fc6400504c8a4f1a756e587f1cdc6685f8c0', '3rd movement, Adagio'),
('screen_music_cues', 213, 'scene_note_en', 'ff39fe1ec7ecf1dc34fa5b09031589d2e9ff58b47b0cd8612a4e4862cc519b1f', 'At a concert at the Archbishop''s residence, Mozart rushes in and conducts when his piece has already started. Salieri points out the oboe and clarinet passages in a monologue.'),
('screen_music_cues', 214, 'part_label_en', '28e919d277daf07c714b6b39371550b619cdcf737c8f833e157f038adad3aaa3', 'Act 2 finale, Commendatore scene ''Don Giovanni, a cenar teco m''invitasti'''),
('screen_music_cues', 214, 'scene_note_en', '36952001f516096ee85ccc16670b8fc8e5fdc32e311733deb31e4802f6d390a5', 'Mozart stages and conducts Don Giovanni in Vienna. From the audience, Salieri watches the scene in which the statue of the Commendatore appears.'),
('screen_music_cues', 215, 'part_label_en', '06075cd1d423553c114fe90a81af4df7a2ec73267533eac500893122b7737369', 'Sequence, ''When the damned are confounded'' (Confutatis)'),
('screen_music_cues', 215, 'scene_note_en', '1fc07c470b6d7ed25d3cdf813c95c68923ec4a886acd66ea804376c9d66f2401', 'Mozart, on his sickbed, sings this section of the Requiem part by part, and Salieri writes it down. As each transcribed part is added, the piece takes shape.'),
('screen_music_cues', 216, 'part_label_en', '8693763e0f1bf7a02493bb232bbd7604c9b74e1e4404056ec6fd61c55b46f244', 'Sequence, ''Day of Tears'' (Lacrimosa)'),
('screen_music_cues', 216, 'scene_note_en', '7bf8844cd4ad89da84ba6d199c08d38f269d1b31b0c36fb61e96b58f387f3b62', 'Plays in the scenes of the funeral procession on a rainy day and the burial in the cemetery after Mozart dies.'),
('screen_music_cues', 217, 'part_label_en', 'e6153337b41106027d0b542475005515994436c401802d6362c51e72e26b470c', '2nd movement, Romance'),
('screen_music_cues', 217, 'scene_note_en', '4141282bf014db2422128da340a6fdd5bbae82c1c2e72ff4457253fa464464cf', 'First heard when the client in black clothes visits Mozart. It returns in the final asylum scene and carries over into the end credits.'),
('screen_music_cues', 218, 'part_label_en', '91f6573a557419dd86a65ad3c12a0b5a77803645725ffc9a5a69bb2da4f29c06', 'Aria'),
('screen_music_cues', 218, 'scene_note_en', '38f8e86f6e77018f0fff5d5f84bcdce50e9b958b5306270ebd9a3d6c159ba6b2', 'In his makeshift cell in Memphis, Lecter plays this aria on a cassette and listens. While the music plays he attacks two guards and escapes.'),
('screen_music_cues', 219, 'part_label_en', 'de65c2b688ddb6b8c9aa97eb8a0d6c99c08a826d05bb1b299d50cbedf6882145', 'Prelude'),
('screen_music_cues', 219, 'scene_note_en', '60d19611eb462c6d6b4657d80ea0ebca267526430c9ceb4e171a81e9a682c1ec', 'In a Juilliard conducting class, Lydia plays this prelude on the piano to explain to a student, Max, who says he won''t study Bach.'),
('screen_music_cues', 220, 'part_label_en', '6b05da6096d73a7415f5f449e06a44ec293d1521d80c29952e69fa0d9f0b29ad', '4th movement, Adagietto. Sehr langsam'),
('screen_music_cues', 220, 'scene_note_en', 'd09d065cb6bfb769dedc4d5ba4606091c440d9f66bc6d75f2202d4d1628751be', 'Lydia rehearses this movement with the Berlin orchestra ahead of the live recording. When the strings become too syrupy, she tells them to "forget Visconti."'),
('screen_music_cues', 221, 'scene_note_en', 'ff6c0716ec7f60e228377755468361f22588ec7d844834bb32b7601e23244956', 'Lydia chooses this concerto to program alongside Mahler''s Fifth, and Olga, the newly joined cellist, plays the solo.'),
('screen_music_cues', 222, 'scene_note_en', '7d816239fd905bf14099ae6e0188f270fb848e3247e880a90e3660e99de062da', 'Plays as Chris, withdrawing by helicopter, sees Elias, left behind in the jungle, chased and collapsing. It is also used in the first scene and the burning village scene.'),
('screen_music_cues', 223, 'scene_note_en', '677c3a9b51bba10479f2cf516715a44aae19a8ca60b62ed018622197d3e23568', 'During a performance of Turandot at the Vienna State Opera, Ethan tries from backstage to stop the snipers targeting the Austrian chancellor.'),
('screen_music_cues', 224, 'scene_note_en', '27991db96b46f2232dfe68daddb950a1f25529791afeb1055f29c81bd2e7bcdd', 'Joe Kraemer''s film score borrows the "Nessun dorma" melody and uses it again in later scenes in which Ethan and Ilsa are alone together.'),
('screen_music_cues', 225, 'part_label_en', '5325916985e542479d6040df91d13a0892900396d44be69f1710a8b40f9abed1', 'Act 1, aria ''Sempre libera'''),
('screen_music_cues', 225, 'scene_note_en', 'd1de48db7338932e3e9e72db69598c36645131d72996ec9f1ca494521e20c5d8', 'In the scene where Edward takes Vivian to see La traviata at the San Francisco opera house, "Sempre libera" from Act 1 is heard.'),
('screen_music_cues', 226, 'part_label_en', 'e9f81f44cc5313c64403601c29044cf1e37494a88a8734d1ef636832a2fb7ae3', 'Act 2, ''Amami, Alfredo'''),
('screen_music_cues', 226, 'scene_note_en', '2db6807246f9ece23caad9220799854a7322783a0af515b106dcfcebecf620bf', 'In the same opera scene, "Amami, Alfredo" from Act 2 is also heard. Toward the end of the performance, Vivian sheds tears.'),
('screen_music_cues', 227, 'part_label_en', 'b8bdbbb23a538d6e04cab9a55a720b62d4e91f2cac7f60be4741aff1620af8bf', 'No. 3, ''Clair de lune'''),
('screen_music_cues', 227, 'scene_note_en', 'e314b68ca5d399b34a8c69c0f3d6ca196f37915fbbb48881495cbab8a41c71c8', 'Plays as Danny Ocean''s crew, job done, watch the Bellagio fountain show together and then go their separate ways one by one.'),
('screen_music_cues', 228, 'scene_note_en', 'bf50e97bfb85dddf67ec36e2bdb56e4377eb7463c107dafa5b5461da81c1cb84', 'In the opening scene, where Nina dreams she dances the prologue of Swan Lake, the music plays in an arrangement by Clint Mansell.'),
('screen_music_cues', 229, 'scene_note_en', '90c8ed6b3f001c823ec62981a27a61f551b09a67c1418779e897ba2f5d156ffe', 'The violinist Tim Fain appears on screen as the accompanist and plays live in several of the ballet scenes in which Nina dances.'),
('screen_music_cues', 230, 'part_label_en', 'dd9ccd5c5b671f85f3c0dd64ff9b042084ec5f1b83c1b95c077ecf5551a1f7a9', 'Act 4 finale'),
('screen_music_cues', 230, 'scene_note_en', 'e1dc5c39e55b09ad55f49a6b8286fe746e2f850f15f52100311477f5a248d100', 'Plays during the last act of the premiere, as Nina dances the final scene as the Swan Queen.'),
('screen_music_cues', 231, 'part_label_en', 'd7642e1aedc999ae56f7ad5dc8dfc9c5f978c84bfe21c3e5d566755c49c224d0', 'March'),
('screen_music_cues', 231, 'scene_note_en', '6ff3b39f7899681563c62e25b15cb6e598d7bbed5b75963abfedcdf1663e00bd', 'Heard in a synthesizer arrangement over the opening titles and the first scene showing Alex and his gang at the Korova Milk Bar.'),
('screen_music_cues', 232, 'part_label_en', '8b16d5a2e75090ec6460223a1d4d96067f46db1b64132f551ce51c61f66f784a', 'Overture'),
('screen_music_cues', 232, 'scene_note_en', '3e32aa23e39b1677c8ace2d6536d37c53bddea407399daf08484f194c569501c', 'Plays as Alex attacks George and Dim, who have challenged him, on the riverside promenade. It is also used in the gang''s other scenes of violence.'),
('screen_music_cues', 233, 'part_label_en', '8b16d5a2e75090ec6460223a1d4d96067f46db1b64132f551ce51c61f66f784a', 'Overture'),
('screen_music_cues', 233, 'scene_note_en', 'cbf021bc272050a48595e2f925bac38fbaf3c9efcbba54dce89d0129e8bbda85', 'Plays in fast motion as Alex spends time in his room with two girls he met at a record shop.'),
('screen_music_cues', 234, 'part_label_en', 'dbdade1f0a6f2c472991d5f968da343e8772281120ea7b72bcbc09b948e78209', '2nd movement, Molto vivace'),
('screen_music_cues', 234, 'scene_note_en', 'ef1bc71262b0040322079d584f10fe6512148364cb7c7332ca0ed082b1e68da8', 'Alex lies on his bed in his room, playing this movement and sinking into violent fantasies.'),
('screen_music_cues', 235, 'part_label_en', 'a047b1c75f7e0275034690e668d19e9fc494cdb4a2681b3de8cac20fd8d4659b', '4th movement, Presto – Allegro assai'),
('screen_music_cues', 235, 'scene_note_en', '2e138969ca74512ad4a76653d2515819d8f9895704643c475909776eecb3aed8', 'Heard as the film music of the Nazi newsreel footage that Alex, undergoing the Ludovico technique, is forced to watch with his eyes held open.'),
('screen_music_cues', 236, 'part_label_en', 'dbdade1f0a6f2c472991d5f968da343e8772281120ea7b72bcbc09b948e78209', '2nd movement, Molto vivace'),
('screen_music_cues', 236, 'scene_note_en', '95b6830df47f5139802114e46f54d87319062ee6b024b5c782ddadbd7014fb74', 'The writer Alexander plays this piece loudly downstairs for Alex, whom he has locked in an upstairs room.'),
('screen_music_cues', 237, 'part_label_en', '039d7ad47a7d5b53c8daf782bbc5043a694235724e494d9ea1ef42e7b1a7d562', 'Act 1 Prelude (Vorspiel)'),
('screen_music_cues', 237, 'scene_note_en', '1e2138ecf407f0cf02398ea55ec16ae7de7305aafc1282e48860ed8e48181dd5', 'The prelude plays under the slow-motion images of the roughly eight-minute prologue before Part 1 begins. It returns several times in the main film.'),
('screen_music_cues', 238, 'part_label_en', '6b05da6096d73a7415f5f449e06a44ec293d1521d80c29952e69fa0d9f0b29ad', '4th movement, Adagietto. Sehr langsam'),
('screen_music_cues', 238, 'scene_note_en', '55823f2a3fc1f9b784b8b811f300d8a3ab030a0325a4cf7e8d20cf5e8065d165', 'Heard in the first scene, as the steamship carrying Aschenbach glides through the lagoon at dawn into Venice. It returns several times up to the final beach scene.'),
('screen_music_cues', 239, 'part_label_en', '9fd6b6186f30ac227514d83c139865ee92e4cd266a05f56b911f09163f646b99', '4th movement, Sehr langsam. Misterioso (''O Mensch! Gib Acht!'')'),
('screen_music_cues', 239, 'scene_note_en', '5b305783c02d195a0fd355cf0a000e3c12f1a529ebfa3752617e7e73c02e7766', 'Heard as Aschenbach, seeing Tadzio pass by the beach hut, begins to write music.'),
('screen_music_cues', 240, 'scene_note_en', '2a799f401302b1dffae8086c9dba2e7c92bf7da28a6d6a722b2b0d5ff1c881c4', 'Tadzio tries playing this piece on the piano. Aschenbach recalls the prostitute Esmeralda, who played the same piece.'),
('screen_music_cues', 241, 'scene_note_en', 'ca0629e2a08be41c8f691643dbcb8bb6661f2a4ff21df299253f7ef3f4daf2e6', 'As Aschenbach, having heard that Tadzio''s family is leaving, goes out to the beach, a Russian woman sings this song unaccompanied.'),
('screen_music_cues', 242, 'part_label_en', '04f9af2f69bcfa2646e818642292b4ed568ad06ba62880ba2447ca87af1a3bde', '1st movement, Adagio sostenuto'),
('screen_music_cues', 242, 'scene_note_en', '8b4fc4f253b31e98eda6b623fd96252c790a55837609577f1307d4d4a53e1f03', 'At a memorial service for a former village head, the first movement of the "Moonlight" sounds in the community hall, and a wealthy man of the island is found dead. The sonata is heard in each case that follows.'),
('screen_music_cues', 243, 'part_label_en', '26e2985460bf5f91d49e54bfdb9901382a48b47619f7df81e0c9a30ae40ff32d', '1st movement, Allegro con spirito'),
('screen_music_cues', 243, 'scene_note_en', '1e1e0c534ced565b424e86dff9752d037e919ef64e571f431d4de1cd5cbe9321', 'As an assignment from Professor Tanioka, Chiaki and Nodame play this sonata together on two pianos.'),
('screen_music_cues', 244, 'part_label_en', '4fa50fd1fd5284930b800f43d108236a9f03b6a3668ed1035c8fcb4c7676d2e2', '1st movement, Poco sostenuto – Vivace'),
('screen_music_cues', 244, 'scene_note_en', '3fd9e5459a71536025ef211452cbca12189fac94b9390a1915694c12ae262701', 'In episode 5, Chiaki conducts an S Orchestra rehearsal in Stresemann''s place, but the ensemble falls apart. It is performed again at the R☆S concert in episode 23.'),
('screen_music_cues', 245, 'part_label_en', 'e7683ff707b0c2406d73b6732a68e0bbb6d53b4b933e1f5089a93bc8ab458dcc', '1st movement, Allegro con brio'),
('screen_music_cues', 245, 'scene_note_en', '4b1a87aec1630e757be25e8683d4f7de9822b39a37e631e503d5e8253895988d', 'The S Orchestra, conducted by Chiaki, plays this symphony on stage at the school''s regular concert.'),
('screen_music_cues', 246, 'part_label_en', '4bc4e761ea16e2ff4583636c1e2c562dee41e3ffcb914d30b209694f5401e685', '1st movement, Moderato · part of 3rd movement, Allegro scherzando'),
('screen_music_cues', 246, 'scene_note_en', '8b0901207b5f679e2e227a5a03fb5d4e3b75d567f254275bc8f6a226bd2798c6', 'At the school festival in episode 11, Chiaki plays the solo while Stresemann conducts the A Orchestra. In episode 12, he plays it with Nodame on two pianos.'),
('screen_music_cues', 247, 'part_label_en', '0778dadba146db2cf08a6b585dc6d59b08e19709e0153dd9764d62fd8d065ba7', '1st movement · part of the 4th movement'),
('screen_music_cues', 247, 'scene_note_en', '2666777b76991d540f84c6730d2097dd52aebf5aa1ac76482758c7e3a7081e5b', 'Chiaki conducts this symphony at the first concert of the newly formed R☆S Orchestra.'),
('screen_music_cues', 248, 'scene_note_en', '893dbeb3cca83e7eb2259900c8c3f9e47cc917ee62669236205667db2ecdeacc', 'Pan Wei plays this piece in the first round of the Chopin Competition. Kai, in the audience, hears Pan Wei play for the first time and is stunned.'),
('screen_music_cues', 249, 'scene_note_en', '598b6bd57d8084e24b4cc1a625da6dcf7556a6aab5293cfdfa4a4fd8673d638d', 'Shuhei plays this étude, nervously, on stage in the first round of the Chopin Competition.'),
('screen_music_cues', 250, 'scene_note_en', 'eccb464e12d77d3e4ee7b96ebabc94516a276079b66cc0123fc5a7a459bee9c4', 'At last Kai takes the stage in the first round of the Chopin Competition and begins his performance with this étude.'),
('screen_music_cues', 251, 'part_label_en', '7253f70e1591769115520705eefd93a1a11a5e308fd3f333e5f52d96cc958ec3', 'Movements 1, 3 and 4 (3rd movement: Funeral March)'),
('screen_music_cues', 251, 'scene_note_en', 'c7c298554d288efa3bd41756658965d0d7d02c8c8abd997d1cfcc691203c9ee5', 'On the first day of the second round of the Chopin Competition, the favorite, Pan Wei, plays this sonata.'),
('screen_music_cues', 252, 'part_label_en', 'a26d2c315718b34ca0c8cc9373be513c153a82a65f99783ce8a64d2634ea1d41', 'Movements 1, 3 and 4'),
('screen_music_cues', 252, 'scene_note_en', '7a589ba9059ebea194082e2d6f11d5ea2aeac1f0cb6e2b57c3590ea61d02d5ac', 'In the second round, Kai takes the stage after Lev and plays this sonata.'),
('screen_music_cues', 253, 'part_label_en', 'dc2b72cb8b8fa3b1cab150f189914190cf38dfefa47146a757855771a5601b0e', 'Movements 1–3'),
('screen_music_cues', 253, 'scene_note_en', '7620b91d4be2fa480498ab279a52470480459479feb4b78ede9c19caf71f4d2e', 'On the last day of the finals, Kai plays this concerto with an orchestra. Pan Wei and Lev play the same piece in the finals too (season 2, episodes 7–11).'),
('screen_music_cues', 254, 'scene_note_en', '86048a1285b3a629e085279f55391287c2c8bbc72947f67424b51bcc8148c361', 'A live-action scene of the Philadelphia Orchestra playing under blue lighting gives way to animation of abstract lines and shapes.'),
('screen_music_cues', 255, 'scene_note_en', 'ba1d8c6daa16b507e01acadb8f4c5049d3e83c5443c06d484b5d101dae5c10a5', 'Fairies, mushrooms, fish and flower petals dance to six numbers from the suite as the seasons change from summer to winter.'),
('screen_music_cues', 256, 'scene_note_en', 'ab049a64b67649f865b741ae9b5f45fc9014b28cf37ab0f580640530be1c77b7', 'Mickey Mouse, apprentice to the sorcerer Yen Sid, enchants a broom behind his master''s back, and the workshop is flooded.'),
('screen_music_cues', 257, 'scene_note_en', '740fba5fdeaffda44ca280460ff978088b731b993c57683f549c036067141e87', 'Shows the formation of the Earth, the appearance of the first living things, and the rise and extinction of the dinosaurs.'),
('screen_music_cues', 258, 'scene_note_en', 'd43669e08be90929c2f26c538d45d6b69e355de44ad7dad84a14e52db170a26b', 'Centaurs, cherubs and fauns hold a festival of Bacchus until a storm raised by Zeus hits them.'),
('screen_music_cues', 259, 'scene_note_en', 'fd2e94efdbc438e4ca48c73bca44df1bc143eee881a8fe1dd19b559b8c086026', 'On Walpurgis Night the demon Chernabog summons the spirits of the graves to Bald Mountain. They retreat at the sound of the dawn bells, and the music leads into "Ave Maria."'),
('screen_music_cues', 260, 'part_label_en', 'e7683ff707b0c2406d73b6732a68e0bbb6d53b4b933e1f5089a93bc8ab458dcc', '1st movement, Allegro con brio'),
('screen_music_cues', 260, 'scene_note_en', '2da7bbbc17167539462c2543d95c406f041d23ed7487a97cb88185c6da639e43', 'Triangular, butterfly-like wings are chased by black bat-shaped figures, then find their light again.'),
('screen_music_cues', 261, 'scene_note_en', 'b1e56e4b0bc5c181eebe2dace7a93584a9938cdf5ceb6c0dc67bec00538467c1', 'A calf from a family of flying humpback whales gets trapped in an iceberg, escapes with its mother''s help, and soars above the pod and the clouds.'),
('screen_music_cues', 262, 'scene_note_en', 'b12b7f1128bcb7837b4c446172931adc3f902657e019dae6bef1bd9df326f288', 'In 1930s New York, an unemployed man, a construction worker who dreams of being a drummer, a lonely girl and a rich husband each get the day they wished for.'),
('screen_music_cues', 263, 'part_label_en', '42cac066e1ebf4e8361d799a6801e74096ce271f841b561f231d0b43b536fe78', '1st movement, Allegro'),
('screen_music_cues', 263, 'scene_note_en', 'bcd83b577a39a0d5d2d18cde41054fd17a51856a351222adf3d77e916cea1853', 'A one-legged toy soldier falls for a ballerina doll and protects her from a nasty jack-in-the-box.'),
('screen_music_cues', 264, 'scene_note_en', '52ddc8bd4b24a2d45fc5430d06dd229feca92a6a4987d23d58a697a9060cf678', 'Donald Duck, Noah''s assistant, loads the animals onto the ark, gets separated from Daisy, and then finds her again.'),
('screen_music_cues', 265, 'scene_note_en', '22271cb5d297ffa985ffe0387b8713d7e16b49450c3259d990d2c2a36ce7ecbf', 'A spring sprite awakened by an elk brings the forest to life, then wakes the Firebird in the volcano, and the forest is engulfed in flames.'),
('screen_music_cues', 266, 'scene_note_en', 'e9cc9d2916bf88fad0325c48cdbaebf1ca6d6736d69ac2ed52e49698bc9aa949', 'Tom, in tails, plays this piece on a concert stage while Jerry, who lives inside the piano, keeps disrupting the performance.'),
('screen_music_cues', 267, 'scene_note_en', '2d9ef6cfae6246f0af8b2fbc678ac8b9d16e876d4993b6bf2a89a31660e20ca3', 'Elmer Fudd, dressed as Siegfried, jabs his spear into Bugs''s burrow and sings "Kill the wabbit" to this melody.'),
('screen_music_cues', 268, 'part_label_en', '8b16d5a2e75090ec6460223a1d4d96067f46db1b64132f551ce51c61f66f784a', 'Overture'),
('screen_music_cues', 268, 'scene_note_en', '8fa6dd110fa786377bb553dbf757346d0993443bf587d6701d44853f949f3151', 'Elmer threatens Bugs for the first time by calling down lightning to show off the power of his spear and magic helmet.'),
('screen_music_cues', 269, 'part_label_en', '8b16d5a2e75090ec6460223a1d4d96067f46db1b64132f551ce51c61f66f784a', 'Overture'),
('screen_music_cues', 269, 'scene_note_en', 'fb9d2ba1d11f8d0732363a1d8d033b5d75541692e7628b51fe837e67705f539a', 'Plays in the chase scene in which Elmer pursues the frightened, fleeing Bugs.'),
('screen_music_cues', 270, 'part_label_en', '1dd1afee277b9a22a2f4ef84da2dbf985307f50110d3ba31f2de06c6beb4555d', 'Act 1, ''Venusberg Music'' (Bacchanale)'),
('screen_music_cues', 270, 'scene_note_en', '6282e217f2fa7132073b7a6eee3b9296cab7ed4c79260e7792443f56ed541df2', 'Bugs disguised as Brünnhilde and Elmer dressed as Siegfried dance a ballet together.'),
('screen_music_cues', 271, 'part_label_en', '0c61bfe14d29d1fe3139ea2190d3f829c6dfaf994c22e3430f67b406f0d45d9f', 'Pilgrims'' Chorus'),
('screen_music_cues', 271, 'scene_note_en', 'd35579b167aa46f665e4b971d9a97795c89952fec47f78b65bb337ca8ebefad1', 'After the ballet, Bugs and Elmer sing the love duet "Return My Love," set to this melody with new lyrics.'),
('screen_music_cues', 272, 'part_label_en', '780b19e8c543ee85df73ca29cde1ad9fff1a86ea06b808aae773ad0722f5abd1', '1st movement, Kräftig. Entschieden'),
('screen_music_cues', 272, 'scene_note_en', '5377dd8f6f633a0822b0b0670878703a8021f52f5ba52e39ac3a73166ec6af21', 'Plays over the first narration of episode 1 and the scene in which the Imperial admirals gather. It is used in the opening narration of many later episodes as well.'),
('screen_music_cues', 273, 'part_label_en', '9c27a356a942dfe2de04566a16285cea68d177accad7a2b58c41bb4118e874ec', '4th movement, Allegro con fuoco'),
('screen_music_cues', 273, 'scene_note_en', '030e95ac20f61bbbb9e96cc5a3d936570d1d9db3634bdc23a51d23d9e9431942', 'In episode 15, the Alliance fleet, pushed back after its supply lines are cut, gathers at the Amlitzer star region for a final battle with the Imperial forces.'),
('screen_music_cues', 274, 'part_label_en', '88bdb62c04a1e2c76a9d2d618a8c1d43d5a984daa52dd91c7988ed100b0e6c88', '1st movement, Andante comodo'),
('screen_music_cues', 274, 'scene_note_en', '8d047a8a894928f936c07797b535e9331db3e76be027c2b9dccb63a9df86f65a', 'In episode 23, Oberstein advises against stopping the nuclear attack on Westerland, leading into the scene of the burning planet.'),
('screen_music_cues', 275, 'part_label_en', '9bb7476c5465ddb2e6209ff4a7cc6502002843f1845fe5d0b43a3ae266b21ec4', '1st movement, Allegro moderato'),
('screen_music_cues', 275, 'scene_note_en', 'fbe5d0d0e4602d454fe8171ee6dd00b3be1e4fe92a89738ad12c972679c87a2a', 'At the victory ceremony in episode 26, Reinhard watches the end of Kircheis, who took the blow of Ansbach''s attack in his place.'),
('screen_music_cues', 276, 'part_label_en', '05a10cc7692fa22124fc2f56699892c4a19453550ed0ecfd2f8c028179fe6f1f', '4th movement, Stürmisch bewegt'),
('screen_music_cues', 276, 'scene_note_en', 'd0c71a76569bb13b280aa0d7f039877066d628ba1742a5ba94e8380b6a681b26', 'In episode 51, the battle in the Vermilion star region begins between the Imperial forces and Yang Wen-li''s fleet, which has driven deep into enemy territory to go after Reinhard.'),
('screen_music_cues', 277, 'part_label_en', '54eddb545626ed6a2d89ad9bf6084a9907ba7d4222d332b0e26c95957265869d', '1st movement, Feierlich, misterioso'),
('screen_music_cues', 277, 'scene_note_en', '3ffabfcc8bac65b9aee6fae4091e19a0286a7d0024fc77b9512417815625eaca', 'In episode 82, plays as Yang Wen-li, on his way to a conference, is attacked by assassins aboard a cruiser and falls.'),
('screen_music_cues', 278, 'part_label_en', '5e4875bfbe7825a7fd1d588dd6bb5f22fbdbf39845b5117833a5abd2a37e9af4', 'Act 3, the Duke of Mantua''s canzone ''La donna è mobile'''),
('screen_music_cues', 278, 'scene_note_en', '4ea0054731e64556d32c207ea291b415782b4b03bf6e1c6dbad1f7ce5c3014cc', 'At the start of the film, Jang-ho and Sang-jin are each driving along in their own cars, and this aria plays on a car radio.'),
('screen_music_cues', 279, 'part_label_en', '1994cbde9235e4388099bfabd52a1f26fed473382468e50d49f420625fbf13aa', 'Act 3, Cavaradossi''s aria ''E lucevan le stelle'''),
('screen_music_cues', 279, 'scene_note_en', 'c4d2d4d444cb40d9afa0e53b236c46d8890f5db21aa47316acce9f970ab9fb8f', 'Jang-ho sings this aria to Sang-jin''s piano accompaniment, revealing his talent for singing. The singing was recorded by the tenor Kang Yo-seph.'),
('screen_music_cues', 280, 'scene_note_en', 'bd0cfc3b83b4a672628db377e82a55ea1dc2ed471bcee1391e4d191eaeb08767', 'In the latter part of the film, Jang-ho takes the stage and sings this aria. The singing was re-recorded by the tenor Kang Yo-seph to match Lee Je-hoon''s acting.'),
('screen_music_cues', 281, 'part_label_en', 'd5da52723557f0563c3d4fcef81bee0769955cc184181d98af14471fd917a2e7', '2nd movement, Adagio un poco mosso'),
('screen_music_cues', 281, 'scene_note_en', 'ceeac5a6f97e16ab59384d0e1105b5fdfedc1b1aab666930a1c625e67943897d', 'Plays when Gwang-ho, the owner of a pizza shop, first sees Ji-su playing the piano.'),
('screen_music_cues', 282, 'scene_note_en', '2a4163d963ff140efc0f0e9dbf2bb803d89ca2e1b093c05683f82f7f4c7eec6a', 'On the night Ji-su returns from meeting successful former classmates, she plays this piece at home all night.'),
('screen_music_cues', 283, 'part_label_en', 'e371ac5d54cfaf5639f95dc301cdaefea7c70ec5747b3a5a02325e468ccf629e', 'No. 7, ''Träumerei'''),
('screen_music_cues', 283, 'scene_note_en', 'a99f579f366e0435ac8f19136f6f61783a28e2b7137f1d51ded35218e502ee99', 'Ji-su plays this piece on the piano to comfort a downcast Gyeong-min. It returns near the end of the film.'),
('screen_music_cues', 284, 'part_label_en', '3ba83b40a4808d33640b2f1a681bd87e7ba0afee0816535e9310777e282c5f5c', 'No. 1, Andantino con moto'),
('screen_music_cues', 284, 'scene_note_en', 'f1f93798ca065b6e6e6ee9a7c0c17662583cff09fef0867592878b1f931a8831', 'Gyeong-min plays this piece in front of an audience at a house concert and is recognized for his skill.'),
('screen_music_cues', 285, 'part_label_en', '5f06bcd95e8a2f764f72af6c000be44fd7caba2850fcab3065045076c317a511', '1st movement, Moderato'),
('screen_music_cues', 285, 'scene_note_en', 'd8511d3231c2568a89410bb2b8d0b60117dfbf6c6993f988c3a2c1c132db22be', 'The grown-up Gyeong-min plays this concerto with an orchestra on a concert stage. The adult Gyeong-min is played by the pianist Kim Jeong-won, who also performed the piece.'),
('screen_music_cues', 286, 'part_label_en', '7da72c3cb6249b3fe34b4684b82c1b7d2837c017e70ba719c44be4ef8fa7561a', 'No. 19, ''Solveig''s Song'''),
('screen_music_cues', 286, 'scene_note_en', 'c4a486366af7aade73c1c1ad40252d8161772c8006e564b541c9e48bc2a00ea8', 'The Harmony choir from a women''s prison sings this song in chorus on a big concert hall stage as the climax of the performance.'),
('screen_music_cues', 287, 'scene_note_en', '903f46bc15cf7c03d0a4ed68cc0dd4180a29739319fd3056396b4fb6ca472c21', 'Kang Bi-o''s signature piece. Kang Bi-o plays it on stage at the first competition in episode 1 and in the face-off in episode 5.'),
('screen_music_cues', 288, 'scene_note_en', '1defe7d84475f69ab16c4012ddb6a370e22b5da15b09a4eb18a47c9ad6db80d4', 'The piece through which Choi Jeong-yo and Kang Bi-o grow close when they first play four hands together. It returns in several later episodes.'),
('screen_music_cues', 289, 'part_label_en', '351cb68b4c008ad9b1f02d7d035a56e1e12875333503a512795ba1bb09bee4e8', 'No. 10, chorale ''Jesu, Joy of Man''s Desiring'''),
('screen_music_cues', 289, 'scene_note_en', '531189acaf0de4a06caace11dd3de83aeb0e4e5f8cdb2c850ad2007390a0553f', 'Kang Bi-o and Choi Jeong-yo sit side by side at a single piano and play four hands together.'),
('screen_music_cues', 290, 'part_label_en', 'be3b0c42eebee12180fa2a80588bd567dacc6268f51d9acaa779d40fd3f78990', '1st movement, Grave – Allegro di molto e con brio'),
('screen_music_cues', 290, 'scene_note_en', '17e20c8c39e995426492eb72aad493c6a0f4824ceca73dfd8337b1bcce82f6e8', 'In the final scene of episode 4, Choi Jeong-yo plays this piece while Kang Bi-o watches from a distance.'),
('screen_music_cues', 291, 'part_label_en', '9dba218a53f5000e798daa3d49bd769e6409f58bf15b40f1d2c623dfb3559578', 'No. 1, Sonatina'),
('screen_music_cues', 291, 'scene_note_en', '675392e47f496d9cc2fbcda6975f3714ff4dac5a60210f9e8408c3c07428867a', 'A piece that Kang Bi-o and Choi Jeong-yo play four hands. In the final episode, the two play it together again.'),
('screen_music_cues', 292, 'part_label_en', '1bea4ab6f95445d1b5439f0b370d71aa0aa62da6a58728f3b34c8a8144e7e1a2', '2nd movement, Andante'),
('screen_music_cues', 292, 'scene_note_en', '9b0986ac1883ec58af34f9d5f5df5d1319933c2bb96ca6a08bcd4de5eaad71d7', 'After her mother dies, the conductor Cha Se-eum plays this movement on the violin at the funeral.'),
('screen_music_cues', 293, 'scene_note_en', '29b620d15b6c9835774cbeb36beb68e080e85e9253e2d6ee9b886ae45d201047', 'In the final episode''s performance, Cha Se-eum plays with the concertmaster Lee Ru-na on two violins with the orchestra.'),
('screen_music_cues', 294, 'part_label_en', '5f06bcd95e8a2f764f72af6c000be44fd7caba2850fcab3065045076c317a511', '1st movement, Moderato'),
('screen_music_cues', 294, 'scene_note_en', '95a8a283ef22f455ac7526a6294033e5b9c7a54691ccb04ecf2dd6a3d382cfe1', 'The opening of the first movement plays under the opening title cards at the start of the film. The pianist is Eileen Joyce.'),
('screen_music_cues', 295, 'part_label_en', 'daa17618ae339f75d50d55c3bae5f1ce8d910717ddb567724d6174695fbcfe33', '2nd movement, Adagio sostenuto'),
('screen_music_cues', 295, 'scene_note_en', '3add52ac572c6fcb8a8d9a0c767c8b7bfea3a3113875e3fa22d12bcaff2b782e', 'Laura listens to this concerto on the radio in her living room and recalls what happened with Alec, while her husband does the crossword beside her.'),
('screen_music_cues', 296, 'part_label_en', '1bea4ab6f95445d1b5439f0b370d71aa0aa62da6a58728f3b34c8a8144e7e1a2', '2nd movement, Andante'),
('screen_music_cues', 296, 'scene_note_en', '6862ab5e199c16d1483056b439265424a3073f46d47e96254bb6a3b02a6033e0', 'Repeated as background music throughout the story of Elvira and Sixten''s flight and life together on the run. The recording used is by Géza Anda.'),
('screen_music_cues', 297, 'scene_note_en', 'e1e7c4eba202466b58a4528d583eaea7d341365f48b8dea9beca81c2ff86d5e7', 'Plays over the opening titles as Jake LaMotta warms up alone in an empty ring. It returns at the end of the film.'),
('screen_music_cues', 298, 'part_label_en', '1db95c84a61367469a90e8d3c5d0aa59b813b857bfcba12c385d0034ec1e631c', 'Barcarolle'),
('screen_music_cues', 298, 'scene_note_en', 'f6ca4c458102394a8085a4541043cd03691cd2e2008faafb5c5f45f61e94ac3c', 'Plays in the color home-movie scenes of everyday life of the LaMottas and their family.'),
('screen_titles', 50, 'title_en', '7888cce71572fcd98b9f28e219d71b1b6e32f50893f2c28024302c3b23c6c09f', 'Squid Game'),
('screen_titles', 51, 'title_en', '175ca2d36da367571620ab09928b43e2a50b22f28dda9d153c1e40d44976be6c', 'Parasite'),
('screen_titles', 52, 'title_en', 'dbc1011c797f44ac5bd0d8a223c2967b3a535d87fb462de8aa1b8a60baede4e7', 'Decision to Leave'),
('screen_titles', 53, 'title_en', '6c9b22c0b66c6ad84e5ca08ca81c7cf2bb164594a4538812b5e7f707a91abb07', 'Oldboy'),
('screen_titles', 57, 'title_en', '103dba1960ff5f3737cb76a1c8133f776aa793e1e901264b66c9fb054a1e1768', 'Your Lie in April'),
('screen_titles', 58, 'title_en', '9058b8ce667572c22b6af9633a01e7373055b66336e0ac070a3510d81711f317', 'Do You Like Brahms?'),
('screen_titles', 59, 'title_en', '7c8bd2ebecbcf28b2c50a9271e8f5e893364d8e11d22649d2526e35e5922fbe0', 'Secret Love Affair'),
('screen_titles', 60, 'title_en', 'e96aa991fdfdc701dac8eaf20761e11b70c3d57c9ef9e962ad0ab3535bcc0cfe', 'Beethoven Virus'),
('screen_titles', 63, 'title_en', '81c01a36f6119d3c8e5f0ec90f1c2db6914f89592097c02f9fa59b1202d75a08', 'Neon Genesis Evangelion'),
('screen_titles', 65, 'title_en', '73bf07439ce264ef50d75118bd8a084c3497d78e6db12bbb62f1a5df14f1d5a3', 'SKY Castle'),
('screen_titles', 66, 'title_en', '27f945480326c0e3884f59f077984a152844b3e4f3085cfce00de7b4a6ed17fb', 'The Penthouse: War in Life'),
('screen_titles', 67, 'title_en', 'abfee1b8cd47d498c7cdba32cc3c4e1a96215a40af22b95b9b0cd49ebfb5fa7f', 'The Glory'),
('screen_titles', 68, 'title_en', '6d260301b956b9ff27c7962d7a0e574523638a527be5373e88d188284d5fd1cf', 'Keys to the Heart'),
('screen_titles', 69, 'title_en', 'eb1957252c39696928abf4ef5643acf9fdf76addf0709c6dbf39e44ad9c2c848', 'Lady Vengeance'),
('screen_titles', 70, 'title_en', '3c99ce3d4775969b8c093dcf246d37906e2aa03d9360e5b149bfc49573bab12d', 'The Handmaiden'),
('screen_titles', 71, 'title_en', '7fa7b244bdd2e9007d588db4543b10b61f8d0ee71499a55d6b558a1b885673ba', 'Thirst'),
('screen_titles', 83, 'title_en', 'ed0305fc5dacad37423f214e8901926fbdcd65825556f8619ea0537a7c499351', 'Detective Conan'),
('screen_titles', 84, 'title_en', '662fcc32bbc26dace4776c283a54996cb57375d8b19dfaed43ce494af60c9c8e', 'Nodame Cantabile'),
('screen_titles', 85, 'title_en', 'e6c171f253fa574710fcf93fcd6f19829049e09962f12b5de15a39c15b92153c', 'Piano Forest'),
('screen_titles', 90, 'title_en', '0cf28a2f6a7c90d5410c5d0c63bb9f74a1bed200e56948a2bfc015764766ec01', 'Legend of the Galactic Heroes'),
('screen_titles', 91, 'title_en', 'aaa944a33c78c3bac745cb901e776d84852857172124aa58641aa49d9878f6d9', 'Papa Rotti'),
('screen_titles', 92, 'title_en', '012dc90f7efc4f61db6b70897604292fcfe2c1bc29fc43e7397227d78d76443c', 'For Horowitz'),
('screen_titles', 93, 'title_en', 'ef3ea3fb627b456ae4ff28367fa579ef35e75fee2f53b97aca988cd00bf8dd3b', 'Harmony'),
('screen_titles', 94, 'title_en', 'c54c61f4804c69db7552e785fb76b1a7fbd5b7a5e15f3a6713f00cede67582dc', 'Four Hands'),
('screen_titles', 95, 'title_en', 'c4ba14f8589843961a3cdb833ff148d087d761ef104172818621b6fa7b2f08a8', 'Maestra: Strings of Truth'),
('pieces', 10, 'description_en', '2bde44a7422cc248c0cc2e03ba1fad3abdd4c09d18ebfbd552d4bd49827b6ab4', 'Known as "the Old Testament of music." A collection of preludes and fugues composed in all 24 major and minor keys. A monumental work exploring the possibilities of "well-tempered" tuning, which made every key usable.'),
('pieces', 12, 'description_en', 'f621a4926cde4f4a023d45bc2f175ffebd36e758957e27f47a513731203dab67', 'Called the "Bible" of solo cello music. It draws rich harmony and contrapuntal melody from a single instrument, the cello. Each suite consists of a prelude and several dances (allemande, courante, sarabande, gigue and others).'),
('pieces', 13, 'description_en', '8034bceb98a16fe7415312e24ee086dbdf9b1b13b2246dda8ead4dd3eb5fcdfa', 'The pinnacle of the solo violin repertoire. The "Chaconne" that closes Partita No. 2 in particular is regarded as one of the greatest violin works ever written as a single movement. The player must perform complex chords and counterpoint on just four strings.'),
('pieces', 14, 'description_en', '582cddf099240d9be34a84292da71bef4cbf53731d9e9ec402aea88a0e8c4982', 'A set of six concertos dedicated to the Margrave of Brandenburg. It is the supreme masterpiece of the concerto grosso style, in which varied groups of solo instruments contrast with the orchestra.'),
('pieces', 15, 'description_en', '1ac0a3b04766cc48199f599eff24a5dfc840685e16c87722a6ac420a46d8e179', 'A vast oratorio (sacred dramatic music) on the Passion and death of Jesus, based on the Gospel of Matthew in the New Testament. It is regarded as the greatest work of sacred music in Western music history.'),
('pieces', 16, 'description_en', '803df8ecfc2861d553f92d3ee4059d8346e911ff89298bc55e0650012c80a428', 'Famous for its overwhelming "Dum~ da-da-dum~" opening, it is the most popular of Bach''s organ works. It combines a dramatic toccata section (improvisatory in style) with a tightly constructed fugue section.'),
('pieces', 17, 'description_en', '137d3ed42f836195b1d774d6eb0b383aa61e4aa66d2af6a990b5cfdbf8a442e7', 'Monteverdi''s first opera, and the work regarded as the first great opera in music history. Based on the Greek myth of Orpheus, it portrays his journey to the underworld to win back his beloved wife, Euridice.'),
('pieces', 18, 'description_en', '5d25545aa3915e6b444613d0f880e35a4424f34221aaf5e1fab87415046957a1', 'A monumental sacred work that Monteverdi composed in applying for the post of music director at St Mark''s Basilica in Venice. It stands out for its grand scale, combining solo voices, chorus and orchestra, and for its dramatic expressiveness.'),
('pieces', 19, 'description_en', 'deb0bd72b045bbd86e13b0fc815985917b72856a3b32e5dafb275e0de18c4926', 'The most famous piece in Monteverdi''s Eighth Book of Madrigals, Madrigali guerrieri et amorosi ("Madrigals of War and Love"). It dramatizes the grief of an abandoned nymph through the contrast between a solo voice (soprano) and a male trio. The lamenting melody over a repeating bass line (ground bass) is especially striking.'),
('pieces', 20, 'description_en', 'a04eea8fae85d8e878ac53f3c5244ea6cb224d602045d6ecd0793f5cd4991c4b', 'Monteverdi''s last opera, in which his approach to operatic composition reached its peak. It deals with a historical episode that was radical for its time: the Roman emperor Nerone (Nero) and his lover Poppea commit all manner of wrongdoing for power, and she finally becomes empress. The duet "Pur ti miro, pur ti godo" ("I gaze at you, I delight in you") is famous.'),
('pieces', 21, 'description_en', '611f8f99f10c74f709a97050da572bec366cb0303f96d1407a495839d721b5db', 'Handel''s greatest sacred work and the best-known oratorio in history. It covers the life of Jesus (birth, Passion, resurrection), and the "Hallelujah" chorus in Part 2 is the most famous number.'),
('pieces', 22, 'description_en', '24ab944ce898a9dedb3fa542e7c695cf9578570d26ff8bac9f55b0a4d3de3544', 'An orchestral suite composed for a royal boating party on the River Thames in England. The "Alla Hornpipe" movement is especially famous, and the work is marked by a brilliant, lively mood.'),
('pieces', 23, 'description_en', '67f1c88ba2920e28c58aba82de8144410159e156977c8493aa1c23accb12d79f', 'Composed for a large fireworks display celebrating the end of the War of the Austrian Succession. Its majestic Overture is famous, and the work was originally designed to be played solely by a large number of wind and percussion instruments.'),
('pieces', 24, 'description_en', '6ace2f0235775db84b865fece3fa8165a9f5cb0f2d70da237f68a8e3d3e42c83', 'An aria from Rinaldo, Handel''s first opera to achieve great success in London. The heroine Almirena, taken captive, sings it as she laments her fate, and its sorrowful melody is very beautiful.'),
('pieces', 25, 'description_en', '5527a9090342ca28e3d78e9a7ce9e23437234ffacb9dc45e8e42b0bbfdbb0337', 'An aria sung by Serse (Xerxes), king of Persia, in admiration of the shade of a plane tree. Thanks to its peaceful, majestic melody, it is better known as "Handel''s Largo."'),
('pieces', 26, 'description_en', '4d8247d8fff3a6cba11c14ce83de45350c4aab375fd3e12f22750a292618dec6', 'A brilliant, majestic instrumental piece that opens Act 3 of the oratorio. It depicts the procession of the Queen of Sheba coming to visit King Solomon, and its festive character makes it a frequent choice at weddings and similar occasions.'),
('pieces', 27, 'description_en', '8fd012db6e3cdf32f00248335e8eb0d64027d30c85f4336955d3079325f308f3', 'The first of four anthems composed for the coronation of King George II of Great Britain. After the orchestra''s majestic introduction, the chorus bursts in with an overwhelming effect. It has since become a tradition to perform it at the coronation of every British monarch. (It is also the work on which the UEFA Champions League anthem is based.)'),
('pieces', 28, 'description_en', 'ef84e8619572158a45a77d402a66574c7d3d03b03547eb649470bb2fb6e06e5f', 'The first four concertos from Vivaldi''s collection of violin concertos Il cimento dell''armonia e dell''inventione ("The Contest Between Harmony and Invention"), Op. 8. A masterpiece of program music, it depicts the scenery and feeling of each season based on sonnets (poems).'),
('pieces', 29, 'description_en', 'cfeb56e30c504f9c16c750760bff9872304c85ec31413cad1cccdb9eec295a6a', 'A collection of 12 concertos. It includes various concertos for one, two and four violins, and was the breakthrough work that spread Vivaldi''s fame across Europe. Bach arranged six of them.'),
('pieces', 30, 'description_en', '6a1b2bb6f3b19892a56a7a1d9278a8f52361dea9f2aa8bfe7ecdcdd0d863ceac', 'Vivaldi''s most famous and most widely performed sacred vocal work. Composed for the choir and orchestra of the Pietà, a school for girls, it is a brilliant, festive piece in 12 movements.'),
('pieces', 31, 'description_en', 'a112e698f4bb94d0a45a93a6508cb58c6324be2615385c32084d9d175a68fde3', 'One of the two mandolin concertos Vivaldi composed. A lovely piece that showcases the mandolin''s clear, sparkling tremolo technique. The first movement is especially famous.'),
('pieces', 32, 'description_en', 'c1a75907b0c9648c5fe1fff5df8152d0e79d2637d66526321c227c4af3c7813b', 'A piece in which two trumpets compete brilliantly in virtuosity, with the bright, grand sound of the baroque trumpet (natural trumpet) as its charm.'),
('pieces', 33, 'description_en', 'bce1b173bfe884309ab25a2a9810f80028fe6bbeca92a790925602ed4732c838', 'The sixth concerto in L''estro armonico (Op. 3), and one of Vivaldi''s standard concertos, the one most frequently played by violin students. The vigorous rhythms of the first and third movements are striking.'),
('pieces', 34, 'description_en', '065ad5dc840920bef009437dbfdfd03d9f747af6ee495a6ccf0fbece7b29ada4', 'Purcell''s only through-composed opera and the supreme masterpiece of English opera. It portrays the tragic love between the Trojan hero Aeneas and Dido, queen of Carthage.'),
('pieces', 35, 'description_en', 'a53569ffc53ea23e360288fe4fcba26ab60c648c40060421f6241f8aa7598abe', 'The lament near the end of Dido and Aeneas, sung by Queen Dido as she faces death after being abandoned by Aeneas. The harrowing yet beautiful melody unfolding over a chromatically descending ground bass is its greatest strength.'),
('pieces', 36, 'description_en', '7f9e7e4f5c34d4297d70ca3231ab9d74e30a026a72503c8fb93861d3295dd4c5', 'A "semi-opera" (dramatic music that includes spoken dialogue and play) adapted from Shakespeare''s A Midsummer Night''s Dream. Though it has no direct connection to the plot of the original, a masque combining lavish music, dance and stage machinery is inserted at the end of each act.'),
('pieces', 37, 'description_en', '3a58c9752f5fabd8a4e116201a18dc1d393709f0c55e918bdc02cc04ba08d95b', 'Solemn, mournful music composed for the funeral of Queen Mary II, who had been fond of him. It is striking for its majestic trumpet and trombone fanfares and its chorus, and, ironically, it was also performed at Purcell''s own funeral a few months later.'),
('pieces', 38, 'description_en', '4ece985376047d5eac0b0909c032ff4c63a0560bf022ec5a5f10e03877c9b51a', 'Incidental music for the play of the same name. Its "Rondeau" movement became even more famous when the 20th-century composer Benjamin Britten used it as the theme of The Young Person''s Guide to the Orchestra.'),
('pieces', 39, 'description_en', '0d42b17e398a47f63e3d74902a76e8024057304fc8fd02cc1f9b710ad1ea97e2', 'Known by the nickname "Cortège" (procession) or "Promenade." It is characterized by a solemn, bright theme reminiscent of a fanfare, and seems to depict a splendid march at the Spanish court.'),
('pieces', 40, 'description_en', 'd9ccbc6a8c6bf5a69e137942c4dfe5faf4886b7a18712f00b2a971ab1c511dae', 'Famous under the nickname "La Caccia" (The Hunt), it is characterized by a cheerful, rhythmic theme that seems to imitate hunting horn calls. It is one of the most popular of Scarlatti''s sonatas.'),
('pieces', 41, 'description_en', 'dc68baa868d294e083de152d9aa44e27cf45058e18900898cb0b4a43df661563', 'One of Scarlatti''s best-known sonatas, creating a dreamy, meditative atmosphere. Its cross-hand technique, in which the hands cross over each other, is prominent, and it evokes the resonance of the Spanish guitar.'),
('pieces', 42, 'description_en', 'a8ed32a07b3a04e59ab1fa32bc48eb397d17e5cb8ffff43927f217a3eb81cdfb', 'A piece characterized by fierce tremolo (rapid repeated notes) and arpeggios that seem to imitate the "rasgueado" strumming technique of the Spanish guitar. It demands extreme virtuosity and is popular with pianists as a challenging piece of repertoire.'),
('pieces', 43, 'description_en', '57ef23ed3afb968f627e78652c8f89d58d3f744e07e15ecf80c2d30c29fb51e6', 'Together with Kk. 27, it is counted among Scarlatti''s most lyrical and introspective sonatas. It is marked by a plaintive, beautiful melody and even hints at Romantic sensibility.'),
('pieces', 44, 'description_en', '52e238e6d96955a66f747c160e1eb9e448f430e265d0585a637117683913078a', 'A sonata often called by the nickname "Pastorale." It is marked by a lyrical, peaceful melody, and is popular as one of Scarlatti''s relatively accessible yet beautiful sonatas.'),
('pieces', 45, 'description_en', 'c0d6a7324f7b8892e5689dc07eeb6304301b6cda3eb27dd81a7225eb7b9258e7', 'Number 1 in the Kirkpatrick catalogue and the first piece in the first collection of sonata exercises that Scarlatti published in 1738 (Essercizi per Gravicembalo). An elegant, well-ordered piece showing his early style.'),
('pieces', 46, 'description_en', 'edd486a009e58d4419bd4ac3427394513c1f81c51b0e0c5dc7fea0d533e41808', 'Rameau''s most famous opéra-ballet. It strings together four different "exotic" stories (Turkey, Peru, Persia, America) in an omnibus format. The "Danse des Sauvages" in Act 4 is especially famous.'),
('pieces', 47, 'description_en', 'e6671fb77b039f5ecd9ff24b912f08ba0178e646d7d44fc99980e9f0ba79e5b0', 'A piece from his second book of harpsichord pieces (1724). A lively, light dance that imitates the rhythm of the tambourin, a small Provençal drum. It is one of the best-known works among Rameau''s keyboard pieces.'),
('pieces', 48, 'description_en', 'e8fed85022c78be8d6135e5b7baa38aa441a00635b1873e7cabd7fa6675eadf0', 'The closing piece of the A minor suite in the Nouvelles suites de pièces de clavecin ("New Suites of Harpsichord Pieces"), published around 1728. It consists of an elegant gavotte theme followed by six brilliant, virtuosic variations (doubles).'),
('pieces', 49, 'description_en', '9662d9179e061e14566a007aa009bf65c0c38981a0e6e3e743ff560ee6b9039d', 'A piece in the G major suite of the Nouvelles suites de pièces de clavecin. A masterpiece of the "character piece" (descriptive miniature), it depicts the clucking and movements of a hen on the keyboard in a playful, finely crafted way.'),
('pieces', 50, 'description_en', 'd894cde352db4d73b21aaf3823999848e2ddc72cd40bb82cf91f9b46c9da73ff', 'Rameau''s representative tragédie en musique (lyric tragedy), counted among the greatest of his operas. It deals with the brotherly affection and love of the twin brothers Castor (a mortal) and Pollux (an immortal).'),
('pieces', 51, 'description_en', '34262ad0c28b444aaac4a4b6bc956d0fc9b8233cd1a2de0cde51cd2b431db6fe', 'Rameau''s shocking first opera, presented when he was 50. It is based on Racine''s tragedy Phèdre. To audiences accustomed to the music of Lully, Rameau''s bold harmony and orchestration came as a shock, and this controversial masterpiece set off the "Lullistes versus Ramistes" dispute.'),
('pieces', 52, 'description_en', '85db9341a0c68f060ab40f2ff08d0ef557e0123bff039e6d0bc7dd075376dcf8', 'The title means "table music." A large collection of instrumental music published by Telemann, it is organized into three "Productions," each containing an overture, a concerto, a quartet, a trio, a solo sonata and more, like a variety gift set.'),
('pieces', 53, 'description_en', '59c40dfd2b3640c0906e8b19e34857c946183f35f28b517f318ed265a3fbb553', 'Regarded as one of the very first full-fledged solo viola concertos in history, and a very important work. It makes good use of the viola''s warm, elegant tone and is now core repertoire for every viola major.'),
('pieces', 54, 'description_en', 'a7d9de314d6e3c28937174b7bd032cefd2b438b08542e3059f44e312a5b03fac', 'A concerto-like suite for alto recorder (or flute). It consists of a French overture and various dances, and the final "Air à l''Italien" movement and the "Polonoise" are especially famous.'),
('pieces', 55, 'description_en', '1da0568c0b98802cf9fac56c2d1f00165583e32bb12a06963fdc65cb43417ef3', 'A programmatic suite for string ensemble depicting scenes from Cervantes''s novel Don Quixote. Witty depictions such as "The Fight with the Windmills" and "Sancho''s Donkey" stand out.'),
('pieces', 56, 'description_en', '6d9ca19c65b23c030bf220512207f23e03bfb8d47330078f1e4d2aacd731266d', 'A set of 12 quartets that Telemann composed around his visit to Paris in the 1730s. Scored for flute, violin, viola da gamba (or cello) and harpsichord, they are counted as masterpieces of chamber music in which French and Italian styles are exquisitely blended.'),
('pieces', 57, 'description_en', '3f48dba4a6e5ae628f487c42a1bf954d4aa25074aa044e4cd6885d5637e99eb8', 'Corelli''s most famous work, the eighth of the 12 concerti grossi in his Op. 6 collection. It bears a note that it was composed for Christmas night, and the peaceful, beautiful melody of the final movement, the "Pastorale," is especially famous.'),
('pieces', 58, 'description_en', '8c21f98bd8576021fd843de05368eb7e37897b919bf2667154e3222e26b42c86', 'The last of the 12 sonatas in Corelli''s Op. 5 collection of violin sonatas. It consists of 23 brilliant variations on the melody of "La Folia," a dance tune popular at the time. It is the work in which Corelli''s violin technique reaches its peak, and is regarded as the most representative example of "La Folia" variations.'),
('pieces', 59, 'description_en', '31bdc0a1b9625e2554a3716cc11d5693bbb7ad890fdb9ebba2d323600a5561ff', 'Corelli''s last collection, the culmination of his career. It shows the peak of the concerto grosso style, in which a small group of two violins and cello (the concertino) contrasts with the full orchestra (ripieno, or tutti). The "Christmas Concerto" is included.'),
('pieces', 60, 'description_en', '249fd05147e5a5fcb77276230819ff86794cd4dc480a7dee0b65055fe1f6a413', 'The most famous of Corelli''s trio sonata collections. Scored for two violins, cello and organ (basso continuo). A model of the "sonata da chiesa" (church sonata), it established the four-movement layout (slow-fast-slow-fast) and is marked by a serious, solemn mood.'),
('pieces', 61, 'description_en', '69bb720d39aa51eacfc470415d53d54ce198a3083b04819789c4dde129401b70', 'The most important and best-known work in which Gluck''s "opera reform" was first applied. It eliminates the needless displays of virtuosity of traditional opera seria (da capo arias) and is composed so that the music serves the drama. It deals with the Greek myth of Orpheus.'),
('pieces', 62, 'description_en', '1ee49e120ba19126bfedd373ae2f38b8be7628d42c918b7da1c5759169d0be68', 'A famous ballet piece from Act 2 of the opera above. It depicts the dance of the spirits when Orfeo arrives in Elysium, the paradise. The clear, beautiful flute melody is so famous that the piece is often performed on its own.'),
('pieces', 63, 'description_en', '35f186f6ebc4184bb1e2be0a5be9caff177845a1a4a006a729fd09bad3425472', 'In Act 3 of the opera above, a despairing aria sung by Orfeo, who loses his wife Euridice a second time after breaking the taboo by looking back at her. It is famous for a tragic and beautiful melody that concentrates Gluck''s "noble simplicity."'),
('pieces', 64, 'description_en', '68242b9b56e5c04e1c7a57f10a6de49129eab39f97935662bba878860f97db9c', 'Gluck''s second reform opera, following Orfeo. It deals with the noble sacrifice of Queen Alceste, who resolves to die in place of her husband, King Admetus. The preface to this opera is very famous as a manifesto setting out Gluck''s ideals of "opera reform."'),
('pieces', 65, 'description_en', 'cd22f386a1432f2189f0a54de6bb3b67f7c427e90e14da7d8b039b60518e200c', 'Regarded as the greatest masterpiece among Gluck''s reform operas. Composed in Paris and based on Greek tragedy, it achieves dramatic tension and musical unity close to perfection.'),
('pieces', 66, 'description_en', '91c0a5c95aaded68b0b192c405a41946fe9df6ec46d904826f771c3c8bcbd4f0', 'One of Mozart''s best-known instrumental works. The title means "a little serenade," and it is characterized by a light, elegant melody. The first movement is especially famous.'),
('pieces', 67, 'description_en', 'a668ccb6a3724a6e34f566e8f9bcc8c688f3ad2085690d8c5649e17a60b2640c', 'One of Mozart''s three great symphonies, famous for the tragic yet passionate theme of its first movement. A masterpiece that hints at Romantic sensibility.'),
('pieces', 68, 'description_en', '1105e3202b786ea8af20ffd050b8b9488e843d5e187873db7ff955a6237be8fe', 'Mozart''s last symphony. The pinnacle of the classical symphony, it is most remarkable for the brilliant, majestic fugal writing in the fourth and final movement.'),
('pieces', 69, 'description_en', '2cb6f763ece421351bc4fe5394e8327c9639ff93882777c4cd8357a4bf28c00d', 'A comic opera (opera buffa) of genius, ahead of its time. It cheerfully portrays the wit of the servant Figaro, who stands up to the privileges of the nobility (the "right of the first night"). From the famous overture on, every aria is counted a masterpiece.'),
('pieces', 70, 'description_en', '34164929a9f75132e66e946158f1e94596b60f65fd162038e9596153baf1fcb7', 'Mozart''s last opera, completed shortly before his death. A German-language Singspiel, it is a fairy-tale-like, philosophical work embodying Freemason ideas. The "Queen of the Night aria" is famous.'),
('pieces', 71, 'description_en', 'ebb194ea941783628f8d63dcadd379142dac8cd4428b5d7f058e46b91a5379be', 'Mozart''s unfinished posthumous work. A requiem mass commissioned by an unidentified patron, it is said by legend that he composed it with a premonition of his own death. His pupil Süssmayr completed it.'),
('pieces', 72, 'description_en', 'dd988fff69d3df55bb1bb03829b1a6dd4c7bfb7ced8333e309d9184dca0e7191', 'One of Mozart''s most dramatic and Romantic piano concertos. Beethoven was especially fond of it and even composed cadenzas for it himself.'),
('pieces', 73, 'description_en', 'def37aaf627ec36e08db469528ba35b4e2a7240da8d1cfb309bed88045ea3ef9', 'The third movement, the "Rondo alla Turca" (Turkish-style rondo), is so famous that the sonata is known by the nickname "Turkish March." It is also popular with piano students.'),
('pieces', 74, 'description_en', 'c70e9e441e59c4449db3e88880c339ad6a36226738a6c8e29e9cb124054bbeb6', 'The last concerto Mozart completed. A masterpiece that expresses the beauty of the clarinet to the utmost, it is known especially for its second-movement Adagio.'),
('pieces', 75, 'description_en', '98c9247daa78d4de303aafa58dd247f0ddbd351fb68b695aa046ead44c6cea87', 'The best-known symphony in Western music history, opening with the famous "Da-da-da-DUM~" motif. It shows in compressed form Beethoven''s musical world of "through suffering to joy."'),
('pieces', 76, 'description_en', '8e465f5b89d4383937c1bf4782e0400019c814ad5737d7f0a5bac3e07ebf9fa7', 'Beethoven''s last symphony. A revolutionary work that was the first to bring a vocal chorus (Schiller''s "Ode to Joy") into its fourth movement. It carries a message of humanity and harmony.'),
('pieces', 77, 'description_en', '9aae2aa84abc29aa8c63681409b51e3cbcc011ca677c9ecd9e17606491d9bd2a', 'Famous for the anecdote that Beethoven originally intended to dedicate it to Napoleon but, enraged when Napoleon proclaimed himself emperor, tore up the dedication. A work of vast scale that broke the framework of the classical symphony.'),
('pieces', 78, 'description_en', '95d1119e356cf97dcd2e4ad78d8b3e7bd68f3f4796bd6556a37507b4a1b89fc3', 'Beethoven''s best-known piano sonata. The dreamy first movement is especially famous, and the nickname "Moonlight" was given after Beethoven''s death by the poet Rellstab.'),
('pieces', 79, 'description_en', '509be8ee7e827ecd0eb5a58c3a24491c56cca229838c114dcad5c040589adff1', 'A masterpiece among Beethoven''s early sonatas. It won great popularity for its tragic yet majestic introduction to the first movement and its passionate melodies.'),
('pieces', 80, 'description_en', '1cd233a03718f975ab921c02912dabee60a1ee3c014b7221bf6fc2bad6a2950d', 'Beethoven''s last piano concerto. Characterized by a grand scale on a par with a symphony and brilliant piano virtuosity, it shows a majesty fitting its nickname, "Emperor."'),
('pieces', 81, 'description_en', '6a562f85f01e1243c32248d2c82832fe8c3a7b4618413c4fc04b40c59784693a', 'Beethoven''s only violin concerto. Together with the concertos of Mendelssohn and Brahms, it is counted among the three great violin concertos, and has a grand, noble beauty.'),
('pieces', 82, 'description_en', '8498586212e839c72ecda34ac081e7f1ae9d1ac74b6d5041a26465d5f21a0e93', 'The most famous piano piece in the world among the bagatelles (short pieces) Beethoven left behind. Who "Elise" was remains a matter of debate.'),
('pieces', 83, 'description_en', '198c571c08b3ca22e7d09305cb4ab947fe04967ae704a56f9c5f35856ca9b22d', 'One of Haydn''s "London" symphonies. Famous for the anecdote that, in the quietly played second movement, a sudden loud chord (timpani and all the instruments) bursts out to startle the audience.'),
('pieces', 84, 'description_en', '35c248318a1d3fbfd962d60e75fb8f0d9dc20de9e632934af731f628ad30837d', 'In the second movement, the bassoon and strings rhythmically depict the "tick-tock" of a clock pendulum, which earned the symphony the nickname "The Clock."'),
('pieces', 85, 'description_en', 'b930ddc59d94fc09e01e93f2ad7d2a8152f666cc36fee7d840d628b8a1b6e269', 'A witty piece Haydn composed for the musicians who had not been granted leave. It is famous for the performance in the fourth and final movement in which the players put out their candles one by one and leave the stage.'),
('pieces', 86, 'description_en', 'ffd3bd527eae733ea0920eae6047ff308de6bcb45e3ee56763c3c1cab1f170d6', 'The second movement is a set of variations on the melody Haydn composed as the Austrian national anthem (the "Emperor''s Hymn"). The melody later became that of the German national anthem.'),
('pieces', 87, 'description_en', '07a9c01e454e946b4faa88328a747387955ab07fa31dea69ac3b731fb1bdfcf6', 'One of Haydn''s greatest masterpieces. Composed after he was deeply impressed by Handel''s Messiah, it depicts the seven days of creation in the Old Testament in grand and vivid fashion.'),
('pieces', 88, 'description_en', 'c24cbf5d22e7294d68a63e613dbb91894b83acdbab99e83300495e06f9b6789e', 'The first great concerto composed for the newly invented keyed trumpet. It shows both the brilliant virtuosity and the lyricism of the trumpet, and is standard repertoire for trumpeters.'),
('pieces', 89, 'description_en', '8dc5d8cb2e038794bc021def91f933b2b543a133d9e896cb6c2227846297e891', 'It began as a collaboration with Gluck, but Salieri completed it when Gluck''s health declined. It was a great success in Paris and earned Salieri recognition as the successor to Gluck''s "opera reform."'),
('pieces', 90, 'description_en', '4aedb488ff534ff64b985b57873bcb7f725fa504fe356442726449bb296d7df4', 'Composed to a libretto by Beaumarchais (author of the original play The Marriage of Figaro), it is one of Salieri''s most ambitious operas. It was a great success in Paris just before the French Revolution.'),
('pieces', 91, 'description_en', '6c88ba8290b9513c417d69700f216d626564fc970f40ff9d6e77f6bd5fff417f', 'A comic opera based on Shakespeare''s The Merry Wives of Windsor. (It is a different work from the opera of the same name later composed by Verdi.)'),
('pieces', 92, 'description_en', '8d8f60710d2ebb4b5a76f46a2f861d51574925a8b4d6a04963e029467736e0d9', 'Salieri''s best-known and liveliest symphony. It shows his side as an instrumental composer.'),
('pieces', 93, 'description_en', '778c49de49dec56ac0d392eb8c5d8cfbd7b69d318b6af3158628ef4532c52e40', 'A collection of études known in Korea as "Czerny 30." It consists of essential études for completing basic piano technique.'),
('pieces', 94, 'description_en', '651cba97e0deaf21c4dbb1f36a1a6241e3f2d014f90f5fc9842f100ab2041b24', 'Called "Czerny 40" in Korea. A collection of 40 études for training speed (velocity) and technique at a higher level than Czerny 30.'),
('pieces', 95, 'description_en', 'db5cb11d4e9562e473ff6049ef6ac3bd43f596735f451524e0ee619259316a63', 'Called "Czerny 50" in Korea. An advanced collection of études that gathers nearly every kind of brilliant technique a pianist needs.'),
('pieces', 96, 'description_en', 'd5e346da83ba73fd2adb9864db36fb45e2855353f86b5d1b4e163a2048c2d49a', 'Called "Czerny 100" in Korea, it is one of the first collections of études that beginning pianists encounter.'),
('pieces', 97, 'description_en', 'd45fd66a6c8cbf797d5e2d6a6f82846e1db85b6e3b1bc74730a1846c2ddc0a8a', 'A witty symphony in which toy instruments such as the cuckoo, trumpet and drum play along with the orchestra. (For a long time it was mistakenly attributed to Haydn.)'),
('pieces', 98, 'description_en', 'b0e9ead4821de9829cee6a982218442ab61c3f1876002f864f3e9e7bff4f4b98', 'A trumpet concerto showing the transitional style between the Baroque and the Classical. The slow melody of the second movement is famous.'),
('pieces', 99, 'description_en', '6eab8658dd43bf9f7ade637c1f4f0875bb855d3e6fc3a0b53adc0397c59f5380', 'A concerto that features the alto trombone, uncommon at the time, as its solo instrument. Today it is important repertoire for trombonists.'),
('pieces', 100, 'description_en', 'a7b371b9ed365cdde5d8d33cb96e950b32f6cb0033dd00cf0fc2add85061a495', 'The most famous piece among all of Boccherini''s works. Because of its elegant, lyrical melody, it has been widely used in films and commercials.'),
('pieces', 101, 'description_en', 'fd1fd75c3c317fc9e9c336a468c604076c87fdaf470438ff7b1e97c430c79b34', 'The most famous of Boccherini''s cello concertos. (However, what is played today is often the version arranged by the 19th-century cellist Grützmacher.)'),
('pieces', 102, 'description_en', 'c337f6ba239fba1fab33179702798104edb980b6290eea5b0dc1f47032a88537', 'A lively chamber work composed by Boccherini, who worked at the Spanish court, using the rhythm of the Spanish dance, the fandango.'),
('pieces', 103, 'description_en', 'aa4ce65179ef7bca4964db58a91a173806b5c49686bb5b52ea6635f3e731bdba', 'C.P.E. Bach''s best-known short piece for piano (clavier). A technical étude in which the two hands cross rapidly while playing arpeggios.'),
('pieces', 104, 'description_en', '99ca892669dac4ad3c8130f41bc4aac6ec90754533674aeec54a7580af688082', 'A concerto that shows well the sharp contrasts of intense emotion characteristic of the Empfindsamer Stil (the "sensitive style"). Baroque rhythmic drive and Classical drama coexist.'),
('pieces', 105, 'description_en', 'a99acb5bcfea73b2ef8732f013899404710b7811db687c2613d3b843e8aa2bb9', 'C.P.E. Bach''s representative flute concerto. Although the influence of his father, J.S. Bach, can be felt, the Sturm und Drang-like intensity stands out.'),
('pieces', 106, 'description_en', '3e6baa72407c3a6de3b047962f9d64b600179b40c726f5306874f285d08bbd84', 'A representative vocal work that carries on J.S. Bach''s majestic sacred music while adding Classical clarity and dramatic expression.'),
('pieces', 107, 'description_en', 'cf33807449e98bba012022979b4f2caf9005ed2b94f0a03af60b5d1f9fc683a5', 'A symphony in the elegant, light galant style, worthy of "the London Bach." It is also known as the overture to Mozart''s opera Lucio Silla.'),
('pieces', 108, 'description_en', 'cf4038614059d3b320ad388afad4a0be6d7896ef156a6982a989c0f82e473b8b', 'A sinfonia concertante in which two violins and a cello blend with the orchestra. The young Mozart was influenced by this genre.'),
('pieces', 109, 'description_en', '7f05132774ebde94331fffd24447b5347a286a8b32fc24efed8e8b15b827fd7b', 'Long known as a work by J.C. Bach and widely performed, it was revealed to be a forgery by the 20th-century French cellist Henri Casadesus. Even so, it remains a popular piece of viola repertoire.'),
('pieces', 110, 'description_en', 'e9f03659a60d8a3171cae04110f460703380a0edf8cfb49227a96502a1bbab1e', 'One of the first great concertos for the clarinet. It displays the clarinet''s virtuosity and lyricism brilliantly, and clearly shows the style of the Mannheim school.'),
('pieces', 111, 'description_en', 'ed90087af9b57f9316fcc7565fa7ebc2d51dd00f6e5fd80289a351efb5d93850', 'A masterpiece among early symphonies, clearly showing the "Mannheim crescendo" (a gradually growing sound) and the "Mannheim rocket" (a rising arpeggio), hallmarks of Stamitz and the Mannheim school.'),
('pieces', 112, 'description_en', 'fe2c7faf15363f0be7e99d5eae229457aa1fe8798a0c69532615bc99193a3d1f', 'A trumpet concerto composed before Haydn''s. Although Baroque influence remains, the lively Classical energy stands out.'),
('pieces', 113, 'description_en', '7305aea72c0f9ea67bfa727a3c1228f18ed6eeb16a1251716c8261f476051800', 'Study material that piano students around the world work through before Czerny. These are the most widely used pieces for learning Classical formal beauty and basic piano technique.'),
('pieces', 114, 'description_en', '777ce412478387cfddbab9562fb7252ef1b444cc6db813c9a207641ac2799744', 'A collection of 100 études whose title means "Steps to Parnassus (the heaven of music)." A textbook of modern piano technique, it was even parodied by Debussy.'),
('pieces', 115, 'description_en', 'c1b64a162bbef824d435329a598ed41795713ee75158f9081a6632d325dd2aad', 'Clementi''s most dramatic and Romantic sonata. A programmatic work depicting the tragedy of the abandoned Dido in Virgil''s epic poem.'),
('pieces', 116, 'description_en', '3abbec77279bd23920f28e314153a04e2c581648a184e51659d935ad825f4e5b', 'A song cycle of 24 songs that Schubert composed shortly before his death. It portrays the despair of a young man who, having failed in love, wanders through a snowstorm, and is the summit of German song.'),
('pieces', 117, 'description_en', '486bd83091f2842e930fcf66b1a6cff639458e25b1301ab7d29f6be4a34c8961', 'A song of genius that Schubert composed at the age of 18. Based on a poem by Goethe, it has a single singer act four voices (the narrator, the father, the son and the Erlking), while the piano depicts the sound of galloping hooves.'),
('pieces', 118, 'description_en', 'a6f6878e1942e8477bd220c9a10ad162e0357b5bc2048986fc25b15ce2818bb2', 'A chamber work that uses the melody of his own song "Die Forelle" ("The Trout") as the theme of a set of variations in the fourth movement. The scoring of piano and string quartet is unusual (a double bass is included), and the mood is bright and cheerful.'),
('pieces', 119, 'description_en', '11664c18283b1e56c2321f740c11f04aa40b982d5da4816d68c810bacfced9cd', 'Schubert''s best-known symphony. Although only two movements were completed, it is regarded as a perfect masterpiece in itself. It announced the beginning of the Romantic symphony.'),
('pieces', 120, 'description_en', '67ccd3e7f53805f62073b07b43a6f867e963e711ae5ddfc50641ef9c43491671', 'It uses the melody of his own song "Death and the Maiden" as the theme of the variations in the second movement. A masterpiece showing the most dramatic and intense tragic beauty among Schubert''s chamber music.'),
('pieces', 121, 'description_en', '46c638299c86da3f347c998eb5a693a4dca51f04f2f9aa18adf088474dc30e0e', 'The best-known collection of Schubert''s short piano pieces. It consists of four pieces and is especially famous for the lyrical melody of No. 3 in G♭ major.'),
('pieces', 122, 'description_en', 'b4b23295921bc3b79136239109b65a03b2a638a0a509a47caba1e244bdd6c0a0', 'Together with the concertos of Beethoven and Brahms, it is counted among the three great Romantic violin concertos. Its innovative structure has the solo violin play the theme right at the start of the first movement.'),
('pieces', 123, 'description_en', 'a03486ff97039719bdec69067d6999f7f6087f57b7e1ab1b645a31cf5b6ea13d', 'Music for Shakespeare''s comedy. It consists of the overture (Op. 21) composed at age 17 and the incidental music (Op. 61) added later. The "Wedding March" in particular is world-famous.'),
('pieces', 124, 'description_en', 'afa5a8eff302c2a35e150c88b07d1fbbe56d0edb8b70227c12a5263d686f9961', 'A symphony composed with inspiration from Mendelssohn''s travels in Italy. The first movement, which evokes dazzling sunshine and blue skies, and the fiery fourth movement, a "saltarello" (an Italian dance), are famous.'),
('pieces', 125, 'description_en', 'ba913c55955fba1b0e90c4cb5d3ffee346e5ff6ef57aa83d779555ed411499f9', 'A collection of piano pieces whose title means "songs without words." Made up of eight books (Opp. 19b, 30, 38, 53, 62, 67, 85, 102), it includes the well-known "Spring Song" and "Venetian Gondola Song."'),
('pieces', 126, 'description_en', '803739c351f219abbedca8043edb678b15ba7b8a3126a962718c1362e1d1c728', 'A concert overture composed during a trip to the Hebrides islands of Scotland, inspired by Fingal''s Cave, where the waves crash. A masterpiece of program music, outstanding in its depiction of scenery.'),
('pieces', 127, 'description_en', '5edb65b132fe5ec43cf9505f139de82c8bce910548291863d2b6ceb619255d9b', 'Famous for the anecdote that Chopin composed it in a fury on hearing that his homeland, Poland, had been occupied by Russia. It is characterized by fierce arpeggios in the left hand.'),
('pieces', 128, 'description_en', 'b3b1eb5b8f3c5e471393d7ab703724f5da77ebcc59bbe34be24f50a8448b9e56', 'One of the most popular of Chopin''s piano pieces. The fierce opening and closing sections contrast dramatically with the middle section, which stands out for its sweet lyricism.'),
('pieces', 129, 'description_en', '211d8ddfeedc0c1d833e897bcf081a66cf98877981664ee2e7d05bef5918185f', 'The first work in which Chopin elevated the "ballade" genre into a piano solo piece. With its epic, dramatic development, it is counted among Chopin''s greatest masterpieces.'),
('pieces', 130, 'description_en', 'edc6d9e308c6cc55022ac5c154cbf6d314eff4309f1aafcf4c7f1fbeed12d5f6', 'A work that expands the polonaise, a Polish folk dance, to a majestic, heroic symphonic scale. It shows Chopin''s patriotism and spirit.'),
('pieces', 131, 'description_en', '50eac37418816096a0c04c03eeb61168b35fa9fec818c409a90be5432346c3b2', 'The best-known of Chopin''s nocturnes. Characterized by a sweet, lyrical melody, it has been used in numerous films and dramas.'),
('pieces', 132, 'description_en', '33ff15b47b812822b700fdef29f79b8b99842525796d2321f3e5de0ab305476a', 'Composed just before Chopin left his homeland, Poland. The orchestra is judged somewhat thin, but the poetic beauty and brilliance of the piano part are overwhelming.'),
('pieces', 133, 'description_en', '1c539729ed2715496774a6bd954d3fe94b64516f83ed399db81aecdd5a1a585c', 'The anecdote goes that Chopin composed it after watching his dog chase its own tail. It is also called the "Minute" Waltz, but it is very difficult to play in under a minute.'),
('pieces', 134, 'description_en', '9feec2893d82fc2bf11ce490a8362c109bb2f5c32e0f67bccd7b9e596f2bc3cd', 'A representative song cycle composed in 1840, Schumann''s "year of song," when he married Clara. Based on poems by Heine, it portrays the joy and anguish of love and the pain of heartbreak.'),
('pieces', 135, 'description_en', '57315176f0a837c56a9c89e6e3d06751c6801761ba95d59abd412b3700f3877e', 'A suite of 13 short piano pieces written in remembrance of childhood. It is a work for adults. No. 7, "Träumerei" (Dreaming), is very famous.'),
('pieces', 136, 'description_en', 'c1d67a7eaa967eff1bb42d5827796ee9cc5517dcdceb0ae1f24f92e77beb244b', 'A masterpiece of the Romantic piano concerto. The orchestra and piano fuse as closely as in a symphony, and Schumann''s passion and lyricism are in harmony.'),
('pieces', 137, 'description_en', 'd3ecafcd03763ab9996b7321d20dde3258227c60e1091fbf774802bd1547e0d9', 'A symphony Schumann composed with inspiration from the scenery of the Rhine and the grandeur of Cologne Cathedral. Its five-movement structure is unusual, and it is full of Romantic vitality.'),
('pieces', 138, 'description_en', 'af5bcfcd22be0860bd287fbde4fed3e6284e152f0e7ad7f106961cadbeaa5169', 'A suite of 21 character pieces depicting in music the figures at a masked ball (carnival), such as Pierrot and Harlequin, as well as Schumann''s own inner selves (Florestan and Eusebius), Chopin, Paganini and others.'),
('pieces', 139, 'description_en', '0689536d9aa81949b5cb02b2b6c1181e221cd581acbc9368c46f5dd4b90d10a1', 'One of Liszt''s most beloved piano pieces, ranking alongside Chopin''s nocturnes in popularity. Originally composed as a song and arranged for solo piano, it is characterized by its sweet melody.'),
('pieces', 140, 'description_en', '34bc88177df6bdbbd8f7ca0cc8e5a061670d3a7dc2f621090cf795d1be1f2fa2', 'A piano étude based on the theme of "La Campanella" ("The Bell"), the third movement of Paganini''s Violin Concerto No. 2. It is characterized by brilliant high-register technique that imitates the sound of bells.'),
('pieces', 141, 'description_en', '62136f31b56597c80bf10daca6512e5dee1f0e356384430d7f3c77d7ddff4784', 'The most famous of Liszt''s 19 Hungarian Rhapsodies. The contrast between the improvisatory opening of Gypsy (Romani) music (the lassan) and the fiercely accelerating second half (the friska) is striking.'),
('pieces', 142, 'description_en', 'ddf5a849e332534ddda3f6b5a1578b4e55c5357d7ff741e9103c012037cb461d', 'The representative work of the "symphonic poem" genre that Liszt created. Based on Lamartine''s poem that sees life as a prelude to death, it depicts various facets of life (love, struggle, triumph and more).'),
('pieces', 143, 'description_en', 'ad6e00e3d28b385be0b9cb0691417309714c5dce513682153aead0de2c17b3f8', 'One of the 12 études that show Liszt''s superhuman technique. A fierce, heroic piece depicting the hero Mazeppa as he gallops across the wilderness tied to a horse.'),
('pieces', 144, 'description_en', '21863415a06c8d8ca6bc8df784950e0ab3e055f827fbaf77e3c40351b98840a4', 'The opening of Act 3 of Die Walküre, the second opera of the four-part Ring of the Nibelung cycle. It gained overwhelming recognition after its use in the film Apocalypse Now.'),
('pieces', 145, 'description_en', 'e324204600380886e4934f03220faeea9f8137c6761e774012e197dc6e3d1caf', 'A revolutionary opera that changed the course of Western music history. Through an ambiguous harmony known as the "Tristan chord," it expresses the longing of unresolved love and heralded the breakdown of tonality.'),
('pieces', 146, 'description_en', '5bf6084757e663a0fedd5ef519e9e49049b263adb31c3601b6433b463aa4fa07', 'The "wedding march" from Act 3, which, along with Mendelssohn''s wedding march, is the piece most used at wedding ceremonies around the world today.'),
('pieces', 147, 'description_en', '42a6c967e33489611612c0757b16c2ba2416d2a5a8f7cecedf1f26252151c9e5', 'A masterpiece among Wagner''s early Romantic operas. A brilliant overture in which the devout theme represented by the "Pilgrims'' Chorus" contrasts with the sensual theme of the "Venusberg."'),
('pieces', 148, 'description_en', '0d8389472ae107eef4d41bfa4a3c2755cf4b2ec66a6d99139de426f12d276e6b', 'Verdi''s most famous and beloved opera. It portrays the tragic love between Violetta, a woman of Parisian society, and the naive young Alfredo. The Brindisi (Drinking Song) and other numbers are famous.'),
('pieces', 149, 'description_en', '8821b6bdb83b7265806b80589b1e01def1214fa577ef5e72b7bc1185c8ed7fde', 'One of the three great masterpieces of Verdi''s middle period. It portrays the tragedy of the hunchbacked jester Rigoletto. The aria "La donna è mobile" is world-famous.'),
('pieces', 150, 'description_en', 'd06e4c17b7da58f4c0e7f7c425018dfff0acf78132517e96b6418a53252b7371', 'A spectacular opera composed to commemorate the opening of the Suez Canal. Set in ancient Egypt, it portrays the tragic love between Aida, princess of the enemy nation Ethiopia, and the Egyptian general Radamès. The "Triumphal March" is famous.'),
('pieces', 151, 'description_en', '1e5166ad71441e3ea94586e56c9424696f162fe1139f23b30865f093423da7ed', 'A chorus sung by Hebrew slaves taken captive in Babylon as they long for their homeland. Called a "second national anthem" by Italians, who were then under Austrian rule, it made Verdi a national hero.'),
('pieces', 152, 'description_en', '053fe3f2f1b25a6ed73b57a89f082e4424dc632aeb0aac5b3ee8cd980034858b', 'A requiem mass that Verdi composed in memory of the great writer Manzoni, whom he revered. Although it is sacred music, it is characterized by "operatic" fierce drama and emotional expression, and the "Dies Irae" section is especially overwhelming.'),
('pieces', 153, 'description_en', '34f3e81dbc680f9aaa9e7f555fa045b6253b54a953f63b51fa2e040c64329525', 'Brahms''s first symphony, which he labored over for more than 20 years. It inherits the "struggle and triumph" design, from C minor to C major, that resembles Beethoven''s Ninth Symphony, and was praised as "Beethoven''s Tenth Symphony."'),
('pieces', 154, 'description_en', 'c88b1148c706838dc9d589bc08e96fc3c25a82855dc3ec539b4030a48a57bff6', 'Brahms''s most lyrical and Romantic symphony. The wistful melody of the third movement, "Poco allegretto," is very famous and is often used in films and dramas.'),
('pieces', 155, 'description_en', 'b4edcc9051311127826836f14be24bdc2175656edf6841ae6d5fdba8a7c5e899', 'The best-known of Brahms''s 21 Hungarian Dances (originally for piano four hands). It is characterized by fierce Gypsy-style rhythms and a wistful melody.'),
('pieces', 156, 'description_en', 'e2d413b3ea6016829f447e5a48adcf1cfa173437e2a657210048a03b663b2e47', 'Together with Beethoven''s concerto, it is counted as one of the two great peaks of the Romantic violin concerto. It is characterized by a symphonic, grand scale and a masculine breadth.'),
('pieces', 157, 'description_en', 'fe98145e3681a39ebd70fe740479a5d4287f5c590f1fb62d45b343738a105cd0', 'Not the traditional Latin requiem (mass for the dead), but a requiem "to comfort the living," set to German texts that Brahms himself selected from the Luther Bible.'),
('pieces', 158, 'description_en', 'b4d9eba7c21accb3e9864a9a48c13f83df6e04641a07b510ac3914dcdc62ec46', 'Tchaikovsky''s last symphony and his greatest masterpiece. Its radical structure ends not with the traditional "joyful" finale but with an utterly despairing, sorrowful Adagio (slow movement).'),
('pieces', 159, 'description_en', '40c1d971ddb7f152a2a48b9e85576e2c6fb06b0c607cdb1e350e7a6fa877cd4e', 'The most famous of the Romantic piano concertos. The melody of its grand, brilliant opening is so well known that nearly everyone has heard it at least once.'),
('pieces', 160, 'description_en', '475c47b34f2435c5b6380f7c245a011cf01936991f50748a545080c7e16df450', 'Together with the concertos of Beethoven, Mendelssohn and Brahms, it is counted among the four great Romantic violin concertos. It is characterized by wistful, distinctively Russian melodies and brilliant virtuosity.'),
('pieces', 161, 'description_en', '061297fb03de73334b8ec7cb1d72c1caed3dfd48ea4d43fea099978a1b598806', 'One of Tchaikovsky''s three great ballets, a fairy-tale work set at Christmas. The suite, including the "Waltz of the Flowers" and the "Dance of the Sugar Plum Fairy," is especially famous.'),
('pieces', 162, 'description_en', '479cccf42a26080e76cc3e0827dca804c38a2e16694c1208a73489cdd33d5159', 'The first of Tchaikovsky''s three great ballets and a byword for classical ballet. It tells the story of Princess Odette, who has been cursed and turned into a swan. The theme melody of the "Scene" is famous.'),
('pieces', 163, 'description_en', '382b2164f771de0a8769b2c4f4957f570b1bb37a5c388bdd03db40a1a5f35f9c', 'Program music composed to commemorate the failure of Napoleon''s Russian campaign. It is famous for its grand finale, which uses real cannon fire and bells.'),
('pieces', 164, 'description_en', '53258875f25f3f040495dbec6c6d3937a8ad3126b1b4e5f32a6f7a4ee108fbe4', 'A collection of études for solo violin, called the "New Testament of the violin." It gathers every technique the violin can express. The last one, No. 24 in A minor, is the most famous.'),
('pieces', 165, 'description_en', 'b2814278fc2b8e2daee42fb8c2b309c28c1bf1df24d90315e4dfc3eee4a96089', 'The third-movement rondo, "La Campanella" ("The Bell"), is especially famous. It is characterized by brilliant violin flageolet (harmonics) technique imitating the sound of bells, and Liszt arranged it as a piano piece.'),
('pieces', 166, 'description_en', '1e7f6a1596b52d1600f2d0621c2d9ef7f047ee12cf0573f7020ada0eca7d1be8', 'The most widely performed of Paganini''s concertos. It combines brilliant violin virtuosity with aria-like melodies in the style of Italian opera.'),
('pieces', 167, 'description_en', 'bafa2e8b9b8253c9d8cf35ccb67a6a0b98a351d9e7eea9af206520c7e030336a', 'Rossini''s greatest masterpiece, a comic opera (opera buffa). It portrays the exploits of the witty barber Figaro. The aria "Largo al factotum" ("I am the city''s jack-of-all-trades") is famous.'),
('pieces', 168, 'description_en', '532d302c602300d0f3c1de0c06df626f27b1bd1cdbfe4899b2ef55534f318687', 'The overture to Rossini''s last opera, William Tell. It is divided into four parts, and the last, the "March of the Swiss Soldiers" (with its lively galloping hooves), is very famous.'),
('pieces', 169, 'description_en', '9930904dd675ff4c6f930a7ea5bd65d651703c7accb98875778003aa5cbf0835', 'One of Rossini''s famous opera overtures, it opens with the distinctive rhythm of the snare drum.'),
('pieces', 170, 'description_en', '376c303fac3ebdb5ebabe4061cd0a4c740ba667009f2dcab389762c1f351ec30', 'Berlioz''s breakthrough work and a masterpiece of program music. It depicts five visions dreamed by a jilted artist under the influence of opium. The "idée fixe," symbolizing the beloved woman, appears in every movement.'),
('pieces', 171, 'description_en', '1d28d916f102cbce351cd3b4c1b94a50dfea5ed1d9b9326e932edddb074cb017', 'An operatic legend (dramatic cantata) based on Goethe''s Faust. The "Hungarian March" (Rákóczi March) from it became famous for its brilliant orchestration and is often performed on its own.'),
('pieces', 172, 'description_en', 'f602e249f49d658e9c4facd6fd9bbc9409ed908f72bdad8a09acb286f1b208ff', 'A brilliant concert overture composed from melodies of his own opera Benvenuto Cellini. It depicts the frenzied atmosphere of the Roman carnival.'),
('pieces', 173, 'description_en', 'bb2f97e12a2886df4cfcb80fec81fee0b9001ee171ca8d68d7703c3492fa2569', 'The overture to Glinka''s second opera. Full of the racing rhythms and lively energy typical of Russian music, it is a regular in orchestral repertoire.'),
('pieces', 174, 'description_en', 'eca8d8f037298aa0d6310f54d7f3d6a1bb0178fd4eb2542287073632e5937c05', 'The first Russian national opera. Its patriotic story is that the Russian peasant Ivan Susanin sacrifices himself to save the Tsar from Polish troops.'),
('pieces', 175, 'description_en', '640634bd8b4be774879621b7f44a37b91364028338dbf17eb423ce9483347a8e', 'Glinka''s best-known song. A beautiful melody depicting the trilling of a skylark, it became even more famous when Balakirev arranged it as a piano solo.'),
('pieces', 176, 'description_en', '8ccef676ef430855ba359fffc1696761890a7aaf914df29ab71224e7477cb6c6', 'Counted as the greatest of Clara Schumann''s chamber works. Although the influence of her husband Robert Schumann can be seen, her own lyricism and solid sense of structure stand out.'),
('pieces', 177, 'description_en', '164040312b6a26a7d53c10bde64595144d7be77454a31fe7bff81e6b5ca08ef7', 'An ambitious work she completed at the age of 16. It shows both the Romantic virtuoso side she shared with her contemporary Chopin and a deep lyricism.'),
('pieces', 178, 'description_en', '6837f19df3b4a102ea60e0b9e4279a9166e30a570bd650130440f582940913cb', 'A late work, composed for the violinist Joachim, her close friend. Deep, intimate Romantic sensibility stands out.'),
('pieces', 179, 'description_en', 'eb3ec9330b17022d1685d55c24b9fb10c9c2f35889e8d8b93c643f0145ba6ed0', 'Franck''s best-known and most beloved chamber work. It was composed as a wedding present for the violinist Eugène Ysaÿe. The four movements are organically linked by a single theme (cyclic form).'),
('pieces', 180, 'description_en', '1c10893bb35e32217f9dafb65045b53187e7e5e783c77f361ed04c56dbfd7a7f', 'The representative French symphony of the late 19th century. A masterpiece characterized by Wagnerian chromatic harmony, organ-like grandeur and "cyclic form."'),
('pieces', 181, 'description_en', 'c3db5fb2e4b42c0c6d003ab512aa843a33431430c166c2ef67d5170ed9b76a3f', 'Originally part of the Mass for three voices (Op. 12), it became widely known when arranged as a solo piece titled "Bread of Life." It is characterized by a devout, beautiful melody.'),
('pieces', 182, 'description_en', 'fb99d22082cc90b6759fa7eed2c89962a4005b8d8be139d95a325f419a7cc930', 'The most popular of Bruckner''s symphonies. It has the character of program music depicting a medieval forest, castle and knights, and the horn solo in the first movement is famous.'),
('pieces', 183, 'description_en', 'dd762d46a036cb8fb81f04ca48e50df483a5b4bddae398975672c475912acaab', 'The symphony that first brought Bruckner great success. The second-movement Adagio is solemn, mournful music written in memory of Wagner, whom he revered, upon his death.'),
('pieces', 184, 'description_en', 'd7d932cc9de538e74fe0287c47ad7423a07dd9bdde11e51aa53d694361cd907b', 'The most famous of Bruckner''s a cappella (unaccompanied choral) motets. Composed for the dedication of Linz Cathedral, it stands out for its mysterious, devout harmony.'),
('pieces', 185, 'description_en', 'fadfd2fa35d0e02bab4729e399a7e0adc57c48b89c061b6a32c3897f91eccf1b', 'A waltz that is something like a "second national anthem," symbolizing Vienna, Austria. It is a regular encore at the Vienna New Year''s Concert and the most famous waltz in the world.'),
('pieces', 186, 'description_en', 'e5b7980fa00d66abb084dcb2b38b3cc7baeaea00cb6a17baa24178b8a75b17fc', 'The overture to Die Fledermaus, the most successful operetta (comic opera) by Strauss, the "Waltz King." It concentrates the cheerful, lively melodies featured in the operetta.'),
('pieces', 187, 'description_en', 'eb227ed8a9e1fac06994b8cec232712c862349a6188af5f24a3fafc02ed33c87', 'A fast, fierce polka depicting thunder (timpani) and lightning (cymbals). A regular in the repertoire of the Vienna New Year''s Concert.'),
('pieces', 188, 'description_en', '5d1c3b28706abf8ef6f60597505e1f80b9cc8da87294b3a6e616239f8ac0bf58', 'Together with By the Beautiful Blue Danube, it is counted as the essence of the Viennese waltz. The scenery of the Vienna Woods and the solo for the folk instrument zither are striking.'),
('pieces', 189, 'description_en', '0f65ecec9adf40032572666fc13bd0d3a57d19c8e10f8c78b7cab9d2805ee81a', 'A piano suite depicting 10 pictures in music, written after seeing an exhibition of works left by his friend, the painter Hartmann, who died young. The theme called "Promenade" links the pictures.'),
('pieces', 190, 'description_en', '891fa06e37714374af6ec8d5e7b6d92aaf28607a4a5b180d05a37cb1a9f777a0', 'A version of Mussorgsky''s original piano suite arranged with brilliant flair by Ravel, the "magician of the orchestra." Today it is performed more often than the original, and the final piece, "The Great Gate of Kiev," is especially overwhelming.'),
('pieces', 191, 'description_en', '47cad8ed497a17fd1d3575ac4bee8e606e3cc368cd8497f75ea7c58ada3bd031', 'A piece depicting witches and demons gathering on Bald Mountain on St. John''s Eve for a frenzied revel. The version arranged by Rimsky-Korsakov is famous.'),
('pieces', 192, 'description_en', '864d2bd06fe83e9ef56e503adefd30c1607eb3d58c782019133862998e72ce62', 'The supreme masterpiece of Russian national opera. It realistically portrays the guilt and downfall of Boris Godunov, who took the throne after murdering the tsar, as well as the suffering of the Russian people.'),
('pieces', 193, 'description_en', '1372dfae5bfcf82a314819f78c206e0d6c50e634609fb91daf6c350a2fb26b73', 'One of the most popular works in the history of Western opera. It portrays the free-spirited love and tragic death of the Gypsy woman Carmen. All the arias, including the "Habanera" and the "Toreador Song," are famous.'),
('pieces', 194, 'description_en', '6b6623f7c100197595dc055db0e5fa0be8b1562a3b42d1add884ed3668de1a1b', 'Incidental music composed for Alphonse Daudet''s play L''Arlésienne ("The Girl from Arles"). The play failed, but the music became very popular and was arranged into two orchestral suites. The "Farandole" and "Minuet" are famous.'),
('pieces', 195, 'description_en', '8c397c18908f4f896c8c689a42a8baeccafcdeffb79e67a37b04e4a3a435d378', 'A duet for tenor and baritone from Bizet''s early opera The Pearl Fishers (WD 13). It is famous for a beautiful melody that sings of the friendship of two men who love the same woman.'),
('pieces', 196, 'description_en', 'e06f71b6d53946a2dda40760229fb234326a0a228287c1efe061219553c94232', 'A symphony Bizet composed as a 17-year-old student. A Classical-style work influenced by Haydn and Mozart, it is characterized by bright, witty energy.'),
('pieces', 197, 'description_en', '8f4cf08f2244a802179dd64d4d2e7ccbeaa01c22f92f0964d23c88ca1f6ebc71', 'Dvořák''s greatest masterpiece, composed in New York in the United States. Inspired by African American spirituals and Native American music, it is known for the Largo melody of the second movement ("Goin'' Home").'),
('pieces', 198, 'description_en', '748f64b328c4419a7391b3d1bf2e6fd01873fb864eec296636dd18d651376c38', 'Counted as the greatest masterpiece among cello concertos of the Romantic era. It combines cello virtuosity, deep lyricism and symphonic grandeur.'),
('pieces', 199, 'description_en', '5eb634188ac3f762b712433239690fb2cdae7b32bacff5494d0be0e3d87411b7', 'The work that brought Dvořák international fame. A collection of lively, colorful orchestral pieces based on folk dances of Bohemia, in the Czech lands.'),
('pieces', 200, 'description_en', '5250ec06ddafbb025579120c93968963e5623691c86559e0ecdb4454a33567c0', 'Chamber music composed in the United States at the same time as the New World Symphony. It is characterized by pentatonic melodies in the style of African American spirituals and exotic rhythms.'),
('pieces', 201, 'description_en', 'c63e459938703570a7e770e550b01960a1bd97360f13f5cc5687f66d9047b908', 'The seventh of the eight Humoresques (Op. 101), and the most famous and best-loved melody among all of Dvořák''s short pieces.'),
('pieces', 202, 'description_en', '30f99f9f461057f33c4c4dae952fd8674004c7ccd46764967faa1f5670bc7279', 'A symphonic suite based on the Arabian Nights, depicting Scheherazade (solo violin) telling stories to the Sultan. It shows brilliant orchestration at its height.'),
('pieces', 203, 'description_en', '3b04efeffdcefd6eb165dd42dd27add030087aa999c983176ad1035f6efeece7', 'An intermezzo from Act 3 of the opera. It is famous for its breathlessly fast passages depicting the prince, transformed into a bumblebee, flying away.'),
('pieces', 204, 'description_en', 'fbb816ccff92f3c82b257262ffd92ebc7070576290e6e0827fb491c04dcba4e2', 'A five-movement orchestral piece composed on Spanish folk melodies and rhythms. Dazzling orchestration and the brilliant virtuosity of the solo instruments stand out.'),
('pieces', 205, 'description_en', '8f79291885b43b9b14cc5e4d4ab2465d6e5c3e545d0cfbe556294e7f8dd4e3d8', 'A majestic, brilliant concert overture composed on the atmosphere of the Russian Orthodox Easter festival and its chants.'),
('pieces', 206, 'description_en', '4e763d056644b4ee191a8d373000bb11f32a88572653a80aaf45b6e7916c1927', 'Unlike the traditional requiem, it omits the "Dies Irae" and portrays death as peaceful rest. The fourth movement, "Pie Jesu," in particular is famous.'),
('pieces', 207, 'description_en', '28bca48679896c7e1b9ba5f613d15106aa91ae342655bc492870c0b56bee94d3', 'An orchestral piece based on the pavane, a slow, elegant old Spanish court dance. It is much loved for its dreamy, sweet melody.'),
('pieces', 208, 'description_en', 'cc25040619953c0d3967f6b711d2749bf12a8c5859522cf01d5a5a7812a5bbfc', 'Originally incorporated into the Pelléas et Mélisande suite, it is characterized by a melody in the style of a pastoral Sicilian dance. It is often played as a flute or cello solo.'),
('pieces', 209, 'description_en', '0b24597f12a31314387e1a2a34a71fc920933845d509c2e54d9c808a50d0c4e4', 'The best-known of Fauré''s many songs (mélodies). A lyrical work singing of the joy of being reunited with a lover in a dream and the sadness after waking.'),
('pieces', 210, 'description_en', '522cadcc39a18f2c855b71adee0060de7182201b5a99c2495f51ab39f877f846', 'One of Puccini''s biggest successes. It portrays the heartbreaking love story of poor artists (Mimì and Rodolfo) in the back streets of Paris. "Che gelida manina" ("Your tiny hand is frozen") and "Mi chiamano Mimì" ("My name is Mimì") are famous.'),
('pieces', 211, 'description_en', 'faaaf2b4d83e52969d92197144003ec764948af5f63a2797d20afec719c1b437', 'An aria from Puccini''s unfinished final work, Turandot. It is the song of victory sung by Prince Calaf after he solves the princess''s riddles, and the "Vincerò" ("I will win!") passage is overwhelming.'),
('pieces', 212, 'description_en', 'c78355ef1ef43ddf6d72f45f478a8736ae3af5111c02e6cf8a36fb0567f325b3', 'An opera about the tragedy of the singer Tosca, her lover Cavaradossi, and Scarpia, the chief of police who leads them to ruin. "E lucevan le stelle" ("And the stars were shining") and "Vissi d''arte" ("I lived for art, I lived for love") are famous.'),
('pieces', 213, 'description_en', 'd99ab0970ec2852a43a404aa73e67c18f9918a1d723714858907462bffcd3f1f', 'Set in Nagasaki, Japan, it portrays the tragic love of the geisha Cio-Cio-San, abandoned by the American naval officer Pinkerton. "Un bel dì" ("One fine day") is famous.'),
('pieces', 214, 'description_en', '1f01302488c3e877c29dcd6a806291efd2926085e6abefa2d3c17c82b9063224', 'An aria from Puccini''s only comic opera, Gianni Schicchi. It is the song of the daughter Lauretta, who pleads with her father to let her marry the man she loves.'),
('pieces', 215, 'description_en', 'e196d9fcd888cdb1c07d9acd9e606e5a1b5045f507e7c9f60b992f6df9143367', 'One of Mahler''s most popular symphonies. Vast in scale, it deals with the philosophical theme of "death and resurrection," and a chorus enters in the fifth movement.'),
('pieces', 216, 'description_en', '2f5fc9597c7731fb941c906aacb0fb04e1dd0963f62012ebb941f941d09eb430', 'A symphony that begins with a funeral-march-like first movement and ends with a jubilant finale. The fourth-movement "Adagietto," played by strings and harp alone, is especially famous.'),
('pieces', 217, 'description_en', 'e68ea7055cc4d4c7a3238370ce7c539e0d15f27858f98d90b0269e65523a7f5b', 'Mahler''s first symphony, composed in his twenties. An ambitious work of the young Mahler that blends sounds of nature, folk-like melodies, a funeral march and more.'),
('pieces', 218, 'description_en', '6c03ca042f0005ff61edf37c686c72610495f76556eee958701e6d1332991baa', 'Called the "Symphony of a Thousand" because a performance requires nearly 1,000 people (a large orchestra, eight vocal soloists and three choruses). It carries the most affirmative message among Mahler''s works.'),
('pieces', 219, 'description_en', 'ff7d1175a3e6f553fd64deb40c5367e0ed9a4c9ee25abb68c0a2f00c650f19ce', 'A "song symphony" in six movements based on Chinese poems, including those of Li Bai (Li Taibai). Because of the superstition of the "curse of the Ninth," Mahler did not call it his "Symphony No. 9." It is one of Mahler''s most pessimistic and profound masterpieces.'),
('pieces', 220, 'description_en', '78bfc4174ae3ebd98d3d26e532842d27371c5364a6d9c7bf5761bffed6e8dea3', 'The third of the four pieces in the Suite bergamasque. The most famous of all Debussy''s piano pieces, it is a dreamy, beautiful work often used as a byword for "Impressionist" music.'),
('pieces', 221, 'description_en', '4f3152eac7ed68122b0134e561e99aeb88067f4542715f91bdcb3d0e5823ed9d', 'A symphonic poem based on Mallarmé''s Symbolist poem, depicting the dream of a faun on a languid afternoon. A monumental work that announced the beginning of "Impressionist music."'),
('pieces', 222, 'description_en', '72c00f2cef969ea9d93fefa7a6edab5b715cf9966184d42f7f6cc6987e084031', 'Debussy''s greatest orchestral masterpiece, depicting the ever-changing scenery and colors of the sea across three movements (including "From Dawn to Noon on the Sea").'),
('pieces', 223, 'description_en', '455e41dd4434b90ff344518b51fab494059e81ffe69379e509c50184bfb29b0c', 'A suite of six short piano pieces composed for his daughter Emma. The "Golliwogg''s Cakewalk" movement is famous, and it playfully quotes Wagner''s "Tristan chord."'),
('pieces', 224, 'description_en', '09cd6d9aa06247741cb56c1a265a5ce04aa795e4d8fe0b903c663777af306c58', 'The first of the two Arabesques (L. 66). A short piano piece characterized by the elegant, lyrical melody of Debussy''s early style.'),
('pieces', 225, 'description_en', '86533a6a1281b93d1e5e03b61a14c0e094aa87746a62db3bc16fd3303356adf4', 'Rachmaninoff''s greatest masterpiece and a byword for the Romantic piano concerto. It is loved around the world for its deep melancholy, explosive passion and sweet melodies.'),
('pieces', 226, 'description_en', '63733af43ce8b5d81a7b8f5d295627fa386d5cf35c38ed4f1cf19ee2a08a5e0d', 'One of the concertos reputed to be the most difficult, demanding extreme technique and stamina from the pianist. It also became widely known to the public through the film Shine.'),
('pieces', 227, 'description_en', 'fd59ce3eeaa1fd97746b570804bb803cc500aed4bc4cdcebf29ce4f4b21b4861', 'A set of variations for piano and orchestra on the theme of Paganini''s Caprice No. 24. Variation 18 (a melody made by inverting the theme) is especially famous.'),
('pieces', 228, 'description_en', '8594909b7187e19d0046f64e8e5b630708896c42a596e6f80f8e99fa9a7392cf', 'The last of the 14 songs of Op. 34. A sad and beautiful melody sung without words, on a vowel ("ah") alone, it is performed in arrangements for many different instruments.'),
('pieces', 229, 'description_en', '03adb689512ba73fc96e188d76631d67179643916b22d8be1a756e7c988327ed', 'A short piano piece composed at age 23 that brought him worldwide fame. It is characterized by solemn, dark chords reminiscent of the bells of the Kremlin.'),
('pieces', 230, 'description_en', 'd67058133e12c3ed737838ef2c471d21592d1a1b68eba67d7a7e6519cdbf874e', 'Ravel''s best-known experimental orchestral work, in which a single rhythm and two melodies repeat for 15 minutes with changing instrumentation, ending in a grand finale.'),
('pieces', 231, 'description_en', 'cb6a3628364f0f7475a7c52a58c17de674606c61fa2f3a5825c3ecdf32f4f725', 'A piano piece (later orchestrated) written while imagining a dance that a young infanta (princess) might have danced at the old Spanish court. It is much loved for its antique, elegant melody.'),
('pieces', 232, 'description_en', '2bd49722cd277c1cf6537903f8e166bb74f2eca70874b8cb3dc6ca351a82497f', 'A piano piece depicting water spurting and glittering. An innovative work that, by taking "water" as its subject before Debussy, announced the beginning of Impressionist piano technique.'),
('pieces', 233, 'description_en', 'a85fb4fe11eee1a0670098cf7d06c22c13e4e2a277e0ba3064363a08afc51b07', 'A light, witty concerto composed under the influence of the jazz Ravel encountered on his trip to the United States. The beautiful piano solo of the second-movement Adagio is famous.'),
('pieces', 234, 'description_en', 'c237448163dfe8318eea7e0d681ed570fef536067a2519d122f8481758e7231d', 'Ravel''s largest and most brilliant ballet music. Suite No. 2 ("Daybreak," "Pantomime," "General Dance") shows the essence of his orchestration.'),
('pieces', 235, 'description_en', 'a6fb7b76bccf6d2f8b13d846c1967ab47e9c6dcb6564e3a79afaff587d9eb99d', 'The overture to Der Freischütz, which opened the era of German Romantic opera. It condenses the opera''s key themes: the mystery of the forest, the sinister presence of the devil, and the joy of victory.'),
('pieces', 236, 'description_en', 'b88dd099f070676b6215d1dcae08a1bed3618adf4c908f3b234005f1cb340a9d', 'A piano piece depicting a scene at a ball in which a gentleman invites a lady to dance and they waltz together. It became the origin of the Romantic "waltz."'),
('pieces', 237, 'description_en', '8d844c226f87cc12a7b92c0cf05bb6b4ecd9ad3d64459c18199d9d55f3e7f31d', 'A concerto that maximizes the dark tone of the clarinet and its brilliant technique. Together with Mozart''s concerto, it is important repertoire for clarinetists.'),
('pieces', 238, 'description_en', '0773ebde796031ad2ea9b07a1a5a8a7cd4d9a4a82304a0644d63c231aa2bad96', 'Johann Strauss I''s most famous work. It closes the Vienna New Year''s Concert and is known for the tradition of the audience clapping along with the beat.'),
('pieces', 239, 'description_en', '1114722db189016ef79d5a22017e944a5bc557daa3de630f33fcdd84c00be315', 'Together with his son''s (Strauss II''s) By the Beautiful Blue Danube, it is regarded as the most lyrical and beautiful of the father''s waltzes.'),
('pieces', 240, 'description_en', '44a33b68b38a3a0187b1cfa8c6be7bb8a3966e2761863e5714dd76bf098f5e42', 'One of the greatest masterpieces of Romantic ballet (the "ballet blanc"). It portrays the tragedy of Giselle, an innocent country girl who dies through the betrayal of a nobleman and becomes a ghost (a Wili).'),
('pieces', 241, 'description_en', '532279ce2de0dbba39b8ad0fa69cd36bcd9923a91c971b10a2a778be77f2f5ce', 'One of the most widely sung Christmas carols in the world. It is better known by the title "O Holy Night."'),
('pieces', 242, 'description_en', '0d3043aebb84ec37bea18913d13b07d1fbc07b96587f201e042804269fdc4b5a', 'An arrangement in which Gounod set a melody to a Latin prayer text over the harmony of the Prelude No. 1 in C major from Book 1 of Bach''s Well-Tempered Clavier.'),
('pieces', 243, 'description_en', '6a0d1efd3cd13d9efbb177a4f7d5a066aa2e592f8b8a20560767d28400f22283', 'Gounod''s signature work. Based on Goethe''s Faust, it deals with the story of Faust, who makes a contract with the devil Mephistopheles, pledging his soul.'),
('pieces', 244, 'description_en', '68911a26c9d526055b11a867f4c016627b422617c721d17d9f15d5f3829e5f1f', 'A five-act opera based on Shakespeare''s tragedy of the same name. Four love duets and the aria "Juliet''s Waltz" are famous.'),
('pieces', 245, 'description_en', '5c7f8bb8176f5515e89022a80920777220e8bd32e10d51d78e645b8a55bbd750', 'Offenbach''s most famous operetta (comic opera). It satirizes Greek myth, and it won immortal fame through the "Can-can" dance music at the end of the overture.'),
('pieces', 246, 'description_en', '3dc436bc31edc3803db2db8258ec6de0b52e86747ce2cad56e244aa621302aa4', 'Offenbach''s only grand opera and his last work. The duet in Act 3, the "Barcarolle," is famous for its dreamy, beautiful melody.'),
('pieces', 247, 'description_en', 'bf5cc0544dd5cda0d37b64dbc2ba8a5f0e5e995315ffd294ebd5472b83ebe45a', 'The second of the six symphonic poems of Má Vlast ("My Country"), which depict the history and nature of the Czech lands. Depicting the flow of the Vltava (Moldau), the lifeline of the Czech lands, it is Smetana''s most famous piece.'),
('pieces', 248, 'description_en', '5f6c1e7ea0a3b37de73820d0050fc1272ccd0ba84767cb03db4c03004947b0f9', 'A representative work of Czech national opera. It portrays a love story between country folk with cheerful dance music. The overture in particular is famous for its racing, fast string passages.'),
('pieces', 249, 'description_en', '367844399bf1e1b79a9adb3336ad0627b2f3092454f316de02d9c2c0e77d98f5', 'Ballet music from Act 2 of Borodin''s unfinished opera Prince Igor. Its exotic, fierce rhythms and enchanting melodies make it a frequent concert piece on its own.'),
('pieces', 250, 'description_en', '9803114f422f6cd542e52d46c5a176d531de83b22e3bca04dc86fd06c8f098d7', 'An exotic symphonic poem set on the vast steppes of Central Asia, depicting the meeting of Russian and Eastern melodies.'),
('pieces', 251, 'description_en', 'c8980c6586be2e97dc24f5158b269becd2d6c41351b4545ba8ff77b6105c6e74', 'Borodin''s representative symphony, full of vigorous energy reminiscent of Russian heroic epics.'),
('pieces', 252, 'description_en', 'f56192c6fd00d8769d7cc774254e42247d8764016bcb43c3a26a6b80b8ca68d1', 'An orchestral suite in 14 movements that cheerfully depicts various animals such as the lion, the swan, the aquarium and the kangaroo. The "Swan" movement is especially famous.'),
('pieces', 253, 'description_en', 'd2f6b6f8f4f3796e96bfad42f18d1e0cb8f1e70c481210fe0dfc93d4ebf9623e', 'A symphonic poem depicting the legend of skeletons rising from their graves to dance to the playing of Death''s violin. The xylophone depicts the sound of bones clattering.'),
('pieces', 254, 'description_en', '6aaf1bdb581330e7f9822217800112b2e9b000c1c9e4f68e0e6080dd18694f42', 'Saint-Saëns''s last symphony. A masterpiece that combines an organ and two pianos with the orchestra to create a majestic, brilliant sound.'),
('pieces', 255, 'description_en', '07d767cbf9edc9cb49c6a8e738347ce52e5c992caa0d753c43fd891159a25031', 'An aria from Act 2 of the biblical opera Samson and Delilah, which Delilah sings to seduce Samson. It is a captivating, sensual aria.'),
('pieces', 256, 'description_en', '01d76831a54517da69a6f7024e238c6f16be335b26afb4cf9d209a447d051f09', 'A cello concerto in a single movement, unusual in that its three sections are played without a break. It shows off both the cello''s virtuosity and its lyricism.'),
('pieces', 257, 'description_en', 'f6707624bd0def831049ab9c23bbd309164950bcb3d5b63fc28396ea55c1cad0', 'By far the most famous of all Bruch''s works. One of the great masterpieces of the Romantic violin concerto, it is ranked alongside the concertos of Mendelssohn and Brahms.'),
('pieces', 258, 'description_en', '438d40dda9a08ad9ee03b9b8e1a261b8cde59e09e109498134a6ea6aa6fc165a', 'A four-movement fantasy for violin and orchestra built on Scottish folk melodies. It is loved no less than Bruch''s violin concerto.'),
('pieces', 259, 'description_en', 'b646bf92b84f7794ae0667d8e5e77b6818fd7540c7db3cd794bb15ac80298cc6', 'A meditative short piece for cello and orchestra, composed on the melody of the chant ''Kol Nidrei'', which is sung on the Jewish Day of Atonement (Yom Kippur).'),
('pieces', 260, 'description_en', '5ca01528dea68e5c9dcdd3dde936e65d4516ba4ed0e5a3cd24a75b26993662d7', 'An intermezzo from Act 2 of the opera Thaïs. This devout, beautiful violin solo portrays the meditation of the dancer Thaïs, who has been converted by the monk Athanaël.'),
('pieces', 261, 'description_en', '2a16d1520280f00a37619f7fd5c31c789f8e71721e29115e7823fc7f69ce2813', 'A French lyric opera based on Goethe''s The Sorrows of Young Werther. It portrays the tragic love of its title character with great delicacy.'),
('pieces', 262, 'description_en', '0d5111274f9aa54919ebf542e0f0e435203a065229281654f6bf13fc54216974', 'Sarasate''s signature work. It is built from a melancholy melody of Hungarian Gypsy (Roma) music (lassan) and a dance that grows ever more fiery (friska), and is the ultimate showpiece of violin virtuosity.'),
('pieces', 263, 'description_en', '890bc7035127650bbccaf9b9bcc419deac9a3540c3ac16eb57aa54d541600368', 'A fantasy built on famous melodies from Bizet''s opera Carmen (the Habanera, the Seguidilla and others), with brilliant violin virtuosity added.'),
('pieces', 264, 'description_en', 'd78c1b7e38f8084174f1600ee108fbffbbef042871c20087495592e58d314747', 'A brilliant short piece that shows off fast violin technique: a slow introduction is followed by the tarantella, a fiery Italian dance.'),
('pieces', 265, 'description_en', '40f32526503b345c29c7a817ba71713c43c57f8c9dc3e3d531bd5e57af93b010', 'No. 1 of Elgar''s five Pomp and Circumstance Marches. The majestic melody of the middle section (Land of Hope and Glory) is so famous that it is called Britain''s ''second national anthem''.'),
('pieces', 266, 'description_en', '57bb029c712e336e610a09cee454f42560f11aa9f0eb1720840f6afd5cdebbaf', 'Elgar''s last major work. An introspective, mournful piece that carries the sense of loss and grief after the First World War. It was rediscovered in the 20th century through the playing of cellist Jacqueline du Pré.'),
('pieces', 267, 'description_en', 'bc3754a1cc56f03355f3bf91443f0173071f8cc71a1207083b3b407d8a122ed3', 'A unique work in which each of the 14 variations portrays a friend or acquaintance in Elgar''s circle. The theme of the ''enigma'' has still not been solved. Variation 9, ''Nimrod'', is especially famous.'),
('pieces', 268, 'description_en', 'b7a12c6f46e64ab4d1f5012f50a11091ef443628356322b05bea1e5141cc1223', 'A sweet short piece for violin (or cello) that Elgar composed to mark his engagement to Caroline Alice Roberts. It is very popular with the general public.'),
('pieces', 269, 'description_en', 'a6496d1ea95a0a4b7d36a726e14556bdb232d44ae2447bd6731962aa495ea2da', 'Leoncavallo''s only success and a leading work of ''verismo'' (realist) opera. Its shocking story: a clown who learns of his wife''s infidelity kills her on the theatre stage.'),
('pieces', 270, 'description_en', '7b7fab90fdf28156f72289f924fdb1396e343699dbe746243f6c64707ed88bb6', 'The aria that closes Act 1 of Pagliacci, sung in anguish by the clown Canio, who must go on stage even though he knows his wife has betrayed him. One of the most famous tenor arias.'),
('pieces', 271, 'description_en', '841250d3be3aca9c492c8881e4d11fa9ba8a084e861b9440ad38d352aecb54c4', 'An Italian song (canzone) by Leoncavallo. Its bright, brilliant melody sings of the splendour of the morning, and tenors love to perform it.'),
('pieces', 272, 'description_en', '3e389d2c8492c9887c38d3dd39e1020ff300ab6c054da2724f657b37d951e134', 'Originally a piano piece, it evokes the flamenco technique of the Spanish guitar so perfectly that it is now better known as a guitar solo.'),
('pieces', 273, 'description_en', '7911437445aec779c16a383a72f6bdd69c431e5e14998d4fe1d10c020551a470', 'Albéniz''s masterpiece and one of the most difficult works in the history of piano music. Twelve pieces capture the impressions and moods of the various regions of Spain.'),
('pieces', 274, 'description_en', '8e65bdeae6a12966e2f6b54ef39359b0e73dc0172268c8145432296759b168c0', 'The second of the six pieces in the suite España. Its exotic, enchanting melody has led to arrangements for many instruments, and it is a much-loved short piece.'),
('pieces', 275, 'description_en', '58f2fb4a961198f4bc2da1c990f8f011c2d0d56e5bd2866daf5a6f82b5564b98', 'Winner of a one-act opera competition, it opened the era of ''verismo'' (realist) opera. Set in Sicily, it tells a story of passion and revenge among ordinary people.'),
('pieces', 276, 'description_en', '05fb762d53ff492dec93c51153b5828f438b9bf8f64467ff72b8ef2a284131ad', 'The tragic and beautiful intermezzo played in the middle of the opera. It became more famous than the opera itself and has been used in countless media, including the film The Godfather Part III.'),
('pieces', 277, 'description_en', '5c55f56d646aadb1ce9a4bce91bbdd3f6ea75ea315be95a7e2e1968ce0fa8956', 'A symphonic poem that stirred the patriotism of the Finnish people resisting Russian oppression. The solemn, beautiful hymn in the middle section is called Finland''s de facto national anthem.'),
('pieces', 278, 'description_en', '708f2eaeac79471554ebd319dc7654af1e73658016567420ae5ba51bea5a4dbe', 'One of the greatest violin concertos composed in the 20th century. It combines the cold, majestic nature of northern Europe with the extreme technical demands of the violin.'),
('pieces', 279, 'description_en', 'ac129c012be219b89673a10a8e8e0ee75ce92a1a3e13c7e1c116912e60ae2c87', 'One of the pieces of incidental music for the play Kuolema. An eerie yet beautiful waltz depicting the vision of a dying mother dancing with ghosts.'),
('pieces', 280, 'description_en', '2e462fc9514bb743fb18be3ae201321398805bf3c3c42667d4c647bcb0798034', 'The most popular and most Romantic of Sibelius''s symphonies. It opens with melodies that seem to depict the nature of northern Europe and ends with a majestic, heroic finale.'),
('pieces', 281, 'description_en', '5b5c138232a4a57fc3eb7f06f4bf4c2a03458cf03d9d5066286bc345778536a3', 'A masterpiece based on a hymn melody by the 16th-century composer Thomas Tallis, in which two string orchestras and a string quartet create a mysterious sound.'),
('pieces', 282, 'description_en', '73537de264d921d2c54f490ca1dfbf0573195dc923f9414063d81501ee72d5f5', 'An orchestral fantasy based on the famous English folk song ''Greensleeves''. It is marked by a lyrical, pastoral mood.'),
('pieces', 283, 'description_en', '03475088571193cba0d7cbfbd1480608d6a04753a6eaea658840c3e35ea69c9b', 'A romance for solo violin and orchestra, inspired by a poem by George Meredith. It portrays a lark soaring into the sky in lyrical fashion.'),
('pieces', 284, 'description_en', 'ea19c982ca1d47bbeb60ed9358101a7e8f08d0d8934a6faa6e82bf1c6bbb6af3', 'A seven-movement orchestral suite depicting the astrological character of seven planets (Mars, Venus, Mercury, Jupiter, Saturn, Uranus and Neptune). ''Mars'' and ''Jupiter'' are especially famous.'),
('pieces', 285, 'description_en', '7cdaf20f69dcff586652d1d383b32285a9dc9b48941460e4fe4c7b4e5a293eb8', 'A string ensemble piece that Holst wrote for the student orchestra of St Paul''s Girls'' School, where he taught. The English folk song ''Greensleeves'' appears in the fourth movement.'),
('pieces', 289, 'description_en', 'bb1ecc78c09e32fa9f2780081f17d8538b34761c4fb21054b47245be218bbb8d', 'An essential collection of etudes for beginning pianists. Titles with a Romantic sensibility, such as ''Arabesque'', ''Pastorale'' and ''Ballade'', make it very popular.'),
('pieces', 290, 'description_en', 'a094cb43d86cc8840c5ad373f649640ccb3943c00c2eed24bcdba5e5f4634b17', 'A step up from Op. 100, this collection of etudes, with titles such as ''Pearls'' and ''Storm'', demands more brilliant technique and greater expressiveness.'),
('pieces', 291, 'description_en', '947f3bed30606884879721bece84b5c71742f6182203300c79ed5aebbbe71768', 'The only piece by Rubinstein still known today, a short piano work. Its sweet melody made it hugely popular as 19th-century salon music.'),
('pieces', 292, 'description_en', 'f122d468b93c05346f0a989ed0360f9e2ed91149ac92ba363f22d598b9921145', 'In its day it was counted as the leading Russian piano concerto before Rachmaninoff, but it is almost never played now, an ill-fated masterpiece.'),
('pieces', 293, 'description_en', '0acfcb42811650cbd493fac80cf6ec33d4457fdeb75cba3068f7e8f1f87daa21', 'Wieniawski''s signature work. Brilliant violin virtuosity is balanced with Polish-flavoured Romantic melodies reminiscent of Chopin (the Romance, second movement).'),
('pieces', 294, 'description_en', 'f171590bc44b9f4aefbb584d745646e03773b1dbe9bd8fbd807e0622db3beffd', 'A work that expresses the Polish dance, the polonaise, through brilliant violin virtuosity. It is often played as an encore to show off a violinist''s skill.'),
('pieces', 295, 'description_en', 'c02895252a397a168a243b1d8ea65d15cef8fcfd0997099c0c22f3464608ead2', 'A short piece for violin and orchestra with a striking mysterious, wistful melody. It represents Wieniawski''s lyricism.'),
('pieces', 296, 'description_en', '8620092f47d6acc11bb5743cd59a941e91502001bddc01aeb7749c0dd2e88006', 'A work that shows the essence of the guitar''s tremolo technique (rapid repeated plucking of a single string). It is dreamlike, as if depicting the sound of the fountains of the Alhambra palace.'),
('pieces', 297, 'description_en', 'b70b80ee60f28b440fb85246d7328766922242c5e4c24a9833ba9737dc35f335', 'Composed by Tárrega after he travelled in Andalusia in southern Spain (a region influenced by Arab culture). Its exotic, plaintive melody is characteristic.'),
('pieces', 298, 'description_en', '88aa6d780e457a6570dbc4e4087e55102bf9211db4f3c11126d3cd5fd805f819', 'Wolf''s first major song collection, setting 53 poems by the poet Eduard Mörike. ''Im Frühling'' and ''Der Verborgene'' are among the famous songs.'),
('pieces', 299, 'description_en', '5a4d6ac967e59129148278d377bcc25c7ad10f1917c0db7fd87f18ffec33aa92', 'A collection of 46 songs based on Paul Heyse''s volume of translated Italian folk poetry. Within a short, compressed form it holds wit and depth, and it is a masterpiece of Wolf''s later years.'),
('pieces', 300, 'description_en', '4c0169567ab9c48375cbd2722cc73a2dfb2f4804bc5ce2c38b128b8acb366782', 'The most famous of Nielsen''s symphonies. Composed amid the turmoil of the First World War, it expresses the ''unquenchable will to live''. The passage in which two timpani seem to fight a fierce battle is striking.'),
('pieces', 301, 'description_en', '15f9000ba621dac1ab50f80b25178dfbfad23f63f4daa3e4ef0f8dfd724e2999', 'One of the great clarinet concertos of the 20th century. It explores the clarinet''s technique and expressiveness to the limit and is marked by a sharp confrontation with the snare drum.'),
('pieces', 302, 'description_en', 'f39aa81d906df75802f6c2011589e4499399be35e2a0da9495f2ddcedaab7a4e', 'Glazunov''s most famous work. It follows the tradition of the Romantic concerto but is distinguished by its single-movement design, played without a break. It is loved for its lyrical, brilliant melodies.'),
('pieces', 303, 'description_en', '83daec90715ad1df8f2daa8b52f35f34770611fd5ef02c58706c1001a2754080', 'A ballet in three acts set in the age of the medieval Crusades. Full of brilliant, exotic melodies, including Hungarian-style dances, it is an important part of the classical ballet repertoire.'),
('pieces', 304, 'description_en', '7e05b4db9df2e92270160d367f7c1fefad2d70260b3c852fe12515f8245bdd17', 'Reger''s best-known orchestral work. Based on the theme of the first movement of Mozart''s Piano Sonata No. 11 (K. 331), it varies the theme with the rich harmony and counterpoint of late Romanticism.'),
('pieces', 305, 'description_en', '2f8fa6af5a289f71a58b820c0490f4ee3dfed02b032bf314f7a153c96853370c', 'A grand and complex organ work built on the ''B-A-C-H'' motif (B♭-A-C-B♮). It concentrates Reger''s reverence for Bach and his contrapuntal skill.'),
('pieces', 306, 'description_en', '8e47218e28c8ac44fe77e80c433ef2e96591d6743703074f97e7502d7ab897a8', 'A ballet based on a legend of the Andalusian Gypsies of Spain. The ''Ritual Fire Dance'' (Danza ritual del fuego) is very famous for its fiery rhythm.'),
('pieces', 307, 'description_en', '6683672305b86316d4cb0422b9ff071f76f32c9648cb478f7a844050109eee82', 'Composed for the Ballets Russes, with sets and costumes by Picasso. A masterpiece that makes modern use of Spanish folk dances (jota, fandango and others).'),
('pieces', 308, 'description_en', '40667545dbe4e54c47ab365cf5a07093b8c7a96c9fa3f378ab2bc4f95ac0d097', '''Symphonic impressions'' for piano and orchestra, depicting the night scenery and impressions of the gardens of Spain (Andalusia). Debussy''s Impressionist influence is strongly evident.'),
('pieces', 309, 'description_en', '3279d753631b30a898302d28df3bdcae6444eefaaf5b02830bde3bd6ef8de74d', 'A revolutionary work that announced the beginning of 20th-century music. It depicts a primitive pagan Russian ritual, and its radical dissonances and primitive, explosive rhythms caused a scandal at the Paris premiere in 1913.'),
('pieces', 310, 'description_en', '36209c3f88836f773dcef5d76be8aded6aa0571efa2d0ea4808750a173b6c171', 'Stravinsky''s first success with the Ballets Russes. It is marked by brilliant, exotic orchestration that shows the influence of his teacher Rimsky-Korsakov. The ''Dance of the Firebird'' and ''Infernal Dance'' are famous.'),
('pieces', 311, 'description_en', '0c975061d8ae6b9501d5cd7150ca777eb725e7354ad06fc369e7776ee1f967ae', 'A ballet telling the tragic love story of three puppets (Petrushka, the Ballerina and the Moor). Its ''polytonality'' technique, in which different keys sound at the same time, was innovative.'),
('pieces', 312, 'description_en', 'eecbaa75fc65cc11b2289c8896b26079be3eed7a343fd82c5df05da855f17114', 'A sacred choral work representing Stravinsky''s ''neoclassical'' period. Set to the Latin text of the Psalms, it combines medieval grandeur with a modern rhythmic feel.'),
('pieces', 313, 'description_en', '28c9c99f1fcb1b8b64a556cba2631a4a3fc160ad8c64b585f151a8373402a602', 'Schoenberg''s early masterpiece in the late-Romantic style. A symphonic poem for string sextet (later arranged for string orchestra), it is marked by Wagnerian intense chromaticism and emotional expression.'),
('pieces', 314, 'description_en', '71b1498e417f7842ade0d795d3ade0b1e1f44ec82cee92f4166b824f1f43246c', 'A work representing Schoenberg''s ''atonal'' period. It is marked by the distinctive vocal technique called Sprechstimme (speech-like singing) and a grotesque Expressionist atmosphere.'),
('pieces', 315, 'description_en', 'd4ee9e166286bd3205a5fd93b9b0476463cf4a0f1824ed8ea8f2246106d96cc5', 'A cantata for narrator, chorus and orchestra based on the testimony of a survivor of the Nazi ghetto. Composed using the twelve-tone technique, it is a shocking and dramatic work.'),
('pieces', 316, 'description_en', '0fd3a645ea7c7e89d17230b93e9abad3cc20d22d379477c08cc24d228dbb2be4', 'Works written just before Schoenberg established the twelve-tone technique. In the fifth piece, ''Waltz'', the technique is used in part for the first time.'),
('pieces', 317, 'description_en', '8e452296c493efc567c0763f2aa5c96b928337d0fca6ac80992f47089ff34f84', 'Composed by Shostakovich, who was in danger of being purged after Stalin''s regime condemned his opera Lady Macbeth of the Mtsensk District, as ''an artist''s response to criticism''. On the surface it conforms to the regime, but beneath lies a joy forced by coercion (tragedy).'),
('pieces', 318, 'description_en', 'ce2f3ec0404be520cbee780162a421ccccb7ffb1dd8767ffff59ceec063e52f4', 'A symphony composed while Nazi Germany besieged Leningrad. The relentlessly repeated ''invasion theme'' of the first movement is famous, and the work became a symbol of the Soviet spirit of resistance.'),
('pieces', 319, 'description_en', 'c58327df9482b8882672f6321ee387294ef7bc77576c33a8fe83429279c88f69', 'Shostakovich''s most popular melody. Long thought to belong to the lost Jazz Suite No. 2, it is now classified as part of the Suite for Variety Stage Orchestra No. 1. It was used in the film Bungee Jumping of Their Own.'),
('pieces', 320, 'description_en', '4961d341ef78691614fec6327e07c2f1b94ea2ecebb9a622385612cf6428100c', 'An autobiographical work that takes the composer''s initials as its theme: the motif D-S-C-H (D-E♭-C-B). Dedicated to the victims of fascism, it is the most intense and anguished of his chamber works.'),
('pieces', 321, 'description_en', '8b9a403621e54c3223292c59927f669a077b2d72814b412386340840ecbb1724', 'A masterpiece of the 20th-century cello concerto, written for Mstislav Rostropovich. It is marked by extreme cello virtuosity, the D-S-C-H motif and fierce rhythms.'),
('pieces', 322, 'description_en', 'b2c10729c67cc2ee011fc978962f6978c198d68736b41887a36510e0528b038e', 'The finest ballet music of the 20th century, based on Shakespeare''s tragedy. The menacing melody of the ''Dance of the Knights'' (Montagues and Capulets) is especially famous.'),
('pieces', 323, 'description_en', 'dc17de0834ee9ce55eb32569ead9890c6830f165a949fd4f15db0008cf7d1734', 'A leading work of ''neoclassicism'', in which Prokofiev reinterpreted Haydn''s style in a 20th-century manner. Witty and light, it has a finale (fourth movement) whose sense of speed is the highlight.'),
('pieces', 324, 'description_en', '4cc688033d941923a3128294042bdd254edba3b5c09cd5967ac236c1f4af1b92', 'A musical fairy tale composed to introduce children to the instruments of the orchestra. Each character is portrayed by a particular instrument: Peter (strings), the bird (flute), the wolf (horn) and so on.'),
('pieces', 325, 'description_en', '010a9cbcc3b5813ab9464e459b6bb00488907184047ab19582c8ae6dd610644b', 'The most brilliant and popular of the 20th-century piano concertos. Sharp rhythms, a percussive piano and lyrical melodies are combined.'),
('pieces', 326, 'description_en', 'a82f6d3d2f8882ea55790c915421d50deeb787c69593c22265051517a489f93c', 'One of three ''war sonatas'' composed during the Second World War. The mechanical, violent finale (third movement) in 7/8 is overwhelming.'),
('pieces', 327, 'description_en', '064acd133498ed9e37ef4e28dd49196de110660c4372f10737e5207deeb790f8', 'Bartók''s greatest masterpiece, composed during his exile in the United States. Every instrument of the orchestra shows off brilliant skill, like the soloist of a concerto.'),
('pieces', 328, 'description_en', 'c4454c760709423bee0cd8705a996dddad01609dab556772527be4bb4316a65e', 'A masterpiece of 20th-century orchestral music that concentrates Bartók''s originality. It is marked by a symmetrical movement structure (the golden section), an unusual instrumentation and folk rhythms. It was used in the film The Shining.'),
('pieces', 329, 'description_en', '0f0edd5815328575c700f674fc3f002a997c7b4e80dec9a3ed39b988e968b8c0', 'A one-act ballet that caused a scandal at its premiere because of its violent, lurid content. It is marked by primitivist, fierce rhythms.'),
('pieces', 330, 'description_en', '3a54dae60abaac5342ee22c9fa31c0981fb8e90a08354003d25d11321b8d2f20', 'A collection of 153 piano exercises that Bartók wrote for his son Péter. Beginning with simple pieces, it lets the player learn step by step up to the complex techniques of 20th-century modern music.'),
('pieces', 331, 'description_en', '88cdb36e09d43e7b9d6986f8b3f80ae2490976e2ee8b1069100120c01a5faa57', 'Considered the greatest series of string quartets since Beethoven. A monument of 20th-century chamber music, it concentrates Bartók''s compositional technique and his research into folk music.'),
('pieces', 332, 'description_en', '708bf15d00110743b28296db2c4ed01f3cf183f5302edb143b6b4d3509730310', 'A symbolic work of American music that combines classical music and jazz. It opens with the famous clarinet glissando (sliding note), and the brilliant piano virtuosity stands out.'),
('pieces', 333, 'description_en', '28bb2fef07a08acc68dec199cb2248758f2437feffbf28b0deab38b04b44125f', 'The first great American opera, set in a poor Black neighbourhood. All of its arias, beginning with ''Summertime'', have become jazz and blues standards.'),
('pieces', 334, 'description_en', '1312711e280159cb34bc7d1fb239b7fb85f49f96bbbab3b50cadf5dbb5e56daa', 'A symphonic poem depicting the impressions Gershwin gathered while travelling in Paris. Jazzy blues melodies and the sound of Parisian car horns (taxi horns) blend delightfully.'),
('pieces', 335, 'description_en', '63d5c968ac1682316e885a9f83e3071c9a6a774bce5bff7dc3b3ec2bfbac73bc', 'A full-scale three-movement concerto written after the success of Rhapsody in Blue. It combines the form of the Romantic concerto with the idiom of jazz.'),
('pieces', 336, 'description_en', '5013cc9c6537b0f4bfa0bd8c8eddc3b311f147caef650c0912a61234c55e7ecd', 'A musical that transposes Romeo and Juliet to a conflict in modern New York between a Puerto Rican immigrant gang (the Sharks) and a white gang (the Jets). ''Mambo'' and ''Tonight'' are among the famous numbers.'),
('pieces', 337, 'description_en', '0e7925838ae4a0e2fa9e0bdddef1ed95b1d388bdd3f6967c4345a54d2dd2833b', 'An arrangement of the musical''s main dances as a symphonic suite. Jazz and Latin rhythms and fierce orchestration stand out.'),
('pieces', 338, 'description_en', '788120b6a99872bb23bf4a27ba00c4a311a4ead69ec3cbd59b9ed656942bc4de', 'The overture to the operetta based on Voltaire''s satirical novel Candide. Witty and brilliant, it is a staple of American orchestras'' repertoire.'),
('pieces', 339, 'description_en', '14abc49cae4ec65513f50a2528fa8169ac1d2ad572aa863b3d1176730c3efd48', 'A symphony in two parts and six movements, inspired by a poem by W. H. Auden. The piano plays a role as important as in a concerto, and the work portrays the loneliness and faith of modern people after the Second World War.'),
('pieces', 340, 'description_en', 'caf3365d32341fe81746163c3836adfd8bca7d5ef09f7fb835b5fcd3e8bc2ad6', 'The national anthem of South Korea. Composed around 1935, it was adopted as the official anthem when the South Korean government was established in 1948.'),
('pieces', 341, 'description_en', '6ccfb4f93cccac0df78e974236d42e79d9c6f0e748f9df9becfddd9a92642280', 'A symphonic poem composed after Ahn Eak-tai studied with Richard Strauss. Built on late-Romantic orchestration, it develops the melody of the ''Aegukga'' (national anthem) as its main theme.'),
('pieces', 342, 'description_en', 'cad24f60f04d78b769136c2c8b7017861ba691100073e7e446f96dd75f4fb258', 'Composed in 1920, the first Korean art song (gagok). Its plaintive melody sings of the sorrow of the people under Japanese colonial rule through the image of the balsam flower.'),
('pieces', 343, 'description_en', '67607b9303df09b61e112b1726596658f54be4c5dd37ca8630239dd6dfab1162', 'A children''s song beloved by the whole nation, beginning with the words ''The home where I used to live...''. Set to a poem by Lee Won-su, it is regarded as the archetype of Korean lyricism.'),
('pieces', 344, 'description_en', 'dc618f0e29ca103b4e977cacbfe3790729e1d5ef1e823fca6b24b6f9da75b397', 'Composed in 1921, the oldest surviving original Korean work for violin. According to an anecdote, it holds Hong Nan-pa''s own tragic love story.'),
('pieces', 345, 'description_en', 'c9595f13af4e991b39189e6e8eede2f8fc595b1f8f3be5e9f403317abf47a19a', 'An opera based on the classic Korean novel Simcheongjeon. Premiered as the opening work of the cultural festival of the 1972 Munich Olympics, it brought Isang Yun worldwide fame.'),
('pieces', 346, 'description_en', 'd5a52a1f89ba97533901b766de941214e4d89b8846c98b52a339c32305b2dadc', 'A masterpiece that reveals Isang Yun''s deep understanding of the cello. He conceived it while imprisoned after the East Berlin Affair, and the cello''s sobbing ''nonghyeon'' technique (a Korean way of wavering the pitch) is outstanding.'),
('pieces', 347, 'description_en', 'ff2551c041442344524c23fb1225cc9e1f40af09a85fba2143e3909180b23ba0', 'Based on the idea of ''ye-ak'' (ritual and music), a representative orchestral work by Isang Yun that realises the solemn, slow breathing of court music with a Western orchestra.'),
('pieces', 348, 'description_en', 'd58b31be5c9d34e4f24ae11a1c87db9975f4a5889937ba77cff2ee64012779b6', 'Piano etudes that create an original sound by combining the twelve-tone technique with the sigimsae (ornamentation) and grace notes of Korean traditional music.'),
('pieces', 349, 'description_en', '09c03e9a7dda0369ab2960d34273a3efd583920f0d4bd19ddf32bb5d4b39346b', 'The first of a triptych of staged cantatas, composed on secular poems found in a medieval monastery. Primitive, intense rhythms are its hallmark.'),
('pieces', 350, 'description_en', '52e08a8cbc4ee7b9f5dc7d4c88e9e5be5b21a40259c94e8bae53d8976ba9a435', 'The chorus that opens and closes Carmina Burana. With its majestic, overwhelming melody singing of the whims of the goddess Fortune, it is the most famous piece of 20th-century classical music.'),
('pieces', 351, 'description_en', '1569fd6cc30bcd3784609f5c7795eaf7bf51c6f7fd6d521f79b0ad48686a4b70', 'John Cage''s most famous and most controversial work. For 4 minutes 33 seconds the performer sits in front of an instrument (usually a piano) and plays nothing. It presents ''sound within silence'' (the noise of the audience and so on) as music.'),
('pieces', 352, 'description_en', '9a2aaf84aac4775aa516e04c077bfa68e27241e16e344743fdecc547244dc5d2', 'Screws, rubber, bolts and the like are inserted between the strings of the piano to make a ''prepared piano'', and the work uses it to pursue percussive, Eastern-sounding timbres.'),
('pieces', 353, 'description_en', 'd6dfa93185dea5137897fc88bc0332d16bea4cf5b2016e9e66e2aa4227fd48e7', 'A grand work in four acts and five hours that opened the era of ''minimalist opera''. An innovative work made up of repeating figures and images, with no plot.'),
('pieces', 354, 'description_en', 'cd149fb0a2202056a00a52654f930e7f654a41a045c26081afc1eb4a03f3e40f', 'One of the most famous of Philip Glass''s piano etudes. It is characterized by an endlessly repeating right-hand arpeggio and shifting left-hand harmonies.'),
('pieces', 355, 'description_en', '91e081e985c61d8f152fb5096a5e1ba4cca8253a7c6f181255c4efaf2da66a95', 'Music composed for the film The Hours. Glass''s characteristic repeating piano figures effectively conveyed the film''s melancholy, introspective mood.'),
('pieces', 356, 'description_en', '64f05a259faf37042d46c68ebf17736d2c50ae8d7199164f44e264dfb1ef95cc', 'An educational masterpiece that introduces every instrument of the orchestra (woodwinds, brass, strings and percussion) through variations and a fugue on a theme by Purcell.'),
('pieces', 357, 'description_en', '2c89e242efb70e379597e307e95e10a797b6c3a230f940107d9cc14d87ac497a', 'The greatest masterpiece of 20th-century English opera. It portrays the tragedy of Peter Grimes, a fisherman isolated from his village. The four ''Sea Interludes'' are especially famous.'),
('pieces', 358, 'description_en', 'ee40597138a47ff4b29f301b3956974bc0e683d84b0d1984717bbf8df8e98f1b', 'The finest requiem of the 20th century, composed for the rebuilding of Coventry Cathedral, which was destroyed in the Second World War. It interleaves the text of the traditional Latin Mass with the anti-war poems of the First World War poet Wilfred Owen.'),
('pieces', 359, 'description_en', '82002513e767da807c8d552eae9469fb2795a2a84f1bf684024007a617a6c158', 'The first of three cello suites composed for the cellist Mstislav Rostropovich, inspired by Bach''s unaccompanied cello suites.'),
('pieces', 360, 'description_en', 'df57c80a4d878412c65b196be5c9440c1aaf9d5d5def648c24a680aa26992f71', 'A chamber work composed and premiered in a German prisoner-of-war camp during the Second World War. With its unusual instrumentation of violin, cello, clarinet and piano, it depicts the ''end of time'' of the Book of Revelation in a mystical way.'),
('pieces', 361, 'description_en', 'd03dd00459c239ac8ffed20a6342e01a9b0603beff028a814e917a9b2d329902', 'A set of twenty piano pieces that view the birth of the infant Jesus through twenty different gazes (the Virgin Mary, angels, stars and so on). It is the essence of Messiaen''s piano music.'),
('pieces', 362, 'description_en', '673b654519d638be2ca7dc89a7a218e569d35dd00797bfa35715d20a8a7da69c', 'A huge symphony in ten movements, whose title means ''love, time, life'' and the like in Sanskrit. A piano and the ''ondes Martenot'' (an early electronic instrument) are used as solo instruments.'),
('pieces', 363, 'description_en', '1c3dcdf38fc06215c293040957fe96f53d20b48bc98a6daa730ee8d04ac77e86', 'Thirteen piano pieces composed on birdsong that Messiaen transcribed throughout France. An original work that reproduces birdsong on the piano.'),
('pieces', 364, 'description_en', '8cfa8e55f8047d0d23270150aafc9f3a11b61a7f0752d634beed0a220d8616b2', 'The greatest masterpiece of 20th-century Expressionist opera. In atonal music it portrays how the poor soldier Wozzeck is gradually driven mad by social oppression, commits murder and is destroyed.'),
('pieces', 365, 'description_en', 'ea98cffc1fd97522829422ed93f4b38debc14f049f68e1aa1c03d2d2a04f15e5', 'Berg''s last work, left behind at his death. Although it uses the twelve-tone technique, it combines a Bach chorale with Romantic lyricism to express deep sorrow and beauty.'),
('pieces', 366, 'description_en', 'ae86be3b2678f733c343cf33103f5d82c362bf0476b0184b3c262ae04f02743e', 'A suite in six movements for string quartet. Composed with the twelve-tone technique, it is a passionate, lyrical work that holds Berg''s secret declaration of love.'),
('pieces', 367, 'description_en', '555a9c78b3a410e7dc00048f91f0fb86bfe6b7a671ca0faa910d88f275f7a04f', 'The peak of Webern''s twelve-tone technique. Played by only nine instruments, it is marked by extremely restrained ''pointillist'' sound and a symmetrical structure. Its running time is about 10 minutes.'),
('pieces', 368, 'description_en', 'c66da992c4ccc0e51608a51b3b0d1c62e865ed7b3bc3546fd2dcb17bafb3268d', 'An early work from Webern''s ''atonal'' period. It consists of five extremely short (aphoristic) movements and is a radical short work that destroys traditional harmony and form.'),
('pieces', 369, 'description_en', 'db3066f27c3546dbd3f72ca8d63c7be23ba80bf13dd116c5cd6ac5164e7d15e0', 'An orchestral work from the atonal period. Each movement is very short, and timbre itself (Klangfarbenmelodie) is treated as an important element of the music.'),
('pieces', 370, 'description_en', '4dd2bece1fa0133377d19bd8b2ccdbecd68e731d52f28ad47e368b2e5af29ce7', 'Ives''s most famous and most philosophical work. Over hushed strings (silence), a trumpet poses ''the question of existence'', and the woodwinds answer it in confusion (mockery).'),
('pieces', 371, 'description_en', 'cb62a68d4b6162a110308eaf1c45fe922ffdd60708a7a71defacc29c7c7f05bd', 'Ives''s most experimental large-scale work, in which complex rhythms, polytonality and collage techniques are all deployed. It was so complex that it was not given a complete premiere until 1965, fifty years after it was composed.'),
('pieces', 372, 'description_en', '70bdf76fb21443029c2341b6d35553d9044440ca47932ae0f24c687aec930987', 'A piano sonata in four movements portraying the American Transcendentalist thinkers (Emerson, Hawthorne, Alcott and Thoreau). It is filled with extremely difficult, experimental techniques (dissonance, atonality).'),
('pieces', 373, 'description_en', 'cfa0e9c82bafbe0b1e2a5af538486f9f92cc25637a73b45131fa7e1cc1728f49', 'An orchestral suite depicting three places in New England in the United States (a Revolutionary War monument, Putnam''s Camp and the Housatonic River). Its ''collage'' technique, in which several melodies sound at once, is famous.'),
('pieces', 374, 'description_en', '390bc46e7c94a69cb08d0694016a0296ec967486d6c312c1b6b6548a6ac4ba55', 'Piazzolla''s signature work, which introduced his ''nuevo tango'' to the world. A compound of ''Libertad'' (freedom) and ''tango'', it announces a new style that breaks away from traditional tango.'),
('pieces', 375, 'description_en', '224f181e3ea7b317ba037cdbdddc5cfe07d7eb66177c3b2585d339d948d932c6', 'A piece loved for having one of the most lyrical and plaintive melodies of all Piazzolla''s works. It was used on the soundtrack of the film Enrico IV.'),
('pieces', 376, 'description_en', '86341b8a96f92ebf1b31657957127bc150524f67e0a7028dee9d44517f88d249', 'Composed in memory of his father''s death, and Piazzolla himself counted it as his ''finest work''. Fierce rhythms and anguished melodies alternate.'),
('pieces', 377, 'description_en', '9b3021a8c5089d131c0e6a4ccbabf34c936016806e9e7a39a9c2b02765d19ed1', 'A tango-version response to Vivaldi''s The Four Seasons. It portrays the four seasons of Buenos Aires in four tango works (''Winter'', ''Spring'', ''Summer'', ''Autumn'').'),
('pieces', 378, 'description_en', '22b9621a58d21a31f3b5b5abd3765a088205755840b5762cfd8e9053a66bb7a5', 'Satie''s most famous piano piece. The first of three short pieces written while imagining the festivals of ancient Greece (the gymnopédies). Simple and dreamlike, it is regarded as a forerunner of minimalism.'),
('pieces', 379, 'description_en', '42e5ad4081b7d4994639703915245488f9633f551b97e5db96e393b97581e56e', 'One of six short piano pieces inspired by the ancient Cretan palace (Knossos). Like the Gymnopédies, it creates a mysterious, exotic atmosphere.'),
('pieces', 380, 'description_en', '69c3914b1a4094301f84fd83188ba113363b91358cae7fa934cde78444fadf07', 'A popular chanson (waltz) that Satie composed for a cabaret singer. It shows Satie''s cheerful, sentimental side.'),
('pieces', 381, 'description_en', 'f14dfe21261cb88794dbc686f42ac182a86b3dedb33ff6816e7d9b9b9655f16c', 'A fierce dance of Armenian warriors from the last act of the ballet Gayane. Along with ''Boléro'' and ''O Fortuna'', it is one of the greatest hits of 20th-century classical music.'),
('pieces', 382, 'description_en', '9ecb378f757b081f0c504b976542dcc9b8148e7eada5f66e5cc165a7d1e2b1ad', 'A ballet in three acts about the revolt of the Roman gladiator Spartacus. The ''Adagio of Spartacus and Phrygia'' is famous for its sensual, grand melody.'),
('pieces', 383, 'description_en', '550447feeedb7878397bbe51bb7183d316c08b3e0c86827461beda506fc94f92', 'A brilliant violin concerto full of the exotic melodies and rhythms of Armenian folk music. It is one of the major concertos of the 20th-century repertoire.'),
('pieces', 384, 'description_en', '59a51085d1846900473b4645ad150a4d6a3a8c57609b01a9c8ecf073e0273fcc', 'A suite arranged from the incidental music for Lermontov''s play Masquerade. The ''Waltz'' movement is especially famous.'),
('pieces', 385, 'description_en', '8d27a7730011e99d32003bc7de081358633bc6e764f62584c563a88e2c3ada48', 'Nam June Paik''s early avant-garde music. It consists of various written instructions instead of a score, and is made up of actions such as smashing a piano or shouting.'),
('pieces', 386, 'description_en', '3267604359c18f77abf1580ccf45b6a9a7bd025184d1b8a291bb6a805e488d25', 'A representative action piece from his Fluxus period. Instead of playing, the performer slowly lifts the violin and smashes it down on a table.'),
('pieces', 387, 'description_en', '2c1c05e55bf5e3c127e7ea6887879a6f14c60b791c2d756463ed6d5999f520d9', 'An early piano work composed under the influence of John Cage''s ''prepared piano''.'),
('pieces', 388, 'description_en', '2e7719701e31becc30655f720b5125c3db992e943661a77b118205c7d2d3aab8', 'A gagok set to a poem by Lee Eun-sang, and one of the best-loved gagok among Koreans. It portrays longing for his hometown (Masan) in a Romantic, grand melody.'),
('pieces', 389, 'description_en', '5a4ede7f7682a114b97d57e0fa9b7161ea082e275a63dcacdb2f3b114e68dcda', 'A gagok set to a poem by Jo Yeong-chul. Beginning with the words ''Oh, my beloved magnolia'', it is a brilliant, passionate song of the mood of spring and of love.'),
('pieces', 390, 'description_en', 'b50b1d3edf1535fe408c261be9a4d7cf1fca60465027f4dc23f7ec97f54d06b7', 'A gagok set to a poem by Kim Dong-hwan. It opens with the words ''My heart is a lake'' and is a lyrical song of love like a calm lake.'),
('pieces', 391, 'description_en', 'ab858f592e6c96c12eae80e0a6a3d75838f217acb7e11c3c387a797afad5c751', 'Kim Dong-jin''s representative orchestral work. Composed in 1968, it combines Korean melodies with Romantic orchestration.'),
('pieces', 392, 'description_en', 'c1228aa75aba9939846ac01cd1af86bbf4367195ec32d9ebae3d6fe59508b469', 'Janáček''s most famous orchestral work. It is marked by a brilliant first movement in which nine trumpets sound a fanfare, and it symbolizes the might of the Czech army and the freedom of Brno.'),
('pieces', 393, 'description_en', 'ac7a0659af3b017ca4ab2695e5318af289398f3700baea06d37b8d6557a5dabe', 'The opera that raised Janáček to the ranks of the world''s composers. A masterpiece of ''realist'' opera that grafts the ''speech intonation'' of the Moravian region onto the melody.'),
('pieces', 394, 'description_en', '240da96a905d6833be2b8d1bff83231ca5500803782a292b386c00e4ca476cd3', 'A fairy-tale-like, philosophical opera in which the world of forest animals and the world of humans intersect. It holds Janáček''s love of nature and his idea of the cycle of life.'),
('pieces', 395, 'description_en', '639ae168d4dd08cceced7acbce1bb85d0f6e2669a850e0688316a3700e2a8665', 'An original setting of the Mass that uses a text in Old Church Slavonic (Glagolitic) instead of the traditional Latin Mass. Janáček''s Pan-Slavism and intense expressiveness stand out.'),
('pieces', 396, 'description_en', '8f8436e08ba18f18825efcdeead68b782686be8409e48bb7d32fc0c116f39ccc', 'The most famous of the nine Bachianas Brasileiras. With its unusual scoring for an ensemble of eight cellos and a solo soprano, it is famous above all for its first movement, ''Aria (Cantilena)''.'),
('pieces', 397, 'description_en', '496e45d1dcd5f6c16b6a19bd74a84da1b6cb80a11f4ad14fbf04e70eb2d16987', 'The first of the twelve guitar etudes (W 235). Dedicated to the guitarist Andrés Segovia, it is essential repertoire for guitar majors.'),
('pieces', 398, 'description_en', '73840101d167f1d8fb228b7b000296fde47a89c8efa079341c5e3f4246ac179f', 'The first of the fourteen Chôros. A solo guitar piece that captures the features of indigenous Brazilian folk music.'),
('pieces', 399, 'description_en', '98028fc299387a1a475f01fe3387d92a35067916ff8ec1f5f1bf65077e07d391', 'The last (fourth) movement of Bachianas Brasileiras No. 2, a suite in four movements for orchestra. It cheerfully depicts the sound of a small country steam locomotive.'),
('pieces', 400, 'description_en', '8a542620d78eca93a403936bea2744d511eb9f66b92066d26ab1cf494f9d2778', 'A symphony in three movements reworked from the music of Hindemith''s opera of the same name, Mathis der Maler. It was inspired by the work of the Renaissance painter Matthias Grünewald.'),
('pieces', 401, 'description_en', 'df5d1a5c33402f39fea2993df617dd9c11dcd22b312ca6e9953890163e0f3fb4', 'An orchestral work based on themes from Carl Maria von Weber''s forgotten piano duets, brilliantly varied with Hindemith''s characteristic neoclassical technique.'),
('pieces', 402, 'description_en', '40974f94f8caa0622f2414fff909681d4dabb95081e10873c6a47fc45b8afe58', 'The most famous of the three viola sonatas left by Hindemith, who was himself a violist. It is at the core of the 20th-century viola repertoire.'),
('pieces', 403, 'description_en', '16172b75e6114de4a0093f516993225cba7be7ea39580aba6dacce054fd12a76', 'Poulenc''s greatest operatic masterpiece. It deals with the true story of the Carmelite nuns who chose martyrdom during the French Revolution. The chorus in the final guillotine scene is shocking.'),
('pieces', 404, 'description_en', '4b9669b665c7d33b6091343b6b27ee7ea7259be1567bb395738bf2ef17912cb1', 'Sacred music for solo soprano, chorus and orchestra. One of the masterpieces of 20th-century choral music, in which devotion and characteristically French wit coexist.'),
('pieces', 405, 'description_en', '44f6fcddaf9f7b6e9e60a77a8fd4effbdd752ba703318c820775cd9a417df888', 'An early piano piece by Poulenc, influenced by Satie. A charming piece in which simple, witty melodies repeat endlessly (perpetual motion).'),
('pieces', 406, 'description_en', 'f5ee6d5a1aac0bdf527dae0d3dc51fe5ca70db369aa0c89825faad970bdcab76', 'The most important and most frequently performed of the 20th-century flute sonatas. The flute''s lyricism and Poulenc''s characteristic lightness and melancholy are in perfect harmony.'),
('pieces', 407, 'description_en', 'f6a8eebdd82fdd46d7038b38c021c989c07ca44a2dff1244d55da3c980abafb7', 'The most important work in the history of electronic music. The first ''spatial music'', it combines a boy''s altered voice (musique concrète) with pure electronic sounds (synthesizer) through five loudspeakers.'),
('pieces', 408, 'description_en', 'dc240c68c2d23bc6b150df386c6df93ba950fe9e2e7933655cc18210f1468e0f', 'A ''meditation music'' for a vocal ensemble of six. The singers sing a low B♭ using overtone technique, creating a mysterious sound.'),
('pieces', 409, 'description_en', '9ea11e2f9b6a21ad7509ec79ac5ac7f4f2357edb50f84fd0155868a1a4ed4ba4', 'Act 3 of the opera Wednesday from Light. The four members of a string quartet each play from a separate helicopter in the air, and the sound is transmitted to the ground, making this an avant-garde work.'),
('pieces', 410, 'description_en', '01301965da69b86b36df4f0638fae149006637a3b141b019878ef03ab0bf0daa', 'A representative work of late-20th-century ''postmodernist'' music. A symphony in five movements for eight voices and orchestra. In the third movement in particular, a great deal of music (Bach, Beethoven, Debussy and others) and text is layered by collage technique over Mahler''s Symphony No. 2.'),
('pieces', 411, 'description_en', '6be8f941b7af4ab186898dfbcec34957e7f361e958a153ea172a16e444e99692', 'No. 3 of the fourteen Sequenzas, a series exploring the virtuosity of solo instruments. A performance-art piece that dramatically expresses every sound the female voice can make (laughter, whispers, coughs, screams and others).'),
('pieces', 412, 'description_en', '28ecef720d1d9e144545371817fd5f73e104b61bccac9726d93e8dfbb4aa5939', 'Berio''s most popular collection: eleven folk songs from around the world, including the United States, Armenia, France and Italy, arranged for mezzo-soprano and chamber ensemble.'),
('pieces', 413, 'description_en', 'acc8a6622062dfb8723328056e5f2c92a2e71488172c52e8ec59b15cbe049649', 'Lutosławski''s early masterpiece and his best-known work. Like Bartók''s work of the same name, it is based on Polish folk songs, and every instrument of the orchestra shows off brilliant technique.'),
('pieces', 414, 'description_en', '0b225a8b76015124a4e9427e0db3887bc43fd68ac769f0c3a76df21a9ee1d093', 'Variations for two pianos on Paganini''s Caprice No. 24. Composed to be played in cafés during the Second World War, it is counted a masterpiece of 20th-century arrangement.'),
('pieces', 415, 'description_en', '357f7d495111ada112effc67d8fd881041b622db919b3f5183e8f1c07d9ac8b5', 'A masterpiece that concentrates the composer''s late technique of ''limited aleatoricism''. It is marked by passages in which the conductor gives only the broad framework and the players improvise the detailed rhythms.'),
('pieces', 416, 'description_en', '429350401b1c51a8be4e92a3824335dc25ab887ffdf4add6d3a4203338dda914', 'The main theme of Francis Ford Coppola''s Godfather trilogy. Immortal film music that holds both the melancholy of Sicily and the ruthlessness of the Mafia.'),
('pieces', 417, 'description_en', '83c944e019d24392a1076b0f3aed2fe6ec4bfd33de0f76a3c29dda9f3a59b351', 'The main theme of Franco Zeffirelli''s film Romeo and Juliet. Also famous as the song ''A Time for Us'', it shows romantic melody at its height.'),
('pieces', 418, 'description_en', '75485829e342074cb400788ad29ece885ebf6e6dfc7e79b486ab3ca8c44800cf', 'The theme of Federico Fellini''s film La Strada. The sad melody played on trumpet perfectly voices the pathos of the film.'),
('pieces', 419, 'description_en', '322e05d67deef8e580b360168278891a7926d567c3dd4f09a170c5431f70edd4', 'Innovative music composed for Alfred Hitchcock''s Psycho for string ensemble alone. The ''stabbing sound'' (violin glissando) of the shower scene became a legend of film music.'),
('pieces', 420, 'description_en', '82a242e49d980aae2c2f15196df58ae1c34e91ae9ed756d3f82d1534bb8207fd', 'Music for Hitchcock''s Vertigo. Through endlessly circling arpeggios and unstable harmony, it perfectly depicts the protagonist''s vertigo and obsession.'),
('pieces', 421, 'description_en', '9dd081d7a3225116a604859b62f4109a3179ce8f70dbc7c1ca4473a57fc02c4b', 'Herrmann''s last work, written for Martin Scorsese''s Taxi Driver. A jazzy saxophone solo expresses the city''s night streets and the protagonist''s loneliness and madness.'),
('pieces', 422, 'description_en', '4c506d058febfa944aa94f7ed12d5b2bd695e6d44c2530397cece398a13f158f', 'Released in 1966, the first Korean electronic music (musique concrète). An experimental work composed by recording and altering everyday sounds (water drops, machine noises and so on).'),
('pieces', 423, 'description_en', 'bc4493016cf716d532038628cc8615eff5d1ef9b9fd564f99ea35e9bc1062da9', 'A chamber work for flute, piano and percussion. One of the early representative works of Korean avant-garde music, influenced by Isang Yun, Stockhausen and others.'),
('pieces', 424, 'description_en', 'e1b2f6f2e21fa25b3fd41fb1cf3aa569b8e71d305050ca08947091d4d29e561b', 'A representative art song by Na Un-young. Set to a poem by Kim Tae-o, it portrays the lyricism of a moonlit night in a Korean pentatonic melody.'),
('pieces', 425, 'description_en', '4bc1225ecf19ff2a7b4345ae15f2be28f6748081d0ec67388a7da8e768861358', 'A representative hymn of Korean church music. Composed on the text of Psalm 23, it is widely sung as a four-part chorus.'),
('pieces', 426, 'description_en', '890cd86b361e439884180e3d5630604c44082e9aac0822711072da4a12abb37d', 'A children''s song set to a poem by Han In-hyeon. Beginning with the words ''Mother, in the island''s shade...'', its lyrical, plaintive melody has gone beyond the children''s song to become a favourite of the whole nation.'),
('pieces', 427, 'description_en', '97cfa2f4975101288e09dea776f1461ba3d389ab1c501c4520db6281b7fd515f', 'A representative art song by Lee Heung-ryeol. It is marked by a solemn melody that expresses the han (deep-seated grief) of the people through the image of crossing a hard, rocky hill.'),
('pieces', 428, 'description_en', '3948d6a19623d36b37c4fe6c9bce8e8fd29d0442f2ffa7618ca76cca2ecb6c7a', 'Beginning with the words ''Forgetting all the pain of giving birth'', a song that symbolizes Parents'' Day. A devout art song about a mother''s sacrificial love.'),
('pieces', 429, 'description_en', '97abb117aab92ebafc757792337badc96a02ae97819ca1e251e568ba7e706cf8', 'Jo Doo-nam''s most famous gagok, beginning with the words ''The green pine of Ilsongjeong...''. It is said to portray the independence fighters of the Manchurian plain, but there is controversy over the background of its words and music (pro-Japanese collaboration).'),
('pieces', 430, 'description_en', 'c2038f27aa7338a15fa9804a2e3782bf4b0a8a3765ee406005f9acc44169c453', 'A lyrical gagok beginning with the words ''Whenever I see you...''. It is marked by a tender melody that longs for one''s hometown and first love.'),
('pieces', 431, 'description_en', 'f25e7e69045e7b8eeaf00e1f0d5236e57293e20aa9ca4b154c635559e6f87ee2', 'A version of the ''Air'', the second movement of Bach''s Orchestral Suite No. 3, arranged to be played only on the violin''s lowest G string. Its calm, sublime melody is characteristic.'),
('pieces', 432, 'description_en', 'cda9a1f01568234062455b4ae9cc60e48bdce1b51d4dee651f861dce5735f61f', 'The most famous chorus among Bach''s church cantatas. A flowing triplet accompaniment and a serene choral melody blend together, and it is often used at weddings.'),
('pieces', 433, 'description_en', '5daaebeb9b2fa880755ddc7f6c3ecf7fd902488c743794a8865697beab8e901d', 'A piece that often appears in solemn scenes of films and dramas. The stately, solemn rhythm of the Baroque dance and its intense chord progression are striking.'),
('pieces', 434, 'description_en', '8e92b78c0a1759ad4721f46287c29dbb5103f0bd6b9009233943f573c4e4d0f8', 'The largest and most famous of Mozart''s horn concertos. The lively rondo theme of the third movement, reminiscent of a hunting horn, is widely known.'),
('pieces', 435, 'description_en', '87b6bfb42784d46cb2c4be84a29b486b24275911e1e7984f294f671e8b65179d', 'A sonata Mozart wrote for beginners, which carries the subtitle ''Sonata facile'' (easy sonata). The clear, pure opening of the first movement is a melody everyone has heard at least once.'),
('pieces', 436, 'description_en', 'af582a778f611b9471ff4e5ed7309e0fbedab3b8f64c3f3d2d910a6ebc43ff71', 'Known as the ''Twinkle, Twinkle, Little Star Variations''. Based on a French folk-song theme, it is a lovely piece that unfolds twelve varied, virtuosic variations.'),
('pieces', 437, 'description_en', '22fa17e06537b115fc30e142ee9e2f2f07624c374f3e7a3bb021b610fc7c0dea', 'Programme music in which Beethoven depicts the feelings he experienced in nature. The sounds of a brook, birdsong, a storm and more are vividly expressed by the orchestra.'),
('pieces', 438, 'description_en', '1e2064b2821811c8b7b775a2da9e966aefe848500cbc9332b4e5a2a53b642312', 'A piece whose rhythmic drive is so striking that Wagner praised it as ''the apotheosis of the dance''. The second movement, with its solemn, mysterious atmosphere, is especially popular.'),
('pieces', 439, 'description_en', 'e44ec994c06f2f117d3e87b592d7a6634e730cbd4ce12f54f46b433705f5a667', 'The brightest and warmest of Beethoven''s violin sonatas. Its beautiful melodies carry the lively spirit of spring.'),
('pieces', 440, 'description_en', 'ff5c779423e146200ce374d81da4e06b83ed7250738d80192c989e5e7f7d0ee3', 'A masterpiece among Beethoven''s middle-period sonatas, in which passionate, stormy emotion sweeps through. It demands a high level of technique and a powerful touch.'),
('pieces', 441, 'description_en', 'a58e440c1faae003b42ede09df890f4d4bb5df5431fe7e85997c2b4a86f492b8', 'A work Beethoven dedicated to his patron, Archduke Rudolph. It is considered the most grand and noble masterpiece in the history of the piano trio.'),
('pieces', 442, 'description_en', '102b349de2896c99e335117cc1f3ea17adaf702542d449f9c572f9fc2059bfe8', 'The most famous of Boccherini''s works. It is a model of the elegant, aristocratic Rococo style, and the delicate shimmer of the strings is beautiful.'),
('pieces', 443, 'description_en', '0f64aaae6c34392f1bdc001b0520f58633d7ddc60d6dc668b2b3bf75cbe90fd5', 'A song Schubert composed on an epic poem by Walter Scott. Thanks to its devout, beautiful melody, it is often performed in religious contexts as well.'),
('pieces', 444, 'description_en', '84d62738c5ac2a25b452fd74c38cdd1ae8f849570c0da1e49838abfca3de3dfd', 'The best loved of Schubert''s short piano pieces. Its charm lies in a simple, folk-like melody set over a light accompaniment.'),
('pieces', 445, 'description_en', '352b3234950a328d13f8f31fbc6b0d5a853498c6ca5072dd75acd2f1962c706d', 'Published after Chopin''s death, it is famous as the theme of the film The Pianist. Its plaintive, sad melody touches the heart.'),
('pieces', 446, 'description_en', '562bc4aa98c0209b3279a7a212f38f1e2cea7c5e358ff7e19116f5a3fbd736d2', 'The longest of Chopin''s preludes. The A♭ that repeats throughout the piece is reminiscent of raindrops falling from the eaves.'),
('pieces', 447, 'description_en', '83f6653bce23ace3baa73193ec5d98a8612b6be26823c9f0911c6d01617d89d2', 'A piece about which Chopin himself said he had ''never written a more beautiful melody''. It is marked by a lyrical melody and a contrasting, passionate middle section.'),
('pieces', 448, 'description_en', '859b27b33bd4d9e32d6780c2d13eebaff55fc3b5cb2c756eafb4a7ac09195414', 'Regarded as the greatest of Schumann''s chamber works. The piano and string quartet are in perfect harmony, and it overflows with Romantic passion and energy.'),
('pieces', 449, 'description_en', '538dd14ca865a0fc7c8e6a88851a9f5a1e68a1e394fdea4fbf052f85b6497f9b', 'A piece that stands out for Mendelssohn''s characteristic flowing melodies and balanced form. The lyrical theme of the first movement, played by the cello, is especially famous.'),
('pieces', 450, 'description_en', '4d2e051bc0bea5965155de952eb752c3b3cde4b222bad39d1c8632c94fd36774', 'A concerto that concentrates Liszt''s brilliant virtuosity. Its active use of the triangle in the orchestra has earned it the nickname ''Triangle Concerto''.'),
('pieces', 451, 'description_en', '3b45563d3cc8e104f36275ae514d2e23e0681777a00efc10de047d50d4cc9c86', 'The most famous lullaby melody in the world. Brahms composed it for a friend''s child, and it carries a simple, warm feeling.'),
('pieces', 452, 'description_en', '235d643b56a1be3dbe87baa0329670c90335f6de40a4f0bb91a7168ba4cc89c1', 'Brahms''s last symphony, a masterpiece that combines classical formal beauty with Romantic tragedy. The fourth movement, which adopts the Baroque form of the passacaglia, is the highlight.'),
('pieces', 453, 'description_en', '85e36f58bdab772119959abe90d86d6e5153fac04fdd1a6761333b32af97befd', 'The most popular of Tchaikovsky''s symphonies with the public. It portrays a struggle against fate and the victory over it, and the horn solo in the second movement is very beautiful.'),
('pieces', 454, 'description_en', '1fbbd2193be53049822f9eac7ccc77cf2b146a12659a1403f86d5c396e0f2059', 'Tchaikovsky wrote it out of admiration for Mozart. A masterpiece that stands out for its elegant waltz movement and the rich sonority of the strings.'),
('pieces', 455, 'description_en', 'f37a95dc3e65e56a0d366f8066385c0124e33ce969e7891ebd78f771d6655767', 'One of Rachmaninoff''s most widely known piano pieces. The contrast between the intense, march-like rhythm and the lyrical middle section is superb.'),
('pieces', 456, 'description_en', '9f27c25d96cd7533cd8969ba6c69d45614eb0b0940f0c80345d99e30af2d71b6', 'An early piano piece by Debussy, dreamlike and gentle in mood, as its title (''Reverie'') suggests.'),
('pieces', 457, 'description_en', 'b7c0b6d1827400a48166361b203dab1fa1d0055e720a45c943f24b57a1bf26ef', 'A violin piece Ravel made by borrowing the style of Hungarian Gypsy music (tzigane). A brilliant and difficult work that demands the highest virtuosity of the violinist.'),
('pieces', 458, 'description_en', '44890744f4f155612ee10b3e8c728613f13ea299cd2fa139f76aa4329ddc2a50', 'A bright, lively piece that Shostakovich composed as a birthday present for his son. It became even better known through its use in Disney''s film Fantasia 2000.'),
('pieces', 459, 'description_en', '264f7d1f3c025f7b6db896282cf8b61ab54071bc5800879dd7bc2bd4e47cee99', 'An early signature work of Elgar, full of English refinement and lyricism. The soft, warm harmony of the strings is soothing.'),
('pieces', 460, 'description_en', '065274c15f59f3e3eb72779df513a467dd6a517a8bb3abf60eb174babe99d32e', 'A piece that reinterprets Arirang, Korea''s representative folk song, in a modern art-song form. It is marked by Korean sentiment and grandeur combined with piano accompaniment.'),
('pieces', 2799, 'description_en', '48976aca923652a06de8c737af817d390b98c96b03f9b94ced7ff514cb7cb712', 'The first of the orchestral suites that Khachaturian compiled in 1943 from the music of the ballet Gayaneh, which is set on an Armenian collective farm. Between dances that draw on Armenian folk melodies and rhythms sits the lyrical ''Adagio of Gayane'', which was used in the film 2001: A Space Odyssey.'),
('pieces', 11293, 'description_en', '0513dd3d8bcf764aeaf2671a599683c4f6f8df015e7eb414c2d13da71c7acd1f', 'Mahler''s last completed symphony. In the first movement, which begins with a hesitant rhythm, life and death collide, and in the final Adagio the string melody gradually fades away into silence. Mahler died in 1911 without seeing it premiered, and Bruno Walter gave the premiere in Vienna the following year.'),
('pieces', 11933, 'description_en', '6d4ceb0822d4389be45d51ba237950d3e8a2116b374daaf317ec5ad5b2a0e9ab', 'Mahler''s longest symphony, in six movements and lasting more than an hour and a half. Under a plan to portray the stages of nature one after another, it begins with an enormous first movement; in the fourth movement an alto sings the ''Midnight Song'' from Nietzsche''s Thus Spoke Zarathustra, and it ends with a majestic string Adagio.'),
('pieces', 14198, 'description_en', '5d1f34f1d569b263dbe872295c5eb4fe469231216e7672a6837092601732df58', 'Incidental music written by Grieg for a production of Ibsen''s play Peer Gynt. It premiered in 1876 in Christiania (now Oslo). ''Morning Mood'', ''The Death of Åse'', ''In the Hall of the Mountain King'' and ''Solveig''s Song'' were later assembled into two orchestral suites and became more widely known.'),
('pieces', 14951, 'description_en', 'd46689252e823dfe4b66a9bc1a724320fa025fdc6cb9adcd8af95df21fb44924', 'Also called ''Actus tragicus'', an early funeral cantata by Bach. It seems to have been written around 1707, in his early twenties, during his time in Mühlhausen. It begins with a quiet sonatina in which two recorders and two violas da gamba blend, and sings of a faith that accepts death.'),
('pieces', 15339, 'description_en', 'e68cfc4da847dededc30f540c7ee2aebaa394a981bea76fe3bc9f10025ba67c2', 'A church cantata by Bach for bass solo. He wrote it in Leipzig in 1727 for the Feast of the Purification of the Virgin Mary, and it sings of the feeling that, like the old man Simeon holding the infant Jesus in his arms, one can now depart the world in peace. The swaying aria ''Schlummert ein, ihr matten Augen'' (''Sleep now, you weary eyes''), No. 3, which is like someone lulling themselves to sleep, is especially famous.'),
('pieces', 26024, 'description_en', 'e0a71c9e12286051bf5627490f21c78c698154a505c925c4f56a3de982aeb2b1', 'A three-act opera seria that Handel wrote for the Royal Academy of Music in London. It portrays the fidelity of Rodelinda, queen of the Lombards, who grieves for her husband Bertarido, believing him dead, yet in the end refuses the marriage proposal of Grimoaldo, who has seized the throne. It premiered at the King''s Theatre in London in 1725.'),
('pieces', 26025, 'description_en', '9bd703252b3dd44a5142478ab60f323db19e97d9bb8af7d3b81e51363d38b261', 'A symphonic poem inspired by Nietzsche''s philosophical book of the same title. The ''Sunrise'' introduction, in which a trumpet sounds C-G-C over organ and a low sustained note, is especially famous, and it became widely known through its use in Kubrick''s film 2001: A Space Odyssey. Nine sections named after Nietzsche''s chapter titles follow almost without a break.'),
('pieces', 26026, 'description_en', '895ba03592bf5eec0d3b6f30ed3a6094e51a54704803809b7d04096163a6bc3b', 'A requiem for soprano and mezzo-soprano soloists, two mixed choruses and orchestra. It has four parts: Introit, Kyrie, Dies irae and Lacrimosa. The Kyrie (second movement), in which twenty voices interweave in micropolyphony, was used in the film 2001: A Space Odyssey. It premiered in Stockholm in 1965.'),
('pieces', 26027, 'description_en', '01842fe6b7e3bd49193fcf1952002200e4bde26636abeeef21083d5a8f3bd6a4', 'An unaccompanied mixed-chorus piece in sixteen parts. Setting the communion text of the Requiem Mass, ''Lux aeterna luceat eis'' (''Let eternal light shine upon them''), the voices sing the same notes slightly out of step, so that the harmonies overlap and dissolve as if blurring. A representative work of Ligeti''s micropolyphony, it was used in the film 2001: A Space Odyssey.'),
('pieces', 26028, 'description_en', '849e9357a3d2bfbcfcc4393ae1119aaa7b5266a24dd1ddbbdc066f25cc1b7d7f', 'An orchestral work built not on clear melody and metre but on huge masses of sound. Each instrument takes a different note to form a dense cluster, and its colour and density change slowly. Premiered at the Donaueschingen Festival in 1961, it made Ligeti''s name known and was used in the film 2001: A Space Odyssey.'),
('pieces', 26029, 'description_en', 'c6475c0a2307d60ebd1290afb4f00c90575f68d65523775cd0f1bfa3b0012626', 'The largest and most intense of Beethoven''s violin sonatas. The violin and piano confront each other as equals, like a concerto. Beethoven first wrote it for the violinist George Bridgetower, but it acquired its present name when it was dedicated to the French violinist Rodolphe Kreutzer.'),
('pieces', 26030, 'description_en', 'd30607d91829d0d27d4d21351fa729b27aee5dbb6878d038579ffc94bfd71c55', 'A piece for violin and orchestra that Saint-Saëns wrote for the Spanish violinist Sarasate. A melancholy introduction is followed by a rondo with Spanish rhythms that unfolds brilliant virtuosity. It is also often performed in the version for violin and piano arranged by Bizet.'),
('pieces', 26031, 'description_en', 'd44e58440f413cfc1597c9524b67e32312415b55adc55aed6314036e3b99d944', 'Rachmaninoff''s 1921 arrangement for solo piano of Kreisler''s short violin piece Liebesleid (''Love''s Sorrow''). To the wistful Viennese-waltz melody of the original he added his characteristic dark harmonies and countermelodies, making a piano piece that is deeper and more brilliant than the original.'),
('pieces', 26032, 'description_en', '9be8b3107ed38f930025f864f177855701fdda542ae0dabb0c86685216935995', 'Liszt''s arrangement for solo piano of ''Widmung'' (''Dedication''), the first song of Schumann''s song collection Myrthen, which Schumann presented to Clara before their marriage. It keeps the song''s melody intact while building it up with wide arpeggios and octaves, turning a declaration of love into grand piano music.'),
('pieces', 26033, 'description_en', 'f2e2a436cd0e3e692a5752ca791c6617cf97541000be142db42d29304ccf4d57', 'A piano duet for four hands that Schubert wrote in 1828, the year he died. It begins with a tender theme in F minor, passes without a break through a Largo, a Scherzo and a fugue-like finale, and returns to the opening theme. When it was published after his death, it was dedicated to his pupil Caroline Esterházy, whom he had held dear.'),
('pieces', 26034, 'description_en', '70b7d2c24ea3e2cf5b712c3332ecf4b7c42a374f2cd83889c29e0e189afeb43f', 'A collection of twelve piano pieces, one published each month throughout 1876, commissioned by the music magazine Nouvelliste. From January''s ''At the Fireside'' to December''s ''Christmas'', it portrays the scenery of the twelve months of the Russian year. June''s ''Barcarolle'' and November''s ''Troika'' are especially loved.'),
('pieces', 26035, 'description_en', 'd494b608c7fbe24b50d3a63ddb3bc857f6a5ea9845c256e74da4b4787f6ce4e1', 'A sonata for piano four hands that Mozart completed in Vienna in 1787. It has a first movement in which the two players trade the themes with energy, a second movement that flows like song, and an elegant rondo as the third movement. It is a mature four-hand work in which the two parts confront each other as equals, like a concerto.'),
('pieces', 26036, 'description_en', '8dcaf42b7c0dc124c83462a11aa7299663483f34564a649832cbf5e8dbec8b21', 'To a polonaise that Chopin had first written for piano and orchestra, he added a calm Andante spianato, written for solo piano in 1834, to make a single work. From the lake-still opening in G major it passes through a fanfare into the brilliant, majestic polonaise in E♭ major.'),
('pieces', 26037, 'description_en', '5d3cb639ec948ebe290d5bad0215058279c21e32917e48e298a523c44bd6d872', 'A suite in which Ravel orchestrated in 1911 his piano duet written for the young brother and sister of a friend. Based on Perrault''s fairy tales and others, its five pieces, ''Pavane of Sleeping Beauty'', ''Hop o'' My Thumb'', ''Laideronnette, Empress of the Pagodas'', ''Conversations of Beauty and the Beast'' and ''The Fairy Garden'', depict scenes from fairy tales in delicate colours.'),
('pieces', 26038, 'description_en', '7b45a173f94b79ac90536f0d66f32fb241508147ce595fd0804f6daed0e47c8c', 'A chamber cantata by Vivaldi for alto solo, strings and basso continuo. Two recitatives and two arias convey the lament and anger of someone tormented by a heartless lover. The first aria, ''Ah ch''infelice sempre'', in which pizzicato and bowed strings overlap in a sobbing flow, is especially famous.'),
('pieces', 26039, 'description_en', 'a13a93dcb94540ffb2e024c8a52f55b988d3aaf0edaec07ad5c38f563df8293e', 'Vivaldi''s ''ripieno concerto'', played by string ensemble and basso continuo alone, without a solo instrument. A short piece in three movements, fast-slow-fast, it condenses the characteristics of Vivaldi''s concertos, such as vigorous rhythm and sharp contrasts of dynamics.'),
('pieces', 26040, 'description_en', '4e1e737381f31b6ce65817832f92c737dd9409517710bdc4cbcefdb865e604a6', 'Vivaldi left more than thirty concertos for bassoon, and this is one of the more frequently performed among them. In the dark key of E minor, the bassoon shows both the weight of its low register and agile leaps, in three movements, fast-slow-fast.'),
('pieces', 26041, 'description_en', '41ef57a724cde64750d11f692a2fae36a175d8a718dd85d6b38c96f522c2a38a', 'A symphony Mozart wrote at 17. Only two of his symphonies are in a minor key, this one and No. 40, so it is known as the ''little G minor symphony''. The passionate first movement, driven by syncopation, became widely known when it was used in the opening scene of the film Amadeus.'),
('pieces', 26042, 'description_en', 'ab3c05997b34eab07f3f47f8b09ed3069d92d752ee722bef8ebeb4792e0fd78c', 'A large-scale serenade in seven movements for twelve wind instruments and double bass. Oboes, clarinets, basset horns, horns and bassoons blend, and the Adagio (third movement) was used in the scene in the film Amadeus where Salieri, looking at the score, confesses that he seems to have heard the ''voice of God''.'),
('pieces', 26043, 'description_en', 'f4269815ccdc27842358679194a2c2263a241211738db0aff4a4f8df04d8666a', 'Mozart''s two-act opera to a libretto by Da Ponte. It portrays the debauchery and downfall of the philandering nobleman Don Giovanni, moving between comedy and tragedy. It premiered in Prague in 1787, and the highlight is the Act 2 finale, in which the Commendatore, now a statue, appears and drags the unrepentant Don Giovanni to hell.'),
('pieces', 26044, 'description_en', '24dab47bd13cc042929febf431c822216adfd25f040ce7b1ea5f4a5c655a559b', 'Barber''s arrangement for string orchestra of the second movement of his String Quartet, Op. 11, written in 1936; it was premiered by Toscanini and the NBC Symphony Orchestra in 1938. The slow melody builds step by step to a climax and then breaks off into silence, and the piece is often played at memorial occasions.'),
('pieces', 26045, 'description_en', '3f73c5734bf3c297b0fb9d2ebaa57424238cbcba85b6cf1049b7b25cf035443b', 'A song for which Mussorgsky wrote the music in 1865 to ''Sleep, peasant''s son'', a song from the play The Voyevoda by the playwright Ostrovsky. A Russian-folk-style lullaby for a peasant baby, it is one of his early songs, and two versions survive.'),
('pieces', 26046, 'description_en', '1f009100eb6631f78fa78ed3382aa73cda921fc395ce3d382a3335b68323d5a6', 'A sonata Mozart wrote in Vienna in 1781 to play with his pupil Josepha Auernhammer. A bright piece in which the two pianos share the themes and trade them, shining as if in competition. It is one of the few works Mozart left for two pianos.'),
('pieces', 26047, 'description_en', 'e531c6f5add14bd8bb310f9700e19c7ac611567d5021de815620c441a577e4d3', 'A late work by Chopin named for the songs of the Venetian gondoliers. The left hand keeps up an accompaniment rocking like waves in 12/8, while the right hand sings a melody doubled in thirds and sixths. Written in 1845-46, it is his only barcarolle.'),
('pieces', 26048, 'description_en', 'f08b5ed73cde67112d4058c64ff11f846dcac9432ed0fd8074b8c5d98e664de7', 'The first of the Op. 10 etudes, which Chopin dedicated to Liszt. The right hand runs ceaselessly up and down widely spread arpeggios across the keyboard, while the left hand supports it with a weighty bass melody in octaves. Because the hand must stretch wide, it is counted among the most difficult etudes.'),
('pieces', 26049, 'description_en', 'b5798b6c5e6ddeafd7b7c73a861356670ba87f61b9fe111b4324edbb3e661ead', 'Chopin''s piano sonata, widely known for its third movement, the ''Funeral March''. The march was written first, in 1837, and the other movements were added at Nohant in 1839 to complete the work. After the passionate first movement, the scherzo and the Funeral March, the short finale in which both hands rush in unison is startlingly unconventional.'),
('pieces', 26050, 'description_en', '9981f99d5817c457afeeb117ca3f1a4344a66d2f69547935e536f7b511c75d43', 'Chopin''s last piano sonata, completed at Nohant in 1844. It has a more classical balance than No. 2, and passes through a majestic first movement, a light scherzo and a Largo that sings like a nocturne before ending with a fiery rondo finale. It is among the largest of his solo piano works.'),
('pieces', 26051, 'description_en', 'a6d17ec8b9f14cb5b5027968df49a71bdde54e3a1390187f3a5c0b9062df7d65', 'An orchestral work based on Goethe''s poem The Sorcerer''s Apprentice. It vividly portrays the story of an apprentice who, while his master is away, uses a spell to make a broom fetch water and, not knowing how to stop it, floods the house, with a comic theme led by the bassoon. It premiered in Paris in 1897 under Dukas''s own baton.'),
('pieces', 26052, 'description_en', '50305afc8669f5b786acc1d36c92303bcc8b333a3acf17ed12acd3cc55cdba1b', 'A symphonic poem that forms the ''Roman trilogy'' with Fountains of Rome and Roman Festivals. Without a break it depicts four scenes of pines: at the Villa Borghese, near a catacomb, on the Janiculum Hill and along the Appian Way. At the end of the third section a recording of a nightingale is played, and in the fourth the march of a Roman legion approaches in a huge crescendo.'),
('pieces', 26053, 'description_en', '050df0858b19c3cfa1fb492f64630e2994196a1ddda32a38fae9cdc6b9bcaf4f', 'A three-act opera based on the legend of the Dutch captain cursed to wander the seas for ever, who is redeemed by the love of Senta, a woman faithful to the end. It premiered in Dresden in 1843 under Wagner''s own baton. The overture depicting the stormy sea and ''Senta''s Ballad'' are famous.'),
('pieces', 26054, 'description_en', 'f1767c22a37d38e541ddb7d86e80e6960238333f685e29aa119363cbd133f0ea', 'A five-act grand opera about the tribune Rienzi, who in 14th-century Rome rose against the nobles to become leader of the people and then fell. Based on Bulwer-Lytton''s novel, with a libretto Wagner wrote himself, its 1842 Dresden premiere brought him his first great success. The overture, which begins with a trumpet signal, is often played separately.'),
('pieces', 26055, 'description_en', 'f5fd4f654c8e9a05c9d84d40e480175ad773d3015c82f625918b2e246ae462d8', 'A three-act opera in which the knight Tannhäuser, who had given himself to pleasure in the grotto of the goddess Venus, reveals this at the Wartburg song contest, sets off on a pilgrimage, and is redeemed by Elisabeth''s sacrifice. It premiered in Dresden in 1845, and for the 1861 Paris production Wagner newly wrote sensual ballet music for the Venusberg scene in Act 1.'),
('pieces', 26056, 'description_en', '485414fcd51dc9bea549b0c68a7fa5242882f23973f08cb0d67bdc0d8d280ca1', 'A symphony to which Bruckner devoted the last few years of his life but which, because he died before finishing the fourth movement, remains in three movements. It is said to be dedicated ''to the dear God''. A mysterious first movement, a scherzo that hammers down roughly and a majestic Adagio follow, and it premiered in Vienna in 1903.'),
('pieces', 26057, 'description_en', 'cd7d40afb9dabab75d678be8e9df80ca173cea621105b07faacd4c45e00e318f', 'The Norwegian composer Halvorsen''s arrangement for violin and viola duo of the passacaglia, the last movement of Handel''s harpsichord suite in G minor, HWV 432. To the short theme of the original he added brilliant variations, making a concert piece in which the two string instruments trade breathlessly. It is also often played on violin and cello.'),
('pieces', 26058, 'description_en', '35c1a5235b0cb898d967a02665ec4e2cc47cc6563a3e3fc6bf3bb82f7d04b647', 'A concerto Mozart produced in March 1785, a month after completing No. 20 in D minor. Between a stately, march-like first movement and a light finale lies the second movement, an Andante, in which the piano sings dreamily over muted strings. The second movement was used in the 1967 Swedish film Elvira Madigan, and the film''s name stuck as the concerto''s nickname.'),
('pieces', 26059, 'description_en', 'c21887ea2aabc9ee2cb982459fdf6e61c22982b7685491e4f833757ef2434fdf', 'A two-act ''sailors'' drama'' that Mascagni wrote after the success of Cavalleria rusticana. Based on a novel by Alphonse Karr, with a libretto by Targioni-Tozzetti, it premiered at La Scala in Milan in 1895. It is rarely staged today, but the barcarola that follows the tenor aria is often recorded separately.'),
('performance_sectors', 7, 'description_en', 'b09402e158645481a295d2728ad30913ea8f298a5896f669d6c75ae072aadb03', 'The things to listen for are the heavy octaves of the opening Largo and the sad Moderato melody that follows. Pianists differ enormously in how they convey the weight of the first note and the sorrow of the melody.'),
('performance_sectors', 7, 'name_en', '8407cba452d33b5be1f718b549984b229dea40d650fa7c4c31034903845feb23', 'Introduction & First Theme'),
('performance_sectors', 8, 'description_en', '4691fef6f0ea33197d6dad559242117571a9064108fbf4e2f5db28268e7d8036', 'After the turbulent first theme, the mood changes completely and a dreamy melody in E♭ major appears. It is regarded as the most beautiful passage in Chopin’s Ballade No. 1.'),
('performance_sectors', 8, 'name_en', '8a7bc71da167b2f13dae4a59abe4f173bbdc7768b3355d52934412ae86eec48c', 'Second Theme (Meno mosso)'),
('performance_sectors', 9, 'description_en', 'dc2b0e9ba6e7ab26022c9fd756be5e0015d219515d07bc3265df259551bfdd14', 'Explosive chords arrive under the marking “Il più forte possibile” (as loudly as possible); after a brief pause to catch its breath, the music races ahead in a frenzy.'),
('performance_sectors', 9, 'name_en', 'eb44a6ad891dc2199d9d9df9332dded8b553ed78eb907d58bda77d25bf4fb460', 'Coda (Presto con fuoco)'),
('performance_sectors', 11, 'description_en', '2767182007ddd3606c54553a51e9f07bebfe29d48116c24c97651ea7ca244fda', 'Rachmaninoff Piano Concerto, first movement.'),
('performance_sectors', 11, 'name_en', '69fbbcbdfcb0605a0500c9b92092d50a211c5e4d2b082bde5884a27976ac9271', 'Movement I'),
('performance_sectors', 12, 'description_en', '744f600f7a06c289fa2620bedcb93d771b30dc7e4019786d1c39530b81c40b7b', 'Rachmaninoff Piano Concerto, second movement.'),
('performance_sectors', 12, 'name_en', '2af682bdf2a475224bc14fb1fa4afde64518a4286290869f2d397c9e5bd07c7c', 'Movement II'),
('performance_sectors', 13, 'description_en', '1f8ab6d31a07c1ab8d7c83d0c29980d423b3765dca0d0a45c669d37667fe503b', 'Rachmaninoff Piano Concerto, third movement.'),
('performance_sectors', 13, 'name_en', 'c733dc067278855093540b371891e7ea3b7a335c60015718b13c278ea166b960', 'Movement III'),
('performance_sectors', 14, 'description_en', '3c92d325f76efdef7ec00f957a139943ee5dc33306aa377be80d50e3e359b664', 'Pianists choose between the ossia and the original version of the first-movement cadenza, which makes it a good passage for comparison.'),
('performance_sectors', 14, 'name_en', '7d76000ba38d0ca4bdd766af97fee8a5eb3ec08d641c7f4eb27adaba38a6aacb', 'Movement I cadenza'),
('performance_sectors', 17, 'description_en', 'a2b1b31289620eba8b688c84e85f06ccb4c521f9b6138060d3891d90168fb1df', 'A comparison of the highlights of the second movement.'),
('performance_sectors', 17, 'name_en', '2af682bdf2a475224bc14fb1fa4afde64518a4286290869f2d397c9e5bd07c7c', 'Movement II'),
('performance_sectors', 18, 'description_en', '3a5e77f2e101da6a677efeeb651c4b2aa952d0bd01d15fab52aa00ea665067d2', 'From the climax of the second movement to the finale of the third.'),
('performance_sectors', 18, 'name_en', 'f772d8f66eb0f06b98a7daa4f3812cafd857bb46bb7542058e9a171781f847aa', 'Movement III, climax'),
('performance_sectors', 19, 'description_en', '654303c55e336a323f1df67c4ecc3dd8bbbc8f4bc3cc8d8244b5a3b30ae41d53', 'The introduction to the second movement.'),
('performance_sectors', 19, 'name_en', '9fecb04d0c2e409c05257ebdfe76ccdaf4141e0cceb442de7c3e6d169e353c0e', 'Movement III, introduction'),
('performance_sectors', 25, 'description_en', '235bc5654400bcb544f27ab45ce9e1c0e19ace267a408b74775cfc50556f6ef0', 'Prelude No. 7 of the 24 is a sixteen-bar, mazurka-like miniature in A major. Short phrases with the same rhythm follow one another eight times, and in the middle of the second half one widely spread chord rings out. Performances differ in **how much they hold back the phrases before that chord**.'),
('performance_sectors', 26, 'description_en', '5bd0b8889e4ffafd38c198dc80c8ee1c795eddb9d7f8a5acfd74be48a6a3ba27', 'Variation 1 is a 3/4 variation in which two voices chase each other. The score asks for both the first and second halves to be repeated. **Gould skips both repeats**, which makes his the shortest version of this variation, at 1:10.'),
('performance_sectors', 27, 'description_en', '6fbe2cf9816300e8ad2cbe44e2c682d242e160ed1ea5696ecbb10f20912ec2a8', 'The first piece of Grieg’s Lyric Pieces, Arietta. A high melody sings while a calm figure flows beneath it. After the melody rises once to a big moment, it returns to the first theme and closes quietly. The three performances differ most in **how loudly the first note is played**.'),
('performance_sectors', 28, 'description_en', '545b6949ccd41777b72363181d917f3b02d498628985c8ccc1eacaf7b3315adb', 'A short Étude in G♭ major, lasting about a minute. The right hand moves without pause between two successive notes and short, detached octaves; the music swells in the middle, then the first motif returns and the piece closes on a motif that climbs upward. All three performances last about a minute, and they differ in **whether the build to the middle happens in one go or after stepping back once**.'),
('performance_sectors', 29, 'description_en', '37aa74def13ecf3815a752acd81462a01e13df3388d1333a2654f530ffe2fa54', 'A piece in B minor depicting a game of tag. Fast sixteenth notes run as if chasing and being chased, and in the opening section a gesture repeats in which the first note is struck hard and immediately drops to soft (sfp). It lasts only about 30 seconds, so performances differ in **how fast it runs and how loudly it ends**.'),
('performance_sectors', 36, 'description_en', '9b6c1a3a070cc36e2049cd5cd498b5a8fb86deb1474b462d3b8db4864d4951f9', 'The very beginning of the work. A high D♯ rings like a bell, and the right hand leaps between that bell and the melody below. The score says to play softly but keep the theme clear (ben marcato). The three performances differ most in **how closely they keep to this “softly”**.'),
('performance_sectors', 37, 'description_en', '17028fe81f1593ebdc1abc852295ae1377ce34c8538162d4a12919e6db8e2e62', 'The last 20 seconds or so, where octaves and chords come crashing down. Performers differ in whether they play at full force from the start or build up toward the end.'),
('performance_sectors', 39, 'description_en', 'a42c97e224f33619155c466f89db773cdbcaeb17a69e6614740553b2b99e3dbc', 'The opening of Tchaikovsky’s Concerto No. 1. The horns call out briefly in B♭ minor, then move to D♭ major, where the strings sing the big melody and the piano supports it with wide chords. This melody never returns after the introduction. All three performances are loudest in the first 10 seconds, and they differ in **how far they bring the volume down afterward**.'),
('performance_sectors', 40, 'description_en', '9aa41aa5662f8da215714b45b1c4cf2628c394f8c0be88f6164a6149904eb1ce', 'Coming straight from the previous movement without a pause, the finale bursts out in a C major tutti. The trombones, piccolo and contrabassoon join here for the first time, and the first theme, which climbs up the tonic chord, rings out thickly. Each performance holds **the loud playing for a different length of time**.'),
('performance_sectors', 41, 'description_en', 'e9686396f3d60df43d02b21a1f79061342e5caaa9986cbf09f12eeda5ee4f69e', 'The opening of the Fifth Symphony. The four-note motif is hammered out twice, followed by a long pause, and then the strings pass the motif back and forth softly, building it up. All three performances share this shape, and they differ in **how deeply the quiet passage sinks**.'),
('performance_sectors', 47, 'description_en', '2eb0cbf19f255590e9014d34e60f62a77754f360f41c9022ebd178e017c46171', 'A short waltz also known as the “Minute Waltz.” It begins with a figure in which the right hand circles round and round the same spot; a melody sings leisurely in the middle, and the circling figure returns for a brief close. Some performances put **the loudest moment** early, others after the circling figure has returned.'),
('performance_sectors', 49, 'description_en', '34533864631fdae44961142196253050f463389d68a1f49afc525bc3fe7f0e68', 'An étude that begins with a slow E major song, surges fast in the middle, and then returns to the first song. The right hand alone sings the melody on top while also playing the accompaniment beneath it. In the middle both hands move quickly in double notes and rise to the loudest point. The three performances differ most in **how softly the first song is kept**.'),
('performance_sectors', 51, 'description_en', '5d65c31ce43fe95a19d4adbe375e3751dd4bdb2feee77a647363833034c848f7', 'Over a slow triple meter, the left hand alternates between a low bass note and a chord while the right hand lays a plain melody on top. The accompaniment begins first and the melody then enters; the same course is followed almost exactly twice, with only the ending different. Performances differ in **how loudly the piece ends**.'),
('performance_sectors', 55, 'description_en', '95e9d921ede4bb1e9265d3df31350f9af9d0b6092d74426b67ccd25118e97bba', 'The complete Moments Musicaux No. 3 by Schubert. Over a short, detached left-hand accompaniment, the right hand lays an F minor dance melody; it is a miniature of about two minutes. When it was first published it was given the title “Air russe” (a Russian-style song). Performances place **the loudest moment** differently.'),
('performance_sectors', 56, 'description_en', '495cc1c0410e698c3f683ac19b0bfa4fa9b6cf43d78f03aedcf23d5ec632f525', 'The complete “Für Elise.” The A minor theme that begins with the right hand alternating E and D♯ returns three times, and between the returns come a bright F major section and a dark section in which a low A repeats without pause. All three performances are about the same length, and they differ in **where the loudest point falls**.'),
('performance_sectors', 57, 'description_en', '6ce0ddd4a411e3f1da053b729f78fa6d8fba756b390f10d19850207f7ebc86e8', 'A piano piece in which Ravel borrowed the slow tread of the pavane, an old court dance. The first theme returns three times, with another melody intervening twice, and at the end the first theme comes back in thick chords. Performances divide on **how loudly they close that final return**.'),
('performance_sectors', 58, 'description_en', '65527c0333bbf3bb809a6771ba16763c82bdedc4c1f2d774ee5181d40077b3f8', 'An intermezzo played between scenes of the opera Thaïs. Over the harp’s gentle arpeggios, a solo violin sings a long melody; the melody rises and intensifies in the middle, then returns to the opening melody and ends quietly on a high note. The three performances differ most in **how deeply the music sinks after the big moment in the middle**.'),
('performance_sectors', 59, 'description_en', 'ce4bc01681c22a91f80f953fa6cf4d919614a95c387c899d0d3c0c1cad34b5f2', 'A nocturne that Chopin wrote at twenty and that was published after his death. It sings with slow, expressive feeling (Lento con gran espressione), and in the middle it draws on a melody from his own Piano Concerto No. 2. At the end, quick ornamental figures pour from the right hand. Performances differ in **when they first play loudly**.'),
('performance_sectors', 60, 'description_en', 'e1931bbedebe8e5e33025dd7e48c2c1eb9cf772b851471b6148ec0a22691d1f0', 'An overture strung together from melodies in the operetta Die Fledermaus. It opens with a short tutti, followed by a slow song and a fast dance, and the waltz that is the work’s best-known number flows out among them. In all three performances the loudest sound comes at the same place, and they differ in **how loudly the first tutti is opened**.'),
('performance_sectors', 61, 'description_en', '5f3148ed396830926448631638f53e64034b79060f8ac6bb43931d3c90c12668', 'A fast polka in which the bass drum’s thunder and the cymbals’ lightning break in without pause. It begins with a short tutti, a lively theme runs, passes through the central trio, then returns to the first theme and ends in a rush. In all three performances the last chord is loudest, and **how long the loud playing is sustained** differs.'),
('performance_sectors', 62, 'description_en', 'fb6a53166cf3b54db12b10d4538c51746d310a88442181813ebc9a4646658f31', 'A piece that paints water leaping from a fountain on the piano. The right hand keeps up a finely splintering figure without pause, while short melodies rise and sink among it. In all three performances the loudest point comes about a quarter of the way from the end. The performances differ in **how deeply the quiet passages sink**.'),
('performance_sectors', 63, 'description_en', '53133952b8209c68ac938fb74293b08795c84a499cb94b8d263f795dc5487b52', 'The whole first movement, in which a dotted-rhythm melody rises over a triplet accompaniment. Beethoven wrote that it should be played from beginning to end very softly and delicately, with the dampers raised (senza sordino). In all three performances the loudest point comes about a third of the way in, and the **tempo** differs so much that one performance is more than a minute shorter than the other two.'),
('performance_sectors', 64, 'description_en', '23931167c8e802120813b3842d089d393e35bc75d10c24e33d6734e7dad65d65', 'Throughout the slow second movement, the same song-like melody appears three times. The theme, which begins in the middle register, is soon repeated an octave higher and returns after each of two middle sections that lean toward the minor. From the second middle section on, the accompaniment changes to fine triplets. In all three performances the loudest point comes a little past the middle, and they differ in **how far they bring it down afterward**.'),
('performance_sectors', 66, 'description_en', '8be01ae1cb9f88ea0514a7968830db01563d355c4c40d5b132d91fd98a139eef', 'The complete “Clair de lune.” It starts with soft chords, grows in the middle as left-hand arpeggios spread beneath, and at the end **the first theme returns over the arpeggios**. All three performances follow the same course, and they differ in length and in how loudly the first note is played.'),
('performance_sectors', 67, 'description_en', 'e07398163b2d8905b1d9e2cc6d525bf14b87a71618d1a76d09c3915b72f95d3e', 'It begins with a bell-like motif of three descending notes, sounded very loudly. Soft chords follow, then in the middle the Agitato section speeds up and rushes ahead, and the opening motif returns in thick chords written across four staves. The three performances differ most in **how long they sustain the returning bells at full volume**.'),
('performance_sectors', 68, 'description_en', '2748f5f2cc46fc058ac41c349a997e2c17087b1223a29a3502a05c5d9b8cd1b3', 'A piece in F major built on a melody that begins with a soft upward leap and keeps returning. The same phrase starts again and again, unchanged or at a different pitch, and near the end it pauses at length on the highest note before fading to soft. Performances differ in **where the singing is loudest and how wide the dynamic range is**.'),
('performance_sectors', 69, 'description_en', '0df75ab1d0f1448c963b6403b2a8e2c444150422e45eb4d47231d526b5b43497', 'The whole third movement, which begins with soft arpeggios that surge upward and collide with two loud chords. A second theme in G♯ minor follows soon after, and near the end the music halts briefly on a two-bar slow passage (Adagio) before closing on a very loud chord. Two performances play loudest more than a minute before the end, and one plays **the final chord loudest**.'),
('performance_sectors', 70, 'description_en', '0328e75955aa21ecbbd6bb373b60661ad1b2233a504c5ae75725fc9022c2a6e3', 'The whole finale of the “Pathétique.” Sections in E♭ major, A♭ major and C major interrupt the C minor rondo theme in turn, and near the end the theme glimmers in A♭ major once before closing in C minor. The same movement differs by nearly a minute between performances, **from 3:59 to 4:57**.'),
('performance_sectors', 71, 'description_en', 'cd4bab238e55bd0c71cfb7fd6d700f1e89ba81a7249182a173ce0fc1473dacff', 'The whole Ballade, from the slow introduction to the fiery coda. The soft first theme in G minor and the second theme in E♭ major, which enters in a whisper, return in changed keys, and later the second theme swells twice to a very loud ff. Performances differ in **where the loudest sound is placed**.'),
('performance_sectors', 72, 'description_en', 'c727e3308f7f760c6437e7145ac16a854fb72bf9945bdb34f6e1bc44c3bb841c', 'The whole aria in which Calaf, beginning with “Nessun dorma” (“Let no one sleep”), proclaims victory at dawn. It opens quietly over a soft orchestra; the main melody soars once and settles, then rises again on the final “Vincerò” (“I shall win”), and the orchestra takes it up and closes. The three performances differ most in **how loudly the first peak is sung**.'),
('performance_sectors', 74, 'description_en', '9a467debcfc282fe99c4e70ac1a34681cbcf62593021562d2a573290994d9d6f', 'A movement in the simplest sonata form. The right hand sings a C major theme while the left hand supports it with an Alberti bass. After a passage in which scales flow down at length, the second theme appears in G major, and in the recapitulation the first theme returns in F major. None of the three performances swings the dynamics much, and **the place where each plays loudest** differs.'),
('performance_sectors', 75, 'description_en', '4d96c99cd2610067cc51dceddd61d424aa513ea4ebfbd56097a50a1101fcb23e', 'The whole first movement, which opens with the strings rising in unison on a G major chord. After the vigorous call, a violin song follows, and soon the graceful second theme in D major appears. The same opening returns in the recapitulation. All three performances share the same course, and they differ in **whether the first call or the last chord is made louder**.'),
('performance_sectors', 76, 'description_en', 'c5e148ab92d0a88bbc6df23b1784f2b63141275e4c84a9ad7934ba9effea1ef4', 'A piece depicting Mazeppa, tied to a horse’s back and galloping across the fields. Within chords divided between the two hands, the D minor theme rings out like hoofbeats; in the middle it sinks once as if singing, then surges again and ends in D major. Performances differ in **how deeply the quiet passages sink**.'),
('performance_sectors', 77, 'description_en', 'd8a53f308db52c58aedd7a4f17420f55112333a76f4e52f88ba4ef877bd671a0', 'A rhapsody in two parts, a slow lassan and a fast friska. The C♯ minor lassan opens solemnly in low octaves, and the friska begins softly and gradually speeds up into a dance. Near the end the score leaves a cadenza to the performer. Performances differ in **how they close after the climax**.'),
('performance_sectors', 80, 'description_en', '1052edb3dafe21776aca1bb59d86eb9c4f1ec21638721cbfde3a9e4502259f51', 'The passage where the first-movement cadenza begins. Rachmaninoff left this cadenza in two versions: the long ossia, which piles up heavy chords, and the short original, which runs lightly. **Only Lang Lang plays the ossia**, so this passage is about 50 seconds longer in his performance.'),
('performance_sectors', 87, 'description_en', '41ae0a661dbf993d0f316a11837eb55e83dabd13fb9745575c415e114863318d', 'The introduction that opens the Ballade, and the first theme in G minor. The introduction draws out a melody doubled in octaves and stops on an unresolved chord; the theme starts softly and grows steadily fiercer. The five performances differ most in **how long they keep the music quiet**.'),
('performance_sectors', 88, 'description_en', '1e74f5765420c83ed8bd861568db0513cd6637af245e83fc399f112a4c4491af', 'The passage where the second theme in E♭ major enters in a whisper (sotto voce). Over wide left-hand chords the right hand sings a melody in doubled voices, and soon starts the same melody once more. The four performances differ in **how quietly and how late it enters**.'),
('performance_sectors', 89, 'description_en', '9b3da98891e3d64cb799811d288da007dfaa1234a536d3228f9e5d4edb3d69f1', 'The coda that ends the Ballade. The tempo becomes fiery fast (Presto con fuoco), and the right-hand chords are accented between the beats, pushing forward. The left hand alternates between low bass notes and chords, supporting those off-beats. The five performances differ in **whether they come in loudly from the start and how far they pull back before the end**.'),
('performance_sectors', 90, 'description_en', '07a64e7737d2fea3afa5edceb5882b6b2c5b350a2fa4987d017b669af373ab67', 'The final movement of Haydn’s Trumpet Concerto, in which a lively rondo theme, introduced softly by the strings, keeps returning. It was written for the new keyed trumpet, which can play chromatic notes, so scalar melodies that the old trumpet found hard to produce run through it. Performances differ in **whether the loudest sound falls on the last chord or in the middle of the movement**.'),
('performance_sectors', 91, 'description_en', '61915f82a72f44334dc2788883bc730aea57c8a424ad58e9fbd6f540b4cb94e5', 'A movement in which the solo horn brings out a hunting-style rondo theme in 6/8, and the theme returns again and again with other sections in between. Each time the theme comes back, the orchestra takes it up. In all three performances the theme is cycled evenly, and **the place of the loudest sound** differs.'),
('performance_sectors', 92, 'description_en', 'c5e37ae7811d1fbf29a86241a0147d2f8c902dd232e7283a0267fcb9ce888d79', 'The D major tutti opens with a rising arpeggio, and the violins run lightly through the first theme. The second theme is a comical melody in which the violins leap a wide interval, and the first theme returns in C major. In all three performances the tempo and overall shape are the same, and they differ in **how deeply the quiet passages sink**.'),
('performance_sectors', 93, 'description_en', 'f2e377e32935508977e4f69a00149afe3848a8c1e61c5fda2cf752172f80f357', 'A trill in the woodwinds and a rising figure in the strings set up a galloping ground, over which the brass shout out a theme in 9/8. The theme returns again and again, shifting position, and each time it comes back different instruments carry it. The three performances differ most in **whether the loudest sound is placed in the middle of the piece or at the end**.'),
('performance_sectors', 94, 'description_en', 'eb97224776adb85f5b7b4960a9806b7ce009b55c8709f828eb02acfccb67a82c', 'An overture painting the sea around the Hebrides, the islands off Scotland. Violas, cellos and bassoons bring out a short motif in B minor, and this motif returns throughout. After a fierce rush at the end, it closes softly. The three performances differ in **whether the loudest sound is in the middle or in the final rush**.'),
('performance_sectors', 95, 'description_en', 'b81a33e03d36bde6090e3e61773b5ea485d860d73a5d570f0c211afb7767f5eb', 'A fast movement in G♯ minor that drives on without rest. The four instruments dig in at very loud volume and hardly pause for breath until the end, and amid them a Jewish-style melody taken from Piano Trio No. 2 soars sharply. The three performances differ most in **how long they sustain the loud playing**.'),
('performance_sectors', 97, 'description_en', '06d47692b6c4f5367f424a388539dc4ab798a3ddfcfd9f584e009ee1698fbcd9', 'A piece that begins with a single right-hand line and grows into two and then three interwoven lines. Very slow (Sehr langsam) and without a tonal center, short fragments of melody pass back and forth and then disappear into a quiet last note. The three performances differ most in **how softly the first single line is opened**.'),
('performance_sectors', 98, 'description_en', 'd3f718f7a6cae80c3673bba1d06b3913682d87db344acc6c1542b6a0d34227b6', 'A toccata movement (Precipitato) driving on without rest in 7/8. The left hand obstinately repeats the same low figure while chords hammer above it, ending in a rush to the final B♭ octave. In all three performances the loudest point comes at the end, and the **tempo** differs so that they range from 3:09 to 3:36.'),
('performance_sectors', 99, 'description_en', 'e96efa5f0fc07512d0e1221b1041546a0ddf0810875f01fcba8fc6a068727047', 'The whole slow second movement of the concerto Shostakovich wrote for the birthday of his son Maxim. The strings open a soft introduction in C minor, the piano enters with a quietly singing melody, and the movement closes on a soft piano chord. In all three performances the loudest point comes right in the middle, and the **length ranges from six minutes to seven and a half**.'),
('performance_sectors', 100, 'description_en', '6106f2709957cd0539ddeb62297bc8912e7fe1606a5aa988aa14b71f5bab6f51', 'The D major concerto opens with a soft string introduction. After the orchestra rises once and falls back, the solo violin brings out a brief statement alone and then sings the first theme. Each performance sets **the dynamics and length of the introduction** differently.'),
('performance_sectors', 101, 'description_en', 'f7c8c207993ce1fce7a0562ddc3f72aae2f47d7611b0a427018f3a5aba6c5fae', 'The slow movement, the Romanze, begins with a simple B♭ major song that the piano brings out alone. As this song returns several times, the piano rushes in with fast figuration in the G minor section at the center and the scene suddenly changes. Each performance treats **the dynamics of the opening song** differently.'),
('performance_sectors', 102, 'description_en', 'bde881cacec72400e08182d7e4b317f0af8500f21223cfa9d83ba4717630f619', 'The “Emperor” Concerto begins with a big chord from the orchestra, answered by the piano with an improvisation-like flourish. This exchange occurs three times over three chords, E♭, A♭ and B♭, after which the orchestra brings out the first theme. The three performances differ most in **whether the loudest sound is in the first reply or at the very end**.'),
('performance_sectors', 103, 'description_en', 'a6ecf1b84dd59ed50835f45878848569c4c132f71f3f8963dbfde2ac68c29d7c', 'The opening of the G minor symphony, in which the violins bring out the first theme softly over the violas’ fine accompaniment. The theme, which keeps repeating a sigh-like two-note motif, bursts out forcefully in a tutti, and then the second theme follows, moving to B♭ major and sliding down in semitones. Performances differ in **how early and how long they play loudly**.'),
('performance_sectors', 104, 'description_en', '9ccd8ee940649ab7cb8f81785cf3ee6da4d71b785573a360ddb4ae6d18392b16', 'The last movement opens with a fanfare in which the whole orchestra hurls out a dissonance at once. Then the cellos and double basses declaim a recitative as if speaking, calling up the openings of the previous movements one by one and rejecting them. The three performances differ in **which of the two fanfares is hit harder**, and in length.'),
('performance_sectors', 105, 'description_en', 'a1b73e5083dd7143fa2bbb5f0c442c07a4d663c95ad811f535741b4c9eed9905', 'The Rite of Spring begins with a melody that a single bassoon sings alone in a very high register. Soon the English horn and clarinets layer in different melodies of their own, and as woodwinds join one by one, the sound thickens. Each performance plays **the bassoon’s first sound** at a different volume.'),
('performance_sectors', 107, 'description_en', 'f3841fb6c6562d39a752e3f4f565c3142f58b6aa85bcbdcfd1a060ac19879f7e', 'A piece that moves from a fast C♯ minor section to a slow D♭ major song and back to a fast section. In the outer sections four right-hand sixteenth notes play against the left hand’s triplets, and in the middle a relaxed song (Moderato cantabile) unfolds. Performances differ in **whether the loudest sound falls in the first section or in the returning section**.'),
('performance_sectors', 108, 'description_en', 'f724fa718c3439005d41aceeb83ef1a5b0a6729587326602f0359162b12c22a2', 'Liszt’s piano transcription of one of his own songs, in which a mid-range melody sings amid arpeggio accompaniment. After a short cadenza the melody is sung again in a changed key and reaches a boiling climax, and after a second cadenza it returns to the original key. In all three performances the climax comes at the same place. What differs is **how deeply the music sinks after the climax**.'),
('performance_sectors', 109, 'description_en', '1a017d039f7de25827212dfb62a6d7af15a3ce63aa67dd59bbdad7421163efdf', 'A waltz in which a desolate minor-key melody flows over an oom-pah-pah accompaniment. The whole orchestra takes up the melody that the saxophone first presents and builds it up; near the end it shrinks once and then returns big. Performances differ in **how loudly the first melody is opened**.'),
('performance_sectors', 110, 'description_en', 'ac56fb5726be9d0e05a4140e6472b4e816fdd22e9a242dad9205294597dddbcc', 'A set of twelve variations on the melody best known as “Twinkle, Twinkle, Little Star.” It darkens into the minor in Variation 8, Variation 11 sings as a slow Adagio, and Variation 12 changes to 3/4 and ends energetically. Performances place **the loudest moment** differently, and their lengths differ by more than a minute and a half.'),
('performance_sectors', 111, 'description_en', 'c08576da2de238e7512c4eaaaf9baa5bbdd61fa0664857586579e663abee929f', 'The clarinet opens the piece by sliding up in a single sweep from a low trill. After that, the first theme flows in jazz style and the orchestra takes it up. In all three performances the loudest point is near the end, and they differ in **how low they keep the music before that**.'),
('performance_sectors', 112, 'description_en', 'e5ca6a294b28f93f7dba1123ff5effdb9780c21a58231e51ef460039cf746780', 'The final piece that closes Carnaval, a march in which the League of David (Davidsbündler) drives out the Philistines. Though a march, it walks in three-beat time, and an old dance tune mocking stale taste, the “Grossvatertanz,” breaks in. After material from the first piece returns, the music speeds up and rushes to the end. **Whether loud playing is used from the start or held back until the end** is what separates the three performances.'),
('performance_sectors', 113, 'description_en', '24edea2d64938ac0fc7ef272a26dee726ee94c23f2f87a719193fdfe3b7e69ce', 'The whole Impromptu in G♭ major, in which a long melody sings over ceaselessly flowing arpeggios. The first melody continues, darkens into the minor, rises up once to a big moment, and then returns to the opening melody and closes. Performances differ in **how widely the dynamics rise and fall**.'),
('performance_sectors', 114, 'description_en', 'fa9b24964f90fa60c44f6b997a42528ab50331d92c19f0094976f7c6c264f858', 'The opening of Liszt’s symphonic poem: after the strings’ pizzicato, a short three-note motif rises like a question. As this motif repeats, shifting position, the orchestra swells little by little, until at the end the whole ensemble rings out loudly. In all three performances the loudest point comes at the end, and they differ in **whether the music builds once early on and then settles back**.'),
('performance_sectors', 115, 'description_en', '2ba95e99720012263e9afb6aa130f99011d5075686e60166ee982897feef8140', 'The opening section of the piece depicting an American walking the streets of Paris. Strings and woodwinds step out the light walking theme, and even taxi horns break in as the street starts to bustle. In all three performances the shape is the same: the loudest playing comes about a minute in, then drops sharply. They differ in **how early the volume is raised**.'),
('performance_sectors', 116, 'description_en', '8fb1e764543f5ed266f18d418276d8b94c25664e53929ae512e0e272f509d7f5', 'The final two minutes or so, which close the piece after the battle, with bells and cannon. The chant melody first sung by the low strings returns in full orchestra, and as the music speeds up the brass sing the Russian imperial anthem while the cannons sound. Each performance chooses differently between **opening at maximum from the start and building toward the end**.'),
('performance_sectors', 117, 'description_en', '94eaf91b5c4a660bc1466ef43c262cccadd1e6a3e401f87a4ecff3c07fba562f', 'The introduction in which, after an orchestral hit and a descending piano chord, the oboe brings out the first theme in A minor. The piano soon takes over the same theme and sings it, and gradually builds strength together with the orchestra. Performances differ in **whether the first descending chord or the big passage later on is played loudest**.'),
('performance_sectors', 118, 'description_en', '5de945149c8dee65f479feedcec6a63f88140a04a4c8ca31ecfb2036a62237e5', 'The passage where the slow movement (Larghetto) of Chopin’s Concerto No. 1 begins. Muted strings open the way softly, and then the piano enters singing the E major theme. All three performances begin softly and grow, and they differ in **whether the music settles back after one big song**.'),
('performance_sectors', 119, 'description_en', '2a12ad90ee6276e115cf616f6c1733b9fee41bd269e7f10c1afc5792b808e125', 'The concerto begins when the orchestra throws out a short, resolute theme and the piano answers forcefully in octaves. After this big exchange the music sinks deep for a while and rises again at the end. **How deep and how long the sinking passage is held** is different in every performance.'),
('performance_sectors', 120, 'description_en', 'c97fa4e5790675c225a34f117ae6dab6f886a90c2b1e96f7959e1b3f743ca417', 'The passage that gave the symphony its nickname, “Surprise.” After the soft theme is played twice, at the end of the second statement the whole orchestra suddenly strikes loudly. **How softly the lead-up to that one blow is laid down** differs from performance to performance.'),
('performance_sectors', 121, 'description_en', '7b18d755d114d63fad8ccfbda222625704733366479512a81b90dfe48cf16f94', 'The opening, in which cellos and double basses bring out the B minor introduction very softly. As the violins spread out finely, oboe and clarinet sing the first theme together, and after one big surge the cellos present the second theme in G major. The three performances share this shape, and they differ in **how softly the opening is kept**.'),
('performance_sectors', 122, 'description_en', '19686f8f1a8bfdef43c2e750cfabc2d9f5af902d0e58b2f6b049f0336059ff6b', 'As soon as the movement opens, the winds repeat the same chord rapidly and the violins bring out the A major first theme with big leaps (Allegro vivace). The theme soon spreads to the whole orchestra and rings out loudly, and later all three performances drop to soft once. The performances differ in **how deeply they let this soft passage sink**.'),
('performance_sectors', 123, 'description_en', '19afd54a4fff2331bf5e3cb99b6f17d228eba3cd6df8611b3206afd7d5179307', 'The passage where, just after the orchestra’s soft accompaniment has barely begun, the solo violin sings the E minor first theme in a high register. With no long orchestral introduction, the soloist steps in right away, lifts the theme high, and then the whole orchestra takes up the same theme loudly. In all three performances the loudest point comes around the middle, and the **tempo and the loudness of the first note** differ.'),
('performance_sectors', 124, 'description_en', '4074196f0554ab8d6ae5e932cd85bfda50d0c8306150ca1d12389ed79a718a5e', 'The opening of the Adagio, where the clarinet sings the D major theme alone and the orchestra takes up the same melody and repeats it. The same song is heard once with the solo instrument and once with the full ensemble. The three performances differ most in **whether the loudest singing comes early or late**.'),
('performance_sectors', 125, 'description_en', '01524cfca12c641d26efe8af18035c30b6c28830ea63549cf978ce73f367e4b7', 'The first movement (Allegretto) begins with the cello alone bringing out a four-note motif. The orchestra soon enters and exchanges this short motif with the cello, and the sound grows in size as the passage goes on. Performances differ in **when the music climbs to its loud passages**.'),
('performance_sectors', 126, 'description_en', 'f650dd7ecde770d63e0f225294ace6f6174f4e7c3f5337522be435cef3e61208', 'The finale opens with a four-note motif: C–D–F–E (do–re–fa–mi). The violins bring out the motif softly, a vigorous tutti follows, and soon the strings start a fugato in which they stack the same motif one by one. The three performances share this course, and they differ in **how softly the first motif is brought out**.'),
('performance_sectors', 127, 'description_en', 'b0eb58c35c8a590e34f563d676dd6d116728dfb30003d459269254800a4a0f26', 'The symphony’s nickname, “The Clock,” comes from this passage. Bassoons and pizzicato strings tick evenly like a pendulum, and above them the first violins lightly lay a melody in G major. In all three performances there is one big rise about two-thirds of the way in. The same passage takes anywhere **from 1:18 to 1:41**, so the pace of the steps differs greatly.'),
('performance_sectors', 128, 'description_en', '57637ff79795b01a8417ede6faa4da0d9beb3f1ba0b7988b693f72bd70f389b4', 'The final section of the “Farewell” Symphony, in which the players finish one by one and leave. It is said to have been written to tell the prince that the orchestra, long confined to the summer palace, wanted to go home. Instruments drop out one after another until only two violins remain at the end. All three performances grow quieter, and they differ in **how much they thin out toward the end**.'),
('performance_sectors', 129, 'description_en', '52451ec13f330f98d4b67f4fef38b6b389aa4ea81e4ec176bcf381ff860e86c2', 'The hymn-like introduction (Andante non troppo) that opens the first movement of the Serenade for Strings. The string ensemble lowers a C major melody heavily in thick chords, then gradually settles into the fast section. All three performances cover the same passage, and the **tempo ranges from 1:38 to 2:26**.'),
('performance_sectors', 130, 'description_en', '2a1ad91919ad594c19677a285718da3a59025047a85e55614fc297df481fa21c', 'The opening of the movement that Beethoven titled “Awakening of cheerful feelings upon arrival in the country.” The short theme that the strings bring out softly soon halts on a fermata, and then the theme’s short motif repeats many times and spreads through the whole orchestra. All three performances follow the same course, and they differ in **whether the loudest sound is placed at the early peak or at the end**.'),
('performance_sectors', 131, 'description_en', '50a05267065cbc324d30b2be2936c63cd87f40f2f20c1c2a79a51d60b85efee0', 'After a woodwind chord in A minor, the low strings begin by softly repeating a rhythm of long–short–short–long–long. This repeated rhythm (ostinato) forms the basis of the movement, and when the theme has made one round, the higher strings take it over. In all three performances the first chord is loudest, and they differ in **how deeply the quiet passage after it sinks**.'),
('performance_sectors', 132, 'description_en', 'cecd369151f3075f93971d15c98421bd8c59c9ec3876a95ea64987bbade8b872', 'The passage where the timpani open the concerto by beating out a Charleston rhythm. The orchestra takes up that rhythm and unfolds a jazz-style introduction, and the piano enters alone only after the orchestra has worked itself up. Performances differ in **whether they play loudly from the very start or build up step by step**.'),
('performance_sectors', 133, 'description_en', '22ab27ac9d228323c5b9fe7d61093ed29a55a63f77d1423f2b1abdd3a08d7405', 'The opening of the concerto, a slow melody (Andante) sung softly by a solo clarinet. Soon the strings speed up and move into the fast section, and the piano drives in with the busy first theme. In all three performances the loudest point comes at the end, and **how softly the clarinet introduction is played** differs.'),
('performance_sectors', 134, 'description_en', 'b8faa30a540fef92917678df15c535244f32e366c85bca140d5e5a81bcf80f0a', 'Although this is a concerto, the solo violin has not yet appeared in these two minutes or so; the orchestra opens the stage. The timpani strikes a D softly five times, the woodwinds sing the first theme, and the violins then hit an unfamiliar D♯ in the same rhythm. The three performances differ most in **how softly the timpani opening begins**.'),
('performance_sectors', 135, 'description_en', '7f3d927af170df6fffc75c389990bc0498f88fdc1d925ee279835b8fa522a98f', 'The violin begins by singing the spring theme over the piano’s gentle broken chords. When one round of the theme ends, the piano takes over the same theme and the violin steps back to support it. The three performances differ most in **where the music builds to its loudest point**.'),
('performance_sectors', 136, 'description_en', 'a46c7c992cb22f0e9326cea7eb72509cbac9e5e49e26b8cae622223df9d96a86', 'The third movement opens by repeatedly striking diminished seventh chords. The chords pour down in sixteenth notes into an unbroken flow, over which the F minor theme runs. The three performances differ most in **whether the very first chord is played at full volume**.'),
('performance_sectors', 137, 'description_en', '79b3c7d4e5e1d7a608e40d3934d6298bb380744a026381203b33b73cf3be10aa', 'A rondo in which a pattering theme in A minor and a vigorous march in A major alternate, ending in A major. As a movement imitating Ottoman military bands (alla turca), it has a march section in which the left-hand chords sound like drums. The three performances divide on **how far they come down when returning to the soft theme**.'),
('performance_sectors', 138, 'description_en', '681516dc5576e315422b27f0344807a9d6585ef17665f114abc69d1d02273822', 'The theme of the movement that takes the music of the song “Death and the Maiden” and continues with variations. The four instruments move as one in almost the same rhythm, walking like a slow chorale in G minor. The step of one long note followed by two short ones continues to the end. Performances differ in **how softly the quiet passages are kept**.'),
('performance_sectors', 140, 'description_en', '7f807901e6d5c395f8b82be5119c410e6434ff96790b2ab0c31fa5e198d2eba3', 'The opening of the movement that continues as variations on the melody of the song “The Trout.” While the piano rests, the violin, viola, cello and double bass present the theme plainly in D major. The three performances differ most in **how long the loud playing is sustained**.'),
('performance_sectors', 141, 'description_en', '1d94a61b63a8f7cdfd93cc12450a242f669684c6bada5c6c21f09beababa47f8', 'In this third movement (Poco allegretto), Brahms put a rather relaxed song in place of a scherzo. The cello sings a C minor theme low, with the strings supporting it in a flowing accompaniment, and soon the violins take over the same song. In all three performances the loudest singing comes near the end, and they differ in **when the first loud singing occurs**.'),
('performance_sectors', 142, 'description_en', '3a5d7395ab98b405915aacea4431b863aa8d2bf8769a0fb35a5f96cac5d6b0e0', 'The first two minutes or so of the “Eroica” Symphony’s second movement, where the funeral march begins. The first violins offer the C minor march theme under their breath, with the double basses’ short grace notes beneath supporting it like drums. Soon the oboe takes up the same theme. Performances differ in **when the build-up to a loud sound begins**.'),
('performance_sectors', 143, 'description_en', '22ac157325b1717f98d5c67ad58150fd633fcfa40c8e3e46e00ca21bce947a51', 'The opening of Symphony No. 1 (Un poco sostenuto), where the timpani beat a C without a break while the strings climb in semitones and the woodwinds descend against them. After this weighty opening passage, the sound sinks to soft and the woodwinds step forward. Each performance differs in **whether the opening passage or the loud sound at the end is played louder**.'),
('performance_sectors', 144, 'description_en', '4dc61374cba916f8dd8276c9b0c7ddf29a45cf7fea01868007e05595990cc0e2', 'The variation theme that opens the slow third movement. The piano first brings out a hymn-like melody in D major, and the violin and cello enter and take up the same melody. In all three performances the loudest point is near the end, and they differ in **when they first come near full volume**.'),
('performance_sectors', 145, 'description_en', '0edde95c9f1a1e5a2a80f6fb6920a1ab0bccff1bb07e6d147bd8a891e4163a75', 'The introduction to the first movement, which opens with the cello alone singing the first theme low, in D minor. The piano lays down a restlessly turning accompaniment, and as the violin joins, the three drive the theme loudly together. In all three performances the loudest point is right in the middle, and they differ in **how early they come close to full volume**.'),
('performance_sectors', 146, 'description_en', 'e8a704cf1e7d9130d486240372b667225d7bcd9a91517da32ed307c895568c20', 'The introduction to the first movement opens with a stately E♭ major first theme sounded by all five instruments at once. After the first theme the volume drops a notch, and the music moves to the second theme, in which the viola takes up a song that the cello started. In all three performances the first theme is played loudest, and they differ in **how deeply the second theme sinks**.'),
('performance_sectors', 147, 'description_en', 'cf07f9d130a4c87076a5209ffade5cb4f83d2ca6315ace62bc9cc0684399aad0', 'The opening of the finale (Adagio lamentoso), which closes the symphony with a slow lament. The strings bring out a lament theme descending in B minor; this melody is shared note by note between the first and second violins, so it is not written out whole on either line. In all three performances the loudest point is early on, and the **tempo and the depth to which the middle sinks** differ.'),
('performance_sectors', 148, 'description_en', '8b00253fb054368589f967cda229c092c65aa0e5c7e9dd4888c8708d203c8cc2', 'An introduction in which the full orchestra surges straight into the E♭ major first theme without a prelude. Though in triple time, a hemiola, in which the accents group two beats at a time across the bar lines, overlays it, so the beats seem to surge broadly. The three performances differ most in **whether they play at full volume from the first theme or hold back until later**.'),
('performance_sectors', 149, 'description_en', '0d173aa0e419ceb61eb45bada106a7550cdc595bdf45cf73eb668b328d7a3bb4', 'The first violins open the symphony with a sighing figure, descending notes in thirds paired two by two. The woodwinds support the softly presented theme in between, and as the theme goes on it grows until the whole orchestra rings out forcefully. All three performances follow almost the same course, and they differ slightly in **when they come close to full volume**.'),
('performance_sectors', 150, 'description_en', '6900e7b3f5fbd0cbe1225e8b2804461c474b803e1479ff4f5819a5a4bc9801f0', 'The chorus from Act 3 of Lohengrin that leads Elsa and Lohengrin to the bridal chamber, whose melody is commonly known as the wedding march. After a short orchestral introduction the chorus sings the first melody (Treulich geführt), softens briefly in the middle, and then the first melody returns. In all three performances the loudest point falls at the same place, and they differ in **how softly the beginning and end are kept**.'),
('performance_sectors', 151, 'description_en', 'bab68356da020df918311e12c2369b3d22944b847f4dd3175b1cc3cb8c146bd2', 'A song in which a single singer moves among four roles (narrator, father, son and the Erlking) over a triplet accompaniment that hammers like horse hooves. The son’s cry of “Father” rises higher each time, and at the end the accompaniment stops, leaving a single phrase. In all three performances the loudest point comes late in the song, and they differ in **how softly the ending is closed**.'),
('performance_sectors', 153, 'description_en', '91c9b30f5f15278f5aa87d5532faa925ef4205655bc1e9564d85a53b53e3fa3f', 'Bartók’s “night music” begins. The xylophone strikes a single note, first quickening and then slowing, and the timpani slides the pitch upward. Then the violas bring out a melody low, and the celesta and harp add sparkling sounds. In all three performances the loudest point comes about 20 seconds before the end, and they differ in **how low the middle is kept**.'),
('performance_sectors', 154, 'description_en', '824e07183942642b5b6703e1257a3418f73b902e21d407e6ab432e1d178f3cb1', 'The opening of the slow movement, in which the low strings slowly build dark, low chords and a solo horn then sings at length. The woodwinds speak between the horn phrases, and as the music goes on it rises to a big sound. In all three performances the loudest point comes 20 to 30 seconds before the end, and they differ in **how early the volume is raised at the beginning**.'),
('performance_sectors', 155, 'description_en', '6708c55ddcd9c6f9c495bbe3de14e80a2bb87cf94f67df470146258b7b0d6a04', '“Game of the Pairs” opens with a rhythm played by the snare drum alone, and the wind instruments come in one pair after another. The first pair, two bassoons, walk side by side a sixth apart, and the two oboes that follow stay close together in thirds. In all three performances the music peaks right in the middle, and they differ in **how loudly they continue after that**.'),
('performance_sectors', 156, 'description_en', '27c7a0503f8562b68319e36b9b2e1ce11de375089efb8b76e058fac371b61c18', 'After a brief woodwind introduction, the harp unfolds a long cadenza alone, the horn brings out the D major waltz theme, and the clarinet answers. In the middle the woodwinds and low strings sing a new melody, and then the waltz returns and heads toward a brilliant close. The three performances differ most in **whether the loudest sound comes at the very end**.'),
('performance_sectors', 157, 'description_en', 'acf9385a6b2588ba260cc891fbff40f05984f1885ef858dbaeff5dd508df31a6', 'Music depicting the feud between two families. Harsh dissonances announcing the Prince’s command confront hushed strings, then a heavy march theme steps out, and in the middle the sound suddenly lightens as a soft dance melody flows. Performances differ in **the length of the hushed passage between the two outcries**.'),
('performance_sectors', 158, 'description_en', '6a440928ce535768a31904949a00b802b494c3f2fdad391e72bb0d3917d981e1', 'The Swan theme appears. Over the harp’s arpeggios and the strings’ tremolo the oboe brings out the theme in B minor, and the theme spreads through the whole orchestra, rises loudly, and sinks again. Each performance sets **the volume of the oboe’s first song** differently.'),
('performance_sectors', 159, 'description_en', '20e7e08a67aa09ea94c0882a3d6b4b319273ed34cbbbb18c34031df41c430610', 'A dance that three puppets, brought to life by the magician’s flute, suddenly perform in the middle of the fair. The piano drives chords within the orchestra and pulls along a folk-style melody, sinks softly once in the middle, and returns with the original energy. The three performances divide on **whether the loudest sound comes early or at the end**.'),
('performance_sectors', 160, 'description_en', 'ca5a409682709137687077041b9be1c5b0d5b74c675bf4ca995525b95e8d85a1', 'The dance that the demon king Kashchei and his followers perform, under the Firebird’s spell, until they fall down exhausted. The whole orchestra opens with striking chords, and syncopated rhythms hitting the off-beats drive it on to the end. In all three performances the loudest playing comes at the end, and they differ in **how deeply they let the music sink before that**.'),
('performance_sectors', 161, 'description_en', '3e85256bd53fd900815c59c73a09ea1a1ab696429ae424bc9c8e79362deb7656', 'The famous wedding march, opened by a trumpet fanfare, familiar from weddings. Between the stately C major march sections, a much gentler middle section intrudes, and then the march returns. **The point at which the playing first reaches near-maximum volume** differs by more than three minutes between performances.'),
('performance_sectors', 162, 'description_en', 'cc24a73e25475bba1b348b0700202a4f4c3267b819c3c83d92e294f7f6f05245', 'The opening of the first movement, in which the orchestra lays out the theme before the solo violin enters. Low strings and woodwinds bring out the first theme in D major softly, then the whole orchestra rises up loudly and settles again. With no soloist yet, the difference lies with the conductor and orchestra. Performances differ in **how softly the first theme is played**.'),
('performance_sectors', 163, 'description_en', 'b610ca7c7f46b470c5bad0030911e99daac5b65c529951052e7791a1459e71d3', 'It opens with the scene from Richard Dehmel’s poem in which two people walk under the moonlight through a cold, bare wood. In D minor, very slow (Sehr langsam), it begins with a theme in which the low strings step down one step at a time, and grows gradually from a soft sound. In all three performances the loudest point comes near the end, and the same passage takes anywhere **from 2:01 to 2:34**.'),
('performance_sectors', 164, 'description_en', '16213deca7a9db5c10c81e47a3714dd55774ba3bb536dfacbee821e5f47d007a', 'The opening of the Prologue, in which the two gangs first confront each other. Over finger snaps a tritone motif rises, and this unsettling interval spreads on a jazz rhythm, building tension. In all three performances the loudest point comes near the end, and they differ in **how softly the lead-up is drawn out**.'),
('performance_sectors', 165, 'description_en', '431f58229c118ffec0472ab0608be8be60927837512a3f0b4253d54e906752b2', 'An overture the composer made by stringing together song melodies from his own operetta. It opens with a tutti fanfare from the orchestra and runs fast, then midway the melody of the love duet flows leisurely before the music rushes to the end. The three performances differ most in **when they start playing near maximum volume**.'),
('performance_sectors', 166, 'description_en', 'c7e96a68ee78f786c2dfd055d6a1efe5fafd70f447fe5b30bbd6e5fd3640c621', 'The overture opens with the clarinets, bassoons and horns softly singing the Pilgrims’ Chorus theme. Soon the strings overlay a sighing, undulating melody, and the Pilgrims’ theme grows louder and spreads through the full orchestra. In all three performances the loudest point comes at the end, and they differ in **how softly the first chorus is brought out**.'),
('performance_sectors', 167, 'description_en', '439d13eca6fdb1496b944cfd3129d8b66bbf5ff7995ddae9adba48de77c9182d', 'The aria in which the Queen of the Night urges her daughter to kill Sarastro. There are two coloratura passages in which the voice leaps in staccato up to a high F. The big picture is the same in all three performances, and they differ in **how far the dynamics sink between the coloratura passages**.'),
('performance_sectors', 168, 'description_en', 'a8eb88080f3ed4945289e826dc4f79abee03575862c817b448f3aa9c186c49b7', 'The aria in which the Duke of Mantua lightly sings that a woman’s heart changes like a feather in the wind. The orchestra first plays the melody, and as two verses are sung to the same melody in B major, the orchestra takes it up again between them. In all three performances the loudest point is the final cadence, and they differ in **how much is held back while singing**.'),
('performance_sectors', 169, 'description_en', 'bfcccc5690b79c41bbb03acefe581c3b85167ce67a40e29d7c3632800f5026ad', 'The march from the Act 2 scene in which the Egyptian army enters in triumph. Long trumpets on stage play a fanfare melody in A♭ major, and then other trumpets raise the same melody to B major and play it again. In all three performances the last chord is loudest, and where they differ is **how loudly the fanfare starts**.'),
('performance_sectors', 170, 'description_en', 'e861143dceed5629e12ced63ed697f0f970bec46d383fbbf4e728fc29950de61', 'The drinking song (Brindisi) from the Act 1 party, in which Alfredo raises his glass first and Violetta answers with the same melody. The chorus takes up the lively B♭ major melody verse after verse, and at the end the two exchange lines before everyone rushes together toward the final chord. In all three performances the last chord is loudest, and they differ in **how loudly the prelude opens**.'),
('performance_sectors', 171, 'description_en', '6a7bf6da7b07ffdce9eddc95b18956def42c4c201ddef1664b326000872d11db', 'The opening of the Requiem’s second movement, the “Dies irae” (“Day of Wrath”), which sings of the Day of Judgment. The bass drum pounds on off-beats between the chords that the full orchestra strikes down, and while the chorus shouts, the strings sweep in fast scales. In the final passage the chorus mutters in a hushed voice. The three performances differ most in **how low they let this final passage sink**.'),
('performance_sectors', 172, 'description_en', '340f2cd86e723e5216c688cd03e70680067483224b59c7910e49315485cadcf7', 'The fourth of the seven movements, set in the middle, sings Psalm 84 gently in E♭ major in triple time. It rises once in the middle, and near the end it rises again as the voices take up “they praise you evermore” in turn. Performances differ in **which of the two climaxes is played bigger**.'),
('performance_sectors', 173, 'description_en', '2378dcac70697eb14436d05685ea712833054db129ee456b9898cf649df490e6', 'The last piece of the Requiem’s Sequence. The chorus sings over a sighing figure in the strings, and after the first eight bars that Mozart left, his pupil Süssmayr completed it. In all three performances the music is loudest at the end of the opening section, in which the chorus creeps upward by semitones. Each performance sets **the dynamics of the first sound** differently.'),
('performance_sectors', 174, 'description_en', 'c712e9355e98752096ec8223adce00be2d5ccd74081627446d55db2ff4ab5eee', 'Symphony No. 7 begins with the strings striding out the C major first theme forcefully. The theme rises loudly once and surges again, and at the end the sound sinks deep as the music moves into a quiet section. The three performances differ most in **how many seconds it takes to reach the maximum**.'),
('performance_sectors', 175, 'description_en', 'd2392f66ad76944ab9e799173089009e62763d540cf1bd356a194e98359975f9', 'The opening of the Symphony of Psalms, which begins with the orchestra striking a short E minor chord. Since the scoring omits violins and violas, small woodwind figures fill the gaps between the chords, and then the altos begin a prayer in a narrow melody that moves between two notes. In all three performances the course is the same, and they differ in **how deeply they let the spaces between chords and the middle sink**.'),
('performance_sectors', 176, 'description_en', '73e73aba4e7d6ddc83612b300398384a4876761521c860e545bd2259ff320858', 'The final movement opens as a march. Over the timpani’s beats the brass thrust out the D minor march theme forcefully, then the tempo gradually quickens and the whole orchestra drives the theme on. All three performances come in loudly from the first beat, and they differ in **where the loudest sound is placed**.'),
('performance_sectors', 177, 'description_en', 'e4f9eab66c24e77dbca4def50119d0544b093907f65ece6bd3fefb9e1bf28020', 'The passage in The Creation where light first appears in the darkness. Raphael intones the first verse of Genesis low, and the chorus continues very softly, and at “Und es ward Licht” (“And there was light”) the chorus and orchestra burst out all at once in C major. All three performances share this shape, and **the time it takes to reach the light** differs.'),
('performance_sectors', 178, 'description_en', 'efbfb51f659273420157c11e3f6bf457e9a9db541c0a98a6dc6b3c36bac50b7b', 'The fifth song of Winterreise. The piano opens with a prelude like rustling leaves; the first verse in major darkens into minor, and rises loudly at the passage where the cold wind rushes. In all three performances this wind passage is loudest, and they differ in **the tempo of the song**.'),
('performance_sectors', 179, 'description_en', 'd8e16b08d47e970b0edd9ed9566c9e62e1cfec7b4c4910046ab15105144d6d5a', 'The song that opens the sixteen-song cycle Dichterliebe. The same melody is sung for two verses, and the piano prelude returns between the verses and at the end. Even after the song ends, the piano stops on an unresolved chord and hands the question on to the next song. The three performances differ most in **how softly the piano prelude opens**.'),
('performance_sectors', 180, 'description_en', 'fe18f27adedb1343254aec6157452033ec896fe0ac57e8c3ff6340d528efac19', 'An introduction depicting the noise of the big city. The strings race on chromatically without pause, and the brass break in roughly above them. The section extends to the moment when the noise surges on for a while and then suddenly subsides. Performances differ in **when they get close to maximum volume and how long they hold it**.'),
('performance_sectors', 182, 'description_en', 'dda2a1f651a4ee0de93969926788f7016b365e43120a5ff3f01602d588fe8c0d', 'The cello alone opens by rising softly, and the woodwinds place the famous Tristan chord at the end of its phrase. This question-like phrase repeats at ever higher pitches with silences between, until at last the whole orchestra rises up loudly for the first time. The same passage ranges **from 1:37 to 2:06**.'),
('performance_sectors', 184, 'description_en', '1caecbd2cdc179a4659528d963ddf347fb976aa73b568919742143c40c5ba113', 'A C minor miniature lasting under a minute, heard from start to finish. A line of sixteenth notes runs almost without rest between the two hands and ends on a closing chord. None of the three performances varies the dynamics much. **The place of the loudest sound** and the length differ.'),
('performance_sectors', 185, 'description_en', '237d42edc4ffe5766dac6e5c47fd99dcdd733164da01e1da804a7fd3da72c746', 'The opening of the first movement of the B♭ major sinfonia, which also served as the overture to the opera Lucio Silla. The full orchestra throws the door open with force, and loud and soft passages trade places in quick succession. Two performances hold the climax back, while **only one reaches its climax within the first 30 seconds**.'),
('performance_sectors', 186, 'description_en', '1bd98b75f0fa4c34605556a362dd35b9809665b8f97a448786323014ed349b2d', 'The first two minutes or so of the chorus that opens the Magnificat. The orchestra opens forcefully in D major, and the chorus sings the first phrase, “Magnificat anima mea.” In all three performances the final chord is the loudest, and they differ in **how long they sustain loud playing before it**.'),
('performance_sectors', 189, 'description_en', '8cd764d66ba8ad355d37e80981c867b35fa58f2b20639cf1d4f2e8076409b014', 'The lament of Orfeo, who has lost Euridice a second time by looking back. The same major-key melody returns three times, and twice the calling of her name breaks in, changing the key and the tempo. All three performances follow the same course, and they differ in **the loudness of the first sound**.'),
('performance_sectors', 191, 'description_en', 'cc98482b66e46a7d223e91033a71b33f946f8fc6b8f93716e6941bee80617afa', 'The complete overture, which Rossini opens with a snare-drum roll. After a march-like introduction, the fast main section brings two Rossini crescendos, built by repeating the same phrase and adding instruments one by one. Performances differ in **how much of the loud playing they hold in reserve**.'),
('performance_sectors', 192, 'description_en', '271b5fdba8c837d932c8ee7177fd3e2e9c4db56178fe9110e46a91e7c2e1ef93', 'The opening of the fourth movement, in which an artist who has killed his beloved in a dream is led to the guillotine. After soft timpani rolls and off-beat horns, cellos and double basses present a descending minor-key theme. The theme grows as it passes from instrument to instrument, and **how softly the first timpani roll is played** is where the three performances differ most.'),
('performance_sectors', 193, 'description_en', '19ac7ed5aa2d312c5eec46752cfed52f5b4d7798ab619b2fc99e851986527d5c', 'Johann Stamitz, a leading figure of the Mannheim school, opens his Clarinet Concerto with the tutti presenting the B♭ major theme; the solo clarinet then enters and takes up the song. In all three performances the music dips to its quietest at the same spot, and they differ in **where they place the loudest sound**.'),
('performance_sectors', 194, 'description_en', 'b4717487c320af16e27254d1ef41daa6d04f31129d68568454d900379e532c5f', 'The opening of the viola concerto that Henri Casadesus wrote under the name of J.C. Bach. The string tutti sets out the C minor theme with force, and then the solo viola enters. Performances differ in **how they carry the dynamic level on after the first tutti**.'),
('performance_sectors', 195, 'description_en', '7cae72388c63f6afed22c3dfa5ad21ee1aa057ee8ba66f2aa3e00bc017ac9919', 'Berlioz''s orchestration of the Hungarian Rákóczi March. It opens with a soft wind signal, and the march theme swells several times; later, a long crescendo builds from a very soft passage and bursts into the full orchestra. Performances differ on **whether the loudest sound comes at the peak of the crescendo or at the very end**.'),
('performance_sectors', 196, 'description_en', '7d5cb910caa8c72882c9cc201d2c26ad689ea1d39fb06afec2b0ff790273fb30', 'Glinka''s song depicting a lark singing between sky and earth. After a piano prelude the voice sings the first verse, the piano carries on briefly, and the second verse returns with the same melody. The three performances differ on **whether the first or the second verse is sung loudest**.'),
('performance_sectors', 197, 'description_en', '1e80c05639275f5a4737ac1ade5b95e7f7dc132ddac5747602fbe7964d901b43', 'An overture Berlioz built from melodies of his opera Benvenuto Cellini. After a short, explosive introduction, the English horn sings a long, slow love song; once it has passed to other instruments, the fast dance, a saltarello, drives on to the end. **The point at which the dance reaches nearly full volume** differs by more than two minutes between performances.'),
('performance_sectors', 198, 'description_en', 'bbe4b828b116cdacbffa48eea506627663bf381a8c8f55052dfc80ad7398ab0d', 'The two themes that open Scheherazade come one after the other. Brass and low strings sound the Sultan''s theme loudly; after the woodwind chords die down, the solo violin unfolds Scheherazade''s theme over the harp. Then the music of the sea rises. In all three performances the Sultan''s theme is loudest, and they differ in **how big they build the later part**.'),
('performance_sectors', 199, 'description_en', '5e62ec223af1fc3221755a5964b16b7c4eb874bcb7f2163d7ffb5902b339912c', 'The first Promenade in Ravel''s orchestration: a solo trumpet states the walking theme and the brass answer in chords. The give-and-take of the original piano piece becomes a contrast between solo and ensemble, and the sound broadens as strings and woodwinds join. In all three performances the last chord is loudest, and they differ in **whether the music rises once to nearly full volume in the middle**.'),
('performance_sectors', 200, 'description_en', '843f94a4242b4e2c7347773a44026d23f9d5876b7ce7da5fc651f382a5005ce7', 'A tone poem in which a witches'' night-long revel scatters at the sound of the dawn bells. Furious swirling strings and a heavy brass theme rush on until the bell tolls, and then clarinet and flute sing of a quiet dawn. All three performances reduce the sound after the bell, and they differ in **how softly they play the dawn section**.'),
('performance_sectors', 202, 'description_en', '10f13025e376cdc50a632e3dc203f088c62ab8f0a27c3af46afa398f01da8af7', 'The orchestral introduction of the first movement, in which the clarinet softly states the first theme in B minor. The theme begins quietly over low strings, swells gradually, bursts into a big full-orchestra tutti, and then fades again. Since the cello has not yet entered, the differences among the three performances are the conductor''s, and **how long they sustain the big tutti** differs most.'),
('performance_sectors', 203, 'description_en', '085d9eb54b098d80798da581c60fa8ae74ab49469404c4843b36329e29cdfa32', 'The opening of the F major first movement: over the gentle tremolo of the two violins and a low sustained note in the cello, the viola brings in the first theme. The first violin soon takes up the plain pentatonic melody, and all four instruments grow together. Two performances reach the climax within 30 seconds, while **only one postpones its climax to the middle**.'),
('performance_sectors', 204, 'description_en', '8b2916e741a4713f97c7cfed7083522595a87a0247d75f11294c61ab9cc398de', 'The opening of the second movement, where the English horn sings the first theme after slow wind chords. The chords begin softly, rise up loudly once and then subside, while muted strings support the melody from below. In all three performances the chords are the loudest part, and they differ in **how softly they play the melody section**.'),
('performance_sectors', 205, 'description_en', '8761d0a48d53068c75868336f5531d8a620d5de19e97a8ac9e92bb682b8c56e8', 'The complete Humoresque No. 7, whose dotted-rhythm melody sways lightly in G♭ major. In the middle a minor-key shadow falls and the volume swells; then the first melody returns and ends quietly. All three performances are loudest at the same spot, and their lengths vary **from 2:33 to 2:57**.'),
('performance_sectors', 206, 'description_en', 'd30ce7d7e0783789a74a87195ba17ab78524a33c5e147e4e180016dcd7dba1da', 'The opening, where a solo horn calls out the theme over very softly trembling strings. The winds take up the call one by one and the sound builds, and at the end the whole orchestra rises up loudly. The long crescendo is the same in all three performances, and they differ in **how quietly they hold back the opening**.'),
('performance_sectors', 208, 'description_en', '8001ce1cf5d5ae350ace402e3c68e59ba1be9386047534a8b6c71d27e141e401', 'A short votive piece in C major for unaccompanied four-part chorus (Locus iste). The first line, “This place was made by God,” spreads out in broad chords, and in the middle the harmony passes through several keys and subsides softly. Two performances are loudest early on, while **only one puts its loudest sound later**.'),
('performance_sectors', 209, 'description_en', '33aabf3b945589a552545cf52c236fa8c6ee40bd702f6396b3bf93a021aa6bd6', 'A funeral march that begins with a triplet signal played by a solo trumpet. The signal swells into a cry from the whole orchestra and then subsides, after which the strings take up the C-sharp minor march theme and walk on heavily. All three performances come close to full volume after about 25 seconds, and they differ in **how long they draw out that cry**.'),
('performance_sectors', 210, 'description_en', '14202d42325c9910209417021a848355d82366acb7b30997740478100cdd1ca8', 'The opening of the “Resurrection,” where cellos and double basses charge fiercely upward over wild string tremolos. The C minor theme that follows walks as heavily as a funeral march. In all three performances the music sinks at the same spot and is loudest at the end. They differ in **how deeply they let the middle sink**.'),
('performance_sectors', 211, 'description_en', 'f83de8cf63fad67e1fa509ab564f3d74cb3f52734ed9fe1a335c8be903d5d154', 'The “Titan” opens with the whole string section sustaining a single A, very softly. Over this ground, which the score marks “Wie ein Naturlaut” (like a sound of nature), a descending fourth motif in the woodwinds and a distant trumpet signal emerge one by one. **How early they reach nearly full volume** is where the three performances differ most.'),
('performance_sectors', 212, 'description_en', '245e3e0a2c89fdb519ee04a607a4215545c7f87e5713ccedaf5610152e61cae5', 'The passage that opens with two choirs crying out “Veni, creator spiritus” (Come, Creator Spirit) over an E♭ major organ chord. The two choruses trade the same words, while orchestra and brass fill in above them together. **How loudly they come in from the very first cry** is where the three performances differ most.'),
('performance_sectors', 213, 'description_en', '552d67ba7f5c7d4c3b1f94e7b7dc996a9c01292144ff262e8424aaa9cddfc779', 'The first song of Das Lied von der Erde opens with a violently rising horn signal, and soon the tenor begins a song offering a cup of wine. The text is a German rendering of a poem by Li Bai, so the darkness of life shows through the exuberant drinking song. In each of the three performances, **the loudest sound falls in a different place: the opening, the middle, or the end**.'),
('performance_sectors', 215, 'description_en', '236f1b54405fa2e38ddffc60125ade3434cca35fa61e19732eac07d7156de126', 'The introduction before the waltz begins: over soft string tremolo, the horn plays a rising motif. The introduction rises loudly a few times and subsides to catch its breath, and the first waltz in D major then begins by turning that motif into a dance melody. The performances differ from **the loudness of the first tremolo** onward.'),
('performance_sectors', 216, 'description_en', 'd95dc035677da9207b17b191bcf69bcd836bbfe8c64e1e3d5212136b2e30076e', 'Franck''s Violin Sonata opens the way with a soft piano chord. The violin sings gently with a short rising-and-falling motif, which returns again and again in the later movements in changing forms. All three performances begin softly and go to their loudest at the end. Each sets **the loudness of the first sound** differently.'),
('performance_sectors', 218, 'description_en', '04352e0469ba3a20798715ef00450535be53786329ac27c50232c13d2fa1d860', 'A short prayer for solo soprano, the Pie Jesu. Where other requiems spread out the song of judgment on a large scale, Fauré left only the prayer at its end. Each time a vocal line ends, the accompaniment answers briefly and carries on. The three performances differ on **whether the loudest line comes early or late**.'),
('performance_sectors', 219, 'description_en', 'd16df302b09f5032dc67c9c63b1f25db453a05e82e7b7a0a584716676c3716b6', 'A song in which the singer flies up toward the light with a beloved in a dream, then wakes and calls the night back. Over the piano''s evenly repeated chords, the voice spins long lines. In the last stanza the dream breaks, and the song pleads for the night to return. **The duration** ranges from 2:40 to 3:20.'),
('performance_sectors', 220, 'description_en', '4eb1665ae83aa3661bf04f92012bc866079b076d35abfa71a082bfe7419aac20', 'A slow dance, the Pavane: plucked strings mark the steps and the flute brings in the F-sharp minor melody. The melody passes through several instruments, and around the middle comes a passage where the whole orchestra sounds heavily. All three performances swell in the middle, and they differ in **whether they sink deeply once within the loud passage**.'),
('performance_sectors', 221, 'description_en', '52cb4032c2cc0048455de9fcb3055fa158cceb87c16ec187f88d3e5307c333d2', 'A siciliana in which the cello sings a G minor melody over a slowly rocking dance rhythm. The piano opens first with that rhythm; the cello takes up the melody, goes around once, spreads into a new section, and returns to the first melody. The three performances follow nearly the same course, and they differ in **length and where they sing loudest**.'),
('performance_sectors', 222, 'description_en', '206bea50f4a0850884a991383cf07a5667e7beba222f8fdf0b4cd68bd3aabbab', 'The opening of the first movement of Clara Schumann''s only piano trio. The violin sings the G minor theme from the very first note, and soon all three instruments climb forcefully together. All three performances are loudest at around the 30-second mark, and they differ in **how evenly they carry on after that**.'),
('performance_sectors', 223, 'description_en', '8846d30e78745efa93b2081a3e6ff0af3a02435f60aecd9315d5abee2999b76e', 'The opening of the first movement of the symphony Bizet wrote at seventeen. It opens with a forceful chord from the whole orchestra, and the strings bring out a first theme that soars on a C major chord. Forceful tutti and light string steps alternate. The performances differ on whether **the loudest point** comes early or late.'),
('performance_sectors', 224, 'description_en', '91736859957f3641c505738b3fa8bceb13b3aa3d36a3dccf58e59a63f366fecc', 'The opening of the piano concerto Clara Schumann wrote as a teenager. The orchestral tutti proudly sounds the first A minor chord to open the movement, then the sound soon settles down and the theme follows. All three open loudly and sink deeply later, and they differ on **whether the loudest sound is placed at the opening or later**.'),
('performance_sectors', 225, 'description_en', '59ec11458f2caf2e98eef8627be02f8fa91fe8381906ff5c9d8fe40114235df0', 'The first of Clara Schumann''s three romances, a slow song in D♭ major. The piano opens briefly and the violin takes up a long melody, swelling and subsiding several times as the song continues. All three performances are loudest at the same spot, and they differ in **how deeply they let the later soft passage sink**.'),
('performance_sectors', 226, 'description_en', '7152be197bffe7bfc39446a3100478a779e2c4418e6ca6280273bc416135b524', 'The first two minutes or so of the first-movement introduction, where the orchestra lays out the theme at length first. After a forceful opening chord it drops straight to soft playing, and loud surges and hushed moments alternate in short stretches. All three performances share this shape, and they differ on **whether the strongest sound falls on the first chord or in the surging passage about a minute in**.'),
('performance_sectors', 227, 'description_en', 'd50686dfcf94c0d23ba5c0151a51c3e0dae3000303ca31b23f1f211b01206ebf', 'The opening of the rondo that contains the La campanella (“little bell”) theme Liszt later arranged for piano. A small bell chimes in between statements of the theme, and the solo violin and orchestra trade the B minor theme. The flow is the same in all three performances, and they differ in **how far they come down after the loudest point**.'),
('performance_sectors', 228, 'description_en', '6a4e88f50a45381a21b7838e1a6dcbff25103b733fb7103fca8355dce8e1604f', 'A piece named after Clementi''s collection of studies, teasing a child practicing the piano. Right-hand sixteenth notes roll on without rest, slow down and soften in the middle, roll on again and close forcefully. **How long and how deeply the middle sinks** is where the three performances differ most.'),
('performance_sectors', 229, 'description_en', '80b76cf888ad15f2fdcb6c7be345bf599c16b9d542e8e2f8983316af2b8dc16b', 'The first scene, of day breaking over the sea. Over soft timpani tremolo and low strings the harp draws a figure, and the English horn and a muted trumpet together offer a short melody. The sound, begun very slowly (Très lent), wakes bit by bit. Performances differ in **how quietly the first sound is played**.'),
('performance_sectors', 230, 'description_en', 'e61f9d9feecaba41771aca7a23bfe58f79b6434d3e04dfd0279036c98f8f53f7', 'The piece opens with an unaccompanied flute theme that slides down by semitones and returns. Harp and horns soon answer quietly, and the flute theme comes back over changing harmonies below. All three performances are loudest at the end, and they differ in **how deeply they let the early part sink**.'),
('performance_sectors', 231, 'description_en', '675ad6429aade0a134184194a992693ac55bac50c9482de7fcdb1c62d27f5a9e', 'A prelude in which a singing middle section sits between outer sections of short, bouncing march-rhythm chords. In the middle the tempo eases a little (Un poco meno mosso) and a long melody flows over the left-hand accompaniment. Performances differ in **how deeply the middle song is allowed to sink**.'),
('performance_sectors', 232, 'description_en', '74f543355a3daa58f3e9457f4b58892aa6c0d2609c266dc5d338d3db4d04ce1a', 'The variation in which the solo piano turns the Paganini theme upside down into a slow song in D♭ major. The orchestra takes up the melody the piano gave first, rises up loudly, and sinks to a soft close at the end. The flow is the same in all three performances, and they differ in **when the climax comes and how long it is sustained**.'),
('performance_sectors', 233, 'description_en', '4a62af40c8f2633c4cae3ce31b4d1c2419a4137783f74eed48d7ea1ed3e07c0c', 'A single whip crack, and the piccolo plays a lively first theme to open the movement. The trumpet takes up the theme and the whole orchestra climbs high, and then the sound drops sharply and moves to a relaxed, jazz-tinged melody. All three performances are loudest within the first 25 seconds, and they differ in **how deeply the relaxed passage is allowed to sink**.'),
('performance_sectors', 234, 'description_en', 'b36c80c694147d86c1a40bbee711e3ef69f60e6ab3baabd764a3cc4f2ed83218', 'The opening, where the snare drum begins to etch out the same rhythm very softly. Over pizzicato violas and cellos the flute brings out the first theme, and then the clarinet takes up the same theme. All three performances are loudest at the end, and they differ in **when they reach nearly full volume**.'),
('performance_sectors', 235, 'description_en', '4c7714bf4db0e42a1130f00aac6741cccad33d1481243d9e779e540ab631cb2e', 'A piano piece in which the right hand sings a slow melody over broken chords spread evenly by the left hand. The tempo mark is “without slowness” (Andantino sans lenteur), so although it is dreamlike, it never stops flowing. All three performances are loudest at the same spot, and they differ in **how softly the first melody is brought out**.'),
('performance_sectors', 236, 'description_en', '281bc022065c4ac7b3448fa9b5ad19627c0a7617d78bbaf2470266457ca94123', 'A song lamenting the wounds Fortune has dealt (Fortune plango vulnera), repeating the same music for three stanzas. In each stanza the chorus begins softly and rises with the orchestra to close it. All three performances end the three stanzas similarly loud, and the difference lies in **how softly they sink back when a new stanza begins**.'),
('performance_sectors', 237, 'description_en', 'ee29a7f92e2ed6bf197790755327812da5d4143b5295d8e38ad27402eaa43316', 'Satie''s slow waltz, an adaptation for solo piano of a song written for a cabaret singer. The left hand marks the waltz accompaniment with a bass on the first beat and chords on the other two, and the right hand takes the song melody. **The length** differs greatly from performance to performance: one is a minute longer than the other two.'),
('performance_sectors', 238, 'description_en', '21362f99d5521a7d2cc46f13c77c108ba3f28ad13a70798eb1ca8810a03f8c87', 'The chorus invoking the goddess Fortune that opens and closes the entire work. It begins with heavy cries from the chorus and timpani, then the chorus repeats the same rhythm very softly before bursting out in the last verse and driving to the end. All three performances follow the same course, and they differ on **whether the loudest sound is the first cry or the last**.'),
('performance_sectors', 240, 'description_en', '329f442419ac8bef4ae729aa38ad9be70dea4346f6c5bbec47404b7cf644ceb9', 'The opening of Ravel''s piece imitating Hungarian Gypsy music: a cadenza with which the violin begins alone, without accompaniment. It starts slowly (Lento), drawing the melody out on the low G string, and moves between hesitation and rushing, free of the beat. All three performances pause deeply once in the middle, and they differ on **whether the strongest sound comes before or after that pause**.'),
('performance_sectors', 242, 'description_en', '5a27b87151fc1966365eb904cd57e7c0b6a696148ea54534c7cd14500daccfce', 'The first two minutes or so of the “Emerson” movement, where thick chords surge, subside for a while, and rise again. Ives wrote much of this movement without bar lines, leaving the flow largely to the performer. **How deeply the middle is allowed to sink** is where the three performances differ most.'),
('performance_sectors', 243, 'description_en', 'cf206eabdbf720be61b93679f23b712fe719ec979772df56a9b18395ed650d7d', 'A short prelude that poses a question to the entire symphony. Low strings open solemnly, and then the chorus sings the hymn “Watchman, tell us of the night.” The words are a dialogue between a night traveler and the watchman. All three performances are loudest about two-thirds of the way through, and **the same passage differs in length by nearly 40 seconds**.'),
('performance_sectors', 245, 'description_en', 'aa5225a5e6f81864e7125e1b8c1bb84d9c360c1a73cd1c3f2b7e4fcf4da6561f', 'At the opening of the War Requiem, over bells and low strings, the chorus intones “Requiem aeternam” (eternal rest) in low voices. The bells ring uneasily, repeating C and F-sharp, a tritone apart. All three performances sustain the soft passage for a long time and rise loudly at the end, and the only difference is **how long they draw out that soft passage**.'),
('performance_sectors', 246, 'description_en', '3120257892cd03f0f9e0c5bbc2fcc5f0f6ecde091040ab75088ccaa4e387d6f1', 'The opening, where the full orchestra states Purcell''s theme all at once with force. Then woodwinds, brass, strings and percussion take up the same theme in turn, and finally everyone comes together again. **Whether the first or the last full-orchestra statement is played loudest** is where the three performances differ.'),
('performance_sectors', 247, 'description_en', 'a33c8a7f4f3db4cf18f486b75227a0ef1c6aca2a0482d299e95fb0d082b32b11', 'The suite opens with a slow, broad song for a single cello. This song (Canto) returns three more times in changed form between the movements. **Whether the loudest sound is placed early or at the end** is where the three performances differ most.'),
('performance_sectors', 248, 'description_en', '50cdd30378643a64b65a99b94d45c85006bdd6422ec62a7bf2c2d5727cde4d4b', 'The first movement, which Berg wrote using the twelve-tone technique. As its name suggests, it moves in a jovial way (gioviale) and lasts around three minutes; it opens with a chord sounded by all four instruments and trades short motifs among them. All three performances are loudest at about one minute, and they differ in **how deeply they let the music sink after the climax**.'),
('performance_sectors', 249, 'description_en', '1b87c9f55b4ab85d002304ef937c23e65732cce48431eac135579bbd71351104', 'The opening of the concerto Berg wrote in memory of Manon Gropius, who died at eighteen. The clarinet and harp offer a soft figure, and the solo violin answers by touching its four open strings (G, D, A, E) in turn. Performances differ in **where the music rises highest**.'),
('performance_sectors', 250, 'description_en', '7ee0c962730ce452ebeed1841cc19b64343e60e081233bca65c9552ddc2ddb6e', 'The complete first piece, which portrays the monument to Colonel Shaw, who led a Black regiment in the Civil War. Over very soft strings a slow march drags on as if shuffling its feet, with fragments of old songs mixed in faintly. It surges loudly once about two-thirds of the way through and then returns to the opening stillness. Performances differ in **how quietly the opening is kept**.'),
('performance_sectors', 251, 'description_en', '6500c62a8cef7f201755130614cca4615234d09728d8d855ad895021069af51c', 'True to the instruction “violently moving” (Heftig bewegt), this movement alternates fierce shouts and hushed whispers again and again in under three minutes. Plucked and bowed sounds interleave in short fragments. All three performances shout out loudest near the end, but **the loudness of the whispers** varies from performance to performance.'),
('performance_sectors', 252, 'description_en', 'd8c97afe4228c632aaaac4ac4128185678f07bb1121c73d0871f42d3f4b11abb', 'The first movement of Webern''s Symphony, a double canon in which the four voices are paired off and follow each other in inversion. The melody never stays long with one instrument but hops among horn, clarinet, harp and strings, one or two notes at a time. All three performances are loudest a little past the middle, and they differ in **how softly they play the beginning and the end**.'),
('performance_sectors', 253, 'description_en', '886b21852edb2f41ccb6f080c6b704dc644207e5a65bb82cd449f33e12423fa8', 'The movement that first presents the two themes running through the whole symphony. The heavy “statue theme” (thème-statue) played by trombones confronts the flower theme played softly by two clarinets, and after the piano cadenza several layers of rhythm pile up on top of each other at once. The three performances differ on **when they first play loudly**.'),
('performance_sectors', 255, 'description_en', '19d1548aaeaa1003bcd242eefb4730ccd0e0d14f4eabb2297a9dc5276fa32f0c', 'The first piece, depicting birds awakening at dawn. The clarinet takes the blackbird''s song and the violin the nightingale''s, while underneath the piano and cello tirelessly repeat fixed rhythms and chords. All three performances sound loudest about three-quarters of the way through, and they differ in **how softly they play before that**.'),
('performance_sectors', 256, 'description_en', '49fa465eb6d64dcfc1868340b3afde2b13b22879b6fd89fe5e43187d9f30fb22', 'The Sabre Dance from the ballet Gayane. Over a relentlessly pounding rhythm the xylophone races through a sharp theme, and in the middle the saxophone and low strings sing a relaxed melody at length. Then the first theme returns and drives to the end. Performances differ in **how far the dynamic level drops in the middle song**.'),
('performance_sectors', 257, 'description_en', '3da02c6aca99f0d11d5794150adce99ba516e262ea1ac9aa283d35d927fa5ed9', 'The first movement opens fast and resolutely (Allegro con fermezza). The orchestra opens with a forceful tutti, and the solo violin soon enters and leads the first theme, with its clear rhythm. All three performances come close to full volume within 10 seconds, and they differ on **whether the loudest sound is in the first tutti or later**.'),
('performance_sectors', 258, 'description_en', '3ed81dedd8a852edb1114b0cd1155261ef803a1f0436349b140c4873955cecef', 'The waltz that opens the Masquerade Suite. Over a whirling accompaniment the violins spread out a wistful minor-key melody at full volume; the same theme returns several times and ends with the biggest surge at the very end. The flow is almost the same in all three performances, and they differ in **how long they sustain loud playing**.'),
('performance_sectors', 259, 'description_en', 'f8d0077529dedb49a8dec796c09091e4c65a852abb149724fe84ac5ee298758e', 'Piazzolla''s tango arranged three ways, for **cello, trumpet and string quartet**. The underlying repeated rhythm stays the same, and only the melody instrument changes. Lengths vary widely, from 3 minutes to 6 and a half, and only the cello version comes in loudly from the start.'),
('performance_sectors', 260, 'description_en', '9851bd5650fb3105de31104b538d4635df5baa8c02702a770accad60825110ec', 'You hear the same melody played by cello and orchestra, cello and piano, and violin and string ensemble. Only the cello-and-piano version is notated a whole tone lower, so that the cello sounds fuller. As for length, **the violin and string ensemble version is about a minute longer**.'),
('performance_sectors', 261, 'description_en', 'eea5bbdd6d7755173c02db01979429ee5f33378450a59ef824d5b26bceaf9ea8', 'Piazzolla''s “Summer” in three instrumentations: **violin with string ensemble, string quartet with orchestra, and solo guitar**. The guitar version is shortest at 4:41, and the quartet-with-orchestra version is longest at 7:07.'),
('performance_sectors', 262, 'description_en', 'e6fb5e9debaf9534e239cd412d07605d1634cee15d358685ad247b929cda6aab', 'All three sing it in A major, the key originally written for the tenor. The first verse is nearly the same, and the settings diverge in the second verse. In the Grigolo version the orchestra takes over, in the Domingo version the Vienna Boys'' Choir joins, and in the Carreras version there is a duet with a boy soprano. **The Domingo version runs about 45 seconds longer**, so the lengths also differ greatly.'),
('performance_sectors', 263, 'description_en', '55713aa309f26be8938cdf5c51706d06deaf4e0233b3b5d8bb74389a29650f8f', 'Piazzolla wrote this after losing his father. You hear the same piece in **violin, bandoneon with chorus, and two-piano** versions. Lengths range from 4:38 to 8:37, and the point of the highest peak varies from early on to near the end.'),
('performance_sectors', 264, 'description_en', 'e387414d7fa0e2ef4bc7506be8d2dd4afbbbb9613d269d88fd57cfb96766f288', 'Being a wordless song sung on a single vowel, it can be performed by any instrument. Rachmaninoff himself also left an orchestral version. You hear the same melody in **voice, cello and orchestra**.'),
('performance_sectors', 268, 'description_en', 'ed3051f789fb0d8f41f67cf3b8d10223b2fa8e7a703f9f871be91f232e65cb1b', 'The passage that ends Act I, where Violetta shrugs off love as a vain dream and vows to live free. After the “Follie!” recitative, the fast cabaletta continues with dazzling ornamentation, and in the midst of it Alfredo''s love song from outside the window breaks in. The three performances differ most in **whether they save the loudest sound until the very end**.'),
('performance_sectors', 269, 'description_en', '4868e9579d5e3bdf87edb66db103af793516e273a4da5eb1feda0dbe51b4e728', 'The opening of the Adagietto, played very slowly by strings and harp alone. Over the harp''s arpeggios the first violins sing the theme very softly, and then the cellos take up the melody. At the cello entry Mahler wrote “do not drag.” **How slowly they draw it out** is where the three performances differ most, from 1:44 to 2:01.'),
('performance_sectors', 270, 'description_en', '1e74f2563ac6125fd35d3aafc344f9d41bf339b2717d6359bd972f62c12f1dec', 'The passage in which the piano alone opens the concerto with eight bars of bell-like chords. The chords begin softly and pile up, growing louder; then violins and violas and the clarinet bring in the first theme in C minor, while the piano fills in beneath with fast arpeggios. **How slowly the eight bells are tolled** is where the three performances differ most.'),
('performance_sectors', 273, 'description_en', '6c9103e1b497f27e4ee6a4688d752652e90b273c22f7c1748f95908f1f100837', 'The start of the slow second movement of the “Emperor” Concerto. The strings, led by muted violins, sing a hymn in B major softly and surge up loudly twice; when they subside again, the piano enters very softly, descending from a high note. **How slowly the strings'' hymn is drawn out** is where they differ most, from 1:48 to 2:01.'),
('performance_sectors', 274, 'description_en', '224b56ca357d1d273365697129215f29518a8cee9d371a8e24e3c18e0e782d6b', 'The opening of the second movement, where timpani cut in alone on the strings'' octave motif. A fugato in which the strings enter softly, one every four bars, swells at length and bursts into a fortissimo of the full orchestra; after the woodwinds briefly catch their breath, the second theme in C major returns, again in fortissimo. The performances differ in **which of the two fortissimos they give more weight**.'),
('performance_sectors', 276, 'description_en', 'e9df73e6053a5e7e3378faf3434deae08ba31b6789077139cb0a59f1d3a8928c', 'A scene in which Violetta, writing a farewell letter, hides it from Alfredo, cries “Love me, Alfredo,” and leaves. The first part is a dialogue of short exchanges, and at the end the melody of the Act I prelude bursts out. **The length of the whole scene** is where the three performances differ most, from 2:06 to 2:40.'),
('performance_sectors', 278, 'description_en', '4f4a85a69ee7726ca590c2b6707c7b1a0991d23d083dce0d5c4b438a14e5d530', 'The passage at the end of the fourth movement''s march section where chorus and full orchestra sing the first verse of the “Ode to Joy” together in D major. The melody carries on the march''s 6/8 meter and ends just before the slow “Seid umschlungen” begins. All three performances are loudest at the very first sound, and they differ in **whether they climb back up to that level in the big passage that follows**.'),
('performance_sectors', 282, 'description_en', 'be569583bef7e5bac61ddd1e641b451acb1ac860abd3a72bf58827330fc15895', 'The complete overture to The Marriage of Figaro, in which soft whispers of strings and bassoons and loud full-orchestra sound collide without pause. There is no development: from a short string link at the end of the exposition it moves straight into the recapitulation. Mozart originally meant to put a slow movement here, but dropped it and joined the two halves with this link. **How deeply the soft passages are lowered** is where the three performances differ most.'),
('performance_sectors', 283, 'description_en', 'f51325432f60fc153b369f9fe22849a6becd7a24ca5e98567ed4193117923cef', 'The aria that opens the Goldberg Variations, a sarabande in G major with a melody densely hung with ornaments. The 32 bars are divided into two halves of 16 bars, each repeated, and the bass of this aria forms the skeleton of the 30 variations that follow. All three performances observe every repeat, and the biggest difference is in **whether they lower the dynamics on repeating**.'),
('performance_sectors', 284, 'description_en', 'c923ede14497642d232da0b5af513ca8d5c1e8dd491a2f4e9ab378abd674c85b', 'The passage in which the men''s chorus shouts fiercely at the damned and the women''s chorus softly pleads “call me.” After this confrontation goes back and forth twice, all four voices together prostrate themselves in prayer, moving from A minor to A♭ minor, a semitone lower, and the last chord leads into the Lacrimosa. **How quietly the women''s chorus passages are played** is where the three performances differ most.'),
('performance_sectors', 294, 'description_en', '9aa0b77f980fe74a217e96047e762835821df74b3b90ee29002714f1e31ec760', 'All three performances play Rameau''s complete harpsichord piece “Tambourin” in E minor on the piano, as in the film The Handmaiden. The left hand sounds E and B together to imitate a drum, and above it the right hand''s fast refrain keeps returning. **Only Hewitt plays the first refrain once more.** Beyond that, tempo differs most, so the lengths range from 1:08 to 1:27.'),
('performance_sectors', 295, 'description_en', '2a40e55eb532ea0155f0c4262483ebcb44f85e84f4c7f96d98a9365ca1854943', 'The G major prelude that opens the first of the unaccompanied cello suites. Broken chords flow without pause, stop once at a fermata on a high D in the very middle, and the second half sounds the open D string repeatedly over a long semitone-by-semitone ascent before closing in G major. **How deeply the soft passages are allowed to sink** is where the three performances differ most.'),
('performance_sectors', 296, 'description_en', 'e89ba58c592087ca0fe6b8ad4022382f43b19e92d9b9243d373c444d3f25be12', 'The C major prelude that opens Book I of the Well-Tempered Clavier. A broken-chord figure runs through nearly all of its 35 bars; in the second half a long G in the bass builds tension before it closes with a single C major chord over a C in the bass. **How slowly the same figure is traced** is where the three performances differ most, from 1:44 to 2:22.'),
('performance_sectors', 297, 'description_en', '3c69c611c57f66c906a546dbab5885e69014da8e2f6feea645915261d8c88eea', 'The complete E minor étude nicknamed the “wrong note” étude. In the fast outer sections, grace notes that clash with the melody by a semitone run throughout, giving a playful feel; the middle changes to E major, Più lento, with the left hand singing a long melody and the right hand wrapping it in wide broken chords. **How leisurely the same score is drawn out** is where the three performances differ most, from 2:50 to 3:24.'),
('performance_sectors', 298, 'description_en', 'cd7bb658a4cb39794b0b8071c592b1da7875fc7cb75a6174ab4964acfa47f10c', 'Cavaradossi''s Act III aria, sung before his execution as he remembers the nights he loved. A solo clarinet first presents the melody in B minor, and the tenor, from “O dolci baci,” takes it up almost unchanged and drives on to “muoio disperato.” **Whether the first climax is sung as loudly as the last** is where the three performances differ most.'),
('performance_sectors', 299, 'description_en', 'e234f5551df411a59921333db27c5af3956f9630751ba63b7fd26cba58c46b7f', 'The chorale “Jesus bleibet meine Freude,” the tenth movement that closes Cantata BWV 147. The orchestra keeps up a melody flowing in triplets without pause, and between them the chorus inserts the hymn tune line by line. **How loudly they raise the volume on each line where the chorus enters** is where the three performances differ most.'),
('performance_sectors', 300, 'description_en', '81f00cecaa580cb8fe2d4fd04d15a7276f492eae296b381781a05c85ed601e41', 'The first movement of “Winter,” to which Vivaldi attached a sonnet, depicting shivering in the cold amid snow. From the lowest strings, voice after voice piles up repeating the same note, and trills are laid on top; then the solo violin storms alone in fast figures like a biting wind. **How long the soft introduction is drawn out before the first big rise** is where the three performances differ, from about 25 seconds to over 40.'),
('performance_sectors', 301, 'description_en', '56bcc24ff99d2e75eec0ea752834ed9e5df2d88e0edad42d351d2dab84931a23', 'The “Hallelujah” chorus that closes Part II of Messiah. In this D major chorus with added trumpets and timpani, the four voices sing “The kingdom of this world” together like a hymn in the middle, and at “King of Kings” the sopranos and trumpet cry out on one note and climb higher and higher. **How low the soft middle passage is brought** is where the three performances differ most.'),
('performance_sectors', 302, 'description_en', '9d50906fed539a09796fdef554b8c22e24f01c8146b71398399124695c277100', 'The passage where Elgar''s Cello Concerto begins with a recitative for solo cello. The cello strikes chords forcefully, nobilmente, and the clarinets, bassoons and horns answer briefly; then the violas present the 9/8 Moderato theme first and the cello takes it up. **How deep the soft spot in the middle of the introduction is** is where the three performances differ most.'),
('performance_sectors', 308, 'description_en', '313d98d9236a30c3812c9ebf43f890a28ee98a6103d1cbed617320d93e899991', 'The passage that opens the finale of the “New World.” The strings repeat a two-note semitone rise, growing denser and louder, then horns and trumpets state the E minor theme loudly while the other instruments support with short chords. After the theme is repeated once more, the violins take it up. **How much quieter the strings'' opening is than the brass theme** is where the three performances differ most.'),
('performance_sectors', 309, 'description_en', '149ee511c78aa82d45cafeecf5741b2b8f4eb19461e9be72b3d55b46586acbb7', 'The complete A minor étude nicknamed “Winter Wind.” Four slow (Lento) bars first present the theme softly, and once the fast section (Allegro con brio) begins, the right hand plays a ceaselessly cascading figure while the left hand carries that theme heavily. **The overall length** differs most among the three performances, from 3:22 to 3:55, and so does where the loudest sound is placed.'),
('performance_sectors', 310, 'description_en', '6332a4325ca64d6e733522b5d2e8846c8337a33a792581d19c7df28e7e6cd3f2', 'The passage in which the Adagietto builds to its last big climax and ends. The strings grow gradually louder until they reach a very loud (ff) spot where the harp strikes an F major chord forcefully, then come down “slowing greatly” and disappear on the quietest (pppp) chord. **How much these fourteen bars are stretched** is where the three performances differ most, from 1:18 to 1:55.'),
('performance_sectors', 311, 'description_en', 'e50fb1a006001f6467e6b6a3d432b69e9a79d7a74a9d10b68049b86e65a9cf1f', 'The fast march that closes the William Tell Overture (Allegro vivace). After a trumpet fanfare, the strings open a galloping-rhythm theme softly and the whole orchestra answers very loudly; in the middle, bassoons and horns lay very soft, gentle long notes over fast violin figures. **How deeply this middle section is lowered** is where the three performances differ most, and so is how loudly the last minute is pushed.'),
('performance_sectors', 312, 'description_en', '9ccd568e49367e57cac2b7f9f9a34e96ad6505a814f58667ed8ea28482111232', 'The complete first movement of Shostakovich''s Piano Concerto No. 2. The bassoon first states the theme and the piano answers with single notes spread in octaves between the hands; in the middle a new D minor theme gradually fades, and then the orchestra suddenly bursts out loudly. After the big climax, the piano plays a fugato alone. **How much the D minor passage and the piano solo passage are lowered** is where the three performances differ most.'),
('performance_sectors', 318, 'description_en', '779c3f1a1e4250b2f2a42a160be1ffe46c656000fa1319a076a8723410f09d7a', 'The complete F# major barcarolle: over a left hand rocking in 12/8, the right hand sings in thirds and sixths. The middle moves to A major and begins softly (sotto voce); at the end the F# major theme returns loudly (f), swells to very loud (ff), passes through a soft fast figure, and closes very loudly. **Whether the loud passage of the early theme is played as loudly as the ending** is where the three performances differ most.'),
('performance_sectors', 319, 'description_en', '79b97a519369a80b5d299962c46d2908944c860cd5b9e3bc7170ef2e8c1b2b0f', 'Liszt''s arrangement for solo piano of Schumann''s song “Widmung” (“Dedication”), in A♭ major. In the middle E major section, the right hand repeats triplet chords softly, and later those triplet chords return in A♭ major to support the melody at fortississimo (fff). **How leisurely it unfolds** is where the three performances differ most, from 3:29 to 3:55.'),
('performance_sectors', 320, 'description_en', 'b7bab9a0afa0365a90cc84bcc529a505cf1948bf7ebc1a1c15676ebdb0f6fd72', 'The opening of the funeral march, the third movement of Chopin''s Sonata No. 2. The left hand alternates chords of B♭ and G♭ major like tolling bells, and above it the melody, repeating the single note B♭, walks softly (p) before moving to a passage piling up loud (f) chords. **How low the soft steps are held before the loud chords** is where the three performances differ most, and the lengths also range from 1:13 to 1:31.'),
('performance_sectors', 321, 'description_en', 'b0ba2456af1067776897630c45e9e88022075c32fc012d0966f9d3d857294cdf', 'Rachmaninoff''s solo piano arrangement of Kreisler''s “Liebesleid.” It starts as a waltz in A minor, passes through a faster section that turns to A major, and after a very loud (ff) climax goes through a soft fast figure and closes in A major. **How deeply the soft passage after the climax is lowered** is where the three performances differ most, and the lengths also range from 4:11 to 4:50.'),
('performance_sectors', 322, 'description_en', '371083d0ffca1e4cf108030038f6bcf5d336f2eb3078929c92c5e4003db4c627', 'The complete C major étude, the first of Chopin''s Op. 10. The right hand runs up and down sixteenth-note broken chords built on tenths through as many as six octaves without pause, and the left hand supports with a slow melody in octaves. The score says f throughout and never rises to ff, so **where the loudest sound is placed** is where the three performances differ most.'),
('performance_sectors', 327, 'description_en', 'b0a66b23dbbd32420147f4f53cdc8d4cdcc39a514035c14dc49879a8facbedfa', 'The complete slow movement in F major made widely known by the film Elvira Madigan. Muted strings first play the whole theme over a triplet accompaniment and pizzicato, and then the piano enters and sings the same melody. **How slowly it is drawn out** is where the three performances differ most, from 6:08 to 7:04.'),
('performance_sectors', 328, 'description_en', '6171bdb94b5f93a0e9ed231cc64ce1c4b670acfaf58faabb56f18a4c8c1f93ca', 'The complete B♭ minor Adagio, which Barber arranged for string orchestra from the slow movement of his string quartet. The melody moving stepwise up and down piles up higher and higher and reaches its climax on four big chords; after a long rest the first melody returns and fades on an unresolved chord. **How slowly it is drawn out** is where they differ most, from 7:23 to 8:33.'),
('performance_sectors', 329, 'description_en', '1d1584b03a9fb9f2221b7d94b046d0628e68e794291fe478050b954f26d7c5a6', 'The opening of the first movement of Symphony No. 25, heard at the start of the film Amadeus. The strings state the G minor syncopated theme loudly and repeat it once, then the oboe touches the notes of that theme softly in long notes, and as the music turns to B♭ major the string tremolo surges again loudly. **Whether the repeat of the theme is also pushed loudly** is where the three performances differ most.'),
('performance_sectors', 330, 'description_en', '94b73967920bf4ff463de477af01d9c1fdf8cb9e5a35a87b2bdfcd48e056cc4c', 'The complete third movement of the Gran Partita, in which Salieri in Amadeus marvels as he points to the oboe and clarinet. Over an E♭ major accompaniment in which the winds repeat notes like a pulse, the oboe sustains one long note and the clarinet takes it up, and then three instruments, including the basset horn, trade the melody. **How slowly it is drawn out** is where they differ most, from 4:57 to 5:50.'),
('performance_sectors', 336, 'description_en', 'e8d24fa0f0cf470e4995c09e46ad18d469394d311ca782b1daf34e2d538bca34', 'The fifth piece, closing the Mother Goose Suite, a C major piece marked slow and solemn (Lent et grave). It opens with soft strings, sings quietly for a long time, and closes loudly with glissandos in the last bars. **How long the final loud passage is held loud** is where the three performances differ most.'),
('performance_sectors', 337, 'description_en', 'a093884c194c97cd75b502d1b873cc1a1eb5044f597c7c730efe1c4eae30e79d', 'The instrumental sonatina that opens a cantata written for a funeral. Very slowly (Molto adagio), two recorders echo each other, supported below by two violas da gamba and the continuo. **Whether the sound fills out loudly from the start or opens softly and grows toward the middle** is where the three performances differ most.'),
('performance_sectors', 338, 'description_en', '79429ee790fcf6304672074c4e134c1d2a86a4e7844c10768848e7c27d61abf1', 'An aria in C minor based on Simeon''s song as he holds the infant Jesus in his arms, singing “I have enough; I would gladly depart even today.” The oboe first brings out a melody leaping up a minor sixth, and the solo voice takes it up and sings “Ich habe genug.” **How slowly it is sung** is where the three performances differ most, from 6:45 to 8:07.'),
('performance_sectors', 339, 'description_en', 'e1591dac194fe89d67a064d32433313f90f4f5ab33c82ce9f241d0956be8c53e', 'April from The Seasons, a B♭ major piece depicting the spring flower the snowdrop. A poem by Maykov is printed at the head of the score, the marking “un poco rubato” is given, and there is a D minor section in the middle. **How deeply and long the soft passage is held** is where the three performances differ most.'),
('performance_sectors', 340, 'description_en', '025df993adc9557806708bc7965ef579553c1bc2fdd48b28809b13bf4b5fbd3e', 'Solveig''s song from Act IV, which she sings in front of the hut while waiting for Peer Gynt. The strings open the prelude in unison, and after two rounds of the A minor verse (Un poco Andante) and the wordless A major dance-like section (Allegretto tranquillamente), the strings close again. **How slowly it is carried along** is where the three performances differ most, from 4:46 to 5:52.'),
('performance_sectors', 346, 'description_en', '61fefdfb9c76cfa51bfc7d236836b9161282772624575401cb233edeb1c0eb77', 'The passage in the slow second movement of Mendelssohn''s Violin Concerto (Andante, C major) where the solo violin sings the first theme. A long melody resembling the composer''s own piano collection Songs Without Words continues and ends just before the dark A minor middle section. **How slowly it is sung** is where the three performances differ most, from 2:45 to 3:19.'),
('performance_sectors', 347, 'description_en', '848280259bce55bbcad9c6b3d7a2e4e58e863d52ce1b17bd9b91d62423cb5ec8', 'The opening of Saint-Saëns''s Danse Macabre, where the harp strikes D twelve times to mark midnight. The solo violin, with its E string tuned down to E♭, draws a tritone, and after the flute''s waltz theme and the violin''s descending second theme, the whole orchestra sounds the waltz loudly. **Whether the big climb 30 seconds before the end is made in one go or in two stages** is where they differ most.'),
('performance_sectors', 348, 'description_en', '604593c44e5f6f18e831c070a97163a6272e12f8c366411a680f4005e4daff5c', 'The slow first part (Andante, E major) of Rosina''s cavatina “Una voce poco fa,” which she sings holding a letter. After the orchestral prelude the song of confessing love follows, and the forceful vow “Sì, Lindoro mio sarà” appears twice, before and after. In all three, a mezzo-soprano sings in the key Rossini wrote. **How long the same passage is sung** is where the three performances differ most, from 2:10 to 2:35.'),
('performance_sectors', 349, 'description_en', '0825290d628d120a74f5e43da5415bb9f6cbf8da0d7f6732f59ba2d3ce8318b1', 'The passage in the second movement (B major) of the “Emperor” Concerto where the strings'' hymn ends and the piano enters for the first time. The piano comes in softly, descending from a high note, and continues the song; in all three performances it grows louder toward the end. It includes only what was heard in the film, so it ends mid-phrase. **How slowly the same passage is unfolded** is where they differ most, from 48 to 58 seconds.'),
('performance_sectors', 350, 'description_en', 'd2922dd45553a3999bbfefe01bfe54599210c063f17778d661046065762be4fe', 'The passage where the finale of Chopin''s Piano Concerto No. 1, the Rondo (Vivace, E major), begins. After a brief orchestral opening, the piano presents the rondo theme for the first time, in the rhythm of the Polish dance known as the krakowiak. **Whether the last phrase of the theme is built back up to close** is where the three performances differ most.'),
('performance_sectors', 355, 'description_en', 'f30e558c40155ab71735724e4491ce7a1bb11c3f5c5fa47055ca8ecd38c5b9b2', 'The complete work for violin and orchestra that Saint-Saëns dedicated to Sarasate. Over plucked strings the violin sings a slow, melancholy introduction (Andante malinconico); in the fast rondo the orchestra-only tuttis break in loudly twice, and the ending turns to A major and closes faster (Più allegro). **Whether the loudest sound comes in an early tutti or the final chord** is where the three performances differ most.'),
('performance_sectors', 356, 'description_en', '7be6b6819d83536582cfe3bc94c33fb871cbf3d2a7091b330f1a18104d21cbd1', 'About the first three minutes of the fourth movement, in which Mahler set the “Midnight Song” from Nietzsche''s Zarathustra. Over muted cellos and basses alternating between two notes, the alto sings “O Mensch! Gib Acht!” (O man! Take heed!), and the oboe draws notes upward “like a sound of nature.” The score marks the whole passage “very soft throughout” from the start. **Which phrase carries the loudest sound** is where the three performances differ most.'),
('performance_sectors', 357, 'description_en', '7ef7f6a9ef5292d5957f9197ff8c8c95bb427b41402bae0bf6a0e3c0fc445b1a', 'The Venusberg dance that opens Act I of Wagner''s Tannhäuser. Bacchantes break roughly into the nymphs'' dance, and when the sirens sing “Naht euch dem Strande” (Come to the shore), the dance answers more wildly and subsides at the end. All three use the Dresden version, before it was greatly expanded for Paris, and **how fast they drive it** is where they differ most, from 4:29 to 5:00.'),
('performance_sectors', 358, 'description_en', 'd10927ae100466eeeb48621d92bf22fa14646394d328a87dc2a4b416f60ea056', 'The Act II finale scene in which the statue of the Commendatore accepts the supper invitation and visits Don Giovanni. The chords that opened the overture turn into a diminished seventh and sound louder (ff) than in the overture as the statue enters; Don Giovanni, refusing to the end to repent, is dragged to hell in the Allegro amid a chorus from beneath the earth. **How slowly it is drawn out** is where the three performances differ most, from 6:31 to 8:01.'),
('performance_sectors', 379, 'description_en', 'fe6e850b062785ea906b014661f44e87c4804417e562095ecd61f7741a7d7ef1', 'The first two minutes of the last symphony Mahler completed. Cellos and horns touch A in alternation and the harp sounds a four-note motif, then the second violins trade a D major theme falling two notes at a time with the horn. At the end it turns to D minor and brass and timpani enter loudly. **How slowly the D major opening is drawn out** is where the three performances differ most, from 2:01 to 2:22.'),
('performance_sectors', 380, 'description_en', 'b9b6d0539b5c5006d74f8e9ac111efe9b84232d5c09dd9688b4455a914a8927c', 'The opening of the overture to Wagner''s opera about the cursed sailor condemned to wander the sea. Over strings storming like a tempest, horns and bassoons blow the Dutchman motif loudly; the whole orchestra strikes twice, at ff and fff, then gradually softens and halts on a rest. **How big the build is from the first f to the ff** is where the three performances differ most.'),
('performance_sectors', 381, 'description_en', 'f0843e6a004bc5ec28f6d3efb3d4f2b3fa9ebfbab1771850fb5c3ae5698eb94d', 'The slow opening of the overture to Wagner''s early opera Rienzi. The trumpet swells and fades on a long A, sending a signal three times, and the strings answer softly each time; after a passage rising by semitones, the strings sing the melody of Rienzi''s Prayer from Act V all the way through for the first time. **How loud the trumpet signals sound** is where the three performances differ most.'),
('performance_sectors', 382, 'description_en', 'c17c7f7e43539313d82c5eea0af13b3832c435ab67617acf4091391332c05ff1', 'The opening of the last symphony Bruckner never finished. Over a soft D tremolo in the strings, eight horns sound the introductory theme; the horns rise loudly, moving the harmony far afield, then subside, and the passage ends as the music begins to build again. **How quickly the introduction is moved along** is where the three performances differ most, from 1:45 to 2:06.'),
('performance_sectors', 383, 'description_en', '2459a4aa0b2929a0318a0263af488af22beb0310d29cd150c250347b6570ea2e', 'The 3/8 Allegro that closes Vivaldi''s Bassoon Concerto in E minor. The tutti plays the ritornello four times, and in the solo passages between them the strings mostly rest while the bassoon continues its fast figures with the continuo. Lengths range from 2:50 to 3:19, and most of that difference comes from **the length of the final tutti**.'),
('performance_sectors', 384, 'description_en', '289999c4750b1937801f439b4599b8ffad26c856d7dfd2a46a89e757a2821629', 'The slow introduction (Adagio sostenuto) that opens the first movement of the Kreutzer Sonata, and the first theme of the Presto. The violin alone opens with four bars on an A major chord, the piano answers and leans toward the minor, and after stopping very softly, the piano echoes the theme the violin brings in at the A minor Presto. The ending bar is the same in all three, and **how slowly the introduction moves** is where they differ most, from 1:28 to 1:55.'),
('performance_sectors', 385, 'description_en', '65938e8acab748bda44a96c7f53bc1be5c37bf2a79389a8a9c2382f37a083543', 'The passage where the polonaise begins in Chopin''s Andante spianato et Grande polonaise brillante. The orchestra sounds a signal in polonaise rhythm and rises in a crescendo to ff, then after a bar''s rest and a soft slowing, the piano brings out the E♭ major theme a little more slowly (Meno mosso). **How low the orchestral crescendo starts** is where the three performances differ most.'),
('performance_sectors', 386, 'description_en', '2158c339c45ecd99d7e5c78b075eb6990997f5591a7f017b40a8b16bd0de22fb', 'The complete first movement of Mozart''s Sonata for Two Pianos in D major. The two pianos begin by sounding the same melody forcefully in unison, then one takes up a phrase the other has brought out, and they share the themes. All three repeat the exposition, and **how deep the soft passages are** is where they differ most.'),
('performance_sectors', 387, 'description_en', '419e1d6de33c5bc106d01d2798308cf3fd81cd2124365715d32894a06b472270', 'The complete first movement of Mozart''s four-hand sonata in C major, played by two people sitting side by side at one piano. Primo and secondo bring out the theme forcefully in octave unison, and then trade delicate answers; all three repeat only the exposition. **Lengths range from 8:06 to 9:04**, and whether the loudest sound is placed at the start or at the end also varies.'),
('performance_sectors', 388, 'description_en', '97c3d1239a42248d5a278b7ce79c98f5db1870e9360301685674831a7b0ff3b5', 'The Adagio from the ballet, depicting Gayane''s despair. It is played by strings alone and begins with a slow, smooth melody in the low register. **Lengths range from 4:22 to 5:06**, which is where the three performances differ most, and how deep the dips between the loud passages go also varies.'),
('performance_sectors', 389, 'description_en', '35d238c79eae4e95f0d8cabafa49b4166eb7ed842aedde55526d6f8f5a59a3ee', 'The Kyrie in which twenty voices, five parts each divided in four, layer semitone-moving melodies so densely that it is heard as a mass of sound rather than individual melodies. It is built as an enormous fugue, and the middle section where Christe is sung is much gentler. **How deep the soft middle passage is** is where the three performances differ most.'),
('performance_sectors', 390, 'description_en', 'd65c57ad3d65afc2b5f27ed77ab34ce5fa007de66d18ae3504afb395e5f4849c', 'The first aria (Larghetto) of a shepherd weeping over the heartless Dorilla. To depict the word “weeping” (lagrimar), Vivaldi has the strings of the same part play partly pizzicato and partly with the bow. **How soft the pizzicato opening is** is where the three performances differ most.'),
('performance_sectors', 391, 'description_en', 'bdd0bb47565a2a6dd5fcc4846e4b21bdd8cfe4c3131f17d89005f96fa026979f', 'Rodelinda''s Act II aria, in which she, having promised to marry Grimoaldo only if he kills her son with his own hands, defies him with “Spietati” (merciless ones). In the middle she sings that she can never join hands with that cruel man, then returns to the first part. **The length, from 4:13 to 4:51**, is where the three performances differ most.'),
('performance_sectors', 392, 'description_en', '424eedabfbb93870d68ce448febb8a2ff5588d9480c1c9e38a085b63ea1e1e0f', 'The first 44 bars of the “Eroica” first movement. The whole orchestra strikes an E♭ chord twice loudly (f), then the cellos bring out the theme softly (p), and in the seventh bar it veers off to C♯. With repeated sf accents, the whole orchestra sounds the theme very loudly (ff) at bar 37. **The tempo at which the same 44 bars pass, in 47 to 52 seconds**, is where the three performances differ most.'),
('performance_sectors', 393, 'description_en', 'fb2c3a7da0b57e6e0b358e37c504ca7a886fc799f31c55fd651bdfe1fa60cf7b', 'A piece in which a 16-part chorus sings, without accompaniment, the “eternal light” phrase of the requiem mass. The women''s chorus starts on a single F and widens the pitches, in the middle the sopranos enter clearly on G and the chorus spreads over more than two octaves, and later the sopranos and tenors touch B, the highest note of the piece. The score has no marking louder than p, and **how deep the later soft passage is** is where the three performances differ most.'),
('performance_sectors', 394, 'description_en', 'f8556f6caa1c6092514e1103433b561822c28922c111804b71b95e24ca8b5f82', 'Halvorsen''s rewrite for string duo of the Passacaglia, the last piece of Handel''s harpsichord Suite No. 7 (G minor). It was originally for violin and viola, but all three performances use violin and cello. Over a four-bar theme it varies with changing techniques such as pizzicato and ponticello and closes on a G major chord. **How deep the soft middle passage is** is where the three performances differ most.'),
('performance_sectors', 395, 'description_en', 'd6e4a2b360df9bb96b4314403ed43e41e419fe6b9c4194992366caa419875b6e', 'The slow introduction of a symphonic scherzo that follows Goethe''s ballad. Over muted strings the clarinet first presents the broom theme, the music suddenly races ahead, and after a single timpani stroke and a long rest, the bassoon plays that theme through to the end for the first time. **Whether the racing passage is played at full strength right away or builds toward the end** is where the three performances differ most.'),
('performance_sectors', 396, 'description_en', '7f601bc6eab9df7b2b542d51bad30ecd21765409ac650eaf3b2be3360253a5fa', 'Rodelinda''s last aria in Handel''s opera Rodelinda. At the end of the opera she sings of her joy and love at being reunited with her husband Bertarido. All three performances come close to full volume once early on, and **how long and deep the soft passage that follows is** is where they differ most.'),
('performance_sectors', 397, 'description_en', '4f87e5da6e302dd188a2f0da9aa2a9ec9fd0816bb3db5752353ec54af90212c9', 'From the return of the closing theme in C minor at the end of the first movement''s recapitulation to the stop on the diminished-seventh fermata. The closing theme, which starts softly (p) and rises to f, appears twice; after the rising figure of the first theme returns, a very loud (ff) diminished seventh is held at length. **How long the final diminished seventh is held** is where the three performances differ most.'),
('performance_sectors', 398, 'description_en', 'e80fc8557830a968d3a53743d14428b672d3b6d2c93f493a73f1243db04db058', 'The introduction that opens the tone poem, “Sunrise.” Over a low C held by organ, contrabassoon and double basses, the trumpet plays a rising C–G–C motif, and the harmony shifts between major and minor before closing loudly in C major with the organ added. **How much time they take to reach the final C major** is where the three performances differ most, and the lengths range from 1:38 to 1:57.'),
('performance_listening_notes', 59, 'headline_en', 'f330724f6452bd69afb51c6afc2a12a465a8fa681d8be724f996312f14d0bd75', 'One big peak, reached early'),
('performance_listening_notes', 59, 'note_en', '724cfa7cc82c391770cd761c8f72269ac7700a5171fc598de91fcafcdf4cee4d', 'Earlier than the other two, it already reaches nearly maximum volume in the opening phrase. After catching its breath once, it hits the climax on that chord.'),
('performance_listening_notes', 60, 'headline_en', '0308055233f9d5e0bba38de80566a7bbbc58e60097dc6fac51954f7df4d4adb8', 'No repeats, 1 min 10 sec'),
('performance_listening_notes', 60, 'note_en', 'a49a200ff7224e40df77b1540cd9a9ff91347850357752e20f97f8f09d88adf6', 'It plays each of the two halves only once, so it is much shorter than the other two. From the first beat it drives to the end at nearly maximum volume.'),
('performance_listening_notes', 60, 'facts_en', 'a49a200ff7224e40df77b1540cd9a9ff91347850357752e20f97f8f09d88adf6', '["No repeats"]'),
('performance_listening_notes', 61, 'headline_en', '0d0901faf451b287891d13f1fc3092d1d9a599dcf53a7fd4970259ff4f51e34a', 'Soft opening, long loud stretch'),
('performance_listening_notes', 61, 'note_en', '61f2bbf7c0e6cb4e1ab16f39cea3a05ccbec2785bd100a259a576e829fdc148e', 'Starts the softest of the three. Its loud passages last the longest, and after pulling back once it rises to the climax.'),
('performance_listening_notes', 62, 'headline_en', '952024b3d52720e5d7ac315f122b9bf3a837c297176106452854339f67ff667c', 'One build, no ups and downs'),
('performance_listening_notes', 62, 'note_en', '5b07a957f1d3556e2d22f83761d5a37ad7ac18b80681fe6c93408ecfa08148f4', 'Has the least rise and fall of the three. It stacks up in one go from the start and reaches its climax the latest of the three.'),
('performance_listening_notes', 63, 'headline_en', '5064431ef6140b01bedb948b2cf0fe05768180c1e48d6b41d8c637d96c2f6c9b', 'Shortest, loud from the first note'),
('performance_listening_notes', 63, 'note_en', '60c2346f8e56e7fd910743b93968436e16fb49d26b254afc13d20485b1d132fa', 'At 1 min 9 sec, it is 16 seconds shorter than Gilels. It enters loudly from the first note and reaches nearly maximum volume within 10 seconds.'),
('performance_listening_notes', 64, 'headline_en', 'ff67c18041dd786a5dc3f89e8465182f611b5ec179f4b1a993868308b941451b', 'Softest opening phrases'),
('performance_listening_notes', 64, 'note_en', 'f30a10b3bb8d3709f707b99c2cbf18ee87a443d290043068cab7625adc87f4a4', 'Holds back the opening phrases, keeping them the softest of the three. It builds in one move at the middle and rings out loudly just once.'),
('performance_listening_notes', 65, 'headline_en', 'b83f4311b6aace2e9c317d4f3d7ef4012952bc5aef1ac04b537deee82a8a9b55', 'Alone in peaking near the end'),
('performance_listening_notes', 65, 'note_en', 'f5c3510bf8330f95b96b1fc4f1da1cab12d5ab58bf90537a74f3043755dbc195', 'The other two press hardest around the middle, but this one alone presses hardest near the end.'),
('performance_listening_notes', 66, 'headline_en', 'fd0636c54ac848537bd25f8c2f7a546bece4cc12be38a62bb6cf0e7c34c73738', 'Sets the ending down softly'),
('performance_listening_notes', 66, 'note_en', 'd64d1f1882de6c1f958a7453d7297552e87fe94867f8c7a85318320be8013428', 'Enters loudly from the start and pushes on to the middle without a break. The final phrase is set down much more softly than Seong-Jin Cho''s.'),
('performance_listening_notes', 67, 'headline_en', '0a7f5ad8e307f0cdd6be3fab71a996ca28458f1732cfc5f424375a268c02b4de', '1 min 25 sec, two pull-backs'),
('performance_listening_notes', 67, 'note_en', '7ccaa5c8879a1660775ca2bb67d2b15d1b42659d359974b93adcc0ec3ce0668d', 'At 1 min 25 sec, it is longer than the other two. It pulls back twice before the climax, then pushes on again.'),
('performance_listening_notes', 68, 'headline_en', 'b97ae6846e2cea8bab50979a7240eb95637f372b4dcc987e0035bfa9a7643456', '34 seconds, ending set down'),
('performance_listening_notes', 68, 'note_en', '3cff78b2c5b0e729f68426b16aeb9c94bd5ecd33e1c83bc4fe3bb94f09bfa13d', 'At 34 seconds, it is the longest of the three. It presses hardest in the middle and sets down the ending the softest of the three.'),
('performance_listening_notes', 69, 'headline_en', 'a1f087766a407563e77f7f2b3d82ac5ec62becf0a4e107eb46108d5e8b69b8ac', 'Pulls back, then peaks first'),
('performance_listening_notes', 69, 'note_en', '98acfbae13a7501cbb440628caa3a462cef0058a0d41fa25cbe87d449c747062', 'After building once and pulling back, it reaches nearly maximum volume earlier than the other two. It also sustains the loud playing for a long time.'),
('performance_listening_notes', 70, 'headline_en', '64c3be358341b2637f49d19d0151463542ada163c5ce8139d17bb93b00747928', '26 seconds, the fastest'),
('performance_listening_notes', 70, 'note_en', '6c31564d82fac6d4fa4fb043d5e3f5d42bdb9e764dad49b7546b702ab4f755e8', 'At 26 seconds, it is 6 to 8 seconds shorter than the other two. It sustains loud playing longer than Horowitz and Andsnes, and the ending hardly softens at all.'),
('performance_listening_notes', 71, 'headline_en', 'da64e1b95f79db6e2aa17543ceb0cbfad71d2b7659cdce8be82ab55436601cd0', 'Deep pull-back, short peak'),
('performance_listening_notes', 71, 'note_en', '09f67916c957c3e4e356d1a8c03d35fa4f102208aecb5f009deb2d630d2655c7', 'After building up, it pulls back deeper than Ashkenazy. Loud playing is brief, and it sets down soon after.'),
('performance_listening_notes', 72, 'headline_en', '3034332843c64782dcfb4ed930ac322b38598c5830cea48195a54664e8e8c820', 'Repeats kept, brisk pace'),
('performance_listening_notes', 72, 'note_en', '96e842af863d2713edf0544f1938bfcd77ca2f04706eb1da410ea68bebd26ac7', 'It takes both repeats yet finishes about 30 seconds sooner than Levit. On the repeats it plays evenly, at about the same volume as the first time.'),
('performance_listening_notes', 73, 'headline_en', 'de475c3f401b45c59dda969dbfc0e5ac41f1213bce190c45964a76d35a86a79c', 'Climax at the final cadence'),
('performance_listening_notes', 73, 'note_en', '5334a7457a957703910ca74d61fa2c2ff8c58533599d31106bc20add88d9568b', 'Takes every repeat and plays the longest of the three. It stays even to the end and strikes loudest just before the final cadence.'),
('performance_listening_notes', 92, 'headline_en', '24ff093b8b76e504b9faeb84bec65c8f947da44f06e60af38837033121981f3a', 'Soft, as the score asks'),
('performance_listening_notes', 92, 'note_en', '63788245ac29eba833a17daf0845cf226e69c8b484fed817038eb430395b762f', 'Starts the softest of the three and grows bit by bit until the last quarter. At the end it steps down a level.'),
('performance_listening_notes', 93, 'headline_en', '14462073559d1777b6161535bd93a1462449bc3c1484b3a5cf4c37801e6b70a6', 'Thunderous from the start'),
('performance_listening_notes', 93, 'note_en', 'eed6e6e0994dd526743dc1a2e43f22553f792fe2bd25084abea2b0537dd1e5d1', 'Enters at nearly maximum volume right at the start, and that level hardly drops until the end. It presses on as a single mass with no room to breathe.'),
('performance_listening_notes', 95, 'headline_en', '1e8875014cf5e8a1a4938ef88fc920ba951fcf1cab5341585fe5e2bf7aab9374', 'Back half a level lower'),
('performance_listening_notes', 95, 'note_en', 'bc4169a63626e2ce48c816aace6a2e0f14568522c418aa0610450c4cc7d994d1', 'Rings loudest in the first 10 seconds, then steps down a level and keeps the later part low. Its softest spot is also the deepest of the three.'),
('performance_listening_notes', 95, 'facts_en', 'bc4169a63626e2ce48c816aace6a2e0f14568522c418aa0610450c4cc7d994d1', '["Dutoit · Verbier Festival"]'),
('performance_listening_notes', 96, 'headline_en', '5e81539ca916f50e737efc0ffc65ad3fb67a673a9dec76fd5c39224dca8c6480', 'From soft to full orchestra'),
('performance_listening_notes', 96, 'note_en', '585ddaa8462eecf7a89eab4236b4484af36016b48f297fc3bdb0299c9f9eddf6', 'Alone in starting from a soft sound, it rises to the full orchestra within 8 seconds. The time it sustains loud playing is the shortest of the three.'),
('performance_listening_notes', 97, 'headline_en', '8cc26ecb97b8115314ba9ed3c813d1d86aed5866281af17950bfd153719bfe78', 'Soft right after the climax'),
('performance_listening_notes', 97, 'note_en', '7cc4d8649fbefba28f81903a985c81da718f0c2984c7f3951f7503848057291e', 'Drops to soft right after the climax and leaves it soft for the last 14 seconds. It sets down the soonest of the three.'),
('performance_listening_notes', 98, 'headline_en', 'bee2443df9f31f192fc4872ec60fd24c8c7418695ec6490cd2dd3f28c81316d6', 'One drop in the middle'),
('performance_listening_notes', 98, 'note_en', '4b0be4dc3339646a3e55d48dcc24bc8e06902baa4da73bea506c5130d2138998', 'Plays the first chord the hardest, then lets go sharply once in the middle. Before the end it climbs back to nearly maximum.'),
('performance_listening_notes', 99, 'headline_en', '1e1c2cdc1384619000ec7cffb5fb3c537ffd8318e5bdcb372743cf8d096e4b28', 'Sinks the deepest'),
('performance_listening_notes', 99, 'note_en', '45dfd0f3ec08778a1f1b1f1078b62942517e48b52262a145aa74f7b86e09de8d', 'Sinks the second soft passage the lowest of the three. That makes the contrast the greatest when it surges again.'),
('performance_listening_notes', 100, 'headline_en', '41b01f431f5cb4e15c9b74db93d08be2050f154e31f474635b6fd1f320f7af2f', 'Loudest in the first part'),
('performance_listening_notes', 100, 'note_en', 'f31c4221537fedbd52c7756a4149beba260e768d912011d91fd67ef03e6b8a19', 'Plays the first third louder than the other two. It cuts back all at once in the middle, then climbs again.'),
('performance_listening_notes', 100, 'facts_en', 'f31c4221537fedbd52c7756a4149beba260e768d912011d91fd67ef03e6b8a19', '["Järvi · Orchestre de Paris"]'),
('performance_listening_notes', 102, 'headline_en', 'c138f0aee7a3de78c6a23ee7145e7857b024fbdd6c9cfb25f38e3538c152bce4', 'Held back, then a storm'),
('performance_listening_notes', 102, 'note_en', '75aa90e93863e078dced0f0e66e1af1a9fd62a865d1aedd27ccfdfdfc845bb9c', 'Saves its strength for the first few seconds and builds bit by bit. The loudest sound bursts out 5 seconds before the end.'),
('performance_listening_notes', 103, 'headline_en', '0cb78b5322042f78ddddc107022b429f7291d3a0f3edce9ad584125a05ae75f3', 'Builds and lets go, repeatedly'),
('performance_listening_notes', 103, 'note_en', 'd0feb3b84fc28b8aff1d9fd0857fd67b4b5ea89c96f2ff164cdb8aec48005dd4', 'Rather than building in one go, it builds and releases phrase after phrase. After the climax it lets go the most of the three.'),
('performance_listening_notes', 105, 'headline_en', 'ca8a07ad7c6d81023722c856aa734c9e17e0c9970841196f85a9b037ec67ba68', 'Near maximum in 10 seconds'),
('performance_listening_notes', 105, 'note_en', '17443ae260e2c167d8de3c5a8b9820e9bd8268bc8000cce69139b486ca1b2198', 'Builds from the very start and is almost at its loudest by about 10 seconds. It never comes down to the end, so it ends up the furthest from ‘soft’.'),
('performance_listening_notes', 106, 'headline_en', 'd061f5bfd5c0ae7bfb23c66225bd4dee92015355bf61d0d5161dbb112746eeef', 'Dips only a little in the middle'),
('performance_listening_notes', 106, 'note_en', '14f99eda58ebf9329c73276b0820758ff44b76b9f2d4125e3795cac0e9ce86d4', 'At 58 seconds, it is 6 seconds shorter than the other two. It sustains loud playing longer than the other two, and even the middle comes down only a little.'),
('performance_listening_notes', 107, 'headline_en', '5006014975650e5bc9dd01a9a27cb21d70a6536ec19a8689cf5b58dc00b24bd0', 'A long stay at the top'),
('performance_listening_notes', 107, 'note_en', 'f82c7c957e1477b58b798e299804d0107c53b2f8b22ff14183f423bc95860fbc', 'Holds the third surge at maximum volume for almost 6 seconds. It sustains loud playing the longest of the three.'),
('performance_listening_notes', 109, 'headline_en', 'b331a6aab4b99135338a4ab5e739d60cab6328196c66f608576cc979555ad711', 'One more at the end'),
('performance_listening_notes', 109, 'note_en', 'afddddb508b733eeaae034596de56540cc92b0a2392adf02028e099f949f6f4c', 'The flow is more even than in the other two. Near the end it reaches nearly maximum once more, and the close is also less soft.'),
('performance_listening_notes', 122, 'headline_en', 'b9813b10dddf9e0ddd68c8071eb16fbb8ba5fd9220fcf7afd446c02e6b5b92d7', 'Ends softly'),
('performance_listening_notes', 122, 'note_en', '8b0d6f605133bef50655d8ca8046d5a0316acf541cfd2b08cdc66fbe0a35502b', 'The pattern of playing loudest after the figuration returns is the same as Kissin''s. But the ending is much softer than Kissin''s.'),
('performance_listening_notes', 124, 'headline_en', '04ee1ebc50cb74057e89a824eaddd53d61e875056a4a158cc6fae9344704859d', 'Weight on the opening'),
('performance_listening_notes', 124, 'note_en', 'b41a9f8a4a67402cdbdb593d4bcad46af0c18fc6417e1924f65159403833d5ab', 'Alone in playing loudest in the opening section. From the middle it steps down a level, so its loud playing is shorter than the other two''s.'),
('performance_listening_notes', 125, 'headline_en', '77f02a2b4d2d8b0c9116d792ef735d9a514781cd7ddc064b9a1fb117385583f1', 'Most even to the end'),
('performance_listening_notes', 125, 'note_en', 'a1f629b2508aedc18d9d53ce25ed40c3709ef8d07071ad916b4a2653c88fcf76', 'The smallest difference in volume among the three, and it reaches nearly maximum the earliest. The ending also doesn''t get as soft as in the other two.'),
('performance_listening_notes', 129, 'headline_en', '8f71c0a1f63a89db36f98778eac294608f3d65943f06d0106bd733a301552d60', '3½ minutes, the shortest'),
('performance_listening_notes', 129, 'note_en', '9d8c5568f295374e9a6d68f3d0e858934145511444eed7120d4070046c1f0b02', 'At 3 min 30 sec, it is more than 30 seconds shorter than the other two. It already raises the volume to nearly maximum at the peak of the first melody.'),
('performance_listening_notes', 133, 'headline_en', '18382761f87644fbcc5e7ab4418a36a67d53b78c894c2fe52a3d07e1e8b00ddb', 'A very soft first melody'),
('performance_listening_notes', 133, 'note_en', '3c073f1ae49be48ba17a14c3fb9fb0b974c6fb198b22079a196321fd6b555fe1', 'Sings the first melody the softest of the three. Before the middle it sinks deeper still, and only just before the climax does it reach maximum.'),
('performance_listening_notes', 134, 'headline_en', '033808b0c0a893f0ff7c83c5dc422cc95ac3365454a64cce08219f50a2066b8a', 'A first melody kept up'),
('performance_listening_notes', 134, 'note_en', 'cac134cdacb6b3ab7ba4c4b9ccfa6bb226ff42184fdd05fa2b4434472a77b25d', 'At 4 min 17 sec, it is 47 seconds longer than Pollini. It doesn''t lower the volume much from the first melody on, so the gap between soft and loud is smaller than in the other two.'),
('performance_listening_notes', 137, 'headline_en', '04eb6fbf3f3e2c445fd53a38e492c8c3a40260e313ed6ddc5594de0a621783d9', 'Builds to the end'),
('performance_listening_notes', 137, 'note_en', '2161c4cd5f72aafe57bb2e95b118f5745c67deaf53f2dd5e855ec8925fe6a07f', 'Grows bit by bit toward the end, placing the loudest sound about 10 seconds before the finish. The ending is also less soft than in the other two.'),
('performance_listening_notes', 139, 'headline_en', '882a41de6b1257def3223118c80d14886cd45e07ec0807cc34e55b765e49f35a', 'Climax placed early'),
('performance_listening_notes', 139, 'note_en', 'd1076fe78aa6b29abb9df84d70879d60276d703b30000f6995e69c14a0e2972d', 'The climax comes earlier than in the other two. After that it repeatedly drops deep, and ends the softest of the three.'),
('performance_listening_notes', 141, 'headline_en', 'a60457818005e694041f278af1e3fecf2675cdc15cae7e9bbfc2720d52624e9f', '2 min 58 sec, even'),
('performance_listening_notes', 141, 'note_en', '785dd7753ce4dd7424567168ee86f82903649183d7e0b651ed969cc166764dd3', 'At 2 min 58 sec, it is more than 15 seconds shorter than the other two. The gap in volume is also the smallest, and it pushes on evenly from start to finish.'),
('performance_listening_notes', 149, 'headline_en', '35756ee3f8d9c910ea22a9d2a95a08d6c0d8e2aa1531ea545ecb7f70bce9fab8', 'Loudest at the very start'),
('performance_listening_notes', 149, 'note_en', 'f048a0244aedefac894bcc5501335eb0334f66a5ad43f9a399c570109cf20a9e', 'Alone in playing loudest at the opening. After that it eases off bit by bit, leaving the ending very soft.'),
('performance_listening_notes', 150, 'headline_en', '174e91f7413819442a9bbe1e46e797092912ef68bae02ff2cd323e830d26d0ad', 'Climax in the very middle'),
('performance_listening_notes', 150, 'note_en', '21a70eb85346dcb7fbb500738e7b9a76458157771388e96f1d93484ed6bbb2d3', 'At 1 min 41 sec, it is the shortest of the three. It holds back at first and rises to its loudest at the very middle.'),
('performance_listening_notes', 151, 'headline_en', '882a41de6b1257def3223118c80d14886cd45e07ec0807cc34e55b765e49f35a', 'Climax placed early'),
('performance_listening_notes', 151, 'note_en', '501fbabc7636c13fd2e0d1681cb45ec5ab31a48762903935967298d81650b5fc', 'Unlike the other two, it puts the loudest sound in the first half of the piece. Ten seconds after the climax it sinks the deepest of the three.'),
('performance_listening_notes', 152, 'headline_en', '43346c71a416f69874bdad44e2cb2407e82ab8f1e4cb2659d1d3f6ebc68db446', 'Climax put off until late'),
('performance_listening_notes', 152, 'note_en', 'da3725f84a6f443ce75e525f8652ad28734e20cfd259fb4ec8a2dfbb77db8bf5', 'At 2 minutes, it is longer than the other two, and its climax comes the latest. Twelve seconds after that it sinks deeply, then rises again.'),
('performance_listening_notes', 153, 'headline_en', 'b5805c588e3c0959cdb53323cad22c8d00d000c2e354f799c3f95d4f68dcedfa', 'Late climax, soft ending'),
('performance_listening_notes', 153, 'note_en', '8c7b0fcfe28240d077d8c5b7860fe8c83a8f94f5cc9325c6845e772a354176c0', 'Puts the climax late, then drops to the quietest point 10 seconds later. It finishes the ending much more softly than Lang Lang and Ott.'),
('performance_listening_notes', 154, 'headline_en', 'c83562bec0d1dca2d17651fee74533a9f6ae5315383d94b660c39fa3abf5311a', 'Softest spot at the start'),
('performance_listening_notes', 154, 'note_en', '33a4f812708ad287b7920221e5e8276220c7ce80386299786edf9e71c5019355', 'Puts the quietest sound at the opening and doesn''t sink much afterward. The gap between soft and loud is also narrower than in the other two.'),
('performance_listening_notes', 155, 'headline_en', '96543a3b07f39923f3603959a20a3c1ba5ac08b11a5adf081f716157db05d0fd', 'Big again on the final return'),
('performance_listening_notes', 155, 'note_en', 'bc5b5b2f1646ea0c9a8332ec2d5f26dcadd6c97a4e3320d49c484c3c1bff4cb8', 'After hitting the climax three quarters of the way through, it pulls back deeply once. On the final return it climbs back to nearly as loud.'),
('performance_listening_notes', 156, 'headline_en', '276a78f37bcc9f47e9544b88c9d74c6c1d7928ce23ee03bb414101e6b93a0834', 'Eases back less after the climax'),
('performance_listening_notes', 156, 'note_en', '67226472b10e09d130a68c447b277a3c12d4829fc74af3e340c07e05eabc4ead', 'Rises to its loudest in the big middle passage. Even after the climax it eases back less than the other two, and it puts its softest point near the end.'),
('performance_listening_notes', 157, 'headline_en', 'a50275b82900003aad2b744bb2692344952b7d8d3f2179e1a9276126e710d38d', 'Deepest drop after the climax'),
('performance_listening_notes', 157, 'note_en', '86125277cbccf171ecfe3ec5b54c8f8c358e7819e8444701b00ab4d4619bf2a3', 'After rising to its loudest in the middle, it sinks within 20 seconds to the lowest of the three. It also sustains loud playing longer than Perlman and Bell.'),
('performance_listening_notes', 158, 'headline_en', '80715fc2ae6f674a876449049b3faaa333486c60a4f06240788164c13ba5745f', 'Softest start and end'),
('performance_listening_notes', 158, 'note_en', '83693e155ed0b047f2a56def97816c9ed1c7c44bf41bb56a71c9bc597410ee29', 'Starts the softest and ends the softest of the three. Before the climax it draws back deeply once, then rises in one move.'),
('performance_listening_notes', 159, 'headline_en', '97e8c76e7170fd820173d7785566f63cea9500b22798f200ebd3fefcfcc86cc4', '30 seconds longer, late climax'),
('performance_listening_notes', 159, 'note_en', 'd633cfaa4baca2eac17df40c9362dc1a3aa2cb1dce3e95db92c7f8f9a4f29b06', 'At 5 min 5 sec, it is about 30 seconds longer than the other two. After one big rise in the middle, it places the loudest sound in the later part.'),
('performance_listening_notes', 160, 'headline_en', '5131c83c1fee3f150e152ae8072b2f45fbd2e8bdcd0619c5c4f43344897dbb19', '6 min 20 sec, soft ending'),
('performance_listening_notes', 160, 'note_en', '5e887c5ca1b54ed6447d33f678a6780d6d9061542282351ea3510c9a976da424', 'At 6 min 20 sec, it is about 30 seconds longer than the other two. It keeps the loud playing the shortest of the three, and sets the ending down the softest too.'),
('performance_listening_notes', 161, 'headline_en', '385de191b3008e4c05d5b66a2c34b6b068d79560cc10f1e274e702002ace89b7', 'Middle climax, soon soft'),
('performance_listening_notes', 161, 'note_en', 'cde43f84a89ebb6ad0fa7b0df5d80d8f6ce18bcfcf9173e8252410bcda69c456', 'Alone in playing loudest in the middle. It sinks to the quietest point right after, setting the loudest and softest sounds close together.'),
('performance_listening_notes', 162, 'headline_en', '8bc3334a252d6bf40ae724f92fe91f212b4991945aa7a60250b2a7d0cd61859b', 'Final chord is the climax'),
('performance_listening_notes', 162, 'note_en', '8e9a9ff628e4a41b3d3865bd188afe21379b320b8c5b2eb7035a6a749e3d86fc', 'Alone in placing the climax at the very end. Its first sound is also louder than in the other two, and it builds the final return big and sustains it to the end.'),
('performance_listening_notes', 163, 'headline_en', '5a719606025506f52654900d486209fcb8f15147fd7e2fa34cc5d54cf3ea88f9', 'Holds back until the last minute'),
('performance_listening_notes', 163, 'note_en', '618079ae0f0e5fea75b32d75d392589670b1efcfe3e86b416c572f47eea000db', 'At 4 min 10 sec, it is about 20 seconds longer than the other two. Only with a minute left does it reach nearly maximum for the first time.'),
('performance_listening_notes', 164, 'headline_en', '3cf9ea51ac6d8866d283c151f1e7e1517018c3c7429688b89b22282aafb403f3', 'An overture over 8 minutes'),
('performance_listening_notes', 164, 'note_en', '14992c11eac727b7b8411c3f5721411aefaccefe68002e973178830280dabba2', 'At 8 min 8 sec, it is 47 seconds longer than Kleiber. It reaches nearly maximum only after almost 6 minutes.'),
('performance_listening_notes', 164, 'facts_en', '14992c11eac727b7b8411c3f5721411aefaccefe68002e973178830280dabba2', '["Berlin Phil"]'),
('performance_listening_notes', 165, 'headline_en', '4648b2c25f8e2396a0ecb2cd83d5cc31da83f42c729bc042af023093f8b805ef', 'Maximum only at the very end'),
('performance_listening_notes', 165, 'note_en', '50eaf37f1f8fdf2e853c77ce353e1c5801268fab015059c43a44dcd2f182cbee', 'At 3 min 11 sec, it is the longest of the three. It lowers the middle the most, and reaches nearly maximum only in the last few seconds.'),
('performance_listening_notes', 165, 'facts_en', '50eaf37f1f8fdf2e853c77ce353e1c5801268fab015059c43a44dcd2f182cbee', '["Vienna Phil"]'),
('performance_listening_notes', 166, 'headline_en', '410a80ceb6d6179e96ede7096bb1bea395267942cb12548500e8f050124ff92e', 'Near maximum from the first tutti'),
('performance_listening_notes', 166, 'note_en', 'c1c2f7d4d9534a49e0068be0c4b07c7a7994bcaea305c92fb4838d30179d4f4d', 'Unlike the other two, it opens at nearly maximum from the first tutti. The gap between soft and loud is also the smallest of the three.'),
('performance_listening_notes', 166, 'facts_en', 'c1c2f7d4d9534a49e0068be0c4b07c7a7994bcaea305c92fb4838d30179d4f4d', '["Vienna Phil"]'),
('performance_listening_notes', 167, 'headline_en', '6e59d8c1903ff37b03ec022f10151d856adfb82b56631e95e7bcf982f669c417', 'Soft until the climax'),
('performance_listening_notes', 167, 'note_en', '4340e2b9296b7cc7a63b2f6422ea28d0d18f47a1a7d17c12807f4aa8124b9b85', 'Keeps the first two thirds softer than Karajan and Ozawa. After dropping to its quietest, it climbs to the climax in 40 seconds.'),
('performance_listening_notes', 167, 'facts_en', '4340e2b9296b7cc7a63b2f6422ea28d0d18f47a1a7d17c12807f4aa8124b9b85', '["Vienna Phil"]'),
('performance_listening_notes', 168, 'headline_en', '7b44ead12bb5f3a23fa09ecc48724f694382ff477708960a78cc3efaeae16cf3', 'Near maximum only at the climax'),
('performance_listening_notes', 168, 'note_en', 'e61ba38870f43d3cd2f16b99c51769c3ae7dde77e94677c9827d26cd95206212', 'The gap between soft and loud is the smallest of the three. It reaches nearly maximum for the first time only at the climax.'),
('performance_listening_notes', 169, 'headline_en', '13a30d0a49cf34b95a6b6ea6a1d213903dda5f0caac767dc031c6049991a4934', 'Near maximum early'),
('performance_listening_notes', 169, 'note_en', '08e5642e8fc64807fcc513f299592295bb81fa9044c52db0f9080a0f06823adf', 'Reaches nearly maximum more than a minute earlier than the other two. Then it immediately cuts back to a very low level.'),
('performance_listening_notes', 170, 'headline_en', 'ba3125e91085dc201c328a9001edd35a6fc6aeded2d24c37c83dbb2dc270fa35', 'Weight on the later part'),
('performance_listening_notes', 170, 'note_en', 'c1d871be40444c44f6889d12e47f828e623d05c89dbe810401da25c81d1aab37', 'Drops the middle a level, then lifts the final 50 seconds again. Alone in placing the later part louder than the earlier part.'),
('performance_listening_notes', 170, 'facts_en', 'c1d871be40444c44f6889d12e47f828e623d05c89dbe810401da25c81d1aab37', '["Vienna Phil"]'),
('performance_listening_notes', 171, 'headline_en', '498454746dc5b77a055269dfffa4a344ad5578b5c6331a99214f102d28b12cb2', 'A less soft ending'),
('performance_listening_notes', 171, 'note_en', '1998362b848686afea70a778b3a6d71397e35ef6bd91eca6d2c4b157e9d11c1c', 'Drops to its quietest 20 seconds after the climax. But the ending stays less soft than in the other two.'),
('performance_listening_notes', 172, 'headline_en', '6a886698e90c862f9392d9a9a1ad6214f0298a66d7d68a1ac7aaac7c3a30038f', 'Loud from start to finish'),
('performance_listening_notes', 172, 'note_en', 'a0360763b4cbf3834bb82d805963ace80ee26186017501513223d2ff03308fa4', 'Enters loudly from the start and reaches nearly maximum in 18 seconds. It sustains loud playing longer than Karajan and Muti.'),
('performance_listening_notes', 172, 'facts_en', 'a0360763b4cbf3834bb82d805963ace80ee26186017501513223d2ff03308fa4', '["Berlin Phil"]'),
('performance_listening_notes', 173, 'headline_en', '82323c101a3a81fadd2b450e847cb90fdc3c78b7f573d79718a73ce9d7367bbf', 'Just one climax'),
('performance_listening_notes', 173, 'note_en', 'da90bad7e3cb579321e66f778fc33e512f11ee7e8b4b1e9c3472e3b67b2b89cb', 'Plays its loud passages shorter than the other two. Soon after the climax it sinks deep, and the later part continues a level lower.'),
('performance_listening_notes', 174, 'headline_en', '45c8947d76334948777a720773e9bbd55496246e33b8827e37caa5d97e6f5e7b', 'Loud in only one spot'),
('performance_listening_notes', 174, 'note_en', '8b481ed51b1f1891928b4762d2ea53cec6d26f3e7be875c2001ba2d3cddd6421', 'Plays loudly in just one spot in the middle and sings far below that elsewhere. The final third sinks the softest of the three.'),
('performance_listening_notes', 175, 'headline_en', '93a2a94a6627e3fa830bcf5edb0974823685ed35f18ce578cc97190b48f941f9', 'Over a minute shorter'),
('performance_listening_notes', 175, 'note_en', 'd4773817cf35327fefa79323a512eff5a29f3a6acc8d0213f06cce3be24d28e8', 'At 4 min 54 sec, it is more than a minute shorter than the other two. The gap in volume is also small, so it flows evenly from the start.'),
('performance_listening_notes', 176, 'headline_en', '93bdced563d2c7665ca4a0dc0f9e8710c724309cb03408809a5aa2b54141f3ed', 'Soft opening, wide range'),
('performance_listening_notes', 176, 'note_en', 'f0a0a4211c471ec6a126d9b10088a2764bd101fa6b2e5ac6461a74e72246a218', 'Starts the softest of the three. The gap between soft and loud is also the largest, and near the end it rises loudly once more.'),
('performance_listening_notes', 177, 'headline_en', '774513d46b4b603e7904053159887c33985eb4fd15293b44f9dc878eb7e2b8c7', 'Holds on after the climax'),
('performance_listening_notes', 177, 'note_en', '706de19cd04e3290a52b0e63aa2c2b556f18e8e152e00aa439a1d08b41f987f9', 'Unlike Ashkenazy, it doesn''t let the volume down even after the climax. Only on the last note does it drop to its quietest.'),
('performance_listening_notes', 178, 'headline_en', 'd42c59c5590ac9314b38485b392ab33d7915651d7faceeffa60c8dc84cd5ab4e', 'Little rise and fall'),
('performance_listening_notes', 178, 'note_en', '6975b3f43a40ccd0bef8768e49d3af6ee0fd6fd407ca31b0ebff17284adba829', 'The ups and downs are slightly smaller than in the other two. The ending is set down as softly as Ashkenazy''s.'),
('performance_listening_notes', 182, 'headline_en', 'f8eacedbfb73c1a1d660e1a7e1b5e0cc716367d87627661e32558d968d52ca0a', 'The shortest of the three'),
('performance_listening_notes', 182, 'note_en', '3b01893dcef03dd8824325f3371afb1f9222101122804fa68225348673c62979', 'At 4 min 32 sec, it is about 40 seconds shorter than the other two. It keeps the big middle passage loud for over a minute, and the ending doesn''t get as soft as in the other two.'),
('performance_listening_notes', 183, 'headline_en', '397513efafefe368223363d2fe498b76cb32084efdc86eb0643ed5b56616c39c', 'Two climaxes'),
('performance_listening_notes', 183, 'note_en', 'abd9b8f8e2317b256c670a39406bf7fc2b96cfc24e78881bf6dce900452e10e3', 'Rises loudly in two places and cuts back sharply between them. It ends the last 2 minutes very softly.'),
('performance_listening_notes', 184, 'headline_en', '5c8a4a955616d5f53cc9ffbcdc02041a742253310e32b5ad9fad7e8bf3cc181f', 'Bells at maximum, twice'),
('performance_listening_notes', 184, 'note_en', 'e5b9f9323846f1bac41407a72340dffd1f688bbdb73ebdaf8c5f817d43947af8', 'Rings the returning bells at maximum twice. It sustains loud playing the longest of the three.'),
('performance_listening_notes', 185, 'headline_en', 'c9f175407b699ac1fcd410cd91d53f63d8d46744cca13b52038e4d316c9726a6', 'Softest first note'),
('performance_listening_notes', 185, 'note_en', '56945c7cff24490b792187632dbf866b00d5a9f468e3e47162dea524a386a4bb', 'Its first sound is the softest of the three. The gap between soft and loud is also the largest, and the flow is almost the same as Seong-Jin Cho''s.'),
('performance_listening_notes', 186, 'headline_en', '2a6eed5e4b0650cb433c72e131ef02a421ef699e4285cc46b401a927898820c6', 'Shortest, builds early'),
('performance_listening_notes', 186, 'note_en', 'ebbfd12840a8130e5988b695edc95368360217d2bec7842fa96584157da439b4', 'At 3 min 48 sec, it is about 30 seconds shorter than the other two. It starts getting louder the earliest, and closes the ending the least softly.'),
('performance_listening_notes', 187, 'headline_en', '9b33638c79b9226c4da0e907f72972f704e9e9fa08ab8640ac9a2e951d234751', 'Just one big climax'),
('performance_listening_notes', 187, 'note_en', '3c83ea894e00bb77c2e0ffa78b10e88b9b40043b17e31309a83b452cab467e6c', 'Holds back from the first bell more than the other two. Its loud playing comes only at the climax, and the gap between soft and loud is the largest.'),
('performance_listening_notes', 188, 'headline_en', '98ee0549fcbf8c24a43f99c926d8c285b206e095e0ae017bd228a5517dcea113', 'Climax at the one-third mark'),
('performance_listening_notes', 188, 'note_en', '54413ed55e7ac531de4b3312ecc6201daca87cfd0edf81cede3dfc8a5feccb1c', 'Sings loudest at the one-third mark, the earliest of the three. It sinks the later part the deepest, so the volume gap is also the largest.'),
('performance_listening_notes', 189, 'headline_en', '11f9c83ec3ebe06705c02b32cab26743cbf07ff051c360234cdc9d7869cd1370', 'Sinks 40 seconds after the climax'),
('performance_listening_notes', 189, 'note_en', '934468b5b8eeec3390d509fa84fb9476fef77a242d12a58a743e16d965129528', 'Forty seconds after the climax, it sinks to the lowest of the three. The last 10 seconds are also far softer than in the other two.'),
('performance_listening_notes', 190, 'headline_en', '1214a7712c04a9172bbc4b14b403b7d316c5e18c9df5b67066a94e11074a3be9', 'A long sink, then one peak'),
('performance_listening_notes', 190, 'note_en', 'b1eeebdf96a6c32c40dec24812141db3ff5db9687be8c1ac5c541aba5a95be80', 'Opens clearly for the first 20 seconds or so, then sinks for a long while. It sings loudly only once in the middle and sets down again.'),
('performance_listening_notes', 191, 'headline_en', 'b9ef35e9e2cff94a905174b54cfa3e5ac03f089b10674ff7eb4f03cdabd61a2d', 'Deepest dip in the middle'),
('performance_listening_notes', 191, 'note_en', '581d973c9f4a19b867d5adada3357c684c2b308dc82db4049a743c554f53d78e', 'Sinks the middle passage, which all three lower, the deepest. The loudest sound comes 1 min 15 sec before the end.'),
('performance_listening_notes', 192, 'headline_en', '26d1f9abbf995f2c28f466fd7edab22e69ea0fc8d03b51649b375bd6b4f8960c', 'Loud for long from 35 seconds'),
('performance_listening_notes', 192, 'note_en', 'c9fa521132cf4077f005ded054b8d6d815f66586ecba18d25c218387d391d2c5', 'At 2 min 56 sec, it is 16 seconds longer than Lang Lang. It reaches nearly maximum in 35 seconds and sustains loud playing longer than the other two.'),
('performance_listening_notes', 193, 'headline_en', '9f1686346e299d9bce8e9a5b84684f664576c10dc0632bfb0596a639cb08e0df', 'Climax on the last chord'),
('performance_listening_notes', 193, 'note_en', '643387d2aaffdae3c1a1d510f622fc8bcbd89c04654f311dc28ed51700d9ef3b', 'Unlike the other two, it puts the loudest sound on the final chord. It drops to its quietest 15 seconds before the end, then rises in one move.'),
('performance_listening_notes', 194, 'headline_en', '78c2ea6356fb9629d699616c1706593f368cfa279a372d210ccaaa16bb632689', 'Soft from the first note'),
('performance_listening_notes', 194, 'note_en', '10256fa43024310e3397b4226054dc4801196ed832ecdd4c2a21a84f384dbf2d', 'Plays the first note softly, and reaches nearly maximum about a minute later than Levit. The climax also sits closer to the end than in the other two.'),
('performance_listening_notes', 195, 'headline_en', 'b1a440b86ada9f856fd8afaf2d26afcfcc59a6c0aee289f1071c584724e27dcf', 'A fast rondo, 3 min 59 sec'),
('performance_listening_notes', 195, 'note_en', '3fb681bc8d9dc1bbf854f2797eb9501222d055785d86501c43b448555eba6743', 'At 3 min 59 sec, it is the shortest of the three. It reaches nearly maximum in 15 seconds and sustains loud playing longer than the other two.'),
('performance_listening_notes', 196, 'headline_en', '9e73359a0445310ee5dd1f64f9273dfa5b2c2e2ea1605d26fb18657c320206de', 'Pulls back before the climax'),
('performance_listening_notes', 196, 'note_en', '631a3bd9308cd8406e185b3f889e55537ade84bd9b67ae83e5c1aca3241eee89', 'At 4 min 57 sec, it takes about a minute longer than Levit. Before the climax it sinks deeply once, then climbs again.'),
('performance_listening_notes', 197, 'headline_en', 'c8252d6f69ae523f44f2d7f32e06053d73a1d43f080d8cf47f09f24681367d27', 'Loudest at the two-thirds mark'),
('performance_listening_notes', 197, 'note_en', 'd9c3c0b4f54473cc88ff262b3b7440e8904aaf4209366ef0c742c5ab6299737a', 'Plays loudest at the two-thirds mark of the piece, the earliest of the three. It also sustains loud playing the longest, and doesn''t come down much even in the last 3 minutes.'),
('performance_listening_notes', 198, 'headline_en', 'aab0613bd89e0a5b7864528eb053e9de6aba4062ca84d8ca192fbf915d8510ef', 'Climax on the final chord'),
('performance_listening_notes', 198, 'note_en', '07efdcb7a67edf6c4116dc972acdc7ebe824aca73f3031b80bc31529b4505895', 'Saves the loudest sound for the very last chord. About 2 minutes before the end it pulls back sharply, then builds up again.'),
('performance_listening_notes', 199, 'headline_en', 'a837b61891c89fb121633e3af37e1a61c15bd117dc9ca571ca3ff7b85c2b0d8f', 'A very soft introduction'),
('performance_listening_notes', 199, 'note_en', 'ecbfe23f1ac8c0a1183866d1adeddbb96c515dd7170fdfdcf21c9f048b71c6ff', 'Opens the introduction softer than the other two, and spreads the volume gap wider. The loudest sound comes in the coda.'),
('performance_listening_notes', 200, 'headline_en', '94b45d4fe6ce02861a49681921e461ba134600f457f410761b8014e658d85777', 'Held back until the final cry'),
('performance_listening_notes', 200, 'note_en', '0b229665285af210ff869078f91608a537e42748a62556dac8840f3125ce37bc', 'Opens the beginning the softest of the three. It holds back until just before the final cry and reaches maximum there for the first time.'),
('performance_listening_notes', 201, 'headline_en', '4fbea78c66c4828b322e82fd33b95eaa8946a16a593c738f1d6a9fd516148bec', 'Longest, building to the end'),
('performance_listening_notes', 201, 'note_en', '24e23b6ef3ac34182f142755ecb91ac41033ea9df38b70302510267cbcc9a4d6', 'At 3 min 25 sec, it is longer than the other two. It places the first high point a level lower and builds steadily toward the final cry.'),
('performance_listening_notes', 202, 'headline_en', '6c4a4ad8f7a26e3fdd2582cfd99cd3504aa2cd4e67e447d86ae2bcd7c2a35d30', 'Maximum from the first peak'),
('performance_listening_notes', 202, 'note_en', '80f019c49f853d6717c21d508945b5703edcaddeb5a5b2ade911b9043f634f39', 'Already reaches nearly maximum at the first high point. The other two get that loud only at the final cry.'),
('performance_listening_notes', 206, 'headline_en', '29c0431a3365fa089e3fcc38ce3ada4b3521ecaadbed9c2b2752de1cc3bb7a68', 'Climax 30 seconds from the end'),
('performance_listening_notes', 206, 'note_en', '0ea65fe5f0b39d4e4d644da6fb7f18ec93c79f086977d2a7aa7994ba73535470', 'Pulls back a minute before the end, then builds again. The loudest sound comes well later than in the other two, 30 seconds before the end.'),
('performance_listening_notes', 207, 'headline_en', 'be764c9bc4f64508ada1b655454a5752cad5fb844321593e551f3574658e87b7', 'Soft opening, loud in the middle'),
('performance_listening_notes', 207, 'note_en', '1af79e5184348a3b95a71aa413d0715bc0d5b5a1cfea22fa669456bb3fd34d48', 'Plays the first note the softest of the three. The loudest sound comes a minute later than Pires, past the very middle.'),
('performance_listening_notes', 208, 'headline_en', 'a93db0c4b5af47901c19d18caa605f819141bae9f12883916b141a8d2a5ec2be', '4 min 6 sec, steady'),
('performance_listening_notes', 208, 'note_en', '70c6b42af1d5da1bc41831b45898b48cfa300ee8e13b2b6a1039e40c4e3fdbd1', 'At 4 min 6 sec, it is shorter than the other two. It barely changes volume from start to finish and keeps even.'),
('performance_listening_notes', 209, 'headline_en', '74d45802fdf7a0320111595e7bea69f45eb9d95100e3d196c8b2aac8638297c5', 'First call as loud as the last'),
('performance_listening_notes', 209, 'note_en', '20d861d444aed06316ac97436a6570c0dfb87e18ff55bb6e07e7ca566c70dc17', 'Plays all four big passages at the same volume. Unlike the other two, it doesn''t make the final chord louder.'),
('performance_listening_notes', 209, 'facts_en', '20d861d444aed06316ac97436a6570c0dfb87e18ff55bb6e07e7ca566c70dc17', '["Capella Istropolitana"]'),
('performance_listening_notes', 210, 'headline_en', '4807dda9e57f97ae216752b5ac02a13a46e51ae7e1287d2ee7b70a57808a5cbb', 'Final chord the loudest'),
('performance_listening_notes', 210, 'note_en', 'c4793089980f77661dee066a7527bb0aa68839d7e11db4e192458994ffcd1dc6', 'Lowers the earlier big passages a level and plays loudest on the final chord. It also sustains loud playing the longest of the three.'),
('performance_listening_notes', 210, 'facts_en', 'c4793089980f77661dee066a7527bb0aa68839d7e11db4e192458994ffcd1dc6', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 211, 'headline_en', '7e8ae025a6136257addb01046fdba704820227d46d9977d22f1be4ff8c264b71', 'Cuts loud playing short'),
('performance_listening_notes', 211, 'note_en', '4a5cab308e6f9142ff28166d2c42fe0302c972db0d2d4c2ff5f8a1f58c79e550', 'The flow is almost the same as Marriner''s, putting weight on the final chord. But it cuts the loud playing shorter than the other two.'),
('performance_listening_notes', 211, 'facts_en', '4a5cab308e6f9142ff28166d2c42fe0302c972db0d2d4c2ff5f8a1f58c79e550', '["Berlin Phil"]'),
('performance_listening_notes', 212, 'headline_en', '41e24d5aead13a0afe6db9852c8921d800ae8c4a8f4f930e5846eab124c32e5b', 'Loud opening, maximum at 26 sec'),
('performance_listening_notes', 212, 'note_en', '8d51981bb7e129efc188b0c7a004c20bbf15f96f9a6c4ec46a3059ded2441639', 'Starts louder than the other two and reaches nearly maximum in 26 seconds. Before the end it drops very low, then closes big again at the finish.'),
('performance_listening_notes', 213, 'headline_en', 'bec1f0ca8012b685e7bc2dba2997f72bd8be8c9803d9a004668fb89e00599511', 'Loud playing held long'),
('performance_listening_notes', 213, 'note_en', 'a412e10c2417814834745b72ac91dd74d8d088758597ab000b3d76e4025d8296', 'At 7 min 9 sec, it is about 40 seconds shorter than Trifonov. It doesn''t lower the soft passages as deeply as the other two, and sustains loud playing the longest of the three.'),
('performance_listening_notes', 214, 'headline_en', '4c683066463db1c750a6092b04ee368b27bbde1d87a894382037f96eaf783d9d', 'Deepest soft passage'),
('performance_listening_notes', 214, 'note_en', 'f55efbe060f99b8fbd6d62a504eac064a03125f195021bee0fffbd8c6745f120', 'Reaches the loudest sound only past the middle. The soft passage before the end sinks deeply earlier than in the other two.'),
('performance_listening_notes', 215, 'headline_en', 'f8ea012d0492581453585f19fb733fbb5c033c785ff1e62b94f4c14534290941', 'Biggest rise and fall'),
('performance_listening_notes', 215, 'note_en', '9309a7158759d03a4d509491b639788dbefe682ebaea879c15204a8cac266c6f', 'The gap between soft and loud is the largest of the three. About a minute before the end it cuts back deeply, then rises near maximum again at the finish.'),
('performance_listening_notes', 216, 'headline_en', '8068cace518b7a93de131fea05c23649b3cc083a8dd7e1c2cab7bc4371a2f330', 'Late climax, lower last minute'),
('performance_listening_notes', 216, 'note_en', '25683745f92df000dae7bc5c2261743ab66c64a4b94017848c892facd12762be', 'The climax comes later than Lisitsa''s and Shishkin''s. After that it drops the last minute a level, and the time spent on loud playing is also short.'),
('performance_listening_notes', 217, 'headline_en', '3f8d0d9d08d9054ceb37b7786779489835ac67136f6ff4765d78601b53840f48', 'About 80 seconds shorter'),
('performance_listening_notes', 217, 'note_en', '406eb2a34e1215f804f9905244d5b606dd5a6f0669385a9693ce189252049c07', 'At 8 min 4 sec, it is about 80 seconds shorter than the other two. It keeps the volume gap small, and reaches maximum earlier than both.'),
('performance_listening_notes', 224, 'headline_en', '4c6e9dbbe91bd1c694a9c2269b6f821f5880c65f5316ac1aaf9015b7e26fb6e5', 'All at once in the last 20 sec'),
('performance_listening_notes', 224, 'note_en', '2ac042d699d438ff302b209bb54c1485c0f06492d17bab65ae81640b4c11d659', 'Starts the softest of the three. After sinking once more in the middle, it builds up all at once in the last 20 seconds.'),
('performance_listening_notes', 224, 'facts_en', '2ac042d699d438ff302b209bb54c1485c0f06492d17bab65ae81640b4c11d659', '["Original version"]'),
('performance_listening_notes', 225, 'headline_en', '6d15fed9ab4a0d88332be2747c91837e2608e7442e641624ac775ae333c7e2f5', 'At maximum through the second half'),
('performance_listening_notes', 225, 'note_en', '1e4caf48f12c4ae76af33e9c7a62d90fe5eb5e3bc51f4fb39dc62a98f8e5406c', 'After catching its breath briefly twice early on, it drives the second half at nearly maximum volume.'),
('performance_listening_notes', 225, 'facts_en', '1e4caf48f12c4ae76af33e9c7a62d90fe5eb5e3bc51f4fb39dc62a98f8e5406c', '["Original version"]'),
('performance_listening_notes', 226, 'headline_en', 'e8602dc736f20f33814c349275dca736f27fedcc04f6cf779783ce6beead8477', 'The only ossia'),
('performance_listening_notes', 226, 'note_en', '7b47b85e9cbf92cab8f6933f692727b36a8a48cd47084766bfddddf8f0157276', 'As the ossia built on heavy chords, it is about 50 seconds longer than the other two. It enters loudly from the start and reaches maximum in 30 seconds.'),
('performance_listening_notes', 226, 'facts_en', '7b47b85e9cbf92cab8f6933f692727b36a8a48cd47084766bfddddf8f0157276', '["Ossia"]'),
('performance_listening_notes', 245, 'headline_en', '6122f0a49fddc51186eb7537ebe0a7bec8a080ede6fe9ee9a13afc4411498f98', 'Longest, built in three stages'),
('performance_listening_notes', 245, 'note_en', '105eadfc476702f2e48b66477cb2b6fe79d8a547f1bf81530c88c2e3e00c927a', 'At 3 min 16 sec, it is the longest of the five. It keeps the first part of the theme soft for a long time, then builds in three stages.'),
('performance_listening_notes', 246, 'headline_en', '39a16fa24837e29ff2d89b4f3fbe689bb1864d3374f9cf06a62b204a439f1862', 'Pulls back, then one leap'),
('performance_listening_notes', 246, 'note_en', '3a1f98b31c059e98bbac018513ddd3a91fab747214821de48aa824a65755c0f4', 'Just before the climax it pulls back sharply once, then rises in one move. The climb is the steepest of the five.'),
('performance_listening_notes', 247, 'headline_en', '6e3297430f0e9d278c2cf83e5bc4432a0a0b18316700bcb51d6acd0d0754df7c', 'Shortest, loud from the introduction'),
('performance_listening_notes', 247, 'note_en', 'aef1f08f39ce14cc8d80c7cd73e621510aa81d7243bccbb86518ea309ad16795', 'At 2 min 46 sec, it is the shortest of the five. It slashes in loudly from the first octave of the introduction and hits hard twice more in the theme.'),
('performance_listening_notes', 248, 'headline_en', 'b8f4ef8a5792a8b64871de6c2301c0e3a60e660a6355f241dd09522d505f1f3c', 'Holds its breath the longest'),
('performance_listening_notes', 248, 'note_en', '431207c3b1aa01f83c5ab27a55b44ec4332455ca8c83a3e290b46edffe093847', 'The soft passage after the introduction lasts over a minute, the longest of the five. The climax also comes the latest.'),
('performance_listening_notes', 249, 'headline_en', '4d9cc33ea8c588a91b97f7c7380f0df6d6f05812362f641996d43a4188c67e8c', 'Even, big at the end'),
('performance_listening_notes', 249, 'note_en', '43c19a3e043ccf26c086cc9a4565fb4edc40d70c8f0c1b92b2712f17adf09a8c', 'Sings the first half at a similar, even volume. Its first note is the loudest of the four performances.'),
('performance_listening_notes', 250, 'headline_en', 'eddd7a60d0ba2117dcb716bc0f7f70ff9b624908ec96facf268212358f221c11', 'Quietest first note'),
('performance_listening_notes', 250, 'note_en', 'f47faf94be7328f4b723bd2162cec9e277aca9be88eea1ba54ca18f82c30caf4', 'Enters the softest of the four. It is also the only one of the four to put the climax right in the middle.'),
('performance_listening_notes', 251, 'headline_en', '877f520305c1b22c94a16687a198fff2d3834cc1cd5518f0ef5ee99694809fc3', 'The shortest'),
('performance_listening_notes', 251, 'note_en', 'be8faddcf9103ae8697f24afe2db503b75251ef238367a810de31175d6faaa53', 'At 1 min 13 sec, it is the shortest of the four. It cuts back deeply twice along the way, then climbs to its loudest at the end.'),
('performance_listening_notes', 252, 'headline_en', '9d0334ffc966a26e92dadeb4f06651488997fcd694b5847eb685d47d74ddf7f4', 'A whisper for the first 4 sec'),
('performance_listening_notes', 252, 'note_en', '31b2885e3394de8d0601310db41e9e5399de25e32fae97156f8406b8a6f6ec59', 'Keeps the first 4 seconds very quiet, then builds big within 20 seconds. The climax comes near the end of the piece.'),
('performance_listening_notes', 253, 'headline_en', 'd18239b40c8e3c980ca99a3186026d1b43119680b4557ed638e8b6920a2725f7', 'Maximum later than the other four'),
('performance_listening_notes', 253, 'note_en', 'ae4437ea03cf225bc3515a96472cd0257983b52820151cc057b5d6d47828deab', 'Reaches nearly maximum later than the other four. It sinks twice before the end, then surges again at the finish.'),
('performance_listening_notes', 254, 'headline_en', 'e984053a782d355ae51645e4b89bf1671ff6730a2eb0718c6ce31bbeb7479bd6', 'Loud playing held long'),
('performance_listening_notes', 254, 'note_en', 'ac1a5f3e0027eeda41ec111ef71b3efcc1af34bdeebde27d81b3edabd00aa369', 'Sustains loud playing longer than the other four. Before the end it sinks the deepest, then bursts out again.'),
('performance_listening_notes', 255, 'headline_en', '464f34062269b44029efa8097af93e226c36c094d34bc21262acae2c3024a195', 'Loud last 10 seconds'),
('performance_listening_notes', 255, 'note_en', '3401f791d9c65d50fd70350d1659493801ec681622ac521397628f6f762ce069', 'Passes quickly through the soft passage before the end. It plays the last 10 seconds the loudest of the five.'),
('performance_listening_notes', 256, 'headline_en', '2dc837a90cc9d410ff837e4678a19e2eeac85fcc3b3ec5298db24852270efce7', 'Two long sinks'),
('performance_listening_notes', 256, 'note_en', 'aed3d2059549719ef16c04973ec9dc2d1da04e574011832c05e356d4faaca636', 'Enters more softly than the other four. It sinks for a long time twice before the end, and sets down the last bars the softest too.'),
('performance_listening_notes', 258, 'headline_en', '42a6d224324ef0158c66ca33177910b556e7f14be3ffd10efb1ac5f2efe29578', 'Early lift of a level'),
('performance_listening_notes', 258, 'note_en', 'c6b2986a40cb8aaad3703f1585680182211cf8b43f1e7d2ab2fe295a74224124', 'Leaves the soft passage early and holds a level higher in volume for almost a minute until the climax.'),
('performance_listening_notes', 259, 'headline_en', '1caa6f45f7a83990e246ba07828f3d2fc6a1fd0337bb5f343bceb5cea3ed3776', 'Straight to maximum'),
('performance_listening_notes', 259, 'note_en', 'c37bfb3957fb660bbd53abe2a054e191f8dfc9810e09df38eed9e1421fcd98e4', 'Enters at nearly maximum from the first note. Even in soft passages it doesn''t drop as low as Zimerman or Seong-Jin Cho.'),
('performance_listening_notes', 260, 'headline_en', 'ad8242f89d5fa7afce173c25e93ce36afc745346798d47ac477367ebadf41857', 'Rises early, stays even'),
('performance_listening_notes', 260, 'note_en', 'b37c827980365ee8253c79fd77d9adfc2ad9fd3a963a15673258f1cf1ab4e29e', 'Reaches nearly maximum a minute earlier than Marsalis and carries the first and second halves evenly. The loudest sound comes on the last chord.'),
('performance_listening_notes', 260, 'facts_en', 'b37c827980365ee8253c79fd77d9adfc2ad9fd3a963a15673258f1cf1ab4e29e', '["Abbado · Chicago Symphony"]'),
('performance_listening_notes', 261, 'headline_en', '77bd66661253a82279f2a24a998932abc9d290e6dc739ec5a0edb29a89466a3d', 'Loudest at the very middle'),
('performance_listening_notes', 261, 'note_en', 'ed5620fe004dd5fa8ea2fe3956de4b3e1b9dc408d6ab84bf0fccc4c4f88b4899', 'Alone in playing loudest at the very middle of the movement. Before the end it sinks to its quietest, then rises again.'),
('performance_listening_notes', 261, 'facts_en', 'ed5620fe004dd5fa8ea2fe3956de4b3e1b9dc408d6ab84bf0fccc4c4f88b4899', '["Stadlmair · Munich Chamber"]'),
('performance_listening_notes', 262, 'headline_en', '2c5f53a5b189cf243754c8ee3d81ca3523061b9737f7eb933e066b3074851622', 'Sinking deeper and deeper'),
('performance_listening_notes', 262, 'note_en', '48d12781d1eaaf65229d4a7a33caf2c21cdd7df174ec95029c7e98ebd0d79e59', 'Reaches nearly maximum the latest of the three. It sinks the soft passages deeper each time, then cries out loudest on the final chord.'),
('performance_listening_notes', 262, 'facts_en', '48d12781d1eaaf65229d4a7a33caf2c21cdd7df174ec95029c7e98ebd0d79e59', '["Leppard · National Phil"]'),
('performance_listening_notes', 263, 'headline_en', '488feb4eb6553e13ab1be8901926b4404373226571e39e5350a56dcc33e39d5b', 'Low for the middle minute'),
('performance_listening_notes', 263, 'note_en', 'dc78dcc7d52b8307640e3f6f5e0e1cdc2bd5715db485565e888d0632078d2e66', 'At 3 min 58 sec, it is longer than the other two. It keeps the middle minute a level lower, then rises again to play loudest.'),
('performance_listening_notes', 263, 'facts_en', 'dc78dcc7d52b8307640e3f6f5e0e1cdc2bd5715db485565e888d0632078d2e66', '["Böhm · Vienna Phil"]'),
('performance_listening_notes', 264, 'headline_en', 'f53d16edc67c743afc8237710ca6c1b11295753579c04ffb227e5f279c2f1e77', 'Nearly maximum the latest'),
('performance_listening_notes', 264, 'note_en', '2a0df9315fc298d6785afabdd1f96e36c52d359673c7073734e6477b4bdb29fb', 'Reaches nearly maximum the latest of the three, and that very spot is the climax. Before the end it drops to its quietest, then raises the volume again.'),
('performance_listening_notes', 264, 'facts_en', '2a0df9315fc298d6785afabdd1f96e36c52d359673c7073734e6477b4bdb29fb', '["Munich Chamber"]'),
('performance_listening_notes', 265, 'headline_en', '556474bbe653d448c708e2adb238ebe8f7192a22220a2fa7ce185fe86a7df54a', 'Short, climax on the last chord'),
('performance_listening_notes', 265, 'note_en', '1eb1682c3e92813dfcd8d93481d229d75cf7b2acf81956c73f0f1a614c0d819b', 'At 3 min 29 sec, it is about 30 seconds shorter than Högner. It holds loud playing for a long time, then plays the final chord the loudest.'),
('performance_listening_notes', 265, 'facts_en', '1eb1682c3e92813dfcd8d93481d229d75cf7b2acf81956c73f0f1a614c0d819b', '["Marriner · Academy of St Martin"]'),
('performance_listening_notes', 266, 'headline_en', '39640457ab156357bbb872e0ad350dd2e951b518f31f4914aba918b3bc2108c7', 'Deep drop after the climax'),
('performance_listening_notes', 266, 'note_en', '1861d3d694a9e1cf9aa276e40a8bab1a74604798f1f5bc152d88a3c2bd1be365', 'Sinks the soft passage the deepest of the three. Even after the climax it sinks for a long while, then closes big at the end.'),
('performance_listening_notes', 266, 'facts_en', '1861d3d694a9e1cf9aa276e40a8bab1a74604798f1f5bc152d88a3c2bd1be365', '["Berlin Phil"]'),
('performance_listening_notes', 267, 'headline_en', 'db1d832c9a6c28ffb722d1b1e395f671ded441aabb3da9e30c65b19e0dbf2175', 'Softest early on'),
('performance_listening_notes', 267, 'note_en', '145b71c5f1a36c69092e59c514f14dc1d81fa4dc73706fc41b6fa48eea428dc8', 'The flow is almost the same as Karajan''s. But the softest spot is early in the movement, not after the climax.'),
('performance_listening_notes', 267, 'facts_en', '145b71c5f1a36c69092e59c514f14dc1d81fa4dc73706fc41b6fa48eea428dc8', '["London Symphony"]'),
('performance_listening_notes', 268, 'headline_en', 'a06f02c4542782c52ab6c4a9655eea0885a040d2aaa1b58b96bc1c3d3ae63eb4', 'Less sinking, more even'),
('performance_listening_notes', 268, 'note_en', 'f9b89934f0576fbe8ad4ea797cf28f304e80b0db75eed01b6e80c721a1015e9d', 'The gap in volume is smaller than in the other two. The less it sinks, the longer it sustains loud playing.'),
('performance_listening_notes', 268, 'facts_en', 'f9b89934f0576fbe8ad4ea797cf28f304e80b0db75eed01b6e80c721a1015e9d', '["Academy of St Martin"]'),
('performance_listening_notes', 269, 'headline_en', 'c5844a0afce259edb7da270d6794d967ecf5baa0e424a31168a711bee930cbb6', 'Climax in the middle of the piece'),
('performance_listening_notes', 269, 'note_en', 'b853dce3c1c8b8b01ec0fec4eea561df9618f8a2dd04af052f1ccc6f438ce5e0', 'About 20 seconds longer than the other two, and alone in playing loudest in the middle of the piece. The ending isn''t as big as the other two''s.'),
('performance_listening_notes', 269, 'facts_en', 'b853dce3c1c8b8b01ec0fec4eea561df9618f8a2dd04af052f1ccc6f438ce5e0', '["New York Phil"]'),
('performance_listening_notes', 270, 'headline_en', '0726af5084854f8b625fede47251b6b9591f7db7a732ea1dc81cbd825b2d10d4', 'Up in a minute, then on to the end'),
('performance_listening_notes', 270, 'note_en', '2e0aaf7e9efe0c1360d2e8c3c64e7c5666925840df97f66b2458d45b6f52346a', 'Reaches nearly maximum the earliest of the three and sustains loud playing the longest. It carries that level to the end and puts the climax at the very end.'),
('performance_listening_notes', 270, 'facts_en', '2e0aaf7e9efe0c1360d2e8c3c64e7c5666925840df97f66b2458d45b6f52346a', '["NHK Symphony"]'),
('performance_listening_notes', 271, 'headline_en', '6fd7c721c9e3d01c82ae8531bbaf5ab363bad014f63755fdab38b06b93d9931a', 'Soft opening, builds up'),
('performance_listening_notes', 271, 'note_en', '9d519ee8eac7b290301a77d0b8c2ce74d018948424e9afcae3f61e06f37472df', 'Starts more softly than the other two and builds toward the end. Before the end it sinks to its quietest, then cries out loudly at the very end.'),
('performance_listening_notes', 271, 'facts_en', '9d519ee8eac7b290301a77d0b8c2ce74d018948424e9afcae3f61e06f37472df', '["Vienna Phil"]'),
('performance_listening_notes', 272, 'headline_en', '8863786d5f2380ba9d7b9ff46be854daf59171d472061a4aef0592c8b672d656', 'Maximum in the final rush'),
('performance_listening_notes', 272, 'note_en', 'e0e040f037b14a879249f243f09948187c4196e6772d53bef0769fcea2affeb6', 'Alone in placing the loudest sound in the final rush. During the 30 seconds of rushing, it hits nearly maximum again and again.'),
('performance_listening_notes', 272, 'facts_en', 'e0e040f037b14a879249f243f09948187c4196e6772d53bef0769fcea2affeb6', '["London Symphony"]'),
('performance_listening_notes', 273, 'headline_en', '1a16c1b8316fed50d4ba3abf41182dc7ebf44e4b1c4b9f38f014ce1c68fe851d', 'Maximum in the middle and at the end'),
('performance_listening_notes', 273, 'note_en', 'a5c1a2ec2757857934ee7a5a5b69cc9a4faecffbdbef434add000c5d8c5b0171', 'Raises both the middle and the final rush to nearly maximum. It sustains loud playing the longest of the three.'),
('performance_listening_notes', 273, 'facts_en', 'a5c1a2ec2757857934ee7a5a5b69cc9a4faecffbdbef434add000c5d8c5b0171', '["Gewandhaus"]'),
('performance_listening_notes', 274, 'headline_en', '55f4f0b18dcaacb23bbd3193ba64aaa8cd52aa1f937f4df96f203b6ef8f6bbcb', 'Final rush a level lower'),
('performance_listening_notes', 274, 'note_en', 'e88eb963bd061ddc1eeec40fe917abedf5610366cf7e38fc1b97f0861524cc77', 'Rises loudest in the middle, and the final rush goes a level lower. The close is also softer than Gardiner''s and Masur''s.'),
('performance_listening_notes', 274, 'facts_en', 'e88eb963bd061ddc1eeec40fe917abedf5610366cf7e38fc1b97f0861524cc77', '["Israel Phil"]'),
('performance_listening_notes', 275, 'headline_en', '21d794a1d2c06a4df6df5d3e921f7d113670e03de2a7744333aeaa4b84a480d8', 'Enters a level lower'),
('performance_listening_notes', 275, 'note_en', '91a796a9b3ec6654084fa928abc35f12fcb31a032f4b2a2f77ac1ae6c2e827f3', 'Enters lower than the other two and holds back for almost a minute before surging. It doesn''t sustain loud playing but cuts it short.'),
('performance_listening_notes', 276, 'headline_en', 'a03372b24a18046077bd3d466ed128f90f48112aa7306c3f9e10e5d9d8c4c928', 'Longest and even'),
('performance_listening_notes', 276, 'note_en', 'af3551d635b698a8d5a6f4d2950fadbbc9f793c5bbcb5cc0e1f89984e6f3e748', 'At 2 min 52 sec, it is the longest of the three. It reaches nearly maximum in 18 seconds and pushes on evenly with no big pull-backs.'),
('performance_listening_notes', 277, 'headline_en', 'aa813962a4572df57a9ca265db9f78548f49847d494e8b7a766cf1d9838a9d5a', 'Near maximum from the first strike'),
('performance_listening_notes', 277, 'note_en', 'b35f6c81e73b5211262a9b522ab2c61140f0b979821dcd8dd9f689154d3a4d88', 'Enters at nearly maximum from the first strike and, unlike the Emerson Quartet, sustains loud playing for a long time. It catches its breath once before the end, then drives on again.'),
('performance_listening_notes', 281, 'headline_en', '51c9f19ec92b9aebc7f11daa2bc59c1e15b62453c2b56f246f8f31986be80c7c', 'The deepest soft passages'),
('performance_listening_notes', 281, 'note_en', '70bb46a90f919da3145b59a4b3bb6237da57f04086d2ad2d9212c396fdd5cdfa', 'At 1 min 58 sec, it is about 12 seconds shorter than the other two. It sinks the soft passages the deepest of the three, and sets down the ending the softest too.'),
('performance_listening_notes', 282, 'headline_en', '000f0fac5580bbe1645a5823d2b4dbb1698cbdf022093a0bf90bfdd1e78abd0e', 'Holding back past a minute'),
('performance_listening_notes', 282, 'note_en', '36242bee8d3a2c04908539b296393c3109278e7ddb86b96801d1ecd677ffa472', 'Holds back the big passage in the first part more than the other two, reaching nearly maximum only after a minute. Its loud playing is also shorter than Serkin''s.'),
('performance_listening_notes', 283, 'headline_en', '1ea25d35c8e43876fbebf96abca848e4951e8a7d8e845985643571583b6386ea', 'Loud from the first melody'),
('performance_listening_notes', 283, 'note_en', 'ceace3a17e5e6ba816d6be660a7c85cb290e67cc983359908ce87e38a3c8fe53', 'Plays louder than the other two from the first note. It already rises to the climax''s level early on, and builds to that level once more later.'),
('performance_listening_notes', 284, 'headline_en', 'bc79f282b653ce27ffc61954ed91241a9b732de14b5c074f1c4c5eb9aaf185da', 'Pushing hard within 16 seconds'),
('performance_listening_notes', 284, 'note_en', '9662bbd0c1a4064938237c6be00ba92f9b6e7274705e1b47e2981f0daab3ce53', 'At 3 min 9 sec, it is 27 seconds shorter than Gould. It reaches nearly maximum in 16 seconds and sustains loud playing for a long time.'),
('performance_listening_notes', 285, 'headline_en', 'd7ef94c228f1893a559ac5f67813fe79b90db7c3d205587c879c98c745806d57', 'Loud in the middle too'),
('performance_listening_notes', 285, 'note_en', '26bc25fecc976b30cf3a6a6c1a886ee57b4fee0dad378e50b422ce66f181ccfe', 'At 3 min 36 sec, it is the longest of the three. It carries the middle louder than the other two, and rises to its loudest at the end.'),
('performance_listening_notes', 286, 'headline_en', '51e316e4b8f31adcfd9e7c271e19463ea2af6b8ed7fe11dd690f94d8fc6359a0', 'Built up in the last minute'),
('performance_listening_notes', 286, 'note_en', '21113abbce39002a5d773f4160c8020e389dc87f34ff3fae12f6d0d3058ca3e2', 'Keeps loud playing shorter than the other two and stays a level lower until the middle. It builds big in the final minute or so.'),
('performance_listening_notes', 287, 'headline_en', 'fe530d0bc8116181ea791f1f81acb11948e8ff0bc23c1234a0fe9bc38a57427d', '7 min 38 sec, deep sinking'),
('performance_listening_notes', 287, 'note_en', '71a1ba9e0362aaa8fc345ac18d786d4f847efd137cdd716877040feb656c8176', 'At 7 min 38 sec, it is about a minute and a half longer than Yuja Wang. It sinks the soft passages the deepest, and ends the softest too.'),
('performance_listening_notes', 287, 'facts_en', '71a1ba9e0362aaa8fc345ac18d786d4f847efd137cdd716877040feb656c8176', '["Currentzis · Mahler Chamber"]'),
('performance_listening_notes', 288, 'headline_en', '0c202f3da110a0d5c49161df811743a76183589e68340be55e5745ce0c19f671', 'A level louder from the start'),
('performance_listening_notes', 288, 'note_en', '8c7a0485f2ab1174f1b9be72d7e5f7636271f2d9543facc022b660e7bdd0b8e2', 'Opens the loudest of the three. Even after the climax it stays big for a while.'),
('performance_listening_notes', 288, 'facts_en', '8c7a0485f2ab1174f1b9be72d7e5f7636271f2d9543facc022b660e7bdd0b8e2', '["Wolff · Saint Paul Chamber"]'),
('performance_listening_notes', 289, 'headline_en', 'd7a7749e6496427c89a44a128e6963032ec4e495f71f97d5b295f9bee7cf4960', 'The shortest, 6 minutes'),
('performance_listening_notes', 289, 'note_en', 'd334d20f6b2d9401c914c927f28e54679befe07b29d9d9030f1f0de7b7b25681', 'At 6 min 5 sec, it is shorter than the other two. The ending doesn''t get as soft as Melnikov''s.'),
('performance_listening_notes', 289, 'facts_en', 'd334d20f6b2d9401c914c927f28e54679befe07b29d9d9030f1f0de7b7b25681', '["Nelsons · Boston Symphony"]'),
('performance_listening_notes', 290, 'headline_en', '1bb295ebd9b633ab862179eb9b67039806264cbee3880f7a1374704ba9a4ac1f', 'Orchestra raised early'),
('performance_listening_notes', 290, 'note_en', 'f7fbe53a2d227814f65cdc39f963aec2c62ce9f825b4bb0cfda6cfd93b87323c', 'Raises the orchestra to a big sound earlier than the other two. Afterward it doesn''t sink as deep as the other two.'),
('performance_listening_notes', 290, 'facts_en', 'f7fbe53a2d227814f65cdc39f963aec2c62ce9f825b4bb0cfda6cfd93b87323c', '["Ashkenazy · Cleveland"]'),
('performance_listening_notes', 291, 'headline_en', 'ea89d04dbb104b8e3a46e2dde705ce7885b5f3307eb9b838e3ebdf9f179c9de0', 'Introduction held back 30+ seconds'),
('performance_listening_notes', 291, 'note_en', '0e805480669756bcd439bb91ab38f3053f43945d4c7c375cbfa16761381c5c96', 'Opens the introduction the softest of the three, and it runs about 12 seconds longer than the other two. After holding back for over 30 seconds, it rises big in one move.'),
('performance_listening_notes', 291, 'facts_en', '0e805480669756bcd439bb91ab38f3053f43945d4c7c375cbfa16761381c5c96', '["Karajan · Vienna Phil"]'),
('performance_listening_notes', 292, 'headline_en', '94b4fa2bfdd1f1f160e0cf567729b7938d9577615a7effc43f737a40658bc46c', 'Big again at the solo'),
('performance_listening_notes', 292, 'note_en', '44cb64dfdf2e75088ebc7e4f88638a71feff376eac3b2d4b0e1579ac9c116fc7', 'After the solo enters, it rises again louder than the other two. The ending also closes less softly than Bell''s and Mutter''s.'),
('performance_listening_notes', 292, 'facts_en', '44cb64dfdf2e75088ebc7e4f88638a71feff376eac3b2d4b0e1579ac9c116fc7', '["Harding · Mahler Chamber"]'),
('performance_listening_notes', 293, 'headline_en', 'e8e1def65bae43b64b88c6c0d526216ca103b81838dc0c77a87bb42adff4fb40', 'Softest opening melody'),
('performance_listening_notes', 293, 'note_en', 'a56070bd8bde8c4677bb591af1a9145583995a44477b1860b463b7af52e4e07e', 'Plays the opening melody the softest of the three. So the contrast with the minor-key section is greater than in the other two.'),
('performance_listening_notes', 293, 'facts_en', 'a56070bd8bde8c4677bb591af1a9145583995a44477b1860b463b7af52e4e07e', '["Academy of St Martin"]'),
('performance_listening_notes', 294, 'headline_en', '1712c846502d379cd51f454fa1eb8e87dd81a90a2f0706cbe601b0d135c71f11', 'Loud and even, the shortest'),
('performance_listening_notes', 294, 'note_en', '78a44b2efdcf5be2618e93e77f550614cb6773d561f6c8b7299dfe0a94bcc3ed', 'At 1 min 31 sec, it is the shortest of the three. Through all three replies it keeps the loud level the most even of the three.'),
('performance_listening_notes', 294, 'facts_en', '78a44b2efdcf5be2618e93e77f550614cb6773d561f6c8b7299dfe0a94bcc3ed', '["Abbado · Berlin Phil"]'),
('performance_listening_notes', 295, 'headline_en', '089c672256dcbfe7e95f627cb8b65d0a2ae000011599bdbab2e64b1a0b869a0b', 'Climax at the very end'),
('performance_listening_notes', 295, 'note_en', 'f4fdabcddc8b964f60db1124536571a6189e2aba1f8d79683c922ec79713dbaf', 'The other two are loudest at the first reply; only Lupu rises loudest at the very end. The middle is held a level lower.'),
('performance_listening_notes', 295, 'facts_en', 'f4fdabcddc8b964f60db1124536571a6189e2aba1f8d79683c922ec79713dbaf', '["Mehta · Israel Phil"]'),
('performance_listening_notes', 296, 'headline_en', '6deb9b2ec948746250e33e125fd96fa2e606753a2e783879cffb64efa5360902', 'Near maximum four times'),
('performance_listening_notes', 296, 'note_en', 'b9f3e52e7f117c39eb564516ca8aa0027cdcda0eb19fa98abce03ae7e69d8352', 'At 8 min 29 sec, it is shorter than the other two. In the minor-key section it reaches nearly maximum four times, staying loud for over a minute.'),
('performance_listening_notes', 296, 'facts_en', 'b9f3e52e7f117c39eb564516ca8aa0027cdcda0eb19fa98abce03ae7e69d8352', '["Zacharias · Bavarian Radio"]'),
('performance_listening_notes', 297, 'headline_en', 'b99f0e11713efcc3a7bc94d82ddf51e3c26ce1821fcfe3ccd25d45d331d76ba9', 'Loud even in the opening melody'),
('performance_listening_notes', 297, 'note_en', 'ad1404ed5376a9f8afa74a1e4854b12bed995b6e4fc869cfcbe222ca0f778335', 'Enters loudly from the first melody and reaches nearly maximum before the other two. It also opens the gap between soft and loud less.'),
('performance_listening_notes', 297, 'facts_en', 'ad1404ed5376a9f8afa74a1e4854b12bed995b6e4fc869cfcbe222ca0f778335', '["Nézet-Séguin · Chamber Orchestra of Europe"]'),
('performance_listening_notes', 298, 'headline_en', '702a5095ab86ff0a1cf9f53a45b448bf175a612bc4791fcdf3cef712cc4e5997', 'Holds back the first chord'),
('performance_listening_notes', 298, 'note_en', '43289b26cd21f6da51a167de93281e60687d9c44c9f7b9c6876823155a87fc98', 'Saves the first chord more than the other two, so reaching nearly maximum takes 18 seconds. It also sinks the middle the deepest.'),
('performance_listening_notes', 298, 'facts_en', '43289b26cd21f6da51a167de93281e60687d9c44c9f7b9c6876823155a87fc98', '["Mehta · Vienna Phil"]'),
('performance_listening_notes', 299, 'headline_en', '94f9431c3deb8c2bb502ce4aeded2c865f15db58a813e8c9025ac5f864e04f66', 'Climax 4 seconds from the end'),
('performance_listening_notes', 299, 'note_en', '4d3d885ce4e38940249fb4587774d4a113dc584149f6b078f6a08898870ec45d', 'After reaching nearly maximum on the first tutti, it sinks deeply on the second theme. The loudest sound comes later than in the other two, 4 seconds before the end.'),
('performance_listening_notes', 299, 'facts_en', '4d3d885ce4e38940249fb4587774d4a113dc584149f6b078f6a08898870ec45d', '["Academy of St Martin"]'),
('performance_listening_notes', 300, 'headline_en', '93897da6fc811897e8dee4f45d961105d255696d0245d28c1fc2bed3ea5a1834', 'Weight on the second fanfare'),
('performance_listening_notes', 300, 'note_en', 'f8ce66d6c8a8c6ac9119bdbce37b386829ff2cfafcefa7b94825c95ca5ee1ce8', 'Cries out the second fanfare louder than the first. It sinks the ending the softest of the three.'),
('performance_listening_notes', 300, 'facts_en', 'f8ce66d6c8a8c6ac9119bdbce37b386829ff2cfafcefa7b94825c95ca5ee1ce8', '["Berlin Phil"]'),
('performance_listening_notes', 301, 'headline_en', '871bcca779854f174490cc8c92238edafe5e82a99ee08428bf25a26825aa108f', 'Earliest and longest'),
('performance_listening_notes', 301, 'note_en', 'ccc08e2d883c9a7dc7c996bf51d5da1c9e5d7aee4ff5053a56247d8fbed39e75', 'Reaches nearly maximum the earliest of the three and sustains loud playing the longest. After the second theme it rises big again and pushes on to the end.'),
('performance_listening_notes', 301, 'facts_en', 'ccc08e2d883c9a7dc7c996bf51d5da1c9e5d7aee4ff5053a56247d8fbed39e75', '["Berlin Phil"]'),
('performance_listening_notes', 302, 'headline_en', '2ab3361de06b6def3efb2ff9d77a12feefa1b1d711cc072d3861cc962647c9b5', '1 min 45 sec, strong first fanfare'),
('performance_listening_notes', 302, 'note_en', 'de45ff380012a85d5c851119f8d4e8e1fcb3762fe97d107dec0cdcfebffab324', 'At 1 min 45 sec, it is more than 15 seconds shorter than the other two. It cries out the first fanfare the loudest and answers the second at almost the same level.'),
('performance_listening_notes', 302, 'facts_en', 'de45ff380012a85d5c851119f8d4e8e1fcb3762fe97d107dec0cdcfebffab324', '["Gewandhaus"]'),
('performance_listening_notes', 303, 'headline_en', '076bfbd406bd453a2b50a5ad0c0554414db5829c619229838a1d9b8135e52e4e', 'Longest, soft ending'),
('performance_listening_notes', 303, 'note_en', '827739acf5092127ab775b155dfb78e25dd10aa59eb59817c65bcf263a026435', 'At 2 min 10 sec, it is 25 seconds longer than Chailly. It cuts loud playing short and gives the soft passages more room toward the end.'),
('performance_listening_notes', 303, 'facts_en', '827739acf5092127ab775b155dfb78e25dd10aa59eb59817c65bcf263a026435', '["Seoul Philharmonic"]'),
('performance_listening_notes', 304, 'headline_en', '73ea3cddcb9561bfe8a8f580d937448a9776a68da1c6b64360f4e7e14485fab4', 'Big only in the last 20 seconds'),
('performance_listening_notes', 304, 'note_en', '048f28e069137bb26133a27355315507a9ccd0397a4a86d0051392742f9b4e6f', 'Starts more softly than the other two and reaches nearly maximum only after more than a minute. It is also slightly longer than the other two.'),
('performance_listening_notes', 304, 'facts_en', '048f28e069137bb26133a27355315507a9ccd0397a4a86d0051392742f9b4e6f', '["Vienna Phil"]'),
('performance_listening_notes', 305, 'headline_en', '15f9d6fce1538b86087bbb69036a661db77c797b9bcb51d5e00a92255e7e2eed', 'Loud last 30 seconds'),
('performance_listening_notes', 305, 'note_en', '3680b827fba46378637d42d58af127123f6eff6da3394b377de0c87cfe1ffee9', 'At 1 min 31 sec, it is the longest of the three. It starts building about 10 seconds earlier than the other two and pushes the last 30 seconds loudly.'),
('performance_listening_notes', 305, 'facts_en', '3680b827fba46378637d42d58af127123f6eff6da3394b377de0c87cfe1ffee9', '["Philadelphia Orchestra"]'),
('performance_listening_notes', 306, 'headline_en', 'd7dea3bdf4e256d57232b53d3f693f7e32f6d59365092d8f102063956a6c898f', 'Quietest bassoon'),
('performance_listening_notes', 306, 'note_en', '3b72b8038f7d7b4ebf30e91f0c9769b6e63088620ef51f055987161fbecd91cb', 'Plays the bassoon''s first note softer than the other two. It builds bit by bit for over a minute, then raises it all at once 20 seconds before the end.'),
('performance_listening_notes', 306, 'facts_en', '3b72b8038f7d7b4ebf30e91f0c9769b6e63088620ef51f055987161fbecd91cb', '["Mariinsky Theatre Orchestra"]'),
('performance_listening_notes', 307, 'headline_en', '680a16f8ee2bff0312b36c0a2bb65fccc486549ae5b6a4cc8c2e800e66b50582', 'A clearly opened bassoon'),
('performance_listening_notes', 307, 'note_en', 'ae06280051dda4606e26a4aaedaee1c68dd983dc840e172d19c1275d2efc8277', 'Opens the bassoon louder than the other two. It holds a similar level for over a minute, then builds in a rush in the last 20 seconds.'),
('performance_listening_notes', 307, 'facts_en', 'ae06280051dda4606e26a4aaedaee1c68dd983dc840e172d19c1275d2efc8277', '["LA Phil"]'),
('performance_listening_notes', 309, 'headline_en', 'd19e5c35ae70c3a2dedaa515f9ff808d5ff919f8c20788ab6572a0befbbf0af7', 'Over 50 seconds shorter'),
('performance_listening_notes', 309, 'note_en', 'b2e523a98d6214f905204e3894959c2f855fcc61385ea3bb0131f268aa268cf0', 'At 4 min 38 sec, it is more than 50 seconds shorter than the other two. It also sustains loud playing for the shortest time, and rises to its loudest near the end.'),
('performance_listening_notes', 310, 'headline_en', '368a07e57d42a53166bcf8b71bbc9423a7de82c3f6bf5e0704e19384024a981d', 'Sinks, then one leap'),
('performance_listening_notes', 310, 'note_en', '41e0850dea2fb575e6bb5dcc7a08bb5842107c91fb0363e64f7603c86617142f', 'At 5 min 56 sec, it is more than a minute longer than Yundi Li. It sinks to its quietest in the later part, then rises to its loudest in 24 seconds.'),
('performance_listening_notes', 311, 'headline_en', '211687cf5352fdf2152bf899db11587ff2aeb5b4c57eef4e22a5b6c21587d2f4', 'Climax in the first section'),
('performance_listening_notes', 311, 'note_en', '10a05bb745cdb19ccac2e8f5ccca848dc3f436e9e09a72b89f73bbb1a4a01557', 'Alone in rising loudest in the first fast section. It plays the returning fast section at almost that loud.'),
('performance_listening_notes', 312, 'headline_en', 'c90c8e7de5cd611c5f082629a0fed959e90b4b6236121a974640eddf259a1741', 'A loud first phrase'),
('performance_listening_notes', 312, 'note_en', 'e5125c008a727e12bdf8a227982c33a09c26015cefe174a21a0ae92ba6323fcd', 'Plays the first note the loudest of the three, and the ending doesn''t get as soft as in the other two. The gap between soft and loud is also narrower.'),
('performance_listening_notes', 315, 'headline_en', 'f70c808ee74023e52858e172f423810bc5f685be59808e9daa3d755a1753db91', 'Quietest a minute after the climax'),
('performance_listening_notes', 315, 'note_en', '744be03b4e80ea077c709c74d909ca5c31d3c8b687237306e693deeea9bc9eb6', 'At 5 min 1 sec, it is 41 seconds longer than Kissin. A minute after the climax it sinks to its quietest, and closes the ending more softly than Lang Lang and Kissin.'),
('performance_listening_notes', 316, 'headline_en', '14316f036f7a4d73b5d2a0148182ee5bc70fbb839330ca21c98f437010995537', 'Holding the climax long'),
('performance_listening_notes', 316, 'note_en', '59cd80647243e429fbd41cbb2f1c830d51198ac68d943f7087b68a25de057055', 'At 4 min 20 sec, it is shorter than the other two. It has already reached nearly maximum 15 seconds before the climax, and holds loud playing for a long time.'),
('performance_listening_notes', 317, 'headline_en', '74d38c75752b97f1008aa25241190f277a628baf14c5e46cc9b54d48b04a654a', 'Climax in the later part'),
('performance_listening_notes', 317, 'note_en', 'bf30611ce2fa3258e07a8b134de83218932b58c71375c25d2553b48c1c2d840c', 'The loudest sound comes later than in the other two, in the later part. It sustains loud playing the longest of the three.'),
('performance_listening_notes', 317, 'facts_en', 'bf30611ce2fa3258e07a8b134de83218932b58c71375c25d2553b48c1c2d840c', '["Singapore Symphony"]'),
('performance_listening_notes', 318, 'headline_en', '84fadfdca44126fb29d35c048ea4d1940ba4a759d0b1b98668e7861ce7636a58', 'Soft start, maximum at the end'),
('performance_listening_notes', 318, 'note_en', '8bb6c135a7bcbadc958e96024b1c0064c4f7f324e68e336989a98feea8bc7f53', 'At 9 min 25 sec, it is the longest of the three. It brings out the theme the softest and plays the final chord the loudest.'),
('performance_listening_notes', 319, 'headline_en', 'cc84b04a399f8d8059131cbd7426ef7d69f9e3f366bdebe5ad9d3280b0677751', 'Soft from the saxophone'),
('performance_listening_notes', 319, 'note_en', '929395e8961428cd2cd69b20ea4963bbdaec8c643330e0757cacfe00ca0a700d', 'Opens the first sound more softly than the other two. It builds for over a minute and rises to its loudest just before the middle.'),
('performance_listening_notes', 319, 'facts_en', '929395e8961428cd2cd69b20ea4963bbdaec8c643330e0757cacfe00ca0a700d', '["Royal Concertgebouw"]'),
('performance_listening_notes', 320, 'headline_en', '3e69b1231977ff3767c8bf427b0a784af00c3a5c880806b22ea16aed638e036a', 'Shortest, peak in the middle'),
('performance_listening_notes', 320, 'note_en', '27600cebdf0ccd1d104a8c2a28000c12df446dca13851154f43c8050a54f71c0', 'At 7 min 46 sec, it is about 1 min 40 sec shorter than Ciccolini. Alone in playing loudest in a middle variation.'),
('performance_listening_notes', 321, 'headline_en', '937a58d4b46016716e99499af1e598433d4d4e7a92674976eba6aa28bcf5fdf1', 'Even, without cutting back'),
('performance_listening_notes', 321, 'note_en', 'd863f916d5a733ff9409e702f2b48ffa910dd0e23ad62a4ac334ee2516872c02', 'Moves on evenly with no big pull-backs. It leaves the last 10 seconds louder than Litton and Chailly.'),
('performance_listening_notes', 321, 'facts_en', 'd863f916d5a733ff9409e702f2b48ffa910dd0e23ad62a4ac334ee2516872c02', '["Vienna Phil"]'),
('performance_listening_notes', 322, 'headline_en', 'dd4a57f2d64813b8426e81cba0f147dad941bf149eed265208a779143408078e', 'Sinks before the end, then maximum'),
('performance_listening_notes', 322, 'note_en', 'c5d34f9e80d64869a9078e9776bfc329dbd32ca6f2cec693312c6de7d8049426', 'Like Ciccolini, it plays loudest at the end. About a minute before that, it sinks to its quietest and then pulls back up.'),
('performance_listening_notes', 323, 'headline_en', 'cad1c7369d4c6695d31149b43c9732657069c0a887bc1bbc3902367c98cec66f', 'Low until 20 sec from the end'),
('performance_listening_notes', 323, 'note_en', 'eb144f74faf6af185dfb75ad126d860f2b12f8c54f7b6f1423cdbf2b8af1c6e6', 'Stays low for over a minute, then rises to its loudest in one move 20 seconds before the end. The gap between soft and loud is greater than in the other two.'),
('performance_listening_notes', 323, 'facts_en', 'eb144f74faf6af185dfb75ad126d860f2b12f8c54f7b6f1423cdbf2b8af1c6e6', '["Wordsworth · Royal Phil"]'),
('performance_listening_notes', 324, 'headline_en', 'f16934b942be295267c9107421b580d2207dc3437a1d0d631f93c8b99782f6a4', 'A level louder from the middle'),
('performance_listening_notes', 324, 'note_en', '1fbac80962992923553cfd7a2193a5c559ded3deb6eb411d755abcf6a270cc10', 'At 1 min 36 sec, it is the longest of the three. From the middle section on it raises the volume a level and builds once more at the end.'),
('performance_listening_notes', 324, 'facts_en', '1fbac80962992923553cfd7a2193a5c559ded3deb6eb411d755abcf6a270cc10', '["Columbia Symphony"]'),
('performance_listening_notes', 325, 'headline_en', '4f20258f33f880a0e195815e520502f6c841c24ebd864592be7d661bd4c12bc9', 'Latest, all at once'),
('performance_listening_notes', 325, 'note_en', '38324a76496c836edc500ef3a5d9de59cb29fe9d5bb8528b8229fec228a6556f', 'Plays the clarinet''s first note softer than the other two. It also presses the middle low, and rises in one move only at the very end.'),
('performance_listening_notes', 325, 'facts_en', '38324a76496c836edc500ef3a5d9de59cb29fe9d5bb8528b8229fec228a6556f', '["Wolff · BBC Symphony"]'),
('performance_listening_notes', 326, 'headline_en', '384563644b2afce78481647fe6d4928a5722db9396e9504b5c5cea235436c403', 'Driving from the start'),
('performance_listening_notes', 326, 'note_en', 'bc80ada8ed15f4dd8f9058a7de1ba9c4bf69627f73827f0ecc24c6d9a280a1ad', 'Enters at nearly maximum from the first note and sustains loud playing the longest of the three. The middle drops only a level.'),
('performance_listening_notes', 327, 'headline_en', 'ab8533dceac887e9545e3476c922d5473b240c7e0ed424637c09e5d6df986f96', 'Soft opening, big swings'),
('performance_listening_notes', 327, 'note_en', '102b68e5ef3b405330aabf5145923e6ddae7b88a85b81988a497598c4d47fba1', 'Opens the softest of the three. The gap between soft and loud is also the largest, and within a minute of the climax it sinks to its quietest.'),
('performance_listening_notes', 328, 'headline_en', '6254c0d9f3954148f96b29165f878733ee4b62b066ef1e56978144df6f1b62d4', 'Shortest, early climax'),
('performance_listening_notes', 328, 'note_en', 'dc87d6983faf36cce0861c690325c27e257e4144ee13be4777154f0d95bd206c', 'At 3 min 15 sec, it is 22 seconds shorter than Giltburg. It catches its breath most deeply in the middle, and hits the climax earlier than the other two.'),
('performance_listening_notes', 329, 'headline_en', 'ea4df3a4865d96b4313712a071a13c2f9c31e6b132b1aea6ee273a58729a7b78', 'Held back for 40 seconds'),
('performance_listening_notes', 329, 'note_en', 'da9ffcd28e97e0e07d8294f72a3defb91ccbd4577f21b4a1dad93f191cdf1b78', 'Carries the middle lower than Rubinstein. It reaches nearly maximum only with 40 seconds left.'),
('performance_listening_notes', 330, 'headline_en', '1156ed460eb5248831e6e87ee5d69e9527911a8c76d29fd95257077adb07370e', 'Early and even'),
('performance_listening_notes', 330, 'note_en', '401f801846a6f229df549db1167bb9d8e234b6e351da6382649152f076d34fec', 'Reaches nearly maximum earlier than the other two. It keeps the volume gap small and sustains loud playing for a long time.'),
('performance_listening_notes', 331, 'headline_en', '3cc6cf30629210cd524dda844a1a79c6f830f5d7b15b755f9fbeacc8a4e51b0d', 'Longest, late climax'),
('performance_listening_notes', 331, 'note_en', '1555ed17a42c8d4322600214f502c7be0801d5dfe0607eacc38253c1595201a5', 'At 6 min 52 sec, it is about 45 seconds longer than the other two. Alone in placing the climax past the 4-minute mark, and it sets down softly right after.'),
('performance_listening_notes', 332, 'headline_en', '4fcc1d871214213b74fb09eb1cb3f23d6b478930b16e3aef08944fa2c4c096e0', 'Late, built all at once'),
('performance_listening_notes', 332, 'note_en', '85f4d287fc0cdee7b4fa0765f3d4340fb77bfbba9bace02af87041c14a373e77', 'Keeps the first minute low. It starts getting louder later than the other two and builds all at once in the last 20 seconds.'),
('performance_listening_notes', 332, 'facts_en', '85f4d287fc0cdee7b4fa0765f3d4340fb77bfbba9bace02af87041c14a373e77', '["Philadelphia"]'),
('performance_listening_notes', 333, 'headline_en', '774b1822009cdfab865c58444063de759bc0add767c5452f64c3b036050b4040', 'Early rise, then sinking'),
('performance_listening_notes', 333, 'note_en', 'c8093da26c7abaacd62df6c361f7037681322b60746b06b5e9ea21fe4ddef1bd', 'Builds once earlier than Muti and Masur, then sinks deeply soon after. After that it builds up to the end in three stages.'),
('performance_listening_notes', 333, 'facts_en', 'c8093da26c7abaacd62df6c361f7037681322b60746b06b5e9ea21fe4ddef1bd', '["Berlin Phil"]'),
('performance_listening_notes', 334, 'headline_en', 'c01cafc97316a32cc0ddbd6601a55363ce9659de56e811f012b940bc2bd40775', '1 min 53 sec, deep opening'),
('performance_listening_notes', 334, 'note_en', 'be7b5ba21c7812180e7ee541963df8d2d9db95d687d56ae331b7580fe81615c8', 'At 1 min 53 sec, it is the shortest of the three. The first sound and the low point early on are both softer than in the other two.'),
('performance_listening_notes', 334, 'facts_en', 'be7b5ba21c7812180e7ee541963df8d2d9db95d687d56ae331b7580fe81615c8', '["Gewandhaus"]'),
('performance_listening_notes', 335, 'headline_en', 'f1a2a7fdf5d14db3eaa6255d59c8ce0f1c46a9f663a91f440ff0cf4dad3c6d0e', 'Loud the latest'),
('performance_listening_notes', 335, 'note_en', 'ed64ee6c0d7d8be3eec37b602b889f9b932eb8388983bd391af1025135b80abb', 'Holds back the volume for over the first 30 seconds, then raises it slowly. It reaches nearly maximum the latest of the three, and its loud playing is the shortest too.'),
('performance_listening_notes', 335, 'facts_en', 'ed64ee6c0d7d8be3eec37b602b889f9b932eb8388983bd391af1025135b80abb', '["New York Phil"]'),
('performance_listening_notes', 336, 'headline_en', '44ffd339c7d9a6573c8abf3ff3db39dbf115c4dbbc5aa5ae4d8cef5c5b989bb0', 'Builds and lets go, again and again'),
('performance_listening_notes', 336, 'note_en', '07818ad92aa6b61e56c8e1ee4a97aadd0c96b5be04fd51d142759fdf4564670e', 'Repeats building and letting go four times, rising a level each time. It plays loudest at the end, then cuts back sharply soon after.'),
('performance_listening_notes', 336, 'facts_en', '07818ad92aa6b61e56c8e1ee4a97aadd0c96b5be04fd51d142759fdf4564670e', '["Cleveland Orchestra"]'),
('performance_listening_notes', 337, 'headline_en', '3c84ebceb43c67fd5e957e2bee6f5fa5ffbcb66cf1c42c446ced9b4401f8f008', 'Maximum from start to finish'),
('performance_listening_notes', 337, 'note_en', 'fa7ae63d7671eed207b9e3816f22090489a8fcdbf11b80efdab06c81cce74c33', 'Enters at nearly maximum from the first note and never lets down. It sustains loud playing the longest of the three.'),
('performance_listening_notes', 337, 'facts_en', 'fa7ae63d7671eed207b9e3816f22090489a8fcdbf11b80efdab06c81cce74c33', '["Montreal Symphony"]'),
('performance_listening_notes', 338, 'headline_en', 'b2bd71de8f2c8b16960492e102fb0d9a17d032187d9909956c4dab87d4be7961', 'First half held back'),
('performance_listening_notes', 338, 'note_en', 'b5c0aa0f4208615542c1e934e41bb1fcd101940ffbc8f4961e3f8d541ec9d994', 'At 1 min 49 sec, it is shorter than the other two. It keeps the first half a level lower, raises it in a rush later, and lets the ending down the most.'),
('performance_listening_notes', 338, 'facts_en', 'b5c0aa0f4208615542c1e934e41bb1fcd101940ffbc8f4961e3f8d541ec9d994', '["Berlin Phil"]'),
('performance_listening_notes', 339, 'headline_en', '267ac7bef91e61d1d1372fefe01cd7f043cb25b22653ed5048f8fb2d02a55e04', 'Near maximum in 17 seconds'),
('performance_listening_notes', 339, 'note_en', '58c68e0ad1a667f8a2e633341287c713f68e2797e97b0b05ca7b5b28963c3c10', 'Pushes loudly from the start and reaches nearly maximum more than 40 seconds earlier than Bernstein. It also sustains loud playing longer than the other two.'),
('performance_listening_notes', 339, 'facts_en', '58c68e0ad1a667f8a2e633341287c713f68e2797e97b0b05ca7b5b28963c3c10', '["LA Phil"]'),
('performance_listening_notes', 340, 'headline_en', '502470e2588ab42b50b340bb3ad984782af08df81b93ced7a9fda1136f43197d', 'Straight there, one step back'),
('performance_listening_notes', 340, 'note_en', 'cc8c900383644c50f3c9bef0bb1034a75abe8734d1d4bab89368dc839d0663e4', 'After reaching nearly maximum in 6 seconds, it pulls back once, then rises to its loudest in the middle. The ending is also held big.'),
('performance_listening_notes', 340, 'facts_en', 'cc8c900383644c50f3c9bef0bb1034a75abe8734d1d4bab89368dc839d0663e4', '["Oslo Phil"]'),
('performance_listening_notes', 341, 'headline_en', 'd93a77a3dd7595877d6e0ae030e20ca9f21a8b9936168578767898ecfd713232', 'Held back, then maximum later'),
('performance_listening_notes', 341, 'note_en', '3b5164e87916c977cba4bf27c13d4ddcb7df4991a6bdae93f3d0b75cb36bf34d', 'Alone of the three in reaching nearly maximum only in the big later passage. It sinks the theme the deepest and plays loudest there.'),
('performance_listening_notes', 341, 'facts_en', '3b5164e87916c977cba4bf27c13d4ddcb7df4991a6bdae93f3d0b75cb36bf34d', '["Davis · London Symphony"]'),
('performance_listening_notes', 342, 'headline_en', '1b668c9e89eeeacd241763f6458c4104c782cbdf169ce3334ce8f6d57fecbac3', 'Loudest first chord'),
('performance_listening_notes', 342, 'note_en', '269821db03dde021fa3e307b376b89835f04915b1e2d1904a8ce0f53238dc6c7', 'Alone in playing the first descending chord the loudest. It rises once more to almost the same level in the big later passage.'),
('performance_listening_notes', 342, 'facts_en', '269821db03dde021fa3e307b376b89835f04915b1e2d1904a8ce0f53238dc6c7', '["Abbado · Berlin Phil"]'),
('performance_listening_notes', 343, 'headline_en', '2c92a9108346d182938da220631528b9fad5774eec08d75832cb65dbf84082d8', 'Maximum at the start and later'),
('performance_listening_notes', 343, 'note_en', '85504e153bf0c51b9eff1c61dc747248c54d098dfb8e7a3ec8bf10ea8619e546', 'Plays nearly maximum from the first descending chord. The loudest playing is in the big later passage.'),
('performance_listening_notes', 343, 'facts_en', '85504e153bf0c51b9eff1c61dc747248c54d098dfb8e7a3ec8bf10ea8619e546', '["Abbado · Berlin Phil"]'),
('performance_listening_notes', 344, 'headline_en', 'bdde6ea989a869401f3c8f1cdec6e6774a3dabf728c168ea9f66cc276ff6546a', 'No coming down once up'),
('performance_listening_notes', 344, 'note_en', '270d0da1722e60b0f2c548004282e6f1b5db6a10acd844f9cd7c16d2c7d9531e', 'Once it starts getting louder, it keeps a big volume to the end. Even after the climax it doesn''t sink as much as the other two.'),
('performance_listening_notes', 344, 'facts_en', '270d0da1722e60b0f2c548004282e6f1b5db6a10acd844f9cd7c16d2c7d9531e', '["Conlon · Fort Worth Symphony"]'),
('performance_listening_notes', 345, 'headline_en', 'db51b95b6d41ac825ff4a370bbfecaa02a60559fb02cc67cf51685f76ce974cd', 'A long loud opening'),
('performance_listening_notes', 345, 'note_en', '113fc6579701c31190d23be6723d24d353cabca99b80c90d69902db522aa582d', 'Sustains the loud opening exchange longer than the other two. After sinking, it leaves the ending less soft than Thibaudet does.'),
('performance_listening_notes', 345, 'facts_en', '113fc6579701c31190d23be6723d24d353cabca99b80c90d69902db522aa582d', '["Abbado · London Symphony"]'),
('performance_listening_notes', 346, 'headline_en', '5e44bf6876f7568d5dcf63c62f95ef2b48d94d0109db4e746a16971e358982fa', 'Pulls back, then again'),
('performance_listening_notes', 346, 'note_en', '1ecc0fda53c771efd4d552d86fa1204b6c916da52f361d150fdaa2506dd61c41', 'Places the climax later than the other two, then pulls back once and rises again. It closes the ending the softest of the three.'),
('performance_listening_notes', 346, 'facts_en', '1ecc0fda53c771efd4d552d86fa1204b6c916da52f361d150fdaa2506dd61c41', '["Dutoit · Montreal Symphony"]'),
('performance_listening_notes', 347, 'headline_en', '7749e0641be53403bbdd44b9ea379dbc35b1749038f44b32dace7c27a69883dd', 'Loudest at the very end'),
('performance_listening_notes', 347, 'note_en', '6813e6040e697d7c7328f0c0b5d6d6f1f033e1efea0cb0e64a2b27121cdc8835', 'At 2 min 1 sec, it is about 15 seconds longer than the other two. After sinking deeply once, it rises to its loudest in the last few seconds.'),
('performance_listening_notes', 347, 'facts_en', '6813e6040e697d7c7328f0c0b5d6d6f1f033e1efea0cb0e64a2b27121cdc8835', '["Noseda · London Symphony"]'),
('performance_listening_notes', 348, 'headline_en', 'b07a637a609e694053cb592845bae9023e8ada86edf706d0fc76afe1dfe55a85', 'The deepest sinking'),
('performance_listening_notes', 348, 'note_en', '30894bc9714b6369ae8540ceb8a97dd5de1da66785c1ee6819661da6fa17a8e8', 'At 1 min 46 sec, it is 15 seconds longer than the other two. It reaches nearly maximum in 4 seconds, and sinks the deepest later on.'),
('performance_listening_notes', 348, 'facts_en', '30894bc9714b6369ae8540ceb8a97dd5de1da66785c1ee6819661da6fa17a8e8', '["Hengelbrock · Munich Phil"]'),
('performance_listening_notes', 349, 'headline_en', 'd676bcb39df37cf14718d9da8c142fbc6efb72e2ed817279afcc5cb480910691', 'Early peak, deep sinking'),
('performance_listening_notes', 349, 'note_en', '721e500f2ca7e818e826f51a042b36c4da242b805dcea08cb87eacefbfb6b934', 'Reaches nearly maximum the earliest of the three. It then sinks deeply and rises big again at the end.'),
('performance_listening_notes', 349, 'facts_en', '721e500f2ca7e818e826f51a042b36c4da242b805dcea08cb87eacefbfb6b934', '["Mehta · Vienna Phil"]'),
('performance_listening_notes', 350, 'headline_en', 'f23fcdbd6621b925c0fc96be59cc97b075195b5530e6519d42f465cfa1840f3b', 'Fastest, greatest contrast'),
('performance_listening_notes', 350, 'note_en', 'b3c21abda5d76837fcbe8730bd1cd068438f979337e3ec165115aeb3cf40dbd5', 'The fastest of the three, so the surprise chord comes first. It lays the theme before it the softest, giving the greatest contrast.'),
('performance_listening_notes', 350, 'facts_en', 'b3c21abda5d76837fcbe8730bd1cd068438f979337e3ec165115aeb3cf40dbd5', '["Berlin Phil"]'),
('performance_listening_notes', 351, 'headline_en', '978bd27b9765a499a340f50028e9c6434a154a0f1c475c73b048540e6f4648b3', 'Very quiet for half'),
('performance_listening_notes', 351, 'note_en', '6b43ed0f7bde24dbfec0a2984f98941881494c38ccc3add5c2023ad43b045f15', 'Starts the softest of the three and keeps almost half very quiet. So the contrast when it rises big is the greatest.'),
('performance_listening_notes', 351, 'facts_en', '6b43ed0f7bde24dbfec0a2984f98941881494c38ccc3add5c2023ad43b045f15', '["Chamber Orchestra of Europe"]'),
('performance_listening_notes', 352, 'headline_en', '8b4fcbac5aa33419bb4f5d867f8920b5f8cb35a7ce9732ece9f4090d7bbe2128', 'Building early, step by step'),
('performance_listening_notes', 352, 'note_en', '0674a5bec64d0bb3fadad4408bbf4eaac8d749416c5329d34a7e0cc343cf5358', 'Builds step by step from the opening and reaches nearly maximum earlier than the other two. Even after the climax it doesn''t drop as low as Abbado and Böhm.'),
('performance_listening_notes', 352, 'facts_en', '0674a5bec64d0bb3fadad4408bbf4eaac8d749416c5329d34a7e0cc343cf5358', '["Berlin Phil"]'),
('performance_listening_notes', 353, 'headline_en', 'fa2dc3e262c20553f95bfc5631c6fad82f36b1d4ddc832bf9582366f91bb9b31', 'Large drop after the climax'),
('performance_listening_notes', 353, 'note_en', 'b81dc7a4f5dac0624d2a82443c595d47a9254569ba11dd6808883d0fff2dbd89', 'After building big in the middle, it lets down deeply to the end. The climax comes about 5 seconds later than in the other two.'),
('performance_listening_notes', 353, 'facts_en', 'b81dc7a4f5dac0624d2a82443c595d47a9254569ba11dd6808883d0fff2dbd89', '["Berlin Phil"]'),
('performance_listening_notes', 354, 'headline_en', '6f58e0357a22edf5b40ac6095c52a7167cc70d999e971fe3dc0bff91e3e93c89', 'Climax at the very end'),
('performance_listening_notes', 354, 'note_en', 'd98c09efb92fb5c74fee402dcb74c4d0e5063b402ddbf120d2859f14a45f568e', 'Unlike the other two, it puts the loudest sound at the very end. After a soft passage, it rises in one move in the last 6 seconds.'),
('performance_listening_notes', 354, 'facts_en', 'd98c09efb92fb5c74fee402dcb74c4d0e5063b402ddbf120d2859f14a45f568e', '["Berlin Phil"]'),
('performance_listening_notes', 355, 'headline_en', '6d1586bf8605a65733939c58e0074720aa2ecb0ebe59d4ee8a14e7f6f96bb7a5', 'The slowest surprise'),
('performance_listening_notes', 355, 'note_en', '5d3b8ac364cccfaa7d35224e2813d9684c03f5fa40f69e133b1b7421bbf2f1af', 'At 1 min 43 sec, it is the slowest of the three. It begins the opening theme louder than the other two, and the surprise chord also comes the latest.'),
('performance_listening_notes', 355, 'facts_en', '5d3b8ac364cccfaa7d35224e2813d9684c03f5fa40f69e133b1b7421bbf2f1af', '["New York Phil"]'),
('performance_listening_notes', 356, 'headline_en', '1e09553176da2acea2936c39222bf9ef30675170297fcf9b4b630d39365d7a62', 'Deepest soft passage'),
('performance_listening_notes', 356, 'note_en', 'fb1d464ddabea4b59c4d759ce9160f1a6d32822bf3f73d68378213ed18fc9d07', 'After the climax in the middle, it sinks the soft passage the lowest of the three. It sets down the ending more softly than Karajan and Marriner.'),
('performance_listening_notes', 356, 'facts_en', 'fb1d464ddabea4b59c4d759ce9160f1a6d32822bf3f73d68378213ed18fc9d07', '["London Symphony"]'),
('performance_listening_notes', 357, 'headline_en', 'c6a21ac62bf8ecc39b7c4fd026ec647eaa84f3e915d1ef34245f2532fae1b114', 'Climax in under a minute'),
('performance_listening_notes', 357, 'note_en', '191a22a51e7c54d17f812c39e2273e377b4cf8085585834697cd0b6e86b9cc1e', 'Reaches the climax 13 seconds earlier than Abbado and more than a minute earlier than Karajan. The soft passages go down only shallowly.'),
('performance_listening_notes', 357, 'facts_en', '191a22a51e7c54d17f812c39e2273e377b4cf8085585834697cd0b6e86b9cc1e', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 358, 'headline_en', '9746509860e5babbe41b93ada649922e6a986c3f22af4cc308dc09262191e54e', 'Biggest ending'),
('performance_listening_notes', 358, 'note_en', '5f03a2213f8f6ebf764125dea155163071bec80c264d871cb4d2b993815217d1', 'Lays the opening theme as softly as Karajan does, and closes the final passage the loudest of the three.'),
('performance_listening_notes', 358, 'facts_en', '5f03a2213f8f6ebf764125dea155163071bec80c264d871cb4d2b993815217d1', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 359, 'headline_en', '0986e1a7873c761eb500c908479b5b13534e064dbfa795624bd8f9a6a07e1506', '20 seconds shorter'),
('performance_listening_notes', 359, 'note_en', 'f9b6451fee405e1f0671abb07ab99c80161992674e4e8ba21855d61ebdff0bc1', 'At 2 min 1 sec, it is about 20 seconds shorter than the other two. It puts the loudest sound past the very middle, later than Bell and Mutter.'),
('performance_listening_notes', 359, 'facts_en', 'f9b6451fee405e1f0671abb07ab99c80161992674e4e8ba21855d61ebdff0bc1', '["Wolff · Oslo Phil"]'),
('performance_listening_notes', 360, 'headline_en', '669ca5ddee46e85b0e81e161cad273ea3bce2552163775da58abc27986daccf0', 'Slowest, late climax'),
('performance_listening_notes', 360, 'note_en', 'aef58ab222f65941d5416f2246082ea1cc10a3dc5137dc3538f201426cab4943', 'At 2 min 21 sec, it is more than 15 seconds longer than the other two. Alone in playing loudest in the later part.'),
('performance_listening_notes', 360, 'facts_en', 'aef58ab222f65941d5416f2246082ea1cc10a3dc5137dc3538f201426cab4943', '["Davis · Vienna Phil"]'),
('performance_listening_notes', 361, 'headline_en', 'a310eb3f62e9911360a5ca901e5dd75551f7dd0b07b1cff6cd3323bd6fa846ec', 'Soft opening, early climax'),
('performance_listening_notes', 361, 'note_en', '3687ab5dd3b438127c2b4c8eeb6f8539e44408fe1a5ffb902820f1f6b779a454', 'Starts more softly than the other two and plays loudest early on. It keeps loud playing the shortest of the three.'),
('performance_listening_notes', 361, 'facts_en', '3687ab5dd3b438127c2b4c8eeb6f8539e44408fe1a5ffb902820f1f6b779a454', '["Abbado · Berlin Phil"]'),
('performance_listening_notes', 362, 'headline_en', 'ad33dfedd623902c7b871efaaf1672bfe327a6f56577683592ecbc5ef6072b24', 'Shortest, big early'),
('performance_listening_notes', 362, 'note_en', '0f64591168e17b9bf72ea7f87f08a37813cb1636a55efa99ed89a30567c859f7', 'At 1 min 24 sec, it is the shortest of the three. It starts building at about 20 seconds, rises big early, and sustains loud playing the longest.'),
('performance_listening_notes', 362, 'facts_en', '0f64591168e17b9bf72ea7f87f08a37813cb1636a55efa99ed89a30567c859f7', '["Tilson Thomas · London Symphony"]'),
('performance_listening_notes', 363, 'headline_en', 'bc1bd4b82f578a8912a796246aa2b98a567fdd6bd927f69b3770748b3f757b0d', 'Maximum from the first high point'),
('performance_listening_notes', 363, 'note_en', '4247fcacaed638dd83e6ec5d595a82d554dcb56a11f0171e1d0ad139f584d8cb', 'Rises to nearly maximum from the first high point and sustains loud playing for a long time. The ending also closes bigger than in the other two.'),
('performance_listening_notes', 363, 'facts_en', '4247fcacaed638dd83e6ec5d595a82d554dcb56a11f0171e1d0ad139f584d8cb', '["Marriner · St Martin"]'),
('performance_listening_notes', 364, 'headline_en', '448c192fecec9ca4d5811a649dbe8f1280289d34efa68906b0f3ee6769484b46', 'Big twice, front and back'),
('performance_listening_notes', 364, 'note_en', '3ce6583499c9612a877d90210a520bb281009edd4d63668f7fe1ae60bd39c808', 'Reaches nearly maximum 6 seconds earlier than Meyer and sustains loud playing for a long time. Near the end it rises big once more.'),
('performance_listening_notes', 364, 'facts_en', '3ce6583499c9612a877d90210a520bb281009edd4d63668f7fe1ae60bd39c808', '["Swedish Chamber Orchestra"]'),
('performance_listening_notes', 365, 'headline_en', '65e80f7ee9c37c460b3dd6cf9f11d5a1f9bc7d96daf2f21140969922b67750a2', 'One cut in the middle'),
('performance_listening_notes', 365, 'note_en', '75561c17586dc38fe71324604886b27d5afddac62ac9cf5ee3e9d6e5775f20e9', 'The first sound is louder than in the other two. After one big rise, it cuts back sharply in the middle, then rises again to play loudest.'),
('performance_listening_notes', 365, 'facts_en', '75561c17586dc38fe71324604886b27d5afddac62ac9cf5ee3e9d6e5775f20e9', '["Gergiev · Mariinsky"]'),
('performance_listening_notes', 366, 'headline_en', '5b0af86db6aea8e558512257f1fcef78aa27176d7cfe20e2d52a442fffa36e46', 'Softest first note'),
('performance_listening_notes', 366, 'note_en', '6bb559d3c9aa7d50c1ab34b6b86e65308fff3c4a867d05188ff14d520c45a7b2', 'Starts the softest of the three. The gap between soft and loud is also the largest, and it sinks deeply once more after the climax.'),
('performance_listening_notes', 366, 'facts_en', '6bb559d3c9aa7d50c1ab34b6b86e65308fff3c4a867d05188ff14d520c45a7b2', '["Karajan · Berlin Phil"]'),
('performance_listening_notes', 367, 'headline_en', '756a2b9db1d329a6b55c26ef303c46276d43aab0ebb0af6fc3d97bd0f340b6d1', 'Climax in the last seconds'),
('performance_listening_notes', 367, 'note_en', '92fdbbd9bcf15454608d578015e65ccfda366d48e9c979c867a66c53a4585cef', 'Keeps the first minute soft, and reaches nearly maximum only a few seconds before the end. Unlike Maisky, it saves its loud playing.'),
('performance_listening_notes', 367, 'facts_en', '92fdbbd9bcf15454608d578015e65ccfda366d48e9c979c867a66c53a4585cef', '["Nelsons · Boston Symphony"]'),
('performance_listening_notes', 368, 'headline_en', 'ae5a22a06a10955464b1e2fe7158ca2d8cbbf2b9b8c12a1b78225645ab283aa3', 'A loud first motif'),
('performance_listening_notes', 368, 'note_en', 'cef33d6436cd1a4fcdb53e7133835657dcde815cb65cee83333dce2524185e41', 'Brings out the first motif louder than the other two and reaches nearly maximum in 8 seconds. It also keeps loud playing going to the end.'),
('performance_listening_notes', 368, 'facts_en', 'cef33d6436cd1a4fcdb53e7133835657dcde815cb65cee83333dce2524185e41', '["New York Phil"]'),
('performance_listening_notes', 369, 'headline_en', 'e4caf43ded4e2224739c6b1b59e28a7eb5d39134fee5a85122823f659fe0ad65', 'Softest first motif'),
('performance_listening_notes', 369, 'note_en', 'f21cb1deca99183c3a250d2dc17fa6320c5a27b3e6e021c4a4b62180253ea1d7', 'Brings out the first motif the softest of the three. It puts the loudest sound in the middle, where Bernstein and Böhm put it at the end.'),
('performance_listening_notes', 369, 'facts_en', 'f21cb1deca99183c3a250d2dc17fa6320c5a27b3e6e021c4a4b62180253ea1d7', '["Berlin Phil"]'),
('performance_listening_notes', 370, 'headline_en', 'd80d7ca35c129703b6dcdaa90c90849096744239c7e275007ae20aa27c3600a9', 'A brisk 1 min 18 sec'),
('performance_listening_notes', 370, 'note_en', 'a82dce4805fd66f4106ce3af795cbd9a24cf86c46d01c52b0d52dc4e134d813d', 'At 1 min 18 sec, it is the shortest of the three. It keeps the volume nearly even, rising big just once before coming right back.'),
('performance_listening_notes', 370, 'facts_en', 'a82dce4805fd66f4106ce3af795cbd9a24cf86c46d01c52b0d52dc4e134d813d', '["Concertgebouw"]'),
('performance_listening_notes', 371, 'headline_en', 'a0249ba38773ad30dd9a6dc3fac6f7483af1a410589b5564d97107e22196c150', 'Big pull-back after the tutti'),
('performance_listening_notes', 371, 'note_en', 'dcb9e2101ef008aec44268072c2cd619690533b5191dae172ba2e16fc0a1e357', 'After the tutti it sinks the soft passage deeper than Bernstein and Karajan. It holds loud playing for a shorter time than the other two.'),
('performance_listening_notes', 371, 'facts_en', 'dcb9e2101ef008aec44268072c2cd619690533b5191dae172ba2e16fc0a1e357', '["Berlin Phil"]'),
('performance_listening_notes', 372, 'headline_en', '5d290aeeda6ab1623b7794261b08fd7318dbcb1800e9ed9b3fa8d1b8015fca9b', 'Slowest and softest'),
('performance_listening_notes', 372, 'note_en', 'b5082084068847e5a447bd14cdf38e5d32bd3575ce7338cb8ed1ea082ec7c426', 'At 1 min 41 sec, it is 23 seconds longer than Davis. It opens more softly than the other two, and sinks deeply once more before the climax.'),
('performance_listening_notes', 372, 'facts_en', 'b5082084068847e5a447bd14cdf38e5d32bd3575ce7338cb8ed1ea082ec7c426', '["New York Phil"]'),
('performance_listening_notes', 373, 'headline_en', '1705614150deb81ce51809da717cb7194ef041c4325ebb0e19785986a1d8ba9e', 'Thinning out by equal steps'),
('performance_listening_notes', 373, 'note_en', '9cf719fd65d68a468034137430addbc2ccb6e789393c22f768fcf364ad5f2ef3', 'The first sound is the loudest. From the beginning to the middle, and from the middle to the end, it thins out by almost the same amount.'),
('performance_listening_notes', 373, 'facts_en', '9cf719fd65d68a468034137430addbc2ccb6e789393c22f768fcf364ad5f2ef3', '["Capella Istropolitana"]'),
('performance_listening_notes', 374, 'headline_en', '38923a6678b42c48620d5920a2adbc4bf4eb28b773e301bd5986b463cb9226a7', 'Three small swells'),
('performance_listening_notes', 374, 'note_en', 'f3a9bc9d0616e9040cc30b51279e76d1bb7f5a5d24fe89e00a6949740893175e', 'Repeats small rises and falls three times, then rises big once. It sets the ending down more softly than the other two.'),
('performance_listening_notes', 374, 'facts_en', 'f3a9bc9d0616e9040cc30b51279e76d1bb7f5a5d24fe89e00a6949740893175e', '["Capella Istropolitana"]'),
('performance_listening_notes', 375, 'headline_en', '490a0b3ce3e5e02310f9b352c0e0369a7b89e4a8852db15edf07c56975a82862', 'Less thinning to the end'),
('performance_listening_notes', 375, 'note_en', '3335b94f34892e9876754c97b250e8d437c44443a03666f763cac2acb93e702b', 'It cuts back sharply once in the middle, but leaves the later part the loudest of the three. The last 10 seconds are also the least soft.'),
('performance_listening_notes', 375, 'facts_en', '3335b94f34892e9876754c97b250e8d437c44443a03666f763cac2acb93e702b', '["English Chamber Orchestra"]'),
('performance_listening_notes', 376, 'headline_en', '5377120600fa1c75146c24afc28c22a652e977fd3b6b8fd64c9b5f058b8af083', 'Builds for seconds, then the peak'),
('performance_listening_notes', 376, 'note_en', 'c1f68b944084c3c89d0017eb59446e73176cf6ff144afb6763d7985d602ba9b5', 'Unlike the other two, it rings loudest after building for a few seconds. In the later part, contrary to Barenboim, it thins out to a very soft level.'),
('performance_listening_notes', 376, 'facts_en', 'c1f68b944084c3c89d0017eb59446e73176cf6ff144afb6763d7985d602ba9b5', '["Academy of St Martin"]'),
('performance_listening_notes', 377, 'headline_en', '0914cdc7c9b87e1108329c52a83b3c066f07c715bb57bca1ae267b853651d7db', 'Deep sinking at the end'),
('performance_listening_notes', 377, 'note_en', 'b436f94deca118e0fc7f9b54783372c694c0bc2af0a49221ac2e4b195bcc9b0f', 'Moves 25 seconds faster than Bernstein, yet sinks the ending deeper than the other two. It rings loudest within the first 13 seconds.'),
('performance_listening_notes', 377, 'facts_en', 'b436f94deca118e0fc7f9b54783372c694c0bc2af0a49221ac2e4b195bcc9b0f', '["Berlin Phil"]'),
('performance_listening_notes', 378, 'headline_en', 'd798bc0e343a71a1c91d1b8ae5150a9a69c9eb89071dfa1d84dff2723d940043', 'The fastest introduction'),
('performance_listening_notes', 378, 'note_en', 'aa2df58df27c6f6e620b282d920b79e63a0c1b2caa00b8c0589ae8e0b31545e2', 'At 1 min 38 sec, it is the fastest of the three. It rings loudest within a few seconds of the first chord, and rebuilds the loud playing several times through the middle.'),
('performance_listening_notes', 378, 'facts_en', 'aa2df58df27c6f6e620b282d920b79e63a0c1b2caa00b8c0589ae8e0b31545e2', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 379, 'headline_en', '2f0ed52541bcd2993d3b11d815793563816a7318771dfd8d02365d26363143cd', 'A leap at the second high point'),
('performance_listening_notes', 379, 'note_en', '1c02a60b16a72e72986e44e45447b9a7475d39ea19a891d13c63ac425969e9bf', 'Keeps the first high point the lowest of the three, then rises to maximum in one move at the second.'),
('performance_listening_notes', 379, 'facts_en', '1c02a60b16a72e72986e44e45447b9a7475d39ea19a891d13c63ac425969e9bf', '["Berlin Phil"]'),
('performance_listening_notes', 380, 'headline_en', 'c8abae33358fff31365d5a936598273d92f02572df3c7969e82dfce6a6481be0', 'Builds again early'),
('performance_listening_notes', 380, 'note_en', 'fb9477f009de1c0abbb17926387edb6ad8041d60dbaf5b5e29cfcd5369debd1b', 'Sinks deeply right after the first chord. It builds again earlier than Fischer, holding the later passage a level higher.'),
('performance_listening_notes', 380, 'facts_en', 'fb9477f009de1c0abbb17926387edb6ad8041d60dbaf5b5e29cfcd5369debd1b', '["Vienna Phil"]'),
('performance_listening_notes', 381, 'headline_en', '726cf9d06ac41ee6e6e95632328082792ee6194a2b7c59f8d83271059e7dc4af', 'Shallow soft passages'),
('performance_listening_notes', 381, 'note_en', 'cc83048d8e064d862466a1a35d68c1ea75ff6ee5c63ba276dca148b10f8a06eb', 'Sinks the soft passage the most shallowly of the three. At the end it climbs back up to nearly the level of the first chord.'),
('performance_listening_notes', 381, 'facts_en', 'cc83048d8e064d862466a1a35d68c1ea75ff6ee5c63ba276dca148b10f8a06eb', '["New York Phil"]'),
('performance_listening_notes', 382, 'headline_en', '03b9520180012d596ae659e56d6188ce97841cfa40aa8589ec42cd7df23f1b1c', 'Deepest and longest'),
('performance_listening_notes', 382, 'note_en', 'b9df599b79de7f8f002fe2bd94330206969928a6913163f61c7ef45613880999', 'At 2 min 1 sec, it is more than 8 seconds longer than the other two. Unlike Bernstein, it holds the soft passage deep and long.'),
('performance_listening_notes', 382, 'facts_en', 'b9df599b79de7f8f002fe2bd94330206969928a6913163f61c7ef45613880999', '["Royal Concertgebouw"]'),
('performance_listening_notes', 383, 'headline_en', 'c875b68daa223fae7c16326ac035b0204dd495c7c8d1f0d53e572708d72606cb', 'A slow hymn, 2 min 26 sec'),
('performance_listening_notes', 383, 'note_en', '53dabcb76f5d8786fb387a92e99fc7aec32795147e1a8eeb14c29cef90acfbf3', 'Drags 48 seconds longer than Marriner. Loud playing occurs only in the first minute, and the later part stays soft throughout.'),
('performance_listening_notes', 383, 'facts_en', '53dabcb76f5d8786fb387a92e99fc7aec32795147e1a8eeb14c29cef90acfbf3', '["New York Phil"]'),
('performance_listening_notes', 384, 'headline_en', '36acbb1bb40546f014dfe8cb5771a9fe1952929ef51dde025f31fa322c2ec714', 'A few more seconds at the climax'),
('performance_listening_notes', 384, 'note_en', '3a16f484631e1c6ae342e5be56eb3f52eefeb151fa0c2abc0898e5aa4164c58b', 'The flow is almost the same as Karajan''s. It doesn''t let down right after the climax but keeps it big for a few more seconds.'),
('performance_listening_notes', 384, 'facts_en', '3a16f484631e1c6ae342e5be56eb3f52eefeb151fa0c2abc0898e5aa4164c58b', '["New York Phil"]'),
('performance_listening_notes', 385, 'headline_en', '89dce280614e2b6b24e288e679fa4264c19f1c27e66ba99d183d2deaa917e3c1', '2 min 14 sec, climax at the end'),
('performance_listening_notes', 385, 'note_en', '7c321be25e5bba167f484ad51c37687e0dda6224edb178c8abe271d0cf39e3d1', 'At 2 min 14 sec, it is 13 seconds longer than the other two. It holds back the early high point a level and puts the loudest sound at the end.'),
('performance_listening_notes', 385, 'facts_en', '7c321be25e5bba167f484ad51c37687e0dda6224edb178c8abe271d0cf39e3d1', '["Vienna Phil"]'),
('performance_listening_notes', 386, 'headline_en', '91d47efad3da093c100d28888e0102da5f6dc8c7a3bea81459d68dd6793e5b20', 'Maximum from the opening'),
('performance_listening_notes', 386, 'note_en', 'b8e1af853d94fd3c445905f501fb3b059b8c3946961bc29ce33f5d273d313de2', 'Enters at nearly maximum from the opening that the timpani begins. It sustains loud playing longer than the other two.'),
('performance_listening_notes', 386, 'facts_en', 'b8e1af853d94fd3c445905f501fb3b059b8c3946961bc29ce33f5d273d313de2', '["Alsop · Baltimore Symphony"]'),
('performance_listening_notes', 387, 'headline_en', 'fb6b41f5aa4b9f890fd94016aab269eb0fe8e59e3811d296fa84823e07d53a28', 'Softest after the climax'),
('performance_listening_notes', 387, 'note_en', '7b854654ed3051a7eb5500257d7b119ead011b2dc8f4a358477d325306a26fa6', 'Builds step by step and plays loudest only after more than a minute. After the climax it sinks the softest of the three and ends there.'),
('performance_listening_notes', 387, 'facts_en', '7b854654ed3051a7eb5500257d7b119ead011b2dc8f4a358477d325306a26fa6', '["de Billy · Vienna Radio Symphony"]'),
('performance_listening_notes', 388, 'headline_en', '868f5750fa84394905bb92bfeee17b67367f3e071e4200f95ab576d44b825c5e', '2 min 1 sec, maximum in last 10'),
('performance_listening_notes', 388, 'note_en', 'ba0ae94d395bd9d5e59eb2932af8a8c68496b80d00a94de58782318323625f46', 'At 2 min 1 sec, it is 10 to 13 seconds shorter than the other two. The flow is the same as Ashkenazy''s, rising to maximum all at once in the last 10 seconds.'),
('performance_listening_notes', 388, 'facts_en', 'ba0ae94d395bd9d5e59eb2932af8a8c68496b80d00a94de58782318323625f46', '["Abbado · Berlin Phil"]'),
('performance_listening_notes', 389, 'headline_en', 'c41294cc8b0e76e55c838aef565fe1fab432b318e66a93117d47ff64332ca9c8', 'Building evenly'),
('performance_listening_notes', 389, 'note_en', '4032ebcb3c5950e2c60c21efa9bee26b6ad70498abbf89b97dc6a1a38400282c', 'Unlike Mutter, it keeps the volume gap small and builds evenly. Its loud playing is shorter than the other two''s.'),
('performance_listening_notes', 389, 'facts_en', '4032ebcb3c5950e2c60c21efa9bee26b6ad70498abbf89b97dc6a1a38400282c', '["Barenboim · Berlin Phil"]'),
('performance_listening_notes', 390, 'headline_en', '5e3e718945bd7d589b75e5e67087edd75c91f7db9e7354833e71b7dfce8bc3f0', 'Softest clarinet'),
('performance_listening_notes', 390, 'note_en', '7f3d997650f0e00aae001efd195cafd16f1e307f8e6e905c3ab1b3eb5ecbe09f', 'Plays the clarinet introduction the softest of the three. The gap between soft and loud is the largest, and it reaches maximum only in the last 10 seconds.'),
('performance_listening_notes', 390, 'facts_en', '7f3d997650f0e00aae001efd195cafd16f1e307f8e6e905c3ab1b3eb5ecbe09f', '["Previn · London Symphony"]'),
('performance_listening_notes', 391, 'headline_en', '869558da3e4d2718576e365343779349a5a050afc49957cbcbd358d71e417fd3', 'Early maximum, to the end'),
('performance_listening_notes', 391, 'note_en', 'de397cde383f218e9643f929004c4c92bcbd9b3998c31f5453663c822d8cd242', 'Opens the introduction less softly and reaches nearly maximum earlier than the other two. It then drives on loudly to the end.'),
('performance_listening_notes', 391, 'facts_en', 'de397cde383f218e9643f929004c4c92bcbd9b3998c31f5453663c822d8cd242', '["Rattle · Berlin Phil"]'),
('performance_listening_notes', 392, 'headline_en', 'f6dd0dc798ad79fd0a9d67150f2663819e3cd04ef0f5afe41de48ea91d576eda', 'Built step by step'),
('performance_listening_notes', 392, 'note_en', 'da25ac3580f0fde3184c67746bdd7358ed73b0a8d02bbbd43a5f5b8438932bc0', 'The flow is almost the same as Rogé''s. It builds a level at a time to the climax, and closes the ending less softly than Rogé does.'),
('performance_listening_notes', 392, 'facts_en', 'da25ac3580f0fde3184c67746bdd7358ed73b0a8d02bbbd43a5f5b8438932bc0', '["Nézet-Séguin · Philadelphia"]'),
('performance_listening_notes', 393, 'headline_en', '697467c38a0fb81961e82dcf38ee9efed07377c1f9831159b113a8b48d7b2831', 'Soft timpani opening'),
('performance_listening_notes', 393, 'note_en', 'b0ee3dd5754dd8e2ff9e307c6fde019ff9b31ab767937469fa83c4c99625b27a', 'Opens the timpani''s first strokes the softest of the three. The gap between soft and loud is also the largest.'),
('performance_listening_notes', 393, 'facts_en', 'b0ee3dd5754dd8e2ff9e307c6fde019ff9b31ab767937469fa83c4c99625b27a', '["Karajan · Berlin Phil"]'),
('performance_listening_notes', 394, 'headline_en', '4e0d8efec22703000d01fccd715fdb289dbfda2de5c3ee7989fda5f8e5cd6d40', 'Shortest, loud opening'),
('performance_listening_notes', 394, 'note_en', '4a091dd86596f9623b0377da72d5afabb2ea75cb62772a563d1f984e5e7312ec', 'At 1 min 52 sec, it is 9 seconds shorter than Mutter. It opens the timpani''s first strokes loudly, the exact opposite of Mutter.'),
('performance_listening_notes', 394, 'facts_en', '4a091dd86596f9623b0377da72d5afabb2ea75cb62772a563d1f984e5e7312ec', '["Zinman · Baltimore Symphony"]'),
('performance_listening_notes', 395, 'headline_en', '9e42e291e8dea39c6bed75020f121a020774b1f3a0932ee87b6217caac51170a', 'Quick rise, quick letdown'),
('performance_listening_notes', 395, 'note_en', 'cfc0add985f9422a59aa0edf46a1b19a3b8872e0e4707ae15e9cc2d12c511a64', 'Reaches its climax the earliest of the three, then drops to its quietest right after, 9 seconds later. After that it repeatedly raises the volume big and lets it go.'),
('performance_listening_notes', 395, 'facts_en', 'cfc0add985f9422a59aa0edf46a1b19a3b8872e0e4707ae15e9cc2d12c511a64', '["Piano: Sunwook Kim"]'),
('performance_listening_notes', 396, 'headline_en', '033ea53dc1280a458858af64b145b56495679c464e457efec1c0c6f027d23afa', 'Even after the opening'),
('performance_listening_notes', 396, 'note_en', '5e06b339e23dbf8751b064ffa753cacd289dd78d59765f516079a3c6caf78096', 'The gap between soft and loud is narrower than Clara-Jumi Kang''s and Mutter''s. After the opening it moves evenly, with no big dips.'),
('performance_listening_notes', 396, 'facts_en', '5e06b339e23dbf8751b064ffa753cacd289dd78d59765f516079a3c6caf78096', '["Piano: Ashkenazy"]'),
('performance_listening_notes', 397, 'headline_en', '6018e661c06a402835b3a487ed807a7ca06327fa0c588835b2c344cb084a35f0', 'Sinks, then a leap to the climax'),
('performance_listening_notes', 397, 'note_en', '7fbd1ca7b0d4c83107fcea966a5a6d53d287643164b46425bc49bd472b0bf535', 'Opens more softly than Clara-Jumi Kang and Perlman, and places the climax later. It drops to its quietest 11 seconds before the climax, then pulls up in one move.'),
('performance_listening_notes', 397, 'facts_en', '7fbd1ca7b0d4c83107fcea966a5a6d53d287643164b46425bc49bd472b0bf535', '["Piano: Orkis"]'),
('performance_listening_notes', 398, 'headline_en', '24606413d0536c2599e0a5966213cf9c3fe529ea6d7e0fa7d20dcef8ca6528a8', 'Hammer blow, then straight to soft'),
('performance_listening_notes', 398, 'note_en', '5b301a310377ee251091ccbed5c25438d86149234beb94213dcd3a3820f6746c', 'At 1 min 52 sec, it is the shortest of the three. It strikes at maximum from the first chord, then right away sets down to its quietest.'),
('performance_listening_notes', 399, 'headline_en', 'dc15e5b21cafd3aa8dc50c39c1a958ce9af4117fe43ef3fdc5377fefa243c853', 'Maximum after the repeated strikes'),
('performance_listening_notes', 399, 'note_en', '1739c76b1d924cdd988a4efd87bdbe664e2d48a2de5935ec14e2cba950195438', 'Alone in holding back the first chord, rising to maximum only after the repeated strikes. It builds bit by bit toward the end.'),
('performance_listening_notes', 400, 'headline_en', '85f44b6823cee13ddba91926ca275db6963f6d72cc4d468ec93948a60f7e3b66', 'Loudest in the final section'),
('performance_listening_notes', 400, 'note_en', '075a07753a5c573d75adf6486d1942f25b1a8463b7613213b88d966e9902a953', 'Starts more softly than the other two and grows without any big sinking. It saves the loudest sound for the final section.'),
('performance_listening_notes', 401, 'headline_en', '22ce19b1a2fa4772fc51ac81e133036ec26647ffe2393f3261cb7807dc57db36', 'Loud even in the soft theme'),
('performance_listening_notes', 401, 'note_en', '0abe98c71a26481b786291453d4fb9dd4e5f94371c8f9c63975d52ae7b4e7a5a', 'Enters the loudest of the three. Even when returning to the soft theme, it doesn''t come down as far as Perahia does.'),
('performance_listening_notes', 402, 'headline_en', '7bffafac90ffa8c3fdd973a5efa41645d3385ea2b96fbd2f63fbd387b15a2789', 'Quietest point near the end'),
('performance_listening_notes', 402, 'note_en', '1dabcd850c508e817c091af051b4538c2a74c624cf754877b6766993c1ec3f50', 'Like Ashkenazy, it strikes at maximum from the first chord. Alone in placing the quietest sound near the end.'),
('performance_listening_notes', 403, 'headline_en', 'db6fc6e49e7413dc78f3e3797f97133c9431efeed8d19df7ce93b87ef6944856', 'March and theme clearly separated'),
('performance_listening_notes', 403, 'note_en', 'a366f8bcf5ea69a654a36d1b6588cbddf5ba62ef39aaf815ba345fc59ca4e70a', 'Plays loudest in the march section that appears first. Each time it returns to the theme it comes down deeply, separating it clearly from the march.'),
('performance_listening_notes', 404, 'headline_en', 'dc2e6a501409f879e8e294ffaee9cac8f67c5fa983b5a9f36fb07cc746e2ddcf', '2 min 17 sec, loud later'),
('performance_listening_notes', 404, 'note_en', 'd5955e5cf72756b9aef76d726920260a36d2cb8561cf7b40011564ea5da988ab', 'At 2 min 17 sec, it is 25 seconds longer than the Takács Quartet. It keeps the volume gap small and puts the loudest sound in the later part.'),
('performance_listening_notes', 406, 'headline_en', 'af43f9d70ca8074527cf29a53454c142a68c818707ba919408e31af6a1ce2a9b', 'The shortest of the three'),
('performance_listening_notes', 406, 'note_en', '68a53bc3bc270aadd0206c4bde72ae372971295cc8afa9b2b33a8841bbf5ef32', 'At 1 min 52 sec, it is the shortest of the three. It plays the two big rises at almost the same level.'),
('performance_listening_notes', 407, 'headline_en', '267fe083e4e737df2795e80a55f6611e3bc4d11ab4c8b2efa6c6a3120f0a8f95', 'Big only near the end'),
('performance_listening_notes', 407, 'note_en', '4269867b4825b9152d7b789d0e3b67f131fd7e2b11c43509e095abbf56b47ab6', 'Moves evenly with no big rises and falls, rising big only briefly near the end. Its loud playing is the shortest of the three.'),
('performance_listening_notes', 407, 'facts_en', '4269867b4825b9152d7b789d0e3b67f131fd7e2b11c43509e095abbf56b47ab6', '["Amadeus Quartet"]'),
('performance_listening_notes', 408, 'headline_en', 'ab222f1e5db19bf773f2baa16830cc7e5ca73abd7721c14af34989c66544ee9a', 'Soft to maximum in 12 seconds'),
('performance_listening_notes', 408, 'note_en', 'da6e21df9f30ddc6cfca6da3aaab76883c448e5e3a58b7921e87d5d748a54fb2', 'Softer than the other two from the first note. It rises from its quietest point to maximum in 12 seconds, so the volume gap is also larger.'),
('performance_listening_notes', 410, 'headline_en', 'cd8aa9456f639177945c1b8ad13b643e2f3c0177940b9a9a4e39f97a26ebb7b0', 'Earliest to rise'),
('performance_listening_notes', 410, 'note_en', '6f88b7385ac3bbf06a03ddd6de5ec5b1c75b0e3f02dc7cd405291ae3988da5f8', 'Rises big earlier than the other two, and holds that level until near the end.'),
('performance_listening_notes', 411, 'headline_en', '35e178d7560b530bb6b6dd0c65a844a86721cb9c366f745d1f492d8c0d09d95e', 'Sinks, then biggest at the end'),
('performance_listening_notes', 411, 'note_en', 'a7d282678e2752d528aa80d0997300f1c7c4be018d150fe42c8e60519d31e02c', 'Starts more softly than the other two. It sinks deeply once in the middle, then rises to its loudest at the end.'),
('performance_listening_notes', 413, 'headline_en', 'c0e102ef835875edd1cc40ef5c2b1431e087f8bc69f9fe70b077646856c6b4ce', 'A deep breath before the end'),
('performance_listening_notes', 413, 'note_en', '9b6007628701f9f751dc97191f6a40924d43e80342c066b2c984d0fcf1a695a6', 'Carries the middle a level lower, and sinks deeper than the other two before the end. From there it rises again to the climax.'),
('performance_listening_notes', 413, 'facts_en', '9b6007628701f9f751dc97191f6a40924d43e80342c066b2c984d0fcf1a695a6', '["Boston Symphony"]'),
('performance_listening_notes', 414, 'headline_en', '8bf96428e6ea4d17b88a68176a91c8f45f51be4e54fe6c5a8b4f89df67bc104a', 'The most even volume'),
('performance_listening_notes', 414, 'note_en', 'e23d9be960f7092ec8e2c1af61fb41a2417c205180dacdf4824a1419d307202c', 'The first sound is the loudest of the three, and the volume gap is the smallest. Only near the end does it reach nearly maximum for the first time.'),
('performance_listening_notes', 414, 'facts_en', 'e23d9be960f7092ec8e2c1af61fb41a2417c205180dacdf4824a1419d307202c', '["Gewandhaus"]'),
('performance_listening_notes', 415, 'headline_en', '95511b16eaec41c90b0e79d75b3b5cac9115682f2d9c42bd134a12dd891c0bc4', 'Early build, long hold'),
('performance_listening_notes', 415, 'note_en', '23436182020ff380956ca0088cf3dcaeb07ca98f6b478ec095bac32fc2fa3abc', 'Starts less softly than Karajan and builds early. It reaches nearly maximum in a minute and sustains loud playing for a long time.'),
('performance_listening_notes', 415, 'facts_en', '23436182020ff380956ca0088cf3dcaeb07ca98f6b478ec095bac32fc2fa3abc', '["Concertgebouw"]'),
('performance_listening_notes', 416, 'headline_en', 'f7064fa460feb3792c619a3fe0ccf9033e0216252c5238900a3a3e260533a1cd', 'Building up the opening'),
('performance_listening_notes', 416, 'note_en', '7a4fc1d5375ffa07d921e877e94786973a94d37a8bca5156878f1f026f7d1d34', 'It builds the opening for over 30 seconds until it reaches near maximum. It then drops back to a soft level and rises again to its loudest at the end.'),
('performance_listening_notes', 416, 'facts_en', '7a4fc1d5375ffa07d921e877e94786973a94d37a8bca5156878f1f026f7d1d34', '["Berlin Phil"]'),
('performance_listening_notes', 417, 'headline_en', 'c2b6a42e98533be9a59af5d57e7baaf6a43fe1df2be0b5197554af9bad75d619', 'The most hushed opening'),
('performance_listening_notes', 417, 'note_en', '0de98c8f4e7da126adda2e24d692199492e389394659f9e76b06118c20691400', 'Starts the softest of the three. Loud playing comes only briefly, around the climax.'),
('performance_listening_notes', 417, 'facts_en', '0de98c8f4e7da126adda2e24d692199492e389394659f9e76b06118c20691400', '["Berlin Phil"]'),
('performance_listening_notes', 418, 'headline_en', '5d11535b6aeee75119f9d226d2d910badf469f294d92706b00312057d0f56151', 'Loudest in the opening section'),
('performance_listening_notes', 418, 'note_en', 'da5ecd42298e99cfa889f6de462ebf63220b1764c8d36da2626d02af0fc28742', 'Hits its loudest in the opening section, then drops back the furthest of the three. It rises again at the end, but not as high as at the start.'),
('performance_listening_notes', 418, 'facts_en', 'da5ecd42298e99cfa889f6de462ebf63220b1764c8d36da2626d02af0fc28742', '["Berlin Phil"]'),
('performance_listening_notes', 419, 'headline_en', '289bfa9f6a6e30a6c5b94a5755678a2bcb9f0b7047557f60eb2f8e38d4a53496', 'A less hushed ending'),
('performance_listening_notes', 419, 'note_en', '3fb53400f5a09d03141e4df29eebf1da020196f7bf6e336c7c196205ed15221b', 'The shape is almost the same as Karajan''s. It eases down to a less hushed ending than the other two.'),
('performance_listening_notes', 419, 'facts_en', '3fb53400f5a09d03141e4df29eebf1da020196f7bf6e336c7c196205ed15221b', '["Vienna Phil"]'),
('performance_listening_notes', 420, 'headline_en', '0b31a03d908455cba75237543327f24969b5d4dee1dd59349a010a88ab78a51e', 'Near maximum from the first sound'),
('performance_listening_notes', 420, 'note_en', '717c90fb0d1981447bb6d21c2ace88c964c5997cae7228a66be568232c05232a', 'At 1:53, it runs nearly 10 seconds shorter than the other two. It enters at near maximum from the first sound and rises to its loudest again at the end.'),
('performance_listening_notes', 420, 'facts_en', '717c90fb0d1981447bb6d21c2ace88c964c5997cae7228a66be568232c05232a', '["Royal Concertgebouw"]'),
('performance_listening_notes', 421, 'headline_en', '4a3b7fa9372be8acd31c602765136c57c9478fe08163483723d25fa29e044748', 'Louder sooner in the middle'),
('performance_listening_notes', 421, 'note_en', '4d63dc4559fa3d856f3bca7d14326393f4a7bc209c2a797f967e5c1db8c08a1b', 'It starts softly but reaches near maximum about 50 seconds earlier than the other two. It also sustains loud playing longer than Haitink and Chailly.'),
('performance_listening_notes', 421, 'facts_en', '4d63dc4559fa3d856f3bca7d14326393f4a7bc209c2a797f967e5c1db8c08a1b', '["Berlin Phil"]'),
('performance_listening_notes', 422, 'headline_en', 'c305a71536217527d848fbf7ece36da9adb648fce6e9554184a4a24123116fbc', 'Near maximum in under a minute'),
('performance_listening_notes', 422, 'note_en', 'fa806523bf4ea6f59d9168b7139c722baf7330ef09a1fcc48a38bac5429d3b45', 'Reaches near maximum in under a minute. Just before the climax it drops to its smallest level, then climbs again.'),
('performance_listening_notes', 422, 'facts_en', 'fa806523bf4ea6f59d9168b7139c722baf7330ef09a1fcc48a38bac5429d3b45', '["Michael Barenboim · Soltani"]'),
('performance_listening_notes', 423, 'headline_en', '338bec5fd62463f220a99916bf1b81e3444cc0e5ab0479cadbb4f0a674f1ca38', 'Two crests kept low, maximum at the end'),
('performance_listening_notes', 423, 'note_en', '939b68f7393bd6659f70c7ee36e1fd6ed6fefe40bdcc5b5a2a0df32ceffa2bbc', 'The two early crests are set evenly one step lower. It first reaches near maximum only close to the end.'),
('performance_listening_notes', 423, 'facts_en', '939b68f7393bd6659f70c7ee36e1fd6ed6fefe40bdcc5b5a2a0df32ceffa2bbc', '["Mullova · Schiff"]'),
('performance_listening_notes', 424, 'headline_en', '5b21a2e65620b761dacfd7150538db81a0a3ec3e8ce29ad514e6ddf78907c632', 'Easing far down before the end'),
('performance_listening_notes', 424, 'note_en', 'aa7c6f3f05fd796788388820441546d704d4d29c9d91e14df497826cd1fec12e', 'Rises sharply once, about 10 seconds in. After the climax, just before the end, it settles lower than any of the others.'),
('performance_listening_notes', 424, 'facts_en', 'aa7c6f3f05fd796788388820441546d704d4d29c9d91e14df497826cd1fec12e', '["Capuçon brothers"]'),
('performance_listening_notes', 425, 'headline_en', '0a8c603ac1eaf2bbd770178a54885158de53c85777fc65aa7c51c9500cf52f88', 'The lowest start'),
('performance_listening_notes', 425, 'note_en', 'c9d944d8be5a0e884191d2cfe07ed7db8298b5052bb8cd06a6947ed79a6c0298', 'The first sound is the softest of the three. A few seconds in, it sits at its smallest level, then steps up gradually as it goes on.'),
('performance_listening_notes', 425, 'facts_en', 'c9d944d8be5a0e884191d2cfe07ed7db8298b5052bb8cd06a6947ed79a6c0298', '["Perlman · Harrell"]'),
('performance_listening_notes', 426, 'headline_en', 'b239c70bc41eee43b5bf378f90e156b59c7775a08c97b321f1ecfa4dd2477dfc', 'Maximum from the first chord'),
('performance_listening_notes', 426, 'note_en', 'af313d0ac95507a41e7fd69fab5a964333d7118a2f1f0423a4e8f5826b50ae9c', 'Enters at maximum right from the first chord. The second theme is also pulled back less than in the other two, and it rises again at the end.'),
('performance_listening_notes', 426, 'facts_en', 'af313d0ac95507a41e7fd69fab5a964333d7118a2f1f0423a4e8f5826b50ae9c', '["Emerson Quartet"]'),
('performance_listening_notes', 427, 'headline_en', 'ca1ffb29c33d960ccbb1a591bba17298bb75d1136a2f6803215bf591cc89e3c4', 'The softest cello'),
('performance_listening_notes', 427, 'note_en', 'c8a55be47ec7e1005136d19f462ba4b7546906cba5b075e4ebfb0ef5969c94f1', 'At 2:01, the longest of the three. It opens the cello''s first song the softest, then pulls well back once before building.'),
('performance_listening_notes', 427, 'facts_en', 'c8a55be47ec7e1005136d19f462ba4b7546906cba5b075e4ebfb0ef5969c94f1', '["Bell · Isserlis"]'),
('performance_listening_notes', 428, 'headline_en', '8e7b095eaa8ba8278f6e63c66c882a9b2c46d74ecbb9f6c507600bf6a4ecfe85', 'The deepest dip for the second theme'),
('performance_listening_notes', 428, 'note_en', '9d79fc7acfe56fb5ababb87d5ce1aa6caeb559263542e080063b8fbd51869170', 'The second theme is pulled back the furthest and for the longest of the three. The final third is the softest of the three.'),
('performance_listening_notes', 429, 'headline_en', 'b94c867e6fd319ba6b08fe4131f8a05207d846e5f29cb9dc83ce291cca04f252', 'Near maximum in 20 seconds'),
('performance_listening_notes', 429, 'note_en', '84f1149e17adf739aa6f88e83fb1307510e9a13b4a9eb4dc70b7fb249c9d8a99', 'Reaches near maximum in 20 seconds. After that it pushes on evenly, without swinging much in loudness.'),
('performance_listening_notes', 429, 'facts_en', '84f1149e17adf739aa6f88e83fb1307510e9a13b4a9eb4dc70b7fb249c9d8a99', '["Mutter · Harrell"]'),
('performance_listening_notes', 430, 'headline_en', 'b49ddbc2fea780874049c647ecea3ab167c4b2298bd608edd2ddb333e239c705', 'Loud again at the end'),
('performance_listening_notes', 430, 'note_en', 'a214e326318578054b82ca44dea4fbd3fd0bb5aa8cb84602484da1c145cdd6f6', 'The shape is almost the same as Pressler''s. It pulls back once more for the second theme, then rises loudly again at the end.'),
('performance_listening_notes', 431, 'headline_en', 'a73b9a14f82e55742fe9856f2a9614f60c5bccf7cb3d684231df5ee67f3dae1e', 'Sinking almost to silence'),
('performance_listening_notes', 431, 'note_en', '20494fb5103b0640aa0b6f2c32f411a1a446766f0da2676ce8b02c3fd97e0825', 'The quiet passage in the middle is pulled back the furthest of the three, almost to silence. It runs 18 seconds longer than Karajan.'),
('performance_listening_notes', 431, 'facts_en', '20494fb5103b0640aa0b6f2c32f411a1a446766f0da2676ce8b02c3fd97e0825', '["Vienna Phil"]'),
('performance_listening_notes', 432, 'headline_en', 'f2e59d11f75e2f62ec8ef3cb2965ce60d02aec9718ad735cb8d9b037f83b096e', 'Maximum from the first beat'),
('performance_listening_notes', 432, 'note_en', 'd70b7bee660ac2a3bc84d46127f733512895027b5644410e11f174800cef77c7', 'Enters at near maximum from the first theme. It reaches the climax earliest of the three and sustains loud playing the longest.'),
('performance_listening_notes', 432, 'facts_en', 'd70b7bee660ac2a3bc84d46127f733512895027b5644410e11f174800cef77c7', '["Vienna Phil"]'),
('performance_listening_notes', 433, 'headline_en', '74e2d098e52bc6f91d113a73e0f5a89d4968a186d2ee3ce451af9bb7c14630ae', 'Loud all the way past the climax'),
('performance_listening_notes', 433, 'note_en', '4e51e4a296b6de33b354ab64a1040cb9c355b5df202d3351b9ed1673c1f3cf49', 'Nine seconds shorter than Previn. From the climax to the end, it holds loud playing the longest of the three.'),
('performance_listening_notes', 433, 'facts_en', '4e51e4a296b6de33b354ab64a1040cb9c355b5df202d3351b9ed1673c1f3cf49', '["Berlin Phil"]'),
('performance_listening_notes', 434, 'headline_en', '7958fef77920f707096f382163bde6889f6e60f2a2342df6cab0debef5c13cb0', 'Shortest and shallowest'),
('performance_listening_notes', 434, 'note_en', '893dd179350b6c0b5b2cebf8fd2ebeda099699df3d3eb828dc92f67b8e94ba99', 'At 2:01, it is 27 seconds shorter than Haitink. It eases down only slightly in the middle, then climbs back to near maximum.'),
('performance_listening_notes', 434, 'facts_en', '893dd179350b6c0b5b2cebf8fd2ebeda099699df3d3eb828dc92f67b8e94ba99', '["Berlin Phil"]'),
('performance_listening_notes', 435, 'headline_en', '60f80cf164edeff6d9a727bd3c707047e5012007e33b10597398f156c99b120e', 'A 2:28 lament'),
('performance_listening_notes', 435, 'note_en', 'bbeb0b157e54595709e2c04f09c9a8f5d542fbf6ca22cc583685714e37276de7', 'At 2:28, it runs longer than the other two. Loud playing is brief, and it ends the softest of the three.'),
('performance_listening_notes', 435, 'facts_en', 'bbeb0b157e54595709e2c04f09c9a8f5d542fbf6ca22cc583685714e37276de7', '["Concertgebouw"]'),
('performance_listening_notes', 436, 'headline_en', 'f76815b715e0abe1f2885f11f557be5196568a17f6913b2a70601ede555b5167', 'Maximum on the second peak'),
('performance_listening_notes', 436, 'note_en', 'd54aa0c50fa99c6ca01d6282e155a6705b84cc00875136c5b0c2b4940c5f9a24', 'It does not reach maximum in the first theme and gets to near maximum later than the other two. The ending is the softest too.'),
('performance_listening_notes', 436, 'facts_en', 'd54aa0c50fa99c6ca01d6282e155a6705b84cc00875136c5b0c2b4940c5f9a24', '["Chicago Symphony"]'),
('performance_listening_notes', 437, 'headline_en', '91c2042cbf374bdb8b1c433d7293dea33f6663f865b0a01e9b899b7277eddd9f', 'Near maximum before the one-minute mark'),
('performance_listening_notes', 437, 'note_en', '4e026d904a6b7f15f227443ff2e5ef603bcf651d37765ff891f0d9a9a2e80ea8', 'It runs 9 seconds longer than Karajan. It reaches near maximum more than 10 seconds before the other two, and its dynamic range is slightly narrower.'),
('performance_listening_notes', 437, 'facts_en', '4e026d904a6b7f15f227443ff2e5ef603bcf651d37765ff891f0d9a9a2e80ea8', '["Royal Phil"]'),
('performance_listening_notes', 438, 'headline_en', '9dda302df77b8e376fabf3690ddc6a5fe456660ff8615071dfe8a298d6bd3045', 'A shape like Previn''s'),
('performance_listening_notes', 438, 'note_en', 'c5e9411b79791687b6e8f84c986bdce22e9ffc59eb8cf428956023d16e0cd6e4', 'The shape is almost the same as Previn''s. But it reaches near maximum last of all, only 10 seconds before the climax.'),
('performance_listening_notes', 438, 'facts_en', 'c5e9411b79791687b6e8f84c986bdce22e9ffc59eb8cf428956023d16e0cd6e4', '["Berlin Phil"]'),
('performance_listening_notes', 439, 'headline_en', 'f673ad6d093eb4aec18422889fa4d53913cd71c4a4c7fc70a516e7b238be2fab', 'The most unhurried pace'),
('performance_listening_notes', 439, 'note_en', 'acd63730b0d38563533b8aac2dcd026fde743ffd650743684292b907eae562e3', 'At 2:01, it runs about 20 seconds longer than the other two. It reaches near maximum once early on and places the climax right in the middle.'),
('performance_listening_notes', 439, 'facts_en', 'acd63730b0d38563533b8aac2dcd026fde743ffd650743684292b907eae562e3', '["Concertgebouw"]'),
('performance_listening_notes', 440, 'headline_en', '8af716356206e9ba702cb85289c555bed5cd93e46a723d4d53581bb98d19a4f0', 'Longest, with a soft close'),
('performance_listening_notes', 440, 'note_en', '4888cd5e178ef05acea00fba424a2923d4e787603c34107584c754a279a156b2', 'At 5:24, it runs roughly a minute longer than the other two. It starts the softest of the three and ends the softest.'),
('performance_listening_notes', 440, 'facts_en', '4888cd5e178ef05acea00fba424a2923d4e787603c34107584c754a279a156b2', '["Bavarian Radio Symphony"]'),
('performance_listening_notes', 441, 'headline_en', 'b9c4f9336ddf35b0f3b5c2a666a2b029ea8edb38d6f329e317ff619c3bb8a422', 'Latest climax, soft ending'),
('performance_listening_notes', 441, 'note_en', 'f75b60790d03b5ca3b78d40b76d2f7e5ba1e602d57ae4b0cb44348c85ed9943b', 'The loudest moment comes later than in the other two. It also ends the softest.'),
('performance_listening_notes', 441, 'facts_en', 'f75b60790d03b5ca3b78d40b76d2f7e5ba1e602d57ae4b0cb44348c85ed9943b', '["Martineau (accompanist)"]'),
('performance_listening_notes', 442, 'headline_en', '79cb0269ecdd9c96e4d5f5d9428200df7d5d78cb00ed3077aaffd0b3ab5b1ddf', 'Opening big, closing big'),
('performance_listening_notes', 442, 'note_en', '0763c368247e087d98586877173be5f6a5207591357d0fc445e608b65d6360cd', 'Unlike Davis, it starts loud and its ending is less soft. It builds earliest, and its range between quiet and loud is the smallest.'),
('performance_listening_notes', 443, 'headline_en', 'f7d11aab205441c1d6576f35cb1d7cda41358172dbe822f44bd720c384a75693', 'Arriving early, ending loud'),
('performance_listening_notes', 443, 'note_en', 'a29129cf25f1799024e613af70a692c4d87809738c14a14a6fa53842f42e10f0', 'Reaches near maximum before Goerne and Terfel. It also doesn''t taper to as soft an ending as the other two.'),
('performance_listening_notes', 443, 'facts_en', 'a29129cf25f1799024e613af70a692c4d87809738c14a14a6fa53842f42e10f0', '["Moore (accompanist)"]'),
('performance_listening_notes', 446, 'headline_en', '37894c2733899c13029aa58912d18037270da729114b9b5d0967c9bec72116e7', 'Held back, then peaking in seconds'),
('performance_listening_notes', 446, 'note_en', '43d6a7e39d8509a3c6698aebe7360366a484eebcd763291c4a0acdad16483cff', 'The first sound is the softest of the three, and loud playing lasts the shortest time. Late on, it climbs to its loudest within a few seconds.'),
('performance_listening_notes', 446, 'facts_en', '43d6a7e39d8509a3c6698aebe7360366a484eebcd763291c4a0acdad16483cff', '["Haefliger (accompanist)"]'),
('performance_listening_notes', 447, 'headline_en', '67d458e606f693ebc25170ffc0c7d5a06eb14975bf71dbac2ffd08f2532c2b36', 'Soft entry, early build'),
('performance_listening_notes', 447, 'note_en', '0452aafdff346443b059c4b9c16efb2e1e03d6aa4aa96b59f3a51d53bedb766a', 'Like Davis, it enters softly, but it starts building about 30 seconds earlier. It drops back in the middle, then rises again on the opening melody.'),
('performance_listening_notes', 447, 'facts_en', '0452aafdff346443b059c4b9c16efb2e1e03d6aa4aa96b59f3a51d53bedb766a', '["Bayreuth Festival Orchestra"]'),
('performance_listening_notes', 449, 'headline_en', '0bf622c8acab15a2b584c90a75a095118c0fcecf159e2b91469a77088ceede11', 'Loud from the first 10 seconds'),
('performance_listening_notes', 449, 'note_en', '7138e5f7f8d7de52ef74cd51535157533457a7eb9fb47e5f86fcf9370654527b', 'It is already quite loud in the first 10 seconds, and the climax comes earliest of the three. After the climax it eases down the most.'),
('performance_listening_notes', 449, 'facts_en', '7138e5f7f8d7de52ef74cd51535157533457a7eb9fb47e5f86fcf9370654527b', '["Concertgebouw"]'),
('performance_listening_notes', 450, 'headline_en', '67d3297f7e615eb0dc483367216dd6b720f0e4b61bdef557c645dd60f36b615e', '2:12, with a single maximum'),
('performance_listening_notes', 450, 'note_en', '3e1d7208b25d2f769d3902ee40121129de296550551b37e0ed69caac8dc5c6c3', 'At 2:12, it is the longest of the three. It drops to its smallest level midway, then reaches maximum just once, at the end.'),
('performance_listening_notes', 450, 'facts_en', '3e1d7208b25d2f769d3902ee40121129de296550551b37e0ed69caac8dc5c6c3', '["Concertgebouw"]'),
('performance_listening_notes', 451, 'headline_en', 'f57f9763ad6e7b0a85800f638c165f85f4738ae4b7e2437dd52aa346fb886c2a', 'Even, with small contrasts'),
('performance_listening_notes', 451, 'note_en', 'a1b0d7ec7a4cf3f0ac8fe27b70f63b53c4076b9d7d07d0bd14db8e55470c71ff', 'It opens the snare drum introduction less softly than Bernstein and Karajan. The gap between its quiet and loud passages is also the smallest of the three.'),
('performance_listening_notes', 451, 'facts_en', 'a1b0d7ec7a4cf3f0ac8fe27b70f63b53c4076b9d7d07d0bd14db8e55470c71ff', '["LA Phil"]'),
('performance_listening_notes', 452, 'headline_en', 'f610524b37f5a905262f4d7229f9ab4633354ef62894311433d5b01a50fac79b', 'The smallest opening'),
('performance_listening_notes', 452, 'note_en', '1d2cc67b1e299940447821aef40c50c2196622a3e293d4d91b09bf26cbddefe5', 'The opening snare drum is kept at its smallest. After the climax it steps down a level and closes softer than Dudamel and Karajan.'),
('performance_listening_notes', 452, 'facts_en', '1d2cc67b1e299940447821aef40c50c2196622a3e293d4d91b09bf26cbddefe5', '["New York Phil"]'),
('performance_listening_notes', 453, 'headline_en', '6710ba71c85ffbea9294f6b247b34611b04285a984d03dceea6dca399ae3b408', 'Saved to the end, then all at once'),
('performance_listening_notes', 453, 'note_en', '9075cbca503ac5bf79934ac9bb3da1fd5e668a0c7005711345476f0257165d16', 'Starts softly and keeps the middle lower than the other two. It starts to grow 15 seconds later than Ozawa, then rises to maximum in 8 seconds.'),
('performance_listening_notes', 453, 'facts_en', '9075cbca503ac5bf79934ac9bb3da1fd5e668a0c7005711345476f0257165d16', '["Montreal Symphony"]'),
('performance_listening_notes', 454, 'headline_en', 'a3d52e86c5d60b51e0ad3dd91810480e44d45a4350e8b9ba81b569468ac1d55b', 'Early maximum up front'),
('performance_listening_notes', 454, 'note_en', 'ef30367a75e199d3bdd86bc44f1393499a1f2cf134f640f270c904da6a521542', 'At 1:44, it is 28 seconds shorter than Haitink. It lifts to near maximum early, eases back down, then pushes up again at the end.'),
('performance_listening_notes', 454, 'facts_en', 'ef30367a75e199d3bdd86bc44f1393499a1f2cf134f640f270c904da6a521542', '["Vienna Phil"]'),
('performance_listening_notes', 455, 'headline_en', 'a0482531e525f6caf4ebce15905e984c950cc889976676cc783d507446f52c33', 'The earliest build'),
('performance_listening_notes', 455, 'note_en', '6b1e13e120c84a426ec61f0f95c7a7f31ca23f58ac1b2bc2c33c657423c65ee8', 'The first sound is less soft than in the other two, and it begins to grow sooner. It also lets the level fall less at the end.'),
('performance_listening_notes', 455, 'facts_en', '6b1e13e120c84a426ec61f0f95c7a7f31ca23f58ac1b2bc2c33c657423c65ee8', '["Boston Symphony"]'),
('performance_listening_notes', 456, 'headline_en', 'b841d920d3041aa7f7e20068df3b8fed1c8e98490f0bff69f0a62f89c693a511', 'Pulling back, maximum at the end'),
('performance_listening_notes', 456, 'note_en', '6edb56681f713f66a87c23d90def1b9a3d843923325363b01b4788d2fbb3d7d8', 'The first sound is softer than in the other two. It pulls back once before the climax, then rises, and it closes louder than the other two.'),
('performance_listening_notes', 456, 'facts_en', '6edb56681f713f66a87c23d90def1b9a3d843923325363b01b4788d2fbb3d7d8', '["Berlin Phil"]'),
('performance_listening_notes', 457, 'headline_en', '5119cf0ae1edc6c3b93976520c4ec5875fdf4610a344e155ad2d3a2f8ff60941', 'Still loud after the climax'),
('performance_listening_notes', 457, 'note_en', '1cd10d4b73a412e76809ed643dfc9f7f1592e18bfb4411a4ab7f81a6ae6d6a64', 'After the climax it stays at nearly that level to the end. It holds loud playing for more than twice as long as the other two.'),
('performance_listening_notes', 457, 'facts_en', '1cd10d4b73a412e76809ed643dfc9f7f1592e18bfb4411a4ab7f81a6ae6d6a64', '["Berlin Phil"]'),
('performance_listening_notes', 458, 'headline_en', '67d7bb5138e73eeec1ca4fd7e4241a9524219f1ad7500561cf2278b7d13cad95', 'One step at a time to the end'),
('performance_listening_notes', 458, 'note_en', '6dab612f79a3358deb51f3fe03a6729c7677add3dfd43f7972881478c16b2a4e', 'It keeps the middle the softest of the three. Over the last minute it climbs one step at a time, reaching its loudest at the very end.'),
('performance_listening_notes', 458, 'facts_en', '6dab612f79a3358deb51f3fe03a6729c7677add3dfd43f7972881478c16b2a4e', '["Montreal Symphony"]'),
('performance_listening_notes', 459, 'headline_en', '2174ad0436641b8cade637a70008fcd8a89a36d31d7285da88465e1b74572cf1', 'A louder second outburst'),
('performance_listening_notes', 459, 'note_en', '8879a2a6d614a218ca080fe1c0a7565b0e6b15e3fb076c520aa97447b5496606', 'Of the two outbursts, it strikes the second one louder. The hushed section between them passes quickly, in 39 seconds.'),
('performance_listening_notes', 459, 'facts_en', '8879a2a6d614a218ca080fe1c0a7565b0e6b15e3fb076c520aa97447b5496606', '["Chicago Symphony"]'),
('performance_listening_notes', 460, 'headline_en', '7c48adb62f0fb8f8990e7b0d7955f2a17f5eae3ed501f2c74163b09a16407c6d', 'A soft close after the climax'),
('performance_listening_notes', 460, 'note_en', 'beb1a732186a116988364b02e3d14772626266a1e912ccb58ef88f437b4abbac', 'Keeps the opening soft, then rises from the middle. After the climax it settles softer than the other two and ends.'),
('performance_listening_notes', 460, 'facts_en', 'beb1a732186a116988364b02e3d14772626266a1e912ccb58ef88f437b4abbac', '["Montreal Symphony"]'),
('performance_listening_notes', 461, 'headline_en', '642bfb0a90e2cf3fb27e879b4a371f49185b903e977f1b5b50617bef91b7509f', 'The shortest, at 4:56'),
('performance_listening_notes', 461, 'note_en', 'd659c61d35fd701e2dc02be830e068fc2012d189615135a12ae03f19ba53bba4', 'At 4:56, the shortest of the three. The shape is almost the same as Muti''s, and it ends the softest of the three.'),
('performance_listening_notes', 461, 'facts_en', 'd659c61d35fd701e2dc02be830e068fc2012d189615135a12ae03f19ba53bba4', '["Berlin Phil"]'),
('performance_listening_notes', 462, 'headline_en', 'ddf737573407486cc9036cb7a38379c45be4a25b9ed26c3726cb38841160267c', 'A climax a minute before the end'),
('performance_listening_notes', 462, 'note_en', '666236365fe9f64bfa399fb86e4f48e6bc0495049981688040a4aaf1f6508b65', 'Unlike Dutoit and Previn, it reaches its loudest about a minute before the end. It also lifts sharply once, early, in the middle.'),
('performance_listening_notes', 462, 'facts_en', '666236365fe9f64bfa399fb86e4f48e6bc0495049981688040a4aaf1f6508b65', '["Berlin Phil"]'),
('performance_listening_notes', 463, 'headline_en', 'cc309dd6da3e324d16bd300b0db1ed739d5901d5e23e93640a3d17146f6b51aa', 'Loud from the oboe'),
('performance_listening_notes', 463, 'note_en', 'b841a65bec77b610cfe2a7b5b3905a074c82e261af03b1e4d93213f42516908f', 'At 2:44, the shortest of the three. It brings out the first song louder than the other two, so the gap between quiet and loud is the smallest.'),
('performance_listening_notes', 463, 'facts_en', 'b841a65bec77b610cfe2a7b5b3905a074c82e261af03b1e4d93213f42516908f', '["New York Phil"]'),
('performance_listening_notes', 464, 'headline_en', '1d458e9dbae69fd81b203b789770da9e4046767abdaee9a0c007f5e155afaab4', 'A long pause between the outbursts'),
('performance_listening_notes', 464, 'note_en', 'bf681515ef49f92d6133ffade12030e449f5dcf966c386880387dd4e1d4fc7fd', 'It strikes the first outburst the loudest and stretches the hushed passage between the two outbursts to nearly a minute. The other two take around 40 seconds.'),
('performance_listening_notes', 464, 'facts_en', 'bf681515ef49f92d6133ffade12030e449f5dcf966c386880387dd4e1d4fc7fd', '["Concertgebouw"]'),
('performance_listening_notes', 465, 'headline_en', 'b79523fafef1628fb032b7833d92cbb91870915296b07a47e84f87e3eee6e6e7', 'The lowest dip after the introduction'),
('performance_listening_notes', 465, 'note_en', '689aa41dd4815ffaa673b74e87d761a60a024c0c95d49076242e623272860413', 'After the introduction, it pulls the quiet passage back much lower than the other two. Like Dutoit, it places the loudest sound at the very end.'),
('performance_listening_notes', 465, 'facts_en', '689aa41dd4815ffaa673b74e87d761a60a024c0c95d49076242e623272860413', '["London Symphony"]'),
('performance_listening_notes', 466, 'headline_en', '5d3743bdfe77bd319ac85d64909f1cb66c9f704e3e17376a995763f4abe073f4', 'The softest oboe'),
('performance_listening_notes', 466, 'note_en', 'cd440ef8b8dc95317a2d3213f9cb2f86ecf09a6ebb384b699aa20ca847713910', 'The first song is softer than with Dutoit and Bernstein. After that it reaches near maximum sooner and sustains loud playing for a long time.'),
('performance_listening_notes', 466, 'facts_en', 'cd440ef8b8dc95317a2d3213f9cb2f86ecf09a6ebb384b699aa20ca847713910', '["London Symphony"]'),
('performance_listening_notes', 467, 'headline_en', 'ff5cefcf914c1ac2b9c9c07543b9372b87c1695dc3503137245ba6561d3f2550', 'The loudest early tutti'),
('performance_listening_notes', 467, 'note_en', 'eacba55c1c8106acc2dfe6ba47b32dc93a4cf0f7570f1a6651e39be26e038346', 'At 2:26, it is more than 10 seconds shorter than the other two. It enters at near maximum from the start and strikes its loudest in the early tutti.'),
('performance_listening_notes', 467, 'facts_en', 'eacba55c1c8106acc2dfe6ba47b32dc93a4cf0f7570f1a6651e39be26e038346', '["Boston Symphony"]'),
('performance_listening_notes', 468, 'headline_en', '7c3f8210da46a40436509621f8c428d8cf0925bafa4db8d4c5393029dda1fa5c', 'A breath just before the end'),
('performance_listening_notes', 468, 'note_en', 'b8d9fe3b8ba9a2c3f29e29d76c89345fbfbbc9c752c8db04169b5ca1d0a456d3', 'Driving hard from the start, it reaches near maximum earliest of the three. Just before the end it drops sharply once, then strikes its loudest in one stroke.'),
('performance_listening_notes', 468, 'facts_en', 'b8d9fe3b8ba9a2c3f29e29d76c89345fbfbbc9c752c8db04169b5ca1d0a456d3', '["LA Phil"]'),
('performance_listening_notes', 469, 'headline_en', 'a8dc63ba650e806b35b8c09598f719669aafa5e00c71fbc125a45054c45a1175', 'Near maximum in 8 seconds'),
('performance_listening_notes', 469, 'note_en', '4015a278c679cac12fd95dc97350647424d25d800f5b88d2979a3bcc2278f1eb', 'Eight seconds after the fanfare it reaches near maximum. It sustains loud playing the longest of the three and already strikes its climax in the middle march.'),
('performance_listening_notes', 469, 'facts_en', '4015a278c679cac12fd95dc97350647424d25d800f5b88d2979a3bcc2278f1eb', '["Vienna Phil"]'),
('performance_listening_notes', 470, 'headline_en', 'b1ec07a913acaaa8f0af703e2a338c16cd00d63a78b41636964c1c855c61d401', 'Building early toward the end'),
('performance_listening_notes', 470, 'note_en', 'b4b7c40cc464888220aaddc7ddb3ca7e037f660de90508e121425facc1404ab8', 'The loudest sound is placed at the end. The shape is almost the same as Tilson Thomas''s, but it starts building earlier on the way to the end.'),
('performance_listening_notes', 470, 'facts_en', 'b4b7c40cc464888220aaddc7ddb3ca7e037f660de90508e121425facc1404ab8', '["Berlin Phil"]'),
('performance_listening_notes', 471, 'headline_en', '80925effe06550155899602936261dbc0e4e6a3e64c2f6427d0894e040d10fe3', 'Saving the maximum until the end'),
('performance_listening_notes', 471, 'note_en', '05a10d182d938ce82f152be3911cba919402b9c074764f3b183c32ccce348720', 'The gentle passage in the middle is pulled back lower than in the other two. It reaches near maximum only in the returning march.'),
('performance_listening_notes', 471, 'facts_en', '05a10d182d938ce82f152be3911cba919402b9c074764f3b183c32ccce348720', '["Montreal Symphony"]'),
('performance_listening_notes', 472, 'headline_en', 'e88c0a44a100167acc7f4c8acc224a8a3f8e786f63d547a64ffb31faee27051b', 'Soft right after the first chord'),
('performance_listening_notes', 472, 'note_en', 'e3f4eae381c2c6c3627f9d580d76a45fe37df1737e001791afa9706bfb466e3e', 'It runs about 15 seconds longer than the other two. Right after the first chord it drops to a soft level and pulls deeply back in the middle.'),
('performance_listening_notes', 472, 'facts_en', 'e3f4eae381c2c6c3627f9d580d76a45fe37df1737e001791afa9706bfb466e3e', '["Montreal Symphony"]'),
('performance_listening_notes', 473, 'headline_en', '6b6d21ada35a36072ab821702677a88b54c4591bad9bf45680043b41a8bcf437', 'No big drops anywhere'),
('performance_listening_notes', 473, 'note_en', 'fcdb3d457aed6790b5e5e8229947388d19a1d84e4e8a047a3972ed27c9582c20', 'The gap between quiet and loud is smaller than in the other two. With no big dips, it pushes on evenly and reaches its climax at the end.'),
('performance_listening_notes', 473, 'facts_en', 'fcdb3d457aed6790b5e5e8229947388d19a1d84e4e8a047a3972ed27c9582c20', '["New York Phil"]'),
('performance_listening_notes', 474, 'headline_en', '510d53b8b14867d7689bde61a1c42ef47930fbaf900b9ad52666e7c7ddd62021', 'The climax on the final chord'),
('performance_listening_notes', 474, 'note_en', '1fe3178ca2df0dfd61faa5b97a9f4da80a77f41d7f1d63920aca606e763788a1', 'The fanfare opens softer than in the other two. It alone puts the climax on the final chord.'),
('performance_listening_notes', 474, 'facts_en', '1fe3178ca2df0dfd61faa5b97a9f4da80a77f41d7f1d63920aca606e763788a1', '["Boston Symphony"]'),
('performance_listening_notes', 475, 'headline_en', '9601293449b32cbe5274215d7d6f88d41af8f06ffb5c4ab86c2fdffd66e8fe87', 'All at once in the last few seconds'),
('performance_listening_notes', 475, 'note_en', '70e1639a7f7d29f7feecf45d5375340abb10d5a7ed1de66522a9f1020ddd0933', 'It pulls deeply back in the middle, then builds all at once just before the end. That is about 10 seconds later than Haitink.'),
('performance_listening_notes', 475, 'facts_en', '70e1639a7f7d29f7feecf45d5375340abb10d5a7ed1de66522a9f1020ddd0933', '["Philharmonia"]'),
('performance_listening_notes', 476, 'headline_en', 'fdadb5de3c7a61ed3f93724989a66f8b1d222491f6e64c048fe9da08a8145672', 'A less hushed first theme'),
('performance_listening_notes', 476, 'note_en', 'f0f47b019786f13961755dddbefc7f4d11e467c9ce782cd2a1a63e8738282edd', 'It brings out the first theme less softly than Mutter. The passage where the whole orchestra rises is also kept loud longer than in the other two.'),
('performance_listening_notes', 476, 'facts_en', 'f0f47b019786f13961755dddbefc7f4d11e467c9ce782cd2a1a63e8738282edd', '["Marriner · Academy of St Martin in the Fields"]'),
('performance_listening_notes', 477, 'headline_en', '0831c093089f1a5afab79b3b8939f0e5219a2a428db34ef4f13fe49e937c4566', 'Short, with a soft close'),
('performance_listening_notes', 477, 'note_en', 'ce02005e41f2656d6649388a401e83a81eef940594d675c30c35aa740ba47486', 'At 2:01, it is 33 seconds shorter than Mehta. After the climax it lets the level fall the most of the three before closing.'),
('performance_listening_notes', 477, 'facts_en', 'ce02005e41f2656d6649388a401e83a81eef940594d675c30c35aa740ba47486', '["Chicago Symphony"]'),
('performance_listening_notes', 478, 'headline_en', '6c26b7d58cced7e47a95b186a04d0286581ae8869afbe0ed157d86696bf42f2a', 'The middle held low'),
('performance_listening_notes', 478, 'note_en', '42985821ac9879db01e1dd88884de50ebc7351bbda698930cc6f35e9b031baf3', 'It holds the peaks in the middle lower than the other two. Near the end it rises to maximum in 16 seconds.'),
('performance_listening_notes', 478, 'facts_en', '42985821ac9879db01e1dd88884de50ebc7351bbda698930cc6f35e9b031baf3', '["Berlin Phil"]'),
('performance_listening_notes', 479, 'headline_en', '8887b531f9dc5f3aad5dba86f82d616313b3de1c7489c05fd8fe6196f5c93905', 'Longest, with the softest start'),
('performance_listening_notes', 479, 'note_en', 'b0541c034aadfe3c595df8f65adbeeaaa4269064c201728e2b1a1fe53d2f2565', 'At 2:34, it is longer than the other two. The first sound is the softest too, and the loud sound is saved for the end.'),
('performance_listening_notes', 479, 'facts_en', 'b0541c034aadfe3c595df8f65adbeeaaa4269064c201728e2b1a1fe53d2f2565', '["LA Phil"]'),
('performance_listening_notes', 480, 'headline_en', 'eb351aedb599ca2e587435eb900cc49ada3756ffe99b9c5ab5aa0f03eba36222', 'The softest first theme'),
('performance_listening_notes', 480, 'note_en', 'eaf4b26e958e92494bdb9ddcda70e8ee4bf95db6c9f11c0b8919141576e4fb4f', 'The first theme is brought out the softest of the three. The gap between quiet and loud is the largest, and it ends the softest too.'),
('performance_listening_notes', 480, 'facts_en', 'eaf4b26e958e92494bdb9ddcda70e8ee4bf95db6c9f11c0b8919141576e4fb4f', '["Karajan · Berlin Phil"]'),
('performance_listening_notes', 481, 'headline_en', '32ac83ad337f6034351007daeb5c17dfc906fb97a66db8ab8f917fe123056e9d', 'The loudest first sound'),
('performance_listening_notes', 481, 'note_en', 'a8415db58b8710173b4af79345b12fd1518ed98163731a996e65b865871c13e3', 'It starts the loudest of the three. Then it raises each peak a step higher and surges to its loudest near the end.'),
('performance_listening_notes', 481, 'facts_en', 'a8415db58b8710173b4af79345b12fd1518ed98163731a996e65b865871c13e3', '["Royal Phil"]'),
('performance_listening_notes', 482, 'headline_en', '75e36cde2161b0241be52f374c44d33a78bad1e1f983804455ffb2e513cb14da', 'Dropping right after the climax'),
('performance_listening_notes', 482, 'note_en', 'a5c24d5e0f39c5f5ccd89f5e93db3b2e6452b313e7718a07584e314dc5ce9dea', 'The shape is almost the same as Carl Davis''s. Unlike the other two, it drops straight to its smallest level right after the climax.'),
('performance_listening_notes', 482, 'facts_en', 'a5c24d5e0f39c5f5ccd89f5e93db3b2e6452b313e7718a07584e314dc5ce9dea', '["New York Phil"]'),
('performance_listening_notes', 483, 'headline_en', 'f8a27cad6acecf36c2483786ee01bef704e854fb42a2e210d255e341bd31310f', 'The opening kept soft'),
('performance_listening_notes', 483, 'note_en', '42bdb9d8f821022796e6716f0cfcbe892d51aa957dfe3e7e750cf4c20a4ab715', 'At 2:01, it is about 8 seconds shorter than the other two. It keeps the opening very soft, so the gap between quiet and loud is the largest.'),
('performance_listening_notes', 483, 'facts_en', '42bdb9d8f821022796e6716f0cfcbe892d51aa957dfe3e7e750cf4c20a4ab715', '["London Symphony"]'),
('performance_listening_notes', 484, 'headline_en', 'a2f98da4d6736ade2e82d1e55f1ec4fa67af0befb7babe0587661600dd39ff39', 'One more build after the big passage'),
('performance_listening_notes', 484, 'note_en', '6e25e8e83882d38ad4c57b8d276fe7915713e6ed4d9d8d9383895c5f252c957a', 'The shape is almost the same as Mutter''s. After the big passage is over, it builds once more, then closes softly.'),
('performance_listening_notes', 484, 'facts_en', '6e25e8e83882d38ad4c57b8d276fe7915713e6ed4d9d8d9383895c5f252c957a', '["Harding · Vienna Phil"]'),
('performance_listening_notes', 485, 'headline_en', 'f265fdacbc89ed44033a244e4b91079c9078b0a11a06aef3f2562f8bc68a8019', 'Surging again and again'),
('performance_listening_notes', 485, 'note_en', 'e85e252df33d91d6fe65919a707251aefd1460fc9b03ce8dc5e51eea9593909d', 'From the middle it is at near maximum and surges loudly several times to the end. The loudest sound comes at the very end.'),
('performance_listening_notes', 485, 'facts_en', 'e85e252df33d91d6fe65919a707251aefd1460fc9b03ce8dc5e51eea9593909d', '["Vienna Phil"]'),
('performance_listening_notes', 486, 'headline_en', '0439ecf408b0981bd7ec4f1f71eef259fc1b54aefb65166111ca3ffe88391c4c', 'Three even peaks'),
('performance_listening_notes', 486, 'note_en', '1aefb06f3e4b1e0ab6fcb60b5cf9af8df4198af130c354f89af50192647b8774', 'It builds the three early peaks evenly at a similar level. Only the last peak is raised a step, ending at its loudest.'),
('performance_listening_notes', 486, 'facts_en', '1aefb06f3e4b1e0ab6fcb60b5cf9af8df4198af130c354f89af50192647b8774', '["Bavarian Radio Symphony"]'),
('performance_listening_notes', 487, 'headline_en', '939ffc8e24c237efb8532850b578dee783639e4f9a776e40fa0067dd02b8ee34', 'The softest opening chorale'),
('performance_listening_notes', 487, 'note_en', '45fb3dcd2e379ca43c994e99ad66b51564a02041d6856f6434d50df1ad1729fc', 'The opening chorale is brought out the softest of the three. Unlike the other two, it places the climax 13 seconds before the end and closes from there.'),
('performance_listening_notes', 487, 'facts_en', '45fb3dcd2e379ca43c994e99ad66b51564a02041d6856f6434d50df1ad1729fc', '["Berlin Phil"]'),
('performance_listening_notes', 488, 'headline_en', 'c322df489de13267424513bddc18001014427058aa9d5b2e1686a2ec4b974cef', 'Loud right to the very end'),
('performance_listening_notes', 488, 'note_en', 'a358cc6286a933cb3be03080d8183a3d06b7408aee74cd2defe9ea803bcd5165', 'At 2:08, it is 11 seconds longer than Jansons. It sustains loud playing longer than the other two and ends at its loudest at the very end.'),
('performance_listening_notes', 488, 'facts_en', 'a358cc6286a933cb3be03080d8183a3d06b7408aee74cd2defe9ea803bcd5165', '["Gewandhaus"]'),
('performance_listening_notes', 489, 'headline_en', '66d93589fe5a24d1d0cea4d9414936bd9ddb435accbecfaf5f461265e99be093', 'A long dip before the end'),
('performance_listening_notes', 489, 'note_en', 'f6628678fddaa8220f0eb43af45490c1209a6820a76d13a0976b8766af9a8bbf', 'From about a minute before the end it stays soft for the longest of the three, then surges loudly again at the last moment.'),
('performance_listening_notes', 489, 'facts_en', 'f6628678fddaa8220f0eb43af45490c1209a6820a76d13a0976b8766af9a8bbf', '["Abbado · Mahler Chamber Orchestra"]'),
('performance_listening_notes', 490, 'headline_en', 'ac0aacbd412869765e94916a563a0c736ebf5bbd39fb49513cd75ab6707eecdf', 'Three surges'),
('performance_listening_notes', 490, 'note_en', 'd54d27d8eb46dce925e032f63071629a83e4b3eb72ee2f46911b2444f41e6bd7', 'There are three big surges, with short dips between them. It makes loud sounds the most often of the three.'),
('performance_listening_notes', 490, 'facts_en', 'd54d27d8eb46dce925e032f63071629a83e4b3eb72ee2f46911b2444f41e6bd7', '["Harnoncourt · Zurich Opera"]'),
('performance_listening_notes', 491, 'headline_en', '5aad4cc9e94b9ba5d58ac87f4fd509cd6628110c8b84f12d390b5a8c7c3f653f', 'The most even'),
('performance_listening_notes', 491, 'note_en', 'ee1e1b261a66fc164dbab882e68cd4ef89288be826ac6ae923eeed5ecb2f240b', 'The gap between quiet and loud is the smallest of the three. It continues evenly with no big dips and rings out loudest at the end.'),
('performance_listening_notes', 491, 'facts_en', 'ee1e1b261a66fc164dbab882e68cd4ef89288be826ac6ae923eeed5ecb2f240b', '["Solti · Vienna Phil"]'),
('performance_listening_notes', 492, 'headline_en', '1cc297791e2de64a6eae32b6e6085161f3c42efbc252c8c3a6099f12895b85ca', 'Holding back until the last 30 seconds'),
('performance_listening_notes', 492, 'note_en', '28b190059c5a59f7b5bddbb465150f637cded197f70444a68c6f96fc61600151', 'It saves near maximum until 30 seconds before the end. The quiet passage before that is pulled back the furthest of the three.'),
('performance_listening_notes', 492, 'facts_en', '28b190059c5a59f7b5bddbb465150f637cded197f70444a68c6f96fc61600151', '["London Symphony"]'),
('performance_listening_notes', 493, 'headline_en', '3aa9b71475af9e7a63c1d4cace06a67114d42b591f526eb595640536f76f0821', 'Nearly 30 seconds shorter'),
('performance_listening_notes', 493, 'note_en', 'f631a1c69be7660ca0e4e1f54aaa0250836068cd35cc952e7c615ddc4ad8254a', 'At 4:07, it is nearly 30 seconds shorter than the other two. The climax comes earliest too, and loud playing is sustained for a long time.'),
('performance_listening_notes', 493, 'facts_en', 'f631a1c69be7660ca0e4e1f54aaa0250836068cd35cc952e7c615ddc4ad8254a', '["New York Phil"]'),
('performance_listening_notes', 494, 'headline_en', '51a8a0b262a887b92b17959c83dc51912dc94a1e45b4f64025548e787ab2a64a', 'Less restrained than Flórez'),
('performance_listening_notes', 494, 'note_en', '6963be8417dd3beed37105b7066c639fbce266e833d6e827a49d60435d84d23e', 'The shape is almost the same as Flórez''s. But it holds the song down one step less throughout and reaches near maximum 12 seconds before the end.'),
('performance_listening_notes', 494, 'facts_en', '6963be8417dd3beed37105b7066c639fbce266e833d6e827a49d60435d84d23e', '["Morandi"]'),
('performance_listening_notes', 495, 'headline_en', '275fd427af5af1f28abe67853bce55d9b686461f191fe180f3fbef1a665cffd7', 'Held down until the end'),
('performance_listening_notes', 495, 'note_en', '01095bb31825ecef04a3d0f69c63acfd0d30aeed6e099da5931b1e45efc299a7', 'It keeps most of the song the softest of the three. It first reaches near maximum only at the final close.'),
('performance_listening_notes', 495, 'facts_en', '01095bb31825ecef04a3d0f69c63acfd0d30aeed6e099da5931b1e45efc299a7', '["Rizzi · Milan Verdi"]'),
('performance_listening_notes', 496, 'headline_en', '60d004e24b5d1d65442224e6d531edd881ad0e2f4bb0b939c82076873fd28248', 'Maximum already by the middle'),
('performance_listening_notes', 496, 'note_en', 'ed249a5e8be8a10ddece1f1dd373b637e3d43160638220c0f82ccdc6f1414a5c', 'At 1:26, the shortest of the three. It already reaches near maximum in the middle and keeps that level to the end.'),
('performance_listening_notes', 496, 'facts_en', 'ed249a5e8be8a10ddece1f1dd373b637e3d43160638220c0f82ccdc6f1414a5c', '["Philharmonia"]'),
('performance_listening_notes', 497, 'headline_en', '3b594e353d7e04eb0748d5a94f2d68badc183499024d11a2d84411e4ff1f406f', 'Near maximum by the end of the first verse'),
('performance_listening_notes', 497, 'note_en', '7da9f0568c2fe5acfbe4d497e19371bbd0f517d66b9e52edcc4c63171c557676', 'It alone reaches near maximum already at the end of the first verse. Its dynamic range is also narrower than that of Kaufmann and Flórez.'),
('performance_listening_notes', 497, 'facts_en', '7da9f0568c2fe5acfbe4d497e19371bbd0f517d66b9e52edcc4c63171c557676', '["Marin · Munich Radio"]'),
('performance_listening_notes', 498, 'headline_en', '847fd66bed9e8d2f213ec5f4004960cafff4082c66257753e4b82261ba8eb702', 'Building one step at a time'),
('performance_listening_notes', 498, 'note_en', 'fb7ac57a4ccafb556700ac0b2cf3a75b3d9351dffee66497d24bc53259b35d74', 'The prelude opens the softest of the three. As it goes on, it grows a step at a time and rings out loudest on the final chord.'),
('performance_listening_notes', 498, 'facts_en', 'fb7ac57a4ccafb556700ac0b2cf3a75b3d9351dffee66497d24bc53259b35d74', '["Gheorghiu · Lopardo", "Royal Opera House"]'),
('performance_listening_notes', 499, 'headline_en', '22fbfdae420e7b8ec1ebf10ddd3ac5255e9b70a35fe386deefef8c3389c19fb1', 'Loud from the first fanfare'),
('performance_listening_notes', 499, 'note_en', '694870d7fef664526e73d7003b9baa4c0d93144f052a02eb64c479f3c20aef96', 'The first sound is louder than in the other two, and the level hardly drops to the end. At 1:44, it is 18 seconds longer than Muti.'),
('performance_listening_notes', 499, 'facts_en', '694870d7fef664526e73d7003b9baa4c0d93144f052a02eb64c479f3c20aef96', '["Vienna Phil"]'),
('performance_listening_notes', 500, 'headline_en', '2f302bec61c62f1d193f8e0851415cae005853255c64815d7e852535825ec787', 'A breath before the end'),
('performance_listening_notes', 500, 'note_en', 'a460a0591d7b9875ac745eff75be3a2ed21733f38011c8b9c452d246ca1bd37d', 'Unlike Solti, it opens the prelude loudly. It alone takes one more breath before the final chord, then rises.'),
('performance_listening_notes', 500, 'facts_en', 'a460a0591d7b9875ac745eff75be3a2ed21733f38011c8b9c452d246ca1bd37d', '["Fabbricini · Alagna", "La Scala"]'),
('performance_listening_notes', 501, 'headline_en', '8af788e3be79ef5463dc11e2f24229f5a7d8dd7697f71f57405a95a38f742424', 'Three rises late on'),
('performance_listening_notes', 501, 'note_en', 'fd0fa8830efc30b896899a379dfb90dccf8337e2dc2e6b7981f5a800477c0eab', 'The gap between quiet and loud is smaller than in the other two. Past the middle it lifts loudly three times in a row.'),
('performance_listening_notes', 501, 'facts_en', 'fd0fa8830efc30b896899a379dfb90dccf8337e2dc2e6b7981f5a800477c0eab', '["Cotrubas · Domingo", "Bavarian State Orchestra"]'),
('performance_listening_notes', 502, 'headline_en', '93c1e51ed3d2abdc074bb9f59a579999caf6fe2a6d44195d72c1ce86cece6f85', 'Growing only in the last 12 seconds'),
('performance_listening_notes', 502, 'note_en', '9faabd5f39a412e47685cb85b43462a33f65551cdecb030293ee7f532e56f1cb', 'The fanfare is brought out softer than with Karajan and Muti. It starts to grow only in the last 12 seconds and reaches maximum on the final chord.'),
('performance_listening_notes', 502, 'facts_en', '9faabd5f39a412e47685cb85b43462a33f65551cdecb030293ee7f532e56f1cb', '["Santa Cecilia"]'),
('performance_listening_notes', 503, 'headline_en', 'aa8bb5358ec95446de2b13f5cfdbe8c7393c839097a5530b02f4a6fcf492d814', 'The first chord as the climax'),
('performance_listening_notes', 503, 'note_en', '794404a729f5d4034737b4badc950802aee41369a66fd4fa68cf58676349c600', 'It slams down at its loudest right on the first chord. It holds loud playing the longest of the three, and the closing passage is pulled back the least.'),
('performance_listening_notes', 503, 'facts_en', '794404a729f5d4034737b4badc950802aee41369a66fd4fa68cf58676349c600', '["London Symphony"]'),
('performance_listening_notes', 504, 'headline_en', 'a46f8fa3b328daa07486a86e3f73016edf6e3cc2eaa74252b14cc455d205c168', 'The lowest ending'),
('performance_listening_notes', 504, 'note_en', '6cabf0d9aa5bbfba7d6f95f4a16f19fb7795dc429da9a24380b7760fcf35ceb6', 'At 2:25, it runs about 13 seconds longer than the other two. After its loudest point just before the closing passage, it drops lower than Bernstein and Barenboim.'),
('performance_listening_notes', 504, 'facts_en', '6cabf0d9aa5bbfba7d6f95f4a16f19fb7795dc429da9a24380b7760fcf35ceb6', '["Berlin Phil"]'),
('performance_listening_notes', 505, 'headline_en', '41baa829b914b0b090fb773a03aa234161777ed8420aedbbc9933e5c60e220f2', 'Strength only in the final surge'),
('performance_listening_notes', 505, 'note_en', 'a1157c5a80b42e9e1718e79849d2ec140cfa1f3ea45195a18f350f8410a9bfa1', 'At 5:44, it runs about a minute longer than Rattle. Loud playing comes only briefly, in the final surge.'),
('performance_listening_notes', 505, 'facts_en', 'a1157c5a80b42e9e1718e79849d2ec140cfa1f3ea45195a18f350f8410a9bfa1', '["Berlin Phil"]'),
('performance_listening_notes', 506, 'headline_en', 'fcb0bf195042d3115e741eeb8ddcec083987ff0863c1243d6563e9d7f2b8dafc', 'A less hushed close'),
('performance_listening_notes', 506, 'note_en', 'bf13011c9ee57ce8a82f9e59591e9ab4b1b1bacb4137df653c9727a68d86162e', 'Like Abbado, it makes the final surge bigger. After that, it closes the least softly of the three.'),
('performance_listening_notes', 506, 'facts_en', 'bf13011c9ee57ce8a82f9e59591e9ab4b1b1bacb4137df653c9727a68d86162e', '["Berlin Phil"]'),
('performance_listening_notes', 507, 'headline_en', '15b8c101e750d9c6655de724d17032507fd177f36ad00a8fc4e019e203da2fd9', 'Holding the loudest'),
('performance_listening_notes', 507, 'note_en', 'bc350fb237e162e46d849e922b672c3e12c909dd01672df8a776819d7699643c', 'It starts the least softly of the three. It holds loud playing the longest and ends the loudest.'),
('performance_listening_notes', 507, 'facts_en', 'bc350fb237e162e46d849e922b672c3e12c909dd01672df8a776819d7699643c', '["Vienna Phil"]'),
('performance_listening_notes', 508, 'headline_en', 'f6e3c086bb2ff47d474df815509ddbf81a1d5c925fa17255ae7360255c30f906', 'A slow 3:27'),
('performance_listening_notes', 508, 'note_en', '52d8be0f12c702d6cb95957e5c73807b49244adb8a0ec6789ddf5cb5f1a79056', 'At 3:27, it runs more than 20 seconds longer than the other two. Unlike Karajan, it plays loud only briefly before moving on.'),
('performance_listening_notes', 508, 'facts_en', '52d8be0f12c702d6cb95957e5c73807b49244adb8a0ec6789ddf5cb5f1a79056', '["Berlin Phil"]'),
('performance_listening_notes', 509, 'headline_en', '9d06fdbf5051dda9398b8def0fca84832f38bc35a812c74ac1a456222b1e031f', 'Shortest, peaking twice'),
('performance_listening_notes', 509, 'note_en', 'cc917354b50aeda76920de6f648193c181843b12b6afd90123628007d32bafa2', 'At 4:49, it is shorter than the other two. The surge in the middle is made as big as the one at the end.'),
('performance_listening_notes', 509, 'facts_en', 'cc917354b50aeda76920de6f648193c181843b12b6afd90123628007d32bafa2', '["Berlin Phil"]'),
('performance_listening_notes', 510, 'headline_en', '69ea0f7f0c1dfab51f1a63c5129d9599b3e7e3c2576a1fba1dd459004297a86d', 'Pulling back, then straight to the climax'),
('performance_listening_notes', 510, 'note_en', '3eb774b511738284380ed62ff723f460cd2fdf811737340f02bd2d6898ce9632', 'It pulls back once, then rises straight away to its loudest. The closing passage is pulled back deeper than Bernstein''s and shallower than Karajan''s.'),
('performance_listening_notes', 510, 'facts_en', '3eb774b511738284380ed62ff723f460cd2fdf811737340f02bd2d6898ce9632', '["Chicago Symphony"]'),
('performance_listening_notes', 511, 'headline_en', '18158b876187ecb4c425ff99359fdd5f69c3d928ef32cca9737370fe2b88916a', 'A steep climb in 6 seconds'),
('performance_listening_notes', 511, 'note_en', 'b574782796e2c75ee7d36cd217633a82435bc3928fb2c6686b21400623ff43b7', 'At 2:54, it is more than 30 seconds shorter than Muti. It opens a wide gap between quiet and loud, and shoots up to maximum within 6 seconds of starting to grow.'),
('performance_listening_notes', 511, 'facts_en', 'b574782796e2c75ee7d36cd217633a82435bc3928fb2c6686b21400623ff43b7', '["London Symphony"]'),
('performance_listening_notes', 512, 'headline_en', '9d5903f5c8978fc531e77a3a135526facfabd68d3ca118dd953550f7767192d9', '45 seconds to maximum'),
('performance_listening_notes', 512, 'note_en', '2a0e5ea47523ef0a26d12c9a7cb76ab5a3df5e712b59418bad70089c8e361ad0', 'It starts the softest of the three and takes about 45 seconds to reach maximum. Loud playing is the briefest.'),
('performance_listening_notes', 512, 'facts_en', '2a0e5ea47523ef0a26d12c9a7cb76ab5a3df5e712b59418bad70089c8e361ad0', '["London Symphony"]'),
('performance_listening_notes', 513, 'headline_en', '5fd5a10c760807ae0749b4eef1583455f4cf68f1b9af17cf318b2c02b6809f92', 'The smallest dynamic gap'),
('performance_listening_notes', 513, 'note_en', 'bf8ed6430658aca5b4b21711fee48bfb20348fbe6b4343e438f6c3d802532c78', 'Unlike Tilson Thomas, it keeps the range between quiet and loud small. It doesn''t drop far between the chords or in the middle.'),
('performance_listening_notes', 513, 'facts_en', 'bf8ed6430658aca5b4b21711fee48bfb20348fbe6b4343e438f6c3d802532c78', '["Chicago Symphony"]'),
('performance_listening_notes', 514, 'headline_en', '8fb5423b8e364046678a0257f365b05646e8b9ae40953db72eca455e2f453633', 'A deep dip in the middle too'),
('performance_listening_notes', 514, 'note_en', '2aa5cac0e85311271cbbb87c0b63a397642a559acaeb883d60b0f7ea5724216f', 'The gap between quiet and loud is the largest of the three. It sinks as deep in the middle as at the start, then rises again.'),
('performance_listening_notes', 514, 'facts_en', '2aa5cac0e85311271cbbb87c0b63a397642a559acaeb883d60b0f7ea5724216f', '["London Symphony"]'),
('performance_listening_notes', 515, 'headline_en', '001d36a978dbd6992e60afd6a6cd511fa7135bad751eb7108976717443df1e8c', 'A march over two minutes long'),
('performance_listening_notes', 515, 'note_en', '74977934523fd9673e407395f5b1c11f0e10287c2212d6726f8a0e599b3f1caf', 'At 2:08, it is 11 seconds longer than Solti. It steps down hardest on the first beat and lifts back almost as high before the end.'),
('performance_listening_notes', 515, 'facts_en', '74977934523fd9673e407395f5b1c11f0e10287c2212d6726f8a0e599b3f1caf', '["Concertgebouw"]'),
('performance_listening_notes', 516, 'headline_en', 'fe92df8a4df11b646785b343d9df0bcbd9255e3ae135e321959295ad9d01e153', 'Loudest in the first 9 seconds'),
('performance_listening_notes', 516, 'note_en', 'f238cf0f80d4e06502aeec5543eb78f5d4fa59a0371baf3892068c5d9b38a020', 'From the first beat through the 9-second mark, it pushes the loudest. Before the end it drops to the smallest level of the three, then rises again.'),
('performance_listening_notes', 516, 'facts_en', 'f238cf0f80d4e06502aeec5543eb78f5d4fa59a0371baf3892068c5d9b38a020', '["Vienna Phil"]'),
('performance_listening_notes', 517, 'headline_en', 'bf6d853fb609df36142307d92c920b4b0318f7ddf40a5526d6daebcc0d618376', 'Shortest, with maximum up front'),
('performance_listening_notes', 517, 'note_en', 'ec72a2a8ea8d5d55ec2ff59dac17d619e66f41bde01ee16253f03bfe4d7df605', 'At 2:01, it is 16 seconds shorter than Bernstein. It is loudest the first time it rises, and the second time goes a little lower.'),
('performance_listening_notes', 517, 'facts_en', 'ec72a2a8ea8d5d55ec2ff59dac17d619e66f41bde01ee16253f03bfe4d7df605', '["Boston Symphony"]'),
('performance_listening_notes', 518, 'headline_en', '22d2c2ac1fe9a2540e1c3595bc628747b3db8fda2ddd99843cb681ce49a40a6b', 'Straight to maximum, twice the same'),
('performance_listening_notes', 518, 'note_en', '24ef312ed73a6e73a3b59d04887ee43facdb23cbf63bd80f810bc9170e9f9536', 'At 2:17, it is longer than the other two. It reaches near maximum in 6 seconds and hurls out both rises at the same level.'),
('performance_listening_notes', 518, 'facts_en', '24ef312ed73a6e73a3b59d04887ee43facdb23cbf63bd80f810bc9170e9f9536', '["Chicago Symphony"]'),
('performance_listening_notes', 519, 'headline_en', 'ea56c270eb7551cdd3dfde5e7a8da8865fa3cca3dd3f3a976f38f8feee88adf1', 'The climax placed near the end'),
('performance_listening_notes', 519, 'note_en', '4a19ded202c750a32eab9deab71746cc6d0a703fdee235c440182d7e0cd99556', 'Unlike Haitink and Solti, it places the loudest sound near the end. Five seconds after the climax it folds straight back to its smallest level.'),
('performance_listening_notes', 519, 'facts_en', '4a19ded202c750a32eab9deab71746cc6d0a703fdee235c440182d7e0cd99556', '["Boston Symphony"]'),
('performance_listening_notes', 520, 'headline_en', '5b85044a5372d2d811776c83141a62afc61426cd22d742aeae5b70620187e4ae', 'Opening softly, building step by step'),
('performance_listening_notes', 520, 'note_en', 'ada56e5ba1a33b393430f62fe5f67e274e2621b434c4fec7be05955f1cb861ef', 'At 2:01, it is longer than the other two. The first chord is the softest, and it stacks up one step at a time toward the end.'),
('performance_listening_notes', 520, 'facts_en', 'ada56e5ba1a33b393430f62fe5f67e274e2621b434c4fec7be05955f1cb861ef', '["Berlin Phil"]'),
('performance_listening_notes', 521, 'headline_en', '1f2040c27dae2d25d2a6bf76b97684fd8603a957cf1629d05f701fe957fb3799', 'To the light the fastest'),
('performance_listening_notes', 521, 'note_en', 'a0f500e970e009688f73c05c56d562c1477da407c7939e895e9cd9d67c5c1bad', 'At 2:44, the shortest of the three. It opens louder than the other two, shrinks to very small just before the light, then bursts out.'),
('performance_listening_notes', 521, 'facts_en', 'a0f500e970e009688f73c05c56d562c1477da407c7939e895e9cd9d67c5c1bad', '["Chicago Symphony"]'),
('performance_listening_notes', 522, 'headline_en', 'de9d74b52f4f54e17f7d00d413efc3772be07839cb516089f13cfd4badedd6b8', 'Loud in the last verse too'),
('performance_listening_notes', 522, 'note_en', 'f94e447eb31f4f53daa215697398e75841a4405bac3a33921b456ab61bb6b3dc', 'The gap between quiet and loud is the smallest of the three. The last verse is sung loudly again, and the postlude closes the least softly.'),
('performance_listening_notes', 522, 'facts_en', 'f94e447eb31f4f53daa215697398e75841a4405bac3a33921b456ab61bb6b3dc', '["Gerald Moore"]'),
('performance_listening_notes', 523, 'headline_en', '29481e4156905456d02563afede0fc19e135d45dc12dcf100d18564935b610f0', 'A song 35 seconds longer'),
('performance_listening_notes', 523, 'note_en', '05537ce6b6a966b49824147e5791ec45ea93621b3eeb6d1a25d3cea04f94e014', 'At 5:17, it runs more than 35 seconds longer than the other two. It also opens less softly than they do.'),
('performance_listening_notes', 523, 'facts_en', '05537ce6b6a966b49824147e5791ec45ea93621b3eeb6d1a25d3cea04f94e014', '["Gerold Huber"]'),
('performance_listening_notes', 524, 'headline_en', 'e98fc22e5383970b88c3cf04f7a9df929b7abcc455bf325669fe8afdda526156', 'Already up before the light'),
('performance_listening_notes', 524, 'note_en', 'a55e93d1030d8f4844a78e31ec79c02f430d7eee787b580cfccb83a2c032e896', 'It is already at near maximum about 10 seconds before the light. After the light bursts out it also continues louder than the other two.'),
('performance_listening_notes', 524, 'facts_en', 'a55e93d1030d8f4844a78e31ec79c02f430d7eee787b580cfccb83a2c032e896', '["Berlin Phil"]'),
('performance_listening_notes', 525, 'headline_en', '17a0bccc35a70ed3c0557b4d254354efd7db7b2445c29e4d4b4988ce3712c615', 'A very soft prelude'),
('performance_listening_notes', 525, 'note_en', '322fe1c6812aea1f27887744ad21059a5240f02096e7cd6c09eb5ba5e6ec84eb', 'The piano prelude opens the softest of the three. In both verses it lifts to near maximum at the top, and drops far between them.'),
('performance_listening_notes', 525, 'facts_en', '322fe1c6812aea1f27887744ad21059a5240f02096e7cd6c09eb5ba5e6ec84eb', '["Huber (piano)"]'),
('performance_listening_notes', 526, 'headline_en', '3d6a5bbcfa0bf7d9723ac3e85b058c92b347cb69b48e524740e571c0e05ac696', 'The smallest last verse'),
('performance_listening_notes', 526, 'note_en', '95f8e2bd3dcf218327540c2a2926b0a6ace12271b8f223fa0d5bdd7869100c23', 'Unlike Fischer-Dieskau, it sings the last verse small. After the passage about the wind, it eases down little by little to the end.'),
('performance_listening_notes', 526, 'facts_en', '95f8e2bd3dcf218327540c2a2926b0a6ace12271b8f223fa0d5bdd7869100c23', '["Graham Johnson"]'),
('performance_listening_notes', 527, 'headline_en', '638dae64b8d47c22e6279776bb54d4b3af89d4a36c3242a8addb657519797d1a', 'Maximum only in the second verse'),
('performance_listening_notes', 527, 'note_en', '5a65e1966a0b86132c764efb372609c13a119b767fc1642174cae120b5125f76', 'The first verse is kept one step lower, and it reaches near maximum only in the second verse. The other two get there already in the first.'),
('performance_listening_notes', 527, 'facts_en', '5a65e1966a0b86132c764efb372609c13a119b767fc1642174cae120b5125f76', '["Ashkenazy (piano)"]'),
('performance_listening_notes', 528, 'headline_en', '37d9b63d8f035484e3251bf377dd849b8d93477abd570cf217540769e9e4192d', 'Two soft minutes before the light'),
('performance_listening_notes', 528, 'note_en', '9d28ddd01ae3784ca59432282df87e3c06b084dff71ad1688a694b198cffc6d3', 'At 3:15, it runs more than 30 seconds longer than Solti. It opens at its smallest and stays soft for over two minutes up to the light.'),
('performance_listening_notes', 528, 'facts_en', '9d28ddd01ae3784ca59432282df87e3c06b084dff71ad1688a694b198cffc6d3', '["Bavarian Radio Symphony"]'),
('performance_listening_notes', 529, 'headline_en', 'b7aab569e34550b184280386305853de99144700868281299745ddd355c0de9d', 'Both verses at the same height'),
('performance_listening_notes', 529, 'note_en', '644577bc7b89d4c66c56104b0f7aba67b2b6a8265864cda3b0bd475bb29501ad', 'It sings the peaks of the two verses at nearly the same level. The ending is also less soft than in the other two.'),
('performance_listening_notes', 529, 'facts_en', '644577bc7b89d4c66c56104b0f7aba67b2b6a8265864cda3b0bd475bb29501ad', '["Eschenbach (piano)"]'),
('performance_listening_notes', 530, 'headline_en', '49f13c22d34703e7a52e1b01b948e39952127ecaf7ce48721e3b402d0e8994fb', 'The climax arrives first'),
('performance_listening_notes', 530, 'note_en', '5f58af59c16b034515fe2d69f7a99109087e68ba6c5e91393a942b2337603836', 'It reaches its loudest sound before the other two and keeps the middle at near maximum. The passage where it suddenly sinks back is cut down deeply.'),
('performance_listening_notes', 530, 'facts_en', '5f58af59c16b034515fe2d69f7a99109087e68ba6c5e91393a942b2337603836', '["Boston Symphony"]'),
('performance_listening_notes', 532, 'headline_en', 'aee90f2ab78e2b9dfb5eefd164307ceb32fe0880781a76beb3f78aebd21f5df9', 'A pace 20 seconds quicker'),
('performance_listening_notes', 532, 'note_en', 'bbdf712c22ee3f3ed350457bc2e10547e95c72a7f68be44bd973e028165298f9', 'At 1:37, it is more than 20 seconds shorter than the other two. The first two phrases are also played louder than with Karajan and Solti.'),
('performance_listening_notes', 532, 'facts_en', 'bbdf712c22ee3f3ed350457bc2e10547e95c72a7f68be44bd973e028165298f9', '["Oslo Phil"]'),
('performance_listening_notes', 533, 'headline_en', '85b6c8cb54d2781adb5aebfb6970ae2a962834d4e0bc75a904a8a1323f89e8ee', 'The deepest silence'),
('performance_listening_notes', 533, 'note_en', '9f24063f8aa71be0fb101f2302855280257e91f5f7322de4cc1403b7ede2a362', 'The first sound is the softest of the three. It also sinks the deepest between phrases, so the gap between quiet and loud is the largest.'),
('performance_listening_notes', 533, 'facts_en', '9f24063f8aa71be0fb101f2302855280257e91f5f7322de4cc1403b7ede2a362', '["Berlin Phil"]'),
('performance_listening_notes', 534, 'headline_en', '65656689004292570af0d4292fba7da56a2528eb1e536f44f9d129ffd319635f', 'Arriving late, holding briefly'),
('performance_listening_notes', 534, 'note_en', '2490446d709505a3abc751b20041eb06168b8398d4dcaa3e02c9845493bc4644', 'It reaches near maximum the latest of the three, and holds loud playing for only about half as long as the other two. Its dips are the deepest.'),
('performance_listening_notes', 534, 'facts_en', '2490446d709505a3abc751b20041eb06168b8398d4dcaa3e02c9845493bc4644', '["Montreal Symphony"]'),
('performance_listening_notes', 536, 'headline_en', '2a9e4901c0158cee017b984418f9b548affc094d0ffe2e390f2de29f8ea569ce', 'A step higher with each phrase'),
('performance_listening_notes', 536, 'note_en', '9b3a542659fdaba1611df14833f4dada5931ba6db19f856ede06c0427a323d80', 'Each time the phrase returns, it raises the level a step. It rings out loudest at the end when the whole orchestra rises.'),
('performance_listening_notes', 536, 'facts_en', '9b3a542659fdaba1611df14833f4dada5931ba6db19f856ede06c0427a323d80', '["Chicago Symphony"]'),
('performance_listening_notes', 538, 'headline_en', '674132b628239ce038155a4a8a2c3a80988fffecb20295457ff1a1bd0def95bf', 'A full sound early'),
('performance_listening_notes', 538, 'note_en', '9c0bd269124ebfe178771f9eb2511d1533c244fc0e975db0d0cafca0b0953f03', 'It reaches near maximum in 26 seconds, filling the sound even earlier than Ozawa. It also opens a smaller gap between quiet and loud.'),
('performance_listening_notes', 538, 'facts_en', '9c0bd269124ebfe178771f9eb2511d1533c244fc0e975db0d0cafca0b0953f03', '["Chicago Symphony"]'),
('performance_listening_notes', 541, 'headline_en', 'fc0ae38215856cf8213d1a473f6fc4e85eb7bd2d052e9f53861ef10f9204fb19', '49 seconds at one level'),
('performance_listening_notes', 541, 'note_en', '23ccd6610bba32662b9a5136eb78253afab87fbb1dd64e96e38f1a41186fe479', 'At 49 seconds, the shortest of the three. The range between quiet and loud is also the smallest, so it runs at almost the same level from start to finish.'),
('performance_listening_notes', 543, 'headline_en', 'bdb49864ad7d82325daf4a58fd1a47eb7eade1043bc73f63a4ad32e2da66a430', 'Louder toward the end'),
('performance_listening_notes', 543, 'note_en', '1e9c611c260b3ba09887790fa0ff9128311a58d380ab05dd4180a6b1595bb997', 'It sets off softly and grows toward the end. It alone puts the loudest sound a few seconds before the end.'),
('performance_listening_notes', 544, 'headline_en', 'ff4049ff235cc70d7c230a750da556a3631f89518ce4a833e0ed71102a42921c', 'Three small swells'),
('performance_listening_notes', 544, 'note_en', '8b8916b27dc8a53ff59d7937286c94b48daaf849988b6b57bab7c549c6a2b82d', 'It runs with three small rises and falls. The loudest sound comes a little past the exact middle.'),
('performance_listening_notes', 545, 'headline_en', '71315129289bdee8b56ee935dd6748dc99de56a7193a1e1f6a3d3c0ba912918d', 'The deepest drop after the tutti'),
('performance_listening_notes', 545, 'note_en', 'f4d50d7548f3ba9543c00009895c52b44af97d9d2d8f766b747b4319ee0cc2fe', 'At 2:17, the longest of the three. Right after the first tutti it gets softest, and it places the climax late.'),
('performance_listening_notes', 545, 'facts_en', 'f4d50d7548f3ba9543c00009895c52b44af97d9d2d8f766b747b4319ee0cc2fe', '["Stuttgart Chamber Orchestra"]'),
('performance_listening_notes', 546, 'headline_en', 'f6951aee93f2a0defe8a0ddfb8a4454168c23ab193e4aa34cf52a4a6e7ab5723', 'Rising early, holding long'),
('performance_listening_notes', 546, 'note_en', '2014467125346866630e748e83fe611a17189ede5503fc9d3f660902dd6cdde5', 'It reaches near maximum earlier than the other two. It sustains loud playing and pushes on to the end.'),
('performance_listening_notes', 546, 'facts_en', '2014467125346866630e748e83fe611a17189ede5503fc9d3f660902dd6cdde5', '["Dresdner Kammerchor · La Stagione"]'),
('performance_listening_notes', 548, 'headline_en', 'a7e10fd564341dcca3d9a660081d30979cb626c77f68245b0d32839c0c7d08bd', 'Sinking before the end, then one leap'),
('performance_listening_notes', 548, 'note_en', 'dd58238794750b49eb64b0079bfb65fe0d748cc777c9734adb570aef3bd7ff98', 'The first sound is the softest of the three. It sinks to its smallest level just before the end, then rises all at once on the final chord.'),
('performance_listening_notes', 548, 'facts_en', 'dd58238794750b49eb64b0079bfb65fe0d748cc777c9734adb570aef3bd7ff98', '["RIAS Kammerchor · Akademie für Alte Musik Berlin"]'),
('performance_listening_notes', 549, 'headline_en', 'd94ddc889a2e01b8abc27ab634376d6c16ea6e084d485d9d926f46f845465880', 'Even up to the final chord'),
('performance_listening_notes', 549, 'note_en', '6c68f92f8d8fac84797215db80baf916f42327252bfe00d4cdc6d36d608b11ec', 'It doesn''t reach near maximum until the final chord and continues evenly. The gap between quiet and loud is also smaller than with Schneider and Rademann.'),
('performance_listening_notes', 549, 'facts_en', '6c68f92f8d8fac84797215db80baf916f42327252bfe00d4cdc6d36d608b11ec', '["Kölner Akademie"]'),
('performance_listening_notes', 550, 'headline_en', '0276f4e2f3386245b07c7d44e6c02bee44a8de5c12c89e618d76b5db27d86204', 'Even, with the climax late'),
('performance_listening_notes', 550, 'note_en', '7f5035722c9cd6c3288e637d817a3986fd6e81bb9c30ad9e5442ba857c462e54', 'It keeps the range between quiet and loud small and continues the early part evenly. Like Münchinger, it places the climax late.'),
('performance_listening_notes', 550, 'facts_en', '7f5035722c9cd6c3288e637d817a3986fd6e81bb9c30ad9e5442ba857c462e54', '["Concertgebouw"]'),
('performance_listening_notes', 551, 'headline_en', 'b077ed9f149955f64eeec09c265d9bb3c73aa64216d0180e8b42354901052395', 'The climax up front'),
('performance_listening_notes', 551, 'note_en', '7bbdffaffc50bbfb47fb73fb802b6c1404b0ef277075e9a2793c56f081dfd69a', 'It alone places the climax early. It also sustains loud playing longer than the other two and drops sharply once in the middle.'),
('performance_listening_notes', 551, 'facts_en', '7bbdffaffc50bbfb47fb73fb802b6c1404b0ef277075e9a2793c56f081dfd69a', '["Netherlands Chamber Orchestra"]'),
('performance_listening_notes', 555, 'headline_en', 'ae52f955b33f9e580684a3dbaf7f73557010f7c305c8a6f14649b9202e1c46ca', 'From soft to loud in one go'),
('performance_listening_notes', 555, 'note_en', '4f80010b13909a827ec1abd47985fb3a99333be0c3d9ab3920eaedf0bf93959e', 'From its softest point it climbs to its loudest in 18 seconds. Near the end it sings at almost the same level once more.'),
('performance_listening_notes', 555, 'facts_en', '4f80010b13909a827ec1abd47985fb3a99333be0c3d9ab3920eaedf0bf93959e', '["Royal Opera House"]'),
('performance_listening_notes', 556, 'headline_en', '21eb9e34dfaf633af267b82566fbaec16837d7a76f0eb6257a81484b54644073', 'Even, with the climax at the end'),
('performance_listening_notes', 556, 'note_en', '09fc6b61470bd53940ada1f8a182e9e570e4a3d44598eae7c97af98f29455238', 'The first sound is the loudest of the three, and the gap between quiet and loud is kept narrow. The loudest sound comes only near the end.'),
('performance_listening_notes', 556, 'facts_en', '09fc6b61470bd53940ada1f8a182e9e570e4a3d44598eae7c97af98f29455238', '["Utah Symphony"]'),
('performance_listening_notes', 558, 'headline_en', '213c9e4bbafa1888d22a809f4e3de283d1934a905b376cde80f853bfb3fa307b', 'Longest, with the softest first sound'),
('performance_listening_notes', 558, 'note_en', '95b38947993ee324d8dced1f751f8292ab5ce38ce59094aa347d831258ba0afe', 'At 4:17, it runs more than 30 seconds longer than the other two. It opens with the softest first sound, and right after singing its loudest, it sets down to its smallest.'),
('performance_listening_notes', 558, 'facts_en', '95b38947993ee324d8dced1f751f8292ab5ce38ce59094aa347d831258ba0afe', '["Münchner Rundfunkorchester"]'),
('performance_listening_notes', 563, 'headline_en', 'f6753151e8a3fbd3b558058d223c1638dfde1347ead63f00b686e0a54338de8b', 'Loud early in the introduction'),
('performance_listening_notes', 563, 'note_en', '915be4ca598337670a8b27647abb571e6e94675032c652021415a03bbcf2c442', 'It reaches near maximum in the introduction, before the other two. The loudest sound is saved for the final rush.'),
('performance_listening_notes', 563, 'facts_en', '915be4ca598337670a8b27647abb571e6e94675032c652021415a03bbcf2c442', '["Berlin Phil"]'),
('performance_listening_notes', 564, 'headline_en', '1990c9c977b57f7a3e73b0acf8a0c5ee14f3b60da4e407963bfcc7645555e052', 'Saved until the closing chord'),
('performance_listening_notes', 564, 'note_en', 'e69248fc844f9803e48689552e9e95f27488cfe80cf9b8a00fbb54f23477cbf8', 'At 8:50, the shortest of the three. It holds the level back through the main body, then rings out loudest only on the closing chord.'),
('performance_listening_notes', 564, 'facts_en', 'e69248fc844f9803e48689552e9e95f27488cfe80cf9b8a00fbb54f23477cbf8', '["Chamber Orchestra of Europe"]'),
('performance_listening_notes', 565, 'headline_en', '351eab706b4a77ec97865a2baad95d5eaec52788dbb035fe53a6c670ccd63aa4', 'A late burst'),
('performance_listening_notes', 565, 'note_en', '00e554657803a6af689a9e85aca5dc21dc90897ffac52993200e2c17e8ca2c56', 'It bursts out at its loudest later than the other two. It builds up through several rises and falls, then holds that level to the end.'),
('performance_listening_notes', 565, 'facts_en', '00e554657803a6af689a9e85aca5dc21dc90897ffac52993200e2c17e8ca2c56', '["Berlin Phil"]'),
('performance_listening_notes', 566, 'headline_en', 'b6e0c11dd4f94bfbbdb08171214e6005e2199d6424de18966f34e4b5666f2734', 'Hushed timpani, early maximum'),
('performance_listening_notes', 566, 'note_en', '6c0d0384adf5cde8428d3109cf312febba08b8b5e128525b9a815117b102a665', 'The first timpani stroke is the softest of the three. Even so, it reaches near maximum the earliest, and the gap between quiet and loud is the largest.'),
('performance_listening_notes', 566, 'facts_en', '6c0d0384adf5cde8428d3109cf312febba08b8b5e128525b9a815117b102a665', '["Vienna Phil"]'),
('performance_listening_notes', 567, 'headline_en', 'ae5646f04297c7f0edd27c59d15c90c53d8e7aa7efadefb0921a7858c31d3257', 'Loud at the start and at the end'),
('performance_listening_notes', 567, 'note_en', '3121319c29cdf9940495b9617c4ed81d667e70e4ca03094da6fbbdb4f6f3d229', 'It already rings out its loudest early on and closes just as loudly. It sustains loud playing longer than the other two.'),
('performance_listening_notes', 567, 'facts_en', '3121319c29cdf9940495b9617c4ed81d667e70e4ca03094da6fbbdb4f6f3d229', '["New York Phil"]'),
('performance_listening_notes', 568, 'headline_en', '0611fbf2f0c247e2be6a2d9b402cd496f20400117a796f6a8d294e4174022d32', 'Shortest, and loud the longest'),
('performance_listening_notes', 568, 'note_en', 'a8329dfa140d4b53eefef88f0d126c92051f3a284a0835ee4b110b71d8e6d3c9', 'At 1:49, it is about 10 seconds shorter than the other two. Unlike Davis, it starts less softly and sustains loud playing for a long time.'),
('performance_listening_notes', 568, 'facts_en', 'a8329dfa140d4b53eefef88f0d126c92051f3a284a0835ee4b110b71d8e6d3c9', '["Boston Symphony"]'),
('performance_listening_notes', 569, 'headline_en', '7025a9b0cf6ead2a2d6def8770014751e5db464bd2e3e568e7b56d9fb5453382', 'The lowest dip at the same spot'),
('performance_listening_notes', 569, 'note_en', 'e07f4df44be572317bd08038a7f08f7c11fbc946ab381e7de46e9453115cb9a0', 'It pulls the same quiet spot back the lowest of the three. After that it builds again and rings out loudest late on.'),
('performance_listening_notes', 569, 'facts_en', 'e07f4df44be572317bd08038a7f08f7c11fbc946ab381e7de46e9453115cb9a0', '["Kammerakademie Potsdam"]'),
('performance_listening_notes', 570, 'headline_en', '2bd8676b18967e527dd55b12c663f139ffee27c6ebd4832813845689219b288e', 'The climax at the end'),
('performance_listening_notes', 570, 'note_en', '8f53811117745e89f9ae879cb1e08a92c12a48bb9be4ca683abf0777d1e291de', 'At 1:37, it is about 23 seconds shorter than the other two. It alone places the climax near the end.'),
('performance_listening_notes', 571, 'headline_en', '619eec1991371c01ba7f3a8491c775f432cde6b5d4c0ef94bd516fac2738e22e', 'An even level to the end'),
('performance_listening_notes', 571, 'note_en', 'ce6f1fabc55150397b2a71bb8dfa99f81a66b8616c0a8f05f0d049f00f294ab9', 'Its dynamic range is narrower than the other two, and it sustains loud playing more than twice as long. The loudest sound also comes early, in the first third.'),
('performance_listening_notes', 571, 'facts_en', 'ce6f1fabc55150397b2a71bb8dfa99f81a66b8616c0a8f05f0d049f00f294ab9', '["Stadlmair · Munich Chamber Orchestra"]'),
('performance_listening_notes', 572, 'headline_en', '6638704ba14b0a42ef024fd5ba0f45a11a7a65ee8aa0f03b71a7b6ce170d8dcc', 'About 6 seconds longer'),
('performance_listening_notes', 572, 'note_en', '21a98b6f3c25fe235e4bff1ca931375a48c9212aa6da6c80bd9eb71f0b68cee2', 'At 2:01, it runs about 6 seconds longer than the other two. It starts building again right after the quiet spot and rings out loudest toward the end.'),
('performance_listening_notes', 572, 'facts_en', '21a98b6f3c25fe235e4bff1ca931375a48c9212aa6da6c80bd9eb71f0b68cee2', '["Brown · Academy of St Martin in the Fields"]'),
('performance_listening_notes', 573, 'headline_en', 'c2311e2012b887de1567ec9b7c79d48b78babceae12cee1a98574a4692d668c9', 'Twice more at the level of the first tutti'),
('performance_listening_notes', 573, 'note_en', '700a91fb824c42eedeb864d72b613840d2c8aaf2e62b338f6311cd132f80e4c4', 'It strikes near maximum from the first tutti and rises back to that level twice more later. It holds loud playing the longest of the three.'),
('performance_listening_notes', 573, 'facts_en', '700a91fb824c42eedeb864d72b613840d2c8aaf2e62b338f6311cd132f80e4c4', '["Müller-Brühl · Cologne Chamber Orchestra"]'),
('performance_listening_notes', 574, 'headline_en', '26a2eaf3b76bce2277d882540678a14eda40bc7feff9480f1892374073512a3a', 'A deep dip after the first tutti'),
('performance_listening_notes', 574, 'note_en', '9900bcae0a9ee64fb44032c7504e3ac608cd780ba82c06c7c152e1b6fd13e58d', 'After striking the first tutti the loudest, it pulls the middle back deeper than the other two. It also sets down the softest ending.'),
('performance_listening_notes', 574, 'facts_en', '9900bcae0a9ee64fb44032c7504e3ac608cd780ba82c06c7c152e1b6fd13e58d', '["Prague Chamber Orchestra"]'),
('performance_listening_notes', 575, 'headline_en', '7dc0b869c93ab83b70fa258a2a5c4a9c2afa5a420e7e503e468a6da12f65468e', 'The softest signal'),
('performance_listening_notes', 575, 'note_en', '5b6b89a301b79d4b7dce341d8468068b5d16d3e6beedc9e0547b6d6a929ba8ed', 'It opens with the softest signal of the three. It keeps a high level even after the top of the crescendo, ending louder than Rattle.'),
('performance_listening_notes', 575, 'facts_en', '5b6b89a301b79d4b7dce341d8468068b5d16d3e6beedc9e0547b6d6a929ba8ed', '["London Symphony"]'),
('performance_listening_notes', 576, 'headline_en', '862a765598e240f634c215393cf3f43c587e68840830a8757af360d6b08643d0', 'The climax in the second verse'),
('performance_listening_notes', 576, 'note_en', 'd9b5483413749f87322616a419941cdd779afc6b29ba0c130789222a58b4a4ba', 'Unlike Gorchakova and Sukmanova, it sings loudest in the second verse. The start and end are also the softest of the three.'),
('performance_listening_notes', 576, 'facts_en', 'd9b5483413749f87322616a419941cdd779afc6b29ba0c130789222a58b4a4ba', '["Rostropovich (piano)"]'),
('performance_listening_notes', 577, 'headline_en', '863464716a68aa61cc8b8b9c4641a8b846b18b8af3de222927ec81909f10e576', 'The climax in the first verse'),
('performance_listening_notes', 577, 'note_en', '08465035135c8d702b6bc2b8d7c87123962512041577f241d147fc067587f392', 'At 3:27, it is 14 seconds longer than Sukmanova. It sings loudest in the first verse and a little lower in the second.'),
('performance_listening_notes', 577, 'facts_en', '08465035135c8d702b6bc2b8d7c87123962512041577f241d147fc067587f392', '["Gergieva (piano)"]'),
('performance_listening_notes', 578, 'headline_en', '174640edd598713f0e923c2ddea3da22f8709a283dffab904e6675feb4b6f302', 'Near maximum again 20 seconds after the climax'),
('performance_listening_notes', 578, 'note_en', 'bba839eeade50b3c0913268bf46eab0b71da26e7160baa062333bf6e7d64596c', 'The shape is almost the same as Davis''s. Twenty seconds after the climax it rises to near maximum once more.'),
('performance_listening_notes', 578, 'facts_en', 'bba839eeade50b3c0913268bf46eab0b71da26e7160baa062333bf6e7d64596c', '["London Symphony"]'),
('performance_listening_notes', 579, 'headline_en', 'a48be747b32caad67e637031cbfb4edb824bc831581a0dcee9173e98a8755929', 'Near maximum two minutes sooner'),
('performance_listening_notes', 579, 'note_en', '1663c10cfaebff81a2bf8cbffc8753595a98fe9e08d5250b43b3a50f8fb78954', 'At 7:35, the shortest of the three. It also reaches near maximum more than two minutes earlier than the other two.'),
('performance_listening_notes', 579, 'facts_en', '1663c10cfaebff81a2bf8cbffc8753595a98fe9e08d5250b43b3a50f8fb78954', '["New York Phil"]'),
('performance_listening_notes', 580, 'headline_en', '8fec6526a7a54e8e9042df7090d3c50b00343c3a5898c1ccdf5eebb340be1132', 'A climax just before the end'),
('performance_listening_notes', 580, 'note_en', '4f602c36102d5cc186230571aa593b82ba15123a9848e35f353ca1bf4e443cf2', 'It holds the climax back until a few seconds before the end. Before that, it sinks very low once, then builds all the way to the end.'),
('performance_listening_notes', 580, 'facts_en', '4f602c36102d5cc186230571aa593b82ba15123a9848e35f353ca1bf4e443cf2', '["Montreal Symphony"]'),
('performance_listening_notes', 581, 'headline_en', '700b1ae0ff944ccbbe9aed23543e32ef5f2e38e19ac1b6f3e81b231cb5a4d4e9', 'Two verses at a similar level'),
('performance_listening_notes', 581, 'note_en', '07c58a979b733457c9d2c19e3d1b2cf8a137e9801c145b7d53bc0e97e0faa30e', 'The second verse is sung nearly as loudly as the first. The gap between quiet and loud is narrower than in the other two.'),
('performance_listening_notes', 582, 'headline_en', 'b9cc0c3b9c83b944bee9830608c70b825caaf4b380310296521c8cf64f5adc76', 'The softest love song'),
('performance_listening_notes', 582, 'note_en', '51e7d409aab8122e7ddc604d14e54727f41b1d711e175bb8499187db638ecd40', 'It plays the slow song softer than the other two, so the gap between quiet and loud is the largest. From there it grows a step at a time to the end.'),
('performance_listening_notes', 582, 'facts_en', '51e7d409aab8122e7ddc604d14e54727f41b1d711e175bb8499187db638ecd40', '["Berlin Phil"]'),
('performance_listening_notes', 583, 'headline_en', 'e6546ffdbfb45132e5328c2e21a480e7d225bc376e5ac436bbd72d83aa220afb', 'Nearly 40 seconds shorter'),
('performance_listening_notes', 583, 'note_en', '59db72bc0c554964886872c28926587a3cb62b56a7033016f245dd190b758cf4', 'At 4:11, it is nearly 40 seconds shorter than the other two. It sinks deep before the crescendo, then places the loudest sound at the very end.'),
('performance_listening_notes', 583, 'facts_en', '59db72bc0c554964886872c28926587a3cb62b56a7033016f245dd190b758cf4', '["Berlin Phil"]'),
('performance_listening_notes', 584, 'headline_en', '9735a70b51c586000d711607b0c9acf398d990b5bc5e6b74cfad908e86d101d5', 'Not rising again after the Sultan'),
('performance_listening_notes', 584, 'note_en', '94c0493c6db4258634ec42a2b0bb0df808c8c755af4797b5648ddcb207c587fb', 'After the Sultan''s theme it doesn''t rise loudly again. The later part, where the sea music appears, is also kept softer than with Karajan and Gergiev.'),
('performance_listening_notes', 584, 'facts_en', '94c0493c6db4258634ec42a2b0bb0df808c8c755af4797b5648ddcb207c587fb', '["Chicago Symphony"]'),
('performance_listening_notes', 585, 'headline_en', '3ffc48b9572834e40c2fd0aa1bc06c6320284f35534e96c0d1a0882d7f97f2b9', 'Building steadily toward the end'),
('performance_listening_notes', 585, 'note_en', '24a39580d6c3d510b83de145bf3c8f811022d4bfb78a942d444a64b42db262a2', 'After the middle, it builds steadily toward the end. The last third is louder than in the other two.'),
('performance_listening_notes', 585, 'facts_en', '24a39580d6c3d510b83de145bf3c8f811022d4bfb78a942d444a64b42db262a2', '["Berlin Phil"]'),
('performance_listening_notes', 586, 'headline_en', 'a1d9715e09fdbf1d30e6fbd1ba6ffa6791a20da278b5d2d09fe9ce7f319155cf', 'The deepest middle'),
('performance_listening_notes', 586, 'note_en', 'd9112b6f79007450814ddb3fc1789832dc6e01bf3b4366445aeb96be75a3b397', 'At 2:14, it runs about 12 seconds longer than the other two. It sinks the middle the lowest of the three, then rises again at the end.'),
('performance_listening_notes', 586, 'facts_en', 'd9112b6f79007450814ddb3fc1789832dc6e01bf3b4366445aeb96be75a3b397', '["Mariinsky"]'),
('performance_listening_notes', 587, 'headline_en', '99ba5b6f298a4b1b36e1270da3b0e7a6145dd796573a47f630c3d1abc4105551', 'Near maximum once in the middle'),
('performance_listening_notes', 587, 'note_en', '1bf357ed950fd646790e0c751b3f3f2ab2181787f63b33f069d186ad1a2efc6e', 'It rises to near maximum once in the middle. It holds loud playing for the longest time of the three.'),
('performance_listening_notes', 587, 'facts_en', '1bf357ed950fd646790e0c751b3f3f2ab2181787f63b33f069d186ad1a2efc6e', '["Royal Concertgebouw"]'),
('performance_listening_notes', 588, 'headline_en', '1866ae63f70514d5003fb7e686194178ab2dfb025f845ac5a6f94ffa3cfa35b9', 'Maximum from the first whirl'),
('performance_listening_notes', 588, 'note_en', 'aca45a4580cc02442952cc7b3ac36437e78cd9434de44680e0806ef8d9859432', 'At 8:33, it is about a minute shorter than the other two. It enters at near maximum from the first whirl, and the dawn passage is also less soft.'),
('performance_listening_notes', 588, 'facts_en', 'aca45a4580cc02442952cc7b3ac36437e78cd9434de44680e0806ef8d9859432', '["Pittsburgh Symphony"]'),
('performance_listening_notes', 590, 'headline_en', '718a925c4219419bc5f7c3e2fc3279ddaac047cdb1435279b74140b8372ea369', 'Long, with a deep drop'),
('performance_listening_notes', 590, 'note_en', 'c1961d397fd28eb4177a76a61fc90e05f984b2f9aa256db2ee10148401fabd44', 'At 1:44, it is longer than the other two. After the loud sound in the middle it sinks the deepest, then rises to the last chord.'),
('performance_listening_notes', 590, 'facts_en', 'c1961d397fd28eb4177a76a61fc90e05f984b2f9aa256db2ee10148401fabd44', '["London Symphony"]'),
('performance_listening_notes', 592, 'headline_en', 'd2cc47778c3f61c59b831197550fcefbf93e3cf5f27adc1758823dfa9bb21145', 'A whirl one step lower'),
('performance_listening_notes', 592, 'note_en', 'cecefeb99a575dbc1fa3e0f2b188fff28bc1f325cf8d427e4973f9bb1444c789', 'It opens the first whirl one step lower and reaches near maximum in 16 seconds. The dawn passage is pulled back much softer than with Reiner.'),
('performance_listening_notes', 592, 'facts_en', 'cecefeb99a575dbc1fa3e0f2b188fff28bc1f325cf8d427e4973f9bb1444c789', '["Royal Phil"]'),
('performance_listening_notes', 594, 'headline_en', '09fa5c4878229ed3dfdd060cf06681a178729530bad16e12f2f82cefea9ae668', 'Maximum just before the last chord'),
('performance_listening_notes', 594, 'note_en', 'efe689493a6810a3436235692e46c0506d1883a9781f28ad6150308a58460f62', 'In the middle it stops just short of near maximum. It first reaches near maximum only a few seconds before the last chord.'),
('performance_listening_notes', 594, 'facts_en', 'efe689493a6810a3436235692e46c0506d1883a9781f28ad6150308a58460f62', '["Philadelphia"]'),
('performance_listening_notes', 595, 'headline_en', 'd80a3e8e819a14bfb0270f4da85b71a4b83f96eb7c8c8bbc9b77c7f639672729', 'Two minutes held back'),
('performance_listening_notes', 595, 'note_en', 'e2c803cf422e9911d1a90711f65602e488ab721c3614edd638d5166888d70fd1', 'It holds back for about two minutes before reaching near maximum. It places the climax earliest of the three and sinks the dawn passage the softest.'),
('performance_listening_notes', 595, 'facts_en', 'e2c803cf422e9911d1a90711f65602e488ab721c3614edd638d5166888d70fd1', '["Berlin Phil"]'),
('performance_listening_notes', 596, 'headline_en', 'ef92405390aa5abee9de64f6262889040a4b258a7dfd581785e5c89f7282d004', 'A less hushed opening, an early build'),
('performance_listening_notes', 596, 'note_en', 'f7589006904e8a353cf95b74b356d58de89cae8ea99c7ece08ab6a2451c4f64c', 'It starts less softly than Rostropovich and Mørk. Before the big orchestral passage it builds ahead of time once, then rises.'),
('performance_listening_notes', 596, 'facts_en', 'f7589006904e8a353cf95b74b356d58de89cae8ea99c7ece08ab6a2451c4f64c', '["Harding · Mahler Chamber Orchestra"]'),
('performance_listening_notes', 597, 'headline_en', '3e1adbe74d85f5ad25f0e82fc85a0663b6267ad22cb79465ed1b14b4abebf8ba', 'A brief orchestral passage'),
('performance_listening_notes', 597, 'note_en', '32eb1a9b4f30343c08609089cee8366c45bed25db7f262f6875d9d54aec41187', 'It reaches near maximum later than the other two, only just before the climax. It also cuts the big orchestral passage short.'),
('performance_listening_notes', 597, 'facts_en', '32eb1a9b4f30343c08609089cee8366c45bed25db7f262f6875d9d54aec41187', '["Jansons · Oslo Phil"]'),
('performance_listening_notes', 598, 'headline_en', 'e2b1c1f201cfa5f85864db9fbeb3bf70db22a22344d67962a0a879a6684aa771', 'Early maximum, a rest later'),
('performance_listening_notes', 598, 'note_en', 'b62cdf3b11c6b4208e8d2fcb3b70777a259f3d9eb4f987e256488d032bb90376', 'Reaches near maximum in 20 seconds. Later on it drops deep once, then builds again.'),
('performance_listening_notes', 599, 'headline_en', '7ade143e96b6090cc7437a56662dbfbd5bdc4f41c2db6aef4be51cfbfd43b93c', 'Loud to the end'),
('performance_listening_notes', 599, 'note_en', '038859ec2e2c7dab5534d42c8c43ee9835992fe3a5f959fe97039db1d89e3822', 'The gap between quiet and loud is the smallest of the three. It holds loud playing the longest and ends the loudest.'),
('performance_listening_notes', 600, 'headline_en', '9b33b5447102e527f29a1d863dffaa29546c9250938a396a193ca09d00c8dd67', 'Building again late on'),
('performance_listening_notes', 600, 'note_en', '72c605f0b7479f95e83bdcb5d0a0fb32ed75ecb76196b02e5839bcfeab22dd35', 'It keeps the melodic passage after the chords soft for a long while, then builds up again later, louder than the other two.'),
('performance_listening_notes', 600, 'facts_en', '72c605f0b7479f95e83bdcb5d0a0fb32ed75ecb76196b02e5839bcfeab22dd35', '["Berlin Phil"]'),
('performance_listening_notes', 601, 'headline_en', 'b596fac381910408f22a69e71d8507a6aa4d00fc5b6a4eb00db0b65431f05531', 'Softest after the chords'),
('performance_listening_notes', 601, 'note_en', 'de5d407e893788fb1751024c29a55a0d1a7dd6bdf58627bd9ffe8ec1c836991e', 'It carries the melodic passage after the chords the softest of the three. It ends the softest too.'),
('performance_listening_notes', 601, 'facts_en', 'de5d407e893788fb1751024c29a55a0d1a7dd6bdf58627bd9ffe8ec1c836991e', '["Chicago Symphony"]'),
('performance_listening_notes', 602, 'headline_en', '5cfb222e0205ed330fbf9a33dfcdac9acd2d7285a8fbd10fac0247d2d34dbae5', 'The big orchestral passage held longest'),
('performance_listening_notes', 602, 'note_en', '12c1b2ec10a24c03945f91ff24dd00ec314db477856cd4b1a23a477f4b1da8d4', 'It holds the big orchestral passage the longest of the three. After reaching near maximum, it stays loud for nearly 30 seconds up to the climax.'),
('performance_listening_notes', 602, 'facts_en', '12c1b2ec10a24c03945f91ff24dd00ec314db477856cd4b1a23a477f4b1da8d4', '["Karajan · Berlin Phil"]'),
('performance_listening_notes', 603, 'headline_en', '50deba73b9f30966f1bb71164aa356d7c26aaeb9f7ce9c7ccdf3d37745805e17', 'More than 15 seconds shorter'),
('performance_listening_notes', 603, 'note_en', 'ba5664ee73c7f3e848a0c1ab06f2a3b154b7ba088a3392718024fe387421c9c3', 'At 1:42, it is more than 15 seconds shorter than the other two. Its quiet passages don''t sink as low as Solti''s.'),
('performance_listening_notes', 603, 'facts_en', 'ba5664ee73c7f3e848a0c1ab06f2a3b154b7ba088a3392718024fe387421c9c3', '["Vienna Phil"]'),
('performance_listening_notes', 604, 'headline_en', '138e3d92277ea14ba1a8e7b46a79f5e66ef9c9cf9614ced80d8a62430e2ae8fb', 'The climax in the exact middle'),
('performance_listening_notes', 604, 'note_en', 'a186b92db476e2212bebc4a2759d602331245138b3ab323f2355799dcd801a32', 'It is very soft from the first sound. It reaches the climax in the exact middle, more than 45 seconds later than the other two.'),
('performance_listening_notes', 605, 'headline_en', 'd073b7788c20b1ae01cf16e33e64fc4914fa15a2c384c647af7e285fe866dc0e', 'An even 2:57'),
('performance_listening_notes', 605, 'note_en', 'ca1c23f03456c061af0fe078b9a0b4fae6c0cc5abb1516fac5a9ef5e16fd97fb', 'At 2:57, the longest of the three. It continues at a similar level, evenly, and reaches near maximum later than the other two.'),
('performance_listening_notes', 606, 'headline_en', 'd903b21a730a4f1f6ad48d253007523ad195b742b13aba8cbb2b92fc60f3153a', 'Building gradually and early'),
('performance_listening_notes', 606, 'note_en', '4bd40d5040c2e12d1084288e2894b9904f6dccbcf1a3a3d65ba4167820b30852', 'It holds the opening down less than the other two and builds little by little. It also begins its big swell sooner than Muti and Chailly.'),
('performance_listening_notes', 606, 'facts_en', '4bd40d5040c2e12d1084288e2894b9904f6dccbcf1a3a3d65ba4167820b30852', '["Vienna Phil"]'),
('performance_listening_notes', 607, 'headline_en', '2a5f7b2210f3cbaa2bb88986a1911eea6df4d4607a7666733fb75e2f71677432', 'Held down the lowest'),
('performance_listening_notes', 607, 'note_en', '564d4bc5a7c8784375f6b194832f32159360426828e3b68147746d328d94749d', 'It holds the opening the lowest of the three and sinks deep once more in the middle. As a result, the gap with the end is the largest.'),
('performance_listening_notes', 607, 'facts_en', '564d4bc5a7c8784375f6b194832f32159360426828e3b68147746d328d94749d', '["Berlin Phil"]'),
('performance_listening_notes', 608, 'headline_en', 'f56b3f6fd7d6e8745a69bc3cdec1c08da7d196d24b62048a01d0ca9a94d6fcf6', 'Softest at start and finish'),
('performance_listening_notes', 608, 'note_en', '1c3bcae8cc35b27628a6cd90f0412b55bf06c847de68d56e0d7d85b06b7ddd05', 'At 2:33, it is 24 seconds shorter than Lympany. The start and end are the softest, and it lifts loudly just once, in the middle.'),
('performance_listening_notes', 610, 'headline_en', '8ad5cfc97cdfdb12e3c3db29ddee5bf39d92f0e0663e791f44506e3544ffd8e7', 'Late, and all at once'),
('performance_listening_notes', 610, 'note_en', '246a7e2e4218446b035a9f5b24ee171aedb7f3277e80f45496757bdd3808f145', 'It starts to grow 11 seconds later than Böhm. It builds up all at once in the last 15 seconds or so.'),
('performance_listening_notes', 610, 'facts_en', '246a7e2e4218446b035a9f5b24ee171aedb7f3277e80f45496757bdd3808f145', '["Concertgebouw"]'),
('performance_listening_notes', 612, 'headline_en', 'c5eb3ad4c7b618993dfac4c63cb186916e472483ec256bc081f410c2d8d9441c', 'Loud once more after the climax'),
('performance_listening_notes', 612, 'note_en', '82a50048b262891e6afba79819f69c03d38488cac481abaf638c67d592efdc48', 'After the climax it rises once more to almost that level. The ending is also less soft than Firkušný''s.'),
('performance_listening_notes', 614, 'headline_en', 'ec14cb2b8af1946783b9ba6610bbf7415dd087d60cfa7bf65562ecad2c3c9a5f', 'Longest, with a late climax'),
('performance_listening_notes', 614, 'note_en', '50009e8a5b403960979509e1265c0fb2af08f0a1ed5b5e49504f8a6dc3d411c5', 'At 3:18, the longest of the three. It sinks the middle the lowest and places the loudest sound late.'),
('performance_listening_notes', 614, 'facts_en', '50009e8a5b403960979509e1265c0fb2af08f0a1ed5b5e49504f8a6dc3d411c5', '["Gardiner"]'),
('performance_listening_notes', 615, 'headline_en', '54db4270758a7977c12df8526f61ea992380cb83ec585cd168cd65b709bab8bd', 'Nearly 20 seconds at maximum'),
('performance_listening_notes', 615, 'note_en', '745ff11ecf2f0bfbb44a8a2719f121d853c9cd37fa103e6a4a48e3e49a34e066', 'It stays at near maximum for nearly 20 seconds and reaches the climax the latest of the three. The gap between quiet and loud is the largest too.'),
('performance_listening_notes', 615, 'facts_en', '745ff11ecf2f0bfbb44a8a2719f121d853c9cd37fa103e6a4a48e3e49a34e066', '["San Francisco Symphony"]'),
('performance_listening_notes', 616, 'headline_en', '6de1559a4a7cf9a6bed3f22c2b989c008fd788fe9b033294ca0ccf63d7935b86', 'A less hushed middle too'),
('performance_listening_notes', 616, 'note_en', '34171899d5f56aa131197ee4dac00d84b98be48c2ffc76724e2da6dc88ab8a6b', 'It keeps the gap between quiet and loud small. The middle doesn''t sink as deep as in the other two.'),
('performance_listening_notes', 616, 'facts_en', '34171899d5f56aa131197ee4dac00d84b98be48c2ffc76724e2da6dc88ab8a6b', '["Kļava"]'),
('performance_listening_notes', 617, 'headline_en', '90df19f50cd9edc3105ec291fa7c79af04f0030a80acbd04023ab3f58317eaa2', 'A long-held outburst'),
('performance_listening_notes', 617, 'note_en', '6cb63ac3848aa0a0ea47316a5fe91314c1f8ea9392cd5828e73b0d6e8b615d6d', 'After the climax it keeps the outburst going for a long time at a level one step lower. The middle passage is also louder than in the other two.'),
('performance_listening_notes', 617, 'facts_en', '6cb63ac3848aa0a0ea47316a5fe91314c1f8ea9392cd5828e73b0d6e8b615d6d', '["Berlin Phil"]'),
('performance_listening_notes', 618, 'headline_en', '766fb1872dfc14976ea12a0ceb041d96244d3de850c5de1f912948bd5ef4dc1e', 'A shallower middle'),
('performance_listening_notes', 618, 'note_en', 'a3c8e530d7d1fd2ec9b4882a7d9ef0f4ec099f541cf348df31bb0d1b4c368ff2', 'It pulls the middle back less than the other two. From there it builds step by step and drives hardest at the end.'),
('performance_listening_notes', 618, 'facts_en', 'a3c8e530d7d1fd2ec9b4882a7d9ef0f4ec099f541cf348df31bb0d1b4c368ff2', '["Vienna Phil"]'),
('performance_listening_notes', 619, 'headline_en', '45592fe615a7e90a1f00ad7db10cb4ab76ca782b3cfe498c2ca36b7b88be8ee0', 'A short outburst'),
('performance_listening_notes', 619, 'note_en', '2a7b3b784bbf0dbdce5b275f5e113c7703cb9a47041dcec8b8db9acfd4fa5e1c', 'Unlike Karajan, it cuts the outburst short. It sets the level down soon after the climax and carries the march on at an even level.'),
('performance_listening_notes', 619, 'facts_en', '2a7b3b784bbf0dbdce5b275f5e113c7703cb9a47041dcec8b8db9acfd4fa5e1c', '["Boston Symphony"]'),
('performance_listening_notes', 620, 'headline_en', '98992b396f3ed6ce4fed8338f886300f953f5865d2ea8f1894f684ff1f9ab8e4', 'A deep middle, then one lift at the end'),
('performance_listening_notes', 620, 'note_en', 'f5eba9e5bb3885fdfd2278a0fc47c61ec0ee75c44ca986a59566752d828525f7', 'It sinks the middle the deepest of the three. In the last 20 seconds or so it pulls the level up all at once.'),
('performance_listening_notes', 620, 'facts_en', 'f5eba9e5bb3885fdfd2278a0fc47c61ec0ee75c44ca986a59566752d828525f7', '["Chicago Symphony"]'),
('performance_listening_notes', 621, 'headline_en', '26a00c9e55730ed4abdd1c0fb3e1c35db6dce7af1942ee8755375b3344d30c99', 'Sinking right after the climax'),
('performance_listening_notes', 621, 'note_en', 'ef59800cee97f230cb8ab7ea01563f00d75da1d3cd062075b16077f3d65a752a', 'At 2:53, it is 25 seconds shorter than the Monteverdi Choir. Loud passages are brief, and 7 seconds after the climax it sinks deep.'),
('performance_listening_notes', 621, 'facts_en', 'ef59800cee97f230cb8ab7ea01563f00d75da1d3cd062075b16077f3d65a752a', '["Layton"]'),
('performance_listening_notes', 622, 'headline_en', '0e8382359ac41ecf337c9b8a94cd25fb8e555f914e1f11f090fdf491c16931a4', 'The loudest opening'),
('performance_listening_notes', 622, 'note_en', '4695caf79a8a69b0a22e54e0416b3f588fe391785d2d8ef115f8cd7aefd3fac7', 'It pushes louder than the other two from the very start. After dropping back, it is also the first to start building again, stacking up over 30 seconds.'),
('performance_listening_notes', 622, 'facts_en', '4695caf79a8a69b0a22e54e0416b3f588fe391785d2d8ef115f8cd7aefd3fac7', '["London Symphony"]'),
('performance_listening_notes', 623, 'headline_en', 'e8ba51f32dccb429cfcceca9869f945dbb9aed93a26f903538a85c7872be791c', 'The middle one step higher'),
('performance_listening_notes', 623, 'note_en', '14b0d8efbe75588b5bfef205e15a974dffb8b7b898da213c5ab95793e6e91c86', 'The shape is almost the same as Haitink''s. But it opens the first sustained note much louder, and the middle also sits one step higher.'),
('performance_listening_notes', 623, 'facts_en', '14b0d8efbe75588b5bfef205e15a974dffb8b7b898da213c5ab95793e6e91c86', '["Boston Symphony"]'),
('performance_listening_notes', 624, 'headline_en', '00fcf31cd41ceedf7d0b7c86fa2500f4a46c669e7fcb581526be199a4e70e85f', 'A late arrival at maximum'),
('performance_listening_notes', 624, 'note_en', '6e9d6f992ee1009f86177ecb017e07b61d2aaea4742a8ae4903cf090baff970d', 'The first cry opens the lowest of the three, and it reaches near maximum only after more than 30 seconds. After the climax it eases down once, then rises again.'),
('performance_listening_notes', 624, 'facts_en', '6e9d6f992ee1009f86177ecb017e07b61d2aaea4742a8ae4903cf090baff970d', '["Rundfunkchor Berlin · Berlin Phil"]'),
('performance_listening_notes', 625, 'headline_en', '6cee2c7adedb45f382e0079cbdd0aff4e7c758b0cae792fd4a0f07ba308ae9f2', 'Maximum in the exact middle'),
('performance_listening_notes', 625, 'note_en', '6762e0fb2784e4eb9e259d9642fc6a8f86c080707acdce06f8f8f07dceee7101', 'It places the loudest sound in the exact middle. From there it steps down, and the latter part sits lower than with Solti and Bernstein.'),
('performance_listening_notes', 625, 'facts_en', '6762e0fb2784e4eb9e259d9642fc6a8f86c080707acdce06f8f8f07dceee7101', '["Berlin Phil"]'),
('performance_listening_notes', 626, 'headline_en', '8ce4dcefd3a4e4a6d35dca077b4501f40315044388613a0bd1b3a2b8e677bf0b', 'Maximum on the first signal'),
('performance_listening_notes', 626, 'note_en', '25d35a5a787aa0a8c1d98194d1049f83ccea4d4a9279ee6f2c4495b7c70094eb', 'It blasts at maximum from the horn signal. It holds loud playing the longest of the three.'),
('performance_listening_notes', 626, 'facts_en', '25d35a5a787aa0a8c1d98194d1049f83ccea4d4a9279ee6f2c4495b7c70094eb', '["Chicago Symphony"]'),
('performance_listening_notes', 627, 'headline_en', '7816b11d0b38fdb8ffe1bf47b2895ad24a4f282e0fe53557e924f626e2bcec12', 'Near maximum in 36 seconds'),
('performance_listening_notes', 627, 'note_en', 'fcb3936a602b0a184a5c0d62afc7ae204fba017059363ffbf06df3728508e008', 'At 1:49, the shortest of the three. It reaches near maximum in 36 seconds and holds loud playing much longer than the other two.'),
('performance_listening_notes', 627, 'facts_en', 'fcb3936a602b0a184a5c0d62afc7ae204fba017059363ffbf06df3728508e008', '["San Francisco Symphony"]'),
('performance_listening_notes', 628, 'headline_en', '3bd465075086dfe82431b11d6b6ac35d2d8c024ea33bd19acec5842fc0fc3641', 'Even through all of 1:19'),
('performance_listening_notes', 628, 'note_en', '333bfec609960742aba93febf971e1a767fc8a8a5ac95d50e38624ef552877fd', 'At 1:19, it is 9 seconds shorter than Abbado. It enters at near maximum from the first cry and pushes on evenly to the end.'),
('performance_listening_notes', 628, 'facts_en', '333bfec609960742aba93febf971e1a767fc8a8a5ac95d50e38624ef552877fd', '["LA Master Chorale · LA Phil"]'),
('performance_listening_notes', 629, 'headline_en', '845ae2e59a6e8bfe45fbcb36e798b8a13c20c3b264922962ede87cb2a3e20c35', 'A big drop at the end'),
('performance_listening_notes', 629, 'note_en', '364dd2fdc9b0d6931f7c6d1638e2093e7f72ddcf027ddf77e5dbe0f61b2b8c2c', 'Entering at near maximum from the first cry is the same as with Dudamel. The ending is set down much softer than in the other two.'),
('performance_listening_notes', 629, 'facts_en', '364dd2fdc9b0d6931f7c6d1638e2093e7f72ddcf027ddf77e5dbe0f61b2b8c2c', '["Vienna State Opera Chorus · Chicago Symphony"]'),
('performance_listening_notes', 630, 'headline_en', 'c1df83f2f401b3e6190cced456fb366377acd757d781b283d9b18bb85ff8e544', 'Maximum at the end'),
('performance_listening_notes', 630, 'note_en', '5e12b22aba0a344e5a41b4eb97cb595b50c84217bc7617c1438c678df6284c1d', 'It carries the early part loudly, then steps down. It begins to grow in the last few seconds and blasts to its loudest within 4 seconds.'),
('performance_listening_notes', 630, 'facts_en', '5e12b22aba0a344e5a41b4eb97cb595b50c84217bc7617c1438c678df6284c1d', '["Vienna Phil"]'),
('performance_listening_notes', 631, 'headline_en', 'b1087eeff38e9637c6d3fa8ecf4a330d29a7ff377b01efde122066441d1bcd8c', 'The softest opening drone'),
('performance_listening_notes', 631, 'note_en', '9ea93f708187934de39484d95ee69a4e3d4fe9d26eabb3bf29e48bcc1c493257', 'The first drone opens very softly. It stays small for nearly a minute, then rises all the way to the climax in one go.'),
('performance_listening_notes', 631, 'facts_en', '9ea93f708187934de39484d95ee69a4e3d4fe9d26eabb3bf29e48bcc1c493257', '["Berlin Phil"]'),
('performance_listening_notes', 633, 'headline_en', '3412d7f94c89fd6e5e0810c1752c410f43a681b66e9f954a232d25bcf9daa0b9', 'The climax up front'),
('performance_listening_notes', 633, 'note_en', 'c66359190a2473930c877e26dbfa061a9288455ca3ecd0f0d6154a44f37e22a2', 'It places the climax early, in the first big passage of the introduction. It doesn''t rise that high again later.'),
('performance_listening_notes', 633, 'facts_en', 'c66359190a2473930c877e26dbfa061a9288455ca3ecd0f0d6154a44f37e22a2', '["Vienna Phil"]'),
('performance_listening_notes', 634, 'headline_en', '5901fe5381f2aea278708ed12a8a266ba6ef06c557a41250dfc3c7889fc42372', 'Softest and longest'),
('performance_listening_notes', 634, 'note_en', 'fd97c37bdb8f29ddedd9468756854e716ce1ea95cce912c024588cf8cb779765', 'It starts the softest of the three and runs about 10 seconds longer than the other two. Before the end it sinks deep once, then rises to its loudest.'),
('performance_listening_notes', 634, 'facts_en', 'fd97c37bdb8f29ddedd9468756854e716ce1ea95cce912c024588cf8cb779765', '["Argerich (piano)"]'),
('performance_listening_notes', 635, 'headline_en', '49865541efaba5882a19dc0c23bc163630c8336c7ecb59e1f948ba39620b4473', 'Clear from the first sound'),
('performance_listening_notes', 635, 'note_en', '798edae97c0d98fb2dc7585428a93c2de5ca48041a4daa982a5096cb1d6f5869', 'The first sound is louder than in the other two. After taking a breath once before the end, it pushes loudly to the finish.'),
('performance_listening_notes', 635, 'facts_en', '798edae97c0d98fb2dc7585428a93c2de5ca48041a4daa982a5096cb1d6f5869', '["Orkis (piano)"]'),
('performance_listening_notes', 637, 'headline_en', 'b7a395ee4244c921d66c69ce74b3a8ac3ece0655ab5dcbf671e43babcda2d98b', 'A little earlier than Mutter'),
('performance_listening_notes', 637, 'note_en', '31b3b203a355e0671cf3e1668875742a9c4c7923e4ea69ff9387c0680b17807e', 'The shape is almost the same as Mutter''s. It reaches near maximum a little earlier than Mutter and sustains loud playing longer.'),
('performance_listening_notes', 637, 'facts_en', '31b3b203a355e0671cf3e1668875742a9c4c7923e4ea69ff9387c0680b17807e', '["Thibaudet (piano)"]'),
('performance_listening_notes', 639, 'headline_en', '1d8ac92c431b3c0b406d8906bfa422c9495729ebb50a551c8e1adbed5f69e74b', 'The softest tremolo'),
('performance_listening_notes', 639, 'note_en', 'a54e7f79501b61f44fda75b0e8e5c6b78fab040a111ba79d936ade792a35a047', 'It opens the tremolo the softest of the three and, at 1:49, is the shortest. The gap between quiet and loud is the largest too.'),
('performance_listening_notes', 639, 'facts_en', 'a54e7f79501b61f44fda75b0e8e5c6b78fab040a111ba79d936ade792a35a047', '["Berlin Phil"]'),
('performance_listening_notes', 640, 'headline_en', '2d186c2e098522fe21859ffdf9cf965923494761d24afcfca7ea8b4fdb10a00c', 'Twice at the same level'),
('performance_listening_notes', 640, 'note_en', 'd9bc72b606060d8042376d2ca441f4d2cdb1aef4cfcdc5617bb57ba7b7aa5d8e', 'It lifts the big passages at the start and the end to almost the same level both times. The climax comes later than in the other two.'),
('performance_listening_notes', 640, 'facts_en', 'd9bc72b606060d8042376d2ca441f4d2cdb1aef4cfcdc5617bb57ba7b7aa5d8e', '["New York Phil"]'),
('performance_listening_notes', 644, 'headline_en', '9e997916ea972eb5dae535dd6c16426ba0c98e13a5e057ca8d9f8859d0b5d3b2', 'A prayer of 4:17'),
('performance_listening_notes', 644, 'note_en', '98013d0fdad874c8a2e907669186a28db73ab2b1088e6ce65f5abdbded5f00e5', 'At 4:17, it runs more than 35 seconds longer than the other two. The first sound is the least soft of the three, and the climax is placed late.'),
('performance_listening_notes', 644, 'facts_en', '98013d0fdad874c8a2e907669186a28db73ab2b1088e6ce65f5abdbded5f00e5', '["Lucia Popp · Dresden Staatskapelle"]'),
('performance_listening_notes', 645, 'headline_en', 'd155179d964ad70db417e7d8098517a1b5c1869889cbe403697538c9133a8ebf', 'The shortest prayer'),
('performance_listening_notes', 645, 'note_en', '89ea41fd4dc388420132e1224cfb3ceaa42278166fd0adcb4dc2725f35928008', 'At 3:27, it is 50 seconds shorter than Davis. It opens the widest gap between quiet and loud and sings its loudest line late.'),
('performance_listening_notes', 645, 'facts_en', '89ea41fd4dc388420132e1224cfb3ceaa42278166fd0adcb4dc2725f35928008', '["Sheila Armstrong · Orchestre de Paris"]'),
('performance_listening_notes', 646, 'headline_en', 'fbc4c5755f3f1d65401c4d11e94d0eef15b25fe06e6f6b87e2a53e492cf32175', 'Maximum within a minute'),
('performance_listening_notes', 646, 'note_en', '06a8d7704c3477b892e470c59e1e9fbc75abe424a8e61a73e4f4b7b7f94fccae', 'It sings its loudest within a minute, alone in placing the climax early. After that it reaches near maximum twice more.'),
('performance_listening_notes', 646, 'facts_en', '06a8d7704c3477b892e470c59e1e9fbc75abe424a8e61a73e4f4b7b7f94fccae', '["Kiri Te Kanawa · Montreal Symphony"]'),
('performance_listening_notes', 647, 'headline_en', '876ab506babfa17978ab4608914806f023930663ab0a2b8d70114347a3357f1d', 'Near maximum from the first line'),
('performance_listening_notes', 647, 'note_en', '0614d0cea96b43a9055a78f675b83ff438d419e8d75a2c5272db1cb748033e39', 'At 2:40, it is more than 30 seconds shorter than the other two. It sings at near maximum from the first line and places loud passages evenly several times.'),
('performance_listening_notes', 647, 'facts_en', '0614d0cea96b43a9055a78f675b83ff438d419e8d75a2c5272db1cb748033e39', '["Tharaud (piano)"]'),
('performance_listening_notes', 648, 'headline_en', 'a70365dc2654e762f44e4a57119fab1617a6073626162591cf0ffe39328d2c33', 'A pace more than 40 seconds longer'),
('performance_listening_notes', 648, 'note_en', '9be9209b2b8d273a7112e08030a38a3a9228db3c03c29b01ad5a5929278ad134', 'At 6:59, it runs more than 40 seconds longer than the other two. It carries the big passage in the middle through without any big drop.'),
('performance_listening_notes', 648, 'facts_en', '9be9209b2b8d273a7112e08030a38a3a9228db3c03c29b01ad5a5929278ad134', '["Philadelphia"]'),
('performance_listening_notes', 649, 'headline_en', 'a455bb1e760366c47a1340ebfcd03c0e3646b6111f26da3e724d9c65efbcab1f', 'Loud again near the end'),
('performance_listening_notes', 649, 'note_en', 'e78544325dff1c367be8ce2bda85566024c9888fc349783cd060971390a223cf', 'Unlike the other two, it sings loudly once more near the end. The ending also doesn''t get as soft as with Isserlis and Yo-Yo Ma.'),
('performance_listening_notes', 649, 'facts_en', 'e78544325dff1c367be8ce2bda85566024c9888fc349783cd060971390a223cf', '["Dalberto (piano)"]'),
('performance_listening_notes', 650, 'headline_en', 'b30cb02c5af1e8264a6fc2c2f8e11c361e5bebea83a9ffd22fa101c5b7cc545b', 'The longest rendition'),
('performance_listening_notes', 650, 'note_en', '026a5e83c6958e0cd78ecf08571a7bda7b871472068e97998e9825d42a11a626', 'At 3:20, the longest of the three. It sings loudest past the middle and lifts loudly once more before the end.'),
('performance_listening_notes', 650, 'facts_en', '026a5e83c6958e0cd78ecf08571a7bda7b871472068e97998e9825d42a11a626', '["Thibaudet (piano)"]'),
('performance_listening_notes', 651, 'headline_en', '884a86e69e21b447bf3062b289a4527c58a8f46e678b239a851318dbae910e33', 'Loudest in the first melody'),
('performance_listening_notes', 651, 'note_en', '1c0a69808a7dab4d3a3b8eae9fbce136063ac699d7b2376b68c44397a8ea8535', 'It starts the softest of the three yet sings its loudest within the first melody. The other two place their loudest singing later.'),
('performance_listening_notes', 651, 'facts_en', '1c0a69808a7dab4d3a3b8eae9fbce136063ac699d7b2376b68c44397a8ea8535', '["Devoyon (piano)"]'),
('performance_listening_notes', 652, 'headline_en', '670a604bd50ef9eb63964044ce63023f754408d0d5433a2244e4521a6c36a30b', '3:28, with a mid-piece climax'),
('performance_listening_notes', 652, 'note_en', '2f609f5d49241ba829c9204427682f9b0c9d65bcbd2544a7783bec2e1786e9d5', 'At 3:28, it is about 15 seconds shorter than the other two. The loudest singing comes at the end of the middle section.'),
('performance_listening_notes', 652, 'facts_en', '2f609f5d49241ba829c9204427682f9b0c9d65bcbd2544a7783bec2e1786e9d5', '["Stott (piano)"]'),
('performance_listening_notes', 653, 'headline_en', '9037576565419eb0c69f08da638d1598c403eb05ff77fe503105bbebe5742f53', 'The deepest dip inside the big passage'),
('performance_listening_notes', 653, 'note_en', '4f57dd1ae36de9b466a4db0c0b1eb236f2d17f342d48a1f37c0787d3096339a3', 'It keeps the opening the softest of the three. Even within the big passage it pulls back lower than the other two, then rises again to its loudest.'),
('performance_listening_notes', 653, 'facts_en', '4f57dd1ae36de9b466a4db0c0b1eb236f2d17f342d48a1f37c0787d3096339a3', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 654, 'headline_en', '1ab96747f927bbed6ed2d98cf5eda74229a8b6107a14cb8405d2aff8e15f6114', 'A pizzicato opening softly'),
('performance_listening_notes', 654, 'note_en', 'a30e4da1cc2ac61af73a9fe0dd5660014503a931b8a3935d364b015737ffd298', 'The first sound is softer than in the other two. It rises to its loudest in the middle, and doesn''t pull back as deep inside the big passage as Marriner does.'),
('performance_listening_notes', 654, 'facts_en', 'a30e4da1cc2ac61af73a9fe0dd5660014503a931b8a3935d364b015737ffd298', '["San Francisco Symphony"]'),
('performance_listening_notes', 655, 'headline_en', 'f3f67bcc486d4420a601dc9222277f2c40f5a9ac49c6af72abd9b9a046324359', 'A brief climax'),
('performance_listening_notes', 655, 'note_en', '7beaa4de7a62573a572b64b9c09d93f3b848214f63db9621430219942c44044a', 'The shape is almost the same as Fleming''s. After the climax it drops back once more, so loud playing is briefer than in the other two.'),
('performance_listening_notes', 655, 'facts_en', '7beaa4de7a62573a572b64b9c09d93f3b848214f63db9621430219942c44044a', '["Dalberto (piano)"]'),
('performance_listening_notes', 656, 'headline_en', '9e1b3a3484ee9432ab20b5e7d4794283183a998e2d4245cd83426e3aa251c0cb', '2:01, pulling back twice'),
('performance_listening_notes', 656, 'note_en', '8d407bc5d84bd191593acee804a0668f1d0e830fe4602aec53139c14199449a1', 'At 2:01, the longest of the three. After the climax it pulls back twice, then rises again toward the end.'),
('performance_listening_notes', 656, 'facts_en', '8d407bc5d84bd191593acee804a0668f1d0e830fe4602aec53139c14199449a1', '["Benedict Klöckner"]'),
('performance_listening_notes', 657, 'headline_en', '1198511e6af575aea7eafb709f7364931a7363823039466470c8fbbcf6546612', 'Early maximum, lower afterward'),
('performance_listening_notes', 657, 'note_en', 'af3b6b234bed700d8301e3078ca2b168fda80109f8007d2331586a25d2da1504', 'It reaches near maximum before Schirmer and Pressler. After the climax it keeps the latter part low and closes softly.'),
('performance_listening_notes', 657, 'facts_en', 'af3b6b234bed700d8301e3078ca2b168fda80109f8007d2331586a25d2da1504', '["Mutter · Ferrández"]'),
('performance_listening_notes', 658, 'headline_en', '9fb79927a9a64368be8f29fac92fba4b6155dd283655fb783ff415e7a963cf1f', 'Short, with a loud start'),
('performance_listening_notes', 658, 'note_en', 'b5e3647e3676dafe4b76cbac6443fe2713ba93d7bbba03f65feb7f3bbb9c68cd', 'It is about 10 seconds shorter than the other two. It strikes its loudest early and rises to the same level twice more.'),
('performance_listening_notes', 658, 'facts_en', 'b5e3647e3676dafe4b76cbac6443fe2713ba93d7bbba03f65feb7f3bbb9c68cd', '["New York Phil"]'),
('performance_listening_notes', 659, 'headline_en', 'ce643cdc58f4bbb7839f409d9d2a89713380231f151e6b7c8ac2f3ed0b1c0b32', 'The climax placed late'),
('performance_listening_notes', 659, 'note_en', '749dd6c5c9878d0bc404f888c23e247984919f7ef0feb49fa0e13abfcc203a21', 'It alone places the loudest sound late. After that it sinks the deepest of the three.'),
('performance_listening_notes', 659, 'facts_en', '749dd6c5c9878d0bc404f888c23e247984919f7ef0feb49fa0e13abfcc203a21', '["Mathieson · Royal Liverpool Phil"]'),
('performance_listening_notes', 660, 'headline_en', 'e22e786a4ce442bc03e7777fd5aca92250e8d907c409ea93caf7b08003064c0d', 'The ending set far down'),
('performance_listening_notes', 660, 'note_en', '7019592d350123ec772de8a0df24c5a3a41a595f149baa7e6550dccb965f3f0f', 'It places its loudest sound late and sets down the softest ending of the three. The shape is almost the same as Haitink''s.'),
('performance_listening_notes', 660, 'facts_en', '7019592d350123ec772de8a0df24c5a3a41a595f149baa7e6550dccb965f3f0f', '["Montreal Symphony"]'),
('performance_listening_notes', 661, 'headline_en', '1078f779db3b030e2bb97d8304f819a2ec6d626658da1f42cd4c37e51ec869c6', 'The climax at the opening'),
('performance_listening_notes', 661, 'note_en', 'e143710c031ccab1ef00f72ee1420c2a593b2baf7238ce3006e23ec1bf45f391', 'It opens at near maximum from the first chord and places the loudest sound at the start as well. The middle rises and falls one step lower.'),
('performance_listening_notes', 661, 'facts_en', 'e143710c031ccab1ef00f72ee1420c2a593b2baf7238ce3006e23ec1bf45f391', '["Wordsworth · BBC Concert Orchestra"]'),
('performance_listening_notes', 662, 'headline_en', 'd8a2bc13caf105588c28e77009513fba2c4f0e7f2384757d2c14910facc8901f', 'Near maximum from the first chord'),
('performance_listening_notes', 662, 'note_en', '53bfa7e356037a01f219e460ce35dfc1fbad6ed4180403f406903625f22b80fd', 'It enters at near maximum from the first chord and rises three times to similar levels. It strikes the third the loudest.'),
('performance_listening_notes', 662, 'facts_en', '53bfa7e356037a01f219e460ce35dfc1fbad6ed4180403f406903625f22b80fd', '["Concertgebouw"]'),
('performance_listening_notes', 663, 'headline_en', '1f3b748bb361d1a7992ed2a009400cccf902580ccf8588f90d6d49f24c9b18b0', 'Reaching for near maximum twice'),
('performance_listening_notes', 663, 'note_en', 'f18f3b9bd098a2ad8a6cea8612292ac3946c818ce4f153a560940be6ff42ed06', 'After rising to its loudest at the opening, it reaches for near maximum again. It also sustains loud playing longer than Parham and Kanneh-Mason.'),
('performance_listening_notes', 663, 'facts_en', 'f18f3b9bd098a2ad8a6cea8612292ac3946c818ce4f153a560940be6ff42ed06', '["Tasmanian Symphony"]'),
('performance_listening_notes', 664, 'headline_en', 'e8a1fe73a442db37d91332b972e697e8b02f49ebec8a50d1b407af82a21c6db4', 'Pushing on most evenly'),
('performance_listening_notes', 664, 'note_en', 'adee488dece0085304b7239dec6cf815f9a5e1c38782dcd5871aafb23472007a', 'The first sound is less soft than in the other two. It keeps the range between quiet and loud small and reaches maximum once more near the end.'),
('performance_listening_notes', 664, 'facts_en', 'adee488dece0085304b7239dec6cf815f9a5e1c38782dcd5871aafb23472007a', '["Beaux Arts Trio"]'),
('performance_listening_notes', 665, 'headline_en', '8edad9382a42ae054cb182813d8e58ecb268ed5ded48929dfd99ad6acd77bec9', '2:42, with a soft opening'),
('performance_listening_notes', 665, 'note_en', 'a74f5acfbe23356155a7ca299a17119e8b542b1d6af3cf502c84354dab46e77f', 'At 2:42, it is about 15 seconds shorter than the other two. It opens the softest of the three and sings its loudest in under a minute.'),
('performance_listening_notes', 665, 'facts_en', 'a74f5acfbe23356155a7ca299a17119e8b542b1d6af3cf502c84354dab46e77f', '["Ott (piano)"]'),
('performance_listening_notes', 666, 'headline_en', '414132cf8d171d3787b387da6ee3d2a8ee5e070492812e2632bc9dc7ddf3661b', 'The loudest first chord'),
('performance_listening_notes', 666, 'note_en', '591c245e82bc4be380922b0fd606a1a160a3226d22592caaee8ea3ca9fcc94d3', 'It alone sounds the first chord at its loudest. The driving passage around the one-minute mark is met at nearly the same level.'),
('performance_listening_notes', 666, 'facts_en', '591c245e82bc4be380922b0fd606a1a160a3226d22592caaee8ea3ca9fcc94d3', '["Slatkin · London Symphony"]'),
('performance_listening_notes', 667, 'headline_en', '054eb3761a1c6c32a6da9ae5a55c39d573feebd75850be2d12b7c40341ab8123', 'A big drop after the climax'),
('performance_listening_notes', 667, 'note_en', '43f9e1eb7cec2fe1e05d212929c761f9af63d137123d6696c87bb6444ae18b82', 'At 2:01, it runs about 7 seconds longer than the other two. After its loudest strike it drops the most of the three, then climbs again.'),
('performance_listening_notes', 667, 'facts_en', '43f9e1eb7cec2fe1e05d212929c761f9af63d137123d6696c87bb6444ae18b82', '["Dutoit · London Phil"]'),
('performance_listening_notes', 668, 'headline_en', 'be804674b28d8dfec3fb966dc12f200f71d15c99e60756c39d99061b3fbea85d', 'Loud playing held long'),
('performance_listening_notes', 668, 'note_en', '336b281a9dc18d91a1f441a49ac427684ff7967b0fcb7f62c4031721295ac7d0', 'It holds loud playing the longest of the three. In under 30 seconds it surges to near maximum again, and around the one-minute mark it strikes its loudest.'),
('performance_listening_notes', 668, 'facts_en', '336b281a9dc18d91a1f441a49ac427684ff7967b0fcb7f62c4031721295ac7d0', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 669, 'headline_en', '9c7ab8042bc111bc1301da256ffa9ce5963a43a9df6baf50489847995a76a536', 'Even to the end'),
('performance_listening_notes', 669, 'note_en', '83b8e88c6d3dbe551b0fa0368621308b685f5262fee79c92017ef38c0b16e860', 'Even in the quiet passages it doesn''t sink as low as the other two. In the later part too, it carries the song along without cutting the level much.'),
('performance_listening_notes', 669, 'facts_en', '83b8e88c6d3dbe551b0fa0368621308b685f5262fee79c92017ef38c0b16e860', '["Yeol Eum Son (piano)"]'),
('performance_listening_notes', 670, 'headline_en', 'c10b64e141b1a6e4a1a50b0f038f286d568850936752782d2260410af22e4e58', 'The deepest dip late on'),
('performance_listening_notes', 670, 'note_en', 'f985bdcbc4fb291f46db9f35c8972f0bee1e428bd208077fba631054bd8e3d50', 'It sinks the quiet passage late in the piece deeper than the other two. From there it rises again to close the song.'),
('performance_listening_notes', 670, 'facts_en', 'f985bdcbc4fb291f46db9f35c8972f0bee1e428bd208077fba631054bd8e3d50', '["Pappano (piano)"]'),
('performance_listening_notes', 671, 'headline_en', 'ee6d4b5b8a356fe39dc4e3e9ee2968510c84aef7432cbc2a933a3981d0fd52aa', 'Strength in the second big passage'),
('performance_listening_notes', 671, 'note_en', 'c95a519a7e6341e4355c25c13e257e6000b081912ad75cf6def1df1c0a0350e6', 'It keeps the first big passage lower than the other two and strikes its loudest in the second.'),
('performance_listening_notes', 671, 'facts_en', 'c95a519a7e6341e4355c25c13e257e6000b081912ad75cf6def1df1c0a0350e6', '["Esser · Vienna Symphony"]'),
('performance_listening_notes', 672, 'headline_en', '5650f442765f10fa3dc0c8c9e1bc2a57f8a0058b42668c107ae8d9cf234e03bd', 'Settling deep after the climax'),
('performance_listening_notes', 672, 'note_en', '9a399f12512365d1aa7ee6ec514f7f7668b373c73e6a05985514ac1635bc950d', 'It reaches near maximum later than the other two. After the climax it settles lower than Midori and Bell and stays soft to the end.'),
('performance_listening_notes', 672, 'facts_en', '9a399f12512365d1aa7ee6ec514f7f7668b373c73e6a05985514ac1635bc950d', '["Foster · Royal Phil"]'),
('performance_listening_notes', 673, 'headline_en', '8e1d51983bb3f755fd04e72f5a71cc8cd7032900e3a391bdcfb2bc6958ca2602', 'Sinking, then building up'),
('performance_listening_notes', 673, 'note_en', '9415aaec34c8e2dabf5a6612e1b77955e3304fe09d9f30b990aa8f248cbe62b4', 'It sinks the middle deep, then builds up steadily, placing the climax later than the other two.'),
('performance_listening_notes', 673, 'facts_en', '9415aaec34c8e2dabf5a6612e1b77955e3304fe09d9f30b990aa8f248cbe62b4', '["Oue · NDR Radiophilharmonie"]'),
('performance_listening_notes', 674, 'headline_en', '3c58bc6d872afe0eab0a9dff8c279d0dc300d30bce08bf3c6e178e33c5d6583f', 'Building all the way to the end'),
('performance_listening_notes', 674, 'note_en', '91416b9aaf8d09a61ca949cfa8649ab4408bac902d0d17f6bc44e704d87dc3fb', 'The shape is the same as Seong-Jin Cho''s, but about 20 seconds shorter. After sinking deep in the middle, it builds all the way to the end and strikes its loudest at the very end.'),
('performance_listening_notes', 675, 'headline_en', '0ee5960c73fc30b9bf0ff62eb0f1d6589a82007c11eb38e1287313d2acdd9f40', 'The most even of the three'),
('performance_listening_notes', 675, 'note_en', '4ced2caa26abdb3ed96a829ddfd20ea9f5dc856ce8635a77fe5cb6d591b9ea5c', 'The gap between quiet and loud is the smallest of the three, and the middle sinks the least. It reaches near maximum the earliest and holds it to the end.'),
('performance_listening_notes', 676, 'headline_en', 'dee52dc85cf86eb441d5c21cbf8d2483bc6f1445cc3b931c5652d8fd35bedbeb', 'A deep, long middle'),
('performance_listening_notes', 676, 'note_en', '2e8714cfb1bb3b72568a7008249af6fce60c7c064dc1b5523ec21acd2bb309bf', 'At 2:19, it runs more than 20 seconds longer than the other two. It opens softly and sinks the middle deeper than Bavouzet and Thibaudet.'),
('performance_listening_notes', 677, 'headline_en', 'eddd7a60d0ba2117dcb716bc0f7f70ff9b624908ec96facf268212358f221c11', 'The smallest first sound'),
('performance_listening_notes', 677, 'note_en', 'cd936ff401264dfc54e293df853ee02e8d18137f6b89edde2a0fa3e4995704cc', 'The first sound is the smallest of the three. Around the 30-second mark it steps up a level, stays there for a long while, then surges once.'),
('performance_listening_notes', 677, 'facts_en', 'cd936ff401264dfc54e293df853ee02e8d18137f6b89edde2a0fa3e4995704cc', '["Royal Concertgebouw"]'),
('performance_listening_notes', 678, 'headline_en', '7c7a22b728ce04b7ee0e7b6b5b1f6564ff8b882861b4dd62cedab5d7625bd36b', 'A less subdued opening'),
('performance_listening_notes', 678, 'note_en', 'c9b990ead1c2b33f966f88edf6274ec79521825128e813249e88c1116ba6078c', 'At 2:01, it is 15 seconds longer than Abbado. The opening doesn''t sink as low as in the other two, and it builds for nearly the last 20 seconds.'),
('performance_listening_notes', 678, 'facts_en', 'c9b990ead1c2b33f966f88edf6274ec79521825128e813249e88c1116ba6078c', '["Royal Concertgebouw"]'),
('performance_listening_notes', 679, 'headline_en', '566ea4f67d858d878cf148ff990097b3d70af0e3fdc22b16743474be47eac5f0', 'Shortest and smallest'),
('performance_listening_notes', 679, 'note_en', '7afd38b51059261947d19c217c485dc2007780d2b4f6ad85a4021e9e00a6f2f9', 'At 1:46, the shortest of the three. It sinks the lowest at the start and keeps the middle soft too.'),
('performance_listening_notes', 679, 'facts_en', '7afd38b51059261947d19c217c485dc2007780d2b4f6ad85a4021e9e00a6f2f9', '["Pahud (flute) · Berlin Phil"]'),
('performance_listening_notes', 680, 'headline_en', '46cc9bbdcf881509c93801e07dd811c3377e62af420661f9c0b299e63cef324d', 'Dipping just before the surge'),
('performance_listening_notes', 680, 'note_en', 'dbcc3aa949e074d97975373dbeb14e6f4e3dd5a27d797d0d10a53337aa6035d5', 'At two minutes, it is longer than the other two. It stays soft for over a minute, drops to its smallest just before the surge, then rises.'),
('performance_listening_notes', 680, 'facts_en', 'dbcc3aa949e074d97975373dbeb14e6f4e3dd5a27d797d0d10a53337aa6035d5', '["Berlin Phil"]'),
('performance_listening_notes', 681, 'headline_en', '3a160ca10628cdfadcb59c8c5ca0907672d246cc43b91cb249666df8b98e2282', '1:37, surging early'),
('performance_listening_notes', 681, 'note_en', 'ed412250446209179bb39d942a6787a426cfd47abc93e1b8425728dac4ce6668', 'At 1:37, it is more than 20 seconds shorter than Karajan. It starts to grow about 10 seconds earlier than the other two and surges first.'),
('performance_listening_notes', 681, 'facts_en', 'ed412250446209179bb39d942a6787a426cfd47abc93e1b8425728dac4ce6668', '["Montreal Symphony"]'),
('performance_listening_notes', 682, 'headline_en', 'b35e4f3f10c65022e9bfc26c838a05c481fab80ca7b8416c746f9a7338ee7a56', 'A hushed first flute'),
('performance_listening_notes', 682, 'note_en', 'f89d0530e53b6993fc564cff67f10c65c0300eacb68f88fb5e87b6f30fdc86ff', 'The first flute is softer than in the other two. After a deep pause early on, it steps up one level at a time to the end.'),
('performance_listening_notes', 682, 'facts_en', 'f89d0530e53b6993fc564cff67f10c65c0300eacb68f88fb5e87b6f30fdc86ff', '["Hutchins (flute) · Montreal"]'),
('performance_listening_notes', 683, 'headline_en', '79080257f7fea2f438608291ad2ebacc13c6f9eb5e08517e5c212d6a9f3e410e', 'The middle song sunk deep'),
('performance_listening_notes', 683, 'note_en', '215f1611ff13126aa70a9813c53dbd7f9710eb4cd74b77ba2fbff45c12a49d13', 'It sinks the middle song the deepest of the three. The loudest sound is in the returning march, and it ends the softest too.'),
('performance_listening_notes', 684, 'headline_en', '98d336dae3625008fa03f1842ad64e606b122f7b2cd1b1d5f1ba738c13927e3e', 'A brief single maximum'),
('performance_listening_notes', 684, 'note_en', '6e87e5349ebdb58b03aaa07eea5e3b0d7d8b9d9f3c41e6bd0afe054578ae7cfb', 'At 2:52, it runs 11 seconds longer than the other two. Loud playing is brief, and it reaches near maximum later than Yuja Wang and Lang Lang.'),
('performance_listening_notes', 684, 'facts_en', '6e87e5349ebdb58b03aaa07eea5e3b0d7d8b9d9f3c41e6bd0afe054578ae7cfb', '["Nézet-Séguin · Philadelphia"]'),
('performance_listening_notes', 685, 'headline_en', 'c0cf452cd92e538955a3be67467f1f072a5a19d724cf4de10910c44716664be0', 'Matching marches at start and end'),
('performance_listening_notes', 685, 'note_en', '980f2b8b7a372b3f507251f4762558c04586a8b70bced62a96b658905a08f060', 'It rises to its loudest in the first march and plays the returning march at the same level. Unlike Shelley, it leaves the ending loud.'),
('performance_listening_notes', 686, 'headline_en', 'd5bc604a1a851f0851e20b887a49a6c435523567c40974b44df51a19eac3bcda', 'The middle kept loud too'),
('performance_listening_notes', 686, 'note_en', '69347b17dbe4ff0add2f1298ac6400139e11c53dce6452fcde9f7c17801f9ad1', 'The middle song also sinks less than in the other two. It also holds loud playing for the longest time.'),
('performance_listening_notes', 687, 'headline_en', '3dc605a246b2ccaa0ec7b94c918eaf85feeed7bbcb7916485dc03edecb062ea5', 'The loudest middle'),
('performance_listening_notes', 687, 'note_en', 'da9567aab605a0360465f1b63b4f88ba7b3cc980edf342aebd81a8560f9fa545', 'It carries the middle third the loudest of the three. Even before the climax it drops the least of the three.'),
('performance_listening_notes', 687, 'facts_en', 'da9567aab605a0360465f1b63b4f88ba7b3cc980edf342aebd81a8560f9fa545', '["Dudamel · LA Phil"]'),
('performance_listening_notes', 688, 'headline_en', '78757b1a0c34a90745074a46a91479b2e3319512d5e63d74792ff90837250c53', 'A climax 18 seconds earlier'),
('performance_listening_notes', 688, 'note_en', 'efe3b3062ba83a49432328b7a1716cd067db52611c10dca2525d1440c696d145', 'It reaches the climax 18 seconds earlier than Yuja Wang. After the climax it sinks the softest and sets the ending down.'),
('performance_listening_notes', 688, 'facts_en', 'efe3b3062ba83a49432328b7a1716cd067db52611c10dca2525d1440c696d145', '["Gergiev · Mariinsky"]'),
('performance_listening_notes', 689, 'headline_en', 'f442548a8c7bb83341a05f50ec8fd7e18ab9ece686febd389ce1e4a4b47f0c52', '1:48, holding long'),
('performance_listening_notes', 689, 'note_en', 'd89221b60d84a44e2a12bc0e1e752918aaa7f9d5d6a4db98ab36be6b498e1485', 'At 1:48, the shortest of the three. It holds loud playing the longest, and the latter part sinks the least.'),
('performance_listening_notes', 689, 'facts_en', 'd89221b60d84a44e2a12bc0e1e752918aaa7f9d5d6a4db98ab36be6b498e1485', '["Dutoit · Montreal Symphony"]'),
('performance_listening_notes', 690, 'headline_en', '8ab422243cc9bf927323a4b66995712a84ed8258e176b1c14c1711def3b951bc', 'All at once in the last 5 seconds'),
('performance_listening_notes', 690, 'note_en', 'c13ee9648afbab98d791a14c0ef1633526fdf121ee6399fc866c8e31420d0aa3', 'The snare drum starts less softly than in the other two. It saves near maximum until 5 seconds before the end, then rises all at once.'),
('performance_listening_notes', 690, 'facts_en', 'c13ee9648afbab98d791a14c0ef1633526fdf121ee6399fc866c8e31420d0aa3', '["Chicago Symphony"]'),
('performance_listening_notes', 691, 'headline_en', 'c075c3c87086f289fb7c6099fed747369b39a4994fb8676fecbad4aec7094884', 'Sinking the lowest'),
('performance_listening_notes', 691, 'note_en', 'c005f659be5c2d461ffdfcc7a14f85ef8a376570fac21b2693be804bbc70f412', 'After blasting the first theme twice at near maximum, it pulls the relaxed passage back lower than Rogé and Seong-Jin Cho.'),
('performance_listening_notes', 691, 'facts_en', 'c005f659be5c2d461ffdfcc7a14f85ef8a376570fac21b2693be804bbc70f412', '["Abbado · Berlin Phil"]'),
('performance_listening_notes', 692, 'headline_en', '8c5643ce180dc155fe55d841d0f1b84034fd51fac9b26b3c6dfe716bed4ca4db', 'The softest first melody'),
('performance_listening_notes', 692, 'note_en', '5cfdef72ba935c014d33b363320e4781c105cc012176e6d4b7103b425170d166', 'It brings out the first melody the softest of the three. The gap between quiet and loud is also the largest of the three.'),
('performance_listening_notes', 693, 'headline_en', '60344b70f51974211741c9822fe34c9cf70fe42e37d23c22441c6ec8a72b6349', 'Even from the start'),
('performance_listening_notes', 693, 'note_en', 'c331077a74bcb78f2d93f27e1099098d8b472a7009a9c0dab2b1aaa00a3a5e12', 'It brings out the first melody louder than the other two. The gap between quiet and loud is also the smallest, so it flows evenly.'),
('performance_listening_notes', 694, 'headline_en', '31bcea2464f8633db5fbe991086be585a16f127550d1ca4495c99e4114e711ad', 'A long 4:37'),
('performance_listening_notes', 694, 'note_en', 'c48ee6c9a36a8aacf8e387457a76bde8d71043fe935a455af3027784dfe5025d', 'At 4:37, it runs more than 20 seconds longer than the other two. The shape is the same as Thibaudet''s, but the first melody is brought out a little louder.'),
('performance_listening_notes', 695, 'headline_en', '0ccbb269764c7ca25c5bc3faeafccce342d991fa6ec3bab1d85939836aa66939', 'Already at maximum by the middle'),
('performance_listening_notes', 695, 'note_en', 'a89f58af72352399f8e8c47896f2b3a9ffb5f15c5dad5b13e3964a19e0cd20b2', 'It already reaches near maximum in the exact middle. From there it doesn''t come down but holds evenly to the end.'),
('performance_listening_notes', 695, 'facts_en', 'a89f58af72352399f8e8c47896f2b3a9ffb5f15c5dad5b13e3964a19e0cd20b2', '["London Symphony"]'),
('performance_listening_notes', 696, 'headline_en', '419d4132296a8fed1cb2bd596ae3912f946d305684aa802182f9f70702935108', 'The second peak one step lower'),
('performance_listening_notes', 696, 'note_en', 'b0685056059c17ebde12d326db1752451fe0b1c0172883286bd6c939f128b6e5', 'At 2:01, it is 13 seconds longer than Rogé. After the first climax, it keeps the second one step lower and finishes less softly than the other two.'),
('performance_listening_notes', 696, 'facts_en', 'b0685056059c17ebde12d326db1752451fe0b1c0172883286bd6c939f128b6e5', '["Nelsons · Boston Symphony"]'),
('performance_listening_notes', 697, 'headline_en', '31e7c66c84633e968f42aed300948153befab15020115b871b22539c7c9d23c6', 'The softest snare drum'),
('performance_listening_notes', 697, 'note_en', 'b9a27af82d1c5cfc3cf5a3591a541a68c2a8ea793654b3e05e05681bafff437d', 'It starts the snare drum the softest of the three. It repeats the pattern of building up and then easing back three times.'),
('performance_listening_notes', 697, 'facts_en', 'b9a27af82d1c5cfc3cf5a3591a541a68c2a8ea793654b3e05e05681bafff437d', '["Berlin Phil"]'),
('performance_listening_notes', 698, 'headline_en', '8231838f77ca9b6b52eb9c0ba8d7b053838b75a8d8c8e8fda557d5173e38b130', 'The climax at the end of the first verse'),
('performance_listening_notes', 698, 'note_en', 'a07abe78352817dca2b837643f647a14493a3448f5e783c0a3d64ec1d9f0723d', 'It alone strikes the climax at the end of the first verse. The ends of the second and third verses are matched at nearly the same level.'),
('performance_listening_notes', 698, 'facts_en', 'a07abe78352817dca2b837643f647a14493a3448f5e783c0a3d64ec1d9f0723d', '["Rundfunkchor Berlin · Berlin Phil"]'),
('performance_listening_notes', 699, 'headline_en', 'cf5edff44f873f7d25d89f0e4f95e88cebbda518d4922fc2a258476e106fba2b', 'Building little by little from the start'),
('performance_listening_notes', 699, 'note_en', '00344bb088d74cd455f2546afdc6543165cd51cdd14a13f76e1521c904d0ebeb', 'It opens the softest of the three. From there it builds little by little and rises to its loudest around the middle.'),
('performance_listening_notes', 700, 'headline_en', '3804655866bb29394db2907c0b5315454e6a8e9f75345991372744319131ae82', 'Smallest right after the outburst'),
('performance_listening_notes', 700, 'note_en', 'de317a800579f3922572e6a99fed6d06378497dcafd2233b96cd1347dba9e519', 'The first cry is the loudest, and 10 seconds later it drops straight to its smallest level. It sinks the quiet passage the deepest of the three.'),
('performance_listening_notes', 700, 'facts_en', 'de317a800579f3922572e6a99fed6d06378497dcafd2233b96cd1347dba9e519', '["Philharmonia Chorus · Philharmonia"]'),
('performance_listening_notes', 701, 'headline_en', '6dd40f4023060a370096c02167d982a52d6820fd2ae008aea7789a44b0fd33bb', 'The deepest dip with every verse'),
('performance_listening_notes', 701, 'note_en', '139241e4cf99a4a595bb2290a2367802aafc7c8ccc57b449d527e45b1b3f6737', 'Each time a new verse begins, it sinks the softest of the three. It puts the loudest sound at the end of the last verse.'),
('performance_listening_notes', 701, 'facts_en', '139241e4cf99a4a595bb2290a2367802aafc7c8ccc57b449d527e45b1b3f6737', '["Philharmonia Chorus · Philharmonia"]'),
('performance_listening_notes', 702, 'headline_en', '11f10a89e61cfc04e41bfa75502a16cea92dba89a080a3d6bb3abb9e8a5b6974', 'Shallow dips between verses'),
('performance_listening_notes', 702, 'note_en', '6c27c3c0471d2853b0e427ba491691a6cbae414a2727cfd986f0a3f66f8cd8b7', 'Unlike Muti, it sinks only slightly between verses. The gap between quiet and loud is also the smallest.'),
('performance_listening_notes', 702, 'facts_en', '6c27c3c0471d2853b0e427ba491691a6cbae414a2727cfd986f0a3f66f8cd8b7', '["Chicago Symphony Chorus · Chicago Symphony"]'),
('performance_listening_notes', 703, 'headline_en', '4ae79f9b66e58fffe18f0a3df21d597c5f27fa8dd5ea14fbbbcc1e514de8d50f', 'Nearly 20 seconds shorter'),
('performance_listening_notes', 703, 'note_en', 'b26281afb162d18ec8a2c332600d26a3dc5ae2365fe6efe8921680759e39b285', 'At 2:20, it is nearly 20 seconds shorter than the other two. The quiet passage doesn''t sink as low as with Muti and Levine.'),
('performance_listening_notes', 703, 'facts_en', 'b26281afb162d18ec8a2c332600d26a3dc5ae2365fe6efe8921680759e39b285', '["Rundfunkchor Berlin · Berlin Phil"]'),
('performance_listening_notes', 704, 'headline_en', '0c8559bc273b19963784cc819ae0bbd4bc04be2974a502f41113f389b29df1e2', 'A minute longer'),
('performance_listening_notes', 704, 'note_en', 'b9b9be1b5ba9fa0db7cd6cca95def77f94ac1a217f42a97b6f7c7607fb6a75c3', 'At 6:04, it runs a minute longer than the other two. Its dynamic range is also narrower than Rogé''s and Thibaudet''s.'),
('performance_listening_notes', 705, 'headline_en', 'e4d910c9789c004ebb5516ca216e62b006f5962126a930a4ca892b667c89c3e3', 'The climax on the last cry'),
('performance_listening_notes', 705, 'note_en', '6e6e0938e09747fc8b27733107128c603657a776785aa88deaedd85d36a31790', 'Unlike the other two, it places the loudest sound on the last cry. It builds toward the end and bursts out at the very close.'),
('performance_listening_notes', 705, 'facts_en', '6e6e0938e09747fc8b27733107128c603657a776785aa88deaedd85d36a31790', '["Chicago Symphony Chorus · Chicago Symphony"]'),
('performance_listening_notes', 706, 'headline_en', '2c776a24105626ffa9856126d69609a199c729aa3907bd39d5d2713e4b283187', 'Near maximum in 30 seconds'),
('performance_listening_notes', 706, 'note_en', '47fdc1286c6eb4ac75564875edf956757bd43d5e16f30115fefa61bee192557c', 'It reaches near maximum in about 30 seconds, while the other two take over two minutes. Forty seconds after the climax it drops to its smallest level, then rises again to finish.'),
('performance_listening_notes', 708, 'headline_en', 'cf10ddb37bbeeebfd387a537236ca1c155242208459a986ab4f0213aa67a8f5f', 'Saved until the end, then loud'),
('performance_listening_notes', 708, 'note_en', 'e347d14d3b5a41c846dd016f074418a4d95f4ad6e45296bc31e615774266d685', 'It spares loud playing more than the other two and reaches near maximum 20 seconds later than Perlman. After a deep pause in the middle it builds up again.'),
('performance_listening_notes', 708, 'facts_en', 'e347d14d3b5a41c846dd016f074418a4d95f4ad6e45296bc31e615774266d685', '["Dutoit · Royal Phil"]'),
('performance_listening_notes', 710, 'headline_en', 'fb8ba61e3ff9bf3eb568c76f8f7d4c8b18316a2f01412d78e6a45e8394d519cc', 'The loudest ending'),
('performance_listening_notes', 710, 'note_en', '80e6a73d6979a5511c2aac258232c23d8e0a7ba7df7a3a3fdec03c0bc9f7f829', 'After pausing it rises loudly again and holds that level to the end. Its loud playing is the longest of the three, and its ending is the least soft.'),
('performance_listening_notes', 710, 'facts_en', '80e6a73d6979a5511c2aac258232c23d8e0a7ba7df7a3a3fdec03c0bc9f7f829', '["Mehta · New York Phil"]'),
('performance_listening_notes', 713, 'headline_en', '219e4a5fa5551cf7bdd28e7e7ffde76267541990e7db315b51a23df946f61c88', 'A climax just before the pause'),
('performance_listening_notes', 713, 'note_en', '1c6daf4d6d18b5eb37b7c4411a87074ababfb7d43c936306842940556059a23a', 'It alone strikes its loudest just before the pause in the middle. Right after, it sinks deeper than the other two.'),
('performance_listening_notes', 713, 'facts_en', '1c6daf4d6d18b5eb37b7c4411a87074ababfb7d43c936306842940556059a23a', '["Abbado · London Symphony"]'),
('performance_listening_notes', 716, 'headline_en', '0f5a1bc02a7307e8f26126cae51a96b6e2251a22d6d8ef122647c34c1739ef79', 'A mid-piece climax, an even flow'),
('performance_listening_notes', 716, 'note_en', '9c4ac5821ef3eecb5776dd4e6d9bca8f3b85c9b038c7c8044f8f212e1a6bca96', 'It alone places the loudest sound in the middle. It carries the front, middle and back at nearly the same level.'),
('performance_listening_notes', 717, 'headline_en', 'ff48c83f677f559bd1d1474a31693cd241fb48eba53a38f299f109a98e041c89', 'Long quiet stretch, then maximum in 10 seconds'),
('performance_listening_notes', 717, 'note_en', '4cc3a713fdb05d0b8985286ba0be717b0dca5a656fffa66670e22e77e2a4f5c2', 'It plays loud for the shortest time of the three. After the first chord it stays quiet for a long while, starts to swell near the back, and reaches its maximum within 10 seconds.'),
('performance_listening_notes', 717, 'facts_en', '4cc3a713fdb05d0b8985286ba0be717b0dca5a656fffa66670e22e77e2a4f5c2', '["Dallas Symphony · Chorus"]'),
('performance_listening_notes', 719, 'headline_en', 'e7f5ec8b37ef9deed751940128201023de2c6df90bc695ce09f7a090f591b6fd', 'Holds the loud sound the longest'),
('performance_listening_notes', 719, 'note_en', '2ad3b09884170a6117aa6e31ea0e9388d87fbd91b1517ee258ab98d6e9e70347', 'It rises straight to its loudest and holds loud playing longer than either of the other two. The middle drops by just one notch.'),
('performance_listening_notes', 721, 'headline_en', '639247bac61390bbb82d2338b0da2e7e9ed16e3d61d4e59c34014cb1d62e95b0', 'Early climax, deep middle'),
('performance_listening_notes', 721, 'note_en', '81d1776839d1b0435d280f3b4fbcf5b1340d7aa88e63585604bf874e327c4f44', 'It reaches its loudest within 9 seconds, then sinks the middle deeper than Hamelin does. From there it builds up again.'),
('performance_listening_notes', 722, 'headline_en', '5deae46d764ee0484b514a6fcaef0014d1a5de87b63311aa4160581f6321ac6e', 'The fastest pace'),
('performance_listening_notes', 722, 'note_en', '98bf6e7a1dbeccefa3ba54cedfff807890488ae410041488f4cd834a95ca2231', 'At 2:52 it is shorter than the other two. It starts out loud, and it begins to swell earlier than Litton and Tilson Thomas do.'),
('performance_listening_notes', 722, 'facts_en', '98bf6e7a1dbeccefa3ba54cedfff807890488ae410041488f4cd834a95ca2231', '["Boston Symphony · Tanglewood Festival Chorus"]'),
('performance_listening_notes', 724, 'headline_en', '5ad6782ab23fca4f72f4d21dd17ce946194bd10d7287e985da091a5a9f06a3e9', 'Rises in two stages'),
('performance_listening_notes', 724, 'note_en', '6c4a128fb77d2cb986580872153db4c05e92fd337a8a7a8e16160da374a0a4c6', 'At 3:31 it runs 39 seconds longer than Ozawa. It sinks the quiet passage at the start deep, then builds up in two stages.'),
('performance_listening_notes', 724, 'facts_en', '6c4a128fb77d2cb986580872153db4c05e92fd337a8a7a8e16160da374a0a4c6', '["San Francisco Symphony · Chorus"]'),
('performance_listening_notes', 725, 'headline_en', '881d01e38b3137a3b880f830b6c517d8fa25156a076284ee08879306ee9c6071', 'A quickly passing opening'),
('performance_listening_notes', 725, 'note_en', '724b3ea26a2f744ed4f921e61874386e1b50d5e9948f33cf924278dfaa39ac9c', 'At 2:01 it is 35 seconds shorter than Noseda. It moves through the quiet passage quickly and climbs to its loudest in just a few seconds at the end.'),
('performance_listening_notes', 725, 'facts_en', '724b3ea26a2f744ed4f921e61874386e1b50d5e9948f33cf924278dfaa39ac9c', '["Bavarian Radio"]'),
('performance_listening_notes', 726, 'headline_en', '57c3c7017e0d1c7759cefa7b782ac1eed7772085f6df6773bb9a835057f69ae1', 'Maximum at the final tutti'),
('performance_listening_notes', 726, 'note_en', 'f3a5fd350c7c9e0b06666e05ce19d9070f43787152292cd21f9c40b3220b33fd', 'It reaches its loudest at the last tutti, when the whole orchestra gathers again. It also ends the loudest of the three.'),
('performance_listening_notes', 726, 'facts_en', 'f3a5fd350c7c9e0b06666e05ce19d9070f43787152292cd21f9c40b3220b33fd', '["Royal Phil"]'),
('performance_listening_notes', 727, 'headline_en', 'fa7374925e6aa9f138b449c577cec8aed3f2fd1ff0fe2229b83c107fe63b6325', 'Saved until the end'),
('performance_listening_notes', 727, 'note_en', 'df1fe7cd19a102dd70efec5dccbaa8d419e7bd427f3c7ff08f0db8ba4aecdd0a', 'It keeps the big early passages one notch lower and saves the loudest sound for near the end. It doesn''t linger on loud playing either.'),
('performance_listening_notes', 728, 'headline_en', 'ba5ba6e327ea4554d2e88c6b83fb1e86ecfff7350a96165a823bd8e6140da97d', 'Near maximum from the first note'),
('performance_listening_notes', 728, 'note_en', 'f424b8ffc37602ed33dc3f3ce2f8faf6391d2ac1d4c6710753ad2f60a1412dfd', 'At 2:09 it is the shortest of the three. It enters near maximum from the very first note and sings at its loudest early on.'),
('performance_listening_notes', 729, 'headline_en', 'e08fd46ca51ca54d2c9ae8301274b5d89e775395174a44f2a79a93d36d7ce994', 'Builds early, ends softly'),
('performance_listening_notes', 729, 'note_en', 'c4238885088a17de9bcb6572e091f3fe86e2c3109c8f892bcedc8320f809ab7a', 'It builds toward the final tutti 11 seconds earlier than Previn. After the climax it sets the ending down alone, quietly.'),
('performance_listening_notes', 729, 'facts_en', 'c4238885088a17de9bcb6572e091f3fe86e2c3109c8f892bcedc8320f809ab7a', '["London Phil"]'),
('performance_listening_notes', 730, 'headline_en', 'ae19a2ce168f07bf8ba86204db2f46a86d7030df90ad3c0f85fdc64e7ae7eebc', 'Quietest just before the end'),
('performance_listening_notes', 730, 'note_en', '71a47b3809217f655ce03300a27ae63ad704fdcb7bc9cedb32dcba2f24027fe7', 'The gap between quiet and loud is wider than in the other two. It sinks to its softest just before the end, then jumps to loud in one move.'),
('performance_listening_notes', 731, 'headline_en', '06f02b5544a880ef087c53e3a76dadf44cc6bf6b021eaae159790890c8aba606', 'Maximum at the first tutti'),
('performance_listening_notes', 731, 'note_en', '2656d3307391726add355c0241476afb540aeca96525f322778739f7bd8ed567', 'It rings out loudest at the first tutti, the opposite of the other two. In the middle, where the instrument groups take the theme in turn, it drops one notch.'),
('performance_listening_notes', 731, 'facts_en', '2656d3307391726add355c0241476afb540aeca96525f322778739f7bd8ed567', '["Philadelphia"]'),
('performance_listening_notes', 732, 'headline_en', 'b943d790f71a6b01b3daaa97f79fdab54540c4702af21820d35d3dd8a41ff16c', 'A less hushed opening'),
('performance_listening_notes', 732, 'note_en', '8eabda2016220e99e2d176e036bcd2a6bd1cf5e79cc064eb1e3a2d3c755246bd', 'Unlike the other two, it plays loud from the very first sound and keeps the gap between quiet and loud narrow. Its loud passages also last the longest.'),
('performance_listening_notes', 732, 'facts_en', '8eabda2016220e99e2d176e036bcd2a6bd1cf5e79cc064eb1e3a2d3c755246bd', '["Birmingham Symphony"]'),
('performance_listening_notes', 733, 'headline_en', 'b9fd3aea1c696a173a52db6ac9fe1ef7143732b2c7060abe06978b61bade6b4d', 'The longest hush'),
('performance_listening_notes', 733, 'note_en', '337a3eadc9d6d151a91006d37d865a1767b787c03a797d0b6e481cb7025bf7a9', 'At 2:36 it is the longest of the three. The first sound is also the softest, and it stretches the quiet passage out the longest before rising at the end.'),
('performance_listening_notes', 733, 'facts_en', '337a3eadc9d6d151a91006d37d865a1767b787c03a797d0b6e481cb7025bf7a9', '["London Symphony"]'),
('performance_listening_notes', 734, 'headline_en', 'e2bb24d7d14c26e6a5c4669717da0f5557072baff6973af4b471d81f5d9f63a6', 'Another climax 30 seconds from the end'),
('performance_listening_notes', 734, 'note_en', 'a59cede022a826fd84d7e0c30cd0214055e63965ebe780627dcb31992f01e2cc', 'About 30 seconds before the end it rises once more, as loud as the climax. Just before that it drops to its smallest, then swells in one move.'),
('performance_listening_notes', 735, 'headline_en', '5591ab7a465e62c8dc496ddac316e81396a57ac4640390993a6336ea2107c11b', 'Maximum at the very end'),
('performance_listening_notes', 735, 'note_en', '3c3c079ca6e51e2783b15dbd6b7b9d57b8202a05df90e35abea55de23543898e', 'Later than the other two, it reaches its loudest at the very end. Before that it swells loudly once, pulls back, and builds up again.'),
('performance_listening_notes', 735, 'facts_en', '3c3c079ca6e51e2783b15dbd6b7b9d57b8202a05df90e35abea55de23543898e', '["Harding · Vienna Phil"]'),
('performance_listening_notes', 736, 'headline_en', '1393c0dc61021422abd5c6111290f899964fb2593b1a3753495d4aa6d7a3c98a', 'Maximum twice'),
('performance_listening_notes', 736, 'note_en', '18027b93103efb63887309b77b632d62f6f7aab0291f0d70e2e655b51d961eb2', 'The first sound is the quietest of the three. In the big passage it reaches near-maximum twice and sustains it longer than the other two.'),
('performance_listening_notes', 736, 'facts_en', '18027b93103efb63887309b77b632d62f6f7aab0291f0d70e2e655b51d961eb2', '["Boston Symphony"]'),
('performance_listening_notes', 737, 'headline_en', 'd1d6ee13b9dfdc470d9609f08c7376c12d5ba15fced25b8fa6b1f46a0adceb54', 'Near maximum within 30 seconds'),
('performance_listening_notes', 737, 'note_en', '6ff8d1a9ea7576a59a1f5d2f5a22658966eaa35ab532a3b9fffc06372b22906c', 'Earlier than the other two, it reaches near-maximum within 30 seconds. After the climax it reaches near-maximum two more times.'),
('performance_listening_notes', 738, 'headline_en', 'c9587811b32200aad976f5397f739472784e2161e2d6a3d4d3b26138661a3824', '3:02, deep middle'),
('performance_listening_notes', 738, 'note_en', 'ffd15515c87a5e0563a20b511738e81e70eb317aa84e8dd7add6d3201bc733c4', 'At 3:02 it runs about 10 seconds longer than the other two. It sinks the middle lowest of the three and keeps its loud passages the shortest.'),
('performance_listening_notes', 739, 'headline_en', '566aa9b5a9b5966f96d941f5a956f5c212ee8fc0c6e90956aa2d93a8f32cf085', 'A preview peak mid-way'),
('performance_listening_notes', 739, 'note_en', 'fcb5018ce02f095513bbd9676372736c4562e46df1c71827bf01c602d3081019', 'Unlike the other two, it rises once ahead of time around the middle. The big passage is built up in several stages until it reaches the top.'),
('performance_listening_notes', 739, 'facts_en', 'fcb5018ce02f095513bbd9676372736c4562e46df1c71827bf01c602d3081019', '["St. Louis Symphony"]'),
('performance_listening_notes', 740, 'headline_en', 'fbe97638d271dc59b5146a0f3b00497138a9fce8599077ae665652c9b093f25f', 'One maximum in the middle'),
('performance_listening_notes', 740, 'note_en', '2a25a6b1d17aa5a6cad64f9d50662b67816e52ae2e3d09b5c00f380b59b785ae', 'Alone among the three, it reaches its loudest in the middle. After that it sinks deep, and its loud passages are the shortest.'),
('performance_listening_notes', 740, 'facts_en', '2a25a6b1d17aa5a6cad64f9d50662b67816e52ae2e3d09b5c00f380b59b785ae', '["Ozawa · Boston Symphony"]'),
('performance_listening_notes', 741, 'headline_en', 'd25a095ed6f049432d436d1874ead353a8131da22da6ecfd7d96b71636512edd', 'Less hushed, more even'),
('performance_listening_notes', 741, 'note_en', '188bd31cddc67dc31ea02d5c9ff4ea4e48e0cd7b63a7858c4a11c73e1592eff7', 'It doesn''t drop low at the start or in the middle. It draws things out evenly, begins to grow, and reaches the climax within 10 seconds.'),
('performance_listening_notes', 741, 'facts_en', '188bd31cddc67dc31ea02d5c9ff4ea4e48e0cd7b63a7858c4a11c73e1592eff7', '["Levine · Chicago Symphony"]'),
('performance_listening_notes', 742, 'headline_en', '836186636ea5ea165c56057e727fc828028a927583b8dca2305d4e18090479be', 'A short peak'),
('performance_listening_notes', 742, 'note_en', 'afd432806a28620a6e4ec2c00a046325ab0baa0184e3b7fa038eda5a4cb18b80', 'At 8:03 it is about 30 seconds shorter than the other two. It touches the top briefly, then comes back down to very quiet within 16 seconds.'),
('performance_listening_notes', 742, 'facts_en', 'afd432806a28620a6e4ec2c00a046325ab0baa0184e3b7fa038eda5a4cb18b80', '["New York Phil"]'),
('performance_listening_notes', 743, 'headline_en', 'a5c35631f40daf3989ff460d3b02e4dfc1f57054bf765efd6cdcc782d7c2bfc0', 'A cry held back to the end'),
('performance_listening_notes', 743, 'note_en', 'c8086051948ffdd6c69a438d670d0b7704f47f9f3a37c253d87000390e8716c3', 'It saves the loudest sound until about 10 seconds before the end. It sustains loud playing the longest of the three.'),
('performance_listening_notes', 744, 'headline_en', '66c524782bcafd8e60e0c2b38dc66ed746b29c91a8e048b159ed64b8c4791df9', 'Bursts out loud, then quickly small'),
('performance_listening_notes', 744, 'note_en', 'f2a1b3d122a1dca5b3949970ba0d7a6e011ff28c0cde44b538840c271ab80269', 'It flings out the first gesture loudly, then drops to its quietest within 14 seconds. The gap between quiet and loud is bigger than in the Arditti and Italiano quartets.'),
('performance_listening_notes', 745, 'headline_en', '90aa63c00a65b7904aaf811d52d664fb4b1cf7e08b39e596d0881a8a73c452b0', 'The softest ending'),
('performance_listening_notes', 745, 'note_en', '395a7136687a47ead567f956388dafc532d004da8eae3ed636899120bdca16c9', 'It sets the ending down quieter than either of the other two. Its loud passages are also the shortest, and the gap between quiet and loud is the widest.'),
('performance_listening_notes', 745, 'facts_en', '395a7136687a47ead567f956388dafc532d004da8eae3ed636899120bdca16c9', '["London Symphony"]'),
('performance_listening_notes', 746, 'headline_en', 'b000f837a4d49aa06b7419d9a1fcd2805da32bed3346d0668a2c8310fee30604', 'A loud opening'),
('performance_listening_notes', 746, 'note_en', '85455dd3077e5fd5a400dff077b5dc7491e860c87969890b9a89fec2125646c9', 'It opens louder than the other two. The climax arrives about 15 seconds later.'),
('performance_listening_notes', 746, 'facts_en', '85455dd3077e5fd5a400dff077b5dc7491e860c87969890b9a89fec2125646c9', '["Cleveland"]'),
('performance_listening_notes', 747, 'headline_en', '5a844ef196f7500edc68433767195a3eddd37db22720cda7b1c0f4735969f71d', 'Sustains loud sound longer'),
('performance_listening_notes', 747, 'note_en', '1779cdac71bfccd926d506b2a9b60f614c46a0c2b34ff8c31d72a1d01d9a3c49', 'Unlike Dohnányi, it opens quietly. The ending is less quiet, and it carries loud playing the longest.'),
('performance_listening_notes', 747, 'facts_en', '1779cdac71bfccd926d506b2a9b60f614c46a0c2b34ff8c31d72a1d01d9a3c49', '["Berlin Phil"]'),
('performance_listening_notes', 748, 'headline_en', 'b80e0ebf3b47b26c4da84596167fcf717dafc0b447eb43957e4e4837ca5203b0', 'A less tiny whisper'),
('performance_listening_notes', 748, 'note_en', 'fb87f8258b94b399d3108c29cc48f18ef8ab5c38583900eb42783cef25f96da6', 'At 2:38 it runs more than 20 seconds longer than the other two. It doesn''t make the whisper as small as the Arditti and Emerson quartets do, and it reaches near-maximum early.'),
('performance_listening_notes', 749, 'headline_en', 'a77fcd3527cad081cc260c94fc933a191c411d6012eaec3e076965af440e6ddc', 'The least subdued middle'),
('performance_listening_notes', 749, 'note_en', '0fe837e6415601aef82c4d218aac77136f5d73a62f421e1541b604343ba809d7', 'In the big passage at the start it already rises to near-maximum. It lowers the middle the least of the three.'),
('performance_listening_notes', 749, 'facts_en', '0fe837e6415601aef82c4d218aac77136f5d73a62f421e1541b604343ba809d7', '["Nelsons · Boston Symphony"]'),
('performance_listening_notes', 750, 'headline_en', '7c210a5cb9ccd89dccc81dfe7229be03bc97b919b8a0fc49f6f0a061193c62f2', 'Maximum only seconds from the end'),
('performance_listening_notes', 750, 'note_en', '407fa375b24c99193d69eb3af606ea00eb7da1dce959b4f281c8c77a6ce4c2cd', 'It doesn''t get near maximum until a few seconds before the end. Unlike Yuja Wang, it carries the middle very quietly.'),
('performance_listening_notes', 750, 'facts_en', '407fa375b24c99193d69eb3af606ea00eb7da1dce959b4f281c8c77a6ce4c2cd', '["Chailly · Concertgebouw"]'),
('performance_listening_notes', 751, 'headline_en', 'a3a5be539be1895aa6476cb596f2f4e17405a1818506fdaf7293929d6826d176', 'Maximum at both front and back'),
('performance_listening_notes', 751, 'note_en', 'b0816ea0787481bb8604e2c49b08b2c599b7016d231a38139227a893305c8cfc', 'It opens at near-maximum from the start. It sustains loud playing longer than the other two and rises to that level once more late on.'),
('performance_listening_notes', 751, 'facts_en', 'b0816ea0787481bb8604e2c49b08b2c599b7016d231a38139227a893305c8cfc', '["Myung-Whun Chung · Paris Opera"]'),
('performance_listening_notes', 753, 'headline_en', 'd9be1b4213933082b5ea431fe22bcfaa555a8d37168c60569a8a1b832c800298', 'Loud just once'),
('performance_listening_notes', 753, 'note_en', 'f66807413b3e3e250fbe6e030b0c8f86c053a9c4a34e35cf34c6e61828bd9d40', 'It keeps a quiet level steady and rises loud exactly once. Apart from that one moment there is almost no loud playing.'),
('performance_listening_notes', 754, 'headline_en', '3578bed2d13d599131bfda188965b075e79193e50ba5180b2bf1de3148b10342', 'The most even volume'),
('performance_listening_notes', 754, 'note_en', '1f51b0f888812f4f1a44407a67f4899ce7fe023e84db1ff73c34f68a85a4dbfd', 'The first sound is the loudest of the three, and the levels before and after stay the most even. There is no deep drop anywhere.'),
('performance_listening_notes', 756, 'headline_en', '90155c1652eafc273b8f04633fbc3b4a6784af89cac8310c22685b3dedf0a4a4', 'A very quiet opening'),
('performance_listening_notes', 756, 'note_en', 'df338496f948c17296b9c752a2298bc31da4db3d1c8f3f592a895504fb9477a4', 'It starts far quieter than the other two. From there it grows little by little.'),
('performance_listening_notes', 758, 'headline_en', 'e32ba6b3f39635a501aa173089533dc7f52dbe2c58018e8a60030e047020b17b', 'Keeps its force in the middle too'),
('performance_listening_notes', 758, 'note_en', 'c3e2681de1842aadc5c1445d6ec5d07f8ac8128393a2b7d765ee9553e5d10d50', 'At 2:35 it runs 22 seconds longer than Rozhdestvensky. Even in the middle tune it eases the level down only slightly, and in the later part it blasts out at maximum twice.'),
('performance_listening_notes', 758, 'facts_en', 'c3e2681de1842aadc5c1445d6ec5d07f8ac8128393a2b7d765ee9553e5d10d50', '["Philadelphia"]'),
('performance_listening_notes', 759, 'headline_en', '28f03d7277eda51482d302a98756ed8aa7c0e96f41aa43370f60938589b75ae5', 'First maximum only after the tune'),
('performance_listening_notes', 759, 'note_en', '0ad04813b16a409cf4c4fc510257c610454770e1934f1626a6abaad3e89cd054', 'At 2:13 it is the shortest of the three. It sinks the middle tune the deepest, and only after that reaches maximum for the first time.'),
('performance_listening_notes', 759, 'facts_en', '0ad04813b16a409cf4c4fc510257c610454770e1934f1626a6abaad3e89cd054', '["St. Petersburg Phil"]'),
('performance_listening_notes', 760, 'headline_en', '781556ba1ce6e1177211e7bca4821c6d45173a221823c9c2a2152756d8bbcdf7', 'Near maximum in 11 seconds'),
('performance_listening_notes', 760, 'note_en', 'fe0230efd5efbe276026ad508fa8af78f623f0b4ce1c260ec5fe0e1ac29a0a99', 'It reaches near-maximum within 11 seconds. It carries loud playing longer than the other two.'),
('performance_listening_notes', 760, 'facts_en', 'fe0230efd5efbe276026ad508fa8af78f623f0b4ce1c260ec5fe0e1ac29a0a99', '["Armenian Phil"]'),
('performance_listening_notes', 761, 'headline_en', '300165b94da835b70264fba21a1ae54c4f50541003ad03f91f24c851f075b3fe', 'Drops back, then another climax'),
('performance_listening_notes', 761, 'note_en', '103a56dcffcdb99d13412808d36e52fda36bdc052a5086274af9616682e8756c', 'After the first tutti it sinks deep, then builds up again and rises to its loudest. After that it continues one notch lower.'),
('performance_listening_notes', 761, 'facts_en', '103a56dcffcdb99d13412808d36e52fda36bdc052a5086274af9616682e8756c', '["Järvi · Royal Scottish National Orchestra"]'),
('performance_listening_notes', 762, 'headline_en', 'ef927166d24cd55d55594f95559b8df65dbd30f3f438fd3e7cf19b3a83a2206c', 'The first tutti is the climax'),
('performance_listening_notes', 762, 'note_en', '5ff1c498b17e537f3e1c693d9ae1f8a4d0bc5cdd997612309c4893d9545fdee0', 'Alone among the three, it places the loudest sound at the first tutti. The gap between quiet and loud is also narrower than in the other two.'),
('performance_listening_notes', 762, 'facts_en', '5ff1c498b17e537f3e1c693d9ae1f8a4d0bc5cdd997612309c4893d9545fdee0', '["Fistoulari · London Phil"]'),
('performance_listening_notes', 763, 'headline_en', '3b45c30519f33ba24e8800c5988fc41ef5a5699de45fc7019d8a69db08d0f365', 'Softer ending after the climax'),
('performance_listening_notes', 763, 'note_en', '7c0bd5880825a3177cf4c055641d41e134617650d704e39eac08e295dbafaf8e', 'After playing its loudest, it sets the ending down much lower than the other two. The time it spends at loud levels is also the shortest.'),
('performance_listening_notes', 763, 'facts_en', '7c0bd5880825a3177cf4c055641d41e134617650d704e39eac08e295dbafaf8e', '["Royal Scottish National Orchestra"]'),
('performance_listening_notes', 764, 'headline_en', '43831a17a4e6241340c78bdf7472c3d6a54c8227f1d5a9ebdaaf2f0ef4a6f857', 'Deep after the climax, then loud again'),
('performance_listening_notes', 764, 'note_en', '41a4577597d428c9f531f78bd63f4e8d3bf562dd8aa6ea5765d3b7ba6615f9e5', 'After the first tutti it comes down only one notch, then rises to its loudest. After that it cuts back the deepest of the three and swells once more.'),
('performance_listening_notes', 764, 'facts_en', '41a4577597d428c9f531f78bd63f4e8d3bf562dd8aa6ea5765d3b7ba6615f9e5', '["Goetzel · Borusan Istanbul"]'),
('performance_listening_notes', 765, 'headline_en', '5e39cdf9a0f7d4e3453cedbc9cab13d848841798564a34155403486a8fb1d3b4', 'Maximum from the first big passage'),
('performance_listening_notes', 765, 'note_en', '55258d0d2f0785f8332b79381d6f5778320ada2e55fa1377f9ce4ae4f2620e84', 'At 4:07 it runs 15 seconds longer than Järvi. From the first big passage it plays near-maximum and sustains loud playing the longest of the three.'),
('performance_listening_notes', 765, 'facts_en', '55258d0d2f0785f8332b79381d6f5778320ada2e55fa1377f9ce4ae4f2620e84', '["Armenian Phil"]'),
('performance_listening_notes', 766, 'headline_en', '858b62fb104c22391396592ff66a41a9b83933f8451e2f2f08769e2638184363', 'Maximum at the final chord'),
('performance_listening_notes', 766, 'note_en', '3a9def7b9ea3ad45b09213ab7c2333c7930147866f8039687b6c399a16e30735', 'Alone among the three, it plays its loudest at the final chord. It comes down deep once before the end, then builds all the way to the finish.'),
('performance_listening_notes', 766, 'facts_en', '3a9def7b9ea3ad45b09213ab7c2333c7930147866f8039687b6c399a16e30735', '["London Symphony"]'),
('performance_listening_notes', 767, 'headline_en', 'eec8a0e772a016deac3d11ee964bba7941ebb70bc04bbdee49e52806799e4bf4', 'Cello version, the shortest'),
('performance_listening_notes', 767, 'note_en', 'a5151addcff6c6fcb5f38390d7cab9901b01125e18521a65ab9d90a6e12ec058', 'At 3:06 it is the shortest of the three. It comes in loud from the start, barely changes level, and holds loud playing the longest.'),
('performance_listening_notes', 767, 'facts_en', 'a5151addcff6c6fcb5f38390d7cab9901b01125e18521a65ab9d90a6e12ec058', '["Cello"]'),
('performance_listening_notes', 768, 'headline_en', '9661812fff1cd8b6718e792ee2d244b0cb138c5439529f465c10690d55970592', 'Trumpet version, built up from soft'),
('performance_listening_notes', 768, 'note_en', '80575879ad2014367642a086b632c2ed51b5d09a3899c9ebd6b06cb0869e9075', 'It starts quieter than the other two and builds toward the end. The gap between quiet and loud is large, and it pushes on loudly right to the finish.'),
('performance_listening_notes', 768, 'facts_en', '80575879ad2014367642a086b632c2ed51b5d09a3899c9ebd6b06cb0869e9075', '["Trumpet"]'),
('performance_listening_notes', 769, 'headline_en', '38f886284367157226ad617bbf9876ce8a85b3d383c181d9cf93d2913437401f', 'Quartet version, over six minutes'),
('performance_listening_notes', 769, 'note_en', '15e386cbb5ea50db8a9523de1ab122e4c45b3b18424fc58d81d6ea96f89fa46b', 'At 6:35 it is more than twice as long as Yo-Yo Ma''s performance. It opens quietly, reaches near-maximum in under two minutes, then carries the middle section loudly for a long stretch.'),
('performance_listening_notes', 769, 'facts_en', '15e386cbb5ea50db8a9523de1ab122e4c45b3b18424fc58d81d6ea96f89fa46b', '["String quartet"]'),
('performance_listening_notes', 770, 'headline_en', '2c1a1d291349f0f43b1eadebf9d698369e90156508ccd2163aefc040d3fa4d92', 'With the orchestra, mid-way'),
('performance_listening_notes', 770, 'note_en', '091e1f7f719e35c507644b6bd332962d4cf42256244e7d416eb46ab306dee1e7', 'The cello opens quietly and, together with the orchestra, rises to its loudest right in the middle. It swells loudly once more later and ends softly.'),
('performance_listening_notes', 770, 'facts_en', '091e1f7f719e35c507644b6bd332962d4cf42256244e7d416eb46ab306dee1e7', '["Cello · orchestra"]'),
('performance_listening_notes', 771, 'headline_en', '10fabbf846f82368ab5b92492f3bbb1f78f68b95f87ed0b123ab97c7398b629a', 'A surge in the final stretch'),
('performance_listening_notes', 771, 'note_en', '268b78f44bc159a3fc08be9c32d8bbb4e94384187a4a41cb54acd51c7afaa246', 'It starts the quietest and opens the widest gap between quiet and loud of the three. The final third surges far louder than the front.'),
('performance_listening_notes', 771, 'facts_en', '268b78f44bc159a3fc08be9c32d8bbb4e94384187a4a41cb54acd51c7afaa246', '["Violin · string ensemble"]'),
('performance_listening_notes', 772, 'headline_en', '86b50e7fd7c15cc43a933558ec43f49f25ed62ca7c78a1f19eb21c06b2f408f1', '7:07, loud from the start'),
('performance_listening_notes', 772, 'note_en', 'f0397cdd63cecfb725d6c844b9b1b15c6fce71d4290b1c957bcdc96dafa0db85', 'At 7:07 it runs about two and a half minutes longer than the guitar version. It comes in loud from the start and holds loud playing the longest.'),
('performance_listening_notes', 772, 'facts_en', 'f0397cdd63cecfb725d6c844b9b1b15c6fce71d4290b1c957bcdc96dafa0db85', '["String quartet · orchestra"]'),
('performance_listening_notes', 773, 'headline_en', '1d3f5adc12490d6adf040c582c9297c7d2f7c8e5a0f21287f44dd4af4b632a5c', 'The shortest, the guitar version'),
('performance_listening_notes', 773, 'note_en', '7c98567164f5350e4bd58fc8f46beeb1e4da4a8316cac3ceab079e1a31589931', 'At 4:41 it is shorter than the other two. The front, middle and back carry on at similar levels, and the loud playing is brief.'),
('performance_listening_notes', 773, 'facts_en', '7c98567164f5350e4bd58fc8f46beeb1e4da4a8316cac3ceab079e1a31589931', '["Solo guitar"]'),
('performance_listening_notes', 774, 'headline_en', '580a7c3fb26f68231729597fe578ad5ad50744609581a7e33257d13f287ba1c1', 'Rises early, then pulls back'),
('performance_listening_notes', 774, 'note_en', '350fe74063ef45d146974ac2bd6fd0ee931374df0e5d3d056c5129eaad0a8e83', 'It reaches near-maximum earlier than the other two. It pulls back a long way in the middle, then rises to the same level again late on.'),
('performance_listening_notes', 774, 'facts_en', '350fe74063ef45d146974ac2bd6fd0ee931374df0e5d3d056c5129eaad0a8e83', '["Cello · piano"]'),
('performance_listening_notes', 775, 'headline_en', '6d27cf3ca87fc603f70a5624f0148b74dbe1f9e588717e667264d70a4f6c4604', 'A version a minute longer'),
('performance_listening_notes', 775, 'note_en', '60439431a244e438921244286f2a211fd4a81099b9a23db25c83c3e7bba20d68', 'At 4:47 it runs about a minute longer than the other two. Its loud playing is the shortest of the three, and it is the last to reach near-maximum.'),
('performance_listening_notes', 775, 'facts_en', '60439431a244e438921244286f2a211fd4a81099b9a23db25c83c3e7bba20d68', '["Violin · string ensemble"]'),
('performance_listening_notes', 776, 'headline_en', 'aa3d8a50abe5b9d21a35400fe9ed4cef781b6f1d1361c1f5ec92ddbad549d42b', 'Longest, loud at the end'),
('performance_listening_notes', 776, 'note_en', '2980d2c13f27394d2fb87a1d633b04e4c9f5517aed98919071f4c474af564190', 'At 4:51 it runs about 45 seconds longer than the other two. It doesn''t reach near-maximum until the final 40 seconds.'),
('performance_listening_notes', 776, 'facts_en', '2980d2c13f27394d2fb87a1d633b04e4c9f5517aed98919071f4c474af564190', '["Vienna Boys'' Choir"]'),
('performance_listening_notes', 777, 'headline_en', '62bf988e36bb1622c761a8a2f99e994e46dad31dc7e143255193d27a24103592', 'One big swell at the end of the first verse'),
('performance_listening_notes', 777, 'note_en', '818a7a0e506b3121ec36ae2c36d7c5e35f09069d131675f45d296cd51e1d2453', 'At the end of the first verse it swells loudly once, takes a breath, and builds again. It closes the quietest of the three.'),
('performance_listening_notes', 777, 'facts_en', '818a7a0e506b3121ec36ae2c36d7c5e35f09069d131675f45d296cd51e1d2453', '["Boy soprano and duet"]'),
('performance_listening_notes', 778, 'headline_en', '7f38dffc6475f9e5eff46a55ed947821af1a3318fb5f42feb00c38f7df88d9c5', 'Opens soft, ends loud'),
('performance_listening_notes', 778, 'note_en', '6cbef0ba179e8b5eea017ab1ff43561259fdb93dabaa8fbf9601e28ac854f123', 'The first sound is quieter than in the other two. It builds step by step, and the ending is, if anything, less soft.'),
('performance_listening_notes', 778, 'facts_en', '6cbef0ba179e8b5eea017ab1ff43561259fdb93dabaa8fbf9601e28ac854f123', '["Orchestra"]'),
('performance_listening_notes', 779, 'headline_en', 'e06e932ced114e53f131e0d94f718773c030c82c0ef7b64b677f995816e156a8', 'Maximum near the end'),
('performance_listening_notes', 779, 'note_en', '82a65435d7fb95216f44bbf87eb679cbaf3289ee5fae75368ec2034a90b0df6a', 'It reaches its loudest the latest of the three, near the end. Before that it also rises to near-maximum twice.'),
('performance_listening_notes', 779, 'facts_en', '82a65435d7fb95216f44bbf87eb679cbaf3289ee5fae75368ec2034a90b0df6a', '["Violin"]'),
('performance_listening_notes', 780, 'headline_en', '5e6831663ee9cdeac8c7a98636ede7bf858396d49952aac0b7320d5e98b254c2', 'Shortest, held back then released at once'),
('performance_listening_notes', 780, 'note_en', 'f78bf4faa373a4293e087fa8e26573e76558a171d529994b3e32f0db6b3eab05', 'At 4:38 it is nearly four minutes shorter than the two-piano version. It holds back near-maximum until past the midpoint, then rises all at once.'),
('performance_listening_notes', 780, 'facts_en', 'f78bf4faa373a4293e087fa8e26573e76558a171d529994b3e32f0db6b3eab05', '["Bandoneon · chorus · chamber orchestra"]'),
('performance_listening_notes', 781, 'headline_en', '4c678f0fe50aa8e99e1a765fa01ca7bab2e06fb1dbdd49d4c92806ed670eccc1', '8:37, maximum early on'),
('performance_listening_notes', 781, 'note_en', 'a2af0ce278f63987d53aa1d906b1a3b02160f3539ce16d4c6a64942fb89c9b70', 'At 8:37 it is longer than the other two. It starts the quietest and reaches its loudest about a quarter of the way in.'),
('performance_listening_notes', 781, 'facts_en', 'a2af0ce278f63987d53aa1d906b1a3b02160f3539ce16d4c6a64942fb89c9b70', '["Two pianos"]'),
('performance_listening_notes', 782, 'headline_en', '66e5dc025d33e94726efaabfec925ee710429b66a47fb753737f4894024d2744', 'Orchestral version, the longest'),
('performance_listening_notes', 782, 'note_en', '9fb5479909808b445454dc3eba29aa83adeb2166b5829af8f85adadfe2ec5be4', 'At 7:00 it is the longest of the three. The melody passes from instrument to instrument, rising loud again and again.'),
('performance_listening_notes', 782, 'facts_en', '9fb5479909808b445454dc3eba29aa83adeb2166b5829af8f85adadfe2ec5be4', '["Orchestra"]'),
('performance_listening_notes', 783, 'headline_en', '42e6b50e824955b5bafb78c44037c64972ccae8fe930232191d44e90ad6274ed', 'A long cello line'),
('performance_listening_notes', 783, 'note_en', 'c3d15cfedcba2d73f0578a2b26a793a3931d845828d6c11454163f3ebc94c261', 'It runs a minute and a half longer than the voice version. Drawing out a single long note, it rises to its loudest in the middle.'),
('performance_listening_notes', 783, 'facts_en', 'c3d15cfedcba2d73f0578a2b26a793a3931d845828d6c11454163f3ebc94c261', '["Cello · piano"]'),
('performance_listening_notes', 784, 'headline_en', 'e80550c76380c0c553fb068456e83cfcdae57acdcfc3611c0802604cba62b6da', 'Voice version, the shortest'),
('performance_listening_notes', 784, 'note_en', '22756a7c65fd2ca6d9658e142b0191c6b9f89f8f407a3d73f06e76be0c98f4b8', 'At 4:58 it is the shortest of the three. It rises and falls within a quiet range, and grows loudest only near the end.'),
('performance_listening_notes', 784, 'facts_en', '22756a7c65fd2ca6d9658e142b0191c6b9f89f8f407a3d73f06e76be0c98f4b8', '["Voice · piano"]'),
('performance_listening_notes', 794, 'headline_en', '63ea9460653f91d58b22a0f8de781d3f05fed37b8a751483083713797c7495d8', 'Five big peaks'),
('performance_listening_notes', 794, 'note_en', '08cc785f57b5ba3bc42c78f896d1dc804bc8338673eae61f00e69433172a0d37', 'It rises loud in five places, all at similar levels. It doesn''t hold back the ending as much as Gruberová does, and raises it a little further at the last.'),
('performance_listening_notes', 794, 'facts_en', '08cc785f57b5ba3bc42c78f896d1dc804bc8338673eae61f00e69433172a0d37', '["Kleiber · Bavarian State Orchestra"]'),
('performance_listening_notes', 795, 'headline_en', '833400a0f8e37f672bf47c5dbc182bc11bbc33b2dcc5db516527f7dbac30b1af', 'Pushed up in the last 30 seconds'),
('performance_listening_notes', 795, 'note_en', '1e6b04750dd91b10c7c36dd6a4524abdf11391adc7348b80911f7415136e7c74', 'It runs 6 seconds shorter than Bernstein and 17 seconds shorter than Myung-Whun Chung. It keeps the middle low and reserved, then climbs to its loudest over the final 30 seconds.'),
('performance_listening_notes', 795, 'facts_en', '1e6b04750dd91b10c7c36dd6a4524abdf11391adc7348b80911f7415136e7c74', '["Concertgebouw"]'),
('performance_listening_notes', 796, 'headline_en', 'c3dd07fa79a3b7ebf41970723e815b726ef8c96d641d949266047dc934a9a30a', 'The slowest of the three'),
('performance_listening_notes', 796, 'note_en', '0214e2377ae740765d37702d9178aa88a55bfe831d2530c8eed73d227df63345', 'At 2:01 it is the longest of the three. It lets the level fall between phrases less than the other two do, and builds the volume step by step.'),
('performance_listening_notes', 796, 'facts_en', '0214e2377ae740765d37702d9178aa88a55bfe831d2530c8eed73d227df63345', '["Performance used in \\"Decision to Leave\\"", "Seoul Phil"]'),
('performance_listening_notes', 797, 'headline_en', 'fa4fff62073a93e79477697a5d22205470240f1b271372b2f66ad50bdcfce963', 'Maximum right after the quiet passage'),
('performance_listening_notes', 797, 'note_en', '9b1fe110643f36b2c79b97d27dcf3be712f0f3af74a6c9909805053404b6a185', 'As soon as the quiet passage in the middle ends, it reaches near-maximum. It rises to that level several more times afterward, and unlike the other two it doesn''t save the ending.'),
('performance_listening_notes', 797, 'facts_en', '9b1fe110643f36b2c79b97d27dcf3be712f0f3af74a6c9909805053404b6a185', '["Solti · Royal Opera House"]'),
('performance_listening_notes', 798, 'headline_en', 'de9c981fbe21abdeb69538a54b47b76e5a93f30918ef0db7a8932eb015b431f2', 'Maximum held back to the end'),
('performance_listening_notes', 798, 'note_en', 'fa96b502bc4e36aae6a469484b3646a67decdca7efac4665eaa6b988e072d294', 'It never reaches near-maximum until 16 seconds before the end. The quiet passage in the middle is also the deepest of the three, and it swells loudly just once at the close.'),
('performance_listening_notes', 798, 'facts_en', 'fa96b502bc4e36aae6a469484b3646a67decdca7efac4665eaa6b988e072d294', '["Rizzi · London Symphony"]'),
('performance_listening_notes', 799, 'headline_en', 'a96c77c71f0c45d73bbcc89b53bd6fae0b8dd6e54cf609dc50aa6e080255601a', 'One more after the climax'),
('performance_listening_notes', 799, 'note_en', '07a3fdbd2ca09b15bcc996bdde16b4469307ab7f9cc999a242057c6a174a765b', 'It pulls back sharply in the middle, then builds for nearly 30 seconds to reach the climax. Unlike Zimerman, it rises to near-maximum once more 10 seconds later.'),
('performance_listening_notes', 799, 'facts_en', '07a3fdbd2ca09b15bcc996bdde16b4469307ab7f9cc999a242057c6a174a765b', '["Previn · London Symphony"]'),
('performance_listening_notes', 800, 'headline_en', '36418ba9644e79b98d40758483329755bd3f05ecfb8063bc04eb6f87210ed1ac', 'Bells ringing for over 30 seconds'),
('performance_listening_notes', 800, 'note_en', '0ff4d6f93061b3cb8269c4071bc3eec110d03d037062ddaa611f7b596234d91f', 'It takes over 30 seconds on the eight bars of bell-like chords, more than 10 seconds longer than the other two. As soon as the theme enters, it reaches near-maximum.'),
('performance_listening_notes', 800, 'facts_en', '0ff4d6f93061b3cb8269c4071bc3eec110d03d037062ddaa611f7b596234d91f', '["Ozawa · Boston Symphony"]'),
('performance_listening_notes', 801, 'headline_en', '81a746df93c92cd4dcbcb366a503c9dc7fe9d154840d83425859df2323ab782f', 'Swells and settles with each phrase'),
('performance_listening_notes', 801, 'note_en', '74f215370b01ccdd4e560474e0efbc348a033b4475fc157c44ea2a69b4211059', 'Unlike Myung-Whun Chung, it swells every phrase loudly and then settles deeply. Before the final climax it pulls back the deepest, then climbs in two stages.'),
('performance_listening_notes', 801, 'facts_en', '74f215370b01ccdd4e560474e0efbc348a033b4475fc157c44ea2a69b4211059', '["Vienna Phil"]'),
('performance_listening_notes', 802, 'headline_en', '37cdbd479cc2fd53d0d4f1418aac10cc7e00140047eb65564f753082b12b9fa7', 'Still loud in the last 20 seconds'),
('performance_listening_notes', 802, 'note_en', 'a142be619231f289702e84212c444ead5a9c78a2c7ce9a778109d7b78ccb09ab', 'From the first chord it starts the least quietly of the three. In the last 20 seconds too, it keeps up a loud level and doesn''t come down as far as the other two.'),
('performance_listening_notes', 802, 'facts_en', 'a142be619231f289702e84212c444ead5a9c78a2c7ce9a778109d7b78ccb09ab', '["Nézet-Séguin · Philadelphia"]'),
('performance_listening_notes', 809, 'headline_en', 'b665fcac94add46bc0c0ac95a51a9f1fe652a020dfd194a6bf8cc5f7acf6bb91', 'A hymn moving briskly'),
('performance_listening_notes', 809, 'note_en', '116df18c330d14a7bcfd6868f2d964d0023bb2ea83b6f7fcdb04653e5cbeef5b', 'At 1:48 it runs about 10 seconds shorter than the other two. It builds the hymn gradually from the start, and doesn''t sink the quiet passage as deep as the other two do.'),
('performance_listening_notes', 809, 'facts_en', '116df18c330d14a7bcfd6868f2d964d0023bb2ea83b6f7fcdb04653e5cbeef5b', '["Haitink · Concertgebouw"]'),
('performance_listening_notes', 810, 'headline_en', '6dce2aa4af85a83fb5f548c1a48817e5d21a64210a746fa898a54478f7b48ca9', 'Two fortissimos at an even level'),
('performance_listening_notes', 810, 'note_en', '9d158ff3fe6304c136a3d19527de7e95f0b0c24506f0fcc54b0a8b7dd197ad0b', 'It strikes the first fortissimo and the second theme at almost the same level. The woodwind passage between them is sunk deeper than Solti does.'),
('performance_listening_notes', 810, 'facts_en', '9d158ff3fe6304c136a3d19527de7e95f0b0c24506f0fcc54b0a8b7dd197ad0b', '["Vienna Phil"]'),
('performance_listening_notes', 811, 'headline_en', '15df3e793cb9a8eb67b063a2927f2a71849837da740738cc8bce0fcc3f1fee02', 'The deepest quiet passages'),
('performance_listening_notes', 811, 'note_en', '7f3671b945e998ab8e1139512e19a031726bf3db643c1fec882723dcfa30c81f', 'It sinks the quiet passage the deepest of the three, so the gap to the loud passages is also the widest. It draws out the hymn 10 seconds slower than Perahia.'),
('performance_listening_notes', 811, 'facts_en', '7f3671b945e998ab8e1139512e19a031726bf3db643c1fec882723dcfa30c81f', '["Rattle · London Symphony"]'),
('performance_listening_notes', 812, 'headline_en', '92a92101fb3de2118dadc1c39fe030c90ba462684fdc3c630613b4db11628fad', 'Weight on the first fortissimo'),
('performance_listening_notes', 812, 'note_en', '16bd67f395e24d7ea2e0a0684d5d2dc88b9ef0569198c9f77f69cfb7e5770577', 'Unlike the other two, it blasts loudest at the first fortissimo and drops the second theme one notch. It opens at near-maximum from the very start.'),
('performance_listening_notes', 812, 'facts_en', '16bd67f395e24d7ea2e0a0684d5d2dc88b9ef0569198c9f77f69cfb7e5770577', '["Chicago Symphony"]'),
('performance_listening_notes', 813, 'headline_en', 'ee0ca8cb969f528fc08f1cd1b8c3a226db605ae4b3321915af9be0d9c2262c25', 'Held back until the second theme'),
('performance_listening_notes', 813, 'note_en', 'c6de0abdfb4d8722c1959dd74350ce39c61f7b4717f261ae592560f2fb7ef538', 'It holds back the opening and the first fortissimo the most of the three. Its loudest sound comes at the second theme.'),
('performance_listening_notes', 813, 'facts_en', 'c6de0abdfb4d8722c1959dd74350ce39c61f7b4717f261ae592560f2fb7ef538', '["Berlin Phil"]'),
('performance_listening_notes', 814, 'headline_en', 'f3426a319d2c42c960b05ecd3fa56da34eea348b3fbfc17a3394a37fa5236429', 'An even first 50 seconds'),
('performance_listening_notes', 814, 'note_en', '6eced46cb9ba8f48b438b4db369f37891e4de43b6ec4b270fdbe835190e6b608', 'It sings the first 50 seconds of the hymn at a steady, similar level. Unlike Perahia, it doesn''t grow bit by bit, and rises to near-maximum only when it reaches the loud passage.'),
('performance_listening_notes', 814, 'facts_en', '6eced46cb9ba8f48b438b4db369f37891e4de43b6ec4b270fdbe835190e6b608', '["Levine · Philharmonia"]'),
('performance_listening_notes', 818, 'headline_en', '8ef281f9e867e516621b80442e961ec928b9b77518582c0b7b0ff9354c3fe6f0', 'Restrained at first, a long finish'),
('performance_listening_notes', 818, 'note_en', '209db13d418775c19958f874c8af61e9182237f726a0ba64be9bce86ee54ffd5', 'At 2:40 it is the longest of the three. It holds things quiet for more than the first minute, then sustains the last big passage at near-maximum for nearly 6 seconds.'),
('performance_listening_notes', 818, 'facts_en', '209db13d418775c19958f874c8af61e9182237f726a0ba64be9bce86ee54ffd5', '["Muti · La Scala"]'),
('performance_listening_notes', 819, 'headline_en', '7b7ecdd685e4105e0fd63e76dcb13b2d7c8c6c3b0a4aaa14eee9c33cebe7441d', 'Short, loud only once'),
('performance_listening_notes', 819, 'note_en', '988b937f7a15a0895afea4c06575c67efae92e05e559a7bddde0ed349fa10503', 'At 2:06 it is 34 seconds shorter than Fabbricini. It keeps the first rise before the last big passage one notch lower, so near-maximum happens only once.'),
('performance_listening_notes', 819, 'facts_en', '988b937f7a15a0895afea4c06575c67efae92e05e559a7bddde0ed349fa10503', '["Kleiber · Bavarian State Orchestra"]'),
('performance_listening_notes', 820, 'headline_en', 'b479e4863ca93d81d7728edeb32187e43f69758cf62fd08f02b68c8dea356fb7', 'Loud twice'),
('performance_listening_notes', 820, 'note_en', '42489b555c672909bac870ed2e95247f1d29ecdd2d51f6cdaa06090ec51047df', 'At 2:20 it falls between the other two performances. Unlike Cotrubaș, it rises to almost the same level before the last big passage too, so there are two big outbursts.'),
('performance_listening_notes', 820, 'facts_en', '42489b555c672909bac870ed2e95247f1d29ecdd2d51f6cdaa06090ec51047df', '["Solti · Royal Opera House"]'),
('performance_listening_notes', 824, 'headline_en', '2af386a76e873b3c9a7073bcfb23f20565f019d51cefdfbf9ca1b76a00dc4654', 'The shortest, 47 seconds'),
('performance_listening_notes', 824, 'note_en', '4e8a0de695d766ccb8113adce184d8c9caaecbf91d6c0bf282936731e15bf602', 'At 47 seconds it is the shortest of the three. At each big passage it climbs back to near the level of the first sound, so the flow is almost the same as Solti''s.'),
('performance_listening_notes', 824, 'facts_en', '4e8a0de695d766ccb8113adce184d8c9caaecbf91d6c0bf282936731e15bf602', '["Vienna Phil"]'),
('performance_listening_notes', 825, 'headline_en', '3178b73fd793a88cd5ca69ff1802ac2cd6d4da506b5ff7469c4c0bd103007a57', 'The opening level to the end'),
('performance_listening_notes', 825, 'note_en', '09ca41269895685cc61b52fd5f6eada5026cee343deb8977e0e8c146dcebca8d', 'Unlike Haitink, it keeps the level of the first sound all the way to the end. In the last big passage before the finish, it rises as loud as at the start.'),
('performance_listening_notes', 825, 'facts_en', '09ca41269895685cc61b52fd5f6eada5026cee343deb8977e0e8c146dcebca8d', '["Chicago Symphony"]'),
('performance_listening_notes', 826, 'headline_en', 'bc432ad877977e8e0b39ce80a7a02cc0c67d55d522d68c21ac5caec0fcd52478', 'A step below after the first sound'),
('performance_listening_notes', 826, 'note_en', '3d8ef3d12b5fe33feaae5ac93e6aef5598b06c4371eef980d0e9bcc3aba4df04', 'Only the first sound is at maximum; alone among the three, it sings the later big passages one step below that. At 51 seconds it is 4 seconds longer than Rattle.'),
('performance_listening_notes', 826, 'facts_en', '3d8ef3d12b5fe33feaae5ac93e6aef5598b06c4371eef980d0e9bcc3aba4df04', '["London Symphony"]'),
('performance_listening_notes', 836, 'headline_en', 'd90c14d068c9766a26dc94f4f43d5b830236da9d902d79ab30c7fdf982852dc9', 'Quiet passages kept higher'),
('performance_listening_notes', 836, 'note_en', '3c1758164657221193717d049266812acf8576cd13fb1d2161c772c31a1f2b57', 'It lowers the passage that turns quiet again after the first tutti less than the other two do. The loudest sound comes in the exposition, and the ending is almost as loud.'),
('performance_listening_notes', 836, 'facts_en', '3c1758164657221193717d049266812acf8576cd13fb1d2161c772c31a1f2b57', '["London Phil"]'),
('performance_listening_notes', 837, 'headline_en', 'e8fdb782f8a3d1d26dc663bd1991cee294b44b1e9624c1f551de84331a6c4299', 'The fastest Aria of the three'),
('performance_listening_notes', 837, 'note_en', '4ba36d67d70173c4ccc3388f61bb266a4662b0e6fd95824d08f4b97c796ed8b5', 'At 3:41 it is 21 seconds shorter than Hewitt and 14 seconds shorter than Perahia. The repeat is played as loudly as the first time, and the climax comes in the repeat of the second half.'),
('performance_listening_notes', 838, 'headline_en', 'f04c6690757e01f86cf32a61323b06c3eff3ddbec7d143086c5b406e5e80b4eb', 'A narrow gap between cry and prayer'),
('performance_listening_notes', 838, 'note_en', 'd98abe7fca56095eba9b432367f96f854b5a4c7757b19a1fcf4ae47445937536', 'Even when the women''s voices enter, it lowers the level far less than Davis does. It goes in at near-maximum from the first outcry, and swells loud earlier than Karajan.'),
('performance_listening_notes', 838, 'facts_en', 'd98abe7fca56095eba9b432367f96f854b5a4c7757b19a1fcf4ae47445937536', '["Beyer edition", "Bavarian Radio"]'),
('performance_listening_notes', 839, 'headline_en', '36b13aa6e82dd9cd7b7f9fd111b8e90f7dda902a9065a40fe1c28d3aef8c38bc', 'The softest whisper'),
('performance_listening_notes', 839, 'note_en', '02b083254f3d8b90aff3d405e2e052377c4a85e6c538373d0d8bf6d67ec20e36', 'It opens the quietest of the three and lowers the passage leading into the recapitulation just as much. The loudest sound comes at the final chord.'),
('performance_listening_notes', 839, 'facts_en', '02b083254f3d8b90aff3d405e2e052377c4a85e6c538373d0d8bf6d67ec20e36', '["Vienna Phil"]'),
('performance_listening_notes', 840, 'headline_en', 'cafc934e668137532d7abc21422211f62bba5f74de49f41bf5f64a33b47adf39', 'Holds back the first outcry'),
('performance_listening_notes', 840, 'note_en', '9c89a79bc6a7ede2268c1bf0166f89fb0eb09ff24d4cd1b38eeb56b9caa1eabc', 'Unlike the other two, it holds back the first outcry a little and plays the second outcry the loudest. The closing prayer passage runs more evenly than in the other two.'),
('performance_listening_notes', 840, 'facts_en', '9c89a79bc6a7ede2268c1bf0166f89fb0eb09ff24d4cd1b38eeb56b9caa1eabc', '["Vienna Phil"]'),
('performance_listening_notes', 841, 'headline_en', 'fcbe908453c45a61dbffc2baf24c106fc044dca9a1c81c46e6ad959a369237bb', 'A slow prayer, deeply lowered'),
('performance_listening_notes', 841, 'note_en', 'd68db8526292ef2d68adb8f547010c1e806d657ecf371dc4369e19a0b348d79b', 'At 2:43 it runs about 20 seconds longer than the other two. Each time the women''s voices enter, it sinks the deepest of the three, setting up a strong contrast with the outcries.'),
('performance_listening_notes', 841, 'facts_en', 'd68db8526292ef2d68adb8f547010c1e806d657ecf371dc4369e19a0b348d79b', '["London Symphony"]'),
('performance_listening_notes', 842, 'headline_en', '7165cfb67b8fe94d0a87fe48349ba5dc19febcc6dc82da5b5f0bd24a5df87267', 'Repeats one step softer'),
('performance_listening_notes', 842, 'note_en', '605c8f2345eb6523a6d9df261d95b4542150c55cd88e2eb554e184bd210e7877', 'Unlike Schiff, it lowers the level every time it plays the same half again. The second half is raised loud the first time, but on the repeat it is played as small as the first half.'),
('performance_listening_notes', 843, 'headline_en', '410a80ceb6d6179e96ede7096bb1bea395267942cb12548500e8f050124ff92e', 'Near maximum from the first tutti'),
('performance_listening_notes', 843, 'note_en', '9e206b4779b3afb18c3aa1e241c6f348eae297156e7f8540162c8eac6f6751e4', 'It already bursts out at near-maximum at the first tutti. It doesn''t lower the quiet passage as far as Karajan does, and the loudest sound comes at the final chord.'),
('performance_listening_notes', 843, 'facts_en', '9e206b4779b3afb18c3aa1e241c6f348eae297156e7f8540162c8eac6f6751e4', '["BBC Symphony"]'),
('performance_listening_notes', 844, 'headline_en', '7816b11d0b38fdb8ffe1bf47b2895ad24a4f282e0fe53557e924f626e2bcec12', 'Near maximum in 36 seconds'),
('performance_listening_notes', 844, 'note_en', '29c2347d5db1612982b14c9f7d8a787e751735f55b090dba4efeb423ded119ec', 'From the first sound it opens less quietly than the other two, and it already reaches near-maximum in the first half. On the repeat it lowers the level like Hewitt, but not as much.'),
('performance_listening_notes', 872, 'headline_en', '2250c14616cfa54aa986b8396f0d88a2cb226a2197d72627a249d1d35dff76fc', 'Loud through the final refrain'),
('performance_listening_notes', 872, 'note_en', 'fef4d7a03168fdc5f8ac0f7a09439740b2bb77c0c303c4675e8aac02dd81e67c', 'It plays in the same order as Tharaud and runs 19 seconds longer. After sinking deep once in the middle, it carries the second half at near-maximum and ends loudly.'),
('performance_listening_notes', 873, 'headline_en', 'dffcb3b9cfbf60057dc683d260997f8e17a4cb8084748488c1a3e71934dcac01', '1:08, the shortest'),
('performance_listening_notes', 873, 'note_en', '2200f882e510b546cce922fc9b1e1948dd600af949721850d5d4c0bb360f6e86', 'At 1:08 it is the shortest of the three. After about 10 seconds it drops one notch, then rises to near-maximum within 18 seconds.'),
('performance_listening_notes', 874, 'headline_en', 'c2c7389c88a021f79bd3a935aa5c924ac1bdc2ef82317be0d60b3e39b9eea1bc', 'Near maximum only in the last 20 seconds'),
('performance_listening_notes', 874, 'note_en', '370b250c062a37ad14f4342091d51fa4154df45f9c83cb6c7d568144335b3f32', 'Unlike Yo-Yo Ma, it never reaches near-maximum until 20 seconds before the end. In the final climb it rises all at once.'),
('performance_listening_notes', 875, 'headline_en', '25fc206224eefaff001681dca376aabefd3b51432f1fe294f344160f960bbfd0', 'The middle a step lower'),
('performance_listening_notes', 875, 'note_en', 'ac0bf61d892eaf02bbf4a794455b2923e34499078d822d09c81c79336908818b', 'At 2:22 it is the longest of the three. It plays the middle one step lower for over 30 seconds, then rises loud near the end.'),
('performance_listening_notes', 876, 'headline_en', '146832dea8883f4661fe683e26bfde387b0dc5a5cf9db78dd8909297731ab0d0', 'Soft through the second half'),
('performance_listening_notes', 876, 'note_en', 'e76a8855afd02f7f1a185f5ec5eeaf6b4b38a2ab1184944e1ee39f4fbe79bdb1', 'Alone among the three, it plays the first refrain one more time, which makes it about 8 seconds longer. Right after its loudest moment it drops sharply, and unlike the other two it doesn''t rise loud again to the end.'),
('performance_listening_notes', 876, 'facts_en', 'e76a8855afd02f7f1a185f5ec5eeaf6b4b38a2ab1184944e1ee39f4fbe79bdb1', '["First refrain repeated"]'),
('performance_listening_notes', 877, 'headline_en', '22bd4b57a94272ee96b8ad04f54561a51bdf1bd9a58f05e8ab16d295f24254d9', 'Slow, sunk deep'),
('performance_listening_notes', 877, 'note_en', '8e8754ac21733db267c668e1069274d22da0128593f31dc10988ba700fc649e1', 'At 2:36 it is the longest of the three. It opens very quietly, and sinks deeper than the other two once more in the early part.'),
('performance_listening_notes', 878, 'headline_en', '0927b887479576f2b2a9039d57347796a3efa674c4eece950b610134f795db7c', 'One deep drop'),
('performance_listening_notes', 878, 'note_en', '5349f0407ff73a11b63609884a697d7f21a888bbd4e165d88e8164ee6920d462', 'About two-thirds of the way through, it sinks the deepest and longest of the three. Going into the ending it doesn''t pull back as far as the other two.'),
('performance_listening_notes', 879, 'headline_en', '3143d316724550bcc402f539b9921f026cd1a66f8ce975645de2da5c89ccb279', 'Even from the start'),
('performance_listening_notes', 879, 'note_en', '06012c76619c1dfa08b01e7c22eace9fc48ba2d1b7231dc24f5c826708c32d25', 'At 1:44 it is 38 seconds shorter than Gould. It reaches near-maximum within 15 seconds and doesn''t change the level much until just before the final chord.'),
('performance_listening_notes', 880, 'headline_en', '08c00a4b4305707ed2a9e46911eca001051730e76735b0f8c1f8b1db4957c996', 'Weight on the later passage'),
('performance_listening_notes', 880, 'note_en', 'c6fc60172e1bb4a4661fec84233d361970daea91ede7f08f655cad16bfa71aa6', 'It pushes at near-maximum for longer in the later passage past the two-thirds mark than in the big passage in the middle. The other two put more weight on the middle.'),
('performance_listening_notes', 881, 'headline_en', '11a65ef9d5a0281170d3278defd3527780bd641e3d447fd5f55d8a8d06d78933', 'Near maximum in one minute'),
('performance_listening_notes', 881, 'note_en', '13e01813f16cae255a8f2251aada41c1d31bd3fea05d62dbff4aa46456520a1d', 'It reaches near-maximum in one minute and carries the whole second half loudly. The quiet passages near the end aren''t sunk as deep as in the other two.'),
('performance_listening_notes', 882, 'headline_en', '67c241c450f6c3264fb97efd67b860afb14036d597cbd6518eb92bb16cfbf19b', 'Opens soft, a long build'),
('performance_listening_notes', 882, 'note_en', '66d9126284e0edaa46a6ad655ebe0bc7453489882682c50d9bd756718d04e78e', 'Unlike the other two, it opens very quietly. It builds step by step for over a minute, pulls back once before the climax, then rises.'),
('performance_listening_notes', 883, 'headline_en', 'f5e4911c95339e95bf32738a0abb445a48c2c9fe9c3f98c03e9888c1dfd40911', 'An unhurried 3:24'),
('performance_listening_notes', 883, 'note_en', '08da4e0d5adc84066d2484f3fb4011608161632e3eadc489e3d5fa26d214b884', 'At 3:24 it runs more than 30 seconds longer than the other two. With 30 seconds to go it falls very quiet for nearly 10 seconds, then rises loud again.'),
('performance_listening_notes', 884, 'headline_en', '9beb6a90ad25a7628c8fe1e0c9406c749c39691a1aab2436e6372e5873ac18a9', 'One step higher at each climax'),
('performance_listening_notes', 884, 'note_en', 'a5f79a3da94d18d4031d42c59221c2a7688ca8bc79064f0352c8314ac1f36756', 'It sets the first climax the lowest of the three and raises each following climax by one step. Once it enters the big passage, it doesn''t come down for over 40 seconds.'),
('performance_listening_notes', 884, 'facts_en', 'a5f79a3da94d18d4031d42c59221c2a7688ca8bc79064f0352c8314ac1f36756', '["Mehta · Philharmonia"]'),
('performance_listening_notes', 885, 'headline_en', '0af4ea25cde9dd9378c3ca3aee3cf6e1815a4fc11e32ae2d34c668cbc6e4e7c8', 'Ends at the opening level'),
('performance_listening_notes', 885, 'note_en', '5d68bbaf8bde45413c239aa76690eba4c42b520bf1f3b7f6c0114ec963ec58fc', 'The flow is almost the same as Harnoncourt''s. The final orchestral passage continues at the same level as the start, and unlike Harnoncourt it doesn''t sink.'),
('performance_listening_notes', 885, 'facts_en', '5d68bbaf8bde45413c239aa76690eba4c42b520bf1f3b7f6c0114ec963ec58fc', '["Collegium Vocale Gent"]'),
('performance_listening_notes', 886, 'headline_en', 'a64b1da97255cf19bba4307838accf5079e48cc17f50d06041b7e9dd0bb27312', 'A winter 33 seconds shorter'),
('performance_listening_notes', 886, 'note_en', '6799cc549995f2231349e510e68dd41d529fd35cd2c372c18e249d255cab21b3', 'At 3:04 it is 33 seconds shorter than the other two. It builds the quiet introduction bit by bit and rises to its loudest within 30 seconds.'),
('performance_listening_notes', 886, 'facts_en', '6799cc549995f2231349e510e68dd41d529fd35cd2c372c18e249d255cab21b3', '["Performance used in \\"Oldboy\\"", "St. Luke''s Chamber Ensemble"]'),
('performance_listening_notes', 887, 'headline_en', '82d0f8ca831d4eff1ac0bb9daeb34d843d202b8db0881669315f1b2b39e9917b', 'Final orchestra sunk deep'),
('performance_listening_notes', 887, 'note_en', 'ea05e405646723542e1c5893bc08aa678b5cf5fe2d664e8eeba663403c07dc35', 'The way it raises the level with each choral line is almost the same as Herreweghe''s. But it sinks the final orchestral passage far lower than at the start before closing.'),
('performance_listening_notes', 887, 'facts_en', 'ea05e405646723542e1c5893bc08aa678b5cf5fe2d664e8eeba663403c07dc35', '["Tölzer Knabenchor"]'),
('performance_listening_notes', 888, 'headline_en', 'bbf986907628c78f8c2552863958be3075fad32f41384b0e61e29acaed1dcd65', 'Quiet passage kept higher'),
('performance_listening_notes', 888, 'note_en', '1d36b4e5fd9af3b5906da2fc72844aca221ffa5140b0d10289c560a349b5672a', 'It lowers the quiet passage in the middle less, and sinks the one that turns quiet again right after it deeper. It also opens the first orchestral passage quietly, setting it against the chorus.'),
('performance_listening_notes', 888, 'facts_en', '1d36b4e5fd9af3b5906da2fc72844aca221ffa5140b0d10289c560a349b5672a', '["Bavarian Radio Symphony"]'),
('performance_listening_notes', 889, 'headline_en', '2530d41a4c877e2784b7e00d70b4640c7a497e01675d8700d51d1859a4e187a2', 'Near maximum again'),
('performance_listening_notes', 889, 'note_en', 'b75b4b49881898f58d38b321bb556a3b25bfcdcacf46c6d65c4def8e86e7ca4e', 'After the first chord it rises to near-maximum again in the second big passage. The quiet passage after that is shorter than in Kanneh-Mason''s.'),
('performance_listening_notes', 889, 'facts_en', 'b75b4b49881898f58d38b321bb556a3b25bfcdcacf46c6d65c4def8e86e7ca4e', '["Previn · London Symphony"]'),
('performance_listening_notes', 890, 'headline_en', 'db8e5a7575575fc5dc11d35038283fc0e84d5119efecfbf2d564b3bc3c64a94f', 'Loud only in the two middle lines'),
('performance_listening_notes', 890, 'note_en', '4dcf4f1151c4f549a39795b2085ad6ad7522f3fc89fbdce00e4fdb584281c27d', 'It is the shortest of the three. Even when the chorus enters it is mostly quiet, rising loud only in the two middle lines and dropping deep again straight away.'),
('performance_listening_notes', 890, 'facts_en', '4dcf4f1151c4f549a39795b2085ad6ad7522f3fc89fbdce00e4fdb584281c27d', '["English Baroque Soloists"]'),
('performance_listening_notes', 891, 'headline_en', '0f592d92f60c0b9fa78e32c2c70a7309712e1eb77bb5b244abfeb80c2a01860a', 'Near maximum in 1:30'),
('performance_listening_notes', 891, 'note_en', 'ac48bc924356badda46ecf33b0e20d1657e0be2471202f2f5c0abb6a88e78074', 'Right after the quiet passage in the middle, it already rises to near-maximum. The other two hold that level back for about another minute.'),
('performance_listening_notes', 891, 'facts_en', 'ac48bc924356badda46ecf33b0e20d1657e0be2471202f2f5c0abb6a88e78074', '["Berlin Phil"]'),
('performance_listening_notes', 892, 'headline_en', '4c683066463db1c750a6092b04ee368b27bbde1d87a894382037f96eaf783d9d', 'The deepest quiet passage'),
('performance_listening_notes', 892, 'note_en', '37b88404afff85532559ee5f83036d83bad37260e3472a468bfbe2307b4d3a43', 'It sinks the quiet passage in the middle the deepest of the three, then rises loud immediately. It saves near-maximum until 70 seconds before the end.'),
('performance_listening_notes', 892, 'facts_en', '37b88404afff85532559ee5f83036d83bad37260e3472a468bfbe2307b4d3a43', '["Chicago Symphony"]'),
('performance_listening_notes', 893, 'headline_en', '2ea05bb7c31be4105e92162bb8368f4f608c533d6a94b23f8a338e420f2d1639', 'A deeply sunk middle'),
('performance_listening_notes', 893, 'note_en', '65a954547a6762ef99b992e0caab52a7f069fad3caa8fbbad9b43fdedeafe961', 'The quiet passage in the middle of the introduction is the deepest of the three. The big passage that rises again later isn''t raised as high as in Yo-Yo Ma''s and Schiff''s.'),
('performance_listening_notes', 893, 'facts_en', '65a954547a6762ef99b992e0caab52a7f069fad3caa8fbbad9b43fdedeafe961', '["Rattle · London Symphony"]'),
('performance_listening_notes', 894, 'headline_en', 'd0e08c0f2679873fd6e8fbba8867bd30af5772c260b0bc09b927b9d846acdbe2', 'A quiet first 40 seconds'),
('performance_listening_notes', 894, 'note_en', '50b021b93e905c5bf84fed886e5ec2ed39aaf26bb70f874fb95b8f219803849f', 'The first 40 seconds before it rises loud are longer and quieter than in the other two. Right before the first climax it pulls back deep, then climbs loud within 7 seconds.'),
('performance_listening_notes', 894, 'facts_en', '50b021b93e905c5bf84fed886e5ec2ed39aaf26bb70f874fb95b8f219803849f', '["Pappano"]'),
('performance_listening_notes', 895, 'headline_en', 'd37be01a4792247db42f167de72d346b1169f23b33aef11167b3e3dde3e1b638', 'A long, growing introduction'),
('performance_listening_notes', 895, 'note_en', 'dde28c2b41a6f18763c81f1abbe972599d85dfa2d7f407a9d2f9b1e4014be070', 'Like Kremer, it draws out the introduction for nearly 40 seconds, but grows a little all the while. In the middle of the later quiet passage it rises loud once and then comes back down.'),
('performance_listening_notes', 895, 'facts_en', 'dde28c2b41a6f18763c81f1abbe972599d85dfa2d7f407a9d2f9b1e4014be070', '["Mehta · Israel Phil"]'),
('performance_listening_notes', 896, 'headline_en', '388f9a2c3979faf4c063c4aeded974b1d0572b5c13c8acb37172b1ea330b26e2', 'A softer end to the introduction'),
('performance_listening_notes', 896, 'note_en', '005cccc32566bcc97f4afe348aafbc80da2b2a777c4aff7446512d3d9dd4b08f', 'It draws out the introduction for over 40 seconds, dropping softer just before it begins to swell. Unlike Perlman, it never raises the later quiet passage loud for nearly a minute.'),
('performance_listening_notes', 896, 'facts_en', '005cccc32566bcc97f4afe348aafbc80da2b2a777c4aff7446512d3d9dd4b08f', '["Abbado · London Symphony"]'),
('performance_listening_notes', 897, 'headline_en', 'e9747b0e28c976869a16064d428e73819b0a205953b5b9cb4702a4193a6e5449', 'Loud for over 18 seconds'),
('performance_listening_notes', 897, 'note_en', '0741e8071e7181df2d07dcb6ae3caaa9065a692b4f896a0daa627bcd9e185560', 'It stays loud for over 18 seconds from the first chord, about 8 seconds longer than the other two. It passes through the quiet passage in the middle much more shallowly than Kanneh-Mason does.'),
('performance_listening_notes', 897, 'facts_en', '0741e8071e7181df2d07dcb6ae3caaa9065a692b4f896a0daa627bcd9e185560', '["Marriner · Dresden Staatskapelle"]'),
('performance_listening_notes', 898, 'headline_en', 'b38318b8ec6b102c4509136100a4fb11369bcbdb87ad12685a115c43fb53ba0e', 'Loud from the first climax'),
('performance_listening_notes', 898, 'note_en', '26fe98922199e9328f8b185635abb2be36691b432750cedf402d84e228007673', 'Unlike Domingo, it sings the first climax almost as loud as the last. The second climax is at almost the same level as the first.'),
('performance_listening_notes', 898, 'facts_en', '26fe98922199e9328f8b185635abb2be36691b432750cedf402d84e228007673', '["Davis · Royal Opera House"]'),
('performance_listening_notes', 914, 'headline_en', '151122589d0e840c078e9bf9aa2d59953b2499f4ddedab7c3ecb05410f6bcdec', 'A step back after the first chord'),
('performance_listening_notes', 914, 'note_en', 'c2fb6ad703d032a61fb865fb3d3e6c7cdc7ad84d500f1f6c8ef87ddab6b2304d', 'At 1:36 it runs over 5 seconds longer than the other two. After the first chord of the brass theme it steps back, then rises loud again in the repeat.'),
('performance_listening_notes', 914, 'facts_en', 'c2fb6ad703d032a61fb865fb3d3e6c7cdc7ad84d500f1f6c8ef87ddab6b2304d', '["Berlin Phil"]'),
('performance_listening_notes', 915, 'headline_en', '912b6cdda46ec7b9816f8dd32fcbc579cf575181ca358131be0e66077dfccc6a', '3:55, pulling back often'),
('performance_listening_notes', 915, 'note_en', '2e32b6d930db1a50e687d9aea8126783634d14f84b1afdd0d88215d539ab523e', 'At 3:55 it runs over 24 seconds longer than the other two. In the fast passage it pulls back deeply several times and then surges again.'),
('performance_listening_notes', 916, 'headline_en', 'f7199f912911dcb7e88013a0d5654dc197e4c2e5f32f1642f0e84f8bdc24041c', '1:18, a steady descent'),
('performance_listening_notes', 916, 'note_en', '712175f4b3256fb8558ef38395b4bd82b32e5e8cbe81a4891537bb8585296a68', 'At 1:18 it is 15 seconds shorter than Boulez and 37 seconds shorter than Karajan. After the very loud spot it never climbs again, and descends steadily to the end.'),
('performance_listening_notes', 916, 'facts_en', '712175f4b3256fb8558ef38395b4bd82b32e5e8cbe81a4891537bb8585296a68', '["Chicago Symphony"]'),
('performance_listening_notes', 917, 'headline_en', '9d391d4d27513f73f2fe59a601e9dd45f63be6942ab17ac64c9982800e5c565d', 'Deep through the middle'),
('performance_listening_notes', 917, 'note_en', '8d7344a25fe0fdcb446963bae5433466ba972131d0c7bf704fa1bf29f9245025', 'It holds the quiet passage in the middle at the lowest level of the three throughout. It opens the fanfare quieter than the other two, too, and builds up loudly.'),
('performance_listening_notes', 917, 'facts_en', '8d7344a25fe0fdcb446963bae5433466ba972131d0c7bf704fa1bf29f9245025', '["Philharmonia"]'),
('performance_listening_notes', 918, 'headline_en', '0ac739fec0d188c8dc6daa099b4d530a171a766e6bdc2b16b17bde796337b44e', 'The softest fugato'),
('performance_listening_notes', 918, 'note_en', 'f7669461c5410102ad78896ddc4b9f1665228b60cdd9f3b5e3f1c342d5daa78f', 'It plays the fugato for solo piano the quietest of the three. At the big climax it hits near-maximum briefly three times.'),
('performance_listening_notes', 918, 'facts_en', 'f7669461c5410102ad78896ddc4b9f1665228b60cdd9f3b5e3f1c342d5daa78f', '["Nelsons · Boston Symphony"]'),
('performance_listening_notes', 919, 'headline_en', 'ab05bf5f02ea32fedaba42ba49e9949a91a7ecefd62806577ff380c9950c7ce6', 'Quiet passages not lowered as much'),
('performance_listening_notes', 919, 'note_en', '17c0de2530c0f9dc156958b40113163968a33e593c2605d92f6e883d0a7f2179', 'It lowers the D minor passage and the closing passage less than the other two. It also rises to the big climax earlier than the other two and keeps it loud for over 40 seconds.'),
('performance_listening_notes', 919, 'facts_en', '17c0de2530c0f9dc156958b40113163968a33e593c2605d92f6e883d0a7f2179', '["Wolff · Saint Paul Chamber Orchestra"]'),
('performance_listening_notes', 920, 'headline_en', 'fd464af0ec9d1ab498801ceeb57527856274b295e5562a54211260ab630c47ee', 'The climax one step later'),
('performance_listening_notes', 920, 'note_en', '2a3453ccae485df2dcbd625f905d7b1fd4c2d25978b90be0a5a4821a8720e9fc', 'After one loud hit on the very strong chord, it rises louder about 10 seconds later. Its time at near-maximum is the shortest of the three.'),
('performance_listening_notes', 920, 'facts_en', '2a3453ccae485df2dcbd625f905d7b1fd4c2d25978b90be0a5a4821a8720e9fc', '["Vienna Phil"]'),
('performance_listening_notes', 921, 'headline_en', '37a5ceb66db731c9303c97b55ebc016ce79dc3359b7009f3339a17880f602eb1', 'The longest loud passage'),
('performance_listening_notes', 921, 'note_en', '96e23251893ea958b82f7a2e1b520df58505ff6984a46737534fc83decb67f66', 'It sustains the loud passage about 10 seconds longer than the other two. Unlike Solti, it doesn''t come down deep at the end and closes loudly.'),
('performance_listening_notes', 921, 'facts_en', '96e23251893ea958b82f7a2e1b520df58505ff6984a46737534fc83decb67f66', '["LA Phil"]'),
('performance_listening_notes', 922, 'headline_en', 'fd2c1d25b154d271fcc62a3d19fc35860a3f7c8485c1597e461b59a76d1d96d9', 'D minor passage sunk deep'),
('performance_listening_notes', 922, 'note_en', '1673caa0008fb09b07e065aafc183ead64d491f1b54279a36ff0ce2a2d64941d', 'It lowers the D minor passage deeper than the other two. At the big climax it holds near-maximum as one block for over 20 seconds.'),
('performance_listening_notes', 922, 'facts_en', '1673caa0008fb09b07e065aafc183ead64d491f1b54279a36ff0ce2a2d64941d', '["Currentzis · Mahler Chamber Orchestra"]'),
('performance_listening_notes', 923, 'headline_en', '1e7d74475fd726834a48e7e885623ca6481509c416164a28f8427cdab62f2ac9', 'The last minute near maximum'),
('performance_listening_notes', 923, 'note_en', '8680cb2810490e5c858aa9c4dd847ff8c37bd579616de552828001c21eb41f38', 'It drives the whole last minute close to near-maximum. It lowers the quiet passage in the middle less than Muti does.'),
('performance_listening_notes', 923, 'facts_en', '8680cb2810490e5c858aa9c4dd847ff8c37bd579616de552828001c21eb41f38', '["Montreal Symphony"]'),
('performance_listening_notes', 924, 'headline_en', '5f478aae735d77a4bbfbbd26307000e3b76ec70250e049bbb04e7fe9e569d0e7', 'Near maximum on arrival'),
('performance_listening_notes', 924, 'note_en', '0bef379f5619d3eaf49f853d513965f0a30f90f07b79a1a9dc95babb2513426f', 'It reaches near-maximum the moment it enters the fast passage. Except for one break, it never backs off, and it sustains loud playing the longest of the three.'),
('performance_listening_notes', 925, 'headline_en', '50b0e5cf127bc339edd9026898ef73a37b5194746b3059c5138c711bd685fc4e', 'Maximum held back to the end'),
('performance_listening_notes', 925, 'note_en', 'bfaa704c040a89156cc5da5dfaafa361956f58cac916e7ef8cdcf5a28734e517', 'Throughout the fast passage it pushes along one step lower, reaching near-maximum only about 40 seconds before the end. The other two get there within the first 40 seconds.'),
('performance_listening_notes', 926, 'headline_en', '22e191bf60c0ffdf31192f4cc3ff6c98af619e14ce06cf86267e463eeac816d7', 'Maximum only at the final chord'),
('performance_listening_notes', 926, 'note_en', '86c78fc40e1ebfe31c5f0360c6525acb6c13358dcf99050acfa2b463bbfaef6d', 'It opens the fanfare loudly from the start and saves near-maximum for the very last chord. The other two reach it once earlier, after two minutes.'),
('performance_listening_notes', 926, 'facts_en', '86c78fc40e1ebfe31c5f0360c6525acb6c13358dcf99050acfa2b463bbfaef6d', '["Berlin Phil"]'),
('performance_listening_notes', 927, 'headline_en', 'b1ebefd09ce0175811dbc19b063ed692b4d3cafd8f2a11ec28f3fd9aa713307c', 'Rises again before the end'),
('performance_listening_notes', 927, 'note_en', '2813abb1cbc8d80c81a31930a308e9e8cb53b37c09ec8ed1169bec432e8200e4', 'At 1:55 it runs over 20 seconds longer than the other two. After the climax it sustains loud playing for over 30 seconds, and rises once more about 30 seconds before the end.'),
('performance_listening_notes', 927, 'facts_en', '2813abb1cbc8d80c81a31930a308e9e8cb53b37c09ec8ed1169bec432e8200e4', '["Berlin Phil"]'),
('performance_listening_notes', 928, 'headline_en', '6d0d2ffe90a35d8b75fd5dd0101bc9cd151642435ab224e77a3a997d8a041c31', 'Loud from the start'),
('performance_listening_notes', 928, 'note_en', '4ed3e8d1351387d5cf85d810f7e0eb1a0b1480f753e61180dd1793af133143c7', 'It opens the strings the loudest of the three, so the gap to the brass theme is small. Toward the end, unlike Dudamel, it comes down deep.'),
('performance_listening_notes', 928, 'facts_en', '4ed3e8d1351387d5cf85d810f7e0eb1a0b1480f753e61180dd1793af133143c7', '["Chicago Symphony"]'),
('performance_listening_notes', 944, 'headline_en', '95474256a01f96a45d49ff249185b7f6ed66a2d536f4d77e5ccc49ffc817e87b', 'The loudest sound in the final section'),
('performance_listening_notes', 944, 'note_en', 'ab663953ded0748cd48b14c7e4763cae3f3b6bda1dcfeb584d1c0fb9fa3a95d3', 'It plays the opening theme far lower than the final section, and the A major section in the middle slightly higher than that. It also sinks the quiet passages the deepest of the three.'),
('performance_listening_notes', 945, 'headline_en', '613c1eaf8bbb3618ac52bca4f8e31ba3bd5284ac53ce42ac98960c306a8b1aa3', 'The most unhurried of the three'),
('performance_listening_notes', 945, 'note_en', '11bd5eebd2abd639d153411c196c7bf40e153321d8b6c25947b6fd95dbcdb19f', 'At 3:55 it is the longest of the three. It opens louder than the other two from the start, and brings the big early passage close to the level of the last.'),
('performance_listening_notes', 946, 'headline_en', '258697d49e98a45eecac1be7ef7c7058a4e225a42e0350710aeb0525ad7fe546', 'Maximum from the first theme'),
('performance_listening_notes', 946, 'note_en', 'daba1ce93cde5b124b5df1cb443ffbaff2e4de57263de056a3416c612793fa6f', 'It already plays its loudest in the strong passage of the early theme. It pushes the final section just as hard, and unlike Zimerman it doesn''t save it for the end.'),
('performance_listening_notes', 947, 'headline_en', '0ab372887bf5d137439e132d1ff99ee3be150cd7f6d5791c6f4eaea5a8b5d2a6', 'Up a step, then steady'),
('performance_listening_notes', 947, 'note_en', 'd5a8d8fe2dd34ae450ba50a6176e28a996592c89311d3d5a38c139018f1c4f82', 'At 1:24 it falls between the other two performances. Around 20 seconds it moves up one step and walks at the same level for over 30 seconds, then rises again at the loud chord.'),
('performance_listening_notes', 948, 'headline_en', '9c98a5881bc379d14753b03490b6463d7fc185ea74f523d1be187da9568041ed', 'All pushed to the end'),
('performance_listening_notes', 948, 'note_en', '2829cb7385403af55f341951f0db4857e6cd412c71d39cedc77e07f00dd9fbbf', 'At 3:29 it is 26 seconds shorter than Yeol Eum Son. It keeps the early big passage low and raises everything at once in the last big passage.'),
('performance_listening_notes', 949, 'headline_en', '8faf893786397d119fa02cb91a4005b3231fcca7045a722caebe0d89044e03ac', 'Loud from the first strong passage'),
('performance_listening_notes', 949, 'note_en', '3b8ccc8c096936e8e60abdfdce01b8a48bcaa028896294e9921cc7b583cea526', 'At 4:11 it is the shortest of the three. It plays near-maximum from the first strong passage, and sinks the quiet passage after the climax very deep.'),
('performance_listening_notes', 950, 'headline_en', 'f8a17c4f8f356c9cba766a85ecb07f267a522be9eda264843955dadec4e47975', 'Loud even in the quiet march'),
('performance_listening_notes', 950, 'note_en', 'a760c0c30c8b51b7837f46749ba165bd6fdb2149dedb3e57b0a3cdb494595b7e', 'At 1:13 it is the shortest of the three. It rises close to maximum right in the middle of the quiet march, so the gap to the loud-chord passage is small.'),
('performance_listening_notes', 951, 'headline_en', '0699bb84fdb2ad8ac825443b5776bd483374763b291b745fc9121477506815ab', 'A long, loud final section'),
('performance_listening_notes', 951, 'note_en', '69b0b0249ad1a7d6c5ec31b1f4420654789ef55d37fef186d2ed2361c8f5ea08', 'It plays the early strong passage louder than Zimerman, and carries the final section loudly for about 30 seconds longer than Zimerman.'),
('performance_listening_notes', 952, 'headline_en', '89a7b71cea20cf8c0268c5cc777482376db860a4853dfd65a54f2e23a9797224', 'Loud again at the close'),
('performance_listening_notes', 952, 'note_en', '560f6bee557689457b552658698836750a050698f488f3e3421fdbcfaf17228f', 'After the climax it lowers the quiet passage as deep as Shelley does, then rises loud once more at the A major close. Shelley doesn''t build the close that much.'),
('performance_listening_notes', 953, 'headline_en', '9b2ae0e1f1f32984d0a11d41928885908dcfb626978565e7bb715d33f07532a9', 'Growing toward the middle'),
('performance_listening_notes', 953, 'note_en', 'd4d22b98b018b01ee20f443f55a98a13339ca5533bb6e39e48e8d10f3198445c', 'The loudest sound, which Ashkenazy places at the start and Pollini toward the back, this one places right in the middle. It drops low once early on, then grows toward the middle.'),
('performance_listening_notes', 954, 'headline_en', 'c42602f826f0d7398ceeb4d0fd795d1f147fa672bd734169423c43026e764784', 'Near maximum in the first 4 seconds'),
('performance_listening_notes', 954, 'note_en', 'd7823391f347800e3ccf164b6544c5ef705589928ca8a9cebae50e43026f9fb1', 'It reaches near-maximum within the first 4 seconds and puts its loudest sound at the beginning too. The other two play their loudest after more than a minute.'),
('performance_listening_notes', 955, 'headline_en', '0505092a410e2e6e83e2fc2721c220a2285fe3d317de3856da37556ecd393aeb', 'Long and even'),
('performance_listening_notes', 955, 'note_en', 'f91845a8fc78f4682e55c9cdfb9196025776efc6976e8c6933ef7951166a5546', 'At 4:50 it runs 39 seconds longer than Shelley. It doesn''t lower the quiet passages as deep as the other two, and carries the loud passage at the climax longer.'),
('performance_listening_notes', 956, 'headline_en', '771accc0ece5bd1da27f4dc7bb0b9fd535be3775e029a6ed2028901f2a5e4fcc', 'Quiet up to the loud chords'),
('performance_listening_notes', 956, 'note_en', '327ddd44b3d2452ef32c6370a25be37186c8c6410dbb54135b0af8fc0e528967', 'At 1:31 it runs 18 seconds longer than Argerich. It holds a quiet walk low for over a minute, then rises all at once at the loud chords.'),
('performance_listening_notes', 957, 'headline_en', '5bcf2a7ab8b2b586dd68dcd32c75896168c9b821f1e8ba3b9143bccc9b9df499', 'A final section with no retreat'),
('performance_listening_notes', 957, 'note_en', '9b6f036faf1e75c7cc97c2a4ed022651fbcb2b8f2165cfa20d97afbd570b0435', 'It pushes the last big passage loudly for nearly a minute without once backing off. The other two come down once before it, then rise again.'),
('performance_listening_notes', 958, 'headline_en', '71ac0dc93a27c668d4667bcb8b135048f4e8da584b7e0799848534f93a47f682', 'Maximum only late'),
('performance_listening_notes', 958, 'note_en', '22a078e1ac1324a0645e15a5fda227557815c87a4ad523acea56dad930080dba', 'The difference in level is the smallest of the three, so it pushes evenly from start to finish. Its loudest sound comes about 20 seconds before the end.'),
('performance_listening_notes', 971, 'headline_en', 'a7ed3348bc30958a8672c9510d1abefd3c5fd4dc2fb00c706adf7d057479a137', 'Near maximum only late'),
('performance_listening_notes', 971, 'note_en', '7968029d09d61f916a83eb4d21d488f923356c6aeaadf5d2ce2435f5f035586c', 'It reaches, just short of four minutes in, the level that the other two hit at the orchestral opening. The early step back is also the deepest of the three.'),
('performance_listening_notes', 971, 'facts_en', '7968029d09d61f916a83eb4d21d488f923356c6aeaadf5d2ce2435f5f035586c', '["Abbado · Chamber Orchestra of Europe"]'),
('performance_listening_notes', 972, 'headline_en', '16b50c330738d4e321ac08db112edd68af6cfa3a2692cfdc379522ddd34e5538', 'Low until a minute before the climax'),
('performance_listening_notes', 972, 'note_en', 'c690d330af69542d1166fe2d4d66cedc00a3faef2aee40766da36ea7bead338f', 'It sets the early climb the lowest of the three and rises all at once from a minute before the climax. Soon after the climax it rises loud once more.'),
('performance_listening_notes', 972, 'facts_en', 'c690d330af69542d1166fe2d4d66cedc00a3faef2aee40766da36ea7bead338f', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 973, 'headline_en', '7db115a2548606386b907d9ec42292bf066402c055cf570310623ed426f18309', 'The deepest end of the oboe passage'),
('performance_listening_notes', 973, 'note_en', 'd6d5d81294a00195fe480796c7352991e4c4cc4669928d41e11d64d22ec90787', 'Even when the theme repeats it pushes near-maximum. The very quiet spot at the end of the oboe passage is sunk the deepest of the three.'),
('performance_listening_notes', 973, 'facts_en', 'd6d5d81294a00195fe480796c7352991e4c4cc4669928d41e11d64d22ec90787', '["Vienna Phil"]'),
('performance_listening_notes', 974, 'headline_en', '57681861672ce6182a8fc46d620f5c28dfd0cca1f5baa6446994ddda040065ba', 'Near maximum just once'),
('performance_listening_notes', 974, 'note_en', 'ad6f1859bc7113c6c20f72fc23372eb4828c3b11732f5775701aef5e6281d13b', 'It plays near-maximum only once, in the first third. Its length is similar to Böhm''s, but it lowers the middle less than Böhm does.'),
('performance_listening_notes', 974, 'facts_en', 'ad6f1859bc7113c6c20f72fc23372eb4828c3b11732f5775701aef5e6281d13b', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 975, 'headline_en', '5be9bcd45c0c1cf657dd08c974db8979fd7a716fe3e10dec8995962dbe616475', 'A step lower after the climax'),
('performance_listening_notes', 975, 'note_en', 'a0fbf683f9afd04992ec86cc502cacc80ad706722bc4bcb01df946969dec03e3', 'It builds the climb in the middle loudly too, and plays the climax in one go. Unlike the other two, it doesn''t rise loud again after the climax and continues one step lower.'),
('performance_listening_notes', 975, 'facts_en', 'a0fbf683f9afd04992ec86cc502cacc80ad706722bc4bcb01df946969dec03e3', '["St. Louis Symphony"]'),
('performance_listening_notes', 976, 'headline_en', '2f6c7254dfe6d6cb1051eba10b9de8b4bc500e952456dbf64a603f56a257bd52', 'Soft from the repeated theme'),
('performance_listening_notes', 976, 'note_en', '4df6112f242f2196df9225bb69f7e9e50185b31b9d8f4ce81ee7d6238e02463b', 'Unlike the other two, it already lowers the level when the theme repeats. At 1:01 it is 9 seconds shorter than Böhm.'),
('performance_listening_notes', 976, 'facts_en', '4df6112f242f2196df9225bb69f7e9e50185b31b9d8f4ce81ee7d6238e02463b', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 977, 'headline_en', '1f5fc7fef3ef53cbed5fc7ec9a3f7babe42e5c7f236d63d3ac6e5aaf0c9ce3e9', 'An unhurried 7:04'),
('performance_listening_notes', 977, 'note_en', '17281e942e7de2901e52009ac14dd4908e63c2b7cc33004b37ad4f971c8843b2', 'At 7:04 it runs about 55 seconds longer than the other two. It rises to its loudest where the orchestra rounds off the theme, and unlike Pires it doesn''t hold back until the second half.'),
('performance_listening_notes', 977, 'facts_en', '17281e942e7de2901e52009ac14dd4908e63c2b7cc33004b37ad4f971c8843b2', '["Marriner · Academy of St Martin in the Fields"]'),
('performance_listening_notes', 978, 'headline_en', 'd7db2cf78560365acc714610df580a46102d3682d8cfdf3589460f35eeef4776', 'A quick 4:57'),
('performance_listening_notes', 978, 'note_en', '1266e5f3f78f499104f566e64e066597d87ddfee4d927278b50efed652295b60', 'At 4:57 it is over 40 seconds shorter than the other two. It climbs close to near-maximum far more often than Böhm does.'),
('performance_listening_notes', 978, 'facts_en', '1266e5f3f78f499104f566e64e066597d87ddfee4d927278b50efed652295b60', '["Zurich"]'),
('performance_listening_notes', 979, 'headline_en', '2d0260cc21b971006e9745345607a39b284a7bcc44bb7fd81c02fad97c5f6726', 'The middle pressed low'),
('performance_listening_notes', 979, 'note_en', '1d3f21e813ab26e49323a77f5862aab61466590c8fc69873406f8f8854a9c3eb', 'It holds the middle the lowest of the three and has only two brief loud spots. At 5:50 it runs 53 seconds longer than Harnoncourt.'),
('performance_listening_notes', 979, 'facts_en', '1d3f21e813ab26e49323a77f5862aab61466590c8fc69873406f8f8854a9c3eb', '["Berlin Phil"]'),
('performance_listening_notes', 980, 'headline_en', '5678e74c713c5b9c0bf29c0c8fe94070ab23fb2acdd18075615075b3cb99230f', 'A slow 8:33'),
('performance_listening_notes', 980, 'note_en', 'a3d3299b07556a845108a4cc30b3c0b22c05f101c7e5d8be06acaac5762a6d39', 'At 8:33 it runs over a minute longer than the other two. It holds loud for 40 seconds around the climax, drawing it out over 15 seconds longer than the other two.'),
('performance_listening_notes', 980, 'facts_en', 'a3d3299b07556a845108a4cc30b3c0b22c05f101c7e5d8be06acaac5762a6d39', '["Baltimore Symphony"]'),
('performance_listening_notes', 981, 'headline_en', '7d2525e1f6105e824a12edff765e75285ccdca39ef5dc1c2cd88e8849da440bc', 'A slow 1:10'),
('performance_listening_notes', 981, 'note_en', '490b5660eede0c376c0872eb5c9e3da62386ec62fd3a6fa0553a1afc74bb3731', 'At 1:10 it runs 9 seconds longer than Marriner. The flow is almost the same as Bernstein''s, but it lowers the oboe passage less than Bernstein does.'),
('performance_listening_notes', 981, 'facts_en', '490b5660eede0c376c0872eb5c9e3da62386ec62fd3a6fa0553a1afc74bb3731', '["Berlin Phil"]'),
('performance_listening_notes', 982, 'headline_en', 'ac97aafa1301a359beea192e421fd5e15636a1ca82bae3dcea0ed5722f575d0b', 'Maximum at the first wind chord'),
('performance_listening_notes', 982, 'note_en', '761ea4e9eec40e158c94f78264766a749cea9278eb20bd06289e9512e058deff', 'It already reaches its loudest at the opening chord, where the winds cut in strongly. Unlike Pires, it reaches near-maximum several more times early on.'),
('performance_listening_notes', 982, 'facts_en', '761ea4e9eec40e158c94f78264766a749cea9278eb20bd06289e9512e058deff', '["Zacharias · Bavarian Radio"]'),
('performance_listening_notes', 998, 'headline_en', '28a2096f393134f7faf39f96aa59161ac11d04bc3f93b875048109486a2ca829', 'The shortest, 3:21'),
('performance_listening_notes', 998, 'note_en', 'be578e1ee871adff5f706168337356266035dfbadf868985232ad46794f49365', 'It is 34 seconds shorter than Bernstein and 18 seconds shorter than Nézet-Séguin. In the big passage at the end, it spends the least time at near-maximum of the three.'),
('performance_listening_notes', 998, 'facts_en', 'be578e1ee871adff5f706168337356266035dfbadf868985232ad46794f49365', '["Seoul Phil"]'),
('performance_listening_notes', 999, 'headline_en', '792685aa5fdfd79d4e2b4646057722f038bea82997e87a305c5be600f5ba7bf6', 'One big swell in the middle'),
('performance_listening_notes', 999, 'note_en', '2de5330a94bfa2ae6b7575bcd70565b705d2de5867390375477c82de84913b7e', 'Like Gardiner, it comes in loud from the start, but it rises once more right in the middle and then returns to the earlier level.'),
('performance_listening_notes', 999, 'facts_en', '2de5330a94bfa2ae6b7575bcd70565b705d2de5867390375477c82de84913b7e', '["Ensemble Correspondances"]'),
('performance_listening_notes', 1000, 'headline_en', 'a429ec4b42d8b7d6621fa562824ddc4f264f1dca18747850db95aaabcc43f33e', 'A soft final minute'),
('performance_listening_notes', 1000, 'note_en', '2d292794a7a0e7ec5d7015bd5d529d6f455d8fb0563b0a28d252c265acdcecb2', 'It is 1:22 shorter than Fischer-Dieskau. It rises loud in several places, and closes the final minute a step quieter than the other two.'),
('performance_listening_notes', 1000, 'facts_en', '2d292794a7a0e7ec5d7015bd5d529d6f455d8fb0563b0a28d252c265acdcecb2', '["Norrington · Camerata Salzburg"]'),
('performance_listening_notes', 1001, 'headline_en', '9c4f5eee595b0a42db41bf98c626801596fe5b13f13293d90d7765304a41a906', 'Opens soft, building to the middle'),
('performance_listening_notes', 1001, 'note_en', '9b6ec02e11e77471e8f7e76608f1c9816dce658f98084e4144c28e82ae7c9e94', 'It opens quieter than Gardiner and Daucé, and grows bit by bit toward the middle. It touches near-maximum only briefly and soon eases back.'),
('performance_listening_notes', 1001, 'facts_en', '9b6ec02e11e77471e8f7e76608f1c9816dce658f98084e4144c28e82ae7c9e94', '["Leonhardt-Consort"]'),
('performance_listening_notes', 1002, 'headline_en', '0eef01b21c49b8d35b600af8418a3f5e02813de5dc879d288b4f02c8c0ebfb9d', 'Climax early on'),
('performance_listening_notes', 1002, 'note_en', 'a54f067289e32ea18f16ce1b91c864324e2230055ad02c194782d4f86eef4aca', 'It plays its loudest around the 30-second mark. It doesn''t sink the middle as deep as Yunchan Lim does, and eases down gradually over the last 30 seconds.'),
('performance_listening_notes', 1003, 'headline_en', '690afb483966867f4e243b8b24dbeda20946dfe7dee476ea08ecf69631e7e53b', 'Less hushed through the song'),
('performance_listening_notes', 1003, 'note_en', '37677240d62b8d704b892e8cc40033261a282448693d99157a43738190ba2f4c', 'There are fewer places where the level drops far during the singing than in the other two. It opens less quietly, right from the string prelude.'),
('performance_listening_notes', 1003, 'facts_en', '37677240d62b8d704b892e8cc40033261a282448693d99157a43738190ba2f4c', '["Paavo Järvi · Estonian National Symphony Orchestra"]'),
('performance_listening_notes', 1004, 'headline_en', '66ca794e9862fc182beac5f518bfbb3cb7944e293bb8ca0ea91bfe7df09c00f2', 'Frequent loud rises'),
('performance_listening_notes', 1004, 'note_en', '6143593ade2f1208af9fa8f12b1f2354be6f79430b8eff76b7d5d6bcb1e9893d', 'It has more places where it rises loud than the other two. The loudest sound comes about a minute before the end.'),
('performance_listening_notes', 1004, 'facts_en', '6143593ade2f1208af9fa8f12b1f2354be6f79430b8eff76b7d5d6bcb1e9893d', '["Neeme Järvi · Gothenburg Symphony"]'),
('performance_listening_notes', 1005, 'headline_en', '8dbcf9cd19f4a20b181964b352c97e941a2f558fd1bc3c6e5cff988f9f16c10f', 'Holds an even level'),
('performance_listening_notes', 1005, 'note_en', '683626a65ab972265abb0131c86007d5f6b52b7146857e1205ce24bceff28c4a', 'It doesn''t sink far in the middle either, and spaces its loud rises evenly in several places. The loudest sound comes right in the middle.'),
('performance_listening_notes', 1006, 'headline_en', 'f5b6015fe7c07a9301945cd44b05e6b3143d9f5336c33c47b9dcd66b49c4a795', 'The last 30 seconds near maximum'),
('performance_listening_notes', 1006, 'note_en', '0ea5702e2fefe79cbbdf447abe1042153fb7d371e587f38d3756f14ec6cf036b', 'At 3:55 it runs 34 seconds longer than Myung-Whun Chung. It doesn''t rise loud until the big passage near the end, but once there it never comes down from near-maximum.'),
('performance_listening_notes', 1006, 'facts_en', '0ea5702e2fefe79cbbdf447abe1042153fb7d371e587f38d3756f14ec6cf036b', '["New York Phil"]'),
('performance_listening_notes', 1007, 'headline_en', '6375f2b3c6745c9643fdebf3c4cdeb54b25e1c7ead9fbe930855c472af1741cf', 'A packed 2:30'),
('performance_listening_notes', 1007, 'note_en', 'fc869cfd02e2b4eaa25c3582b4909802e990bf791911be46073102734a5356cf', 'Unlike Leonhardt, it doesn''t open quietly; it rises loud within 30 seconds and keeps that level to the end. It plays loud for the longest time of the three.'),
('performance_listening_notes', 1007, 'facts_en', 'fc869cfd02e2b4eaa25c3582b4909802e990bf791911be46073102734a5356cf', '["English Baroque Soloists"]'),
('performance_listening_notes', 1008, 'headline_en', 'de089e2e1c8853b9d0fc16e34e676184b2f72c0e5caea45f5c6ec4454f518f21', 'Loud from the middle peak'),
('performance_listening_notes', 1008, 'note_en', 'ea232f36a9ea7736daf3533d00184f7420163f72d9de1434647ec4eb95d8b53c', 'It raises the middle peak louder than the other two. In the big passage at the end it reaches near-maximum, steps back once, then rises again.'),
('performance_listening_notes', 1008, 'facts_en', 'ea232f36a9ea7736daf3533d00184f7420163f72d9de1434647ec4eb95d8b53c', '["Rotterdam Phil"]'),
('performance_listening_notes', 1009, 'headline_en', '52a5c54dce7ea35483e0f013d89d2d66d37d4411022ef630aaf9911d5aa712c5', 'Deep hush in the middle'),
('performance_listening_notes', 1009, 'note_en', '8840bed97ec5ec4c6ddb6549c171feef82481fea3c67d58c864fbf36d1c1d9cb', 'At 2:24 it is the shortest of the three. In the middle it sinks far quieter than the other two, then afterward rises to its loudest.'),
('performance_listening_notes', 1010, 'headline_en', '27577f7f7c472ada2b6ce6a3e8725f9be24b837e1d3627176d274a6fb461ccfb', 'Only one big peak'),
('performance_listening_notes', 1010, 'note_en', 'cf50060a7955def8048fb8e31353a7503391c5d3175686d9abcc649e013fe72e', 'It is similar in length to Goerne''s, but rises high in only one place. The rest continues evenly at similar levels.'),
('performance_listening_notes', 1010, 'facts_en', 'cf50060a7955def8048fb8e31353a7503391c5d3175686d9abcc649e013fe72e', '["Müller-Brühl · Cologne Chamber Orchestra"]'),
('performance_listening_notes', 1011, 'headline_en', '960ff5754b35f09b08830494fb2987e07c0e5490a9f51e726e36ac3e9bf98d38', 'A slow song at 5:52'),
('performance_listening_notes', 1011, 'note_en', '0d1872565cea843bb1c713d89577b9c6c5c0e4297eb52dac41935d24f650e579', 'It runs around a minute longer than the other two. It opens the prelude the quietest of the three, and its quiet passages are more frequent and deeper than in the other two.'),
('performance_listening_notes', 1011, 'facts_en', '0d1872565cea843bb1c713d89577b9c6c5c0e4297eb52dac41935d24f650e579', '["Salonen · Oslo Phil"]'),
('performance_listening_notes', 1012, 'headline_en', '8982086e1dcf7938a8a6e9bf94a8b656fdc5d729a34d45c465b3817641f66576', 'An aria over a minute longer'),
('performance_listening_notes', 1012, 'note_en', 'ee9021719c595628f9644b120125cb1e6999967c3bf99c0fd7aa47d9daa118fc', 'At 8:07 it runs over a minute longer than the other two. It rises loud in several places, but reaches near-maximum only once.'),
('performance_listening_notes', 1012, 'facts_en', 'ee9021719c595628f9644b120125cb1e6999967c3bf99c0fd7aa47d9daa118fc', '["Richter · Munich Bach Orchestra"]'),
('performance_listening_notes', 1028, 'headline_en', 'f3f8be0e9a9f1d365bf65eb8bb1e34ad69a18fd864fa4b3fea39c1ac710f0d24', 'Maximum gathered in the middle'),
('performance_listening_notes', 1028, 'note_en', '645d82757ed86b4734db4e59f76bc8e6555c01d053f5e658dfa8a03ad22bf6c4', 'It gathers its loudest sound at the peak in the middle and carries it loudly for nearly 10 seconds. Unlike Perlman, it keeps the early part one step lower.'),
('performance_listening_notes', 1028, 'facts_en', '645d82757ed86b4734db4e59f76bc8e6555c01d053f5e658dfa8a03ad22bf6c4', '["Wolff · Oslo Phil"]'),
('performance_listening_notes', 1029, 'headline_en', '4dd771b37623d4cd8af64a50f3b2c8739629fc688265d271a2d91aabe2fdfbd3', 'The climb in two stages'),
('performance_listening_notes', 1029, 'note_en', 'ef720a5b090b7c1f41193b4c67610262709e5dac874fc5d6450d5aafd8d5982e', 'The other two rise in one go with 30 seconds left, whereas Bernstein climbs in two stages starting earlier. Just before the last climb that performance pulls back once.'),
('performance_listening_notes', 1029, 'facts_en', 'ef720a5b090b7c1f41193b4c67610262709e5dac874fc5d6450d5aafd8d5982e', '["New York Phil"]'),
('performance_listening_notes', 1030, 'headline_en', 'b5e86e9fd6492a58af49fd75503145bad260042324a94d9174281c58f4170cd0', 'Loud sound kept short'),
('performance_listening_notes', 1030, 'note_en', '25b656aeea3af19c6ac4f472be59aee85d56b7fd793c873e090205879fea824a', 'At each passage of resolve it rises loud briefly and then comes right back down. It spends a third as long at loud levels as Bartoli does.'),
('performance_listening_notes', 1030, 'facts_en', '25b656aeea3af19c6ac4f472be59aee85d56b7fd793c873e090205879fea824a', '["Marriner · Academy of St Martin in the Fields"]'),
('performance_listening_notes', 1031, 'headline_en', 'e27ff9d3a02dca36e0db3d1906441d904be899ecaa80fb426fa5827437c1d524', 'Near maximum only at the end'),
('performance_listening_notes', 1031, 'note_en', 'a8366f4e4415226557771020f22d1e92c785db3c67e64d5779320a2834196922', 'It unfolds 10 seconds slower than Lupu and 6 seconds slower than Pollini. It builds up gradually, reaching near-maximum only in the last few seconds.'),
('performance_listening_notes', 1031, 'facts_en', 'a8366f4e4415226557771020f22d1e92c785db3c67e64d5779320a2834196922', '["Solti · Chicago Symphony"]'),
('performance_listening_notes', 1032, 'headline_en', 'cf7e099654db63f66c324a0d657ed6672e7c716b4d8e7ad6aa09ed37b91f3e36', 'The last phrase loud again'),
('performance_listening_notes', 1032, 'note_en', '04fa6bf4864b1e95a6876523da0821c21f7d8bba045290c370f486df75079556', 'After the orchestral introduction it carries the piano theme at the most even level of the three. It rises loud again in the last phrase to close.'),
('performance_listening_notes', 1032, 'facts_en', '04fa6bf4864b1e95a6876523da0821c21f7d8bba045290c370f486df75079556', '["Mehta · Vienna Phil"]'),
('performance_listening_notes', 1033, 'headline_en', '67fdaa4d7496b69b4c7e4ecd7d5fb5c84fb53575925fb32a4bcdcb95799245c3', 'A loud midnight bell'),
('performance_listening_notes', 1033, 'note_en', '57e29b73e4e290273025ba2e6ee85f8db16562868de783f607942ea533efd657', 'The opening, where the midnight bell tolls, is the loudest of the three. It rises in one go with 30 seconds left, and the last 14 seconds run at near-maximum to the end.'),
('performance_listening_notes', 1033, 'facts_en', '57e29b73e4e290273025ba2e6ee85f8db16562868de783f607942ea533efd657', '["National Phil"]'),
('performance_listening_notes', 1034, 'headline_en', 'ab0ae1b6f8a06a03b7151e87a63cbf6a38bc38a3f8b041a3f1af216d4703f557', 'A step down at the end'),
('performance_listening_notes', 1034, 'note_en', '54d6a0f562658a5f57b81400662affe24358a2ab9176e0b35889cccc65ba2157', 'It enters quieter than the other two and builds gradually. Unlike the other two, after the climax it finishes a step lower.'),
('performance_listening_notes', 1034, 'facts_en', '54d6a0f562658a5f57b81400662affe24358a2ab9176e0b35889cccc65ba2157', '["Böhm · Vienna Phil"]'),
('performance_listening_notes', 1035, 'headline_en', '38401e68533e14f2728ec44ad2ab6d191862df3244beb1f7cde74a1db825422c', 'The slowest, 3:19'),
('performance_listening_notes', 1035, 'note_en', 'e2e93e7c83c7a8caa418034612767f0d670dd7340036bf4a744e56e204f60a9d', 'It plays 30 seconds slower than Hilary Hahn and 34 seconds slower than Perlman. The opening and the quiet passage after the climax are the quietest of the three.'),
('performance_listening_notes', 1035, 'facts_en', 'e2e93e7c83c7a8caa418034612767f0d670dd7340036bf4a744e56e204f60a9d', '["Karajan · Berlin Phil"]'),
('performance_listening_notes', 1036, 'headline_en', '546e45b34a737565b6b87ab7362c7117f8a9a7bb174c3a42ccd21391cee43e97', 'Deep drop before the end'),
('performance_listening_notes', 1036, 'note_en', '6305d82bffd9d02a186ff8887ee25587f871e987aa16b05fb736ebbe16aa0ef8', 'It is 5 seconds longer than Argerich. Like Lang Lang, it builds the last phrase again, but sinks deeper before it.'),
('performance_listening_notes', 1036, 'facts_en', '6305d82bffd9d02a186ff8887ee25587f871e987aa16b05fb736ebbe16aa0ef8', '["Noseda · London Symphony"]'),
('performance_listening_notes', 1037, 'headline_en', 'a75634f9455c08cdd16bb528f65046972a612d6bc512cf1ed5dc25b89013dc6f', 'Maximum placed early'),
('performance_listening_notes', 1037, 'note_en', '7ba88345540a26a81ebbd96f7826655c232efccb43e01bc38950a0bc39c0e720', 'The other two are loudest around the middle, but Perlman''s version already reaches maximum at the one-third mark. It doesn''t sink the quiet passages deep either, keeping an even course.'),
('performance_listening_notes', 1037, 'facts_en', '7ba88345540a26a81ebbd96f7826655c232efccb43e01bc38950a0bc39c0e720', '["Haitink · Concertgebouw"]'),
('performance_listening_notes', 1038, 'headline_en', '3a8b72a4ecbcaf9fedb1f658534c747107136eb5bd8612075cc7d63cf3ab2202', 'Quiet until one big leap'),
('performance_listening_notes', 1038, 'note_en', '25d8d970064260ad1d98cff1b6daa8e572f593d8b3d7ed6969905b1d886bf18f', 'It holds a quiet level until just before the climb, then rises in one go, more steeply than Stokowski. It steps back once and then carries on loudly to the end.'),
('performance_listening_notes', 1038, 'facts_en', '25d8d970064260ad1d98cff1b6daa8e572f593d8b3d7ed6969905b1d886bf18f', '["Philharmonia"]'),
('performance_listening_notes', 1039, 'headline_en', 'fcae9bea9f7ed0a3ffd41339d9f36421d00f3fa9e19d68043686c7efcd201392', 'The fastest, 48 seconds'),
('performance_listening_notes', 1039, 'note_en', 'af5649d413eb83dfb2cfe507828340357a54e89d0a71d30d8ebfa41ac24edbf9', 'It is 10 seconds faster than Ashkenazy. It climbs to near-maximum the earliest of the three, takes one breath, then rises to maximum again at the end.'),
('performance_listening_notes', 1039, 'facts_en', 'af5649d413eb83dfb2cfe507828340357a54e89d0a71d30d8ebfa41ac24edbf9', '["Mehta · Israel Phil"]'),
('performance_listening_notes', 1040, 'headline_en', '21d2d182373b8c3f0d83f7753b0c9ba15db7c2bfb10df24cc6b4bf50b8303333', 'A loud cry, then deep'),
('performance_listening_notes', 1040, 'note_en', '711d2eae4070ea8203553c615a0aca6c2016aa35906f32f9b7129769272c8b92', 'Right after its loudest cry, it drops deep. The gap between quiet and loud is the widest of the three.'),
('performance_listening_notes', 1040, 'facts_en', '711d2eae4070ea8203553c615a0aca6c2016aa35906f32f9b7129769272c8b92', '["Abbado · London Symphony"]'),
('performance_listening_notes', 1041, 'headline_en', 'c2d3d0f893370596b6259436ed6f31c1d7f46ce5d29290164a0ff0ad1993de7c', 'A song over 20 seconds longer'),
('performance_listening_notes', 1041, 'note_en', '8605d62eb942f508883ba87b24e019f07a2efba660f7a2b61e6d91beb2e98b81', 'At 2:35 it runs over 20 seconds longer than the other two. In the last 45 seconds it climbs close to near-maximum four times, more than the other two.'),
('performance_listening_notes', 1041, 'facts_en', '8605d62eb942f508883ba87b24e019f07a2efba660f7a2b61e6d91beb2e98b81', '["Patanè"]'),
('performance_listening_notes', 1042, 'headline_en', 'e15c572c1b3d44e4f8e07d563b24c31f5addc28e30c2143f5a455f4d254aa8f5', 'Loud in the middle, soft at the end'),
('performance_listening_notes', 1042, 'note_en', '8746a74065fbab3899705a867a2e274f9f43651ee18e04c2e5777084513e7bf6', 'It rises close to near-maximum in the middle of the piano theme. Unlike the other two, it doesn''t build the last phrase and closes it softly.'),
('performance_listening_notes', 1042, 'facts_en', '8746a74065fbab3899705a867a2e274f9f43651ee18e04c2e5777084513e7bf6', '["Abbado · London Symphony"]'),
('performance_listening_notes', 1055, 'headline_en', 'c57a18a62fabbb2889b3b5dc52468b96b755f4e9d1b98447b89b05b42cbeaaba', 'All three at maximum'),
('performance_listening_notes', 1055, 'note_en', '163692fb0758592254058a793759aaf1b8aa297223ede314d826f83e9c100fd3', 'The two orchestral tuttis and the final chord ring out at almost the same level. The quiet passages aren''t as deep as in the other two either, so the range of levels is small.'),
('performance_listening_notes', 1055, 'facts_en', '163692fb0758592254058a793759aaf1b8aa297223ede314d826f83e9c100fd3', '["Mehta · New York Phil"]'),
('performance_listening_notes', 1056, 'headline_en', 'bcdcb1b226ad0a86a4e01d8db11494310e8f7db3856347f479c6482defe48090', 'Maximum in the early phrase'),
('performance_listening_notes', 1056, 'note_en', '9a3ef25866a3472ec63166e7f37e0e8d4d86dacb34515853208b6f76bb21a710', 'It rises to its loudest less than a minute after the alto enters. The later phrase continues almost as loud, and unlike Bernstein it doesn''t hold back to the end.'),
('performance_listening_notes', 1056, 'facts_en', '9a3ef25866a3472ec63166e7f37e0e8d4d86dacb34515853208b6f76bb21a710', '["Vienna Phil"]'),
('performance_listening_notes', 1057, 'headline_en', 'a66343b795c9a1b8481005d7726014980eead7f41fc9a74310c1b046bf018e30', 'The fastest dance'),
('performance_listening_notes', 1057, 'note_en', '124e6d939383857713f309eb1cb240eef9a8b60759e3b9283e19b8ffc45d7d19', 'It is 17 seconds shorter than Konwitschny and 31 seconds shorter than Haitink. It holds back the first surge a step and rises to its loudest in the second surge.'),
('performance_listening_notes', 1057, 'facts_en', '124e6d939383857713f309eb1cb240eef9a8b60759e3b9283e19b8ffc45d7d19', '["Berlin Staatskapelle"]'),
('performance_listening_notes', 1058, 'headline_en', 'f87fc3fb7ce2582eca423aa12ad3e7d61efeebf6d1b76165411ca52aded89998', 'One in the middle, maximum at the end'),
('performance_listening_notes', 1058, 'note_en', 'b9d1463575380c8cf6dbc344be0968f4e2b3736fcdf1b4baf6d7a83f68fd9246', 'It rises loud once in the middle phrase, and saves the loudest sound for near the end. It rises loud later than Boulez and earlier than Bernstein.'),
('performance_listening_notes', 1058, 'facts_en', 'b9d1463575380c8cf6dbc344be0968f4e2b3736fcdf1b4baf6d7a83f68fd9246', '["Royal Concertgebouw"]'),
('performance_listening_notes', 1059, 'headline_en', 'ca814b20376e4a7b80b5aca4facbc2439beacd9f0004e24d425c2cc311aafddb', 'Maximum at the first tutti'),
('performance_listening_notes', 1059, 'note_en', '87091a15b518549a14a2196a58cd10b2bf5fb5e85c24012e983ab62ff39b79be', 'It rings out loudest at the first tutti, and the second tutti is one step lower. The final chord closes as loud as the first tutti.'),
('performance_listening_notes', 1059, 'facts_en', '87091a15b518549a14a2196a58cd10b2bf5fb5e85c24012e983ab62ff39b79be', '["Dutoit · Royal Phil"]'),
('performance_listening_notes', 1060, 'headline_en', '1838d97a3ceb6a001573241fc8a66730c4a3cc5f904be60e30da7f2daca4ded9', 'Both surges at maximum'),
('performance_listening_notes', 1060, 'note_en', '44460514fe3353113ed7deeed2b3eb611d6c0ad17b4511e523d99ad94e3c5255', 'It already rises loudest in the first surge, and the second is played at almost the same level. Unlike the other two, it doesn''t hold back the first surge.'),
('performance_listening_notes', 1060, 'facts_en', '44460514fe3353113ed7deeed2b3eb611d6c0ad17b4511e523d99ad94e3c5255', '["Berlin Staatskapelle"]'),
('performance_listening_notes', 1061, 'headline_en', '6e96c9b3fa89070e3281f324e27b02de769159db3cd46064722d5badd442ed22', 'An ending louder than the first chord'),
('performance_listening_notes', 1061, 'note_en', 'c9f2042895e390e82f29f0f52ee78ae79243f61d54a25cd14018565fb2813e1b', 'At 6:31 it is 1:30 shorter than Karajan. The Statue''s first chord also rings loud, but the loudest sound is saved for the end, when Giovanni is dragged down to hell.'),
('performance_listening_notes', 1061, 'facts_en', 'c9f2042895e390e82f29f0f52ee78ae79243f61d54a25cd14018565fb2813e1b', '["Academy of St Martin in the Fields"]'),
('performance_listening_notes', 1062, 'headline_en', '810b1153bb0943de4ad27564cc61d2683559fc97bec5bf9fda3bb7cbdef0539f', 'Deep between the surges'),
('performance_listening_notes', 1062, 'note_en', 'a4e4a9943c6d1ce5df0d1a593866084389181a5c96d3f2e1d5ed92d9bf5067cc', 'The quiet passage between the two surges is the deepest of the three. It holds back the first surge for a long time, and puts its loudest sound in the second.'),
('performance_listening_notes', 1062, 'facts_en', 'a4e4a9943c6d1ce5df0d1a593866084389181a5c96d3f2e1d5ed92d9bf5067cc', '["Bavarian Radio Symphony"]'),
('performance_listening_notes', 1063, 'headline_en', '1f0a1659a73270d63cf5d0833799cf5720c9cb0deb81930b50a7355ad1be8e14', 'Maximum at the Statue''s first chord'),
('performance_listening_notes', 1063, 'note_en', 'f3a1b4ac62b7f1812220f19bb8021f0b4c9505e1bf05c7a7fde85d79c1037eec', 'It rings the Statue''s entrance chord the loudest. After that it presses the dialogue passage the lowest of the three, then raises it again at the end.'),
('performance_listening_notes', 1063, 'facts_en', 'f3a1b4ac62b7f1812220f19bb8021f0b4c9505e1bf05c7a7fde85d79c1037eec', '["Chamber Orchestra of Europe"]'),
('performance_listening_notes', 1064, 'headline_en', 'd9b79ac12e6ca1779dba99dbb022810a77830e9e997e7c62bcf41c0c74955522', 'A final chord louder than the tuttis'),
('performance_listening_notes', 1064, 'note_en', '46499947b9a425d74a4c4f31cbbe5188c403b4955ee725eff1ad48e337d80960', 'Both tuttis are quieter than the final chord, so the loudest sound comes at the end. The quiet passages are also the deepest of the three.'),
('performance_listening_notes', 1064, 'facts_en', '46499947b9a425d74a4c4f31cbbe5188c403b4955ee725eff1ad48e337d80960', '["Wordsworth · Royal Phil"]'),
('performance_listening_notes', 1065, 'headline_en', 'ecb05ec4a20db18f15185eb43fd0f36d43e117ee361ef3562f26b0f241e37baa', 'Maximum only in the last 10 seconds'),
('performance_listening_notes', 1065, 'note_en', '85d1ab3ae23d5d6a4d18fecea6f20f0a12f6d1b09ec3b26d83bd235a31cec6b5', 'It doesn''t rise loud for the first time until 10 seconds before the end. For over two minutes before that it runs the quietest of the three.'),
('performance_listening_notes', 1065, 'facts_en', '85d1ab3ae23d5d6a4d18fecea6f20f0a12f6d1b09ec3b26d83bd235a31cec6b5', '["New York Phil"]'),
('performance_listening_notes', 1066, 'headline_en', '30e4286ece44078fde888b722d068aeb67eca16f925d591eb75fc25b4162ed82', 'Slow and loud, 8:01'),
('performance_listening_notes', 1066, 'note_en', '588ca5e762b12d1c189672041db41186d040fb400244c598c24189a8613d2744', 'It runs over 1:20 longer than the other two. Even in the dialogue in the middle it rises to near-maximum several times, and carries almost the whole last minute loudly.'),
('performance_listening_notes', 1066, 'facts_en', '588ca5e762b12d1c189672041db41186d040fb400244c598c24189a8613d2744', '["Berlin Phil"]'),
('performance_listening_notes', 1127, 'headline_en', '1edc3dc4d82cb8901baffce58ff92481c2c48b2fb30086677e9c6692fdf681ad', 'A very quiet first 7 seconds'),
('performance_listening_notes', 1127, 'note_en', '02c0b6aaa931d0bb11f65bdb5533860a705324d0254ffba40e3c5a4881d048e7', 'The first 7 seconds are very quiet, and then it starts to grow. It is 21 seconds shorter than Bernstein and 7 seconds shorter than Abbado.'),
('performance_listening_notes', 1127, 'facts_en', '02c0b6aaa931d0bb11f65bdb5533860a705324d0254ffba40e3c5a4881d048e7', '["Berlin Phil"]'),
('performance_listening_notes', 1128, 'headline_en', '29d9d8ead9ca7cbf6a77e9ac148b9e3b78a46432973a62aacde3e7ad60597e23', 'Maximum at the second peak'),
('performance_listening_notes', 1128, 'note_en', 'efc335ef8c95365725298ea740a4644cc7b2e42b8bf75c91da6f6536da2af284', 'It sets the first f the lowest of the three and grows loudly up to ff. The loudest sound comes at the second peak.'),
('performance_listening_notes', 1128, 'facts_en', 'efc335ef8c95365725298ea740a4644cc7b2e42b8bf75c91da6f6536da2af284', '["Berlin Phil"]'),
('performance_listening_notes', 1129, 'headline_en', '06bd8917eba9ee63f1fd90dcba7ea151ae8a93fe2b0ffab4713f2cdd35cd9b09', 'Holds loud to the end'),
('performance_listening_notes', 1129, 'note_en', 'acfb19ed3e74ebbf9e4c39fccff2e90999ae85b9372ace3d467892aa637bb60c', 'At the end, where the music turns to D minor and the orchestra comes in strongly, it holds loud the longest of the three. It keeps that level through the spot where Bernstein soon lets go.'),
('performance_listening_notes', 1129, 'facts_en', 'acfb19ed3e74ebbf9e4c39fccff2e90999ae85b9372ace3d467892aa637bb60c', '["Berlin Phil"]'),
('performance_listening_notes', 1130, 'headline_en', 'e1877519e6138387685b429b6abfe1cca48c73c080b163e0200ccf7bb6c1f6fb', 'A long-held maximum'),
('performance_listening_notes', 1130, 'note_en', '0d623584cce4a4e15f92e05b1c284da00e98fc22c9e3829717598f8ca38e4b8b', 'It carries the latter part of the prayer melody close to maximum longer than the other two. The loudness of the trumpet call falls between Bernstein''s and Levine''s.'),
('performance_listening_notes', 1130, 'facts_en', '0d623584cce4a4e15f92e05b1c284da00e98fc22c9e3829717598f8ca38e4b8b', '["LA Phil"]'),
('performance_listening_notes', 1131, 'headline_en', '65e8dd7c7f2b53b5895565c3e67a6b8b0b474a58f2b4426e8d41527456b06336', 'A loud trumpet call'),
('performance_listening_notes', 1131, 'note_en', 'a8c511c61a8cbce3e11b8a6d1e095b5551e9e9add5e086058513ed56aef280de', 'All three trumpet calls are close to the loudest sound of the prayer melody. In the last descent of the prayer melody it quiets earlier than the other two.'),
('performance_listening_notes', 1131, 'facts_en', 'a8c511c61a8cbce3e11b8a6d1e095b5551e9e9add5e086058513ed56aef280de', '["New York Phil"]'),
('performance_listening_notes', 1132, 'headline_en', '0e0c81d8e069fa78e1920d5c6a9b27cc3e5811caf661d296b1e4d87a5d2a7302', 'First peak at 50 seconds'),
('performance_listening_notes', 1132, 'note_en', '7504d32a480191b10cbe4c0ae6671892824e5bbde5c1b464bd6b84ea777fd566', 'It is 16 seconds shorter than Karajan and 21 seconds shorter than Chailly. It reaches the peak where the horn soars after 50 seconds, touches maximum briefly, then drops a step.'),
('performance_listening_notes', 1132, 'facts_en', '7504d32a480191b10cbe4c0ae6671892824e5bbde5c1b464bd6b84ea777fd566', '["Vienna Phil"]'),
('performance_listening_notes', 1133, 'headline_en', '6fb74b81613fda00239069b9a504c190dc8972941ad9078038652e69697b1e9d', 'The slowest, 2:22'),
('performance_listening_notes', 1133, 'note_en', '099a0104c33df006018ae8fe6322ee1affb1a736ff0dfa981611b722f7905c4b', 'It is 21 seconds longer than Karajan and 14 seconds longer than Abbado. Unlike the other two, it swells loudly once 14 seconds after the start.'),
('performance_listening_notes', 1133, 'facts_en', '099a0104c33df006018ae8fe6322ee1affb1a736ff0dfa981611b722f7905c4b', '["Royal Concertgebouw"]'),
('performance_listening_notes', 1134, 'headline_en', 'aad3a1c5d8ced5ef2fd2de4fa31a8ce291f67b454c80d35a07c4a5220b446684', 'A steadily rising opening'),
('performance_listening_notes', 1134, 'note_en', '28a309ba668470ee6300113f1cff7d3477371581085aac46578f5c9ba0f9f22b', 'The opening isn''t as quiet as in the other two, so even when the horn enters it doesn''t swell suddenly but rises steadily. Its length falls between Thielemann''s and Chailly''s.'),
('performance_listening_notes', 1134, 'facts_en', '28a309ba668470ee6300113f1cff7d3477371581085aac46578f5c9ba0f9f22b', '["Berlin Phil"]'),
('performance_listening_notes', 1135, 'headline_en', 'aa18b19db4b49390de30974e7c80bfd3ec9a3839e2d59554af0beaad7ab71edd', 'Maximum at the first ff'),
('performance_listening_notes', 1135, 'note_en', 'aef16844bf760cfa9ab425cb1fcf5cbf3a526b739310effd9abea26458b93194', 'It is near maximum from the start, and its loudest sound comes at the first ff. The second peak is a step lower but runs on later than in the other two.'),
('performance_listening_notes', 1135, 'facts_en', 'aef16844bf760cfa9ab425cb1fcf5cbf3a526b739310effd9abea26458b93194', '["Chicago Symphony"]'),
('performance_listening_notes', 1136, 'headline_en', '4100e0f77c45546d15c85f9f77c3f7bca7cbea1bd5ab859ccab7a308531a83cc', 'Both peaks at the same level'),
('performance_listening_notes', 1136, 'note_en', 'cf4cff85b1f284fa7892bf272f45f5addaaf650937a0a989f5ba8ebf3f620701', 'It plays the first ff peak and the second peak at almost the same level. The span of its swell from the first f to ff falls between Abbado''s and Solti''s.'),
('performance_listening_notes', 1136, 'facts_en', 'cf4cff85b1f284fa7892bf272f45f5addaaf650937a0a989f5ba8ebf3f620701', '["Gewandhaus"]'),
('performance_listening_notes', 1137, 'headline_en', '12a2ff1f9bd57ffb286907d75fde219a24d8d409c40623ff621b1f81688bad04', 'Maximum reached twice'),
('performance_listening_notes', 1137, 'note_en', '7929c6eb33f96afcd979ebfa8a1f068dbbdfcdda9a0b9e10a7e66f396c36b97c', 'It holds the peak where the horn soars near maximum the longest of the three, reaching maximum twice. When it builds up again at the end, it rises close to that peak as well.'),
('performance_listening_notes', 1137, 'facts_en', '7929c6eb33f96afcd979ebfa8a1f068dbbdfcdda9a0b9e10a7e66f396c36b97c', '["Royal Concertgebouw"]'),
('performance_listening_notes', 1138, 'headline_en', 'aea15b19f7de66e45a85151b5f63be9731d23ad9d4cfd0689fc381d7f669839b', 'The slowest, 2:56'),
('performance_listening_notes', 1138, 'note_en', '6278232ec0ba5816ea7d2075dcfbd927e75093f55f75778d23fe608887db1cba', 'It is 15 seconds longer than Mehta and 12 seconds longer than Bernstein. The trumpet call sits a step lower, and the loudest sound comes in the latter part of the prayer melody.'),
('performance_listening_notes', 1138, 'facts_en', '6278232ec0ba5816ea7d2075dcfbd927e75093f55f75778d23fe608887db1cba', '["Met Opera Orchestra"]'),
('performance_listening_notes', 1139, 'headline_en', 'f0863dfd32836565db813dc02d6206ee9e1f7c01452e47c760fb4cc3d50a97d4', 'The most even performance'),
('performance_listening_notes', 1139, 'note_en', '9b88c52028d6988a0b2f843ad61969f22e90c86a0e3c2999f4603eb7580c2358', 'The gap between quiet and loud is smaller than in the other two. It opens the first tutti a step lower and rises to near-maximum from the middle on.'),
('performance_listening_notes', 1139, 'facts_en', '9b88c52028d6988a0b2f843ad61969f22e90c86a0e3c2999f4603eb7580c2358', '["Krček · Capella Istropolitana"]'),
('performance_listening_notes', 1140, 'headline_en', 'db965ca913b27f758d9ef0e6b3c51e7c1f92339b77d191f35566a905f7564441', 'A hushed end to the introduction'),
('performance_listening_notes', 1140, 'note_en', '9b667c17a64b43d74872b02bfcbc968b39fd2f6eff2dc73c30407483cbe25048', 'After the introduction''s crescendo it stays very quiet for over 20 seconds. That quiet passage is the longest of the three, and the introduction''s length falls between Perlman''s and Mutter''s.'),
('performance_listening_notes', 1140, 'facts_en', '9b667c17a64b43d74872b02bfcbc968b39fd2f6eff2dc73c30407483cbe25048', '["Piano: Argerich"]'),
('performance_listening_notes', 1141, 'headline_en', '9e583068118723ed912285ff610d727fe426c66b9effbc1720d78c561b762a65', 'Loud from the first call'),
('performance_listening_notes', 1141, 'note_en', 'ac3dc936b7c8c85cf45665991bf4f5120dabe6875606cbada2d32a2029fdfaf4', 'The orchestra rings out loudly from the first call, so the climb to ff is the narrowest of the three. The piano theme also continues evenly without large swings.'),
('performance_listening_notes', 1141, 'facts_en', 'ac3dc936b7c8c85cf45665991bf4f5120dabe6875606cbada2d32a2029fdfaf4', '["Giulini · LA Phil"]'),
('performance_listening_notes', 1142, 'headline_en', 'fa74270d761e5af3bae6bdaceb8f5b1b2f76ed216de4864dba8a6457c3369db5', 'A brisk introduction'),
('performance_listening_notes', 1142, 'note_en', 'd947c1e624a4346138355495f5f410c9f4b26ed5c453a7f754fae079437a0f87', 'The introduction takes 1:28, 15 seconds shorter than Kremer''s and 27 seconds shorter than Perlman''s. The first chord is also quieter than in the other two.'),
('performance_listening_notes', 1142, 'facts_en', 'd947c1e624a4346138355495f5f410c9f4b26ed5c453a7f754fae079437a0f87', '["Piano: Orkis"]'),
('performance_listening_notes', 1143, 'headline_en', '25d14ac32cccdbda7001a74d946d59b6928447385e899f77b5158d17cac1f1b7', 'Near maximum many times'),
('performance_listening_notes', 1143, 'note_en', '7ba926c4672d96b5e365bed84b4114d3cc7895dbcba7b8deaa1a6ba0f2e7e113', 'At 7:56 it is 27 seconds shorter than Perahia. It reaches near-maximum at each loud passage, and its quiet passages aren''t deep, so the range of levels is small.'),
('performance_listening_notes', 1144, 'headline_en', '9ab7471cd4fa5e631a9d6983e2ae2d5dc5dd23126a32e7c003d4a924ff294b59', 'Near maximum at every tutti'),
('performance_listening_notes', 1144, 'note_en', '7bfa4c69c9f7a5ad8589e55d7fb9d2e1c02c1fc9c56abac87dd5f6e67bfaa2bd', 'At 2:50 it is 29 seconds shorter than Thunemann. From the first tutti to the last, it rings out the loud places at almost the same level.'),
('performance_listening_notes', 1144, 'facts_en', '7bfa4c69c9f7a5ad8589e55d7fb9d2e1c02c1fc9c56abac87dd5f6e67bfaa2bd', '["Schlaefli · Kurpfälzisches Kammerorchester"]'),
('performance_listening_notes', 1145, 'headline_en', '096b5ee62ebbd386e66b94a5648049633fe7488514625cd2276331dbd723e899', 'A slow pace of over nine minutes'),
('performance_listening_notes', 1145, 'note_en', '8a9bbeb8ba895d0108440f9d071837718551b70e81af25ad06a1bdd5b0a30954', 'At 9:04 it is 58 seconds longer than Kissin. It sets the first unison a step lower, and rings out the recapitulation''s unison and the final chord at near-maximum.'),
('performance_listening_notes', 1146, 'headline_en', '0058666bf2bcdb0430a83b25e5704364ca8e2906e8bd20e8c0ffb1a6a74024c9', 'A step back mid-theme'),
('performance_listening_notes', 1146, 'note_en', '85474739f8ec43abbd2cb895c11c6f3dbedcb8465750a23b86c61c02278bd4cd', 'It builds the orchestral crescendo to a range between the Zimerman version and the Rubinstein version. In the middle of the piano theme it pulls back deep once, then rises again.'),
('performance_listening_notes', 1146, 'facts_en', '85474739f8ec43abbd2cb895c11c6f3dbedcb8465750a23b86c61c02278bd4cd', '["Urbański · NDR Elbphilharmonie"]'),
('performance_listening_notes', 1147, 'headline_en', 'b66aedfcfc3f16e63a4e5f5eeea1b08471b37295f58d00e988e86b8f9b20b0ee', 'Maximum in the last few bars'),
('performance_listening_notes', 1147, 'note_en', '50445993fd1cb8c9600f743762771e5820d766a3aa67cc2f1abe19af493022bf', 'It doesn''t reach near-maximum for the first time until a few seconds before the end. The gap between quiet and loud is also narrower than in the other two.'),
('performance_listening_notes', 1148, 'headline_en', 'ec9682bc5be5cb3d0c98af884e4318880f61f5ef0a3627ebfa27aa0277933bd2', 'Maximum from the first unison'),
('performance_listening_notes', 1148, 'note_en', 'ee9332ca70dd8746e1ffc74e7dc3b0ff25b6b0a297eb97c7b9c1f0c68047a5a3', 'At 8:06 it is the shortest of the three. It rings out near-maximum from the first unison, and the quiet passages aren''t as deep as in the other two.'),
('performance_listening_notes', 1149, 'headline_en', '2d802e620ff9e873346bf9916063628c79485b2c1bf05120180c351baeb37a63', 'A final tutti over 30 seconds'),
('performance_listening_notes', 1149, 'note_en', '054e0629ded57224610278abf095fbbef75a6b4c23dcd3a2a41796f285702bdf', 'At 3:19 it is the longest of the three. It extends the final tutti beyond 30 seconds, and its quiet passages are deeper than in the other two.'),
('performance_listening_notes', 1149, 'facts_en', '054e0629ded57224610278abf095fbbef75a6b4c23dcd3a2a41796f285702bdf', '["I Musici"]'),
('performance_listening_notes', 1150, 'headline_en', '836941b9c46225435f33ed52e8d8040d352feabeca4339a969eba570f856dca3', 'A crescendo built from the floor'),
('performance_listening_notes', 1150, 'note_en', 'bd01203e566f1b67ac58824aefcec9f7c0f4daeb0ea2262c9bcd17e1bb9c375c', 'It starts the orchestral crescendo far lower than the other two. It brings out the piano theme softly and grows toward the end, and it is about 3 seconds shorter than the other two.'),
('performance_listening_notes', 1150, 'facts_en', 'bd01203e566f1b67ac58824aefcec9f7c0f4daeb0ea2262c9bcd17e1bb9c375c', '["Wallenstein · Symphony of the Air"]'),
('performance_listening_notes', 1151, 'headline_en', '1693c2362a9f6510e5aeb8c6b6fb49d6f2214e170fb6fbe0dd505332a0e3d1c2', 'Maximum held back until 30 seconds from the end'),
('performance_listening_notes', 1151, 'note_en', 'ccde8b4fcfb227253782dbe0f8d1f16c60c8c9bf56c98a106263404843d406d1', 'It never reaches near-maximum until about 30 seconds before the end. All the loud passages before that finish one step lower.'),
('performance_listening_notes', 1152, 'headline_en', 'c379d703b550761c644cc7f1bb70d383332903bc489b7d957ff3311cba5f02e6', 'A soaring introduction peak'),
('performance_listening_notes', 1152, 'note_en', '5ee85115392f46bcc2fc59d4c64e5c6dca778fc8c15079ae8e0eda3700573240', 'The introduction takes 1:55, 27 seconds longer than Mutter''s. Its biggest peak is much bigger than in the other two, close to the level of the Presto.'),
('performance_listening_notes', 1152, 'facts_en', '5ee85115392f46bcc2fc59d4c64e5c6dca778fc8c15079ae8e0eda3700573240', '["Piano: Ashkenazy"]'),
('performance_listening_notes', 1153, 'headline_en', '0da74b7ba10e3939027afabd2a9a77a8d9525b6be1af139b26b7940dc464603f', 'Deep quiet passages'),
('performance_listening_notes', 1153, 'note_en', '25d6f6d1ec2d0251d9421c10ab20c9bf5e3e9545c5a723b9666ea3339c4d0ce3', 'At 8:23 it is the longest of the three, and its quiet passages are deeper than in the other two. Both of the big passages late in the exposition ring out at near-maximum.'),
('performance_listening_notes', 1154, 'headline_en', '1c925d5faf191c3e8667bb7159278597fdc7e2dae4ae528ee2f1d7986dbafa86', 'Sunk deep, then loud'),
('performance_listening_notes', 1154, 'note_en', '11f02ee467064af93990f9e40f50db392880c07cad81c3b475594789863748fa', 'It rises to near-maximum at every loud passage and sinks the spaces between them the deepest of the three. Its swings are far bigger than Tjeknavorian''s.'),
('performance_listening_notes', 1154, 'facts_en', '11f02ee467064af93990f9e40f50db392880c07cad81c3b475594789863748fa', '["Performance used in \\"2001: A Space Odyssey\\"", "St. Petersburg Phil"]'),
('performance_listening_notes', 1155, 'headline_en', '5a1977030370647455e2d3749b421213fe0600bc6ad1379623755d7166780da3', 'Maximum only at the last peak'),
('performance_listening_notes', 1155, 'note_en', 'ca3b61263bab4f829b5854b1e18806209e92a0595781fd5c69762949cd7cb22d', 'It plays near-maximum only at the final climax. The quiet passage in the middle is also far less deep than Nott''s.'),
('performance_listening_notes', 1155, 'facts_en', 'ca3b61263bab4f829b5854b1e18806209e92a0595781fd5c69762949cd7cb22d', '["Stuttgart Radio Symphony"]'),
('performance_listening_notes', 1156, 'headline_en', '2c01f184af8d613bb28a63acd80fb47669df0f9ecf36635858cf47aad0fdcf34', 'Even level, 4:22'),
('performance_listening_notes', 1156, 'note_en', '32423e7c2b2158da0707ed1489b4e8733bee331482d010015c6dbadd0ef97ee7', 'At 4:22 it is over 40 seconds shorter than the other two. It is loud from the first sound, and the loud level stays even until 20 seconds before the end.'),
('performance_listening_notes', 1156, 'facts_en', '32423e7c2b2158da0707ed1489b4e8733bee331482d010015c6dbadd0ef97ee7', '["National Phil"]'),
('performance_listening_notes', 1157, 'headline_en', '83643f6794ec01de79fb2491eddddbfd5ee37cd3bc04e84beeb7ddacba3e0bfb', 'Near maximum in 45 seconds'),
('performance_listening_notes', 1157, 'note_en', '7c95db61b97d95718d68d1846e322d60814267f46b28bdfa7e62d243f69f2fc7', 'It rises to near-maximum within 45 seconds. Unlike Lesne, it reaches that level many times all the way to the end.'),
('performance_listening_notes', 1157, 'facts_en', '7c95db61b97d95718d68d1846e322d60814267f46b28bdfa7e62d243f69f2fc7', '["Cohen · Arcangelo"]'),
('performance_listening_notes', 1158, 'headline_en', '59de5a06f588c1daad7944a613494d98d4bc66f34c3d6253dba213cd72a2fb59', 'An aria 37 seconds shorter'),
('performance_listening_notes', 1158, 'note_en', '259e46d41fabe27bde6c3c37deca6102fe7ba1c6cb73ffcdd93cab1ed8192c09', 'At 4:13 it is about 37 seconds shorter than the other two. It reaches near-maximum only twice in the latter part, and carries the rest one step lower.'),
('performance_listening_notes', 1158, 'facts_en', '259e46d41fabe27bde6c3c37deca6102fe7ba1c6cb73ffcdd93cab1ed8192c09', '["McGegan · Philharmonia Baroque"]'),
('performance_listening_notes', 1159, 'headline_en', '575f021f39567f9ce84948df70ae38bb9993f6f27a4deea3833bb72bcf8b3c43', 'The quietest opening'),
('performance_listening_notes', 1159, 'note_en', 'cb947ad15de04f2716e0ce33310af154f96f7aaa0b774b966aa7db424fa252f5', 'The opening is the quietest of the three, and so is the gap between quiet and loud. Near-maximum appears only twice.'),
('performance_listening_notes', 1159, 'facts_en', 'cb947ad15de04f2716e0ce33310af154f96f7aaa0b774b966aa7db424fa252f5', '["Il Seminario Musicale"]'),
('performance_listening_notes', 1160, 'headline_en', 'cafee90ec5e8fdc85aff27ff550edfb9cebace3891f965a7f49521dc41698e8b', 'The fastest, 47 seconds'),
('performance_listening_notes', 1160, 'note_en', '4f7bec71ff5c05579b271ca85548a7b401e1371ad56617822b69ea78dbde8838', 'At 47 seconds it is 4 to 5 seconds shorter than the other two. It brings out the cello theme very quietly, but doesn''t lower the second quiet passage as much as Karajan does.'),
('performance_listening_notes', 1160, 'facts_en', '4f7bec71ff5c05579b271ca85548a7b401e1371ad56617822b69ea78dbde8838', '["Chamber Orchestra of Europe"]'),
('performance_listening_notes', 1161, 'headline_en', '05021ce1a92665a4aab6a4c41d7c48c8360ad2cf93062a05c355346003e539de', 'The deepest middle'),
('performance_listening_notes', 1161, 'note_en', 'f18aefb2b78e39001ee68d848709208ed548b4dbe551318cf9acfd61f78fce84', 'It sinks the quiet passage in the middle the deepest of the three. After that it rises to near-maximum twice.'),
('performance_listening_notes', 1161, 'facts_en', 'f18aefb2b78e39001ee68d848709208ed548b4dbe551318cf9acfd61f78fce84', '["Berlin Phil"]'),
('performance_listening_notes', 1162, 'headline_en', 'b1db967daba7f0d30acecbbf66abc4bc6263df36844b59cac6f076710bcd4aba', 'Deeply quiet both times'),
('performance_listening_notes', 1162, 'note_en', '1c0173ff08eddbf10a85579697a688de04324fc0e7bb458ed6d502a5ef3b2fdd', 'It lowers the cello theme after the two chords, and the second quiet passage after that, equally deep. Harnoncourt doesn''t lower the second as much.'),
('performance_listening_notes', 1162, 'facts_en', '1c0173ff08eddbf10a85579697a688de04324fc0e7bb458ed6d502a5ef3b2fdd', '["Berlin Phil"]'),
('performance_listening_notes', 1163, 'headline_en', 'd0b72a1176b5e6f22055e6051c32cb0ed67fb5e3e573df84c0b0ecd24b2491f9', 'A less quiet cello theme'),
('performance_listening_notes', 1163, 'note_en', '2d6c93c54cf2092e6188227e9ab732d2f2d7baee846720e070f0af9843ea2614', 'The cello theme after the two chords is the least quiet of the three. At 52 seconds it is 5 seconds longer than Harnoncourt.'),
('performance_listening_notes', 1163, 'facts_en', '2d6c93c54cf2092e6188227e9ab732d2f2d7baee846720e070f0af9843ea2614', '["New York Phil"]'),
('performance_listening_notes', 1164, 'headline_en', '944afd6cfac85ea2730fb1f10dd4723b8cf78e1d8eb7758d914d25e416dc398c', 'Up loud, down deep'),
('performance_listening_notes', 1164, 'note_en', '6ab1a9dfae93d7671908351268bb747a8322d9717c9d90275d98916b219d0782', 'It first reaches near-maximum a minute later than Mead. In the later part it repeatedly rises loud and sinks deep.'),
('performance_listening_notes', 1164, 'facts_en', '6ab1a9dfae93d7671908351268bb747a8322d9717c9d90275d98916b219d0782', '["Dantone · Accademia Bizantina"]'),
('performance_listening_notes', 1165, 'headline_en', '7bb977e91526bdd9636d1fbfc4f710d7a4e463612528d71257b416b856835f2f', 'Maximum again a minute from the end'),
('performance_listening_notes', 1165, 'note_en', '8d338dd0a6278dee73bf0a88775f0e09663940e0151016d54ecb8f900c2d82b6', 'After rising to its loudest within the first minute, it continues the middle one step lower, unlike the other two. A minute before the end it rises to near-maximum again.'),
('performance_listening_notes', 1165, 'facts_en', '8d338dd0a6278dee73bf0a88775f0e09663940e0151016d54ecb8f900c2d82b6', '["London Symphony"]'),
('performance_listening_notes', 1166, 'headline_en', 'b793f792977705b992305fa157ffd3a70aaffb594ca3c432ca22ed92575708a3', 'Near maximum from the first peak'),
('performance_listening_notes', 1166, 'note_en', '43153eb30f76087c2426ed6c151d2b74ea07e0b6d3501f052f999a0ee461a590', 'It already rises to near-maximum at the first big peak. The last climax arrives over 20 seconds later than Gielen''s.'),
('performance_listening_notes', 1166, 'facts_en', '43153eb30f76087c2426ed6c151d2b74ea07e0b6d3501f052f999a0ee461a590', '["WDR Symphony"]'),
('performance_listening_notes', 1167, 'headline_en', '5f630eceb9bb3c83eaf68f048267d3d58e8c8c1caf12a93835a6c8bc31f2fcf4', 'Maximum only once'),
('performance_listening_notes', 1167, 'note_en', '9f6aa455cf6abf98091506cbf861e1895f14f9d536eb7da36601760e5d27afac', 'Its quiet passages are the deepest and longest of the three. It reaches near-maximum only once, 1:20 before the end.'),
('performance_listening_notes', 1167, 'facts_en', '9f6aa455cf6abf98091506cbf861e1895f14f9d536eb7da36601760e5d27afac', '["Performance used in \\"Parasite\\"", "Curtis · Il Complesso Barocco"]'),
('performance_listening_notes', 1168, 'headline_en', '4bbf2eaa7a1e1c14d794341e483695774e9bc43aab89a66f9e3486b90686466a', 'Near maximum four times late on'),
('performance_listening_notes', 1168, 'note_en', '5b4bebb4d0c451640b8bc861d589e42c913956c09c8385e8f520fcdf48f44687', 'In the second half it reaches near-maximum four times. Though its length is almost the same as Kermes''s, it plays loud far more often.'),
('performance_listening_notes', 1168, 'facts_en', '5b4bebb4d0c451640b8bc861d589e42c913956c09c8385e8f520fcdf48f44687', '["Bicket · The English Concert"]'),
('performance_listening_notes', 1169, 'headline_en', '8f119290ffc7310d6b0750fa057a7ac7f4ced445a34e8bfda194c5c1c1133f70', 'A climax in the first part'),
('performance_listening_notes', 1169, 'note_en', '0ccf1019a8aac100141a2ef5ed084eb9dd82684742ec902648d89c3f52ba4afb', 'At 9:42 it is longer than the other two. Already near the end of the first part it sings as loud as in the middle section, and it empties out the later quiet passage deeply.'),
('performance_listening_notes', 1169, 'facts_en', '0ccf1019a8aac100141a2ef5ed084eb9dd82684742ec902648d89c3f52ba4afb', '["Cappella Amsterdam"]'),
('performance_listening_notes', 1170, 'headline_en', 'bcf1a3efcc688d92e2f36b4250f8cee12004dcc85e769aa304e3006c503a70aa', 'The smallest range of levels'),
('performance_listening_notes', 1170, 'note_en', '155ef53379ea0b3531416d19ffe8474d2ed151d76e48182da82ea875850896bd', 'The gap between quiet and loud is the smallest of the three. It reaches near-maximum from the first part, and its later quiet passage isn''t as deep as in the other two.'),
('performance_listening_notes', 1171, 'headline_en', '906f6704432171d7881a803761be17907d9ffac198c1f57b5bff40bc84e389af', 'A less deep middle'),
('performance_listening_notes', 1171, 'note_en', 'd518245ac6e9d28750f8a587124348249668d3c83cccf861724320c3d8229dc2', 'The quiet passage in the middle isn''t as deep as in the other two. It reaches near-maximum in the final variations and pushes loudly to the end.'),
('performance_listening_notes', 1171, 'facts_en', 'd518245ac6e9d28750f8a587124348249668d3c83cccf861724320c3d8229dc2', '["Cello: Soltani"]'),
('performance_listening_notes', 1172, 'headline_en', '1cae3b537189826e388c772d35c5e866a928221f6c9a937359f3c4989b55b3be', 'Holds maximum right away'),
('performance_listening_notes', 1172, 'note_en', 'b260af5abcaef6c80087a8b052058cb5e84eca55173ba8115824d4183014f41e', 'As soon as the racing passage starts, it reaches near-maximum and pushes at that level until it ends. Unlike Dutoit, it doesn''t build up within it.'),
('performance_listening_notes', 1172, 'facts_en', 'b260af5abcaef6c80087a8b052058cb5e84eca55173ba8115824d4183014f41e', '["New York Phil"]'),
('performance_listening_notes', 1173, 'headline_en', '350791be05ffee51c51d01adf915a07689eeff54bcc20210004901983de66691', 'The first part a step below'),
('performance_listening_notes', 1173, 'note_en', '6ee7cc563630cabc3caf3d93746b1ba9a350a6a06972205e38ae987789f91c46', 'It places the first part a step below the other two, and reaches near-maximum only in the big middle passage. It empties out the later quiet passage as deep as Reuss does.'),
('performance_listening_notes', 1173, 'facts_en', '6ee7cc563630cabc3caf3d93746b1ba9a350a6a06972205e38ae987789f91c46', '["SWR Vokalensemble"]'),
('performance_listening_notes', 1174, 'headline_en', '612b4643f2ede3c8455cef888f3a95dbb433d5ad7a1b7b4c894685237b5e5f69', 'Two deep drops late on'),
('performance_listening_notes', 1174, 'note_en', '341db6b5616f9f139e3575852952a8875425f2cc6ac071dd45ee74257da9fc51', 'Late in the piece it sinks deeper than the other two, twice. Then near the end it rises to its loudest to close.'),
('performance_listening_notes', 1174, 'facts_en', '341db6b5616f9f139e3575852952a8875425f2cc6ac071dd45ee74257da9fc51', '["I Musici"]'),
('performance_listening_notes', 1175, 'headline_en', 'ac567ac9417455c4f85270ebc4c704935a3757826d683563306a8933af77446b', 'Near maximum from the first theme'),
('performance_listening_notes', 1175, 'note_en', 'a0b12da1fc1c1a576254e487535f414e51d6f0bfdc0bb7107f02b20bb2063811', 'The near-maximum level that the other two reach only in the final variations, it reaches already in the first theme. Just before the final variations it is quiet for over 25 seconds.'),
('performance_listening_notes', 1175, 'facts_en', 'a0b12da1fc1c1a576254e487535f414e51d6f0bfdc0bb7107f02b20bb2063811', '["Cello: Taeguk Mun"]'),
('performance_listening_notes', 1176, 'headline_en', 'ae06432e81c3bbe2f2a7cab582ae79c5d49bae5d31098e19882beec71f17f158', 'A deeply sunk middle'),
('performance_listening_notes', 1176, 'note_en', '1aa4ab69d63cd00108798e55c315d8b9fc052341b9be82e39b1d92d29acfbcba', 'At 6:08 it is the shortest of the three. It sinks the quiet variations in the middle far deeper than the other two, then rises in one go in the final variations.'),
('performance_listening_notes', 1176, 'facts_en', '1aa4ab69d63cd00108798e55c315d8b9fc052341b9be82e39b1d92d29acfbcba', '["Violin: Renaud Capuçon"]'),
('performance_listening_notes', 1177, 'headline_en', '4e4ce1ba78c6b12999ab41a89f82292786f682d7dd32b64178ed63d9781e0298', 'The longest quiet passage'),
('performance_listening_notes', 1177, 'note_en', '94dc55426a246f9d135471424964f90e32a9e44fe88b5b20065131d3bb7cdf47', 'At 4:13 it is over 20 seconds longer than Fleming. After the big passage early on, it draws out the quiet passage longer and deeper than the other two.'),
('performance_listening_notes', 1177, 'facts_en', '94dc55426a246f9d135471424964f90e32a9e44fe88b5b20065131d3bb7cdf47', '["London Musici"]'),
('performance_listening_notes', 1178, 'headline_en', '1bfc63dd1f529734c8469f1ab393273d8a757dff68724571455d8c0f9a79e298', 'Short, near maximum early'),
('performance_listening_notes', 1178, 'note_en', '4b728228f3b949e180fd9f4207d0c036a90de4f8c6edeff95ff9ab513ec3c8b2', 'At 3:50 it is the shortest of the three. It reaches near-maximum within a minute and doesn''t press the quiet passages as deep as the other two.'),
('performance_listening_notes', 1178, 'facts_en', '4b728228f3b949e180fd9f4207d0c036a90de4f8c6edeff95ff9ab513ec3c8b2', '["Summers · Met Opera Orchestra"]'),
('performance_listening_notes', 1179, 'headline_en', '220d16a3d677e60970c46126fef9a194a6730c57046aaa78a17b424ebf8448c9', 'Built up in the last seconds'),
('performance_listening_notes', 1179, 'note_en', '0aad3cd2a619a09b2133e35b2bfde9cf878c7c1dee0974b97eda88e521d25749', 'At 3:00 it is the longest of the three. It carries the racing passage one step lower at an even level for over 10 seconds, then rises to its loudest only in the last few seconds.'),
('performance_listening_notes', 1179, 'facts_en', '0aad3cd2a619a09b2133e35b2bfde9cf878c7c1dee0974b97eda88e521d25749', '["Montreal Symphony"]'),
('performance_listening_notes', 1180, 'headline_en', 'b8bd071575ec0cc2bb58cd32ee23ee64b3535a89b513874be7d7fa6ce39844d2', 'The quietest introduction'),
('performance_listening_notes', 1180, 'note_en', 'c4688944bf9ea98f742ff474497efbfb884ea12555d867fe9b1378523c75662d', 'The introduction is quieter than in the other two. In the racing passage it rises close to near-maximum within a few seconds and continues evenly.'),
('performance_listening_notes', 1180, 'facts_en', 'c4688944bf9ea98f742ff474497efbfb884ea12555d867fe9b1378523c75662d', '["Berlin Phil"]'),
('performance_listening_notes', 1181, 'headline_en', '5bb05bbefceee3c22cc37c5cda6363f044b64e8bef7d026d3462ded01311d511', 'A deep return to quiet'),
('performance_listening_notes', 1181, 'note_en', '323def2c4f4158fce4f294eac136d8d77f0b895f5e648ae419eeffe387ef6ac1', 'Each time it restarts quietly after a crescendo, it drops the deepest of the three. It holds the final diminished-seventh chord for over 6 seconds before slowly letting go.'),
('performance_listening_notes', 1182, 'headline_en', 'a2b746ffa9702257bd698158eab99bcfc6eac50588252e231c04384dea1c42ba', 'Maximum already at the first peak'),
('performance_listening_notes', 1182, 'note_en', '888e43aa30442d9ff630559f4ac437363d548c9be06051034d1f9961f012e01a', 'It is about 8 seconds shorter than the other two. It already plays its loudest at the first peak, and releases the final diminished-seventh chord after about 4 seconds.'),
('performance_listening_notes', 1183, 'headline_en', 'a45e1996d392a14c3015adf96a6683a84822640973b41a40aaa90c8b04ed6068', 'Straight on up after the second'),
('performance_listening_notes', 1183, 'note_en', 'cf029fd6622a835a1710b27ac8b478a68949fa18ef0c65b82710955690f12281', 'It places the second motif a step lower than Böhm does, and then, without sinking as much as the other two, keeps building up to the final chord.'),
('performance_listening_notes', 1183, 'facts_en', 'cf029fd6622a835a1710b27ac8b478a68949fa18ef0c65b82710955690f12281', '["Berlin Phil"]'),
('performance_listening_notes', 1184, 'headline_en', '9d70e2151f3405ad69b6147e11c9ed4ce995a48b7c9fcd7058ed59986079e76c', 'Rises early, holds long'),
('performance_listening_notes', 1184, 'note_en', '8af2a9982ef5568776d5bc3fbf13934664a8900cd52d4d124a3ec226d49635fe', 'At 1:38 it is the shortest of the three. It already rises close to near-maximum at the second motif and holds that level for the 20 seconds before the final chord.'),
('performance_listening_notes', 1184, 'facts_en', '8af2a9982ef5568776d5bc3fbf13934664a8900cd52d4d124a3ec226d49635fe', '["Berlin Phil"]'),
('performance_listening_notes', 1185, 'headline_en', 'bdf7511f7e3cc75d3342552ed50256c8e867ce058de16712221a22292efdf2c5', 'Maximum only at the final chord'),
('performance_listening_notes', 1185, 'note_en', 'd3a1ee55e40d886869109198332458f5913b364b8543186cd0fc055cb6c1be14', 'At 1:57 it is 19 seconds longer than Böhm. It leaves the quiet passages between the motifs longer than the other two do, and reaches maximum only near the final chord.'),
('performance_listening_notes', 1185, 'facts_en', 'd3a1ee55e40d886869109198332458f5913b364b8543186cd0fc055cb6c1be14', '["Royal Concertgebouw"]'),
('performance_listening_notes', 1186, 'headline_en', 'ffa7887a872c71ea7ebd3ac0b9527ea27b08a8b355f45e9c5c104782bc95c29a', 'Maximum saved for the final chord'),
('performance_listening_notes', 1186, 'note_en', '7856443a003c1e2cb8bee01d3d80db8db8b5cf05490bb7bd0520f2c989871e16', 'It sets the two earlier peaks a step lower, and plays loudest only at the final diminished-seventh chord. It holds that chord as long as Horowitz does.'),
('sector_featured_pairs', 25, 'title_en', 'eb25c0cb82a313663f300609ef85e6d1e823956912ea07c55a107dd8c283fe3b', 'Cho Peaks Early, Argerich Holds Back'),
('sector_featured_pairs', 25, 'note_en', '68771e0a447222fdb9fa6991ba715622a61e197790eafe740a59bc86dd712828', 'Cho already gets close to the maximum in the opening phrase, then eases back to catch a breath and climbs again. Argerich keeps the opening soft and builds in one go in the middle.'),
('sector_featured_pairs', 26, 'title_en', '35b40c5e9945c4992273832b23e851ae06ef76aad9ad5b074bea31bddacaaf3f', 'Gould Skips Repeats, Levit Keeps Them All'),
('sector_featured_pairs', 26, 'note_en', 'b33833a4dfdb54992d4f1f99b5b0c0f58a872d81c07686ba7e1025d549f02a9c', 'The same variation takes Gould 1:10 and Levit nearly 2 minutes. Gould skips both repeats; Levit observes every one and ends at the loudest point.'),
('sector_featured_pairs', 27, 'title_en', 'f5c2d77cb511588554aba8d90d9efd16ac562edb775c2d46609fcda0730161bb', 'Soft Andsnes, Immediately Loud Hough'),
('sector_featured_pairs', 27, 'note_en', '9d037f9b8540d9bc3998d95e70930add0ddc03f90def15df2e7b50588f6aa87c', 'Andsnes begins very softly, while Hough comes in loud from the first note. Hough''s version is 11 seconds shorter.'),
('sector_featured_pairs', 28, 'title_en', '9703d2f8c3ffb992066d238eacc0fa68d9622131ba496db6bbd5168cf879a789', 'Straight-Building Perahia, Early-Peaking Ashkenazy'),
('sector_featured_pairs', 28, 'note_en', 'fcccd784e26b4780259712ced7fa668e8335ecf8422ab462a3a7f42e1a27c44f', 'Perahia builds in one continuous rise with no pulling back and reaches the maximum late. Ashkenazy eases back once but still gets near the maximum earlier and sustains it for a long time.'),
('sector_featured_pairs', 29, 'title_en', '4cc036964e3e71f5bb6e387ca872a44912e36e5535a9239f4a8aed0ac8483359', 'Fast Argerich, Soft-Landing Andsnes'),
('sector_featured_pairs', 29, 'note_en', '75ca8170a8ab427331e7af7cd489f36e8d1b0404559f847fe70e8cbea444155c', 'Argerich is 8 seconds shorter. Argerich runs loudly to the very end, while Andsnes sets the ending down at the softest level.'),
('sector_featured_pairs', 36, 'title_en', '634255c0a63165f4d968191962e428e17cacd4caf07bffa159475a1133d686e3', 'Loud at Once, Swelling and Releasing'),
('sector_featured_pairs', 36, 'note_en', '86469b81a28f6189ce535979f07084149e88bf4a23533301f98c1b7c42fd5a20', 'Shishkin climbs to nearly the maximum in 10 seconds and holds it to the end. Lang Lang repeats a swell-and-release in every phrase.'),
('sector_featured_pairs', 37, 'title_en', '61c84a68732a34bb9670e7f828cebd0680d4f99adf4e30045d4158e23e3536d2', 'Kissin Pours It Out, Lang Lang Builds Up'),
('sector_featured_pairs', 37, 'note_en', '11931cbe00ac4c42a9af5789eb8b0cc964a7b80c451aacf0f9dc2399f80e14ec', 'They shape the same 20-odd seconds in opposite ways. Kissin reaches maximum loudness as soon as the music starts and holds it to the end; Lang Lang saves strength and bursts out 5 seconds before the end.'),
('sector_featured_pairs', 39, 'title_en', '0eaa58481d9ffe0af20c83974a2e5a447caebd8e5bb8287124ec949a31698d9c', 'A Lowered Back Half, One More Push at the End'),
('sector_featured_pairs', 39, 'note_en', 'b7045f3cc29d9c2b98080153416b62497a07562514e4afa5bec4e558daeb42cb', 'Argerich sets the level a step lower after the first 10 seconds. Yeol Eum Son stays even, then rises to nearly the maximum again close to the end.'),
('sector_featured_pairs', 40, 'title_en', 'c68134259723941839927aa98a74dbf29bfc21cdfb8106f83e82dddbb329d1be', 'Same First Chord, Different Middle'),
('sector_featured_pairs', 40, 'note_en', '412af0f04042732e230ceafedc93e8ebc21ba8663ee06f821a8b8ddf89627624', 'Both strike the first chord at their loudest. Kleiber takes one big breath in the middle, while Thielemann eases back only a little and pushes on to the end.'),
('sector_featured_pairs', 41, 'title_en', 'd0fdf76ff8ae4e4d4116e21b0f4e0628d2f11f3990c4201d74742632e11d0ca5', 'Chung Sets Down Quickly, Kleiber Sinks Deep'),
('sector_featured_pairs', 41, 'note_en', '86bfc9d5fa8f764558378a72796918cb2dd57d181342bc62c3802bf0599bea77', 'Myung-Whun Chung drops to a soft level right after the climax. Kleiber sinks deepest in the second quiet passage, then bursts out of it.'),
('sector_featured_pairs', 47, 'title_en', '51ef4f043a1bf2eb646a8ef13c2880bcdec012e45519333011f192b595244f29', 'Lang Lang Early, Kissin Late'),
('sector_featured_pairs', 47, 'note_en', 'e68c0e4960d9d4d02f03ebcb5ead48a35d8909115bb8387956f2707044fc9c6c', 'Lang Lang hits the climax in the opening section and eases off from the middle. Kissin reaches nearly the maximum in 20 seconds and keeps an even level, playing loudest only after the main figure returns.'),
('sector_featured_pairs', 49, 'title_en', 'fe313c04441e73927d9df3051496bcc5018bb4b748a2039e3ade553b3ab7b09d', 'A Very Soft First Song, an Even First Song'),
('sector_featured_pairs', 49, 'note_en', '5dc7865b97aae9e80309621a33b723fb52e8839b526b7674f77fda811b847d6d', 'Yunchan Lim keeps the first song very soft and sinks once more just before the middle. Shishkin doesn''t drop the same spot much and carries on evenly.'),
('sector_featured_pairs', 51, 'title_en', '986c45dd5150a1da57c69d1b5327ab920df97798027ce7c12f9cbdd7c32b1c91', 'A Growing Ending, a Shrinking Ending'),
('sector_featured_pairs', 51, 'note_en', '91b693c17284780a557fa134b83beeb3913978b9f419451ecf36101e9af9ff57', 'Scheps builds toward the back and sings loudest just before the end. Buniatishvili reaches the climax in the early part, then repeatedly scales back and ends softly.'),
('sector_featured_pairs', 55, 'title_en', '390123aa552a1cb4947bf1dc23be45dd9208867309eb4f71cc71429de4879ca5', 'Loud Up Front, Loud at the Back'),
('sector_featured_pairs', 55, 'note_en', '55667fd871fea43cc8deafca1c49f293537bdf504f552d2cf06ccb84b56b2554', 'Horowitz plays loudest right from the start and eases off toward the end. Fray holds back until past the middle, then plays loudest.'),
('sector_featured_pairs', 56, 'title_en', '4dd7710bc0550b1c0b28b29841efb3c2437a21687d3fd1e8d0e01f2caa4f52bf', 'Lang Lang Erupts Early, Ott Stays Even'),
('sector_featured_pairs', 56, 'note_en', 'a89785a16ee1aaed865a1638951b7009862ffb6dc703afafffe51da7cf50bd57', 'Lang Lang plays loudest in the first half, then drops deep within 10 seconds. Ott never drops sharply and becomes loudest only in the latter part.'),
('sector_featured_pairs', 57, 'title_en', '7e736634b922581da4f4b4e0bbd2050a9d70eff2ef8ea782c23e85075b330d6a', 'Cho Ends Softly, Thibaudet Erupts at the End'),
('sector_featured_pairs', 57, 'note_en', '82234b67867c73f239365faff7e3010210f7cb1520dabaf51e44a0af421deae8', 'Cho passes the climax at the three-quarter mark and closes softly. Thibaudet builds the final return and rings out loudest at the very end.'),
('sector_featured_pairs', 58, 'title_en', 'fed4a3e68523ad89b922023579bfd5b863b8b3255773a7768bdd7d54b3e0df22', 'After the Peak: Little Drop or Deep Drop'),
('sector_featured_pairs', 58, 'note_en', '65f4fc2a6be535c97fe4aa1088fbb65dd16abd6105addce22fabd2d0140ad578', 'Both rise high in the middle but differ afterward. Perlman keeps the sound large, while Kyung Wha Chung pulls it down to the quietest level in 20 seconds.'),
('sector_featured_pairs', 59, 'title_en', 'e286e2cd0fdc2daf8ae722444846231381ed65d89a20b798392281919eb990c7', 'Loud in the Middle, Held Back to the End'),
('sector_featured_pairs', 59, 'note_en', '00628e5a9bf08663f1ffe26490370fc065f2d079423e096ccaf6fde7d7a07d0d', 'Yundi Li plays loudest in the middle and drops straight to the quietest level. Bruce Liu plays loudly for the first time only when a minute remains.'),
('sector_featured_pairs', 60, 'title_en', '1a020c99188e55fb04d1dfcc1636c7a41cf6f4115e2df407c131180b39af41ac', 'Loud at Once, Held Back to the End'),
('sector_featured_pairs', 60, 'note_en', 'ae37c87eedb87ac8a95bb9d25643c2737cac050c86392e2580b1da6d4ac5b73b', 'Ozawa opens to nearly the maximum from the first tutti. Kleiber puts the first tutti a step lower and keeps things soft up to the climax near the end.'),
('sector_featured_pairs', 61, 'title_en', 'ae7acaf2dabf4ec6b4908c6cd47538c6513334879deda2732a0d47a82bf358ff', 'Loud from the Start, Loud Only at the End'),
('sector_featured_pairs', 61, 'note_en', '499cfe84073b382452b385c34d8418c9353f8bb6e150c340d8fa9307c3c106f8', 'Jansons reaches nearly the maximum in 18 seconds and holds a big sound to the end. Karajan sinks the middle deep and reaches the maximum only in the last few seconds.'),
('sector_featured_pairs', 62, 'title_en', '6a85fec56c85f314179ab7c63d4b93466bda5ca2bd6fb9ef194fd39542021a4e', 'Even Bavouzet, Deep-Sinking Cho'),
('sector_featured_pairs', 62, 'note_en', '3f5f2646dc794512a072178a4c528c7c9e7e09a0bb2e0f448df82fbf5349bff6', 'Bavouzet doesn''t sink far even in the quiet places and reaches the maximum only at the climax. Cho reaches the maximum early, then drops straight to a very low level.'),
('sector_featured_pairs', 63, 'title_en', '4d10eedec80ef2d90686145858dcfb1a30fa245e1c3bf87b2061ddaa659240d0', 'Fast Levit, Soft Pollini'),
('sector_featured_pairs', 63, 'note_en', '4ed08be8205464c2211d0fbc0efe15b716abd195216e9731d541911e089c1d1a', 'Levit is over a minute shorter and keeps the level even. Pollini starts at the softest level and opens a wide gap between quiet and loud.'),
('sector_featured_pairs', 64, 'title_en', 'b2ddb008a8392334243af773ecdb89ce0063bf4874e9c459bcc80f3d579fe83e', 'Ashkenazy Sets Down, Yundi Li Sustains'),
('sector_featured_pairs', 64, 'note_en', '785a124a2d100a54df575a99e124d72aacb037563b8946ba3aefa3c424df7985', 'Both rise to their loudest a little past the middle. Afterward Ashkenazy sets the level down for a long stretch, while Yundi Li holds it up until just before the end.'),
('sector_featured_pairs', 66, 'title_en', '1a6f25e7a6969548cb3890320df15625dc02104c88ae8dec08cf1243a472da64', 'Short Pressler, Soft Pires'),
('sector_featured_pairs', 66, 'note_en', '15dbdae43c8d7313d434f7e3ad3f9df4c108803813ee64cafc63da1acf52ab12', 'Pressler is 41 seconds shorter. Pires plays the first note far more softly, while Pressler stays loud for a long stretch in the middle.'),
('sector_featured_pairs', 67, 'title_en', 'e53c7a8f4910d89ee37fee7291050bc28fd3cdebd7618a8dd495de7ba51a001e', 'Sustaining Ashkenazy, Sparing Lugansky'),
('sector_featured_pairs', 67, 'note_en', '348a10f5deed14ff356560887bfdbf034ce4ee38a500e0e29c59e3987c9762d2', 'The lengths are nearly the same. Ashkenazy rings the returning bells at maximum twice; Lugansky plays loudly only at a single climax.'),
('sector_featured_pairs', 68, 'title_en', '0f32738c11e5dfa27cce7d2a4f8af7918ff0b0312b692c2562fb3a015f989756', 'Big Swings from Lang Lang, Even Paik'),
('sector_featured_pairs', 68, 'note_en', '626fdd624b87b30760f05fd368d78631b9935f9d5770875ef2dcd6f52712532c', 'Lang Lang sings loudest a third of the way in and sinks deeply afterward. Paik runs 16 seconds longer and keeps things even.'),
('sector_featured_pairs', 69, 'title_en', 'fc3bb7be03d5bac643ff754406fc8b1b96e22e3fa35fef3fa483a43950a5b31c', 'Pollini Closes Softly, Lisitsa Loudest at the End'),
('sector_featured_pairs', 69, 'note_en', '4afb82de5ea65c578392e30bc10517ce07caf6d123431b3a002c5b337e740dd0', 'Pollini drops to the quietest level 40 seconds after the climax and leaves the ending soft too. Lisitsa pulls back 15 seconds before the end, then plays the final chord loudest.'),
('sector_featured_pairs', 70, 'title_en', 'ebbe5b240a40289639e87007319573de0bfe7e63af639b52949bfc64aea8b210', 'Same Movement, One Minute Apart'),
('sector_featured_pairs', 70, 'note_en', '1b9c7f0b91d75aa1cfbc2f6bcbc73e2d2264c5245c0dcabcbe39762e1329a67d', 'Levit is 58 seconds shorter and holds loud playing longer. Gilels sinks deep once before the end, then rises again.'),
('sector_featured_pairs', 71, 'title_en', 'cbabe54ed4bb6abbeb7acbec8f48d61e5abd6bd21273b36f75db55f053bedb5f', 'Pollini in the Middle, Rubinstein at the Very End'),
('sector_featured_pairs', 71, 'note_en', '52a661499cd85f166c0475c0891d9482b4edafd2f815430769667bd3c4b47710', 'Pollini plays loudest two-thirds of the way through and keeps that level to the end. Rubinstein saves the loudest sound for the final chord.'),
('sector_featured_pairs', 72, 'title_en', '5cf9301ddda34e1c331fb2e6b6a3951759b0ca2854580cfce92b3841e31b8367', 'Kaufmann Loud Early, Beczała Gathers for the End'),
('sector_featured_pairs', 72, 'note_en', '86163a0a6399dd07cd9b61f478b9b35ccf8e6030e79e405f926ff32765a0b83d', 'Kaufmann already sings near the maximum at the first peak. Beczała keeps the first peak a step lower and gathers strength for the final cry.'),
('sector_featured_pairs', 74, 'title_en', 'a40019bb14b21d99d0aa7b70092c69f5c4b392115cde977bbfb3495212406c8a', 'A Climax Up Front, a Climax at the End'),
('sector_featured_pairs', 74, 'note_en', 'b05805ab346cd6e1e126e793314523301f92c82d707135743abce1a1b84e786c', 'Pires is 34 seconds shorter and puts the loudest sound in the first half. Lang Lang pulls back once a minute before the end, then plays loudest 30 seconds from the finish.'),
('sector_featured_pairs', 75, 'title_en', 'e139502bb138171008d27359d64f0a6c97785feb48d7020e4c0ce1da517c1e1d', 'All Four Alike, Loud Only at the End'),
('sector_featured_pairs', 75, 'note_en', '461174ee1365a41ccbb1e3a1124bd1a5aeb84e75de887d2010257cae15a9a52a', 'Sobotka plays the opening call and the final chord at the same level. Marriner holds the opening down a step and gives the final chord the loudest sound.'),
('sector_featured_pairs', 76, 'title_en', '878a6a07f3f3900c122262536978579abfca77049ab0b0b37249154cd302851b', 'Haochen Zhang Sustains, Yunchan Lim Sinks'),
('sector_featured_pairs', 76, 'note_en', '57ae4ada416daec8949aca2e834586e156deb91311ae4309e40dcdb230e3fe9b', 'Haochen Zhang holds loud playing for a long time and doesn''t drop as deeply in the quiet passage. Yunchan Lim sinks the quiet passage before the end very deeply from early on.'),
('sector_featured_pairs', 77, 'title_en', 'f2ded776a0ef64a4c82e7f2fc14fe6416cdd7c97051b005dadc039e476ffbc0a', 'A Re-Raised Ending, a Set-Down Ending'),
('sector_featured_pairs', 77, 'note_en', 'ea7fd8b0bff5d5c28a7cb25d54e2b361c7be2f175334ff366fe78187e4a2046d', 'Both run about 9:25. Lisitsa pulls back deeply a minute before the end and closes loudly again; Sumino, after a later climax, sets the ending down softly.'),
('sector_featured_pairs', 80, 'title_en', 'c3c0008260e091efd7d15ce3137bb56ef9e7429628b86904749cb448986d33e9', 'The Original Cadenza and the Ossia'),
('sector_featured_pairs', 80, 'note_en', '0d82b0a7d552948c9bc34c1dc11f90985aef415c82a37c233fe4e9abec6b5f5c', 'Yuja Wang begins the lighter original version softly and builds at the end, while Lang Lang pushes the heavier ossia loudly from the start.'),
('sector_featured_pairs', 87, 'title_en', '8788ed3f73c782973fae95a66548357464d533ebad64a30474fcf00ba12424c3', 'Rubinstein Rises Early, Zimerman Steps Back First'),
('sector_featured_pairs', 87, 'note_en', 'ee6f02a43960e262002e576f89f781c031d6db18210011800af2e4ca843b39e0', 'Rubinstein leaves the quiet passage early and sustains a high level for a long time. Zimerman steps back once just before the climax, then rises in one go.'),
('sector_featured_pairs', 88, 'title_en', '988f873f1eaa1391fa7cb4ae4c31317a1457869bef14bb1f93816e347859af34', 'Kissin Sings Evenly, Cho Whispers'),
('sector_featured_pairs', 88, 'note_en', '8e3c0a9e6355ac858674a4c0070336e7a8f57b263899a2604640a9966eaea8b5', 'Kissin sings at a similar, even level from the opening, while Cho keeps the first 4 seconds very quiet and builds over 20 seconds.'),
('sector_featured_pairs', 89, 'title_en', '609900202d1372452c9881d5458efbb835b2262a3260e6311dc29bb2ef0226e7', 'Rubinstein Max at Once, Cho Enters Softly'),
('sector_featured_pairs', 89, 'note_en', 'f9109e0c94eaa02e12a711cfd7568a57b634da6dd60c5d7a05b137379550b4b6', 'Rubinstein enters at nearly the maximum from the first sound and finishes 24 seconds sooner. Cho enters at the softest level and sinks deeply and at length twice before the end.'),
('sector_featured_pairs', 90, 'title_en', 'c08e0bab21c8f1d91720bca7629de0680b0243c50a011e596a756371a94965ba', 'The Exact Middle and the Final Chord'),
('sector_featured_pairs', 90, 'note_en', '8a48ae2a150121f17b311a9e6b3630d497d7dd90a08f315d60c1c17719cd77f0', 'André puts the climax in the middle of the movement and sinks deeply once before the end. Herseth keeps the beginning and end even and gives the final chord the loudest sound.'),
('sector_featured_pairs', 91, 'title_en', '4e6da7733fc9636be200aea17b1f6490ea45ae15b8d727aa56fd4472c0e7054f', 'Högner Dips Then Rises, Tuckwell Sustains'),
('sector_featured_pairs', 91, 'note_en', '68ebf6c59928b25e8bfd1ec13e3568aa419fb4a966118df8f041e26f0a6d6fd9', 'Högner steps back a level in the middle and rises again. Tuckwell is about 30 seconds shorter, sustains loud playing longer, and puts the climax on the final chord.'),
('sector_featured_pairs', 92, 'title_en', '0c89f15885820a538996344a68ca5abfe28185cba0f13b72d6b9865d6da4c116', 'Same Length, Different Depth'),
('sector_featured_pairs', 92, 'note_en', '5648d7a60156c643832adb80cccef696cfd58e7de2e1884555cc138c8260b170', 'Length and climax position are nearly the same. Karajan sinks the quiet passages deepest; Marriner sinks them less and sustains loud playing longer.'),
('sector_featured_pairs', 93, 'title_en', '6975eea2a764b96c147d30666ea474d5bd44fb7dd5b4b050056dd5a55ca1bb42', 'Loud at Once, Slowly Built'),
('sector_featured_pairs', 93, 'note_en', 'f78ce688bacd64ad4e50a76473aeefc05257a9a192204176e86b5e167c3bd9b1', 'Järvi reaches nearly the maximum in a minute and pushes on loudly to the end. Nelsons starts softly, sinks once, then builds up at the end.'),
('sector_featured_pairs', 94, 'title_en', 'd343417138ea5c71fdcb2f60a0083778b9a745da03bae08fb96888fdb9f83f9f', 'Peak at the End, Peak in the Middle'),
('sector_featured_pairs', 94, 'note_en', '2aa9a0a20601d6c39e8a933f1a2d03e19073d31ae104b106d2561f6bed910948', 'Gardiner puts the loudest sound in the closing rush, Bernstein in the middle. Bernstein takes the closing rush a step lower and closes more softly.'),
('sector_featured_pairs', 95, 'title_en', 'f1ce1307efe25457258704e2d78c94fc27c9ab606cdd97c5c7d0e43a43e54038', 'From the First Strike, From a Minute In'),
('sector_featured_pairs', 95, 'note_en', 'cf66dc9f83df08980e0f1c90d2dd3f23a6b1f74bb37717c9df4e90dfbd843226', 'The St. Lawrence Quartet is already near the maximum on the first blow. The Emerson Quartet enters a step lower, holds back for nearly a minute, then drives hard.'),
('sector_featured_pairs', 97, 'title_en', '83c9895de0a18b5843583d24a5042a3b15b654cedf1b8bb0129271ca1a9d3f77', 'Serkin Opens Loud, Cascioli Holds Back'),
('sector_featured_pairs', 97, 'note_en', '03c5f34981d91b6731ee9a91e2e064bb0b9d93a16ede14a6a1dd8724966fd1a2', 'Serkin plays the first melody loudly and already reaches nearly the maximum in the early part. Cascioli opens softly and holds back the maximum for over a minute.'),
('sector_featured_pairs', 98, 'title_en', '1383c2f000664ba228d27f3ea5711b029456eb811a78cdbc14d435838bd226f0', 'Loud at Once, Built Up at the End'),
('sector_featured_pairs', 98, 'note_en', 'ce56d63872c2db1df5c046495cbe4f5eaed1cd82b5cf4eb5907f63644703c36f', 'Pollini reaches nearly the maximum in 16 seconds and sustains loud playing for a long time. Lisitsa stays a step lower until the middle, then builds up over the last minute or so.'),
('sector_featured_pairs', 99, 'title_en', '31c9cbc5ad6f62b04a828520d2916c9d27ddf9074613526f6fe88830a0500022', '7:38 and 6:05'),
('sector_featured_pairs', 99, 'note_en', 'b3683bb4f171cb4ac37d9b3620bfc4e52d27c33e050b539b11df90e89142ec0d', 'Melnikov plays the same movement in 7:38, Yuja Wang in 6:05. Melnikov closes at the softest level, while Yuja Wang drops less.'),
('sector_featured_pairs', 100, 'title_en', '6163e70f57ee4d9c404925bb855e4436a0ace1a0e4ad10cc49e66681a8ab95f1', 'Mutter Holds Back Long, Bell Rises Early'),
('sector_featured_pairs', 100, 'note_en', '97a2e58851af04eef23c129da9c1a3ee89a95dc4ff7799d391a8a352abe8a3cd', 'Mutter opens the introduction at the softest level, stretches it past 30 seconds, then rises at once. Bell brings the orchestra up loud 8 seconds earlier than Mutter.'),
('sector_featured_pairs', 101, 'title_en', 'dc17b92bc2e068b4d8e914e4ef5bfee9458d0263012b83ab3ab0af2f5d6e1b3d', 'Buniatishvili Widens, Cho Narrows'),
('sector_featured_pairs', 101, 'note_en', '95b1ff27397a0818345903a185e51500e2ed950af45e8b2301f1205659a26df0', 'Buniatishvili keeps the opening song very soft and opens the gap wide in the minor-key passage. Cho enters loudly from the start and narrows that difference.'),
('sector_featured_pairs', 102, 'title_en', '03c766c8b3617f187d0d7b35e7945fc99c0f4d054fcd4066fdc34e2d9a6987e7', 'Pollini Front-Loads, Lupu Saves It for the End'),
('sector_featured_pairs', 102, 'note_en', 'c16d656121059b3f6338e41420ae98b065e02040d7b9a2d3024f44515a80ecff', 'Pollini is loudest at the first answer and stays even to the end. Lupu lowers the middle a step, then rises to the loudest level at the very end.'),
('sector_featured_pairs', 103, 'title_en', 'b594e5dc4a30f6bfb780a59bdc5f340c517684b65d34d174f9bfab0f6eac1aaa', 'In 20 Seconds, After Over a Minute'),
('sector_featured_pairs', 103, 'note_en', '5abae260cf3f7f54fa43d2702fab105746cd21b55865c44e1f533f2e46f95a3f', 'Karajan reaches nearly the maximum in 20 seconds and sustains loud playing for a long time. Muti lingers softly for a long while and reaches nearly the maximum only 20 seconds before the end.'),
('sector_featured_pairs', 104, 'title_en', '58cd95b747f4edac0f09ab545a751961525452f24112f071ece3e226949a009b', 'Abbado''s Second Louder, Chailly''s First Louder'),
('sector_featured_pairs', 104, 'note_en', '37377c32bd088ad93805796400b0d32d2a4e49bd7d690814f475115157d40927', 'Abbado blasts out the second fanfare louder than the first. Chailly''s first fanfare is the loudest, and the passage runs 16 seconds shorter.'),
('sector_featured_pairs', 105, 'title_en', '77f34176ac8ea3b17ba9145f55797b6c97f2b8ebed7ac93ae683a53cb32b9d4b', 'A Soft Bassoon, a Loud Bassoon'),
('sector_featured_pairs', 105, 'note_en', 'f3b1ccd8cba6048887c860f61b336c3f802718bacbe8e5302984a8441a1f9c89', 'Gergiev brings in the bassoon very softly and builds little by little for over a minute. Mehta opens with the bassoon already loud, keeps the level for a while, then raises it at the end.'),
('sector_featured_pairs', 107, 'title_en', '44f186427a0c9c633910043237d6c65fa483245ab5168289449c028774523058', 'Climax in the First Passage, Climax at the End'),
('sector_featured_pairs', 107, 'note_en', 'a80ef753f16e96f80fc00c8549bd83d685697fe846530625b0038eab268940e8', 'Lang Lang is already loudest in the first fast passage. Trifonov scales back as far as possible later on, then rises to the loudest level in 24 seconds.'),
('sector_featured_pairs', 108, 'title_en', '08bdc53cfe930005493b490e7618b0211df66a16ab9e3a3a5afbd0998da01599', 'Lim After the Peak, Kissin Before the Peak'),
('sector_featured_pairs', 108, 'note_en', '81eebe612b05d384236e15b0c5e02774d7336e71430b394460568317f329f5ba', 'Lim plays 41 seconds longer and drops to the softest level after the peak. Kissin is near the maximum even before the climax and sustains loud playing for a long time.'),
('sector_featured_pairs', 109, 'title_en', 'c1aa33c2f063a6d923c40c2298d787480e40b6efc054fff9ded4f0dbdcd422b7', 'Soft Chailly, Litton''s Late Peak'),
('sector_featured_pairs', 109, 'note_en', '8738894f917ff3593a25eeda1f512fc90c5a4fe4a96fadc4fe7c234458dc0f31', 'Chailly opens at the softest level and rises to the loudest point in the front part of the middle. Litton starts loud and puts the loudest sound toward the back.'),
('sector_featured_pairs', 110, 'title_en', '5c2868ec972937e47fd53e664aa439becab75f30c6047903797b07906124be88', 'Ciccolini Builds to the End, Haskil Peaks Mid-Way'),
('sector_featured_pairs', 110, 'note_en', 'f2fff9dfae5c1d295e1e09076004ad105bbe615e3bb4906f43ce0dc9cbec62cd', 'Haskil is about 1:40 shorter. Ciccolini opens softly and plays the final chord loudest, while Haskil plays loudest in a middle variation.'),
('sector_featured_pairs', 111, 'title_en', 'dc7655690d4c225b9d7866f4a8548f4441a6086aca1f8b200cac81b35135810f', 'Bernstein Raises Early, Thibaudet Holds Back'),
('sector_featured_pairs', 111, 'note_en', '6a89739f960811bda114a5bb9ac5ef6fb09d7f44fad3a29e78a3cc592a017d05', 'Bernstein raises the level a step from the middle on and builds further at the end. Thibaudet keeps the middle low too and rises in one go at the end.'),
('sector_featured_pairs', 112, 'title_en', '50853578d944e2e2cd663a7c69655905b5d36126d23a258405cb757e4f21722c', 'Loud from the Start, Held Back to the End'),
('sector_featured_pairs', 112, 'note_en', '19f9a3c85fb134d28e1cd206583258d5f58af147af4fd6f1012944297286c2c3', 'Rubinstein enters at nearly the maximum from the first sound and sustains it to the end. Giltburg drags the middle at a low level and reaches nearly the maximum only 40 seconds before the end.'),
('sector_featured_pairs', 113, 'title_en', 'c229d79401313309eb7696c45560b445d90149a296f8bb33a1963b587f364d3e', 'Big Swings from Buniatishvili, Even Zimerman'),
('sector_featured_pairs', 113, 'note_en', 'd1de772af2ae318e2b77f7c4322cf9c236a0b425452105e02dd6c962882060a8', 'The lengths are nearly the same. Buniatishvili opens at the softest level and swings widely; Zimerman reaches nearly the maximum early and keeps things even.'),
('sector_featured_pairs', 114, 'title_en', '0a9a9819241bb403cc64d2eca7be689ad719af18345f2c575ec072246a026a5b', 'Muti Stays Low, Masur Sinks Deep'),
('sector_featured_pairs', 114, 'note_en', '9d4677aa64d948243cda94e77eadf1f97b49dfbc559067fa54370a237793b6fc', 'Muti keeps the first minute low and piles it up in the last 20 seconds. Masur sinks deepest early on, then soon builds loudly.'),
('sector_featured_pairs', 115, 'title_en', 'f278fa0d6b354a7b73acefb1e3946fed4e2ce6dbacd0b7050355a7084fa5dfc8', 'Bernstein Holds Back, Mehta Raises Early'),
('sector_featured_pairs', 115, 'note_en', 'a40e023656f302427f5d2a7547f80b10c9e37d82cd0d69687fbfb23a97faf40b', 'Bernstein holds back for the first 30 seconds and gets loud only after nearly a minute. Mehta enters loudly from the start and sustains loud playing for a long time.'),
('sector_featured_pairs', 116, 'title_en', '3ddab1baab319422fa2bd43cf7f15d8da048e4cf356ef5e41f5e5877e565cb9c', 'Maximum at Once, Saved for Later'),
('sector_featured_pairs', 116, 'note_en', '630ac3fb66d768be7d0429589391043002ca1ebb5440ea6146ff6622079f8260', 'Dutoit pushes at nearly the maximum from the first sound to the end. Abbado keeps the first half a step lower, then drives upward in the later part.'),
('sector_featured_pairs', 117, 'title_en', '658c6e07556b116d03b830ab747117b85908e714694f94201123446a57091e1b', 'Kissin at the Back, Perahia at the Start'),
('sector_featured_pairs', 117, 'note_en', 'b3a04f5ff80fde018bee7bbc4ad7595ac9030b67f2376885955cfa8c7812837c', 'Perahia plays the first descending chord loudest. Kissin sinks the theme deeply and plays loudest in the big passage later on.'),
('sector_featured_pairs', 118, 'title_en', 'ce5e040fabf64462b063ecc5175fb682dfb00c6ea939a9708fcbaa882ca31641', 'Tsujii Sustains, Cho Rises at the End'),
('sector_featured_pairs', 118, 'note_en', 'bbdfb2cc9215f91f1e35681ee23df50365092c6bf4122f9248dced65aafb0726', 'Tsujii climbs once and keeps a loud level to the end. Cho sinks deeply once, then rises to the loudest level in the last few seconds.'),
('sector_featured_pairs', 119, 'title_en', 'b004c02beb29eb2c8925227e3a3a6ac72a85bcd69714a7c246833cd2448e12aa', 'Argerich Sustains, Ott Sinks'),
('sector_featured_pairs', 119, 'note_en', '7917abd25ceea47d09f0cf71a7310485651cda5d67137243319587a9d760bd65', 'Argerich holds the first loud passage for a long time and drops less deeply than Ott. Ott reaches the maximum early, then sinks deeply and for a long time later.'),
('sector_featured_pairs', 120, 'title_en', 'c9e6e1a49c5417f6b4097a1a5e9e33fee64b72fd07856327e919a45f7eb1187d', 'Fast Karajan, Slow Bernstein'),
('sector_featured_pairs', 120, 'note_en', '16503ead295d69eb9ef8fb6335bce818d611d131e3930422f380bba6936091f1', 'The same passage takes Karajan 1:15 and Bernstein 1:43. Karajan lays down the opening at the softest level; Bernstein starts louder.'),
('sector_featured_pairs', 121, 'title_en', 'cc7710c59a6722fcd5af9c9b66fbead15a53d8b99698a0320f414f3aad3066bf', 'Abbado Small, Karajan Early'),
('sector_featured_pairs', 121, 'note_en', 'd9a13de555103abf667974255901542a0838a59222734a546549581d09f95fd8', 'Abbado keeps nearly the first minute very small, then stands up loudly all at once. Karajan raises the level little by little from the opening and gets near the maximum about 13 seconds earlier.'),
('sector_featured_pairs', 122, 'title_en', 'd566594dc02c827fdcd621c99cbc4402eb518f23be62a1c7bed4ee33db254e77', 'Same Quiet Passage, Different Depth'),
('sector_featured_pairs', 122, 'note_en', '66b3daaaa5dedc67d930731813f59980e5bc9fe015bf079429f6593b2616a405', 'In the same quiet passage Abbado sinks the lowest of the three. Marriner descends the least and also closes nearly at the maximum.'),
('sector_featured_pairs', 123, 'title_en', '27e09d53a395d5a7baa162c92eea64d8d8a2168ae488b91662e1f5cc8abcf46d', 'Quiet Mutter, Bell Loud for Long'),
('sector_featured_pairs', 123, 'note_en', 'b8384e5864d4bc66b6a970262b4e56bd7534863fd2fe1027790d59227c0f1122', 'Mutter starts at the softest level and sinks deeply even after the climax. Bell drops only slightly after the climax and sustains loud playing the longest.'),
('sector_featured_pairs', 124, 'title_en', '9e9e1a66e8fd125b886e5b43c0d881e41e4cdff5d15fa8265d23096d270a0aa7', 'Same Song, Different Peak Position'),
('sector_featured_pairs', 124, 'note_en', '38f63c28865fdbdd01036e3baa250dcdcb59fb444149f9afa899ff48ab7b8311', 'Ottensamer stretches the song out and puts the climax toward the back. Meyer opens softly, sings loudest early on, then keeps the loud passage short.'),
('sector_featured_pairs', 125, 'title_en', '0e7563ec231f98d5dc0e9464b5f67bef564bd7da1cda9bf36d7c1d18cb7bcd8f', 'Loud Up Front, Loud Only at the End'),
('sector_featured_pairs', 125, 'note_en', 'e473ef768dd80ecbd75089be3d3524e7f793fc910296de50920fe54c2c56cb8c', 'Maisky starts building after 20 seconds and is already loud in the early part. Yo-Yo Ma stays soft for over a minute and puts the climax right before the end.'),
('sector_featured_pairs', 126, 'title_en', '8091e210fcb0db549c8016687e55b104a77999e5ed66286c9c1f6443f9edd237', 'Bernstein Opens Loud, Karajan Opens Soft'),
('sector_featured_pairs', 126, 'note_en', '32e293995e342a6d330820c4bf30962f7c65e21b3c46999fea6a08c1d8a4276c', 'Karajan brings out the first motif the softest of the three and is loudest in the middle. Bernstein plays the first motif loudly and is loudest at the end.'),
('sector_featured_pairs', 127, 'title_en', '1db539fee60c3ebccdb9221555fda324ec9c46e0ae8d59618ca2eeafc52d96c0', 'Same Passage, 23 Seconds Apart'),
('sector_featured_pairs', 127, 'note_en', 'e741531a2e9d32cf8208094bbe04bcb70cd418b01355baa7bb3ff2b733dddba1', 'Davis takes 1:18 for the passage and Bernstein 1:41. Davis keeps the level even, while Bernstein sinks deeply before the climax.'),
('sector_featured_pairs', 128, 'title_en', '7bcd1de9d4ee73023f349589b16538cdd24b0d9743fabf94605edf431ea2ae41', 'Keeping the Back Loud or Thinning It Out'),
('sector_featured_pairs', 128, 'note_en', 'fca883faa488ef57eeabae3318cbba1f96478a22a9007ae45ceb3abd71b86913', 'Both are loudest within the first 15 seconds. After that, Barenboim leaves the later sound loud, while Marriner thins it out to very soft.'),
('sector_featured_pairs', 129, 'title_en', '9cec7a5b57026fc3e64415cfe9fea817712a93e71e032cecd8a5961365d31e0b', 'Fast Marriner, Slow Bernstein'),
('sector_featured_pairs', 129, 'note_en', 'c04fd563e742d9b475ff21964c21f76432467eb2a6ff3c507f02ab9469085c83', 'Marriner takes the same introduction in 1:38 and Bernstein in 2:26. Marriner re-establishes loud playing a few times; Bernstein stays soft after the first minute.'),
('sector_featured_pairs', 130, 'title_en', '449ed1a3f4ba73a75e8e64d0eab36b0584426229429f91804dd74b13806eb4f9', 'Fast Karajan, Böhm Saves It for the End'),
('sector_featured_pairs', 130, 'note_en', '06537b20a236c8908d6b0cba17914be07f980e3bd03c26d6f3a317a3e18f24ca', 'Böhm is 13 seconds longer. Karajan is loudest at the early high point; Böhm holds that point back a step and rises to the loudest level at the end.'),
('sector_featured_pairs', 131, 'title_en', '711c200c04ec04ba6c4f3e31c9be2e23803ec5cb1f9139b762f200f89861adef', 'Shallow Bernstein, Deep Fischer'),
('sector_featured_pairs', 131, 'note_en', '57c9457632e49d0af7e334c885920ae4e444f4c9eb2670f4f7066cefef63a434', 'Bernstein keeps the quiet passages shallow and climbs back close to the level of the first chord by the end. Fischer sinks the same passage deeper and for longer.'),
('sector_featured_pairs', 132, 'title_en', '8adc0cff8851b3f3bc5f703f73e03e86403430803e2e7c3f7aea5eb25ff358dc', 'From the Very Start, Only After a Minute'),
('sector_featured_pairs', 132, 'note_en', '3c146037b87e0534ad052d179a76be60c3817894586323040853de766e090f01', 'Thibaudet plays at nearly the maximum from the very opening, which the timpani begin. Rogé builds a step at a time and plays loudest only after more than a minute.'),
('sector_featured_pairs', 133, 'title_en', '9772c127897fa80c1e459c0c82fc1e296280a420bdddffacd2e30692e163b447', 'Soft Ashkenazy, Early-Loud Lang Lang'),
('sector_featured_pairs', 133, 'note_en', '2e19c6277f129832c0b6e14ad1299c1c05270cc8a0bea2d107a19edc602f00a6', 'Ashkenazy keeps the introduction at the softest level and reaches the maximum only within the last 10 seconds. Lang Lang is less soft from the introduction on and gets near the maximum over 20 seconds earlier.'),
('sector_featured_pairs', 134, 'title_en', 'ec8e86569a1dd7f71be6c7b3427fdb92ee97b1bda08958394a776398978b587f', 'Soft Timpani, Loud Timpani'),
('sector_featured_pairs', 134, 'note_en', '4a91eef19e896f779ab3a7102fb2d7399f6fb0d8e7c737d29b2fca502c558c0b', 'Mutter opens the same five drumbeats at the softest level, Hahn at the loudest. Hahn passes through this stretch 9 seconds faster than Mutter.'),
('sector_featured_pairs', 135, 'title_en', '772cd23904ee3f0119db4f8dce5fe177d036cff6e2b0502427d66ce17ff7f65a', 'An Early Climax, a Late Climax'),
('sector_featured_pairs', 135, 'note_en', '70f6b11a9832f3b3494ecdedc81fd97d5d26f25ac6ffaf5dfc43ac1e22787300', 'Kang peaks early and drops to the quietest level in 9 seconds. Mutter sinks deeply once and reaches the climax 24 seconds later.'),
('sector_featured_pairs', 136, 'title_en', '9ad703b911e35928adfe7f3a05291f3b7df0f3ddc41bc23908f924226de5b698', 'From the First Chord, After the Barrage'),
('sector_featured_pairs', 136, 'note_en', 'e73d00877ada3f7f5ff11cc05230204e0c0946fb5d78e2d988107d8f7a493e5e', 'Pollini hammers the first chord at the maximum. Lang Lang saves the first chord and rises to the maximum only after the run of repeated blows.'),
('sector_featured_pairs', 137, 'title_en', 'ca0b19f5354a4888cbf979f425410735be89da3e1879165d3c071f17a8854469', 'Smaller Drop, Deeper Drop'),
('sector_featured_pairs', 137, 'note_en', '0147eac1773eaf9adcc67f0e93c812935bc4a78ad28f8ce6ab108187779ff801', 'Yundi Li doesn''t reduce the level much even in the quiet theme. Perahia drops deep every time the theme returns.'),
('sector_featured_pairs', 138, 'title_en', 'af22d7381aeed3703fd6987b9c22bacf9d1367af1d0206ea6a03be6782c78116', 'Even Borodin, Wide-Ranging Emerson'),
('sector_featured_pairs', 138, 'note_en', '7a35a2212580cd12ab11ca6e7400c9044a332ed3c09e16ae936fcddafe8378b7', 'The Borodin Quartet keeps the difference in level smallest and puts the loudest sound late. The Emerson Quartet drops to a very soft level, then rises to the maximum in 12 seconds.'),
('sector_featured_pairs', 140, 'title_en', 'e7073f8e2ca19f5bbb35dceca83d27e79fb4de3bf9471c73e0d691582b12099a', 'Bronfman Rises Early, Schiff Rises at the End'),
('sector_featured_pairs', 140, 'note_en', '56e55dbc298ad58318f4e50f38287231c2cf647b00b3a59cdfca6827a6b5f3e4', 'Both come down once in the middle. Bronfman drops only slightly, then soon climbs to the loudest level; Schiff sinks deeply and rises only at the end.'),
('sector_featured_pairs', 141, 'title_en', '40b5ee9d06e55d830f593a754d40a77952b4dcb5d640ddc7616ab939842505f2', 'Even Chailly, Early-Rising Abbado'),
('sector_featured_pairs', 141, 'note_en', '0610c3458d8d23d66679af72d4c742a12eea63cfd4fadbb95c36f84af465cc58', 'Chailly keeps the level even from the first sound and gets loud only near the end. Abbado opens softly but reaches nearly the maximum in the middle first.'),
('sector_featured_pairs', 142, 'title_en', '0018fe437c1e1d97957c7370d578c997062ed82abe58b2eef2a9fed3102621c5', 'Early-Building Haitink, Hushed Karajan'),
('sector_featured_pairs', 142, 'note_en', '34a3cdd7c599a96eeaa1ac2028b8ecc4fa7e867ffa2d02b002eb35cfa144becb', 'Haitink reaches nearly the maximum in a minute and sustains it for a long time. Karajan opens at the softest level and reaches nearly the maximum only just before the climax.'),
('sector_featured_pairs', 143, 'title_en', '2890fe1bf8981103c24ea318c38a1d5e9ca68933afd9ca89cf817150fc309564', 'First Passage or the End?'),
('sector_featured_pairs', 143, 'note_en', '8710f3a549010ef47ca927dd37a234145c9b9c0e2e07e242735f07c2721ee916', 'Karajan brings the sound back up to its loudest at the end after having lowered it. Abbado is loudest in the first passage and doesn''t raise the ending as much.'),
('sector_featured_pairs', 144, 'title_en', '49e7ec0c0fc1cf58f3bd5b41fdcffe441f9151838c66332f0567d6aeb8023b95', 'Barenboim Arrives Early, Previn Only at the End'),
('sector_featured_pairs', 144, 'note_en', '15b2fd84b1a7c38194787d288a3b431b96c54604571e53cafc1a413277e0ddac', 'Barenboim gets nearly to the maximum in under a minute. Previn keeps the first two peaks a step lower and gets nearly to the maximum only at the end.'),
('sector_featured_pairs', 145, 'title_en', '1f9e88abb03762cb32ab99d78a7e2f0e60f2744b6ce6994b99ac77bef0b7f825', 'Previn Loud at Once, Denk Builds Softly'),
('sector_featured_pairs', 145, 'note_en', '5a8837d40161d4a3f2afd53b5f5b442dddcd771ddd87728addbd3c473cee57ed', 'Previn reaches nearly the maximum in 20 seconds and keeps things even. Denk opens the cello at the softest level, steps back once, then builds for nearly a minute.'),
('sector_featured_pairs', 146, 'title_en', 'cb73c4757af20e26d2bf5d182d7e99097b603aa2b09c2b5eea0b6fa6179270bb', 'Argerich Sinks, Pires Raises Again'),
('sector_featured_pairs', 146, 'note_en', 'f952bdaa36e00ace7b3ff9ecb87c27d6ea722cfa52765e6dcaf50509b3acdb6d', 'Both play the first chord at their loudest. Argerich sinks the second theme deepest and longest, while Pires sinks once and raises it loudly again at the end.'),
('sector_featured_pairs', 147, 'title_en', '50df5a271e8f98d8f47e43d85b8ed76936a4483c144c41742d9930b3a880eaca', 'A Shallow Reduction, Almost Silence'),
('sector_featured_pairs', 147, 'note_en', '16c2e3b3d8dac3811468df76e6701934fd44d06c9f9bd79b729bacef89c025ed', 'Karajan is 18 seconds shorter and reduces the middle only slightly. Gergiev sinks the same spot almost to silence.'),
('sector_featured_pairs', 148, 'title_en', '7b6813871abac6883f66703a97e2facacfdd0611065a976caecd9b910d1f856f', 'Muti Loud at Once, Relaxed Chailly'),
('sector_featured_pairs', 148, 'note_en', 'b2d62a43029b27751d6d8bba4a032df1774c44196e77a74163163b0ed7386d7d', 'Muti enters at nearly the maximum on the first theme and reaches the climax earliest. Chailly runs about 20 seconds longer and puts the climax right in the middle.'),
('sector_featured_pairs', 149, 'title_en', '6605b1a9e63a7f792d2863a1f6f173d01a35b58f944186a316f3872ae716681c', 'Previn First, Karajan Longer'),
('sector_featured_pairs', 149, 'note_en', '0476a1ce56d8ee8ca1ec9d1a7d38d282bd9cd89268acdd96cc898df9c5c4cfca', 'Previn reaches nearly the maximum in under a minute. Karajan is 9 seconds shorter and keeps pushing loudly to the end after the climax.'),
('sector_featured_pairs', 150, 'title_en', '55bd82384e983beafe8064df08ffd1680dfca03e3e0a812dd5c91ee31f2c596b', 'Davis Softly In and Out, Frühbeck de Burgos Clear'),
('sector_featured_pairs', 150, 'note_en', '2c28128b594497996ae1fa7293e5185ff8243932a4e3456506c77a40379b50f5', 'Davis runs about a minute longer. Davis puts the beginning and end at the softest level, while Frühbeck de Burgos pushes loudly from start to finish.'),
('sector_featured_pairs', 151, 'title_en', 'c6ce57938287afb9b973a4440c90e0fe53a7e3bccdea0dc5a7656857bcb8b13a', 'Reaching Early, Rising Late'),
('sector_featured_pairs', 151, 'note_en', '9f8559dfc2d6f2b3223b227a9fa8473c2b44d96dfccf224cfcef775af7724cf0', 'Fischer-Dieskau reaches nearly the maximum early and leaves the ending loud too. Terfel postpones the loudest sound until near the end and leaves the finish very soft.'),
('sector_featured_pairs', 153, 'title_en', 'e799740ab1080db31c00549115520bc59b5408b728928c986bd09bec4f134ceb', 'One Late Leap, Early Step-by-Step'),
('sector_featured_pairs', 153, 'note_en', 'ebb80ba94bfbd5e8166b2e64868f24c25a80988da336678a9f5f0fd425008eeb', 'Dutoit keeps the middle low, then rises to the maximum in 8 seconds at the end. Ozawa starts getting louder 15 seconds earlier and builds step by step.'),
('sector_featured_pairs', 154, 'title_en', 'bb192f008ea55eef69b4a827e866cbe95c66691c744c99de66dd5eb506dec03f', 'Once Early, Once at the End'),
('sector_featured_pairs', 154, 'note_en', 'fbf4f75578b0518a1b59e9918bc39eed254bc5ede427f0eb3b38a9ad8ead9a95', 'Gergiev is 28 seconds shorter than Haitink and is already near the maximum early on. Haitink sinks deeply in the middle and rises to the maximum only once, at the end.'),
('sector_featured_pairs', 155, 'title_en', '2f469be416656f519d4759c60894db7ddc8b414c26b4357a8c103b7df1c7e304', 'Bernstein Comes Down After the Peak, Karajan Sustains'),
('sector_featured_pairs', 155, 'note_en', '39455b198bf7021388b157dc0fb331fe3fd2cddff318e8a1460efb4c996dee56', 'Both are loudest in the exact middle. Bernstein then comes down a step and ends softly, while Karajan stays at nearly that level to the end.'),
('sector_featured_pairs', 156, 'title_en', '56ffcae7f23046d3cfb4323b03969021acc3f9dbb890638ee297d2d5c9c99067', 'Dutoit at the Very End, Karajan a Minute Earlier'),
('sector_featured_pairs', 156, 'note_en', 'ef25571e35669b67fa906c8f83bf6360d7532eb072865efda8756baadaf279e0', 'Dutoit keeps the middle soft and becomes loudest at the very end. Karajan raises the middle loudly too and becomes loudest about a minute before the end.'),
('sector_featured_pairs', 157, 'title_en', '4e1981d8fcc669430b1a99a0cbe7dbaa82ab6828cda6c22ff7a0743f37356d01', 'Muti Pauses Briefly, Chung Lingers'),
('sector_featured_pairs', 157, 'note_en', 'e3daf8f729dd8d7ace503b0b7cff3105257e7343abecb316af623cac3e67966c', 'Muti passes through the hushed passage between the two outcries in 39 seconds. Myung-Whun Chung stretches the same passage to nearly a minute and plays the first outcry louder.'),
('sector_featured_pairs', 158, 'title_en', '72cca9bb9ca89e8e4288a778d07ceb038de71ac6796838941bcdfcdbaec4488b', 'Same Oboe, Different Level'),
('sector_featured_pairs', 158, 'note_en', '083587291d705bbff1dd3246b0bd18729abb6cd7ce8ed99a3583386e1cad16aa', 'Bernstein brings out the first oboe song loudly and also runs shorter. Tilson Thomas keeps the first song soft and gets nearly to the maximum earlier.'),
('sector_featured_pairs', 159, 'title_en', 'e50b08a52594088abaa9c72dcbfdac9d6975d94e1527478d59c15a7d1d25e927', 'Ozawa Up Front, Haitink at the End'),
('sector_featured_pairs', 159, 'note_en', '1510fe8df3a6e3c00b6c05161348cd601767946e8e65236690ccaba3ed2742f5', 'Ozawa puts the loudest sound in the early tutti. Haitink sinks the middle deeply and plays loudest at the end.'),
('sector_featured_pairs', 160, 'title_en', '15a8b059a64171635286607706f04f5ff303abbe38518bbd70ceb268b582c094', 'A Deep Middle, an Even Middle'),
('sector_featured_pairs', 160, 'note_en', '28d82973c5941a035e9fa32e1040bd58dd5d42521df375d4ff336f19d9b89374', 'Dutoit eases off right after the first chord and sinks the middle deeply. Bernstein doesn''t reduce much and pushes on at the same level.'),
('sector_featured_pairs', 161, 'title_en', '1bab0468e25b6fdf3238c235c5bcdd71ae020b7a5ae1e4533751e7ffe782ba67', 'Maximum at Once, Held Back to the End'),
('sector_featured_pairs', 161, 'note_en', '0c83cf39a78a7f7ab0da14f4721ed2368a8fceb0d313540361456794e8835fd6', 'Previn reaches nearly the maximum 8 seconds after the fanfare and sustains it for a long time. Dutoit reduces the middle to a small level and gets nearly to the maximum only when the march returns.'),
('sector_featured_pairs', 162, 'title_en', '9c278ed9c49c0dae77d2e8ff1ed2d7d071c5bc3df1bdc34fa01eec4ae88a9fb8', 'Softer Hahn/Marriner, Softest Mutter/Karajan'),
('sector_featured_pairs', 162, 'note_en', '30a6eb9a6418f6687fa2b03ac1a6269a1513d4a4930b3ca85bbdac650e56db5b', 'Hahn and Marriner bring out the first theme less softly and sustain the big passage for a long time. Mutter and Karajan set the first theme at the softest level and open the gap wide.'),
('sector_featured_pairs', 163, 'title_en', 'e7f243f437ccdbbf65c1cdb6a0b2ba1785f468b80a48af10bba312bacf1c3d50', 'Short Barenboim, Long Mehta'),
('sector_featured_pairs', 163, 'note_en', 'e7e6b15f2d6e1f38880e449f9707a57f2c7df262f39c9cd1757b8f676c7d2f93', 'Mehta is 33 seconds longer. Barenboim lets the sound down the most after the climax, while Mehta starts at the softest level and keeps it big to the end.'),
('sector_featured_pairs', 164, 'title_en', '42354869485f98154d56bbb9b0217925d1bdd09c45708276e9ed6b82a774a437', 'Loud-Opening Davis, Softly Drawn-Out Tilson Thomas'),
('sector_featured_pairs', 164, 'note_en', '950252089a52624630314f95551a73a3ca7f1dafaa00ca1cd63ebd3f93377c1a', 'Both are loudest near the end. Davis plays the first sound loudest, while Tilson Thomas stretches out the opening section at the softest level.'),
('sector_featured_pairs', 165, 'title_en', 'ba5a7a4f047bdc6b18ad6e2ccb92019c9e8b24c979738dc7581f33520ba7fed5', 'Nézet-Séguin Holds Back, Bernstein Sustains'),
('sector_featured_pairs', 165, 'note_en', 'a3fcea622ee49f3fc6179ae62280a314385b4b13da834845c371fbf91f591ff1', 'Nézet-Séguin holds back nearly the maximum until 30 seconds before the end. Bernstein reaches nearly the maximum from the middle and sustains it to the end.'),
('sector_featured_pairs', 166, 'title_en', '5ba8f614e95ca78a6e9e3e64b09603a2bcc301990af214baf37959d91cf6945f', 'Abbado Opens Softly, Nelsons Sustains'),
('sector_featured_pairs', 166, 'note_en', '366807e6d77d6e877a5805df5d6dd6fe9d3b7102f32b077019057a03a0954ea2', 'Abbado brings out the first chorale at the softest level and places the climax 13 seconds before the end. Nelsons sustains loud playing the longest and becomes loudest at the very end.'),
('sector_featured_pairs', 167, 'title_en', '7424f4cfca56bb24f03b47900ba8018ff98254a0523aa8fda99acfccd5919589', 'Miklósa Sinks, Gruberová Sustains'),
('sector_featured_pairs', 167, 'note_en', 'd03605dad33a37bb5f81184ff013ffc278fc3dfcf882c414a706f62b408d9e13', 'Both are loudest about 20 seconds before the end. Before that, Miklósa sinks for a long stretch, while Gruberová drops only slightly.'),
('sector_featured_pairs', 168, 'title_en', '63cb0f34ef3e6cfe2bc483201299e23af314f1e79ad41dc5a1179d10fc3717ee', 'Flórez Presses Down, Beczała Cries Out Early'),
('sector_featured_pairs', 168, 'note_en', '08b81e1c6a3e927602bee959c2843309660a86f9cdcf8a23f2290d733fdec9d9', 'Flórez keeps most of the song pressed down softly and reaches the maximum only at the very end. Beczała already cries out at nearly the maximum at the end of the first verse.'),
('sector_featured_pairs', 169, 'title_en', '297f84978407db83e73edb1e33e4664e6053b1831efa5ab774f195ff02386866', 'Karajan Opens Loud, Pappano Opens Soft'),
('sector_featured_pairs', 169, 'note_en', '5547047840e98dcb07e48e8502164323307b0fec2f8488aacd6446a2234ea7fc', 'Karajan enters loudly from the first fanfare and stays even to the end. Pappano starts softly and begins to get louder only 12 seconds before the end.'),
('sector_featured_pairs', 170, 'title_en', '5b6ebddd2258100cff94925f1740ff79a9bd39c68eb7f36a94fee4dfccedb560', 'Solti Opens Softly, Muti Opens Loud'),
('sector_featured_pairs', 170, 'note_en', 'a96d7b171f88b3d98f06919592282b2e56d82c418cfd2f0d0388bbdcd3c157fd', 'Solti opens the prelude softly and raises it a step at a time toward the end. Muti opens the prelude loudly, takes one more breath before the final chord, and then rises.'),
('sector_featured_pairs', 171, 'title_en', 'f6fde4f55c572567c24c9d62e65c4df20161b26222aacbdba31e2345efb9aa7f', 'Bernstein on the First Chord, Karajan Just Before the End'),
('sector_featured_pairs', 171, 'note_en', '3b12b6c23ca9e9ce66ddf28dbd209baee1d6c5f5cd35b370b11ae44bbd628944', 'Bernstein is loudest on the first chord and leaves the closing section loud too. Karajan rises to the loudest level just before the closing section, then sinks the deepest.'),
('sector_featured_pairs', 172, 'title_en', 'e21a6571d455fa15c3f9a35d0c4c687fb05be1795add23e20c4c2358812315a5', 'Abbado Gathers for the End, Rattle Loud Twice'),
('sector_featured_pairs', 172, 'note_en', 'cfaa6ab5c37a285ee0e483b412afecaa94c1803c962606349c248399b42cae0c', 'Rattle is about a minute shorter. Abbado sings loudly only at the final surge, while Rattle sings as loudly in the middle as at the end.'),
('sector_featured_pairs', 173, 'title_en', 'c31dbad45ec4d7eed0046d770036eb32ad93ede789179d15f1386efbd67ae634', 'A Less Soft Start, a Very Soft Start'),
('sector_featured_pairs', 173, 'note_en', '37b53c38634e5c8def57c092d1714a8ad34afa27cb47008d1275981e47c9a5af', 'Karajan starts less softly than the other two from the first sound and sustains loud playing for a long time. Davis starts very softly and rises to the maximum in 6 seconds.'),
('sector_featured_pairs', 174, 'title_en', '8deb568b05116844f8be43616655a66c44dc4c16a0b9325d8e857e520a43bd04', '45 Seconds and 6 Seconds'),
('sector_featured_pairs', 174, 'note_en', 'f09288ecaee86e013d7a7a0a816c59292e0bb0860f2ee023c16e4c5a7180fba2', 'Bernstein reaches nearly the maximum in 6 seconds and blasts out both rising points at the same level. Noseda starts at the softest level and takes about 45 seconds to reach the maximum.'),
('sector_featured_pairs', 175, 'title_en', '954e41c18d5e4aa6383468f0f1b3063e7ddb7bffde7cfc80b0d6bcabde69238b', 'Even Solti, Deep-Sinking Tilson Thomas'),
('sector_featured_pairs', 175, 'note_en', 'f152be95f880a2a85c8172dfa2ad087ab488955f04c236d5f9ca2865faa95671', 'Solti doesn''t sink far between the chords or in the middle. Tilson Thomas sinks the middle as deeply as at the start, then rises again.'),
('sector_featured_pairs', 176, 'title_en', 'eff3f0aeb56634dc9a7b966dc9ae84ce7a2117998e2364a4d07e4a6112e3a9f6', 'Solti at the Opening, Nelsons Toward the End'),
('sector_featured_pairs', 176, 'note_en', 'b057fd1b52bedf9d0028b289d25fed22ad3fa8346067995f984ba2e7af882b70', 'Solti plays loudest from the first beat through the 9-second mark. Nelsons opens a step lower and puts the loudest sound toward the end.'),
('sector_featured_pairs', 177, 'title_en', '03a869136f5d3ad946be52cf0f5bf60110f5b8a00509a442d10f0b3a2e562fe5', 'Let There Be Light, 30 Seconds Apart'),
('sector_featured_pairs', 177, 'note_en', 'e1229cd77db256fc78714876c99c3064e26123b05a55fc28bd0bd01d869d4c33', 'Solti reaches the burst of light early, dropping the sound very low just before it. Bernstein opens even more quietly and takes over 30 seconds longer.'),
('sector_featured_pairs', 178, 'title_en', 'a3c2ec219d6d41fb76e39419f324121ee35f1ae34677fda3fa1fb8a3fa89f96f', 'Same Pace, Different Last Verse'),
('sector_featured_pairs', 178, 'note_en', '3b47bfd9aa54d5202f2c62a4bc28505ffc7a1f9cfe9c4a24300124d35c408dbb', 'The two performances keep nearly the same pace up to the passage about the wind. Fischer-Dieskau sings the last verse loudly again, while Goerne sets it down little by little to the end.'),
('sector_featured_pairs', 179, 'title_en', 'c324bf2c9952181befb847976b94601aa9a0e78691958bfc6c804afd5c63847e', 'Gerhaher''s Soft Prelude, Goerne Holds Back the First Verse'),
('sector_featured_pairs', 179, 'note_en', 'c79f2a3632c13f0ed190f28a030830b9d0a2151f5358658a246668107f3e8b99', 'Gerhaher opens the prelude at the softest level and sings the first verse at nearly the maximum. Goerne keeps the first verse a step lower and gathers strength for the second.'),
('sector_featured_pairs', 180, 'title_en', '67b15ed36f97bef8b3f8262b3da30dd173d6a4b7271d2b2d9066cffa7f5172cd', 'Filling Quickly, Reaching Late'),
('sector_featured_pairs', 180, 'note_en', '2bb3020782163dec8511338bf256fdadcc8538eca321e6880f9a69ded9c14173', 'Solti fills the sound in under half a minute and pushes on at that level. Dutoit reaches the peak only after building for nearly a minute, and cuts the loud passages short.'),
('sector_featured_pairs', 182, 'title_en', '1abbbd3d825bf2ed1d545e904923832753eebaa6d199035290004ccaa8032d21', 'Fast Jansons, Long-Hushed Karajan'),
('sector_featured_pairs', 182, 'note_en', 'd1a57eaacb197c85b7187bc786d2daf1e11522a9a7413c77c5422b2caaa9b32d', 'Jansons passes through in 1:37 and plays loudly from the first phrases. Karajan runs 24 seconds longer and sinks deepest between phrases.'),
('sector_featured_pairs', 184, 'title_en', 'da9843746ce57386c2c8b82eb72afed9c3f8d7fafb7162c7e707898b7661b54d', 'Even Katsaris, Growing Barenboim'),
('sector_featured_pairs', 184, 'note_en', '7370131cb3c0b9ca34c769e027f6332a4e2f95a4a164d0011f1a61a24e67d331', 'Katsaris runs at nearly the same level through 49 seconds. Barenboim runs 8 seconds longer, starts softly, and builds toward the end.'),
('sector_featured_pairs', 185, 'title_en', 'e182e92cf89cdee2f1910f89124cf47cc7a37b9b94bdac4b19ba165195553996', 'Münchinger''s Late Peak, Zinman''s Early Peak'),
('sector_featured_pairs', 185, 'note_en', '4603d9a7f99af3acd9c6f886984a82a0b9c311d1e6d8a7c453ee1aa3dfa6b794', 'Zinman reaches the peak 26 seconds in and sustains loud playing the longest. Münchinger runs 16 seconds longer and puts the climax toward the back.'),
('sector_featured_pairs', 186, 'title_en', 'a8f0ea519a9731beb4a8743aebf1c0fc7494fefa8788330b892331d395dc4335', 'Maximum in the Middle, Only at the Last Chord'),
('sector_featured_pairs', 186, 'note_en', '36528500d2905e6eeefc3cb301a7ccd3dbeab6f1ce2ac7d78da2cc1ae01348a9', 'Schneider reaches nearly the maximum already in the middle and sustains it for a long time. Willens does not get near the maximum until the last chord and stays even.'),
('sector_featured_pairs', 189, 'title_en', '17a5fcc9c14628db0d11c3b166ed35e3e7235f0a24ba11f7bf73fdc68ce3456b', 'Opening Loud, Opening Soft'),
('sector_featured_pairs', 189, 'note_en', '36c3e2cd0bbc6d7d9a52159ab73a8296759e6532c02c97edce9862d495b1ea02', 'Kasarova is 40 seconds longer. Von Stade starts loudly and becomes loudest near the end, while Kasarova opens softly and becomes loudest in the exact middle.'),
('sector_featured_pairs', 191, 'title_en', 'f2b5f88db67eebc920c806b8235be19748910318d588cffd6744038a21fd9e77', 'Holding Back to the Close, Big from the Start'),
('sector_featured_pairs', 191, 'note_en', '582f17fc2291238d09e8999b75d32071161a933d29dba8fe4f464f0bf3761c52', 'Abbado holds the level back throughout the main body and rings out loudest on the closing chord. Bernstein is already loudest in the early part and sustains loud playing the longest.'),
('sector_featured_pairs', 192, 'title_en', '98c4e6fb7d62743a098e583d2d3174217664f710bc386ce39103d7c25249ec49', 'Davis Opens Softly, Ozawa Opens Loud'),
('sector_featured_pairs', 192, 'note_en', '6f4dcebbbf34ef5fbe78dcb74563bc0bc0340e321e694d737865576379f5f134', 'Davis plays the first timpani at the softest level and has the widest gap in level. Ozawa starts less softly and sustains loud playing the longest.'),
('sector_featured_pairs', 193, 'title_en', 'e1714be5825db6007fde488f7f7b4fe96b76e3d9ba59f37d5dab8bc7637daab0', 'Even Brunner, Meyer Building Toward the End'),
('sector_featured_pairs', 193, 'note_en', '0fc360c6c7f90fc396f3d03df5255e1444fef7417ad44b8baf6395409fd19bb1', 'Brunner keeps the level even and puts the loudest sound in the early part. Meyer builds up again after a quiet spot and rings out loudest toward the end.'),
('sector_featured_pairs', 194, 'title_en', '17d0142965a8827277103964cbe37da590fe1264131b2873abf8bc05b7a42bcd', 'Christ Sustains, Malý Sinks'),
('sector_featured_pairs', 194, 'note_en', 'f58ce0f16361f713a2420531c48fb9e1354bd6e4f807cfcc823a33c4b64f7bf8', 'Both are loudest at the first tutti. Christ rises to that level twice more later, while Malý sinks the middle deeply.'),
('sector_featured_pairs', 195, 'title_en', '0868bea5a0291c647d8989137eb9b46987cd438128a2ba9df5e3961ed1a518d0', 'Rattle at the Crescendo Peak, Karajan at the Very End'),
('sector_featured_pairs', 195, 'note_en', '3dbf1e0036e08d88f2620e771211b1d0adb338f5924ed8d6e4f0f7ebc9176c36', 'Karajan is 36 seconds shorter. Rattle is loudest at the top of the crescendo, while Karajan sinks deeper and is loudest at the very end.'),
('sector_featured_pairs', 196, 'title_en', 'e138ac0bf10eddf3a23a563baf638c54fcbc2a3cd82704fcf74aa60a803b39e6', 'Vishnevskaya in the Second Verse, Sukmanova in the First'),
('sector_featured_pairs', 196, 'note_en', '401b2b65a8e24804672e2f10d92d7eb9b34eac3146eab092f8feca082187e653', 'Vishnevskaya sings loudest in the second verse and closes very softly. Sukmanova is loudest in the first verse and sings the second nearly as loudly.'),
('sector_featured_pairs', 197, 'title_en', '3d9dd58d119f3a31f0acdcfa9e1ff7d7a1498f515d50548d3e236b8bd72b63c5', 'Bernstein Rises Early, Dutoit at the End'),
('sector_featured_pairs', 197, 'note_en', 'f168eea8e0a7e5dfa5731b0623f6cb44bfad21b61795ccf1e7fccc96089b1596', 'Bernstein reaches nearly the maximum over 2 minutes earlier than Dutoit. Dutoit rings out loudest only a few seconds before the end, and the whole performance is 54 seconds longer.'),
('sector_featured_pairs', 198, 'title_en', '6e7e2ca1adb5fc8c43a16970da2b1777a4715d4f503420d7360b6f2b5aefeb5b', 'Karajan Builds, Gergiev Sinks'),
('sector_featured_pairs', 198, 'note_en', '6a7e528f486bfc529cc02045cca3ca5c75ef4303af7c77e1af8b7fab3b88b0f5', 'Both open the Sultan''s theme at their loudest. Karajan builds steadily after the middle, while Gergiev sinks the middle to the lowest level and raises it late.'),
('sector_featured_pairs', 199, 'title_en', 'b0fa3b3ba58aa831faaf9498290b173e46d358baf225b5d7e3592a196d78bf76', 'Davis Rises in the Middle, Muti Holds Back'),
('sector_featured_pairs', 199, 'note_en', '611fe52e2c5130d23e2988ecdbbb3c172d0833d9387432e7de26803b3c7b8cf7', 'At the same spot Davis rises to nearly the maximum and Muti stops just below it. Muti gets nearly to the maximum only just before the last chord.'),
('sector_featured_pairs', 200, 'title_en', 'f4c7f102e39e15c1920ad091a34691d72a03021e6a94a14e0ea4cffbec1f1e29', 'Reiner Strikes at Once, Maazel Holds Back'),
('sector_featured_pairs', 200, 'note_en', '76a0dd53986bbafb980144fc53c875cc73625f8da924b775873f85cf24705a95', 'Reiner strikes at nearly the maximum from the first sound and plays the dawn less softly. Maazel holds back for about 2 minutes before raising the level, and sinks the dawn very softly.'),
('sector_featured_pairs', 202, 'title_en', '2836c0985a1a3d40286a58e3809801f2855e5de6e632f5c40bf51088f8d2abb0', 'Karajan Sustains, Jansons Cuts Short'),
('sector_featured_pairs', 202, 'note_en', '53f8740cf29bb1a6b3b7fc2f90033bec414aa35f40b0a7edba705aea39fea188', 'Karajan gets nearly to the maximum early and carries on to the climax for a long time. Jansons gets nearly to the maximum only just before the climax.'),
('sector_featured_pairs', 203, 'title_en', '2689d301299d88307111ab79e1188e095c8a122735a7bdc5f402799c3bf7db4a', 'A Climax Within 30 Seconds, a Climax in the Exact Middle'),
('sector_featured_pairs', 203, 'note_en', 'fe460a34ed7e1547309f1a1d952e994556faf8af3ff171ba0b4bf1e5925e5856', 'The Takács Quartet reaches the climax within 30 seconds and sustains loud playing the longest. The Alban Berg Quartett opens at the softest level and reaches the climax only in the exact middle.'),
('sector_featured_pairs', 204, 'title_en', 'daf0b02e178c0dfebfb3be6a84f7fc553a95b384b0ee08c4a40f98965787e438', 'Deep-Sinking Solti, Short Karajan'),
('sector_featured_pairs', 204, 'note_en', 'f129b65b7df47f9388950f5c40c167ae0988a9838d582b50e0a25d1f12166a67', 'Solti stretches the passage after the chords out at the softest level. Karajan is 17 seconds shorter and passes through with quiet spots that sink less.'),
('sector_featured_pairs', 205, 'title_en', '535b296f7ee1c16e22c030c95b2e114e060b4fab228e1e401a17d0d0e5e6a6e8', 'Same Piece, 24 Seconds Apart'),
('sector_featured_pairs', 205, 'note_en', '83e31f2017d2ce355252a65e41b51b8270d783f06b5e96fc1badf495e710e7d1', 'Firkušný is 24 seconds shorter. Lympany keeps a similar, even level, while Firkušný sets the beginning and end softly and rises loudly once in the middle.'),
('sector_featured_pairs', 206, 'title_en', 'a5ae9b1bd65ecf3ba3e892ea2ad0aa18486695caab311e97e65c5aa1da7f57c6', 'Same Crescendo, Different Start'),
('sector_featured_pairs', 206, 'note_en', '10d60431c109f13bb83c2d7d2bf7534bd80af95bdc0561a43cf09e89cc615d13', 'Böhm starts getting louder earlier than the other two and builds for about 20 seconds. Chailly starts latest and rises in one go within about 15 seconds.'),
('sector_featured_pairs', 208, 'title_en', '05fb9052aab238efc5e271bfe5b871968295c9290a781b1aa1c4c6cf91db671f', 'Polyphony at the Front, Monteverdi at the Back'),
('sector_featured_pairs', 208, 'note_en', '90259c84541c1ce5202730e657f7bf4a6f407440711fefd5febbf926abbe27bf', 'Polyphony sings loudest in the early part and soon sinks. The Monteverdi Choir runs 25 seconds longer, lowers the middle to the smallest level, and is loudest toward the back.'),
('sector_featured_pairs', 209, 'title_en', '25a32b8d66e910088a73b88306f4d5f129d300562039599093533f5e13efe800', 'Tilson Thomas Stretches, Ozawa Cuts Short'),
('sector_featured_pairs', 209, 'note_en', 'c166663189b751e587f297300e888aa67e184df5763377ce966190814a540053', 'Tilson Thomas holds nearly the maximum for almost 20 seconds before reaching the climax. Ozawa strikes the climax in one go and soon sets it down.'),
('sector_featured_pairs', 210, 'title_en', '7e2edfa999d1709aeb1d7e14e633cd222a470cca82b0aa1954b49802231304df', 'Abbado Surges Late, Solti Builds Early'),
('sector_featured_pairs', 210, 'note_en', '54904caddbc83d1d2d10befa19610711fdebd91a6b7243c159ed578072a951e6', 'Abbado sinks the middle deepest and surges in the last 20 seconds or so. Solti pushes the opening loudest and also starts building again earliest.'),
('sector_featured_pairs', 211, 'title_en', '40bd77ca9fee862f586aed3eb4bb3ec2b76b4336d716f10fa26e8bce5d8a481f', 'Tilson Thomas Rises Early, Haitink Holds Back'),
('sector_featured_pairs', 211, 'note_en', 'd0ff84cf56678854823990bbbc7ebe279b1a7159a56945f4e575a7446d8351ec', 'Tilson Thomas reaches nearly the maximum in 36 seconds and sustains it for a long time. Haitink opens on the softest pedal tone, holds back for over a minute, then rises.'),
('sector_featured_pairs', 212, 'title_en', '1ef7958abd6414c5c42f5bec7f914fee59baef529ef0ec7f671b2245bbfebd19', 'Loud at Once, Held Back Over 30 Seconds'),
('sector_featured_pairs', 212, 'note_en', '089a9730eed1616da4698fbab4c312c0b78adf73dcb7376e40dde04ae87a37e7', 'Dudamel enters at nearly the maximum on the first outcry and pushes evenly to the end. Abbado opens a step lower and reaches the maximum only after more than 30 seconds.'),
('sector_featured_pairs', 213, 'title_en', '00728abddb018f6c9c3edab6fd36b8fd1ff6f8a1b89f8e5a0e1762c17b6d87b6', 'Maximum at the Opening, Maximum at the End'),
('sector_featured_pairs', 213, 'note_en', '90436964164f7e00ee423253f9f89a6681211b2b6e954fa8e689479cb1ae395b', 'Solti blasts loudest at the horn signal, while Bernstein blasts loudest in the last few seconds. Both lower the middle a step in between.'),
('sector_featured_pairs', 215, 'title_en', 'af065b8554f842e4692e23223bf7c840e0da0d30984e6266337329da8a8bf4e4', 'Maazel Up Front, Karajan at the Back'),
('sector_featured_pairs', 215, 'note_en', '8576d6e613e0d3221ab8d90839a136f4972a9cae00005a65e890033eb937db4f', 'Maazel strikes the climax in the first big passage of the introduction and doesn''t raise it as much later. Karajan opens at the softest level and reaches the climax in the later big passage.'),
('sector_featured_pairs', 216, 'title_en', '2d561710167ea646b6a2c2cb2486807970fc528b56c12aed71039071f0e038f5', 'Very Soft Capuçon, Clear Mutter'),
('sector_featured_pairs', 216, 'note_en', 'e200d85f8cd84527e076bbfd3bedd1cdaa73f55266a51a57558f927dc18fa1f0', 'Capuçon keeps the opening very soft and runs about 10 seconds longer than Mutter. Mutter plays loudly from the first note and carries that strength to the end.'),
('sector_featured_pairs', 218, 'title_en', '29050f2054a2b40ff9b99d504827c6f0335312faf31eb19084cc9c64df05e929', 'Barenboim at the Back, Dutoit Up Front'),
('sector_featured_pairs', 218, 'note_en', 'e46085cc06d09a406ec5be3bba658f8854ebd55918a6edbfab47aeaba22e57ff', 'Dutoit sings loudest within a minute and gets nearly to the maximum twice more afterward. Barenboim keeps the early part soft and sings loudest in the later part.'),
('sector_featured_pairs', 219, 'title_en', '9c4c62541b51ef060d0bbcb77658ac48f83fe95b3cf4592426d9db2a9fbbd47d', 'Short Devieilhe, Long Fleming'),
('sector_featured_pairs', 219, 'note_en', '4cef306f998e447b318788b9c3b613217cae84c7004210265f8c69f851be8d86', 'Devieilhe sings it in 2:40 and goes to nearly the maximum from the first line. Fleming stretches it 40 seconds longer and sings loudest only after the middle.'),
('sector_featured_pairs', 220, 'title_en', 'd11d4150221f2ab317b35f42bfc36e916adca63b7862ebe83452947fe70f71c5', 'Ormandy Doesn''t Reduce, Marriner Sinks'),
('sector_featured_pairs', 220, 'note_en', '1d32a5b2fcac007b480529edbf339bc1fd14f661399586d754e3170fff15e689', 'Ormandy is 49 seconds longer. Ormandy carries on through the middle without reducing, while Marriner sinks to the smallest level within a big passage and raises it again.'),
('sector_featured_pairs', 221, 'title_en', '19643fc691d9fbcc4572449d07c8996c51d818f6b7c04268b9532c9a0ce451e9', 'Climax Up Front, Climax in the Middle'),
('sector_featured_pairs', 221, 'note_en', '30a730d113f599538a3baaeadb74d61d1d60e0db5e226311687200e31484718a', 'Isserlis sings loudest within the first melody. Yo-Yo Ma flows through about 15 seconds shorter and puts the loudest singing at the end of the middle section.'),
('sector_featured_pairs', 222, 'title_en', 'b9f18499a1c93cf1b892bcb91c807b1ab3f64801bccebf53f4fa018f15704596', 'Even Pressler, Orkis Lowering the Back'),
('sector_featured_pairs', 222, 'note_en', 'c84d9d7e75001598c73603b81593a58d5b64826037961bf505750987b76ac68a', 'Pressler keeps the level even after the climax and reaches the maximum again near the end. Orkis comes down a step after the climax and plays the back part lowest.'),
('sector_featured_pairs', 223, 'title_en', 'd6b471d82d640d6348048f4de26e12213d2f1a90013425c3a160a0a8872a0c0e', 'Climax Early, Climax Late'),
('sector_featured_pairs', 223, 'note_en', '08c222e704bb5b9ac37df871532ec5f5aba1801f40e1959a910602ca8527e741', 'Bernstein is about 10 seconds shorter than the other two and puts the climax in the early part. Dutoit plays loudest in the later part and sets the ending down very softly.'),
('sector_featured_pairs', 224, 'title_en', '34d423086b7db2c457c156cabbef9d712b76840bfeb37ce4f0dde50831cbf600', 'An Early Peak and a Late Peak'),
('sector_featured_pairs', 224, 'note_en', '560d2e636dbc3a7f3c3d255610672a6f681239fab68c8f2af18ec4a3d0a929ad', 'Shelley rises to the loudest level right at the opening and sustains loud playing for a long time. Kanneh-Mason puts the loudest sound just before a deep sinking.'),
('sector_featured_pairs', 225, 'title_en', '29af7d60d5fa7a6d6da9311d2dbafbbff199498eb305b5e7abcff2ad5d5487f1', 'Same Back Half, Different Depth'),
('sector_featured_pairs', 225, 'note_en', '04bd4bdc968c51b69122efefec20c8d3afb83fed9fef978a0cca3224bb0ab600', 'In the same quiet passage in the back part, Kang doesn''t reduce the level much. Janssen sinks very deeply there and then rises again.'),
('sector_featured_pairs', 226, 'title_en', '841e91b22af53ca4264db97b1043cabbd684f6c6d21fbfbf2b92f19d20832386', 'From the First Chord, Only After a Minute'),
('sector_featured_pairs', 226, 'note_en', '61d62e60c1d0403d352fa0c22793cf3a3317ca6c23e221fedcb0e5cde10e3c93', 'Midori sounds the first chord loudest. Perlman first gets near the maximum only in the surging passage around the one-minute mark, then drops the deepest afterward.'),
('sector_featured_pairs', 227, 'title_en', '1a87935322bd579b993fdd11933785b4f07dc94bea0e778195359f05f9d69b80', 'How Deep It Comes Down After the Peak'),
('sector_featured_pairs', 227, 'note_en', '4706aad4bdfad834c0e3814d48ea9cda8aa9d6a2688e3287f4a39d2726e28ca8', 'Both sink the middle deeply and rise loudly. Accardo comes down sharply soon after the peak, while Baráti doesn''t come down as far.'),
('sector_featured_pairs', 228, 'title_en', '333d59ea17a8f1426d9be49de8c8dd65fbfb4b4b91d38ee83bd3e183bd9fc645', 'The Depth of the Middle Differs'),
('sector_featured_pairs', 228, 'note_en', '74a0d0bfea191fcb05eaaeb1df525f502067f561d63a8a1dd90d9ecdc58bda5d', 'Thibaudet sinks the middle only slightly and rolls along evenly. Cho runs 25 seconds longer and sinks the middle deepest and longest.'),
('sector_featured_pairs', 229, 'title_en', 'b5bb909fa294f55a35940123a3b26a54118c0a402bd8544bb5535504b2e950d7', 'Karajan Stretches, Dutoit Soars Early'),
('sector_featured_pairs', 229, 'note_en', '6ee8a675e8964492896ca6ac250e1d04b15dc3a0d5d275f0c7a82720d305e4ec', 'Karajan takes 2 minutes, staying soft for over a minute before soaring. Dutoit passes through in 1:37 and starts getting louder about 10 seconds earlier.'),
('sector_featured_pairs', 230, 'title_en', '769521527c2ba89b72b35d07ddcf3bd8489892327a739d6a787772de519dc4a5', 'Shallow Haitink, Deep Abbado'),
('sector_featured_pairs', 230, 'note_en', '7eab29fd3c38b805326d100d4eb68c014a7985d65ec8fca0e54a3b45aa01d423', 'Abbado is 15 seconds shorter. Haitink sinks the early part the shallowest, while Abbado sinks the deepest and keeps things soft until the middle.'),
('sector_featured_pairs', 231, 'title_en', '566fb9ef61ac96f6017cf9c4db4496b5fe2da1d704839870ebf96149f4ec7f64', 'Deep Shelley, Even Lisiecki'),
('sector_featured_pairs', 231, 'note_en', 'a67e28d0b0e8e0acf2e900fc4c024759ddb3d3312656d19f198f8c4aba994d42', 'Shelley sinks the middle song the deepest and becomes loudest at the returning march. Lisiecki carries the middle on loudly too.'),
('sector_featured_pairs', 232, 'title_en', '2fb4360b0c72f73a6f927731b8112c25be1a71ec76538bf614a7c9cefd7fe157', 'Yuja Wang Stretches the Middle, Lang Lang Ends Early'),
('sector_featured_pairs', 232, 'note_en', '07887ba0e06e1394c0d985ca238f5c24ceb4a2708147c29c272e9c0f22059e17', 'Yuja Wang comes down only slightly even before the climax and carries the middle on loudly. Lang Lang reaches the climax 18 seconds earlier and closes the ending at the softest level.'),
('sector_featured_pairs', 233, 'title_en', 'd04080c81d6c43ccbe04cf6b815c8007fe2c944ff1556473bfea8e4a53940d4d', 'Rogé Sustains, Argerich Sinks'),
('sector_featured_pairs', 233, 'note_en', '72fa624c4f825b0716cbc5054194728c6006d6091eaa78464fb15bf4a6595052', 'Rogé sustains loud playing for a long time and sinks the later part less. Argerich sinks the relaxed passage to the smallest level.'),
('sector_featured_pairs', 234, 'title_en', '26254f0458ba35088b95968112afe7cc7ab9c7a7a77cb42d064f8949e9e15025', 'The Last 5 Seconds and the Exact Middle'),
('sector_featured_pairs', 234, 'note_en', 'e9d3c124068b7f454b89e53511bb69771f4ab1fb7c45c231b50f84f6cb392c0c', 'Abbado reaches nearly the maximum in the exact middle and sustains it to the end. Solti holds back until 5 seconds from the end, then rises in one go.'),
('sector_featured_pairs', 235, 'title_en', 'e8596710167608ecb3823e0b61b2030a8ac46b265bc23129240442487fd8e190', 'Soft Thibaudet, Even Liu'),
('sector_featured_pairs', 235, 'note_en', 'bb7cda3e6f61cb8127b5b277168051df66224ff8503a3f1c5fd86e5e6fec5970', 'Thibaudet brings out the first melody very softly and builds it up big. Liu brings out the first melody loudly and flows most evenly.'),
('sector_featured_pairs', 236, 'title_en', '462ee5bea32f11dbda8113dc22b5105db09aa393a9c214bc7047b6489c0f46a1', 'Deep Muti, Shallow Levine'),
('sector_featured_pairs', 236, 'note_en', '3e0e0214428510e03592c4decd365bb071d8f993aba758fccb158e99cb50d109', 'Both are loudest at the end of the last verse. Muti sinks deeply each time a verse begins anew, while Levine comes down only a little.'),
('sector_featured_pairs', 237, 'title_en', '1eb89b16e32460726c89aeec0329bdfcf0f2cabd2cf75da74fa7454015e4d94c', 'Rogé at 5 Minutes, Ciccolini at 6'),
('sector_featured_pairs', 237, 'note_en', 'd5236c0ec2e1f3202ab71c0b358e696e1e65064435d28aaaf52a6964b61f813d', 'Ciccolini is a minute longer. Rogé opens at the softest level and builds big, while Ciccolini keeps the most even level of the three.'),
('sector_featured_pairs', 238, 'title_en', '7dcb47794db6a7922b5e911c09f115fdbc1836085f9e1ab5969a082dbef3fb78', 'Muti at the First Cry, Levine at the Last'),
('sector_featured_pairs', 238, 'note_en', '3c2c469712878510b64a1a223e03dc818c692381597e68885a2fedbdd827d4f2', 'Muti is loudest at the first outcry and sinks deeply right after. Levine builds toward the end and rings out loudest at the last outcry.'),
('sector_featured_pairs', 240, 'title_en', '0b5e8363dabbb1521af980bc3bf6b6273cc27402f77ac9415d4bf64b5718c437', 'Climax After the Pause, Climax Before the Pause'),
('sector_featured_pairs', 240, 'note_en', '4674aa2754133d2ba1628c5625f970b922379ffdedd985ec00d546cef2a31bae', 'Kyung Wha Chung makes a deep pause in the middle, builds again, and plays loudest at the end. Accardo plays loudest just before the pause and sinks to the deepest level at once.'),
('sector_featured_pairs', 242, 'title_en', '899d9fffc4b84565f91a876d4b009d20c78b6f3951f00dcb0f157d9f0d24da94', 'Even Aimard, Deep-Sinking Denk'),
('sector_featured_pairs', 242, 'note_en', 'a43fd652fe98bd87d0fe2ab6fa7c97e4de416f48934dc19403b70059cfd0a4bc', 'Aimard carries the beginning and end evenly and is loudest in the middle. Denk rises to the loudest level in 9 seconds, then sinks the middle deepest.'),
('sector_featured_pairs', 243, 'title_en', '4248b373887f801f2e96696f7841859543a9bed228d311e77afa9ebc39cee538', '2:52 and 3:31'),
('sector_featured_pairs', 243, 'note_en', '5aae1a57b9e9e6e39264c45a3801d72a0e14da42a13f0445436b7e7fc484f424', 'Ozawa passes through the same passage in 2:52, Tilson Thomas in 3:31. Ozawa starts getting louder early, while Tilson Thomas rises in two stages.'),
('sector_featured_pairs', 245, 'title_en', 'ebab560d5ca4f7a3f2198443f5a6992132283b7f5e568ed5742056c47ec945d3', 'Short Jansons, Long Noseda'),
('sector_featured_pairs', 245, 'note_en', '988935854c5e8dc0c27e03078bbd2f82867d0109b647ce1b12aabdd4bfbf2c0c', 'Noseda is 35 seconds longer. Noseda holds the quiet passage the softest and for the longest, while Jansons passes through it quickly and rises.'),
('sector_featured_pairs', 246, 'title_en', '0ad7b365f78adb9754338017f7dc47d509503691cf54f58d3b3168dc1c009b09', 'Maximum at the End, Maximum at the Start'),
('sector_featured_pairs', 246, 'note_en', 'e9de402e1635c8f0ca751b1de28b3564ba2b702f9c91fc6f4b21120b1b0790fa', 'Ormandy rings out loudest at the first tutti, while Previn rises to the loudest level at the last tutti, where everything gathers again.'),
('sector_featured_pairs', 247, 'title_en', '5af651337858edc3656e74a34ad00618b615e6cd70ecafc0320cc15043b741b2', 'Peak Up Front, Peak at the End'),
('sector_featured_pairs', 247, 'note_en', '5765757db5dbffc203234e6926857d72e7e6984acf5484722ba8d79130953317', 'Mørk puts the loudest sound in the early part, Gerhardt at the end. Gerhardt presses the moment just before it down very small to heighten the contrast.'),
('sector_featured_pairs', 248, 'title_en', 'b774fb1d131d0d3623b4a5fc072f05af74414d4b19618f6d26497672fb4d4182', 'Early-Reaching LaSalle, Deep-Sinking Emerson'),
('sector_featured_pairs', 248, 'note_en', '29b8ba7f7286f8f98bce0ea5c379939f18fbb611974915fd0000570f57a75ece', 'The LaSalle Quartet reaches nearly the maximum within 30 seconds and reduces the middle less than the Emerson Quartet. The Emerson runs about 10 seconds longer and sinks the middle to the smallest level.'),
('sector_featured_pairs', 249, 'title_en', '584c111b28387e134a724741f7f5e36e43a581801e2d33b9b54c37934ccffdee', 'Perlman in the Middle, Capuçon at the Very End'),
('sector_featured_pairs', 249, 'note_en', '9dff1fddbb6c276ac69d96b3ac2d1c3674e2d561849fb27bec50854fa1133744', 'Perlman rises to the loudest level in the middle, then sinks deeply. Capuçon builds little by little and rises loudest at the very end.'),
('sector_featured_pairs', 250, 'title_en', 'f63f11c004e87d71581a3f29d1477c139b055c0e0622a3d6074a557d385f8ea5', 'Tilson Thomas Sustains, Masur Strikes Briefly'),
('sector_featured_pairs', 250, 'note_en', '06e85cadb6d128459d67610195c736b56abafd751128e11c236e6cd857f0b2e7', 'Tilson Thomas reaches nearly the maximum twice in the big passage and sustains it for a long time. Masur strikes the top once, briefly, then comes down to a very soft level.'),
('sector_featured_pairs', 251, 'title_en', '69a3afe52c4f6b79f5e64c2a7fae901bff714cad355e8229754ec5803c673743', 'Emerson Opens the Gap, Italiano Stays Narrow'),
('sector_featured_pairs', 251, 'note_en', '24ed650c6c746e9a6426275f38a6b60ce598c3d217a303005b1963ecd2b2625d', 'The Quartetto Italiano runs 23 seconds longer and keeps the whispers less small. The Emerson Quartet strikes the first gesture hard, then drops straight to the smallest level.'),
('sector_featured_pairs', 252, 'title_en', 'dc41daba810439fa90fd66ed9e6d51d268f1d727e345c6df8a1eff11d0cfde99', 'Boulez Ends Softly, Karajan Sustains'),
('sector_featured_pairs', 252, 'note_en', '9520cb5f76bfb9341227b3c2a266a1495d52272e3113b259a9064df7c241e346', 'Boulez keeps the loud passages short and sets the ending down the softest. Karajan sustains loud playing the longest and closes less softly.'),
('sector_featured_pairs', 253, 'title_en', '55fefd1e8cf6509dd4a47717af2d85667ae589f9fe255baed4e2c923f0a2ff13', 'Loriod Big from the Start, Thibaudet Holds Back'),
('sector_featured_pairs', 253, 'note_en', 'e7028a5b1e20e443379a41e3574154c6fd74dac08f9026c97e57306854196b49', 'Loriod opens at nearly the maximum from the very beginning and sustains loud playing the longest. Thibaudet reaches that level for the first time only a few seconds before the end.'),
('sector_featured_pairs', 255, 'title_en', '172046bf7507918681736505da5f5e0ba1802bca4a8b97e35f6c184ffd99e018', 'Even Fröst, Shaham Opening Softly'),
('sector_featured_pairs', 255, 'note_en', 'ea4ec01c9018521af5bcbf1628bb27d9b860d97aee6c8c71e8f262220a29274f', 'Fröst enters loudly from the first sound and stays even to the end. Shaham opens very softly and raises the level little by little toward the end.'),
('sector_featured_pairs', 256, 'title_en', 'd3e373e5a774f5b6ebad5b4f4ee112b4c8a58533e59764f486408e5a5d96fbb4', 'Rozhdestvensky Sinks, Ormandy Sustains'),
('sector_featured_pairs', 256, 'note_en', 'd5196f82e81d3378c1c4fcac9ffe83bfd599d5b4e8f7de31b91fbc5b3a2432f5', 'In the middle song, Rozhdestvensky sinks the level the deepest, while Ormandy lowers it only slightly.'),
('sector_featured_pairs', 257, 'title_en', '572c50e751c75d1452e94361e5883d566feeda142ff82cedf169365bc4c8c2d2', 'Ricci at the First Tutti, Mordkovitch Rising Later'),
('sector_featured_pairs', 257, 'note_en', '89199f5b7e498d5cc8ce553169b79fde4563fbd29df3757e15447946c6e4f33f', 'Ricci is loudest at the first tutti. Mordkovitch sinks deeply after the first tutti, builds again, and rises to the loudest level.'),
('sector_featured_pairs', 258, 'title_en', '49ca965306e7c8c44c554ee2095674ae036e0ade97e52bd91ddec18bb8741279', 'Järvi Sets Down, Black Pushes to the End'),
('sector_featured_pairs', 258, 'note_en', 'acfbf1d240eb1495408ec9c0f5263f5e47b40b88d8fcef1e11a59bbccd3110b2', 'Järvi plays loudest in the last big passage, then sets the ending down. Black pushes to the end and plays the final chord loudest.'),
('sector_featured_pairs', 259, 'title_en', '634db52228bf4fbd4d9122b12e20c449fc83a7ca22b1ca48b87aa6f7124462e9', 'Cello Loud at Once, Trumpet Builds Up'),
('sector_featured_pairs', 259, 'note_en', 'd744afa144d5e56e71b755f627dbb81f9c0a1b100383eb300fd8acfeb7c1aad7', 'The cello version enters loudly from the start and barely changes the level over its 3 minutes. The trumpet version opens softly and builds for over 4 minutes.'),
('sector_featured_pairs', 260, 'title_en', '40461d3a2eed246a48adee43f3e77a439b60805af1bf90736a0bf43f0a0bec81', 'Cello and Piano, Violin and String Orchestra'),
('sector_featured_pairs', 260, 'note_en', 'eebf3f178284bad7583fdf01ebec597ee824b549d39ee6444dd1ff27fde08fb1', 'The cello version rises early, steps back once, and rises again. The violin version runs about a minute longer and reaches nearly the maximum only once, late.'),
('sector_featured_pairs', 261, 'title_en', 'fc4e9b50b03355b55ed3d18e1b4655a1089657290def6699a5247bed012573ca', 'One Guitar, Quartet and Orchestra'),
('sector_featured_pairs', 261, 'note_en', '1a2c112d90add9778e2d99617cfa9eed1479cb7796d9063a100ea74b6aeb69a1', 'The guitar plays the piece in 4:41, the quartet-and-orchestra version in 7:07. The orchestral version sustains loud playing for a long time, while the guitar keeps an even level.'),
('sector_featured_pairs', 262, 'title_en', 'b81a48ff0cba09d6b77dc50b3edc6d1ba43c492f0176e704db301ad628468e12', 'Long Domingo, Early-Rising Carreras'),
('sector_featured_pairs', 262, 'note_en', '6deb9fa816a1c74ae8fed7326df1bb1ba56efe3f31f59c3571fbc385f11e7476', 'Domingo sings 47 seconds longer and reaches nearly the maximum only 40 seconds before the end. Carreras gets there about a minute and a half earlier.'),
('sector_featured_pairs', 263, 'title_en', 'a0e5c93926a832a19fbe9576006e49d41da9cbf41a1b7910a0ad5c1f8d3e4d3f', 'Tiempo at the Front, Steinbacher at the End'),
('sector_featured_pairs', 263, 'note_en', '44beb86f6d6d7a53aa14a0762a00996df5fe3071cf3b92691ee06044572cf2f6', 'The two-piano version peaks about a quarter of the way in, the violin version near the end. The lengths also differ by about two and a half minutes.'),
('sector_featured_pairs', 264, 'title_en', '1368991c4c4094647a59248927dbd587d7682de0786ced8fcb50e6df2953cd6f', 'One Voice, a Whole Orchestra'),
('sector_featured_pairs', 264, 'note_en', 'c12df22872a14e0d2f877f394234912f9c35ebdcbbcba7e4716e6c6b20871f79', 'The voice sings the same melody in under 5 minutes, the orchestra takes 7. The voice diminishes with every breath, while the orchestra swings widely each time the instruments change.'),
('sector_featured_pairs', 268, 'title_en', '3152a515030f4627cf06445b684ee8d5f6fb953c2c35f9704927588cf834d1bf', 'Peak in the Middle, Peak Only at the End'),
('sector_featured_pairs', 268, 'note_en', 'aecf0f8ee6ef6ddfd4227925e993950e8790a6105f81f3e1f5d6a77eed23ded5', 'Gheorghiu sings at nearly the maximum as soon as the quiet middle passage ends. Gruberová holds that level back until 16 seconds before the end.'),
('sector_featured_pairs', 269, 'title_en', '3bb1bcf06ec4191ed80ec2f39429113158bc819ef7322d0f447fc6c6c3584aea', 'Chailly Surges at the End, Chung Builds Long'),
('sector_featured_pairs', 269, 'note_en', '0652d984f2becbd912cb13e607a19d3fb4c9b4aa77a88827bb6c0e4e7fbf97c1', 'Chung is 17 seconds longer. Chailly keeps the middle low and raises it loudly over the last 30 seconds; Chung builds to a big sound and goes up one more step at the end.'),
('sector_featured_pairs', 270, 'title_en', 'acafe02aefaf53fd71ecfd5be050219865eb1f674366a18762557092eeebb063', 'Zimerman Builds Long, Trifonov Pushes to the End'),
('sector_featured_pairs', 270, 'note_en', 'e57e03a0dccc4e0e1eea1ec4536ed5540636a690e390021cc729b5dd05b77717', 'From a very soft first chord, Zimerman builds the bell sound for over 30 seconds. Trifonov starts less softly, moves on to the theme early, and carries on loudly to the end.'),
('sector_featured_pairs', 273, 'title_en', 'c104a04cf6ccfccad6c2281bbf9068bc6d8ae9d96a2fe58ad0d1a5e15d9000e1', 'Perahia Connects Quickly, Zimerman Sinks Deep'),
('sector_featured_pairs', 273, 'note_en', 'cf77d8ac03f7eb420d5e17a3cfa3b2a45155ed459b692b7878eae35aa7b97d3b', 'Perahia is 10 seconds shorter. Perahia keeps the quiet passages shallow and carries the hymn on, while Zimerman sinks much deeper.'),
('sector_featured_pairs', 274, 'title_en', 'a7413db7e2381c54d79c80d58f9645f96ef58c245f42de2e41bc455db9364140', 'Solti Loud at First Fortissimo, Karajan at Second Theme'),
('sector_featured_pairs', 274, 'note_en', 'ca2ae9e46d8d1907aa4939b09199ac0b484b5b04f45b5d1f54bef584519a341a', 'Solti blasts out loudest at the first fortissimo at the end of the fugato. Karajan holds that passage back and rises loudest at the second theme.'),
('sector_featured_pairs', 276, 'title_en', '3fbd988763f9a27fdefa5b236c5767248288fd9927240daec5d718398b895f4b', 'Relaxed Fabbricini, Short Cotrubaș'),
('sector_featured_pairs', 276, 'note_en', '65bd8bfbccabf1f94c61a62ec30d5b0ce306e970bc313336556a262ef5774476', 'The same scene takes Fabbricini 2:40 and Cotrubaș 2:06. Fabbricini presses the early dialogue down softly, while Cotrubaș rises loudly once in the middle of the dialogue.'),
('sector_featured_pairs', 278, 'title_en', '88449df374f79ba3eef71c61bda14324514158e44ed22120920ead6976c6954a', 'Solti Holds to the End, Haitink Steps Down'),
('sector_featured_pairs', 278, 'note_en', '7399502c9ef5a87dcc8580d8d7ad9cc27cf8aaa9366769071310e34b1d42ca20', 'Solti keeps the level of the first sound to the end and rises to that level again in the last big passage. Haitink steps down a level after the first sound and carries on beneath it.'),
('sector_featured_pairs', 282, 'title_en', 'dadfae63028154c46f96540966a8ce060c61ada73d2ad5f9fc2dbc7092ba7f2d', 'Karajan Lowers Deep, Solti Lowers Less'),
('sector_featured_pairs', 282, 'note_en', 'c85665c21e77ea35df2c702e5a6b7a7f255a22695a8f8207809efeef480e013d', 'Karajan lowers the opening and the passage leading into the recapitulation to a very soft level. Solti lowers the quiet passages less and plays the loudest sound in the exposition.'),
('sector_featured_pairs', 283, 'title_en', 'b202d7d5cf17e44f34ad023dd1d6a5c56022bb6004dcbc60fc97d0a990e01193', 'Loud Again on the Repeat, a Step Softer Each Time'),
('sector_featured_pairs', 283, 'note_en', 'cac7f57f4d8807c1fa4e7aece823e329ac82e44646d450308a6b83c7b67a5702', 'Schiff is 21 seconds shorter. Schiff plays loudest in the repeat, while Hewitt plays each repetition of the same half one step softer.'),
('sector_featured_pairs', 284, 'title_en', '38dc6b8072b1f854e2f5ce090cc48a47d8142e371894d1272c53d9e134bfe667', 'Bernstein Lowers Less, Davis Lowers Deep'),
('sector_featured_pairs', 284, 'note_en', 'ac2d8c491329e0118c7a36762faa456b6d552fc2ff88a399f79b3231396b934b', 'Davis is 22 seconds longer. When the women''s chorus enters, Bernstein lowers the level less, while Davis lowers it far deeper and sets it against the outcry.'),
('sector_featured_pairs', 294, 'title_en', '4350932f47542d43f749b1c982258f269d66fce1088b8c524c62300f185537b7', 'Sokolov Ends Loud, Hewitt Ends Soft'),
('sector_featured_pairs', 294, 'note_en', '580cad2f34bcfde363bd8f937c3847f605e68c86a6190bfc4cec22e7a644dbf0', 'The lengths are nearly the same, but Hewitt plays the first refrain once more. Sokolov carries the second half at nearly the maximum, while Hewitt plays loudest, then keeps the ending soft.'),
('sector_featured_pairs', 295, 'title_en', '11771d171b6730c9db06e1d0d4d230c9b4cb1af5f779ee795fbfe95b1b9b8970', 'Maisky Sinks Deep, Yo-Yo Ma Rises Evenly'),
('sector_featured_pairs', 295, 'note_en', '841035832df69345a448334b575270533c36acf31569001fcb9d3601cc7fd09b', 'Maisky is 11 seconds longer. Maisky sinks deeply once in the early part and once in the later part, while Yo-Yo Ma builds step by step without much reduction.'),
('sector_featured_pairs', 296, 'title_en', 'b3cc225d3191141f3f8e51130d7b57b15ed5bb13b0e6528816809be9297b40be', 'Even Schiff, Softly Building Hewitt'),
('sector_featured_pairs', 296, 'note_en', '25240030bc9a479f9c376551bc963e9ed8b9428868f33fa3a38a882dde5c4e65', 'Hewitt is 14 seconds longer. Schiff keeps an even level from the opening, while Hewitt opens very softly and builds step by step for over a minute.'),
('sector_featured_pairs', 297, 'title_en', 'e919821b5e80cfc79e8cc17daf9ba9705e83943d3255bb0b2dff0fa31096d603', 'Lim Takes a Long Breath, Perahia Goes Straight On'),
('sector_featured_pairs', 297, 'note_en', '5d0ef1739db14aea802e8a93ef043d78c5649a81c594ffcc4b8298052470e1ae', 'Lim is 34 seconds longer. Before the end, Lim goes very soft for nearly 10 seconds, while Perahia lowers the level briefly and goes straight on.'),
('sector_featured_pairs', 298, 'title_en', '40d2eb3ad32db6626f148e5fca9bf11f5ed55324c72544994f4c4056cb46bc53', 'Domingo Steps Up, Carreras Loud Early'),
('sector_featured_pairs', 298, 'note_en', 'f211d7a55b35c23c9a9c5e08869e196b25debf75cab1f3dcebbd106ca970f9a6', 'Carreras sings the first climax at nearly the final level. Domingo keeps the first climax much lower and raises the level a step with each climax.'),
('sector_featured_pairs', 299, 'title_en', '171d5030a88a8c0439d4d54e52a5b719909fefae71a84d51e47ed9dc54cc251b', 'Gardiner Loud on Two Lines, Harnoncourt Raises Each Line'),
('sector_featured_pairs', 299, 'note_en', 'db7d3affa092a6f4e8a68ff1d36db98d069cce397a35d6f8c56752c7ab910510', 'Harnoncourt raises the level each time the chorus enters. Gardiner is mostly soft and rises loudly only in the middle two lines, and runs about 10 seconds shorter.'),
('sector_featured_pairs', 300, 'title_en', '2ebf571f6ece79b05084f964fbd7309ee153db45727897701a265820073b845c', 'Chung Rises Early, Kremer Holds the Hush Long'),
('sector_featured_pairs', 300, 'note_en', '99288aaa8f15cf692187286571e9c8bbd2ca38bdb669e74d00786bd13f2c58f8', 'Chung is 33 seconds shorter. Chung ends the soft introduction at about 25 seconds and rises loudly, while Kremer keeps it soft for over 40 seconds before getting louder.'),
('sector_featured_pairs', 301, 'title_en', '99be63590378748e81ecd24d77f2b633db2d324da5ebf47f368d74aa0b5f45e6', 'Solti Sinks Deep, Rattle Rises Early'),
('sector_featured_pairs', 301, 'note_en', 'a45e2cedb1e1053098c158c2f091a62584bfca391e591600becc8f868efe908a', 'In the quiet passage in the middle, Solti sinks very deeply and Rattle less. Afterward Rattle reaches nearly the maximum right away, while Solti holds back for about a minute longer.'),
('sector_featured_pairs', 302, 'title_en', 'dc565c434778d18204e933d462f9f12fc942a508014509a44286bc4e4b1c43fb', 'Heinrich Schiff Loud for Long, Kanneh-Mason Deeply Soft'),
('sector_featured_pairs', 302, 'note_en', 'cc2a2baae4559ae36486dff2f193e99d0bf53986e49ea85a42ff66d2e91f1adb', 'Heinrich Schiff stays loud for over 18 seconds from the first chord, and the quiet spot in the middle is shallow. Kanneh-Mason''s quiet spot is much deeper.'),
('sector_featured_pairs', 308, 'title_en', '276f7a34432edf3f328526e00c09e19719a9a90772f92dc50e26a3de25437b66', 'Solti Opens Loud, Dudamel Sustains to the End'),
('sector_featured_pairs', 308, 'note_en', '27ce2e0e7a88aec0ef36edecf79ac3a8a6cf5878926d7b740b1c9f043cc11d1c', 'Solti opens loudly from the strings'' first notes and comes down deeply at the end. Dudamel keeps the opening small, sustains the loud passages longer, and closes loudly too.'),
('sector_featured_pairs', 309, 'title_en', 'ebd8aa328ce7d4acd93c30cff6429fa3e7e0353d957e715282036d40efb980c5', 'Rana Steps Back Often, Pollini Pushes Straight'),
('sector_featured_pairs', 309, 'note_en', '385a9d90fe011670181538e3427790c849c2e3632eccb6e79993d9423b3cc4b8', 'Rana is 24 seconds longer. Rana steps back deeply several times within the fast passage, while Pollini passes the same spots shallowly and pushes straight on near the maximum.'),
('sector_featured_pairs', 310, 'title_en', 'f9a3f18abce3aab71870948125f51a7e44790b11a3e83f9b13bd21bb2cda20cd', 'Solti Comes Down Evenly, Karajan Sustains Long'),
('sector_featured_pairs', 310, 'note_en', '1713b23bc54f818dab525ce212413bd1d530bbf52c3f5f73b0e72ed82968e99d', 'Karajan is 37 seconds longer. Solti comes down evenly about 15 seconds after the climax, while Karajan stays big for over 30 seconds and rises once more about 30 seconds before the end.'),
('sector_featured_pairs', 311, 'title_en', 'c6114e85f673fa22a9f53624b0445e96a36beea903ccdb32908a6a5f7d9f8e0a', 'Muti Sinks Deep, Dutoit Pushes to the End'),
('sector_featured_pairs', 311, 'note_en', 'ca7d9e9c4bad27c33bece94fb8471f884a61ce61882451aaa7333c11eb786f23', 'Muti lowers the quiet passage in the middle deeper, and Dutoit less. In the last minute, Dutoit pushes at nearly the maximum while Muti stays a step below.'),
('sector_featured_pairs', 312, 'title_en', '2d42dee2c4fdf08437929e8fcff30784ff8239945c0597b0c7598158e4a386d5', 'Shallow Leonskaya, Deep-Sinking Melnikov'),
('sector_featured_pairs', 312, 'note_en', 'c22e3a2da7eb56d2e4230cd04d6ebb14b397d956e6a3f2be533bc0ffe1e204e8', 'In the D minor passage, Melnikov sinks very deeply while Leonskaya passes through far more shallowly. Leonskaya also carries the closing passage on louder.'),
('sector_featured_pairs', 318, 'title_en', 'c4625eb4500216d256d74730be5bcc6d257c5c22da224cde799bf2067d259418', 'Zimerman Holds Back Till the End, Pollini Bursts Early'),
('sector_featured_pairs', 318, 'note_en', '917ce46d9c9ab24ef5abfceaf68da9253e6ff4897534a6184c4442c3f79ab3aa', 'Pollini already plays loudest in the loud passage of the early theme and pushes the closing passage just as far. Zimerman raises each loud passage a step and puts the loudest sound at the end.'),
('sector_featured_pairs', 319, 'title_en', '781a9e4e99bb02771cb205a0a38c7319f2a581a68956dc23aaa63c493662a310', 'Relaxed Son, Yundi Li Gathers at the End'),
('sector_featured_pairs', 319, 'note_en', '065c1cf19424a83341b4feb1fa7e895da4b848bd393608277f3e501816436676', 'Son is 26 seconds longer and raises the level from the early big passage to nearly the final level. Yundi Li keeps the early part low and raises it all at once in the last big passage.'),
('sector_featured_pairs', 320, 'title_en', '2ef92f8bc41d734682b1b1796d891e26ea3e5a05426658287eb8e45ccc2e3a52', 'Argerich Builds Early, Cho Holds Back to the End'),
('sector_featured_pairs', 320, 'note_en', 'c06e7a71f16077123668ab210f8adba9448822f2127ab24c2e6043f573710416', 'Argerich is 18 seconds shorter and already raises the level close to the maximum in the middle of the quiet march. Cho walks low for over a minute and raises it only at the loud chords.'),
('sector_featured_pairs', 321, 'title_en', '1f26e7b6f06dc3a4795789de29005a1f1c15c52b77834ea5ac1cabd2f4d36601', 'Shelley Sinks Deep, Hough Stays Even'),
('sector_featured_pairs', 321, 'note_en', '543abc4f9f702a79dfaa4382dcdb3766cc74c36b723e97dbf8c315d562073776', 'Shelley is 39 seconds shorter and sinks the quiet passage after the climax very deeply. Hough doesn''t sink deeply even in quiet passages and carries on at an even level.'),
('sector_featured_pairs', 322, 'title_en', '972a579873289c3ec48db8d0fb4be5093f44009c88c7ecf4812ea4359ae4bc0c', 'Ashkenazy Strong at the Start, Pollini Strong at the Back'),
('sector_featured_pairs', 322, 'note_en', 'cfef277724335c48224dac462b029f1d8971350f32ec9fdb4599c1c529893cc9', 'Ashkenazy gets nearly to the maximum 4 seconds in. Pollini pushes at an even level for over a minute and rises to nearly the maximum only in the later part.'),
('sector_featured_pairs', 327, 'title_en', 'f2f1990b9ecb5117bbe317ab52c2fbf3533f5c1fe36ddef14ed1dd7a35f3f2d4', 'Pires Peaks Late, Lisiecki Peaks at the Opening'),
('sector_featured_pairs', 327, 'note_en', 'd4cd52ad50ce01c4d08e711ff8b483a7bb576ba15db1db3ebf3d5e02f8cd7258', 'Lisiecki is already loudest at the opening chord, where the winds break in forcefully. Pires holds back a step there and gets nearly to the maximum only as 4 minutes approach.'),
('sector_featured_pairs', 328, 'title_en', '4f48ab4cfa79b991113edb510ed5474ee85da3ee54b2b89500cbd8d749763011', 'Marriner Rises Sparingly, Zinman Builds from the Front'),
('sector_featured_pairs', 328, 'note_en', '683264bf3c006f3541344d18948775c07c148967a6e1ce2c724020523e7fb6c9', 'Zinman is 1:10 longer. Marriner keeps the early ascent low and raises it all at once from a minute before the climax, while Zinman builds loudly from the start.'),
('sector_featured_pairs', 329, 'title_en', '9f9b32a7478a7d1ece50009437a9a844f64c3240bae63ede514a6caab0c3cceb', 'Marriner Lowers Early, Bernstein Lowers Late and Deep'),
('sector_featured_pairs', 329, 'note_en', '8b8df024d98ea3dbcbcd5c296d9eac24d598cffcaa46bb5aa3839e9cfb9daefd', 'Marriner already lowers to a soft level when the theme is repeated. Bernstein pushes loudly through that theme, then sinks much deeper at the oboe passage.'),
('sector_featured_pairs', 330, 'title_en', '2edc8916721f06a4d70e302957974572b93992a5f329f83bed2d1c6684b8d5cc', 'Harnoncourt Often Loud, Böhm Only Briefly'),
('sector_featured_pairs', 330, 'note_en', 'dc4c70e59d0afe93eacef91326321f915391a357921e1ed61f7b30dc13efa8d4', 'Harnoncourt is 53 seconds shorter. Harnoncourt often rises close to the maximum, while Böhm presses the middle down low and keeps the loud places brief.'),
('sector_featured_pairs', 336, 'title_en', '33751544268bbca9d8936bc2dbb65390c871244d6df490af6a9cf303c5472aad', 'Bernstein Holds Back, Nézet-Séguin Raises Early'),
('sector_featured_pairs', 336, 'note_en', 'd175d05e4d29dc693ffb7f0d97269f49f0e1c7f3247b739582b081b207a2c094', 'Bernstein doesn''t raise the level until before the last big passage, then holds that passage near the maximum for almost 30 seconds. Nézet-Séguin raises it loudly even in the middle and climbs the ending in two stages.'),
('sector_featured_pairs', 337, 'title_en', '70d5b1a99c6572a6c293853f81efa891f31aed760cb45972bf74bd924396465a', 'Gardiner Filling, Leonhardt Growing'),
('sector_featured_pairs', 337, 'note_en', '85a8fcc5d7b15ec38fb98707d7bb1046cb4b6c073455276c3f39d3222bdb59f5', 'Gardiner enters loudly from the start and fills the sound at nearly the same level to the end. Leonhardt opens softly, builds little by little up to the exact middle, then sets it down again.'),
('sector_featured_pairs', 338, 'title_en', '141f6c5d5b8a201cc7a3f040feb8e92bb06b2b454a5c4dc22dafec2192d74eb0', 'Slow Fischer-Dieskau, Goerne Ending Softly'),
('sector_featured_pairs', 338, 'note_en', '30e4b7bf5d57d21597e64a3ae7aa1ab102afe92a41be472f59d363ac28279b9c', 'Goerne is 1:22 shorter. Fischer-Dieskau keeps a similar level to the end, while Goerne lowers the last minute a step and ends softly.'),
('sector_featured_pairs', 339, 'title_en', 'e6eb09c789a95317516145b53e5a66fac63b99aa10a4322c3e4bb8941d06081c', 'Ashkenazy Rises Early, Lim Presses Deep'),
('sector_featured_pairs', 339, 'note_en', 'a77e42b7d827d9062e2df71033a58e4bdba9721db1f6b7ced138a09856d4bb91', 'Lim is 10 seconds shorter. Ashkenazy plays loudest in the early part, while Lim sinks the middle deeply and plays loudest after it.'),
('sector_featured_pairs', 340, 'title_en', '3c2e90a01ff743bd694e1409ef6a4e831377190fd322c870ed2b436c7cf00c5d', 'Even Tilling, Slow and Soft Hendricks'),
('sector_featured_pairs', 340, 'note_en', '87abd9de80ba1ef981150878b9cd137cfbfbf106745d6ce2c462cbd1c848bc7a', 'Hendricks is 1:06 longer. Tilling has fewer and shallower quiet passages; Hendricks drops more often and deeper.'),
('sector_featured_pairs', 346, 'title_en', '528ecc1701ec531b06b9a03780d5c96db6db024fd7070fafd1b85a1b29884198', 'Slow, Deep Mutter, Even Perlman'),
('sector_featured_pairs', 346, 'note_en', 'a6fec6e94b1b4bdf68682fa991203a852c7e0e4d2cc7eb9927e535f7195a40f0', 'Mutter is 34 seconds longer. Mutter sinks deeply after the climax, while Perlman reaches the maximum at the early high point and keeps the quiet passages shallow.'),
('sector_featured_pairs', 347, 'title_en', '958d71f25b42355a7227ee1fe7837b925c3d8360e618174a3e4121cb8d2f8c55', 'Bernstein in Two Steps, Dutoit in One'),
('sector_featured_pairs', 347, 'note_en', '91ef069ccc9abaf382acef085e7946e93bfa1068ef2339cc75d74bab51b03dde', 'Dutoit keeps a soft level until 30 seconds before the end, then rises loudly in one go. Bernstein rises in two steps from before that.'),
('sector_featured_pairs', 348, 'title_en', '39eb4d0261cb820d4a85f973e12f937e72e35835fde25fb8933ecb4c4b2aed90', 'Long Bartoli, Deep-Lowering Berganza'),
('sector_featured_pairs', 348, 'note_en', '49ac7133cf7a6b9325c2886cc479f7f11323f3c55e9ad92d64189cd7f8328a2a', 'Bartoli is 23 seconds longer. Bartoli rises to near the maximum several times near the end, while Berganza sinks deeply right after the loudest singing.'),
('sector_featured_pairs', 349, 'title_en', '0f3ef5a60ad8cc63debac2cc879b8230aded2f92784a0b90c01fdcc9593941f2', 'Ashkenazy Builds Slowly, Lupu Rises Early'),
('sector_featured_pairs', 349, 'note_en', '0b7d6d1862084faafe3977d5d14a85e43ad3738139a374f1f9beeea691af2b92', 'Ashkenazy is 10 seconds longer. Ashkenazy reaches nearly the maximum only at the end, while Lupu is already near the maximum about two-thirds of the way through.'),
('sector_featured_pairs', 350, 'title_en', '48e7da9a9c276c4223ae059cee628aa97fc88fa69cb368e02a178e0ab20be50b', 'Lang Lang Grows the Ending, Argerich Ends Softly'),
('sector_featured_pairs', 350, 'note_en', 'c99067a80c24124eae5675b3fcabf7a3dccf3d3ea988f496876e281af146fe10', 'Lang Lang carries the theme at an even level, then raises it loudly again in the last phrase. Argerich rises loudly in the middle and ends the last phrase softly.'),
('sector_featured_pairs', 355, 'title_en', 'f5ef19212b14f7b7c054978b4d66484589e0de34811db63919d03c886c0cea41', 'Perlman Big Three Times, Janssen Loudest at the Last Chord'),
('sector_featured_pairs', 355, 'note_en', '93da329b32b9be3ced3dca0847dcb14f82f152de5c7c1dca99202ec9a7192594', 'Perlman plays the two tuttis and the last chord at nearly the same level. Janssen keeps the tuttis lower, and the loudest sound comes on the last chord.'),
('sector_featured_pairs', 356, 'title_en', 'eaa916008bc4d10867e94d19cc43c2c3c3e8e9863c0d087141b19d44b8181012', 'Boulez Loud Early, Bernstein Loud Only at the End'),
('sector_featured_pairs', 356, 'note_en', '0b7970ce9ac8e7db4451fb2f548ca9fee602146541d42e99f7789dacf4e4dd18', 'Boulez rises to the loudest level less than a minute after the alto enters. Bernstein reaches that level only 10 seconds before the end.'),
('sector_featured_pairs', 357, 'title_en', '3a0366e336648cc8c9fc3f316a048f167d5adf465ca13421d7c006db23f2c704', 'Konwitschny at the First Rush, Haitink at the Second'),
('sector_featured_pairs', 357, 'note_en', '9221470929562ba49f4179745645b946749372a471db8d0a8dcba3a4bd67924d', 'Konwitschny already rises to the loudest level at the first onrush. Haitink holds back the first onrush for a long time, passes through a deeply soft middle, and bursts out at the second.'),
('sector_featured_pairs', 358, 'title_en', 'ab7bbc67998ce3f718960aad8c452c3700fb25440d5ac619b1f660ce7a16ffe1', 'Abbado on the First Chord, Karajan Long and Loud'),
('sector_featured_pairs', 358, 'note_en', 'b443a1fc209819b4b81edb59706f98180190910df015a40d55e94beb271dc427', 'Karajan is 1:21 longer. Abbado rings out the first chord loudest and presses the middle low, while Karajan rises to nearly the maximum several times even in the middle dialogue.'),
('sector_featured_pairs', 379, 'title_en', 'a487a574504642ee72115620b057b01b339feb06fce7a7de66439c26235601bc', 'Karajan Opens Softly, Bernstein Drags Slowly'),
('sector_featured_pairs', 379, 'note_en', '183a04ea21572dd2fe7fad1b9035e44f55e9ef9e3c42aafa7da909d491ce6357', 'Bernstein is 21 seconds longer, and most of the difference arises in the first 1:30. Karajan''s opening is very soft, while Bernstein swells conspicuously once within 14 seconds of the start.'),
('sector_featured_pairs', 380, 'title_en', 'ae505dedf9c21f31653d98e0f4612cabb24fe41724fd6b0fb20992560ffcab6f', 'Solti Big from the Start, Abbado Builds'),
('sector_featured_pairs', 380, 'note_en', 'b60ced627574e3dc79745afa093472195b0e060896ea63cf1d72332ba9d372d6', 'Solti plays near the maximum from the opening and is loudest at the first ff. Abbado keeps the first f a step lower and builds, reaching the loudest level at the second peak.'),
('sector_featured_pairs', 381, 'title_en', '11920d3e1c797df9a95abe1e74022a30b85a38b6d8e4bb83734cb42e076ae3ff', 'Bernstein''s Loud Trumpet, Levine''s Lower One'),
('sector_featured_pairs', 381, 'note_en', '8f54f4fc238c77e2b7d3fdb343961c78b755848386e6126400ecf23b927ac65b', 'Bernstein''s trumpet signal is nearly as loud as the loud passage of the prayer melody, while Levine''s is a step lower. Levine runs 12 seconds longer, and the loudest sound comes in the latter part of the melody.'),
('sector_featured_pairs', 382, 'title_en', '5714e86b2fb4be7f2c1a5a16c9afe420da6bb1dad5ca78881af5a5fdbe37d51b', 'Thielemann Strikes Briefly, Chailly Sustains'),
('sector_featured_pairs', 382, 'note_en', '06b701e19b9c790df791807c5b83588945a333dd6f208aa707da9f0f6a1d973b', 'Chailly is 21 seconds longer. At the peak where the horns surge, Thielemann hits the maximum briefly and comes down, while Chailly holds a loud level for nearly 15 seconds and reaches the maximum twice.'),
('sector_featured_pairs', 383, 'title_en', 'b635966784a269bbf7f9f846ce6ec10d4c58cf119be3ec0531b226155f38f3a2', 'Herman Closes Briefly, Thunemann Closes Long'),
('sector_featured_pairs', 383, 'note_en', '334518d49592b756c716cb4032f8a4bd9693e1a7b69a243518a05d9f8d722575', 'The two reach the last tutti at almost the same time. Herman finishes that tutti in 12 seconds, while Thunemann carries it on for over 30 seconds.'),
('sector_featured_pairs', 384, 'title_en', '13ca13c56158bc9c3d90255b497eda2078b6d66eda5a6191545d2b131a485d49', 'Short Introduction with Mutter, Long with Perlman'),
('sector_featured_pairs', 384, 'note_en', '46aa2224faa062fd44e0733bedf55ef7b178d4298259bc8a5983b26c9d60a711', 'Perlman spends 27 seconds longer on the introduction. Perlman''s biggest peak in the introduction is loud, close to the Presto, while Mutter''s is a step below it.'),
('sector_featured_pairs', 385, 'title_en', '1569ce4969beccf99a9fc4857eaa48b94b991bbe1ab577a7ebdb21b05fda41b6', 'Narrow Rise from Zimerman, Wide Rise from Rubinstein'),
('sector_featured_pairs', 385, 'note_en', 'e443916349bf4eb5244786a7aafb2becc7f1c2f561d39616fd5d9fca9d5a9603', 'In the Rubinstein version, the orchestral crescendo starts far lower and rises widely to ff. In the Zimerman version, the first signal already rings loudly, so the range of the rise is narrow.'),
('sector_featured_pairs', 386, 'title_en', 'fbd2a0c16f3bf6c5a797592395b5dbf3a73d42fcfdd301ff30ebe2834970ca93', 'Perahia Deep in Quiet Spots, Even Eschenbach'),
('sector_featured_pairs', 386, 'note_en', '7c18ae2c41607b0f9972076b81b423c54f8cad778f38ed5e857567654cc2807e', 'Perahia''s quiet passages are far deeper than Eschenbach''s. Eschenbach is 27 seconds shorter and reaches nearly the maximum in every loud passage.'),
('sector_featured_pairs', 387, 'title_en', 'c5e0d9cc9d4bf6bfd8fa4f1ac0cc8c02b488415b743560e33defd0a49e46fb5c', 'Kissin Loud from the Start, Firkušný Holds Back'),
('sector_featured_pairs', 387, 'note_en', '342abe54997494dd717b269afb3a9ca0187cdeeb9df8372451856de66dbe9880', 'Kissin rings out at nearly the maximum from the first unison and returns to that level several times. Firkušný reaches nearly the maximum for the first time only a few seconds before the end.'),
('sector_featured_pairs', 388, 'title_en', '90eae7458f78a67741f9d442a99a64f01afb1dad3bf8147c35e75a139b29f42d', 'Deep-Sinking Rozhdestvensky, Even Tjeknavorian'),
('sector_featured_pairs', 388, 'note_en', '4ed0643f055a28109e0d154b7076a9f25f7672d78ce9809ce60f4862f20f593d', 'Tjeknavorian is 44 seconds shorter. Rozhdestvensky sinks deeply between the loud passages and raises the level again, while Tjeknavorian keeps the big level even.'),
('sector_featured_pairs', 389, 'title_en', '78781d146919b45d4d49b926bbaea1561e1d93747453c5f55b21f8ba6877f980', 'Shallow Gielen, Deep Nott'),
('sector_featured_pairs', 389, 'note_en', '97f75bbb9be0e0ba562ff88c88734001a549a9fb16f9e5d46c9b014866f4aad6', 'In the quiet passage in the middle, Nott goes very deep and Gielen less. Gielen reaches nearly the maximum only at the last climax.'),
('sector_featured_pairs', 390, 'title_en', '7c5db9b7ea0e82cb7c324e00ed8e4c25097cf06c23840cb595dae73e35aeaf52', 'Mead Loud Early, Lesne Soft at the Opening'),
('sector_featured_pairs', 390, 'note_en', '767978f6e5f410a97f10f533e0c8dea224d2d3a1f64558b9e33ac34e715d5599', 'Mead rises to nearly the maximum in 45 seconds and reaches that level several times. Lesne''s opening is very soft, and nearly the maximum appears only twice.'),
('sector_featured_pairs', 391, 'title_en', 'eaad5d29a8294e9c4e30a7b616c0920d5f77053ef345efb19eebe5a86bc3869e', 'Kermes Holds Back, Crowe Raises Often'),
('sector_featured_pairs', 391, 'note_en', 'c01ff988e454709a07917c25830ca69ecc127cc5f3eedebde112180ef209c396', 'The two performances differ by 1 second in length. Kermes reaches nearly the maximum only once and goes deep in the quiet places, while Crowe reaches nearly the maximum four times in the second half.'),
('sector_featured_pairs', 392, 'title_en', '80972cd88dab44f54667c30e23556a523c681ee40ec0e926fc6a128e9094671f', 'Fast Harnoncourt, Less Soft Bernstein'),
('sector_featured_pairs', 392, 'note_en', 'f8ba5727b2b41b49b51baf56c692b3bc4af06db908b503fb0ed20910f8b1fb80', 'Bernstein is 5 seconds longer. After the two chords, Harnoncourt plays the cello theme very softly and Bernstein less softly.'),
('sector_featured_pairs', 393, 'title_en', '49b4fb85c3704e20660f309eba0045326a975ac4d561fca5447a369a34eeb239', 'Shallow Latvian Radio Choir, Deep Weinberg'),
('sector_featured_pairs', 393, 'note_en', '05ca80a2b54a4601b79a6b5c78fb46117b50c2c4b2ab867bc216a0b25ce6519b', 'The Latvian Radio Choir is less soft even in the later quiet passage and reaches nearly the maximum from the first section. Weinberg goes deep in the later quiet passage, and the first section is a step lower.'),
('sector_featured_pairs', 394, 'title_en', '40dacc6c0cb05ab804f774effe4708804549d7865caa3a9a6112288202ec6936', 'Capuçon Deep in the Middle, Batiashvili Shallow'),
('sector_featured_pairs', 394, 'note_en', 'af285868184aee0fd125a1f6cdf0fbd77ffc75911ed37b792a8198835548107d', 'In the middle quiet passage, Capuçon stays very soft for over 40 seconds. Batiashvili''s quiet middle is short and shallow, so the difference in level is small.'),
('sector_featured_pairs', 395, 'title_en', 'e1c88f3da50b1780d86493fc3eb479bbca24f82193e71cc9496a7bba22cf221a', 'Bernstein Bursts at Once, Dutoit Builds at the End'),
('sector_featured_pairs', 395, 'note_en', 'd5748e687caa3eff20ff78a3d804fe146c23e7b71c02f23aa297794be2a875cc', 'Bernstein reaches nearly the maximum as soon as the racing passage starts and sustains it for nearly 20 seconds. Dutoit drags the same passage a step lower and raises it to the loudest only in the last few seconds.'),
('sector_featured_pairs', 396, 'title_en', 'df4be0b8ccbe855e76066da29e8fcd84e0920b30858850a0a0cfe45ada032894', 'Galante Sinks Long, Fleming Passes Quickly'),
('sector_featured_pairs', 396, 'note_en', 'f01b6098cb287a270bf9416fc911790c2a33b233bb3f1cd53bddfdcdf3c79cdf', 'After the early big passage, Galante draws out the quiet passage deeply for nearly 30 seconds. Fleming passes through the quiet passage after the big one in about 20 seconds, less softly, and the aria is over 20 seconds shorter.'),
('sector_featured_pairs', 397, 'title_en', 'd04ddde458e6e0aba92129b738f0549e999ae9d5beadcee05711c97990d13297', 'Paik Max at Once, Pires Held Back to the End'),
('sector_featured_pairs', 397, 'note_en', '156d83e3c6179657fcebad49f6cc4a042db60bf5c0a0c38b7c1e757cd8a162df', 'Paik already plays loudest at the first peak and releases the diminished seventh chord early. Pires keeps the first two peaks a step lower, plays loudest on that chord, and lets it ring for a long time.'),
('sector_featured_pairs', 398, 'title_en', '766936f030919b9867c5bde14251991007a953eb9f1f1795e7ce95140c08e956', 'Böhm Rises Early, Haitink Arrives Only at the End'),
('sector_featured_pairs', 398, 'note_en', 'fa50e1542d23f967c5fcc2980d30f7e11d68d8d312412da825c8665a36a583ce', 'Böhm is 19 seconds shorter than Haitink and already rises near the maximum at the second motif. Haitink leaves long gaps between motifs and reaches the maximum only near the final chord.');

UPDATE composers t
JOIN tmp_english_text x
  ON x.tbl = 'composers' AND x.field = 'bio_en' AND x.id = t.id
SET t.bio_en = x.en
WHERE SHA2(t.bio, 256) = x.ko_hash;
UPDATE composers t
JOIN tmp_english_text x
  ON x.tbl = 'composers' AND x.field = 'style_en' AND x.id = t.id
SET t.style_en = x.en
WHERE SHA2(t.style, 256) = x.ko_hash;
UPDATE composers t
JOIN tmp_english_text x
  ON x.tbl = 'composers' AND x.field = 'influence_en' AND x.id = t.id
SET t.influence_en = x.en
WHERE SHA2(t.influence, 256) = x.ko_hash;
UPDATE artists t
JOIN tmp_english_text x
  ON x.tbl = 'artists' AND x.field = 'bio_en' AND x.id = t.id
SET t.bio_en = x.en
WHERE SHA2(t.bio, 256) = x.ko_hash;
UPDATE artists t
JOIN tmp_english_text x
  ON x.tbl = 'artists' AND x.field = 'style_en' AND x.id = t.id
SET t.style_en = x.en
WHERE SHA2(t.style, 256) = x.ko_hash;
UPDATE artist_awards t
JOIN tmp_english_text x
  ON x.tbl = 'artist_awards' AND x.field = 'award_name_en' AND x.id = t.id
SET t.award_name_en = x.en
WHERE SHA2(t.award_name, 256) = x.ko_hash;
UPDATE pieces t
JOIN tmp_english_text x
  ON x.tbl = 'pieces' AND x.field = 'description_en' AND x.id = t.id
SET t.description_en = x.en
WHERE SHA2(t.description, 256) = x.ko_hash;
UPDATE performance_sectors t
JOIN tmp_english_text x
  ON x.tbl = 'performance_sectors' AND x.field = 'description_en' AND x.id = t.id
SET t.description_en = x.en
WHERE SHA2(t.description, 256) = x.ko_hash;
UPDATE performance_sectors t
JOIN tmp_english_text x
  ON x.tbl = 'performance_sectors' AND x.field = 'name_en' AND x.id = t.id
SET t.name_en = x.en
WHERE SHA2(COALESCE(t.name_ko, t.sector_name), 256) = x.ko_hash AND (t.name_en IS NULL OR t.name_en = '');
UPDATE performance_listening_notes t
JOIN tmp_english_text x
  ON x.tbl = 'performance_listening_notes' AND x.field = 'headline_en' AND x.id = t.performance_id
SET t.headline_en = x.en
WHERE SHA2(t.headline, 256) = x.ko_hash;
UPDATE performance_listening_notes t
JOIN tmp_english_text x
  ON x.tbl = 'performance_listening_notes' AND x.field = 'note_en' AND x.id = t.performance_id
SET t.note_en = x.en
WHERE SHA2(t.note, 256) = x.ko_hash;
UPDATE performance_listening_notes t
JOIN tmp_english_text x
  ON x.tbl = 'performance_listening_notes' AND x.field = 'facts_en' AND x.id = t.performance_id
SET t.facts_en = CAST(x.en AS JSON)
WHERE SHA2(t.note, 256) = x.ko_hash;
UPDATE sector_featured_pairs t
JOIN tmp_english_text x
  ON x.tbl = 'sector_featured_pairs' AND x.field = 'title_en' AND x.id = t.sector_id
SET t.title_en = x.en
WHERE SHA2(t.title, 256) = x.ko_hash;
UPDATE sector_featured_pairs t
JOIN tmp_english_text x
  ON x.tbl = 'sector_featured_pairs' AND x.field = 'note_en' AND x.id = t.sector_id
SET t.note_en = x.en
WHERE SHA2(t.note, 256) = x.ko_hash;
UPDATE screen_titles t
JOIN tmp_english_text x
  ON x.tbl = 'screen_titles' AND x.field = 'title_en' AND x.id = t.id
SET t.title_en = x.en
WHERE SHA2(t.title_ko, 256) = x.ko_hash;
UPDATE screen_music_cues t
JOIN tmp_english_text x
  ON x.tbl = 'screen_music_cues' AND x.field = 'part_label_en' AND x.id = t.id
SET t.part_label_en = x.en
WHERE SHA2(t.part_label, 256) = x.ko_hash;
UPDATE screen_music_cues t
JOIN tmp_english_text x
  ON x.tbl = 'screen_music_cues' AND x.field = 'scene_note_en' AND x.id = t.id
SET t.scene_note_en = x.en
WHERE SHA2(t.scene_note, 256) = x.ko_hash;

DROP TEMPORARY TABLE tmp_english_text;
